const POEM_STORY = {

  // id=53 中唐 孟郊 〈遊子吟〉rating=7
  // 詩眼：遲到的理解——母愛藏在你當時看不懂的動作裡
  // 隱藏連接：46 歲及第的高光時刻母親不在場
  53: {
    title: "遊子吟",
    author: "孟郊",
    summary: "所有人都以為它是離別詩——其實是一個五十歲的兒子終於把母親接來身邊那一刻，寫下的一封遲到三十年的謝謝。",
    story: `跟你說我朋友東野的一件小事。他這輩子做過最重要的一件事，是五十歲那年把他母親從湖州武康接到溧陽一起住。

孟東野這個人，你可能記得他那句「春風得意馬蹄疾，一日看盡長安花」。那是他四十六歲中進士寫的。整整一個長安的春天，他一天就看完了。可是你發現一件事嗎——那個他等了二十多年的高光時刻，他母親不在場。她還在武康家裡等消息。他人生最快樂的一天，只有他一個人享受。

他這輩子考進士考得很慘。二十幾歲開始跑長安，一直考到四十一歲、四十二歲，還是落第。同輩的人早就在朝廷做官了，他還在旅店裡數銅板。每一次從武康出發，他母親都會在油燈下替他縫衣——不是縫新的，是把舊衣拆了再重縫，因為家裡買不起新布料。

孟母縫衣有個習慣：針腳收得特別特別密。密到旁人都覺得不必要。她也從不解釋。那時候的東野只覺得母親太瑣碎——衣服哪有那麼容易破，何必縫得跟盔甲一樣。他從沒往深處想。

四十六歲中進士之後，他還等了四年才被派到溧陽當一個小小的縣尉。位低錢少，但總算能養家了。他做的第一件事就是回武康。他要把已經很老的母親接到溧陽一起住。

那年他五十歲。母親跟著他離開武康的路上，一路顛簸。到溧陽住下第一個月的某天晚上，東野看見母親坐在油燈下——習慣地拿起針線在縫他的舊袍子。那雙手已經比他記憶中枯瘦了好多。

他站在門口看她。突然什麼都懂了。

他懂了：那些他當年嫌太密、覺得不必要的針腳，是母親一輩子沒說出口的「等你回家」。她心裡藏著一個沒說出口的計算——這一去長安幾千里，一年？兩年？誰知道呢？衣服縫得越牢，她心裡才有一個模糊的把握，這件衣會撐到你回來的那天。

他懂了：從二十歲跑到五十歲，他每一次穿在身上的衣，都是母親的手替他罩著。他懂了：他終於可以報答的這一天，可是母親已經老到，連走遠一點的路都困難。

他退到書桌前，提起筆，寫下六句話：

慈母手中線，遊子身上衣。臨行密密縫，意恐遲遲歸。誰言寸草心，報得三春暉。

他在詩題底下加了四個字：迎母溧上作。

這首詩後來變成了所有中國小學生都會背的〈遊子吟〉。可是幾乎沒人記得那四個字。人們以為它是離別詩。人們以為它寫在某個要出門的夜晚。

其實不是。它寫在一個五十歲的兒子終於把母親接來身邊、終於能好好看她一眼那一刻。那是一封遲到三十年的謝謝。

母親還在燈下縫衣。他沒去打擾她。他只是看著她的手。`
  },

  // id=257 盛唐 李白 〈靜夜思〉rating=7
  // 詩眼：25 歲離家、剩下 36 年都沒回去
  // 隱藏連接：他一輩子漂泊軌跡的起點就在揚州這個秋夜
  257: {
    title: "靜夜思",
    author: "李白",
    summary: "這首所有華人小孩都會背的四句詩，是李白二十六歲寫的——他不知道自己這輩子還會再走三十五年，再也沒回過家。",
    story: `跟你說我朋友太白最早期的一首詩。這首後來被全世界華人小孩都會背的〈靜夜思〉，是他二十六歲那年寫的。他當時剛出四川不到一年。他不知道自己這輩子還會再走三十五年，走到六十一歲客死在安徽當塗，離家鄉幾千里，再也沒回去過。

那年他從四川江油出來，意氣風發。他自己說是「仗劍去國，辭親遠遊」——帶著劍離開故國，告別親人，一個人出去闖。他跟你我一樣，以為出去闖幾年就會回家。

結果二十六歲那個秋天，他生了場小病，客居揚州一帶的旅店裡。他不是什麼名人，還沒進宮、還沒被玄宗接見、還沒紅。他只是一個口袋沒幾個錢、發著低燒、一個人躺在床上的年輕人。

那晚他半夜被月光晃醒。旅店的木床、薄薄的被子、床前一片白亮。他迷迷糊糊還以為是地上結了霜。

抬頭一看，月亮掛在窗外。低下頭，他發現自己躺在一張陌生的床上。

——他想家了。

他不知道該怎麼辦。異鄉的旅店裡沒人可以說話。他想寫封信，可是他家裡的地址一時想不起來要怎麼寄——四川太遠了，他自己走了幾個月才到揚州。他就這樣躺在月光裡，眼睛開開的，想他母親的樣子、想他父親的樣子、想江油老家院子裡的那棵桃樹。

然後他坐起來，摸黑找到紙筆，寫下二十個字：床前明月光，疑是地上霜。舉頭望明月，低頭思故鄉。

沒有典故、沒有華麗的比喻、沒有那個後來大家熟悉的太白式的「白髮三千丈」。就是一個發燒的年輕人，在一個異鄉的月夜，寫給自己看的四句話。

他寫完把紙折起來塞到行李裡，翻身繼續睡。他此刻不知道自己這輩子還會寫上千首詩。他不知道自己會進長安當翰林、被玄宗賞識、被楊貴妃研墨。他不知道自己會安史之亂時因為跟錯永王被判流放夜郎，走到白帝城遇到大赦。他不知道他六十一歲會在當塗的一位遠房叔叔家病逝。

他此刻只是想回家，但是他這輩子再也沒回去過。

四川、江油、青蓮鄉、他父親、他母親、院子裡那棵桃樹——他二十五歲離家的時候，看見的是他這輩子最後一眼的家鄉。他之後所有的漂泊、狂歡、被流放、被讚頌、寫詩、喝酒、醉倒在江邊——都建立在「回不了家」這件事上。

〈靜夜思〉不是四句思鄉詩。它是他這輩子的預告片。他二十六歲那晚在揚州旅店裡寫下的鄉愁，變成了他之後三十五年再也沒解開的結。

所有出門在外的人讀這四句，都會被戳中——因為我們每個人心裡都住著一個二十六歲的太白：那個以為自己出去闖闖就會回家、結果一走就是一輩子的人。`
  },

  // id=266 盛唐 王維 〈相思〉rating=7
  // 詩眼：這不是情詩，是寫給男性老友的訣別詩
  // 隱藏連接：李龜年是盛唐宮廷第一樂師，杜甫也寫過他
  266: {
    title: "相思",
    author: "王維",
    summary: "所有人都以為〈相思〉是情詩——其實它原本的題目叫〈江上贈李龜年〉，是王維寫給盛唐第一樂師的訣別。",
    story: `跟你說我朋友摩詰一段很少人知道的往事。這首所有人都以為是情詩的〈相思〉，它原本的題目叫〈江上贈李龜年〉。是寫給一個男人的。

李龜年是誰？盛唐宮廷第一男歌手。玄宗最寵他，他跟兄弟三個組成當年最紅的宮廷樂團，李龜年是主唱兼首席琵琶。他當年在長安、洛陽紅到什麼程度？——王公貴族排隊請他到家裡演出，一場出場費夠一般人吃一年。

摩詰跟他熟。摩詰自己精通音律，二十一歲進士及第，因為擅琵琶被玄宗安排在「太樂丞」的位置上，跟宮廷樂團往來密切。李龜年唱的很多曲子，用的就是摩詰寫的詞。可以說盛唐那個「詩配樂」的黃金組合，就是這兩位——一個寫詞，一個唱。

然後，安史之亂爆發了。那場叛亂把整個盛唐炸成兩半。長安失守，玄宗逃蜀。摩詰沒跑掉，被安祿山抓住強迫任偽職，戰後差點以「附逆」被殺，靠著弟弟王縉替他求情才勉強撿回一條命。而李龜年呢？流落江南，靠賣藝為生。當年宮廷第一男高音，如今在江南街頭賣唱換飯吃。

戰後某一天，摩詰聽說李龜年還活著，在江南漂泊。他寫了一首詩，寄過去。

紅豆生南國，春來發幾枝。願君多採擷，此物最相思。

沒有一個字提到過去。沒有一句抱怨盛世的崩塌。沒有嘆息宮廷的繁華已經散盡。他就寫「你那邊的紅豆多摘一些吧」——因為他知道，再多說一句，兩個老朋友都會哭出來。

紅豆是南方的植物，在江南長。摩詰在北方寫這首詩的時候，眼前並沒有紅豆。他寫的是李龜年那邊會看到的東西。他把畫面設定在對方的位置——你走出你的破屋子，看見春天開的紅豆，就摘一些吧。因為那個東西啊，是我對你的想念。

有意思的是，杜甫後來也寫過李龜年——「岐王宅裡尋常見，崔九堂前幾度聞。正是江南好風景，落花時節又逢君」。同一個李龜年，兩位大詩人分別寫他。李龜年這個人，就這樣被兩首詩固定在盛唐崩塌的那一刻。

盛唐結束了。那個李龜年在勤政樓唱、摩詰在旁邊聽、玄宗跟貴妃在牡丹亭下笑的時代結束了。但一個「請你多摘幾顆紅豆」的邀請留下來了。

所以下次你聽到人家用「紅豆」比喻情人，你可以跟他說：欸，這個典故最早是寫給一個男歌手的。那不是愛情，是一種比愛情更難的東西——是共同活過一個時代的老朋友，在時代結束之後，隔著千里，寫給彼此的「你還好嗎」。`
  },

  // id=270 盛唐 孟浩然 〈春曉〉rating=7
  // 詩眼：一個放下功名的中年隱士甘心的一個早晨
  // 隱藏連接：他被玄宗一句話踢回鹿門山的往事
  270: {
    title: "春曉",
    author: "孟浩然",
    summary: "所有小朋友都會背的〈春曉〉——其實是一個四十歲被皇帝親口趕走的中年人，終於甘心的一個早晨。",
    story: `跟你說我朋友浩然的一個早晨。這個人是唐朝最會把「不當官」寫得像天堂的詩人。

孟浩然是襄陽人，四十歲以前一直在鹿門山半耕半讀，日子過得很爽。他跟王維是好朋友，跟李白也熟。李白還寫過「吾愛孟夫子，風流天下聞」直接告白。四十歲那年他想通了：我這麼有才，該去長安試試看。

結果——落榜了。

按理說到這裡他應該灰溜溜回家。可他運氣不錯，跟王維混得夠好，王維某天把他偷偷帶進宮裡署衙聊詩。聊到一半唐玄宗突然來了。浩然嚇得躲到床底下，王維不敢欺君，只好如實稟報：有個叫孟浩然的詩人在下面。玄宗說：久聞大名，快出來，念一首你最近寫的給朕聽聽。

歷史記載浩然這時腦子突然當機，他不知道為什麼選了這句：「不才明主棄，多病故人疏」——因為我沒才華，聖明的君主拋棄了我；因為我常生病，老朋友也疏遠了我。

玄宗當場臉沉下來：你自己不來求官，我什麼時候拋棄過你了？你這是誣賴我。

放歸襄陽。四個字，把浩然的仕途永久封印，他就這樣回到了鹿門山。這一次是真的死心了。

我要跟你講的〈春曉〉，就是他這個階段的一個早晨。

那天他醒過來的時候，太陽已經很高了。他躺在床上，不急著起。你想想他有多爽——他不用趕早朝，不用趕考試，不用去長安低頭做人，不用擔心哪個官員要拜訪他。他就是躺著。

窗外樹上的鳥一陣一陣叫。不是一隻，是很多隻。它們吵得很開心。他就聽著。

他想起昨天晚上下過雨。不是聽見了——是躺著躺著想起來的。夜裡他睡得太熟，只在半夢半醒之間，恍惚聽見過幾聲風雨。

窗外的樹是桃樹。開花了好一段時間。他忽然想——被夜裡那場雨打掉了多少呢？

他沒有起來看，他就那樣躺著，繼續讓陽光曬進屋子裡，慢慢想著這個問題。他不再急著計較得失。花掉了幾朵，就掉了。

然後他起身，去書桌前寫下二十個字：「春眠不覺曉，處處聞啼鳥。夜來風雨聲，花落知多少。」

沒有一個字提到「我」。沒有得意，沒有失落，沒有感嘆。就是躺著、聽到鳥叫、想起昨夜的雨、隨口問了一句花掉多少，然後翻個身繼續睡。

這是一個徹底不在乎的人才寫得出來的詩。

李白後來說他「紅顏棄軒冕，白首臥松雲」——年輕時就丟開烏紗帽，老了就躺在山上看雲。這就是浩然一輩子的姿勢。

〈春曉〉不是兒歌。它是一個中年人終於甘心的一個早晨。他沒去看那些花掉了幾朵。不需要。`
  },

  // id=273 盛唐 王之渙 〈登鸛雀樓〉rating=7
  // 詩眼：不是少年壯志，是丟官 15 年重新出仕的中年人的自我鞭策
  // 隱藏連接：他一生只留 6 首詩，兩首成千古絕唱
  273: {
    title: "登鸛雀樓",
    author: "王之渙",
    summary: "所有人都以為「更上一層樓」是少年志得意滿的宣言——其實是丟官後隱居十五年、剛剛爬起來的中年人對自己說的話。",
    story: `跟你說我朋友季陵一個下午的心情。這個人一輩子只留下六首詩——就這六首，其中兩首成了千古絕唱。一首是「羌笛何須怨楊柳」的〈涼州詞〉，另一首就是這首〈登鸛雀樓〉。

聽起來很厲害對吧？可是他人生大部分時間都不順。

王之渙（字季陵）年輕時當過衡水主簿，一個小官。他為人剛正，做事俐落，本來前途看好。結果被同事誣告，他一氣之下——「拂衣去官」——直接辭職走人。

這一走，就在家鄉閒了十五年。

十五年，你想想。他三十歲出頭賦閒到四十幾歲。同輩的人都升官了，他還在家喝酒、寫詩、跟王昌齡、高適、崔國輔這幾個朋友唱和。他有沒有後悔？有沒有想過就這樣過一輩子算了？

沒人知道。但我們知道他終究還是走出來了。晚年他重新出仕，當了文安縣尉——比當年還小的官。但他沒抱怨。他還是一絲不苟地做事。

〈登鸛雀樓〉大概就寫在他重新出發的這段時期。

鸛雀樓在今天山西永濟，就在黃河邊上。那年他登上這座樓的時候，已經是一個丟過官、賦閒十五年、剛剛爬起來的中年人。他不是意氣風發的少年。他站在樓上往西看——夕陽正在往山後面沉下去，一整片橘紅。他再往東看——黃河一路奔騰，往山東方向的大海去了。

太陽在下山。這是提醒他自己的：時間不多了。
黃河還在往前流。這也是提醒他自己的：天地間有些東西不會停下來，你也不能停。

他站了很久。他知道從這座樓上能看到的東西已經到極限了。但他想看更遠。他想看到黃河一路流到大海的樣子。他想看到更西邊的日落的樣子。

要看更遠，就要爬更高。

他登上再上一層樓。往下看，鸛雀樓下的樓層變小了。往遠看，能看見的地平線又拉開了。他忽然覺得——這就是他人生欠自己的東西。他四十幾歲重新出仕，很多人以為他這輩子就這樣了。他不這麼想。他要繼續往上爬。不是為了當大官，是為了繼續看見更多東西。

他下樓的時候寫下二十個字：

白日依山盡，黃河入海流。欲窮千里目，更上一層樓。

「欲窮」——想要看盡——這是一個已經很滿足現狀的人不會用的字。只有還想再看更多的人，才會說「欲窮千里目」。

王之渙寫完這首詩沒幾年就過世了。他一生僅存的六首詩，兩首成千古絕唱。從命中率來說，他大概是唐詩史上最恐怖的存在。

所以下次你在人生某個卡關的時刻，覺得自己已經來不及了：想想王之渙四十幾歲從家鄉走出來，寫下這句「更上一層樓」。從來沒有太晚。只有停在原地。`
  },

  // id=288 中唐 賈島 〈尋隱者不遇〉rating=7
  // 詩眼：他一輩子想成為的那種人就在同一座山裡，只是他找不到
  // 隱藏連接：賈島早年當過和尚，隱者是他走不成的另一條路
  288: {
    title: "尋隱者不遇",
    author: "賈島",
    summary: "他站在松下沒找到那位隱者——但那位隱者其實就是他自己「本來可以成為的那個人」，只是被雲蓋住了。",
    story: `跟你說我朋友浪仙的一個下午。他的名字你可能沒聽過，但你一定聽過他的典故——「推敲」，就是他的故事。

賈浪仙（賈島）年輕時是個和尚，法名叫「無本」，在洛陽附近的寺廟裡住了很多年。後來他遇到韓愈——就是「唐宋八大家」之首的那個韓愈——韓愈勸他還俗、勸他去考科舉。他猶豫了很久，最後真的還俗了，去考進士。

——考了一輩子沒中。

他的名字就這樣卡在唐朝科舉史裡：一個常常在秋天長安街上騎驢邊走邊念詩、想著「僧敲月下門」還是「僧推月下門」比較好的中年落榜生。他當時撞到韓愈的儀仗隊，韓愈聽了兩句反而說：用「敲」比較好。從此兩人成了朋友。

浪仙這個人一輩子在兩件事之間拉扯：一邊是他年輕時的僧人身分——山裡、雲間、藥草、清晨掃地；一邊是他中年之後想證明自己的科舉之路——長安、榜單、應酬、失眠。

〈尋隱者不遇〉就寫在他這種拉扯的中間。

他去山裡找一位隱士。這位隱士是誰？史料沒說。但可以確定的是——他是一個活得像浪仙「本來可以成為的自己」的那種人。

他走到山裡。松樹很多。他找到隱者住的地方——一間簡樸的茅屋。屋前一棵老松樹底下，站著一個童子。可能十歲出頭，穿著粗布，很乖巧。

他問童子：你師父在嗎？

童子的回答很短：師父採藥去了。

浪仙大概愣了一下。什麼時候回來？往哪走了？他繼續問。

童子伸手往山上一指：就在這座山裡。

——就在這座山裡？山那麼大呢？

童子又加一句：山上的雲太厚，我也不知道他在哪。

浪仙站在松下，抬頭看山。雲厚厚地壓在山腰，一大片白，看不進去。他知道那位隱者就在那片白裡面，可能正在採一種特定的草藥，可能剛好在跟一隻鹿說話，可能坐在某塊石頭上曬太陽。他離浪仙很近，可是浪仙看不見他。

他沒有繼續問。他也沒有等。他站在松下看了一會兒，然後轉身下山。

回去的路上他寫了二十個字：

松下問童子，言師採藥去。只在此山中，雲深不知處。

他寫完把紙折起來，準備下次找韓愈的時候給他看。他知道韓愈會懂——因為他自己讀完這首詩才明白，他真正想找的不是那個隱者，是他自己「本來可以是的那個人」。

那個人就在同一座山裡。可是被雲蓋住了。看不見。

浪仙最後也只當到一個小小的縣令，晚年在四川過世。他這輩子始終沒能爬回那座山裡，成為童子口中那樣的人。但他留下了這四句話，讓後世每一個「回不去」的人，都能站在他當年站過的松下，抬頭看看那朵雲。`
  },

  // id=295 中唐 李紳 〈憫農詩-其二〉rating=7
  // 詩眼：27 歲的真心，70 歲被自己的生活背叛
  // 隱藏連接：晚年李紳一頓飯殺三百雞取雞舌的記載
  295: {
    title: "憫農詩-其二",
    author: "李紳",
    summary: "寫下「粒粒皆辛苦」的少年李紳，跟晚年當上宰相、一頓飯要殺三百隻雞的宰相李紳，是同一個人。",
    story: `跟你說一個很沉重的故事。這首所有小朋友吃飯時被爸媽念過的〈憫農〉——你知道寫這首詩的李紳，後來變成了什麼樣子嗎？

李紳寫這首詩的時候大概二十七歲，還沒中進士。他是安徽亳州人，出身官宦家庭但家道中落，青年時期跟窮困的農民有過近距離接觸。有一天他經過田間，看見農民在正午的烈日下彎著腰鋤禾。那個畫面震撼了他。

他停下來看。那個農夫的斗笠已經被汗浸得發黃。汗珠一滴一滴滾下他的下巴，滴到禾苗底下的泥土裡。太陽正在頭頂上，一絲風都沒有。禾苗長得很好，可是這個農夫可能自己一年到頭沒吃過幾頓白米飯。

李紳站在田邊，突然明白一件他從來沒想過的事：他長這麼大吃的每一碗飯，都是這樣被曬出來的。

他回到家寫下二十個字：

鋤禾日當午，汗滴禾下土。誰知盤中飧，粒粒皆辛苦。

他寫這首詩的時候是真心的。這一點很重要，別急著否定。

問題出在後來。

李紳中了進士，做官，一路升遷。他跟白居易、元稹是好朋友，是「新樂府運動」的核心成員之一，年輕時他們一起主張「詩歌要為民生疾苦發聲」。這一階段的李紳，還是那個寫〈憫農〉的李紳。

然後他當上淮南節度使，最後做到宰相。

《雲溪友議》和《本事詩》裡記載了他晚年的生活：一頓飯要「食雞舌」，做一盤菜要殺三百隻雞——只取牠們的舌頭，其餘全部丟掉。宴請客人的排場豪華到連他的老友劉禹錫都寫詩暗諷。他還被指控貪贓、迫害下屬。他晚年最有名的案子是「吳湘冤案」——他強行判一個下級官員死刑，事後被證實是冤枉的。

寫「粒粒皆辛苦」的那個李紳，跟一頓飯殺三百隻雞的那個李紳，是同一個人。

這才是這首詩最深的重量。

你以為這是一個簡單的教育兒童要珍惜糧食的詩？其實它是唐朝寫給我們的一個警告：一個人年輕時真心相信的東西，可能會在他自己手上被推翻。

李紳寫〈憫農〉那一年二十七歲。他當宰相殺雞取舌那一年，大概七十歲。這中間發生了什麼？沒有人替他寫下來。他自己也沒有解釋。

但這首詩留下來了。就這二十個字，穿越一千兩百年，繼續讓每個小朋友在飯桌上被念一遍。

我常想：也許李紳晚年在他豪華的宴席上，某個瞬間，會不會突然聽見自己二十七歲寫下的那句「粒粒皆辛苦」？會不會有一秒，他放下筷子，不敢再吃了？

我們不知道。但我們知道：他寫的這首詩，比他這個人活得更久、更真、更好。

這才是文學最殘忍的地方。它會記得你最好的一刻，然後見證你如何背叛它。`
  },

  // id=297 晚唐 李商隱 〈登樂遊原〉rating=7
  // 詩眼：一個看見自己人生黃昏的人的獨白
  // 隱藏連接：他就是那個夕陽——才華還在燒，時間已經不多
  297: {
    title: "登樂遊原",
    author: "李商隱",
    summary: "「夕陽無限好，只是近黃昏」——他不是在寫夕陽，他是在寫他自己。",
    story: `跟你說我朋友義山的一個下午。這個人一輩子夾在唐朝晚期兩派政治鬥爭之間——牛黨、李黨——兩邊都不待見他。原因說起來很戲劇：他年輕時被牛黨的令狐楚提拔，這是他的恩人；後來他娶了李黨王茂元的女兒，這下牛黨恨他忘恩負義，李黨又不完全信任他。

一個沒有陣營、有才華、又有原則的人，在晚唐這種爛透了的政治環境裡，只能眼睜睜看著自己越走越邊緣。

義山這輩子做過最大的官叫「校書郎」——一個負責校對書籍的小官。他的才華全唐朝都認可，但他就是升不上去。他每次覺得快要有轉機，就有人把他踢回去；他每次以為自己站穩了，就又被調到偏遠的地方。他四十六歲就過世了。

〈登樂遊原〉大概寫在他晚年，某個心情不太好的下午。

樂遊原是長安東南的一片高地，是當時長安人登高散心的最佳去處。從這裡可以看到整個長安城，看到夕陽從西邊落下。這一天他心裡悶悶的，就叫車伕載他上去。

到了樂遊原。這時候正是傍晚。夕陽已經開始沉下去，整片天空是橘紅色的，長安城的宮闕、坊市、街道，全部被染成一片金色。那是這一天最美的時刻。

義山站在那裡看了很久。這片景色美到讓他呼吸都不敢重。他知道再過一會兒，夕陽會全部沉下去，這片金色會全部消失。今天這一刻——這種燒得像神蹟一樣的美——就過了。

他忽然想到自己。

他四十幾歲了。他的才華已經燒到了頂點。他寫的詩美到讓後世研究者頭痛，可是他還沒能走到能讓才華發光的位置。他很清楚：如果他也是一輪太陽，他也正在下沉。

他不是不知道。他就是不甘心。

他從樂遊原下山之前，寫了二十個字：

向晚意不適，驅車登古原。夕陽無限好，只是近黃昏。

他不是在寫景。他是在寫他自己。

夕陽無限好——我知道自己還沒完全燒盡，我還有很多東西可以寫、可以做。
只是近黃昏——但我的時間，快到了。

他寫這首詩沒過幾年就過世了。

有意思的是，宋朝以後有人重新解讀這兩句，說它的意思是「正因為近黃昏，所以才無限好」——一種豁達的接受。這種讀法讓這首詩多了一層溫度。也許義山寫的時候，本來只是感嘆自己時間不多；但這句話一千年之後，變成了每個中年人在人生某個下午都會突然懂的一種心情：知道剩下不多，反而覺得眼前的一切特別美。

〈登樂遊原〉最厲害的地方就在這裡：它的悲，變成了千年後的美。

所以下次你在某個傍晚突然覺得眼前的夕陽美到不像話，你可以想想義山。那個在樂遊原上看夕陽的中年人，他站在那裡的時候，已經替你哭過了。`
  },

  // id=343 中唐 張繼 〈楓橋夜泊〉rating=7
  // 詩眼：失眠夜聽到本來不該響的鐘聲——那個夜晚救了他一生
  // 隱藏連接：張繼一輩子只以這一首詩傳世
  343: {
    title: "楓橋夜泊",
    author: "張繼",
    summary: "他這輩子沒想過，一個落榜的失眠夜、一聲本來不該響的鐘，會變成他所有人生的意義。",
    story: `跟你說我朋友張繼一個超級關鍵的失眠夜。

張繼這個人，你聽過吧？——月落烏啼霜滿天那個。但你可能不知道：張繼一輩子的官途、事蹟、生平，加起來史書上寫不到兩百個字。他這個人，其實就是靠這一首詩活下來的。如果沒有這首詩，張繼就跟唐朝幾千個沒沒無聞的中低級官員一樣，被歷史完全遺忘。

而這首詩，寫在他人生最狼狽的一個晚上。

那年是天寶年間，張繼剛剛在長安落榜。他從長安一路南下，準備回江南老家。經過蘇州的時候，天已經黑了，他把船停在城外楓橋邊上。他沒錢住城裡的客棧，就在船上將就一夜。

那一夜他睡不著。

外面的月亮已經西沉，就要落下去了。天快亮又還沒亮的時候，烏鴉開始叫。天氣冷得像下了霜。他從船艙裡出來看看——江邊的楓樹一片黑影，遠處漁船上的燈火閃著一點微光。他自己躺回去，翻來覆去，怎麼樣都睡不著。

你有沒有失眠過？半夜三、四點，翻來覆去，那種「這輩子是不是就這樣了」的自我懷疑——張繼那晚就在這個狀態。他三十幾歲了，考不上，回家還要面對親戚朋友的目光。他躺在船艙裡，聽著楓橋外的水聲，覺得自己的人生大概就這樣了。

然後——他聽見了一件不對勁的事。

寒山寺的鐘，居然在半夜響。

按照唐朝的規矩，寺廟的鐘應該在清晨敲響，或者黃昏敲響。半夜是不敲的。可那晚寒山寺的和尚，因為某種原因——可能是特殊法事、可能是某位僧人的私人習慣——在半夜敲了鐘。

這個「本來不該響」的鐘聲，穿過夜色，穿過江面，穿進了張繼的船艙，穿進了他的耳朵。

——他愣住了。

一個失眠的落榜生，在人生最低潮的時候，聽見了一聲本來不該聽見的鐘。

那個瞬間他坐起來，摸黑找到紙筆，寫下二十八個字：

月落烏啼霜滿天，江楓漁火對愁眠。姑蘇城外寒山寺，夜半鐘聲到客船。

他不知道自己這輩子將要成為「張繼＝寫楓橋夜泊的那個人」。他只是把當下的畫面老實記下來。

後來張繼考中了進士，做了一些小官，五十一歲的時候在洪州（今南昌）過世。他的其他詩作幾乎沒人記得。但這二十八個字，穿越一千兩百年，讓寒山寺變成蘇州的地標，讓「夜半鐘聲」變成中國人集體記憶的一部分。每年除夕，中日兩國的人還會特地跑到寒山寺聽一百零八響鐘聲。

這才是這首詩最動人的地方。不是失眠者聽見了鐘，是這個失眠夜救了張繼的一生。

如果他那晚睡得好，如果寒山寺那晚沒響鐘，張繼就是另一個被歷史吞掉的小人物。可是命運讓他在最不甘心的夜裡，聽見了一個本來不該存在的聲音。

你人生最狼狽的那個晚上，也許正在寫下你這輩子最重要的一首詩。只是你當下不知道。`
  },

  // id=377 晚唐 杜牧 〈清明〉rating=7
  // 詩眼：異鄉打工人的節日心情——牧童的手勢比酒館本身重要
  // 隱藏連接：杜牧當時被外派江南某處任職
  377: {
    title: "清明",
    author: "杜牧",
    summary: "所有節日獨在異鄉的人都懂：回不了家的日子，能給自己最溫柔的一件事，是遠處那個指向酒館的手勢。",
    story: `跟你說我朋友牧之的一個清明節。這首「清明時節雨紛紛」，是他寫的（雖然學界有些爭議，但傳統上算他的），寫的是所有異鄉打工人都懂的一個心情——過節、一個人、不在家。

你想像一下畫面。清明節那天，牧之不在長安，也不在他老家萬年縣（今西安附近），而是被外派在江南某個小地方當官。清明本來是要掃墓、要祭祖、要跟家人一起吃青糰的日子。可他呢？他一個人，在他鄉。

那天下雨。不是傾盆大雨，是那種綿綿密密、下不停也淋不濕、但就是讓人心情發霉的江南春雨。

他從住的地方走出來。路上偶爾有幾個行人，但每個人臉上都是那種「今天不想跟人講話」的表情。他自己也是。

他不知道要去哪。他就是不想待在住的地方。因為住的地方越安靜，越提醒他這裡不是家。

他就這樣一個人在雨裡走。走到某個路口的時候，他終於決定做一件事——找一杯酒喝。他攔住一個路人問：附近哪裡有酒館？

這個路人是誰？一個牧童。一個放牛的小孩。可能才十歲出頭，穿著蓑衣，戴著斗笠，牽著一頭牛慢慢走。

小孩沒有回答他的問題，只是——伸手一指。

那個指向遠方的手勢，就是這首詩的靈魂。

牧之順著小孩的手看過去，遠遠地，穿過雨霧，他看見一片開著杏花的村莊。那裡有酒。

他站在路口看了一會兒。杏花在雨裡是粉紅色的。村子還蠻遠。他要走過去可能要走半個鐘頭。他抬起腳，往那個方向走。

他一邊走一邊寫下了二十八個字：

清明時節雨紛紛，路上行人欲斷魂。借問酒家何處有？牧童遙指杏花村。

你注意到了嗎？這首詩沒有告訴我們牧之有沒有走到那個村。他有沒有喝到酒。他喝到酒之後心情有沒有變好。都沒寫。

它停在「牧童遙指」的那一個手勢上。

因為那個手勢，就是這首詩想說的全部。

當你在異鄉、當你孤獨、當你想家想到不知道該怎麼辦——你不一定真的要跑去那間酒館。你只需要知道遠處還有一間酒館，就已經足夠讓你撐過這個下午了。

牧童的手指，指的不是酒館，是一個「還有地方可去」的希望。

這首詩流傳一千兩百年，是因為它命中了所有「回不了家的節日」的核心：我們不奢求回家，我們只需要有個方向可以走。

現代人在城市裡加班加到春節，看見便利商店的燈；在國外留學過中秋，看見樓下的小酒吧亮著；一個人搬到新城市過生日，看見手機裡外送 App 的推薦頁——那都是我們自己的杏花村。

牧之那天有沒有走到杏花村？其實不重要。重要的是，那個牧童的手勢，穿過一千兩百年的雨，還在替每個過節不在家的人指路。`
  },

  // id=422 中唐 白居易 〈花非花〉rating=7
  // 詩眼：一段抓不住的美好——所有讀者可以填自己的東西進去
  // 隱藏連接：可能是湘靈，可能是簡簡，可能都不是
  422: {
    title: "花非花",
    author: "白居易",
    summary: "唐朝寫得最像現代流行歌的一首。他不告訴你在寫什麼，因為所有你抓不住的東西，都是它在寫的。",
    story: `跟你說我朋友樂天寫過的一首怪詩。這個人一輩子寫超過三千首詩，是全唐第一多產詩人。他寫〈長恨歌〉一百六十句一氣呵成，寫〈琵琶行〉六百字酣暢淋漓——他從不吝嗇字數。

但他寫過一首怪詩，只有二十六個字。而且他到死都沒告訴任何人這首詩在寫什麼。

樂天晚年把這首詩收在自己的《白氏長慶集》「感傷詩」那一類裡。感傷什麼？他沒說。詩題就叫〈花非花〉——一個等於沒說的題目。整首詩只用比喻，沒有一個具體的名詞。

於是後世研究者吵翻了。

有人說：這是寫他早年的戀人湘靈。樂天十九歲時在故鄉符離認識的鄰家女孩，兩人相愛超過十年，最後被他母親強力反對，逼他三十七歲才娶了別人。湘靈這輩子沒嫁人。樂天到四十幾歲還在偷偷寫詩想她。這首「夜半來，天明去」——會不會是他夢見了她？

也有人說：這是他悼念一個叫簡簡的小女孩。樂天另有一首詩叫〈簡簡吟〉，寫一個十三歲就夭折的鄰家聰慧小姑娘，他很喜歡她。「花非花」也許是同一個時期的作品，同一個嘆息。

還有人說：都不是。這只是樂天寫給「所有他失去過的東西」的一首抽象詩——青春、愛情、才華、盛世，所有那些你以為抓在手裡、回頭卻發現早就沒了的東西。

樂天本人一直沒解釋。他就讓這首詩這樣浮在他的詩集裡，像個謎。

我覺得他是故意的。

因為他不解釋，所以每個讀者可以把自己的東西填進去。

你失去過一段感情嗎？——就是那個人。
你懷念過大學時代的某個朋友嗎？——就是那段時光。
你有沒有過一段短暫的、以為會一直下去、結果突然結束的關係？——就是它。

樂天寫這首詩的時候用了一種很超前的手法：他不告訴你他寫什麼，因為所有你抓不住的東西，都可以是他寫的。

他寫的內容是這樣：

花非花，霧非霧，夜半來，天明去。來如春夢幾多時？去似朝雲無覓處。

不是花，也不是霧。半夜來，天明就走。來的時候像春夢一樣不知道有多久，走的時候像早晨的雲，你到處找都找不到。

有意思的是，這首詩後來變成了現代作曲家們最愛拿來譜曲的唐詩之一。二十世紀有三十幾個作曲家為它寫過曲子，各種版本流傳。原因就是它太像流行歌了——短、抽象、有意境、可以填任何情緒進去。

一首寫在九世紀的詩，長得像二十一世紀的失戀情歌。

樂天大概自己也沒想到。他晚年隨手寫下的一個模糊的嘆息，居然穿越一千兩百年，變成了每個抓不住東西的人都能哼一遍的歌。

這就是為什麼〈花非花〉會活這麼久。因為每一代人都有自己的花非花。都有一些東西，明明剛剛還在，天亮就找不到了。`
  },

  // id=436 北宋 蘇軾 〈水調歌頭-丙辰中秋〉rating=7
  // 詩眼：兄弟思念升級成千年來所有中秋思親人的祝福
  // 隱藏連接：蘇軾與蘇轍的兄弟情深
  436: {
    title: "水調歌頭-丙辰中秋",
    author: "蘇軾",
    summary: "這首中秋節被 LINE 群組轉爆的詞，是一個四十一歲的哥哥寫給七年沒見的弟弟——最後卻變成了千年來所有想家的人共同的祝福。",
    story: `跟你說我朋友子瞻家的一件事。這個人這輩子最重要的關係，不是他兩任妻子、不是他跟王安石的政敵、不是他跟朋友，是他弟弟。

子瞻（蘇軾）跟子由（蘇轍）兄弟差三歲。他們從小一起讀書、一起考科舉，兩人同一榜中進士。史書記載他們寫詩超過一半是寫給對方的。可是兩兄弟的仕途一直讓他們分開。子瞻被貶遍了整個中國——杭州、密州、黃州、惠州、儋州；子由也是東調西調。他們一年到頭很難見上一面。

宋神宗熙寧九年，也就是丙辰年（西元一〇七六），中秋節這一天，子瞻四十一歲，在密州（今山東諸城）當太守。他已經七年沒見到弟弟了——子由當時在濟南，兩地相距不遠，但公務纏身就是碰不著面。

那天晚上，子瞻喝酒。喝到大醉。

中秋的圓月升起來了。他一個人在密州的官舍裡，仰頭看月亮，心裡想的是弟弟。他站起來走到院子裡。他喝得有點站不穩，覺得整個世界在轉。他想跟月亮說話、想跟老天說話、想跟他弟弟說話——可是他弟弟不在。

他在月光下跳起舞來。他的影子被拉得長長的。他忽然醒悟——天上再冷，也比不上人間有他弟弟的溫度。

他回屋坐下寫詞。他抱怨月亮——為什麼老是在人分別的時候特別圓？他又自己和解——人會分離，月會缺，這種事情自古就沒有兩全。

寫到這裡如果是一般人會停在傷感裡。可是子瞻沒停。他把個人的思念，升級成了對全天下的祝福。

他寫下的是這首詞：

明月幾時有？把酒問青天。不知天上宮闕，今夕是何年。我欲乘風歸去，又恐瓊樓玉宇，高處不勝寒。起舞弄清影，何似在人間。轉朱閣，低綺戶，照無眠。不應有恨，何事長向別時圓？人有悲歡離合，月有陰晴圓缺，此事古難全。但願人長久，千里共嬋娟。

最後那句願望——只希望我們都活得夠久，即使在千里之外，也能共同看著同一個月亮——他當下寫下的時候，是替他自己跟子由許的。但這句祝福一千年後會被每一個中秋節轉爆。

子瞻寫完把這首詞寄給了子由。子由讀完也寫了一首和詞回哥哥，題目也叫〈水調歌頭〉。兩兄弟就這樣用詞聊天。

後來的故事更揪心：子瞻晚年被貶到海南儋州，離弟弟更遠了。他過世前特別交代弟弟——與君世世為兄弟，再結來生未了因。這輩子當你哥哥還不夠，下輩子我還要當你哥哥。子由替他寫的墓誌銘超過九千字。他寫著寫著就哭了。

所以下次中秋節你在群組裡轉發那句祝福的時候，你可以想一下——它原本是一個四十一歲的哥哥，在山東的一個中秋夜，喝醉了、想弟弟、想到不知道怎麼辦，才寫下來的。`
  },

  // id=3 三國 曹操 〈短歌行〉rating=6
  // 詩眼：站在人生巔峰的梟雄在戰前宴席上的焦慮——時間不夠、人才不夠
  // 隱藏連接：據傳寫於赤壁之戰前夕橫槊賦詩
  3: {
    title: "短歌行",
    author: "曹操",
    summary: "一個五十四歲、擁兵百萬、站在人生巔峰的梟雄，在戰前宴席上第一句想的居然是——我還有多少時間？",
    story: `跟你說一個超級魔幻的畫面。建安十三年冬天，長江邊上。曹操率領號稱八十萬大軍南下。當晚他在戰船上大擺宴席，文武百官全體出席。他喝多了，站起來，手裡拿著長矛（那把矛叫「槊」），對著長江橫著就開始朗誦一首詩——這就是後人說的「橫槊賦詩」，也就是這首〈短歌行〉。

那時他五十四歲。北方已經被他統一，接下來就是要拿下江東孫權、荊州劉備。他站在戰船上，覺得整個天下都在他腳底下。

可是他抬起酒杯，第一句就震住了全場。

他想的居然是——我還有多少時間？

一個站在人生巔峰、擁兵百萬的曹操，在最志得意滿的夜晚，第一句想的是「時間不夠」。這就是這首詩最有意思的地方。強者的孤獨是這種：不是他失敗，是他太清楚——成事需要的時間，比他剩下的時間多。

接下來他做了一件很妙的事：當著所有部下的面，公開招賢。

他引用《詩經》裡少女想念心上人的句子，用來表達自己對人才的思念。這是超級大膽的比喻，等於曹操公開說：我對還沒來投靠我的人才，就像一個女子思念情人一樣。

在座部下驚呆了。梟雄用少女的口吻示愛人才，這種事只有曹操做得出來。

寫到中段，他抬頭看天。中原冬天的夜空，月亮出來得早，星星就顯得少了。天上有幾隻烏鵲，繞著江邊的樹飛了三圈，找不到一根樹枝可以停。

他把烏鵲寫進詩裡。他要暗示天下人才：你們就像那些烏鵲，繞了半天沒地方去。來我這裡，我這棵樹夠大。

最後他丟出全詩的高潮，用周公吐哺的典故——當年周公為了招待人才，一頓飯要吐出三次口中的食物去見客人——曹操用這個典故告訴部下：我要做同樣的事。

他吟完整首詩：

對酒當歌，人生幾何。譬如朝露，去日苦多。慨當以慷，憂思難忘。何以解憂，唯有杜康。青青子衿，悠悠我心。但為君故，沉吟至今。呦呦鹿鳴，食野之蘋。我有嘉賓，鼓瑟吹笙。明明如月，何時可掇。憂從中來，不可斷絕。越陌度阡，枉用相存。契闊談讌，心念舊恩。月明星稀，烏鵲南飛。繞樹三匝，何枝可依。山不厭高，海不厭深。周公吐哺，天下歸心。

這首詩寫完，全場歡呼。這是史上最強的一次招賢演說。

但你知道嗎？就在這首詩寫下沒多久，赤壁之戰爆發了，曹操被燒得潰不成軍。

那晚宴席上的「志在千里」，變成了他一生最大的挫敗。他退回北方，從此再也沒能統一天下。三國鼎立的格局，就從那把火開始定下來。

有意思的是，這首〈短歌行〉沒有因為他的失敗而失色，反而因為那晚的畫面太過壯麗、太過孤獨、太過真實，成為千古傳誦的傑作。曹操這輩子做過的事情夠殘忍夠精采，但讓後世永遠記得的，是他站在長江戰船上的那一夜，一個五十四歲的老男人，一手拿矛、一手拿酒杯，突然說——我還有多少時間？

強者的哀嘆，永遠比弱者的呻吟更讓人揪心。`
  },

  // id=6 東晉 陶淵明 〈飲酒-其五〉rating=6
  // 詩眼：被官場逼出來後突然發現「不用再證明什麼」的自由感
  // 隱藏連接：不為五斗米折腰的辭官事件
  6: {
    title: "飲酒-其五",
    author: "陶淵明",
    summary: "他不是天生的隱士。他是被官場逼到牆角、才學會了「不用再證明什麼」的中年男子。「悠然見南山」是他這輩子最寶貴的自由。",
    story: `跟你說我朋友淵明的一件小事。這個人不是天生的隱士。他二十九歲出來當官，中間辭官、再當官、再辭官、再當官——來回折騰了十三年。他不是不想做事，是這個時代讓他覺得做什麼都髒。

他四十一歲那年，被派到彭澤當縣令。做了八十幾天，上級派了一個督郵下來視察。手下人跟他說：你得穿正裝、繫好腰帶去迎接。淵明說了那句著名的話——我不能為五斗米折腰向鄉里小兒。

——當天就辭職，回家。

從此不再出仕。他四十一歲。

〈飲酒〉這一組詩（一共二十首）就寫在他辭官之後的某段時間。他辭官後的生活其實很苦——他自己種田種得爛，好幾次差點餓死。他不是那種瀟灑的富家隱士，是真的窮到偶爾要跟鄰居借糧的那種隱士。

但這首〈其五〉是這二十首裡最有名的。

那年秋天他家院子東邊的籬笆下開了菊花。他親手種的。他要去採一些，晚上泡酒喝——他的酒喝完了，得自己想辦法。

他蹲下來採菊。這是實務工作，他要拿菊花去泡酒，不是為了作詩擺姿勢。他採著採著，直起腰來——剛好看到遠方的南山（廬山南邊那座）。

那座山他每天都看得到。可是那一瞬間，他忽然覺得整座山跟他之間有種奇怪的默契。他站在那裡看了很久。夕陽時候，山上的雲氣特別好看。天上一群飛鳥慢慢飛回巢。

他心裡湧起一種說不出的東西。他想告訴誰——這一切裡面有一個真正的道理。可是他張開嘴，發現自己已經忘了怎麼講。

當官的人最會的就是用語言證明自己——寫奏摺、應對、辯論、周旋。而現在他終於變成了一個懶得再解釋的人。

他採完菊回屋，寫下十句話：

結廬在人境，而無車馬喧。問君何能爾，心遠地自偏。採菊東籬下，悠然見南山。山氣日夕佳，飛鳥相與還。此中有真意，欲辨已忘言。

「悠然見南山」的關鍵在那個「見」字。不是「望」，不是「看」，是他低頭做事的時候不小心撞見的。是南山一直都在那裡，只是他終於變成一個不用刻意追求什麼的人，所以才能剛好看見它。

如果是望南山，那是刻意去追求美景。見南山，是南山替他來的。

這才是為什麼這首詩會活一千五百年。它不是描寫多美，它示範了一種活法——不刻意，就會遇見。

淵明不是天生就悟道的隱士。他是被時代逼到牆角，才學會了「不用再證明什麼」。

一千五百年後，每個上班族在午休時走出公司大樓、抬頭看見天上一朵雲，突然愣兩秒的那個瞬間，那就是我們自己的「悠然見南山」。

淵明教會我們的不是離職，是知道自己什麼時候該停下來看看雲。`
  },

  // id=11 盛唐 李白 〈下終南山過斛斯山人宿置酒〉rating=6
  // 詩眼：長安失意時，某夜在山民朋友家的一個安靜晚上
  // 隱藏連接：他此刻剛剛失去玄宗的重用，正在山中散心
  11: {
    title: "下終南山過斛斯山人宿置酒",
    author: "李白",
    summary: "號稱斗酒詩百篇的李白，其實累的時候只想去一個平凡朋友家，喝點小酒、聽聽風、看星星消失就好。",
    story: `跟你說一個很少人講的李白版本。這個李白不是「將進酒」那個狂人，是一個在長安碰壁後、跑到終南山散心的中年男子，某個傍晚下山遇到山民朋友，度過了一個安靜的夜晚。

背景是這樣。李白四十二歲那年被玄宗召進長安當翰林待詔，本來以為要一展抱負，結果玄宗只把他當作寫詩助興的宮廷寵物——皇帝去打獵，叫他寫詩；楊貴妃看牡丹，叫他寫詞。他寫得爽，玄宗更爽。但他想談政治？沒門。

太白很快就悶了。他跟高力士、楊國忠這些人也不對付。他跑去終南山散心——終南山離長安只有三十幾公里，是唐朝官員與文人失意時的標配避風港，號稱「終南捷徑」，很多人假隱居真等再被召回。太白這次去，是真的想暫時逃開。

他在山上待了不知道多久。某天傍晚他下山，準備走回長安。這首詩就開始了。

太白從一個青綠的山頂往下走。天色慢慢暗下來。一輪月亮從他背後升起，投出他的影子，一路陪他到山下。他回頭看剛才走過的山路——一片蒼翠橫在山腰上，非常美。

到了山腳下他遇到一個朋友——「斛斯山人」。這個人是誰？史書沒有記載。「斛斯」是複姓，這是一個住在終南山下的普通山民，姓斛斯的人。太白認識他。

朋友一看見他就拉著他往家裡走。走到家，一個小孩跑出來開柴門。院子裡竹子夾道，藤蘿掃過他的衣服。

注意這個細節——這家有小孩。太白走進的不是一個隱士的清冷茅屋，是一個有小孩、有煙火氣的普通農家。

朋友端出酒來。不是什麼名酒，就是自釀的濁酒。太白很開心。他們兩個開始喝。

這一晚的太白很收斂。因為對面不是達官貴人，是個好客的普通山民。他沒有「將進酒，杯莫停」的狂喊，只是姑且喝幾杯。

他喝到微醺，開始唱歌。松林在夜風裡發出沙沙的聲音，剛好跟他的歌合上。他們兩個一直聊，聊到銀河的星星都稀了——快天亮了。

太白最後醉了。他倒在朋友家的墊子上，什麼心機都沒有了。

回長安之後他寫下十句話：

暮從碧山下，山月隨人歸。卻顧所來徑，蒼蒼橫翠微。相攜及田家，童稚開荊扉。綠竹入幽徑，青蘿拂行衣。歡言得所憩，美酒聊共揮。長歌吟松風，曲盡河星稀。我醉君復樂，陶然共忘機。

「忘機」是這首詩最動人的兩個字。「機」是心機，是算計，是太白在長安宮廷裡每天要應付的那些東西。在斛斯山人的家裡，這些東西全部消失了。

這首詩沒有金句。沒有「天生我材必有用」的自我打氣，沒有「舉杯邀明月」的孤獨，沒有「抽刀斷水」的憤懣。它只是記錄了一個晚上——太白這輩子少數幾個真正放鬆的晚上之一。

這才是這首詩最珍貴的地方。它告訴我們一個秘密：那個號稱斗酒詩百篇的太白，其實累的時候，也只想去一個平凡朋友家，喝點小酒、聽聽風、看星星消失就好。

沒過多久他就被賜金放還，離開長安了。他這輩子再也沒回到斛斯山人的家。但他把那一晚寫下來了，讓我們知道：在他所有豪言壯語的背後，他其實嚮往的是這種簡單的一夜。`
  },

  // id=12 盛唐 李白 〈月下獨酌〉rating=6
  // 詩眼：灑脫的李白其實孤獨到必須跟自己的影子喝酒
  // 隱藏連接：長安宮廷應酬中的極度孤獨
  12: {
    title: "月下獨酌",
    author: "李白",
    summary: "史上最灑脫的李白，其實孤獨到必須跟自己的影子喝酒——這才是他寫過最誠實的一首詩。",
    story: `跟你說我朋友太白一個很誠實的秘密：他其實非常非常孤獨。

大家印象中李白是「五花馬，千金裘，呼兒將出換美酒」的豪俠、是「舉杯邀明月」的浪漫詩人。但這種印象忽略了一件事——他寫最多的題材是「一個人」。他有超過一百首詩寫自己孤獨的樣子。

〈月下獨酌〉就是他所有孤獨詩裡最坦白的一首。

背景是這樣。他在長安當翰林待詔的時期（七四二到七四四），表面上風光無限——被玄宗召見、住宮廷附近、有俸祿、有名氣。但實際上他孤獨到什麼程度？

他跟宮廷派系混不熟。高力士、楊國忠這些真正掌權的人他都得罪過。同時期的其他翰林學士看不起他（他們是進士出身，太白連科舉都沒考過）。楊貴妃身邊那些人嘲笑他的野心。他有官俸但沒有實權，有名氣但沒有朋友。

於是某個春天的夜晚——大概就是他快要離開長安的前幾個月——他在住處花園裡擺了一壺酒。

花園裡花開得正好。他找了個花叢間的位子坐下來。他自己一個人。整個長安沒有一個可以跟他坐下來喝酒的人。他官比不上人家高，資歷比不上人家老，家世比不上人家好。他只有詩寫得比誰都好——但這在酒桌上沒用。

他喝了一杯。悶。他抬頭看月亮，一個念頭冒出來——如果沒有人陪，我就邀月亮下來。

他舉起酒杯對著月亮。他當然沒有月亮陪。但是——他發現地上有他的影子。加上月亮跟影子，一共三個「人」了。

這是史上最寂寞的酒局。

他自己也知道這是假的。月亮不會喝酒，影子只會傻傻跟著他動。但他還是決定玩下去——就暫時把月亮和影子當朋友吧，快樂要趁春天。

他站起來唱歌。月亮在他頭上飄動。他跳舞——影子跟著他亂晃。你想像一下：一個中年男子（他當時四十二歲）在花園裡，喝到微醺，開始唱歌跳舞，抬頭看月亮，低頭看自己的影子，自己陪自己玩。你如果現在做這件事，你的家人會勸你去看醫生。太白就在長安宮廷附近的家裡這樣過了一整晚。

他喝到半醉，寫下這首詩：

花間一壺酒，獨酌無相親。舉杯邀明月，對影成三人。月既不解飲，影徒隨我身。暫伴月將影，行樂須及春。我歌月徘徊，我舞影零亂。醒時同交歡，醉後各分散。永結無情遊，相期邈雲漢。

最後一句——「永結無情遊」——「無情」不是薄情，是「不涉及情感糾葛」的意思。他跟月亮、影子的關係最單純——不會背叛他、不會攻擊他、不會嘲笑他。這才是太白在長安真正需要的朋友：不用防備的朋友。

這首詩流傳一千兩百年最動人的地方，不是「舉杯邀明月」有多浪漫，而是它揭穿了一個秘密——豪放的人，往往是最孤獨的人。

太白不是不能社交。他能寫〈將進酒〉那種一群人狂喝的場面。但他心裡最深的那個地方，其實在夜裡自己跟影子跳舞。

所以下次你一個人吃飯、一個人看電影、一個人在陽台喝酒的時候，你可以想想：那個號稱一輩子豪飲的太白，也曾經一個人在花園裡跟自己的影子玩到天亮。

孤獨不是缺陷，孤獨是有些人天生就帶著的東西。太白讓它變成了詩。`
  },

  // id=17 盛唐 李白 〈子夜四時歌(秋歌)〉rating=6
  // 詩眼：李白替千萬個等丈夫回家的女人代言
  // 隱藏連接：唐代戍邊制度下的搗衣風俗
  17: {
    title: "子夜四時歌(秋歌)",
    author: "李白",
    summary: "李白一輩子寫盡自己的豪放與孤獨——但這首詩他把筆讓給了長安千萬個等丈夫回家的女人。",
    story: `跟你說我朋友太白一個少見的溫柔面。你以為他只會寫「將進酒」的自我抒發、寫「月下獨酌」的個人孤獨，但這首〈子夜四時歌〉的秋歌，是他把筆借給了別人。

他借給了誰？——長安城裡千千萬萬個丈夫在邊疆打仗、每晚在家裡搗衣的女人。

背景是這樣。盛唐時期，唐朝跟吐蕃、突厥、契丹、南詔各處都有戰事。玉門關以西的西域、青海邊上的隴右，都駐紮著大量唐軍。這些士兵絕大多數不是自願參軍，是府兵制下被徵發的——他們家裡有妻子、有小孩、有父母。

一去就是幾年，甚至十幾年。

而長安的女人們，每年秋天要做一件事：搗衣。什麼是搗衣？把厚重的布料放在石頭上，用木杵反覆敲打，讓布變得柔軟，然後縫製成棉衣，寄給邊疆的丈夫過冬。這是唐朝婦女每年秋天的集體儀式。

太白某一年秋天在長安，某個夜晚聽見了。

那晚他大概剛從朋友家喝完酒回來。走到某條巷子裡，他忽然聽見——不是一戶人家的搗衣聲，是幾十戶。他停下腳步。他往前走了幾步，又聽見更多。整條巷子、整片街坊，全部都在搗衣。

他抬頭看月亮。長安上空一片月光。他往四周看——所有的燈都亮著。他知道每一戶燈光下，都有一個女人手裡拿著木杵，一下一下地敲布。

咚。咚。咚。咚。

那是一整座城市的思念，變成了物理上的節奏。

秋風從長安北邊吹過來。太白站在巷子裡，忽然明白這風怎麼吹都吹不走這些搗衣聲——因為那不是聲音，是心情。是玉門關那邊的丈夫。是每一個女人心裡想著的那個「良人」。

「良人」這個詞是漢代以來妻子稱呼丈夫的敬稱，帶著「我的好人」的意思。

他回家寫下六句話：

長安一片月，萬戶擣衣聲。秋風吹不盡，總是玉關情。何日平胡虜，良人罷遠征。

太白在這裡放棄了他一貫的華麗風格，用了最樸素的字眼——因為他知道，這些搗衣的女人講不出華麗的話。她們只會告訴你：風一直在吹，我一直在想他。

這首詩沒有一句抱怨朝廷。沒有一句反戰的口號。它就是把一個等丈夫回家的女人心裡的話老實寫下來——我不在乎政治，我只想我的良人回家。

這才是太白這首詩最厲害的地方。他這個一輩子想當官、想被玄宗重用、想「立功邊塞」的男子漢，居然能寫出這麼柔軟、這麼女性視角的詩。

盛唐邊塞詩大部分是男人寫給男人看的——豪邁、雄壯、想建功立業。而太白這首，是他站到了千萬女人的立場，替她們問了一句：這一切到底是為了什麼？

有意思的是，太白晚年五十五歲時被永王事件牽連流放夜郎，走到半路遇赦。他這一生也體會過「有家歸不得」的感覺。也許他在長安寫下這首詩的時候，還沒真正懂那些搗衣女人的心情——但十幾年後，他懂了。

「長安一片月，萬戶擣衣聲」——這十個字，是太白替一整個唐朝的沉默女性寫的墓誌銘。

千年後我們讀它，還能聽見月光底下那一整夜的敲打聲。`
  },

  // id=55 初唐 陳子昂 〈登幽州臺歌〉rating=6
  // 詩眼：把懷才不遇寫到時空的盡頭——燕昭王那樣的伯樂前無古人後無來者
  // 隱藏連接：他在武攸宜軍中被貶為軍曹的敗退心情
  55: {
    title: "登幽州臺歌",
    author: "陳子昂",
    summary: "他只有二十二個字，把「懷才不遇」寫到時空的盡頭——不是抱怨當代老闆瞎，是抱怨整個歷史都沒有識貨的人。",
    story: `跟你說一個把「懷才不遇」寫到極致的故事。這首詩只有二十二個字，卻是整個唐朝最悲的一首詩之一。

主角陳子昂，四川射洪人。他早年是紈褲子弟，十八歲才開始讀書，二十五歲考中進士。他是「唐詩詩祖」——就是他第一個站出來反對當時流行的華麗宮廷詩風，主張回歸漢魏那種質樸剛健的文風。整個唐詩後來的方向，是他先破的局。

他為人也很剛。武則天當政的時候，他直言進諫過好幾次。有時候武則天很欣賞他，有時候把他晾在一邊。

六九六年（武則天萬歲通天元年），契丹叛亂，武則天派她的姪子武攸宜北伐。子昂被任命為隨軍記室（軍中文書），跟著出征。

武攸宜是個什麼人？紈褲、貴族、不懂軍事。純粹是靠武則天的關係當統帥。他一路北上，屢戰屢敗。子昂看不下去，多次向他獻策：先鋒失利了，我來帶一支奇兵包抄。武攸宜不理他。子昂再獻策，武攸宜煩了，把他從記室貶為軍曹——一個更小的官。

子昂完全被邊緣化。他坐在軍中無事可做，眼看著唐軍節節敗退，卻沒有一個人聽他的話。

這種心情，他決定去一個地方——幽州臺。

幽州臺是什麼地方？就是燕昭王當年築的「黃金臺」。戰國時代燕昭王為了招賢，在幽州（今北京附近）築了一座高臺，臺上放黃金千兩，號召天下有才之士來投靠他。結果他真的招到了樂毅、鄒衍、劇辛這些名將名士，把燕國從弱國變成強國。

黃金臺就是「識人之君」的象徵。

子昂在敗退的軍中，跑去登這座臺。他站在臺上，望著北方的荒野。

他往前看：眼前是空的。這裡是一千年前燕昭王築的臺，可是燕昭王早就死了。
他往後想：以後呢？這種懂得賞識人才的君主，還會再出現嗎？

他站在時間的正中央。前面沒有能收留他的人。後面也沒有。整片天地在他面前展開——那麼寬，那麼久，那麼冷。

他哭了。

不是那種嗚咽的哭。是一個中年男子突然覺得整個宇宙都沒有他的位置的那種哭。

他丟下四句話：

前不見古人，後不見來者。念天地之悠悠，獨愴然而涕下。

一般人的懷才不遇是：這個老闆看不見我，我換一家就好。
子昂的懷才不遇是：整個歷史上，能看見我的那種老闆，前無古人，後無來者。

「獨」這個字是全詩最重的一個字。整個天地間，只有他一個人在流淚。

這首詩只有二十二個字，沒有華麗詞藻，沒有典故堆疊——但它的氣魄大到什麼程度？大到後世公認：子昂這二十二個字，把整個「懷才不遇」的主題寫到了頂點，後人再寫都超不過他。

然後你猜他回長安之後怎樣？

他七〇〇年辭官回家。七〇二年，他所在地方的縣令段簡，看他家有錢，捏造罪名把他抓進監獄，把他關到憂憤而死。年僅四十一歲。

一個把「懷才不遇」寫到千古絕唱的人，最後死在一個小縣令的手上。命運沒有讓他遇到燕昭王，卻讓他遇到了段簡。

這才是為什麼〈登幽州臺歌〉會活這麼久。它不是文青的感嘆，它是一個真正被時代碾碎的人，站在傳說中「識人之君」築的臺上，對天地丟出的最後一聲哭喊。`
  },

  // id=60 盛唐 李白 〈宣州謝朓樓餞別校書叔雲〉rating=6
  // 詩眼：55歲從長安敗退10年後，中年失意的自我頓悟
  // 隱藏連接：他嘴上說「明朝散髮弄扁舟」，行動上沒有一天真的算了
  60: {
    title: "宣州謝朓樓餞別校書叔雲",
    author: "李白",
    summary: "一個從長安被踢出來的中年天才，在餞別酒桌上寫下史上最有力的「乾脆算了吧」——但你知道嗎，他沒真的算了。",
    story: `跟你說我朋友太白晚年的一天。他四十四歲被玄宗「賜金放還」——這四個字聽起來體面，其實就是「給你點錢，滾出長安」。他三年的翰林生涯結束，離開了他一輩子夢想過的那個地方。

之後十年，他到處漂泊。他五十五歲那年在宣州（今安徽宣城）遇到族叔李雲，族叔正好路過要走。太白替他辦了一場餞別酒，地點選在宣州最有名的地標——謝朓樓。

謝朓是誰？南朝齊的大詩人，太白的偶像級人物。太白這輩子提到謝朓次數多到誇張。他選在這棟樓餞別族叔，是有意思的。

那天酒喝到一半，他站起來就開始說話。第一句就狠——拋棄我而去的昨天，我留不住；讓我心煩的今天，煩得要死。

這是太白五十五歲的自我告白。昨天是什麼？是他長安三年、玄宗接見、貴妃研磨、力士脫靴的那個他。今天是什麼？是漂泊十年、事業無成、朋友死的死散的散、頭髮白了一半的他。

寫完自我抱怨，他抬頭看看窗外。宣州秋天，大風萬里，一群秋雁往南飛。他覺得——面對這樣的風景，值得在高樓上大醉一場。

這才是太白。就算酸也酸得有格局。

然後他讚美族叔的文章——你的文章有漢代蓬萊觀（東漢宮廷藏書處）的骨氣、有建安七子的風骨，加上南朝小謝（謝朓）的清新俊發。這是史上最高規格的稱讚。太白這個人不隨便誇人。他趁機也誇自己——我們兩個都懷著超凡的興致，想飛上天去把月亮抓下來。

寫到這裡氣氛正好。但下一句他突然筆鋒一轉，寫出了整首詩最有名的兩句。

拿刀砍水，水更流。舉杯澆愁，愁更愁。

十四個字的爆炸力在哪？它是純粹的物理比喻。沒有任何情感形容詞。就是告訴你兩個事實——水砍不斷，愁澆不掉。這種硬碰硬的比喻，比任何抒情都狠。

而這正是太白五十五歲的中年頓悟——他終於承認：長安失敗這件事，喝酒解決不了。

那怎麼辦？他給出了他的答案：人這輩子這麼不順意，明天就披頭散髮、划一條小船，隨便到哪去。

注意「明朝」兩個字。不是「今天就走」。是「明天再說吧」。

這正是這首詩最有意思的地方。太白說要放棄要出世，但他放到明天。今天他還要繼續喝，繼續跟族叔告別，繼續寫詩。他嘴上說算了，行動上一步都沒退。

他寫下的整首是：

棄我去者，昨日之日不可留。亂我心者，今日之日多煩憂。長風萬里送秋雁，對此可以酣高樓。蓬萊文章建安骨，中間小謝又清發。俱懷逸興壯思飛，欲上青天攬明月。抽刀斷水水更流，舉杯消愁愁更愁。人生在世不稱意，明朝散髮弄扁舟。

事實上，他這首詩寫完沒多久，就又跑去參加永王李璘的幕府（想再創政治事業），結果慘遭牽連流放夜郎。他從來沒有真的「明朝散髮弄扁舟」。他到死都在折騰。

但這句話變成了千古名句，因為它命中了每個中年人的心情——我知道自己該放下了，但真放下要等到明天再說。

太白的偉大就在這種矛盾。他既懂人生的無奈，又不肯認輸。他寫下抽刀斷水的時候，其實已經知道自己還會繼續拿刀砍水——但他還是要繼續砍下去。這才是太白。不是灑脫的仙人，是硬撐到底的凡人。`
  },

  // id=69 盛唐 李白 〈將進酒〉rating=6
  // 詩眼：被踢出去的中年天才在酒桌上的自我催眠
  // 隱藏連接：47歲在嵩山附近的一次醉酒，仕途已徹底玩完
  69: {
    title: "將進酒",
    author: "李白",
    summary: "史上最狂的勸酒詞——寫這首詩時他四十七歲，剛剛失業、口袋見底、頭髮開始白。他不是志得意滿在喊，他是硬撐著喊。",
    story: `跟你說我朋友太白最狂的一個下午。這年他四十七歲，跑到河南嵩山附近，去找兩個老朋友——道士元丹丘和隱士岑勳。地點是元丹丘在潁陽（今河南登封）的別業。

他這時候的處境不太好。四十四歲被玄宗賜金放還，離開長安，仕途已經玩完。老婆許氏過世了，跟第二任妻子劉氏處不好。遣散費也花得差不多了。四十七歲，頭髮白了一半，酒喝多了身體開始出狀況。

他到丹丘家坐下。丹丘擺出酒。三個中年男子開始喝。

太白喝了幾杯，開始說話。他先製造氣勢——你們有看過嗎？黃河的水從天上下來，一路奔到大海就不回來了。你們有看過嗎？高堂上的明鏡照著白頭髮，早上還是青絲，晚上就白了。

丹丘跟岑勳愣了一下。這開頭有點沉。

太白自己接下去——所以呢？人這輩子高興就要喝到底，別讓酒杯空對著月亮。

然後他喊出那句所有人都會念的話——老天既然生了我這樣有才華的人，一定會有用得上我的時候；錢花光了還會再有的。

你在他這個處境下聽他喊——就知道這不是志得意滿。他其實不確定自己還有用，也不知道錢還能不能再來。但他非要說。因為承認的那一秒他就完了。

他繼續喝。他叫兩個朋友——殺羊殺牛盡情快樂，喝就要喝三百杯。岑夫子、丹丘生，別停手。

到了中段他情緒更高——什麼富貴榮華我都不稀罕，我只想一直醉下去，不要醒過來。他這輩子從二十幾歲就往長安跑，就是想要富貴。現在他終於承認——那些我都得不到了，那我乾脆說我不要。

他還在喝。他喝到耍賴——主人你為什麼說錢不夠？現在就去買。我這匹五花寶馬，我這件千金貂裘，都叫小僕拿去換酒。

他把最後值錢的東西全丟出去換酒。

他寫下的是這首：

君不見黃河之水天上來，奔流到海不復回。君不見高堂明鏡悲白髮，朝如青絲暮成雪。人生得意須盡歡，莫使金樽空對月。天生我材必有用，千金散盡還復來。烹羊宰牛且為樂，會須一飲三百杯。岑夫子，丹丘生，將進酒，杯莫停。與君歌一曲，請君為我傾耳聽。鐘鼓饌玉不足貴，但願長醉不復醒。古來聖賢皆寂寞，惟有飲者留其名。陳王昔時宴平樂，斗酒十千恣歡謔。主人何為言少錢，徑須沽取對君酌。五花馬，千金裘，呼兒將出換美酒，與爾同銷萬古愁。

到最後五個字他終於承認——他心裡有一種萬古愁。前面所有豪言壯語都是在遮掩這一點。他寫完把筆放下。丹丘把他扶去睡了。

八年後他五十五歲，會因為跟錯永王被流放夜郎，走到白帝城遇赦。他這輩子沒等到「材必有用」的那一天。

但千年來每一個失意的中年男人在酒桌上喊出那句自我打氣的時候，太白都陪他們一起喊。`
  },

  // id=90 盛唐 岑參 〈白雪歌送武判官歸京〉rating=6
  // 詩眼：極寒邊塞送同事回京，把雪寫成千樹梨花的浪漫
  // 隱藏連接：他真的在西域待了 6 年，親歷者
  90: {
    title: "白雪歌送武判官歸京",
    author: "岑參",
    summary: "他站在冰天雪地送同事回京，明明心裡羨慕到不行——卻把邊塞的雪寫成了千樹萬樹的梨花。",
    story: `跟你說我朋友岑參一個冬天的下午。這年是七五〇年前後，他四十歲，在北庭（今新疆吉木薩爾）當節度使幕府的判官。他這輩子在西域待了整整六年——三十四歲那年跑去安西都護府當高仙芝的幕僚，四十歲又跑來北庭當封常清的判官。

那天是八月。在中原，八月還是夏天末尾。可是在北庭，八月已經下大雪了。

岑參的同事武判官任期滿了，要回長安。岑參替他送行。

那天早晨北風把地上的白草捲起。天上開始飛雪。岑參站在營帳外，看著漫天飛雪——很多雪堆在營帳的頂上、樹的枝椏上、牆的邊角上，白得像春天開滿花的梨樹。

他知道自己在騙自己。這是雪，不是花。但如果他不這樣看，這個冬天他怎麼撐得下去？

武判官要走了。他要回長安。長安的八月是槐花盛開、街道熱鬧、酒樓打烊晚。武判官回去以後就要重回那個溫暖的世界。而岑參呢？他還要繼續待在冰天雪地裡。

他心裡有點嫉妒。他把嫉妒藏起來，改成想像——長安太遠，我想像不到。可是這裡的雪，也可以是梨花。

他們進中軍大帳擺酒。胡琴、琵琶、羌笛都出動了。這是邊塞版的送別，沒有江南送別的紅袖楊柳，只有胡樂器的粗獷伴奏。狐皮大衣不夠暖，錦被覺得薄。將軍手抖得拉不開角弓。都護的鐵甲冷得穿不上。他們在這種天氣裡，硬是把送別席擺出來了。

酒喝完，天已經傍晚。雪紛紛落在轅門（大營門口）。風吹著紅旗，可是旗子已經被凍到無法翻動。

岑參送武判官到輪臺的東門。武判官上馬，往東走。雪蓋滿了天山的路。岑參站在原地看著他的馬隊。

山彎了、路轉了，武判官不見了。岑參能看見的最後一樣東西，是雪地上留下的馬蹄的印子。他知道那些印子會被下一場雪覆蓋。然後這個朋友就跟他徹底斷了。

而岑參呢？他還要繼續留下來。

他回營帳，寫下了這首詩：

北風捲地白草折，胡天八月即飛雪。忽如一夜春風來，千樹萬樹梨花開。散入珠簾濕羅幕，狐裘不暖錦衾薄。將軍角弓不得控，都護鐵衣冷難著。瀚海闌干百丈冰，愁雲慘澹萬里凝。中軍置酒飲歸客，胡琴琵琶與羌笛。紛紛暮雪下轅門，風掣紅旗凍不翻。輪臺東門送君去，去時雪滿天山路。山迴路轉不見君，雪上空留馬行處。

千年後，每一個在寒冷異地送同事回家的人，都能懂他的心情——你走了，我還要留下來。但至少，我要把這場送別寫得好看。`
  },

  // id=101 中唐 白居易 〈長恨歌〉rating=6
  // 詩眼：一場酒後即興命題變成唐朝愛情詩巔峰
  // 隱藏連接：白居易35歲在仙遊寺被朋友起鬨當場命題
  101: {
    title: "長恨歌",
    author: "白居易",
    summary: "一場酒後的即興命題變成唐朝愛情詩的巔峰——結尾兩句連天地都輸給了它的遺憾。",
    story: `跟你說我朋友樂天寫〈長恨歌〉真正的誕生故事。這首唐朝愛情詩第一名的長詩，不是樂天某個深夜靈感爆發寫的——是被朋友起鬨、當場逼出來的。

西元八〇六年，樂天三十五歲，剛從進士考試升為盩厔縣（今陝西周至）縣尉。有一天他跟兩個朋友——陳鴻（詩人兼小說家）和王質夫（他的地方朋友）——一起去附近的仙遊寺遊玩。

三個人喝酒聊天，聊著聊著就聊到五十年前的一件事：唐玄宗和楊貴妃。

五十年前的七五六年，安史之亂爆發，玄宗帶著楊貴妃逃往四川，走到馬嵬坡，禁軍嘩變，逼玄宗殺了楊貴妃。玄宗晚年回長安，再也沒能走出來——他在孤獨中活到七十八歲，鬱鬱而終。

三個人聊到這裡都沉默了。王質夫突然舉起酒杯說——這麼一段驚天動地的愛情故事，如果沒有一位大詩人把它寫下來，時間久了就會被人忘記。樂天，你這麼有才，你來寫。

樂天當場答應。他三十五歲，正值創作高峰。他回家花了幾天時間，一口氣寫完了八百四十個字、一百二十句的〈長恨歌〉。同時陳鴻也寫了一篇散文〈長恨歌傳〉配套。詩、傳一起流傳。

樂天寫的是這樣一個故事。楊貴妃入宮，一回頭一笑，整個後宮的美女都黯淡了。玄宗開始翹班，兩人在長生殿裡許下私下的誓言——在天願作比翼鳥，在地願為連理枝。

然後安史之亂爆發。禁軍嘩變，楊貴妃死在馬前。玄宗遮住臉救不了她，回頭一看，血和淚混在一起流。

戰爭結束，玄宗回長安。池子、宮殿、柳樹都沒變。每一片荷花都像她的臉，每一根柳條都像她的眉。他看到這些就哭。

他不甘心。他找了個道士，讓道士上天入地去找楊貴妃。道士在海外一座仙山上找到了她——她變成了仙女，住在一座叫「太真」的宮殿裡。楊貴妃把當年的信物拿出來交給道士，讓他轉告玄宗當年他們的誓言還在。

故事到這裡本該結束。樂天丟出了全詩最後一擊：

天長地久有時盡，此恨綿綿無絕期。

天地再長久也會有結束的時候，但這個遺憾永遠不會結束。

〈長恨歌〉一發布，長安轟動。從妓女到皇帝，人人都會背幾句。

有意思的是，樂天寫這首詩的時候三十五歲，還沒經歷過真正的失去。他寫的是一個五十年前別人的故事。但他預言了自己晚年的心情——他三十七歲那年，被母親逼著跟愛了十幾年的初戀湘靈永遠分手；他四十幾歲時女兒金鑾夭折。這些遺憾陪了他一輩子。

他寫〈長恨歌〉的時候，其實不知道自己已經寫好了自己人生的伏筆。`
  },

  // id=102 中唐 白居易 〈琵琶行并序〉rating=6
  // 詩眼：共享同一個黃金時代卻互不相識，多年後淪落成同一形狀
  // 隱藏連接：蝦蟆陵——白居易當年翰林學士夜出教坊可能在後排聽過她的琴
  102: {
    title: "琵琶行并序",
    author: "白居易",
    summary: "原來我們早就活過同一個長安——那時你在台上，我在台下，我們不曾說過一句話；多年後卻在千里外的江邊，變成同一種淪落人。",
    story: `跟你說個故事。元和十一年秋，樂天兄——白居易——被貶到江州快滿一年。這夜他到潯陽江頭送一位友人，酒喝到一半，江面上飄來一陣琵琶聲。琴聲一起，他愣住了。這手法，他熟。

當年他在長安當翰林學士，最愛跟朋友夜裡鑽進蝦蟆陵一帶的教坊聽曲。那時全城最紅的琵琶名家，是教坊第一部裡一位十三歲就學成、連老師善才都佩服的姑娘。五陵年少爭纏頭，一曲紅綃不知數——王公子弟為聽她一曲，紅綢絹帛丟得像不要錢。樂天兄擠在後排，遠遠聽過幾次，只覺得那琴聲能把整座長安的春夜彈進弦裡。

那時他從沒走上前去說一句話。他是天子倚重的青年官員；她是京城最耀眼的名伶。他們共享同一座長安、同一段盛世餘光，卻各在各的世界，互不打擾。

他吩咐邀琴聲主人過船。走出來的女子鬢邊已見霜色，她自述身世——本是京城女，家在蝦蟆陵下住。弟弟從軍去了，鴇母辭世，容顏一褪，車馬散盡，最後嫁給常年跑外地的商人。門前冷落鞍馬稀，老大嫁作商人婦。

樂天兄聽到「蝦蟆陵」三個字，心口重重一撞。原來是妳。原來我們曾經那麼近，卻誰也沒認出誰。

而他自己呢？當年直言觸怒權貴，如今從朝廷紅人淪落成江州司馬，門前也一樣冷清。兩條原本平行的黃金人生，此刻在江邊撞成同一個形狀。他一杯酒澆下去，脫口念出這句話：

同是天涯淪落人，相逢何必曾相識。

不必曾相識，是因為我們早就活過同一個長安。

那夜他寫下六百多字的長詩，末句「江州司馬青衫濕」。那件濕透的青衫，濕的不只是眼淚，還有整個回不去的開元舊夢。`
  },

  // id=105 初唐 王勃 〈送杜少府之任蜀州〉rating=6
  // 詩眼：22歲少年重寫送別詩公式——把哭哭啼啼改成豪邁擁抱
  // 隱藏連接：他26歲溺水而死，這句話成了他自己的預言
  105: {
    title: "送杜少府之任蜀州",
    author: "王勃",
    summary: "一個 22 歲的少年重寫了整個中國送別詩的公式——他把哭哭啼啼改成了「兄弟你去吧，我們永遠都在」。四年後他自己溺死在南海。",
    story: `跟你說我朋友子安的一個下午。這個人是「初唐四傑」之首，天才到什麼程度？六歲能寫文章，九歲讀《漢書》就寫了一本〈指瑕〉挑錯。他十七歲考中進士（唐代最年輕紀錄之一）。可是他這輩子只活了二十七年。

〈送杜少府之任蜀州〉大概寫在他二十出頭的時候，還在長安當官（沛王府侍讀）。他一個姓杜的朋友要被派到蜀州（今四川崇州）當縣尉。長安到蜀州，走山路，古代要走一個多月。這是一次很沉重的離別。

按照當時送別詩的傳統寫法，開頭應該是「執手相看淚眼」那種——哭哭啼啼、傷感低回。但王子安這個少年一開口就不一樣。

他先立地理格局：長安的城牆連接著三秦大地（關中），我望向蜀地五津（五個渡口）的方向，只看到一片風煙。

一開頭就氣勢磅礡。他把兩個人的離別放在整個中國的版圖上——不是情緒的私事，是天地的規模。

然後他寫下一個很妙的定義：我跟你的離別心情啊，都是「離家在外做官的人」。

「宦遊人」三個字很關鍵。子安在提醒對方（也在提醒自己）——我們都不是本地人，我們兩個都是遠離故鄉、在他鄉討生活的人。所以這次分離，其實跟我們平常的處境沒什麼不同——我們早就已經在漂泊了。

這個角度太漂亮。他把離別這件事重新定義：不是「原本在一起、現在分開」，而是「本來就都在流浪、只是流浪到不同的地方」。

然後他丟出全詩最狠的一句：

海內存知己，天涯若比鄰。

只要在這個世界上還有你這個知己，走到天涯海角也像住在隔壁。

這十個字是中國送別詩的一次革命。

在子安之前，送別詩的核心情緒是「捨不得」。子安這句更狠——他直接告訴朋友：你去哪都不會孤單。因為我這個朋友，會一直在。

這是把「地理距離」跟「情感距離」切開來的觀念。你走到多遠不重要，重要的是我心裡永遠有你的位子。

最後兩句他還嫌不夠豪邁，補一刀：不要在岔路口，像小孩子一樣哭得淚流滿面。

他寫下的整首是：

城闕輔三秦，風煙望五津。與君離別意，同是宦遊人。海內存知己，天涯若比鄰。無為在歧路，兒女共霑巾。

你知道為什麼這首詩的少年氣這麼重嗎？

因為子安寫這首詩的時候大概二十二歲。他還沒經歷過真正的挫折。他不知道他二十四歲會因為戲寫〈檄英王雞〉被唐高宗踢出王府；不知道他二十五歲會因為擅殺官奴差點被處死；不知道他二十六或二十七歲會在渡海去看被貶到越南的父親時，掉進海裡淹死。

他寫下「海內存知己，天涯若比鄰」的時候，還是那個二十二歲的少年天才——他以為朋友會永遠都在、以為分別只是暫時、以為自己有一輩子可以再見到杜少府。

但這句話變成了他這輩子的預言。他二十六歲那年真的走了「天涯」——他去越南看父親，在南海掉進海裡。杜少府從蜀州回長安時，可能還不知道子安已經死了。

天涯若比鄰——這句話變成了兩個朋友之間永遠沒兌現的約定。

有意思的是，這首詩因此活了下來。它變成了中國所有面對「朋友要遠行」的人的公式——不要哭，我們永遠都在。`
  },

  // id=116 盛唐 杜甫 〈春望〉rating=6
  // 詩眼：被困戰亂長安的父親對家人的擔心——「家書抵萬金」的焦慮
  // 隱藏連接：他妻兒在鄜州羌村，他被叛軍押回長安
  116: {
    title: "春望",
    author: "杜甫",
    summary: "一個四十五歲的父親被困在淪陷的長安，看著春天照常來——他不寫戰爭，只寫等一封收不到的家書。",
    story: `跟你說我朋友杜甫最沉的一個春天。這首「國破山河在，城春草木深」——不是他在寫景，是他在戰亂中被困、和家人失聯，一個人望著春天發呆時的心情實錄。

背景：西元七五六年安史之亂爆發後，唐玄宗逃蜀，長安淪陷。杜甫當時四十五歲，把妻子兒女安置在鄜州（今陝西富縣）羌村，自己隻身北上想投奔在靈武即位的唐肅宗。走到半路被叛軍抓住，押回長安。

他在長安被軟禁了近一年。這年春天，七五七年三月的某一天，他登上一座高處望向遠方——他妻子還在鄜州，他不知道她們是否還活著。

那天他站在長安一處小山丘上。他往北看——遠處是空的。他不知道妻子小孩此刻在做什麼。他往長安城裡看——去年冬天叛軍進城的時候燒殺搶掠的痕跡還在。宮殿沒人打理，草長得比人還高。街道上很少人走動。這座城已經不是他認識的長安了。

國家破了。但山還在原地，河還在流。天地並不因為政權崩塌而動搖。長安的春天照常到來，可是沒人再修剪那些草木。

他坐下來看花。他抬頭看鳥。他忽然發現自己想哭——看到花會流淚，聽到鳥叫都心驚。

杜甫這輩子最痛的事情是什麼？不是他仕途不順、不是他窮得吃不飽——是他最小的兒子在他被貶職期間餓死。那是他一輩子過不去的坎。此刻他還不知道那個悲劇即將發生。但他此刻在長安望著鄜州的方向，心裡的恐懼已經隱隱成形——如果我永遠回不去了，她們怎麼辦？

戰火已經燒了三個月。從去年冬天到今年春天，他沒收到過一封家書。他知道郵路斷絕，寫信也寄不出去。他想知道妻子有沒有東西吃、兒子有沒有生病、家裡的房子有沒有被燒。他每天等一封信，等不到。

他用手指梳了一下頭髮。又掉了一撮。他這半年來白頭髮已經多到自己都嚇一跳。這種焦慮不會讓人一夜白頭，但每天摸一下頭髮，就發現又少了一撮。他把頭髮綁起來，發現簪子插不住了——頭髮太少了。

他走回住處，寫下八句話：

國破山河在，城春草木深。感時花濺淚，恨別鳥驚心。烽火連三月，家書抵萬金。白頭搔更短，渾欲不勝簪。

「家書抵萬金」放到今天就是「等一則家人的訊息等到手發抖」的心情。這首詩沒有寫戰爭的殘酷（沒有屍體、沒有火光），它寫的是一個父親對家人的擔心。整首詩的核心情緒是這五個字。

正因為這樣，〈春望〉能穿越一千兩百年繼續讓人心痛。因為所有時代都會有戰爭，所有戰爭中都有一個焦急的父親，數著頭髮等一封收不到的信。`
  },

  // id=119 盛唐 杜甫 〈月夜憶舍弟〉rating=6
  // 詩眼：戰亂中兄弟散在四方——秦州失眠夜
  // 隱藏連接：他有四個弟弟，三個生死不明
  119: {
    title: "月夜憶舍弟",
    author: "杜甫",
    summary: "他有四個弟弟，戰亂把他們散到四方——一個人在秦州的月夜，他寫下所有分離兄弟共通的一句話：月是故鄉明。",
    story: `跟你說杜甫另一個很少人講的痛。他有四個弟弟——杜穎、杜觀、杜豐、杜占。安史之亂把他們散到四個方向。

杜甫本人在秦州（今甘肅天水），杜占跟著他；杜穎在山東；杜觀在河南；杜豐不知去向。杜甫每天擔心他們是死是活。

七五九年（乾元二年）秋天，杜甫剛剛丟了華州司功參軍的官職（因為替房琯說話得罪肅宗），棄官帶家人西行到秦州。這是他一生最狼狽的時期之一——沒工作、沒錢、四個弟弟三個生死不明。

某個秋夜他睡不著，走出屋子看月亮。

秦州城外的邊塞戍樓打了鼓，宵禁開始，路上沒人。這種鼓聲杜甫小時候在中原沒聽過——秦州靠近吐蕃邊境，每天都要打戍鼓提醒防禦。他站在院子裡聽這個鼓聲，就覺得自己離家真遠了。

天上一隻大雁飛過。傳統上大雁是一群飛的。一隻孤單的雁，代表著失群、失散、失去同伴。他站在秋夜的院子裡，看著那隻雁，忽然想到——這一天正是白露節氣。從今夜開始，露水變白（凝結）。

他抬頭看月亮。同一個月亮。可是他此刻在秦州，家人分散在幾千里外。他忽然覺得——故鄉的月亮比較亮。

你有沒有想過為什麼「故鄉的月亮特別亮」？明明月亮是同一個。但每個離家的人都會覺得——故鄉的月光有某種特別的溫度。因為記憶會替它加濾鏡。你小時候在院子裡看的月亮、跟兄弟一起在屋簷下聽故事的月亮、母親抱著你哄睡的月亮——那個月亮永遠比異鄉的月亮亮。

杜甫用五個字把這種普世的錯覺定格。

他繼續想弟弟們。他的弟弟被戰亂散開了。故鄉洛陽附近已經被叛軍占領，親戚朋友四散。他連能問他們死活的家都沒有了。他也不是沒試過寄信——他寄了。但戰亂中郵路斷絕，信寄出去沒有回音。而且這場戰爭還沒完——七五六年開始，到這一年七五九年已經打了三年了，還看不到頭。

他坐在秋夜的院子裡，寫下八句話：

戍鼓斷人行，邊秋一雁聲。露從今夜白，月是故鄉明。有弟皆分散，無家問死生。寄書長不達，況乃未休兵。

「無家問死生」——這五個字是最狠的。他不是說「聯絡不上」，是說「我連可以打聽的地方都沒有」。

這首詩不是壯麗的悲劇，是日常的焦慮。杜甫沒有寫「弟弟們是不是被殺了」這種極端想像，他寫「我連可以問的地方都沒有」——是那種比較低頻但持續發作的無助感。

有意思的是——這首詩寫下三年後，杜甫在四川終於見到了三弟杜觀。兄弟重逢，恍如隔世。而杜穎、杜豐、杜占，他有生之年沒能再見。

杜甫這輩子把「兄弟情」寫得極深。他不像李白那樣寫「天生我材必有用」的自我讚美，他寫的是一個大哥對弟弟的擔心、一個父親對孩子的愧疚、一個中年男子對家人的責任。

他的偉大不在天才，在溫度。`
  },

  // id=123 盛唐 杜甫 〈旅夜書懷〉rating=6
  // 詩眼：54歲的杜甫在江上獨舟寫下對自己一輩子的判決
  // 隱藏連接：嚴武剛病逝、他失去成都草堂的靠山
  123: {
    title: "旅夜書懷",
    author: "杜甫",
    summary: "五十四歲的杜甫在江上一葉小舟，寫下他這輩子最悲的自我評價——但這首詩本身，就是他錯了的證明。",
    story: `跟你說杜甫晚年最沉的一個夜晚。這是他五十四歲那年，時間是七六五年，地點是長江上。

背景是這樣。杜甫從七五九年開始住成都，靠好友嚴武的照顧過了幾年相對安穩的日子——就是我們課本讀到的「成都草堂」時期。他寫下〈春夜喜雨〉、〈茅屋為秋風所破歌〉、〈聞官軍收河南河北〉，都在這段時間。

但七六五年四月，嚴武突然病逝。杜甫失去了唯一的靠山。他無法繼續留在成都，只能收拾家當、帶著妻兒老小坐船東下，準備投奔別的親友。

那天晚上他的船停在長江上某個地方（一說在渝州忠州之間）。一家人擠在小船上睡覺。他一個人睡不著，走到船頭。

江岸邊細細的草被微風吹著。他抬頭看船——高聳的桅杆下是一葉夜晚的孤舟。整條江上只有他這一條船。所有家人都睡了，只有他醒著。

他抬頭看天。星星低低地掛在天上，像要垂下來——因為船在江上四面都是空曠，沒有房舍樹木遮擋，所以星星看起來特別低。大地一望無際。月亮從江面湧出來，月光在江水上跳動、反射，像從水裡冒出來。長江一直向前流去。

他覺得整個天地那麼大，他自己那麼小。

他問自己——我這輩子算什麼？

他一輩子想做的事情是當官、報效國家、為民請命。他從二十四歲就想考進士，考不上；三十幾歲被權相李林甫用「野無遺賢」的鬼話全部刷掉；四十幾歲當左拾遺，因替房琯說話得罪肅宗被貶；五十歲當工部員外郎，做了兩年因為戰亂又棄官。

他這輩子想以政績留名，結果政績為零。他寫詩只是隨手記錄，可是偏偏詩寫得太好，反而以詩留名。這不是他要的。

他從船頭回船艙拿了紙筆，坐下來寫下八句話：

細草微風岸，危檣獨夜舟。星垂平野闊，月湧大江流。名豈文章著，官應老病休。飄飄何所似，天地一沙鷗。

他把自己這輩子總結成一個畫面——天地那麼大，我就是那隻在江邊飛來飛去、找不到停靠地方的沙鷗。

他不知道自己還剩五年壽命。他不知道自己會在五十九歲客死湘江舟中，寫詩寫到一半就死了。他只是在這個江上的夜晚，看著月亮從水裡湧出來，突然覺得——我這輩子沒做到我想做的。

可是他寫下的這首詩本身，就是他錯了的證明。他嫌自己以文章留名，可他的文章讓他的名字活了一千兩百年。他嫌自己是天地間的沙鷗，可那隻沙鷗飛過的軌跡，變成了所有中年失意者的地圖。

一個人如果能把自己的失敗寫成〈旅夜書懷〉，那他其實已經贏了。只是他自己不知道。`
  },

  // id=134 盛唐 王維 〈終南別業〉rating=6
  // 詩眼：中年後半官半隱的自在——走到路盡頭就地坐下看雲
  // 隱藏連接：王維安史之亂後的「半官半隱」新生活模式
  134: {
    title: "終南別業",
    author: "王維",
    summary: "一個 40 歲後選擇半官半隱的中年人——走到路盡頭他不折返，他坐下來看雲。這是他給所有卡關的人的處方。",
    story: `跟你說我朋友摩詰中年後的活法。這個人早年野心很大，二十一歲進士及第，一路做官。但他四十歲以後開始改變。

轉折點是他母親的信佛影響加上安史之亂的衝擊——他被叛軍抓住強迫當偽官，戰後幾乎被處死。撿回一條命之後，他徹底看透了官場。他做了一個非常特別的決定——半官半隱。

他在藍田輞川買下一處別業（前朝詩人宋之問的舊居），叫「輞川別業」。有空就跑去山裡住幾天，官場的事該做就做。他不辭官，也不當官迷。他找到了一種平衡。

〈終南別業〉就寫在這個時期，大概他五十幾歲。

某天早晨他忽然想去山裡走走。他沒約朋友、沒帶書童、沒帶行囊。他就一個人往南山邊走。

他想去就去，不揪朋友、不跟人約。遇到好風景、好事情，就自己一個人知道。這是摩詰的核心。他不是不能社交，但他享受一個人的時間。他選擇「空自知」——不分享、不炫耀、不記錄。只有他自己看見的那個瞬間，就足夠了。

那天他在山裡隨便走。沿著一條小溪走。溪水越來越細，走到最後——沒了。他到了「水窮處」。

一般人到了這裡會怎樣？折返、抱怨、後悔沒帶地圖。

摩詰的動作是什麼？坐下來。就地坐下來。抬頭看天。剛好看到山上的雲正在升起。

這是一種活法的宣言。當你的路走不通了，不要急著找下一條路。就坐下來。你會發現有些東西正在別的地方升起——比如那朵雲。你以為自己是走到絕境，其實是命運剛好安排你在對的時間、對的位子，看到雲。

這是摩詰五十幾歲才學會的東西。他年輕的時候可不是這樣。他二十一歲進士及第，二十六歲被貶為濟州司倉參軍（因為他署衙的伶人違禁演出黃獅子舞牽連），他當時非常鬱悶。他寫過很多年輕時的憤懣詩。

但活到中年之後他悟出來——走不通，就坐下看看。

他坐在山溪盡頭。過了不知道多久，一個老人走過來——一個砍柴的山民。兩人打了招呼，聊起來。聊到什麼笑了、聊到什麼嘆息了、聊到太陽開始下山他還沒想要回家。

他不刻意找人聊天，但遇到就好好聊；他不設定回家時間，聊到高興就繼續聊。這是一種「不強求」的自由。

他回家寫下八句話：

中歲頗好道，晚家南山陲。興來每獨往，勝事空自知。行到水窮處，坐看雲起時。偶然值林叟，談笑無還期。

「行到水窮處，坐看雲起時」——這十個字是整首詩的靈魂，也是摩詰給所有卡關的人的處方。

年輕時我們追求「計畫」——每一步都要有目的、每一段時間都要有產出、每一次出門都要有收穫。

摩詰告訴我們另一種可能——你可以只是走走，走到路盡頭就坐下，遇到誰就聊聊，忘了回家時間也沒關係。

在中國人生哲學裡，「行到水窮處，坐看雲起時」幾乎變成了「絕處逢生」的另一種說法。但它比「絕處逢生」更平和——它不是說「絕境會變成生機」，它是說「絕境本身沒什麼好慌的，坐下來就是了」。

下次你在人生某條路上走不通了，別急。就地坐下。看看四周有沒有雲正在升起。`
  },

  // id=145 中唐 白居易 〈賦得古原草送別〉rating=6
  // 詩眼：15歲少年的作文練習，寫出千年來最強的生命力宣言
  // 隱藏連接：顧況「長安米貴，居大不易」的典故
  145: {
    title: "賦得古原草送別",
    author: "白居易",
    summary: "一個十五歲少年的作文練習，居然一口氣寫出中國文學史上最強的生命力宣言——野火燒不盡，春風吹又生。",
    story: `跟你說白居易少年時代的爆炸性表現。這首所有人都會背的〈賦得古原草送別〉——是他十五或十六歲寫的一次作文練習。

背景是這樣。唐代讀書人考科舉之前，會找機會拿自己的作品拜訪長安名士，希望對方推薦——這叫「行卷」。白居易十五歲那年帶著詩到長安，去拜訪當時的文壇大老顧況（歌詩四友之一，中唐名詩人）。

顧況看了他的名帖，看到「白居易」三個字，開玩笑說——長安米價這麼貴，居大不易啊！你這個叫「居易」的年輕人，長安可不容易住下來。

樂天把詩集拿給他看。顧況翻開第一首，就是這首。他讀到中段——愣住了。他把玩笑話收回去，對樂天說：有句如此，居天下亦不難！——你能寫出這種句子，別說長安，全天下你都住得下！

於是樂天一夕之間在長安傳開名字。這是他人生的第一次爆紅。而他當時只有十五歲。

那我們來看看這首詩到底在寫什麼。

「賦得古原草送別」是命題作文的規格。「賦得」二字表示題目是別人出的、規定要寫什麼。「古原」是古老的原野，「草」是主題，「送別」是情境。這是唐代科舉的典型題型。

樂天寫的內容是這樣：原野上茂盛的草，一年枯一次、榮一次。野火可以把整片草原燒光。但草的根還在土裡。春風一吹，草又長出來。

「野火燒不盡，春風吹又生」——這十個字是全詩靈魂。

為什麼這句話這麼有力？因為它是關於「毀滅不了的東西」。不管你怎麼燒、怎麼砍、怎麼踩，只要根還在土裡，草就會回來。這是自然界最頑強的生命力宣言。

一個十五歲的少年為什麼能寫出這種句子？大概是因為他還不知道人生的複雜。他只是誠實地寫了他看見的草。少年的力量就在這裡——沒有雜念，只有本能的感受。

後世讀者把這句話用在各種場合——革命者拿來鼓勵自己不會被鎮壓、失戀的人拿來安慰自己會恢復、生病的人拿來相信自己會好、失敗的創業者拿來說服自己再來一次。

一句十五歲少年的作文，變成了千年來所有「不肯認輸」的人的口號。

然後畫面拉開。遠處的芳草蔓延到古老的道路，晴天的翠色連接著荒廢的城牆。他把草的生命力放在整個時空的規模裡——朝代會過去（荒城）、道路會斷（古道），但草還在。

最後他把「送別」的題目扣回來——又要送朋友（王孫）離開了，茂盛的草充滿了離別的情感。

他寫下的整首是：

離離原上草，一歲一枯榮。野火燒不盡，春風吹又生。遠芳侵古道，晴翠接荒城。又送王孫去，萋萋滿別情。

他想告訴朋友什麼？——你走吧，路上有草陪你。他把草變成了朋友之間的媒介。不管你走到哪裡的古道、哪座荒城，只要春天來，草會替我陪你走。

這首詩把「送別」這個古老的題目，寫出了新意。別人的送別詩寫「不捨」，樂天寫的是「不用不捨」——因為有些東西不會離開。

草不會離開。生命力不會離開。只要根還在，一切都會回來。`
  },

  // id=192 盛唐 杜甫 〈蜀相〉rating=6
  // 詩眼：一個失意者在武侯祠拜見另一個時代的失意者
  // 隱藏連接：48歲杜甫剛在成都草堂安頓下來
  192: {
    title: "蜀相",
    author: "杜甫",
    summary: "四十八歲的杜甫跑到成都武侯祠拜諸葛亮——兩個「盡了力還是輸了」的靈魂，隔了四百年在同一個祠堂裡對哭。",
    story: `跟你說杜甫最沉的一次拜見。這不是拜活人，是拜諸葛亮。

背景：西元七六〇年春天，杜甫四十八歲。他剛剛從流亡中安頓下來，在成都西郊浣花溪畔蓋了那間著名的「杜甫草堂」。安定下來之後，他做了一件事——他去成都武侯祠拜諸葛亮。

武侯祠是紀念諸葛亮的祠堂，就在成都。杜甫走進去。他想找丞相的祠堂在哪。走進錦官城外面，柏樹森森的地方——他知道就是這裡了。

武侯祠當時（現在也是）種了很多古柏。相傳其中一棵最老的是諸葛亮親手種的。柏樹象徵著長青、堅忍。杜甫進去看見這些老柏，就覺得——這裡住著一個不會被時間磨損的靈魂。

他往裡走。階前的碧草自顧自地綠著。樹葉裡的黃鸝白白地叫著好聽的聲音。

草綠得再美，諸葛亮看不到了。鳥叫得再好聽，諸葛亮聽不到了。這片武侯祠的春天，是沒有主人的春天。

杜甫寫這兩句的時候，心裡想的是什麼？——他自己。他也曾努力想做出一番事業，結果沒人在乎。他站在武侯祠裡，看見諸葛亮的春天沒有主人，突然覺得——我如果也走了，我的世界也是這樣白費一場。

他想起劉備三顧茅廬。想起諸葛亮輔佐劉備、劉禪兩朝，是一個老臣的忠心。

杜甫這輩子想遇到「三顧茅廬」的老闆。他找過玄宗、找過肅宗、找過房琯、找過嚴武。玄宗不理他；肅宗貶他；房琯敗了；嚴武是他唯一的靠山，但也很快就死了。他這輩子沒被「三顧」過一次。

寫完諸葛亮的功業，杜甫丟出全詩最重的一擊。

出師未捷身先死，長使英雄淚滿襟。

出兵北伐還沒成功，人就先死了。這是諸葛亮二三四年在五丈原病逝的事。他六出祁山，想恢復漢室，結果都失敗，最後在軍中病倒，死在戰場上。這件事讓後世所有的英雄，一想到就哭到滿襟濕透。

杜甫拜諸葛亮拜到最後，哭出來了。他哭的不只是諸葛亮，他哭的是所有「想做一件事、盡了一輩子的力、還是沒做到」的人。

這才是全詩真正的秘密。杜甫不是在寫諸葛亮，他是在寫自己想要的死法。

諸葛亮死得莊嚴——他一輩子為了一個目標奮鬥，直到最後一刻。他死在戰場上，做了他該做的事。

杜甫此刻在成都草堂，四十八歲，什麼事都沒成——但他知道，如果他也能像諸葛亮那樣，一輩子朝一個方向走，即使沒成功，也算是活過了。

「出師未捷身先死」——這是杜甫對自己一生的預言。他十年後客死在湘江船上，正在寫詩，還沒寫完就死了。他的「出師」就是他的詩，他的「未捷」就是這些詩要一千兩百年後才被真正認可。

他寫下的是這樣一首詩：

丞相祠堂何處尋，錦官城外柏森森。映階碧草自春色，隔葉黃鸝空好音。三顧頻煩天下計，兩朝開濟老臣心。出師未捷身先死，長使英雄淚滿襟。

它是兩個失意靈魂的跨時代對話。杜甫四百年後走進諸葛亮的祠堂，兩個人都懂彼此——盡了力，還是輸了；但盡了力這件事本身，就已經夠了。

這就是為什麼〈蜀相〉會活這麼久。它替所有「盡了力還是失敗」的人，寫下了一種尊嚴。輸沒關係，重要的是你有沒有出師過。`
  },

  // id=195 盛唐 杜甫 〈聞官軍收河南河北〉rating=6
  // 詩眼：杜甫一生唯一「不假掩飾的快樂」
  // 隱藏連接：52歲在梓州收到消息、他規劃的回家路線他沒真的走完
  195: {
    title: "聞官軍收河南河北",
    author: "杜甫",
    summary: "杜甫一輩子寫愁寫苦——但這首詩他一反常態，狂到把詩書亂捲、規劃回家路線。八年戰亂結束那個下午，他終於可以哭一場快樂的淚。",
    story: `跟你說杜甫這輩子最開心的一天。這個一輩子寫「感時花濺淚」、「白頭搔更短」、「安得廣廈千萬間」的悲情大詩人，其實有一首詩是快樂到失控的。

就是這首〈聞官軍收河南河北〉。

背景：西元七六三年春天。杜甫五十二歲，人在四川梓州（今三洲）。他這時候已經被戰亂折磨了八年——從七五五年安史之亂爆發，到現在。八年裡他被抓過、被貶過、幾乎餓死過、兒子病死過。

某一天他突然聽到一個消息——官軍收復了洛陽、鄴城（今河北臨漳）。安史之亂徹底結束了。

杜甫當場崩潰——不是傷心的崩潰，是快樂到不知道怎麼辦的崩潰。

四川這邊突然傳來收復薊北（幽州、河北）的消息，剛聽到的時候，眼淚已經流滿了衣裳。這是快樂的淚。他等了八年。八年裡他沒能等到；八年裡他曾經以為這輩子都回不了家了。此刻消息一到，身體先於腦子做出反應。

他轉頭看妻子和孩子。發現他們臉上的愁沒了。杜甫連自己家人平常臉上什麼表情都很清楚——他們一直在愁。此刻他們也聽到消息，愁散了。

他把自己的詩稿、書籍隨手亂捲——不是整齊收拾，是隨便一捲塞著就想走。快樂到快要瘋了。

你能想像杜甫「喜欲狂」的樣子嗎？這個一輩子皺著眉頭寫詩的老頭，此刻站在自己家裡，把詩書亂捲亂塞，眼淚還沒乾——他要回家。

大白天要放聲歌唱、要盡情喝酒，帶著這個春天一起回家。這是不可思議的畫面。杜甫是個嚴肅、正經的儒生。他這輩子沒有在大白天放聲歌唱過。但此刻他要唱。

寫到這裡杜甫的快樂還沒退。他開始規劃回家路線——從巴峽（今重慶奉節）出發，穿過巫峽（今湖北巴東），然後從襄陽（今湖北襄陽）出發，到洛陽（今河南洛陽）。

這句話是一個沒有停頓的地理連線。即、穿、下、向——四個動詞連著跑。杜甫在腦子裡把整條回家的路一次跑完。

他其實根本還沒出發。他人還在梓州（四川），消息才剛到。但他的心已經飛到洛陽了。這是想家想到極致的表現。一個八年沒回家的人，在聽到可以回家的第一秒，腦子裡就把整條路想過一遍。

他寫下的是這樣一首詩：

劍外忽傳收薊北，初聞涕淚滿衣裳。卻看妻子愁何在，漫卷詩書喜欲狂。白日放歌須縱酒，青春作伴好還鄉。即從巴峽穿巫峽，便下襄陽向洛陽。

這是杜甫一生唯一一次「不假掩飾的快樂」。這個大詩人一輩子寫了那麼多悲愴的詩，我們差點忘了他也會快樂。他不只是苦難的紀錄者，他也是一個渴望回家的普通中年男子。

但你知道最傷的一件事嗎？——他沒有真的回到洛陽。

寫完這首詩之後，杜甫的生活還是很糟。他繼續在四川、湖北、湖南之間漂泊。他五十九歲那年，還在往洛陽的路上，死在了湘江的一條船上。

他這輩子沒能執行完「即從巴峽穿巫峽，便下襄陽向洛陽」的規劃。

這才是這首詩最深的重量。一個快樂到規劃回家路線的人，最後死在半路上。那份快樂變成了他這輩子最珍貴的一次「未完成的希望」。

但這首詩留下來了。它告訴後世——杜甫也快樂過。哪怕只有這一個下午。哪怕最後回不去。`
  },

  // id=209 盛唐 崔顥 〈黃鶴樓〉rating=6
  // 詩眼：過客在傳說的樓上突然被打敗——連李白都封筆
  // 隱藏連接：李白〈登金陵鳳凰台〉是模仿它的對打作
  209: {
    title: "黃鶴樓",
    author: "崔顥",
    summary: "唯一一首讓李白封筆的詩。李白登樓時看到它，只留下一句「眼前有景道不得，崔顥題詩在上頭」。",
    story: `跟你說唐詩史上最傳奇的一次「認輸」。故事的主角有兩個——崔顥、李白。

崔顥（七〇四到七五四）在唐代詩人裡不算超一線。他早年寫詩風格輕薄，被人評價「有俊才，無士行」——才華有，人品差。但他中年後生活閱歷豐富了，詩風大變。〈黃鶴樓〉就是他中年後的代表作，大約寫在他遊江夏（今武漢）時。

黃鶴樓在武昌長江邊，傳說古時候有仙人騎黃鶴從這裡飛走。崔顥登上去，站在樓上。

他看四周。傳說中的黃鶴走了，只剩下一座空樓。天上白雲飄了一千年，也是空的。他覺得整個世界都是「一直在等、一直沒等到」的空。

他往遠處望。晴朗的天空下，漢陽的樹木清晰可見；江中鸚鵡洲上，芳草茂盛。這片實景讓他愣了兩秒——原來這裡的長江不空，那些樹、那座洲都在自顧自地活。

太陽下山了。他問自己——我的家鄉在哪裡？

他知道自己家鄉在哪。他就是不明白，為什麼站在別人的傳說樓上、看見別人的城市，他自己的家鄉突然變得那麼遙遠。江上一片煙波。他愁得說不出話。

他下樓的時候寫下這首詩：

昔人已乘黃鶴去，此地空餘黃鶴樓。黃鶴一去不復返，白雲千載空悠悠。晴川歷歷漢陽樹，芳草萋萋鸚鵡洲。日暮鄉關何處是，煙波江上使人愁。

然後我要跟你說另一半故事。

多年後，李白也登過黃鶴樓。李白你認識——那個「白髮三千丈」、「黃河之水天上來」的狂人。他站在樓上準備寫詩，這是他一輩子最擅長做的事。

結果他抬頭看見牆上有詩——崔顥留下的這首。李白讀完，把筆放下了。

他說了一句傳世的話——眼前有景道不得，崔顥題詩在上頭。眼前的景色我寫不出來，因為崔顥已經在牆上寫過了。

這是李白一輩子唯一一次公開承認——有人的詩比他強。

李白為什麼服氣？因為崔顥用他最擅長的招式，把他自己打敗了。李白最會寫時空的巨大感——黃河之水從天上來、白髮三千丈。崔顥這首：昔人、千載、日暮——時間拉到極致；空餘、鄉關、煙波——空間拉到極致。李白一看，覺得這個崔顥用的是他的招式，卻寫得更好。

他離開黃鶴樓沒有寫詩。可是他不甘心。他後來寫了一首〈登金陵鳳凰台〉，明顯是模仿崔顥的結構在跟他對打。這首詩寫得也很好，但後世公認——李白這次還是輸了。

崔顥留下的這首詩不到六十個字。它讓一個過客的鄉愁固定在了長江邊的樓上。李白也曾試著搬走它，可他搬不動。`
  },

  // id=234 晚唐 李商隱 〈錦瑟〉rating=6
  // 詩眼：當時已惘然——清醒時就抓不住的絕望
  // 隱藏連接：錦瑟是王氏遺物；五十弦對應46歲快50的年齡
  234: {
    title: "錦瑟",
    author: "李商隱",
    summary: "唐詩史上最神祕的一首詩——一千兩百年來所有註家吵翻。而答案早就在他自己寫下的五個字：當時已惘然。",
    story: `跟你說我朋友義山最後的一個冬天。洛陽的家，一間光線不多的書房。桌上放著一把落了灰的錦瑟。他伸手用袖子擦了一下——這把瑟，七年沒人彈了。

彈這把瑟的人叫王氏，是他的妻子。義山這輩子官不大、錢不多、心情少晴，家裡卻因為有她一個人在等，變成了唯一像樣的地方。大中五年她病逝，那年義山三十九歲。之後他一個人養兒子、輾轉幕府、寫詩越寫越美，也越寫越少人看得懂。

他這輩子活得像個夾心餅。年少時被恩師令狐楚提拔中進士，令狐家是牛黨；後來他娶了李黨王茂元的女兒，就是這位王氏。從此兩邊都不待見他。他一輩子做過最高的官叫「校書郎」——一個管校對別人書的小差事。整個晚唐最好的才華，只能拿去校對別人寫的爛書。

他今年四十六歲。牙開始鬆，人常常盯著空氣發呆。他知道自己時候不多。

他坐下來，看著這把積灰的錦瑟。傳說古時候的瑟本來五十根弦，帝王聽了太悲，才改成二十五。這把瑟是老規格。他用指腹輕輕撥了一下——啞的，弦鬆了。

他忽然想起很多事。想起二十幾歲在玉陽山學道時，有一位女道士讓他寫過這輩子沒再寫過的詩。想起結婚那年他從桂林幕府趕回長安，王氏還沒卸去釵子就在門口等他。想起兒子出生那天，他抱著孩子在庭院走了很久，聽見瑟聲從屋裡飄出來。

那些事都不算舊。可是他發現一件殘忍的事——在那些事發生的當下，他就已經隱隱知道自己抓不住。年輕時的夢像莊子夢見的那隻蝴蝶，醒了就再也回不去。王氏彈瑟的夜晚，他坐在旁邊聽，月光從紙窗照進來，落在她鬢邊的珠釵上，他心裡就有一個聲音說——這種好日子不會久。這種悲，不是後來才生的。當時就在了。

他提起筆，寫下八句話：

錦瑟無端五十弦，一弦一柱思華年。莊生曉夢迷蝴蝶，望帝春心託杜鵑。滄海月明珠有淚，藍田日暖玉生煙。此情可待成追憶，只是當時已惘然。

寫完他把筆放下。這是他晚年整理詩集時放在第一首的作品，用開頭兩個字當題目。他沒有解釋這首詩寫給誰、為什麼寫。他不需要。

幾個月後義山就病逝了，四十六歲。這首詩後來成了中國詩史上最難解的一首，一千兩百年來註家吵翻——有人說是悼亡，有人說是自傷，有人說是懷才不遇，有人說是他年少的暗戀。可是沒有一個註解能超過他自己寫下的那五個字：當時已惘然。

別再猜了。答案早就在他當時的眼睛裡。他一直都知道。他只是等了一輩子，才把這件事說出來。

錦瑟還在桌上。等下一個聽得懂的人來彈。`
  },

  // id=235 晚唐 李商隱 〈無題〉(昨夜星辰昨夜風) rating=6
  // 詩眼：一次無法承認的心動——桌上遊戲熱鬧，桌下心跳更響
  // 隱藏連接：「無題」等於不能公開的感情
  235: {
    title: "無題(昨夜星辰昨夜風)",
    author: "李商隱",
    summary: "一場熱鬧的酒宴上，一個男人與一個他不能公開喜歡的女人隔著酒桌對視——「心有靈犀一點通」的原始畫面沒你想的那麼浪漫，它其實非常克制。",
    story: `跟你說我朋友義山最會寫的一種詩——你以為是甜的，其實是苦的。

〈無題〉這個題目本身就是一個訊號。義山有將近二十首〈無題〉。他為什麼不敢給題目？因為題目一給，事就穿了。這些詩絕大多數寫的都是他不能公開說的感情——可能是他對某位女道士的暗戀（他年輕時在玉陽山學道，遇見過一位宋華陽），可能是他對已婚貴族女性的傾慕，可能是他對某個宴席上一面之緣的女子的難忘。

這首「昨夜星辰昨夜風」就是最典型的一例。

那晚義山在某位貴族家的酒宴上。宴席擺在畫樓的西邊、桂堂的東邊——他沒說是哪座樓，因為讀者根本不需要知道地址。他要說的是——我記得那個位置。

這種「記得座位」的心情，是所有暗戀過的人都懂的。你不記得那晚吃什麼、講什麼，你記得你坐在哪、她坐在哪。

宴席上他看見那個女子。她坐在他斜對面。他們對視過幾次，也許三次，也許四次。每一次都很短。每一次他都覺得對方眼神裡有什麼。可是他不能站起來走過去說話。

他沒有翅膀。他不能像彩鳳一樣飛過去、把她帶走。但他心裡跟她之間有種奇怪的連通——像犀牛角上那條白線，兩端能點對點感應。

這種比喻的殘忍在哪？「彩鳳雙飛翼」是顯性的、可以被看見的、可以公開飛給大家看的親密。他沒有。「靈犀一點通」是隱性的、只有兩人自己知道的、藏在心裡的默契。他有。

這是「無法公開的關係」的完美隱喻。

宴席上大家在玩遊戲。送鉤是把小鉤藏在手裡讓別人猜；射覆是用容器蓋住東西讓別人猜。這都是熱鬧、大家一起玩的遊戲。義山跟她玩不到一起。他隔著座位看她玩送鉤。他跟她分成不同組玩射覆。他們在同一個宴席上，但被物理隔開。

春酒溫暖，蠟燈紅豔，一切都熱鬧——只有他們兩個之間的距離冷冷地存在。

天亮了。他聽到早晨上朝的鼓聲。他必須離開這個宴席。他必須去上班。他不能像其他男客一樣留下來、跟這個女子多說幾句話。他被「應官」這件事逼走。

他騎馬去蘭台（他當時任職的秘書省）。他把自己比喻成被風吹的蓬草。這是義山一輩子的處境——沒有根、被吹到哪算哪、對重要的東西沒有選擇權。

他一路上寫下八句話：

昨夜星辰昨夜風，畫樓西畔桂堂東。身無彩鳳雙飛翼，心有靈犀一點通。隔座送鉤春酒暖，分曹射覆蠟燈紅。嗟余聽鼓應官去，走馬蘭台類轉蓬。

它是現代都市戀情的原型。

你有沒有在某個聚會、某個工作場合、某個社交場合遇到一個人，你們對視了幾秒，你知道你們之間有某種東西，但你沒辦法追下去——因為你必須回去工作、回去上班、回去你的責任裡？

義山一千兩百年前就寫過了。

昨夜星辰昨夜風——那個夜晚的位置我記得。心有靈犀一點通——我知道你懂。聽鼓應官去——但我必須走。

這是所有「無法追下去的感情」的公式。它不是失戀，它是沒發生過的戀愛。你連被拒絕都輪不到，因為你根本沒告白。

義山把這種心情固定住了。一千兩百年來每一個「心有靈犀但不能繼續」的人，都能借他的詩表達那份說不出口的東西。`
  },

  // id=240 晚唐 李商隱 〈無題〉(相見時難別亦難) rating=6
  // 詩眼：明知結局依然堅持——愛情不是選擇，是活著就得愛
  // 隱藏連接：春蠶蠟炬把愛情寫成生理現象
  240: {
    title: "無題(相見時難別亦難)",
    author: "李商隱",
    summary: "「春蠶到死絲方盡」——他把愛情寫得像一種病，一種你自願得的、明知會死於此的病。",
    story: `跟你說我朋友義山另一首〈無題〉。這首寫得比別的都沉，因為它是一種明知結局、依然堅持的感情。

背景我先說清楚——這首詩的對象是誰，一千兩百年來歷代學者吵翻。有人說是他年輕時在玉陽山學道時愛過的女道士宋華陽；有人說是某位地位高於他的貴族女子；有人說是他寫給多段不能公開的感情的總和。義山自己沒說。他把詩名叫「無題」，就是不想讓你確定是誰。

我猜是這樣一個場景。晚春某個晚上，義山一個人在書房。他剛剛從一個很短暫的見面回來——那個人他這輩子見不到幾次，因為某種阻礙（她已婚，或她是道士，或她住得遠），他們每次見面都像偷竊。今天他們見了，又要分開了。他坐下來點蠟燭寫詩。

他先寫兩人的處境——見面本來就已經很難，好不容易見到了，離別也很難。窗外的春天已經到了尾聲，東風吹著，可是花已經開始凋謝。

他看著蠟燭。蠟燭在燒，火焰旁邊蠟淚一直在流下來。他忽然想到自己——他這種感情就像這根蠟燭，要燒到全部變成灰，蠟淚才會停。也像春天養的蠶，要吐絲吐到死，絲才會停。

只要他還活著，他就會繼續愛。不是因為他選擇繼續愛，是因為除了愛他不知道怎麼做。

他放下筆，想像對方此刻在做什麼。早晨照鏡子的時候，她會不會擔心自己的鬢髮變老變白？晚上讀書的時候，她會不會覺得月光有點冷？他不能問她。他只能猜。

他想寫封信給她。可是他自己去不了她那裡——他形容那個距離像從人間到蓬萊仙山，說遠不遠，可他就是去不了。他只能想像有隻青鳥（傳說王母娘娘身邊的信使）替他跑腿。

他寫下的是這樣一首詩：

相見時難別亦難，東風無力百花殘。春蠶到死絲方盡，蠟炬成灰淚始乾。曉鏡但愁雲鬢改，夜吟應覺月光寒。蓬山此去無多路，青鳥殷勤為探看。

不知道對象是誰不重要。因為義山寫的其實不是某個具體的人，而是——「明知不會有結果，還是無法停止」的那種狀態。

你有沒有暗戀過一個不可能的人？你有沒有喜歡過一個明知不會回來的舊情人？你有沒有為一份工作、一個夢想、一個目標，明知希望渺茫還是無法放手？

那都是你人生中的春蠶絲跟蠟燭淚。

蠶不會知道自己為什麼要吐絲。蠟燭不會知道自己為什麼要流淚。義山不會知道自己為什麼要繼續愛一個得不到的人。但這不重要。活著就得愛。這就是義山的答案。`
  },

  // id=252 南宋 陸游 〈遊山西村〉rating=6
  // 詩眼：主戰派英雄被貶回鄉的第一個春天意外遇見的溫暖
  // 隱藏連接：42歲被罷官的低潮期
  252: {
    title: "遊山西村",
    author: "陸游",
    summary: "南宋主戰派英雄被貶回家鄉的第一個春天，走進一個山村，寫下所有卡關的人都需要的一句：山重水複疑無路，柳暗花明又一村。",
    story: `跟你說我朋友放翁一段特別暖的往事。這一年是南宋乾道二年（一一六六），四十二歲的陸放翁因為主戰言論太激烈，被朝廷罷官，回到家鄉紹興山陰。

四十二歲，正是壯年。他一輩子想收復北方，政治理想被砸碎，只能回鄉「賦閒」。他悶了整整一個冬天。

第二年春天，山陰下起了雨。他悶得再也待不下去，就出門走走。他往家鄉附近的山村走去。

他走到某個小山村。村民見到這個穿著文人袍子的中年男人，熱情地招待他。他們端出一壺自己家釀的臘月酒——酒有點渾濁，還沒過濾乾淨。放翁笑了。他知道這已經是山村最好的待客了。

村民又端出雞肉和豬肉。放翁一個人吃著這頓簡單的飯，忽然覺得——別看這酒渾濁、菜簡單，這已經是他這輩子少數幾次真正被善意招待的一頓。朝廷裡沒有這種。

他吃飽喝足，出門散步。在山裡走著走著。他繞了一大圈，一重山、又一重山、一條水、又一條水，突然覺得——是不是走錯了？前面沒路了？

正當他懷疑的時候，他抬頭。一片柳樹幽暗、一片花朵明豔的地方，居然出現了另一個村子。

放翁站在原地愣了兩秒。他想到自己——被朝廷罷官不是絕路，只是他還沒走到下一個村子。

他走進第二個村子。簫鼓聲一路跟著。快到春社日了——春社是唐宋時代春天祭土地神的日子，是農村最熱鬧的節日。整個村子的人在準備。

他跟這個村子的人聊。他說——以後我可以常來嗎？月色好的時候，我拄拐杖來敲你們的門，你們別嫌我煩。

他寫下的是這樣一首詩：

莫笑農家臘酒渾，豐年留客足雞豚。山重水複疑無路，柳暗花明又一村。簫鼓追隨春社近，衣冠簡樸古風存。從今若許閒乘月，拄杖無時夜叩門。

放翁後來果然繞出來了。他四十三歲之後又出仕、又寫詩、又活到八十五歲。他一輩子寫了九千多首詩，是中國史上寫詩最多的人之一。他八十五歲臨終前還寫下「王師北定中原日，家祭無忘告乃翁」——他到死都在等收復北方。

他四十二歲那個下午在山西村悟出來的道理，救了他一輩子——只要你繼續走，就會有下一個村子。`
  },

  // id=253 南宋 文天祥 〈過零丁洋〉rating=6
  // 詩眼：被俘的宰相寫下史上最有力的死亡宣言
  // 隱藏連接：張弘範逼他寫勸降信、他寫這首詩甩回去
  253: {
    title: "過零丁洋",
    author: "文天祥",
    summary: "南宋最後一位宰相被俘後押解北上——他在敵人的船上寫下一句話，讓忽必烈也無法逼他投降：人生自古誰無死，留取丹心照汗青。",
    story: `跟你說一個南宋末年的下午。一二七九年，宋朝已經完了，元軍統帥張弘範押著一個俘虜北上。這個俘虜叫文天祥，四十三歲，宋朝的右丞相，起兵勤王四年、每一場仗都輸，最後在潮州被抓。

船隊進入零丁洋——今天廣東珠江口外的伶仃洋。海面很大，往哪看都是水。

那天張弘範找文天祥。他要文天祥寫一封信。信要寄給還在崖山抵抗的宋軍統帥張世傑，勸他投降。張弘範拿出紙筆放在文天祥面前。

文天祥拿起筆。可是他沒寫勸降信。他寫了另一首詩，寫完把紙推回去。

那首詩他先回顧自己這輩子——二十一歲那年他考中狀元，那是他人生的高峰，也是他所有麻煩的開始。如果他沒那麼有才，他不會被朝廷倚重；如果他不被倚重，他不會在宋朝快垮的時候被推出來扛。從一二七五年他起兵勤王到今天，四年了，每一場仗都輸。

他寫下山河像被風吹散的柳絮，他自己像被雨打的浮萍。他寫惶恐灘——那是江西贛江上的一個險灘，他當年撤退時經過。他寫零丁洋——就是他此刻正被押解過的這片海。兩個地名剛好對應他人生兩段最慘的時刻。

寫到這裡，張弘範以為他要哭出來了。

可是文天祥抬起頭，寫下了最後一句。他寫——反正每個人都會死，不如死得能被史書記下來。

他寫下的是這樣一首詩：

辛苦遭逢起一經，干戈寥落四周星。山河破碎風飄絮，身世浮沉雨打萍。惶恐灘頭說惶恐，零丁洋裡歎零丁。人生自古誰無死，留取丹心照汗青。

他把紙推給張弘範。

張弘範看完，放棄勸降。他知道這個人不會投降。

但故事還沒完。文天祥被送到大都，關進監獄。忽必烈親自來勸降——只要你投降，宰相之位留給你。文天祥一句話回——我是大宋的狀元、大宋的宰相，只欠一死，其他免談。

忽必烈把他關了三年。三年裡什麼酷刑、什麼利誘都用過，都沒用。

一二八三年一月九日，忽必烈終於放棄，下令處決他。文天祥被押到大都柴市。臨刑前他問身邊的人——哪邊是南方？有人指了。他朝南方跪拜三次——那是南宋的方向。

然後他從容就義，四十七歲。

行刑之後，人們在他衣帶裡發現一段話——讀聖賢書，所學何事？而今而後，庶幾無愧。讀了一輩子聖賢書，就是為了這一刻。

他四年前在零丁洋船上寫下的那句話，用他自己的死兌現了。

一個人如果能讓自己寫的詩變成自己的墓誌銘，他就贏了時間。文天祥贏了。`
  },

  // id=263 盛唐 王維 〈鹿柴〉rating=6
  // 詩眼：極靜中的一聲——用聲音襯托空
  // 隱藏連接：輞川別業20景之一，跟裴迪各寫一首
  263: {
    title: "鹿柴",
    author: "王維",
    summary: "二十個字寫一片空山——王維示範了「靜到極致」的最高境界：不是沒有聲音，是有一個聲音，讓沒有的部分變得更明顯。",
    story: `跟你說我朋友摩詰最禪的一首詩。〈鹿柴〉——只有二十個字——但它是中國山水詩的最高境界。

「鹿柴」是摩詰的輞川別業裡的一個小景點的名字（「柴」念寨，是「柵欄」的意思，鹿柴＝養鹿的柵欄地）。他在這裡寫了很多小詩，這是其中一首。

那天下午他一個人在輞川散步。走到鹿柴附近。這裡幾乎沒人來。他站在鹿柴的柵欄邊看四周。

山裡空空的，看不到人。但——他忽然聽到遠處傳來人講話的聲音。

不是清楚的講話。是那種很遠很遠、隔著幾道山谷、模模糊糊的迴響。你聽得到有人在講話，但你聽不出他們在說什麼。

摩詰站住了。他忽然覺得——這個聲音才讓這座山「更空」。

你有沒有這種經驗？在一個很大的空間裡（大教堂、大峽谷、深山），你聽到遠處有人講話，那個聲音迴響、模糊、失真——你反而更覺得這個空間好大、好空。那個聲音不是「打破安靜」，是「證明安靜有多深」。

摩詰寫的就是這種感覺。他不寫「山很靜」——他寫「山有聲音」。但那個聲音，反而讓你聽出山有多靜。

他繼續往前走。太陽已經開始下山了。夕陽的餘光斜斜地從天空的一邊射過來，穿過整片樹林。

樹林很深。光正常來說是穿不進去的。可是這道夕陽的餘光找到了一個縫隙，穿進去，剛好照到地上一片青苔。

青苔是長在陰濕地方的東西。它平常曬不到太陽。而此刻，一道罕見的餘光找到它，照在上面。這個瞬間，青苔被鍍了金。

摩詰看見這個畫面，愣了兩秒。然後他繼續往前走。

回家之後他寫下二十個字：

空山不見人，但聞人語響。返景入深林，復照青苔上。

這二十個字寫了什麼？寫了一個「沒有主角」的畫面——空山，沒人。遠處的人聲，只是回音，不是「有人」。光是「返景」，不是「陽光」——是被反射的光，不是本體。青苔是被光照到的東西，不是照別人的東西。

這裡面每一個元素都是「間接的」、「殘餘的」、「被動的」。這就是摩詰的禪。他不寫大的、主要的、生命的東西，他寫餘光、回音、青苔。他要告訴你——世界最真實的部分，不是主角，是那些被主角遺漏的角落。

有意思的是，這首詩是摩詰〈輞川集〉二十首中的一首。他跟朋友裴迪一起寫，每人二十首，一人一首對應輞川別業的二十個景點。〈鹿柴〉是其中最著名的一首。

裴迪對應的〈鹿柴〉寫的是什麼？——很直白，很情感化。摩詰的〈鹿柴〉呢？——一個字都沒寫他自己。他把自己完全隱形了。

這就是摩詰與其他詩人的區別。李白寫詩「我」很多；杜甫寫詩「憂」很多；摩詰寫詩——「我」沒了。他變成了一個透明的觀察者，讓山、光、青苔自己說話。

這是禪宗「無我」在詩裡的完美體現。

它示範了一種「消失自己」的智慧。我們現代人習慣了自我表達、自我曝光、自我打卡。摩詰教我們另一種可能——你可以完全消失，讓風景自己說話。

當你消失了，你反而看見了更多。當你不說話了，你反而聽見了更多。當你不擋光了，你反而看見了那片被鍍金的青苔。`
  },

  // id=267 盛唐 王維 〈雜詩〉rating=6
  // 詩眼：一個問題比一百句抒情更痛——不敢問人，只敢問一棵樹
  // 隱藏連接：王維長期在長安為官，家鄉在山西蒲州
  267: {
    title: "雜詩",
    author: "王維",
    summary: "遇到來自故鄉的人，你會問什麼？王維只問了一個問題，卻寫出了千年來最真的鄉愁——來日綺窗前，寒梅著花未。",
    story: `跟你說我朋友摩詰一個下午的動作。

摩詰（王維）這輩子大部分時間在長安或洛陽當官。他家鄉是山西蒲州（今山西永濟）。他從二十一歲進士及第出仕就長期不在家鄉。

某一天他在長安街上走著，忽然聽見一個口音——是他家鄉的口音。他愣了一下，回頭看。那人衣著風塵，剛從遠處來。摩詰上前打招呼——你從哪裡來？

對方說——蒲州。

摩詰的呼吸停了半秒。他也是蒲州人。他趕忙問這個人——你是最近才離開的嗎？

對方點頭。摩詰急著開口，可是下一秒他愣住了。

他發現自己不知道該問什麼。

一般人會問——爸媽好嗎？弟弟妹妹怎樣？莊稼收成好嗎？村裡誰誰誰結婚沒？可是摩詰不敢問。你想想，如果你離家二十年，你遇到老鄉，你敢問「爸媽好嗎」嗎？——你怕聽到不好的消息。父母老了，可能生病了、可能過世了。你怕問。

摩詰把最重要的問題全部跳過去。他不敢問人。他挑了一個最不會受傷的問題——一棵樹。

他家裡有一扇綺窗（雕花的窗戶），是他從小看到大的那扇窗。窗前有一棵寒梅樹。他問對方——你來的時候，那棵寒梅樹開花了嗎？

那扇綺窗前的梅樹是摩詰心裡的「家」。他離家太久，家裡的人、事、物他都不敢問。他選了一棵樹替他問。樹如果開花了，說明家還在，一切都好。

而且他其實不需要答案。他問的過程本身，就是他心裡的花已經開了。他人在千里之外的長安街上，可是當他問這個問題的一瞬間，他的心已經飛回那扇綺窗前，看見那棵梅樹了。

兩人簡單交談了幾句就分開了。對方繼續趕路，摩詰站在原地看著他的背影消失在長安街尾。

他回家把這段對話寫下來，只有四句：

君自故鄉來，應知故鄉事。來日綺窗前，寒梅著花未。

千年後我們每一個離家在外的人，遇到老鄉、遇到剛從故鄉來的朋友、遇到讓我們想起家的任何時刻——我們心裡都會浮起一個「寒梅著花未」式的問題。

你們家門口那棵樹還在嗎？巷口那家餛飩店還開嗎？媽媽做的那道菜還會做嗎？

不是問樹、問店、問菜。是問一個回不去的自己。`
  },

  // id=277 中唐 柳宗元 〈江雪〉rating=6
  // 詩眼：政治犯用不釣魚的釣竿告訴世界「我還在」
  // 隱藏連接：劉禹錫同時被貶朗州，共享同一片雪
  277: {
    title: "江雪",
    author: "柳宗元",
    summary: "他手裡那根釣竿三個小時沒動過——不是他想釣什麼，是他需要有個姿勢，告訴自己還在。",
    story: `跟你說我朋友宗元的一個下午。永州的冬天，瀟水江上，一葉小舟，一個裹著蓑衣戴斗笠的中年人。他手裡那根釣竿，已經三個小時沒動過。

不是他懶。是那根竿子從頭到尾就沒真的想釣什麼。他需要的只是一個「有事做」的姿勢——別人看見他，才不會過來問話。

五年前這個人還在長安當禮部員外郎，跟劉禹錫、王叔文一夥搞政治改革，想把權力從宦官手裡拿回來。他們幹了半年，垮了。王叔文賜死，八個核心成員全數貶到最偏遠的地方，史稱「八司馬」。宗元分到永州。

他南下那年冬天，母親盧氏跟著他。老人家一路顛簸，沒撐到永州就走了。他是罪臣，沒能力辦像樣的葬禮，把母親草草葬在半路一座小山上，一個人繼續往南。

到了永州才發現，這地方比他想像的更糟。瘴氣重、蚊蟲多、當地人聽不懂他的長安話。他被塞在龍興寺一間破房裡當「司馬」，一個沒實權、沒辦公室、連俸祿都常被剋扣的閒官。第一年他大病一場，牙掉了好幾顆，頭髮開始白。他寫信給韓愈，信裡沒抱怨，只說「近日略好」。

朋友都在遠方。劉禹錫被貶到朗州，兩人隔著幾百里，通信有時一個月來一封，有時半年沒消息——信使可能死在路上。

但他沒讓自己爛掉。他走遍永州附近的山水寫下〈永州八記〉；他聽一個捕蛇老頭訴苦，寫〈捕蛇者說〉替他喊冤；他把一條無名的溪命名為「愚溪」，替自己找了個台階。這些事沒有俸祿、也幾乎沒有讀者，除了幾百里外的劉禹錫。

今天他來江邊，不為釣魚。他就是想一個人待一會兒。

雪下得很大。他抬頭看四周，所有的鳥都不見了；他來時踩出的腳印，也被新雪蓋掉了。整條瀟水、整片山巒，此刻只有他一個人。這種安靜大到不像人間。

他忽然覺得這樣也好。如果整個世界要把他忘掉，如果永貞革新永遠不會被平反，如果他的抱負永遠沒機會兌現——那也沒關係。他還在這裡，他還在做事，他還沒放下釣竿。

他從懷裡掏出紙筆，寫了二十個字：

千山鳥飛絕，萬徑人蹤滅。孤舟蓑笠翁，獨釣寒江雪。

寫完把紙折起來，準備下次通信時寄給朗州的劉禹錫。他知道劉會懂，因為劉那邊此刻大概也是這樣的雪。

他收起釣竿站起來，慢慢往龍興寺走。江上還在下雪，什麼聲音都沒有。

十年後宗元死在柳州，四十七歲，沒能等到平反。但他這個下午在江邊留下的畫面，活到了現在——每一個被世界甩開的人，讀完都會突然懂：孤獨不是失敗，只要你還在釣，你就還在。`
  },

  // id=303 盛唐 李白 〈送孟浩然之廣陵〉rating=6
  // 詩眼：一直看著朋友的船消失——最深的告別
  // 隱藏連接：孟浩然是李白的偶像，這可能是他們最後一次見面
  303: {
    title: "送孟浩然之廣陵",
    author: "李白",
    summary: "二十八個字，沒寫一句捨不得——但他在江邊站到船完全消失。這是李白送別偶像的方式：不哭不喊，只是一直看。",
    story: `跟你說我朋友太白送別偶像的一個上午。

孟浩然是太白的偶像。太白年輕時就仰慕他，還寫過一首〈贈孟浩然〉直接告白——吾愛孟夫子，風流天下聞。浩然比太白大十二歲，兩人在襄陽相識，成了忘年交。

七三〇年春天，浩然要從湖北黃鶴樓（今武漢）坐船去揚州（廣陵）。太白替他送行。這一年太白三十歲，浩然四十二歲。

那天早晨太白到黃鶴樓，跟浩然吃了頓早飯。三月，柳絮飛揚、桃花盛開的春天最美的時候。浩然要去的揚州是唐代江南第一大城，經濟中心，是所有文人夢想的地方。

太白替浩然一開頭寫了一句——老朋友從西邊辭別黃鶴樓，在最美的三月順江東下到揚州。他沒有寫一絲捨不得。他把注意力全放在朋友的旅程有多美。

浩然上船了。船開了。太白站在黃鶴樓上，看著他的船。

那條孤獨的帆船慢慢變成遠遠的一個影子，一路飄向下游。太白沒有轉身離開。他站在樓上，看著浩然的船——從近到遠、從清晰到模糊、從船變成帆、從帆變成影子、從影子變成——什麼都沒有。

浩然的船不見了。長江還在流。

他繼續站在原地，看著空空的江面。因為江水的方向就是浩然去的方向。他看江水，其實還是在送別浩然。

他寫下的是這樣一首詩：

故人西辭黃鶴樓，煙花三月下揚州。孤帆遠影碧空盡，唯見長江天際流。

太白這個人平常寫詩多誇張——白髮三千丈、飛流直下三千尺——他豪言壯語很多。但這首送別詩他一個「愁」字都沒寫、一個「別」字都沒用。他只是站在那裡看。這比任何抒情都重。

浩然這輩子跟太白的緣分並不深。他們見面次數不多。浩然五十二歲時，因為背疽剛好又跟王昌齡吃鮮魚破戒，病發過世。太白聽到消息哭了很久。

太白最後一次見浩然是什麼時候？史書沒有明確記載。也許就是這一次——黃鶴樓下、煙花三月、下揚州。

如果是這樣，那個上午就是太白對他偶像的最後一眼。

千年後每一次「不知道還能不能再見」的告別，我們都會像太白這樣站在那裡，看著離開的人變小、變成一個點、消失。而長江，一直在流。`
  },

  // id=304 盛唐 李白 〈下江陵〉rating=6
  // 詩眼：60歲流放路上突然被赦免的狂喜
  // 隱藏連接：這是他晚年少數幾次真正的快樂
  304: {
    title: "下江陵",
    author: "李白",
    summary: "李白 60 歲流放夜郎的路上，突然收到赦免令——他當場坐船回頭，把三峽衝下的那 1200 里，寫成了他一生最爽的一首詩。",
    story: `跟你說我朋友太白六十歲最爽的一個上午。

背景是這樣：五十五歲那年安史之亂爆發，太白跟錯了永王李璘。永王起兵被視為叛亂，兵敗被殺，太白因此被牽連，判流放夜郎（今貴州桐梓）。夜郎在唐代人流放到那裡沒有活著回來的紀錄。他五十九歲被押解上路，從九江一路押送到白帝城（今重慶奉節），準備進入四川繼續南下。

他在白帝城等船。他知道自己這輩子回不來了。

然後奇蹟發生。

七五九年三月，唐肅宗因為關中大旱，下了大赦令——凡是流放的罪犯全部赦免。這消息傳到白帝城時，太白正在準備繼續南下的船。

他當場叫船主調頭。他要往回走。他要順著長江下去，不再往夜郎。

那天早晨他辭別白帝城。白帝城建在山上，早晨常有雲霧。他坐在船頭，看著雲霧慢慢退到身後。船速非常快——從白帝城到江陵（今湖北荊州）大約一千兩百里，只有三峽的長江順流而下才能一天走完。

三峽兩岸的猿猴一直在叫。那個聲音一般是悲哀的，很多詩人聽了都會傷感。但太白根本沒理。他的船已經穿過一座又一座山，猿聲追不上他的速度。他站在船頭看兩岸山巒飛速掠過，覺得自己好像少年。他六十歲了，可他此刻覺得自己二十歲。

他寫下的是這樣一首詩：

朝辭白帝彩雲間，千里江陵一日還。兩岸猿聲啼不住，輕舟已過萬重山。

他寫完把紙收起來。他真的一天到了江陵。

但你知道嗎？這背後其實有更深的哀傷。因為太白沒能真的翻身。他從江陵放歸之後又漂泊了三年，六十二歲那年在當塗（今安徽馬鞍山）病死。他沒能回到長安、沒能重新做官、沒能實現他一輩子想做的事。

那個上午在白帝城掉頭衝下三峽的爽——是他晚年少數幾次真正的快樂之一。

太白這輩子寫過很多壯麗的詩，可是這一首特別。因為它是他真的活過的一天。不是他想像的、不是他吹牛的——是他真的坐在船上，真的一天到了江陵，真的看見兩岸山巒飛速掠過。

千年後我們讀這首詩，還能感受到那條船的速度。感受到六十歲的太白站在船頭，心裡想著——我還沒死。我還有機會。`
  },

  // id=310 盛唐 李白 〈望廬山瀑布〉rating=6
  // 詩眼：李白式的看見——他真的以為那是銀河
  // 隱藏連接：李白這輩子活在放大版的世界
  310: {
    title: "望廬山瀑布",
    author: "李白",
    summary: "「疑是銀河落九天」不是李白的比喻——他真的以為自己看見了銀河。這是李白式想像力的極致示範。",
    story: `跟你說我朋友太白年輕時最狂的一次「看見」。

太白二十五歲離開四川，四處遊歷。廬山（今江西九江）是他這輩子去過至少三次的地方。這首詩大概寫在他二十幾歲時的一次廬山行。

那天他一個人來廬山。他站在山下往上看。

太陽正好照在香爐峰的山頂上。香爐峰是廬山的一座山峰，因為山頂尖圓像個香爐，古代得名。陽光加上雲霧折射，看起來像紫色的煙從香爐裡冒出來。

他繼續往前走。他看見一條白色的東西掛在山壁上——那是遠處的瀑布。從遠處看瀑布，你不會覺得水在動，你只看到一條白色的條狀物靜靜地掛在半空。

他往瀑布走近。走著走著，瀑布現在在他頭頂上。他仰起頭。

瀑布從山頂垂直沖下來。落差非常大。太白站在瀑布下面看——他覺得那條瀑布長達三千尺（唐代一尺約三十公分，三千尺是九百公尺）。

廬山瀑布真的有那麼長嗎？沒有。廬山秀峰瀑布落差大約一百五十五公尺，就算是三疊泉，總落差也不到五百尺。太白誇張了六倍。

可他不是在誇張。他真的以為那麼長。

太白的想像力有一個特色——他看見的東西比別人看見的大。白髮三千丈、桃花潭水深千尺——別人寫詩會有比例感，太白沒有。他的世界永遠是放大版。

然後——他抬頭看瀑布的最頂端。瀑布從山頂沖下來。可是山頂上面就是天空。天空上面就是——

銀河？

他站在瀑布下面，看著這條從天而降的白色巨物——他真的不確定那是不是銀河從天上掉下來了。他不是要把瀑布比喻成銀河。他是在那一瞬間真的分不清。他的腦子把地上的水跟天上的星河連通了。他真的以為自己看見了神蹟。

他寫下的是這樣一首詩：

日照香爐生紫煙，遙看瀑布掛前川。飛流直下三千尺，疑是銀河落九天。

太白的天才不是他的文學技巧，是他的觀看方式。他看瀑布能看見銀河；他看月亮能舉杯邀月；他看白髮能看見三千丈；他看酒杯能看見萬古愁。他活在一個放大版的世界裡。

我們一般人看瀑布，會想「這個瀑布很壯麗」、「今天天氣真好」、「等下要不要拍照」。太白看瀑布會想——天上的銀河為什麼掉下來了？

下次你看見瀑布、看見月亮、看見白髮，你可以想想太白。他會告訴你——別小看你看到的東西。它可能是銀河。`
  },

  // id=319 盛唐 王維 〈九月九日憶山東兄弟〉rating=6
  // 詩眼：17歲少年寫下換位思考的思鄉詩
  // 隱藏連接：王維一生第一首名作
  319: {
    title: "九月九日憶山東兄弟",
    author: "王維",
    summary: "王維 17 歲寫的第一首名作——他一個人在長安過重陽節，寫出了千古最會換位思考的一句：遙知兄弟登高處，遍插茱萸少一人。",
    story: `跟你說我朋友摩詰十七歲那年的重陽節。這年他離家兩年了。他十五歲從山西蒲州出來，一個人到長安遊學求功名。他家在華山東邊，他叫家人「山東兄弟」。

重陽節那天早晨他起床，長安街上已經是節日的氣氛。他站在門口看——一家一家的人抬著酒罈、帶著小孩、拎著茱萸（一種驅邪的植物），往城外的山上去。父親走在前面，孩子跟在後面，老人被兒子攙著，一路上笑鬧不斷。整條街上都是熱鬧的家族出遊。

他一個人。沒地方去。

他昨天也一個人。前天也一個人。他兩年來每天都一個人。可是今天，這種「一個人」的感覺被放大了十倍。他很清楚為什麼——因為今天是重陽節。今天是家人要一起登高、一起喝菊花酒、一起佩茱萸的日子。他不在他該在的地方。

他回到自己的小房間。他想寫詩。

一般少年在這個時候會寫什麼？——「今天重陽節，我一個人好孤單，我好想家。」就這樣。

摩詰坐了一會兒。他決定不這樣寫。

他想像蒲州的兄弟們。他知道他們今天一定會登城東那座山——他們每年都去，路他都熟。他們此刻應該已經到了山頂。他們正在把茱萸插進頭髮和衣襟。他們把去年釀的菊花酒倒進小陶碗。他們在山風裡笑得很大聲。

然後在某個瞬間——他們會停下來。他們會彼此對視。可能是二哥先開口，也可能是小弟。某個人會說——唉，可惜維兒不在。

摩詰在長安小房間裡，隔著一千里的路，聽見了兄弟為他的嘆息。

摩詰把自己的孤獨，翻譯成兄弟們的一次點名。他不寫自己想家，他寫兄弟們也在想他。

他寫下的是這樣一首詩：

獨在異鄉為異客，每逢佳節倍思親。遙知兄弟登高處，遍插茱萸少一人。

這是他這輩子的第一首名作。他當時不知道，這首詩會被之後一千兩百年裡每一個異鄉遊子在節日獨處時念一遍。

一個十七歲少年在長安小房間裡寫下的一句話，變成了所有華人在節日獨處時的自我敘述。

所以下次你在異鄉過節、覺得孤單的時候，你可以想想那個下午的摩詰。他沒有寫「我好慘」——他寫的是「他們一定也在想我」。

千年後這個少年還在替我們過節。`
  },

  // id=328 盛唐 王翰 〈涼州詞〉rating=6
  // 詩眼：戰場前夜的醉——古來征戰幾人回
  // 隱藏連接：邊塞士兵知道回不來，喝酒是先行告別
  328: {
    title: "涼州詞",
    author: "王翰",
    summary: "「醉臥沙場君莫笑，古來征戰幾人回」——這是最豪邁的一句話，也是最悲的一句話。醉的不是快樂，是明知回不來的先行告別。",
    story: `跟你說唐朝邊塞詩裡最有名的一場「醉」。這是甘肅武威（唐代叫涼州）某個軍營的夜晚。

涼州是唐朝西北邊塞的重鎮，是抵擋吐蕃、突厥的前線。從這裡出征，往西北打仗，戰死是常態，凱旋是奇蹟。這一晚軍營裡擺了一場宴席。士兵們知道明天可能就要出征。

桌上擺著葡萄酒——這是西域傳來的葡萄酒，主要產於涼州、河西一帶，內地喝不到。酒杯是夜光杯——傳說中的珍貴玉杯，可以在夜裡發光。頂級的酒配頂級的杯。

戰場前夜為什麼要擺這麼奢華的一頓？

因為每個人心裡都明白——這可能是他們最後一次喝酒。既然是最後一次，那就把最好的擺出來。

士兵們拿起酒杯，正想喝。忽然琵琶聲響起。這聲音有雙重意義——一是宴席伴奏；二是催他們上馬出征。到底是催喝還是催戰？他們自己也分不清。琵琶聲一直響，酒不停在倒，隨時可能響起出征的鼓聲。

他們喝得很快。喝得很狠。他們喝的每一口酒都可能是最後一口。喝到醉，是因為清醒面對死亡太痛了。

有個士兵喝多了。他倒在沙場邊上。旁邊的人看見了，可能想笑他——身為軍人居然醉倒在戰場邊，多丟臉。

那個醉倒的士兵抬起頭，看著要笑他的人，說了一句——別笑我。因為從古到今，出征打仗的人，有幾個回得來？

大家聽了都沉默。因為他們知道他說的是實話。

王翰把這一夜寫下的是這樣一首詩：

葡萄美酒夜光杯，欲飲琵琶馬上催。醉臥沙場君莫笑，古來征戰幾人回。

王翰記錄的其實不只是一場邊塞宴席。他記錄的是所有「明知會失敗還是要拚」的時刻——創業失敗前夜的一杯酒、手術前的一個晚上、離別前的一頓飯、告白前的一個下午。

那都是我們自己的「醉臥沙場」。

所以下次你在人生某個關鍵時刻豁出去，你可以想想涼州軍營的那一夜。你不用清醒，你可以先替自己倒一杯，先醉一場。因為從古到今出征打仗的人，有幾個回得來？不多。但我們願意去——這才是重點。

王翰這輩子只留下兩首詩。他自己也是個豪邁不羈的男子，據說喝酒可以三日不醒。他寫這首詩的時候大概想著他自己在涼州見過的那些士兵——那些用最好的酒、在戰場邊上、明知會死還是豁出去的人。他知道那些人的名字。他知道他們大多沒能回來。他寫下這首詩，就是替他們留下最後一夜的樣子。`
  },

  // id=329 盛唐 賀知章 〈回鄉偶書〉rating=6
  // 詩眼：86歲回家鄉被孩子當外人的心痛
  // 隱藏連接：賀知章離家五十幾年
  329: {
    title: "回鄉偶書",
    author: "賀知章",
    summary: "他 86 歲回家鄉，離家 50 幾年——結果被村裡的小孩當成外地觀光客，笑著問他從哪裡來。這是最溫柔也最痛的一首詩。",
    story: `跟你說我朋友季真一輩子的等待。

季真（賀知章）是唐代的頂級人物，官至秘書監，是玄宗身邊的紅人。他發現了李白、把「謫仙人」這個名號給李白、跟李白張旭那群人並稱「飲中八仙」。但這一切都在長安。他家鄉在越州永興（今浙江杭州蕭山），他三十幾歲離開家鄉考科舉、當官，從此就一直在長安、洛陽。他離家一去五十幾年。

天寶三載（七四四年），季真八十六歲。他向玄宗申請——我想回家鄉養老，出家當道士。玄宗准了，還親自為他寫詩送行，讓文武百官送到長安東門。這是唐代最風光的退休儀式之一。

他終於回家鄉了。

他坐了很多天的船。他還記得從長安到江南的每一段路。他走進越州地界的時候，忍不住哭了。他看見自己出生的縣城的城門。他從十七歲離開這個門，此刻他八十六歲。

他走進他童年住的村子。這個村子他從小就跑，每條巷子他都熟。他走到自己家老宅的位置。房子還在。可是院子裡有幾個小孩在玩。

那些小孩不認識他。

他站在門口不知道怎麼開口。他這輩子最會的就是說話——他是朝廷紅人、詩人、跟李白喝酒的老頭。可是此刻他不知道要怎麼向這些孩子介紹自己。

一個小孩看見這個穿著體面的老人站在門口，笑著問他——先生，你從哪裡來的呀？

季真的呼吸停了。

他這輩子想回家。回來了發現——沒人記得他了。他變成了自己家鄉的陌生人。小孩沒有惡意，他們是笑著問的。可是那句問候戳穿了一切。他坐下來嘆了口氣。他發現自己的口音沒變——他這輩子在長安講了五十幾年官話，回到家鄉他還是能講一口流利的越州話。可是他抬手摸了一下鬢角，白頭髮已經很稀。

時間過去了。

他寫下四句話：

少小離家老大回，鄉音無改鬢毛衰。兒童相見不相識，笑問客從何處來。

季真回家鄉沒多久就過世了。他享年八十六歲，在家鄉走完了最後幾個月。他選擇的「回家養老」變成了「回家等死」。

但他寫下了這首詩。千年後每一個異鄉遊子讀到它，都會想到自己未來的某一天——你老了、回家鄉、發現大家都不認識你了、變成家鄉的觀光客——那個時刻。

所以下次你猶豫要不要回家、要不要多打電話給爸媽，你可以想想季真。他等了五十幾年才回家。回去了才發現——已經來不及了。`
  },

  // id=332 盛唐 高適 〈別董大-其一〉rating=6
  // 詩眼：兩個失意者互相打氣——打氣的人自己也還沒翻身
  // 隱藏連接：44歲高適當時窮到叮噹響
  332: {
    title: "別董大-其一",
    author: "高適",
    summary: "「莫愁前路無知己，天下誰人不識君」——史上最豪邁的送別詩。但你知道嗎？寫這首詩的高適，當時自己也是個窮到叮噹響的中年男子。",
    story: `跟你說唐朝送別詩裡最反差的一個場景。這年是天寶六載（七四七），冬天，北方某片荒野。兩個中年男子在小帳裡喝酒，酒喝完了要各走各路。

一個叫高適，四十四歲，沒工作。他年輕的時候窮到二十幾歲曾以乞討為生。他有才華但沒人賞識，寫的邊塞詩傳到長安沒人在乎。此刻他自己都不知道下一頓在哪。

另一個叫董庭蘭，人稱董大，唐朝當時最有名的七弦琴演奏家。他曾經是宰相房琯的門客——房琯管他吃住，他負責彈琴。今年房琯被玄宗貶了，董大失去了依靠，只能背著琴到處流浪賣藝。

兩個中年失敗者在冬天的荒野上相遇，一起喝了幾杯，暖暖身。然後董大要繼續走了。

那天的天氣糟到極點。千里之內都是黃色的雲——是被風沙吹起的沙塵暴加上冬季陰霾。太陽都變昏暗了。北風把大雁吹走。大雪紛飛。

高適跟董大喝完最後一杯酒。他拍了拍朋友的肩膀，說——兄弟，別擔心你去了那裡沒人認識你。天下有誰不認識你？你是董庭蘭。你的琴聲名滿天下。你不管走到哪，人們一聽到你的琴，就會知道你是誰。

他寫下的是這樣一首詩：

千里黃雲白日曛，北風吹雁雪紛紛。莫愁前路無知己，天下誰人不識君。

董大接過這首詩，收進行囊裡，走進雪裡去了。

但你有沒有發現一件事？高適自己就是那個「前路無知己」的人。他自己就是「天下沒人認識我」的那個人。他在鼓勵朋友的時候，其實也在鼓勵自己。他把自己還沒得到的東西，先送給了朋友。

八年後，安史之亂爆發。高適五十二歲時投奔哥舒翰的幕府，一路升官，最後官至渤海縣侯——這是唐代文人裡少數封侯的一位。杜甫後來寫詩讚美他「當代論才子，如公復幾人」。

董大呢？他繼續流浪賣藝，可是他的琴聲真的到哪都有人賞識。他晚年被大詩人李頎寫進〈聽董大彈胡笳〉，成為唐代音樂史的名人。

高適那天在雪地裡對董大說的話，兩個人後來都真的兌現了。

所以下次你在人生某個低谷送別另一個低谷的朋友，你可以借高適那句話。也許你們兩個現在都沒人認識——但時間會替你們證明。`
  },

  // id=333 中唐 白居易 〈大林寺桃花〉rating=6
  // 詩眼：山下的花已謝、山上的花剛開——時間可以繞路
  // 隱藏連接：45歲被貶江州的失落中的頓悟
  333: {
    title: "大林寺桃花",
    author: "白居易",
    summary: "山下四月的桃花已經謝了，他上到廬山高處，突然發現一片桃花正在盛開——原來春天沒走，只是繞路來這裡了。",
    story: `跟你說我朋友樂天一個很小卻很暖的發現。這一年是西元八一六年，樂天四十五歲，被貶為江州司馬（就是〈琵琶行〉那個時期）。他心情不好，經常跑到廬山散心。

那天他從山下的潯陽江邊出發，往廬山高處走。他要去山上一座叫「大林寺」的寺廟。這段山路走了半天。

出發的時候他心情糟到極點。今年江州的桃花早就謝了，他四月初本來想看春天最後一波桃花，可是江邊已經沒有了。整個春天對他來說結束了。

他一邊爬山一邊想——我這輩子的春天也結束了。他四十五歲。他曾經是天子跟前的翰林學士，如今是個沒實權的江州司馬。他這輩子的政治抱負沒了、他的長安風光沒了、他的青年時代沒了。他覺得自己被時代拋棄了。

他一路爬。大林寺在廬山的高處，海拔比山下高很多。他氣喘吁吁到了寺門口，坐下來休息。

他抬頭看四周。

他愣住了。

大林寺的院子裡，一整排桃樹正在盛開。

他不敢相信自己的眼睛。他站起來走近其中一棵。粉紅色的花瓣一片一片，鮮豔得像剛開一樣。他往別的樹看——每一棵都在盛開。

他明白了——山上海拔高，氣溫低，花期比山下晚。這是自然規律。同一朵春天，在不同的海拔有不同的時間。

樂天當然不懂植物學。他只知道——我以為春天走了，結果春天在這裡等我。

他坐在桃花底下想了很久。原來春天沒有結束，只是換了地方。他一直以為春天走了，其實它只是繞了一條他不知道的路。

他離開大林寺的時候寫下四句話：

人間四月芳菲盡，山寺桃花始盛開。長恨春歸無覓處，不知轉入此中來。

樂天寫下這首詩時，他人生後半段的春天才剛要開始。四十五歲在江州被貶，看似人生完了——但他四十七歲被調去忠州、四十九歲當杭州刺史（治理西湖、修白堤）、五十二歲當蘇州刺史（政績卓越）、晚年官至刑部尚書。

他的人生後半段比前半段更精彩。他四十五歲在大林寺看見的那片桃花，就是他人生後半場的預告。

所以下次你覺得自己的春天已經結束了，你可以想想那個下午的樂天。他氣喘吁吁爬上山，就是為了給你發現這一件事——你的春天沒走。它只是換了地方。你要往新的山上走。那裡有一片桃花正在為你盛開。你還沒看見而已。`
  },

  // id=350 中唐 元稹 〈離思其四〉rating=6
  // 詩眼：深情的悖論——那個瞬間的告白是真的，就算後來變了心
  // 隱藏連接：亡妻韋叢+後來的再婚爭議
  350: {
    title: "離思其四",
    author: "元稹",
    summary: "「曾經滄海難為水」——他寫下史上最深情的悼亡詩。但你知道嗎？他後來又結婚了。這是唐代最複雜的一次深情。",
    story: `跟你說我朋友微之最痛的一個秋天。這年他三十一歲，妻子韋叢剛剛病逝，才二十七歲。

韋叢是京兆尹韋夏卿的女兒，出身名門。微之七年前娶她時，只是個沒錢沒官的校書郎。韋家把大小姐嫁給他，很多人不理解。可韋叢自己一句怨言都沒有。她跟微之一起住陋巷，自己下廚、自己縫衣、自己拔頭上的金釵去換酒錢——只要微之高興。

七年後她病死了。留下一個女兒，還有微之一個人。

那個秋天他一個人坐在書房裡。他想她。她跟他過的每一頓飯、走過的每一段窮日子，全部變成了回憶。

他這輩子還會遇到別的女人嗎？當然會。他才三十一歲，還有大半輩子要走。

可是他知道——她們對他來說算什麼？

他坐了很久。他找到一個比喻。他寫下——見過大海的人，其他小水塘小河流在他眼裡都不能算是水。

他又寫了第二個。除了巫山那朵傳說裡的神女雲，其他雲都不能算雲。

他這輩子見過大海。他這輩子見過巫山雲。她們的名字都叫韋叢。

他繼續寫。就算他走過美女如雲的地方——他懶得回頭看一眼。一半是因為他在修道看破紅塵，另一半——是因為她。

他寫下的是這樣一首詩：

曾經滄海難為水，除卻巫山不是雲。取次花叢懶回顧，半緣修道半緣君。

他把詩收起來。他在悼念他妻子。他當下確信自己這輩子不會再愛別人了。

兩年後，微之三十三歲，跟一個叫安氏的女子有了一段感情，還生了女兒。三十四歲，他娶了裴淑，另一位官員的女兒。他跟裴淑生了幾個孩子，一直到晚年。

他寫「取次花叢懶回顧」的兩三年後，就走進了新的花叢。

歷代讀者為這件事吵翻了。有人說他口是心非。有人說他背叛韋叢。

但你想想那個晚上。那個三十一歲的男人坐在書房裡，剛剛失去七年來替他縫衣煮飯的妻子。他當下寫下「除卻巫山不是雲」的那一秒——他是真的這樣覺得。他不是在騙自己，也不是在騙我們。

只是人會變。那個晚上他不知道自己過幾年還會再愛別人。他當下的深情，不因為後來變了心而變假。

千年後每一個曾經深愛過的人讀這首詩，都能借它承認一件事——你曾經在某個瞬間確信這輩子只愛一個人。那個瞬間是真的。你只是還沒遇到另一片海。`
  },

  // id=359 晚唐 李商隱 〈夜雨寄北〉rating=6
  // 詩眼：未寄達的希望——想像中的「未來聊天」永遠沒兌現
  // 隱藏連接：妻子王氏，這時候他人在四川
  359: {
    title: "夜雨寄北",
    author: "李商隱",
    summary: "史上最會操作時空的一首情詩——他人在四川，寫給長安的妻子，但他寫的是「未來我們重逢後，一起回憶今晚」。",
    story: `跟你說我朋友義山客居四川的一個雨夜。這年他三十三歲，在梓州幕府裡當個小小的幕僚。他妻子王氏留在長安。四川離長安幾千里，他一年也回不了一次家。

那天晚上他收到王氏的來信。信寫得平淡，只問了一句——你什麼時候回家？

他坐在窗邊，把信讀了三遍。他不知道怎麼回。不是「明年」也不是「後年」——他自己就不知道。上頭要他去哪、待多久，他沒有選擇權。他提筆寫下三個字——未有期。

外面的雨下得很大。這場秋雨已經下了兩天了。他推開窗看院子，那口池子的水都漲滿了。四川的秋天就是這樣，一場雨連下三天，把整個世界泡在潮濕裡。

他很想她。他想告訴她今晚有多冷、被褥有多潮、燈油被雨氣熏得多昏。可是這些話寫在信裡沒意義。她收到信可能是一個月後，那時候雨早就停了。

他坐了很久。他決定不寫「現在」，改寫「將來」。

他寫——什麼時候我們能坐在西窗下，一起剪蠟燭芯、一起熬夜聊天？

古代蠟燭燒久了，燭芯會變長，火會變暗，要用剪刀剪掉一小段，火才會重新亮起來。夫妻夜談的時候，兩人輪流剪燭。這是他們婚後常做的事。

然後他寫下最狠的那一句。在那個未來的西窗下，我們一起聊什麼？——我們一起聊今天晚上。聊我在巴山，下著夜雨，一個人想妳的這個時刻。

他把當下的孤單，變成了他們未來共同回憶的素材。此刻的痛不會白費，因為將來它會被兩人一起回憶。

他寫下的是這樣一首詩：

君問歸期未有期，巴山夜雨漲秋池。何當共剪西窗燭，卻話巴山夜雨時。

他把信折起來，寄了出去。

六年後，王氏病逝。義山三十九歲。之後他繼續在各地當幕僚，直到四十六歲病逝。

他們從來沒有一起剪過西窗燭。那個他寫在信裡的「將來」，永遠停在紙上。

但這首詩留下來了。千年後每一個異地相思的人，都可以借他寫下的字告訴遠方的愛人——總有一天我們會重逢，那時候我們一起回憶今晚，我一個人，想著你。

哪怕重逢沒能到來。你在這個雨夜寫下的字，會替你活到那一天。`
  },

  // id=368 晚唐 杜牧 〈泊秦淮〉rating=6
  // 詩眼：亡國之音被當娛樂——歷史正在原樣重演
  // 隱藏連接：〈玉樹後庭花〉是陳後主亡國前寫的
  368: {
    title: "泊秦淮",
    author: "杜牧",
    summary: "他一個人聽出來了——酒家歌女唱的那首歌，是兩百年前陳後主亡國前的作品。當今晚唐正在原樣重演那場崩塌。",
    story: `跟你說我朋友牧之一個很沉的秋夜。

牧之這時候大約三十幾歲，坐船經過南京（唐代叫金陵）。他把船停在秦淮河邊過夜。秦淮河是南京最熱鬧的地方，兩岸都是酒家、歌樓、青樓，晚上燈火通明。

那天夜裡有霧。他從船艙走出來看外面。霧氣籠罩著寒冷的河水，月光鋪在沙上——一片朦朧的、寂靜的、有點冷的秋夜。船停在河邊，離最近的酒家不遠。

酒家裡傳出笑聲、划拳聲、樂器聲。牧之聽了幾秒，忽然愣住了。

有個歌女在唱歌。歌詞他熟。那是〈玉樹後庭花〉——南朝陳的最後一個皇帝陳叔寶（陳後主）寫的。陳叔寶是史上最有名的亡國之君之一。他當年在深宮裡跟寵妃張麗華、孔貴嬪一起寫下這首靡靡之音，用歌女合唱，通宵達旦地享樂。那時候北方隋朝已經整軍南下，準備滅陳。陳叔寶不管，他繼續聽這首歌。

不到十年後，隋軍過江，陳朝亡了。陳叔寶被抓，張麗華、孔貴嬪被殺。

兩百多年之後，秦淮河邊的酒家裡，還有人在唱這首歌。

牧之站在船頭。他看著河對岸的燈火。他忽然覺得——這些花錢聽歌的客人、這個唱歌的女子、這整條秦淮河，都不知道自己在做什麼。

他這時候看到的不只是一場酒宴，是整個晚唐的縮影。晚唐朝廷腐敗、宦官弄權、藩鎮跋扈——整個王朝已經在走下坡。可是京城的達官貴人還在聽這些歌，玩這些樂子，好像什麼事都沒發生。歷史正在原樣重複。而沒人聽得懂。

歌女繼續唱。客人繼續喝。牧之一個人站在船頭聽。

他寫下這首詩：

煙籠寒水月籠沙，夜泊秦淮近酒家。商女不知亡國恨，隔江猶唱後庭花。

他其實不是責怪那個歌女。歌女只是唱她的曲子養活自己。他真正在說的是——那些花錢請歌女唱這首歌的客人、朝廷裡的官員、當今的皇帝——沒人聽得出這首歌的來歷。

牧之寫完詩，回船艙睡覺。他改變不了什麼。他這輩子沒能救得了晚唐。他六十歲那年過世，隔了六十年唐朝正式滅亡。

但他這首詩留下來了。千年後每一個看見自己的時代正在重演歷史的人，讀到「商女不知亡國恨」，都能懂那份無人能懂的痛。`
  },

  // id=375 晚唐 杜牧 〈山行〉rating=6
  // 詩眼：趕路的人突然願意停下——一片野楓林讓他放下行程
  // 隱藏連接：「停車坐愛」二字寫出了成年人少見的放下
  375: {
    title: "山行",
    author: "杜牧",
    summary: "杜牧在趕路，本來趕得急，可是他看見一片野楓林——他叫車伕停車，坐下來看到夕陽。他一輩子見過那麼多繁華，被一片沒人看的紅葉留住了。",
    story: `跟你說我朋友牧之一個晚秋下午的小發現。

牧之這時候在哪、要去哪？史書沒明確記載。但可以確定的是——那天他在某座山裡趕路。他坐一輛簡單的馬車。車伕趕著馬慢慢往上爬。

那條山路蜿蜒又陡。石頭鋪的路面被落葉蓋著，走起來不太平。他往上看——山頭有霧，白雲密密堆在那邊。他順著白雲往下看，隱約看到山腰有幾戶人家的煙冒出來。

這是一座已經進入秋深的山。「寒山」不是山的名字，是他當下的感覺。石徑一直往上斜。他還想再往上走一段。

正當他要繼續走，他忽然叫車伕停車。

因為他看見了。

山路轉彎的地方有一片楓林。楓葉全紅了——不是那種淡淡的橘紅，是整片燒起來的、深深的紅。晚秋的霜把每一片葉子都染透了。夕陽從楓林的縫隙裡穿過來，紅色在陽光下更亮。

他愣了幾秒。他想——這比二月的花還豔。

他跳下車走近楓林。他站在楓樹底下抬頭看。滿樹的紅像倒過來的火。他知道自己趕路耽誤了，可他就是想再多看一會兒。他坐下來——不是普通的坐下，是那種「我要好好看這個」的坐下。

車伕站在遠處等他，沒催他。牧之坐在楓樹下看夕陽從樹葉間穿過。風一吹，幾片紅葉飄下來落在他袖子上。他撿起一片，發現葉脈紅得像血，紋路清晰得像新畫的圖。他忽然想——這種楓林他這輩子經過多少次？他每次都在趕路，都在想下一個任所、下一封公文、下一個要應酬的官員。每一次他都沒停下來看。

他這輩子見過長安宮廷、見過揚州歌舞、見過南京秦淮河、見過各種繁華。可是這個下午，一片沒人看見的野楓林，讓他停下車。

他寫下四句話：

遠上寒山石徑斜，白雲生處有人家。停車坐愛楓林晚，霜葉紅於二月花。

他沒說自己耽誤了多久。他也沒說最後有沒有趕上原定的行程。他只留下這片楓林。

千年後你在某個秋天、某條路上、突然被一片楓紅震住的時候，你可以想想牧之。他也曾經因為一片楓葉，把行程放下。他一輩子當官不順、寫詩留名，可是這一天他做的事很簡單——他就是坐下來看了一場秋天。

那都是我們生命裡少數幾個「值得停下來」的時刻。`
  },

  // id=395 晚唐 杜秋娘 〈金縷衣〉rating=6
  // 詩眼：寫詩的人已經活到了「無花空折枝」的階段
  // 隱藏連接：杜秋娘傳奇一生的縮影，杜牧為她寫〈杜秋娘詩〉
  395: {
    title: "金縷衣",
    author: "杜秋娘",
    summary: "「花開堪折直須折」——這不是勸別人，是一個從姬妾到宮妃到晚年貧困的女子，替自己一輩子做的總結。",
    story: `跟你說一個唐代最傳奇的宮廷女子。她的名字叫杜秋（後人稱杜秋娘）。〈金縷衣〉這首詩相傳是她寫的、或者至少是她一輩子最愛唱的一首歌。

她的故事你要聽好，因為它比這首歌本身還沉。她的一輩子被四個朝代的政治絞在一起，穿過金縷衣、也穿過破麻布。她是唐代版本的「大起大落」——起得比誰都高，落得比誰都低。

她十幾歲被賣給浙西節度使李錡當姬妾。李錡是個當官的富貴人，對她很好。有一天她唱了這首〈金縷衣〉——李錡愛死這首歌了，從此天天叫她唱。這是她第一次成名。

八〇七年，李錡叛亂被殺。他的家眷全部被抄入宮廷。杜秋娘從富貴人家的姬妾，變成宮廷的女僕。

按理說，她這輩子完了。

可是她在宮裡又唱了這首歌。唐憲宗聽到了。憲宗一聽就愣住。他被這首歌打動——年輕時的美好就這麼過去了，別浪費、別吝惜。他把杜秋娘納入後宮，日夜寵愛。

她從一個抄家女僕，變成皇帝身邊最重要的女人。

憲宗死後，她成了唐穆宗的兒子李湊的傅母（貴族的養母兼老師）。李湊是她一輩子最疼的孩子。可是李湊後來因為政治鬥爭被廢，還被殺了。杜秋娘為李湊求情不成，被貶回她的故鄉潤州（今江蘇鎮江）。

當年那個金縷衣裙、皇帝寵愛的杜秋娘，晚年在潤州一個人過著窮日子。

九年後，一個叫杜牧的年輕詩人路過潤州。他聽說了杜秋娘的故事。他去見她。他看見的是一個穿著破衣、頭髮已白的老婦人。他寫了一首〈杜秋娘詩〉紀念她的一生。

而杜秋娘唱過的那首歌留下來了：

勸君莫惜金縷衣，勸君惜取少年時。花開堪折直須折，莫待無花空折枝。

不要吝惜金縷衣（她真的穿過金縷衣）。要吝惜少年時（她真的沒能留住少年時）。花開了就要摘（她的花被摘過，也凋謝過）。不要等花沒了才空手去折樹枝（她此刻晚年，就在做這件事）。

這首詩最痛的地方是——唱這首歌的人已經活到了「無花空折枝」的階段。她不是在勸別人，她是在替自己一輩子總結。

千年後我們念這四句話，其實念的是杜秋娘一生的縮影。你不摘那朵花，時間會替你摘。`
  },

  // id=397 北宋 蘇軾 〈題西林壁〉rating=6
  // 詩眼：你身在其中就看不清全貌——當局者迷
  // 隱藏連接：他剛結束黃州流放四年，在人生轉折點寫下這個悟
  397: {
    title: "題西林壁",
    author: "蘇軾",
    summary: "剛剛結束四年黃州流放的蘇軾在廬山住了兩週。他發現從不同角度看廬山看到完全不同的樣子——他悟到，這就是他一輩子看不清自己人生的原因。",
    story: `跟你說我朋友子瞻一個很重要的春天。這年是宋神宗元豐七年（一〇八四），他四十七歲。他剛剛結束了四年的黃州流放。

四年前他因為「烏臺詩案」（那個他寫詩諷刺新法被抓的案子），差點被砍頭。神宗最後改判流放黃州（今湖北黃岡），四年裡他過得比誰都慘——沒錢、沒官、沒地位。可是他在黃州反而寫出了他這輩子最好的作品：〈赤壁賦〉、〈念奴嬌·赤壁懷古〉、〈定風波〉。他真正變成「蘇東坡」，就是在那四年。

現在他終於獲得改調，要去汝州（今河南臨汝）任職。他一路從黃州坐船東下，路過廬山（今江西九江）。他決定在廬山住幾天，看看這座他仰慕已久的山。

他在廬山住了將近兩週。他遍遊廬山各處。

那天他從廬山東邊的東林寺往西走。從東邊看廬山，是一片橫著的山嶺。他繼續往前走。走到南邊某個角度回頭看——廬山變了，不是橫嶺，是一座座尖峰。

他愣了兩秒。

他繼續走。從遠處看廬山是連綿的一片，從近處看廬山是巨大的懸崖。從高處看下去廬山是灰綠的一片，從山腳往上看廬山是頂天立地的高山。同一座山，他每移動一次位置，看到的都是不同的一座山。

他站在某個山路上想——所以廬山真正的樣子是什麼？

他忽然明白——只要他還在廬山裡，他就永遠看不到廬山的真正樣子。因為他就是廬山的一部分。

這個發現讓他愣了很久。他想到自己——他被貶四年才看清楚朝廷；他此刻站在廬山裡看不清廬山，就像他一輩子站在自己的人生裡看不清自己。

他到了西林寺，在寺廟的牆上寫下四句話：

橫看成嶺側成峰，遠近高低各不同。不識廬山真面目，只緣身在此山中。

這四句話後來成了中國哲學史上最有名的「當局者迷」的比喻。

千年後我們在生活裡卡關的時候——工作卡關、感情卡關、人生方向卡關——常常聽人說「跳出來看看」。這個「跳出來」的智慧，就是子瞻那天在廬山某個山路上悟到的。

他悟出來後，繼續走完他的人生。他之後又被貶了兩次——貶到惠州、貶到儋州（今海南）。他從來沒能真的跳出他的人生。但他留下了這首詩，替所有後人「跳出來」。`
  },

  // id=413 清 高鼎 〈村居〉rating=6
  // 詩眼：大人看孩子放風箏，看見的是自己回不去的童年
  // 隱藏連接：高鼎是清咸豐年間的鄉間老師，一輩子沒當過大官
  413: {
    title: "村居",
    author: "高鼎",
    summary: "他站在家門口看孩子放學跑去放風箏——他知道自己看見的，是自己這輩子再也回不去的一段時光。",
    story: `跟你說我朋友高鼎一個很小卻很暖的觀察。

高鼎是清朝咸豐年間的一位老師，家在江南。他一輩子沒當過大官，也沒寫過驚天動地的詩。他就是一個普通的鄉間讀書人。

這首〈村居〉大概寫在他當老師的時期。他每天教孩子讀書。孩子放學了他自己也回家。他的家在村子裡。

那一年二月的一個下午——不是深冬也不是暮春，是「草長鶯飛」的那種初春——他在自己家門口站著。他看見孩子們放學後從學堂裡跑出來。

孩子們沒有回家寫功課。他們往村外的空地跑。

高鼎站在門口看著他們。他知道他們要去做什麼。

初春的東風吹起來了。這是放風箏最好的季節。孩子們一個個手裡都拿著自己做的紙鳶（風箏），跑到河堤邊上，趁著風還在，把風箏放上去。堤邊的楊柳已經抽出新葉，在春天的煙靄裡輕輕擺動。柳枝一根一根像被酒醉了一樣，晃晃悠悠地垂到地上。

他看著這群孩子。他們沒有煩惱。他們不擔心明天的考試、明天的功課、明天要見的親戚朋友。他們只擔心一件事——風箏會不會飛起來。他們一邊拉線一邊喊。一個孩子的風箏飛得最高，其他孩子仰著頭看。有的孩子跑到田埂上，有的跑到河堤上，有的跌倒了爬起來繼續跑。

他想起自己小時候。他也是這樣跑出去放風箏的。可是那時候的自己什麼都不懂，什麼都不怕。他現在什麼都懂了，可是他再也做不出那個表情——那個「風箏飛起來了！」的表情。他這輩子沒能離開村子去闖蕩，也沒能做出什麼大事業。他每天教書、每天走同樣的路回家、每天看著同一條河堤。可是他很清楚——他這些日子的「什麼都沒做」，正是那些放風箏的孩子將來會失去的自由。

他覺得自己看見的是他自己回不去的一段時光。

他站在門口寫下四句話：

草長鶯飛二月天，拂堤楊柳醉春煙。兒童散學歸來早，忙趁東風放紙鳶。

他沒有寫自己的感嘆。他只寫了他看見的畫面。畫面本身就替他把感嘆說完了。

一百六十幾年後，每一個看見孩子放風箏、忽然想到自己失去的童年的人，都能懂高鼎當年在門口站著的那個下午。

風箏是所有孩子共有的、大人再也玩不了的東西。`
  },

  // id=416 初唐 王勃 〈滕王閣序-僅節錄佳句〉rating=6
  // 詩眼：一場宴會封神的即席表演
  // 隱藏連接：閻伯嶼原本準備讓女婿當場作序，被路過的26歲王勃搶了風頭；王勃隔年就溺死
  416: {
    title: "滕王閣序-僅節錄佳句",
    author: "王勃",
    summary: "一場原本準備捧女婿的宴會，被一個 26 歲路過的書生搶了風頭。他寫下「落霞與孤鶩齊飛」，讓主人衝進宴會廳認輸。第二年他就淹死了。",
    story: `跟你說我朋友子安一輩子最傳奇的一場即席演出。

這年是六七五年秋天，子安（王勃）二十六歲。他因為犯了殺官奴的罪，被剝奪一切官職。他的父親也被牽連貶到交趾（今越南北部）當縣令。子安要南下看父親，一路走走停停，來到了南昌。

那天南昌都督閻伯嶼在剛翻修好的滕王閣舉辦宴會。他邀請了各方賓客，包括路過的子安。宴會上大家喝酒聊天，正熱鬧的時候，閻伯嶼站起來說——今天這個場合，我想請各位替這座樓寫一篇序。

大家心裡都明白。閻伯嶼有個女婿叫孟學士，他早就準備好了一篇序，今天就是要讓女婿在座上展才華，博名聲。閻伯嶼象徵性地問一輪，就是要大家推辭。

賓客一個一個推辭。輪到子安。

子安沒推辭。他說——好，我來。

在場所有人愣了。閻伯嶼臉色一沉，氣得走出宴會廳。他叫下人——那小子每寫完一句，你馬上跑來報告我。

子安拿起筆。第一句寫下「豫章故郡，洪都新府」。下人跑出去報告閻伯嶼。閻伯嶼冷笑一聲——這是老生常談。過了一會兒，下人又跑出來。子安寫下「星分翼軫，地接衡廬」。閻伯嶼沒說話。

一個一個賓客圍在子安身邊看他寫。他手不停筆。他寫南昌的地理、寫在座的人物、寫這座樓的歷史。他寫著寫著，抬頭看窗外——滕王閣面對贛江，那天夕陽正在江面上燒。

他寫下這句：

落霞與孤鶩齊飛，秋水共長天一色。

下人跑出去報告。閻伯嶼聽到——愣住了。他站起來自己衝進宴會廳。

他站在子安身後看他繼續寫。子安寫完全篇六百多字的駢文。閻伯嶼當著所有人的面說了一句——此真天才，當垂不朽矣！

一個原本準備讓女婿展才華的宴會，變成了一個路過書生的封神時刻。

子安寫完這篇序，繼續南下去看父親。第二年他回程時，坐船在南海遇到風浪，掉進海裡淹死了。他這輩子只活了二十六歲（一說二十七歲）。

一個少年在滕王閣的即席表演，成了他這輩子留下的最重要的一件事。

千年後你去南昌，還可以看到重修的滕王閣。閣裡最顯眼的位置刻著他寫的那兩句。一個二十六歲的少年在酒宴上寫下的兩行字，成了那座樓永遠的名片。`
  },

  // id=430 南唐 李煜 〈虞美人-春花秋月何時了〉rating=6
  // 詩眼：亡國君的絕命詞——他寫完就被毒死
  // 隱藏連接：978年七夕、42歲生日當天寫下這首詞，當晚宋太宗把他毒死
  430: {
    title: "虞美人-春花秋月何時了",
    author: "李煜",
    summary: "他一輩子當皇帝當得不好，可是他寫詞寫得比誰都真。他把「愁」寫成一條可以量的東西——一條長江。他寫完當晚，被毒死了。",
    story: `跟你說一個亡國君的絕命詞。這是宋太平興國三年（九七八年）七月七日七夕節。這一天是南唐後主李煜的四十二歲生日。他在汴京（今開封）當俘虜已經三年了。

三年前（九七五年）宋軍攻破金陵（今南京），李煜奉表投降，被押到汴京。宋太祖趙匡胤還算給他面子，讓他當一個象徵性的「違命侯」，關在一座小樓裡。可是宋太祖去世後，宋太宗趙光義即位。趙光義對這個亡國君越來越不耐煩。

李煜在這座小樓裡過了三年。三年裡他寫了很多詞。他不能寫政治，就寫感情。他不能寫國家，就寫夢。他把亡國之痛寫進每一首詞裡。宋太宗看到他的詞越來越不高興。

那天是他的生日，也是七夕節。夜裡東風吹起——春天已經來了，可是他的心裡是冬天。他站在小樓上，望向南方——金陵的方向。

他想起自己曾經的皇宮。那些雕花的欄杆、玉砌的臺階應該還在。可是他知道自己再也回不去。他自己也變了——他從一個穿黃袍的皇帝，變成了一個穿囚衣的俘虜。他四十二歲，鬢角已白，臉色蒼老。

他坐下來寫詞。他把自己一輩子的痛揉在一個問句裡——你問我心裡有多少愁？就像整條長江的春水，往東流，永遠流不完。

他寫下的是這樣一首詞：

春花秋月何時了？往事知多少。小樓昨夜又東風，故國不堪回首月明中。雕闌玉砌應猶在，只是朱顏改。問君能有幾多愁？恰似一江春水向東流。

寫完他叫下人把詞唱給他聽。他自己愛音樂，愛到亡國前一天還在寫曲子。這首詞的曲調叫「虞美人」——傳說中虞姬臨死前為項羽跳的舞。

當晚宋太宗聽到人回報這首詞。他冷冷地說了幾個字——「小樓昨夜又東風」、「故國不堪回首」，這是要復國嗎？

宋太宗下令把李煜毒死。七月七日，這一天是他的生日，也是他的死日。他四十二歲。

他一輩子當皇帝當得不好，可是他寫詞寫得比誰都真。他把「愁」寫成一條可以量的東西——一條長江的水。從今以後每一個人的「愁」，都有了大小。

千年後這首詞還在。可是李煜當年小樓裡的那條東風，早就吹過去了。`
  },

  // id=440 北宋 蘇軾 〈定風波〉rating=6
  // 詩眼：雨中繼續走的悟——也無風雨也無晴
  // 隱藏連接：1082年黃州流放第三年、他寫出一輩子最重要的一次悟
  440: {
    title: "定風波",
    author: "蘇軾",
    summary: "三月裡跟朋友春遊突然下雨。朋友都躲雨去了。子瞻繼續走——他還一邊唱歌一邊走。這場雨讓他悟出他這輩子最重要的一件事。",
    story: `跟你說我朋友子瞻一個下雨的下午。這是宋神宗元豐五年（一〇八二）三月七日。子瞻此時四十五歲，被流放到黃州（今湖北黃岡）已經三年了。

那天他跟幾個朋友一起出門去看春天。他們沒帶雨具——三月的天氣有點涼但看起來不會下雨。他們走到沙湖道上，離黃州城不遠。

天忽然變了。大風吹起來，穿過樹林。雨開始打在葉子上，一聲一聲。

朋友們都跑起來找地方躲雨。他們往路邊的樹底下鑽，往農家門廊底下擠。他們一邊跑一邊叫子瞻——快跑！

子瞻沒跑。他在雨裡繼續走。他甚至還唱起歌來——他一邊淋雨一邊吟嘯，慢慢地走。

朋友們躲在遮雨處看他這個瘋樣子，都不敢相信。

子瞻穿的是最簡單的一雙芒鞋（草鞋）、手裡拄著一根竹杖。他此刻沒有官職，沒有馬車，沒有隨從。他一貧如洗。可他覺得竹杖芒鞋比騎馬還輕鬆。他有什麼好怕的？他這輩子最壞的事已經發生了——他坐過牢、差點被砍頭、被貶到這個沒人搭理的黃州。現在下點雨算什麼？

他繼續走。雨一直下。他一件蓑衣就任這場煙雨過完他這輩子。

過了一會兒，雨停了。春天的冷風把他喝過的酒都吹醒了。他覺得有點冷。抬頭一看——遠處的山頭，夕陽正好照過來。

他回頭看剛才走過的路——那條剛剛還在下雨、颳風、蕭瑟的路，現在什麼都沒有了。他忽然想通——這條路上剛才有風雨，現在有陽光。可是對他來說，剛才那場雨沒讓他停下來，此刻這片陽光也不會讓他多開心。他還是他。

他回家寫下這首詞：

莫聽穿林打葉聲，何妨吟嘯且徐行。竹杖芒鞋輕勝馬，誰怕？一蓑煙雨任平生。料峭春風吹酒醒，微冷，山頭斜照卻相迎。回首向來蕭瑟處，歸去，也無風雨也無晴。

「也無風雨也無晴」——這是他這輩子最重要的一次悟。人生的順境跟逆境都不重要。重要的是你這個人自己怎麼走。順境不必得意。逆境不必消沉。走過去了，回頭看，都是雲淡風輕。

子瞻寫這首詞的時候是黃州流放的第三年。他之後還會被再貶兩次——貶到惠州、貶到儋州。他每一次都用「也無風雨也無晴」的心態走過去。

千年後每個中年人在挫敗中讀這首詞，都能借他這一場雨繼續走。`
  },

  // id=447 南宋 李清照 〈如夢令-昨夜雨疏風驟〉rating=6
  // 詩眼：一個被愛的女子雨後宿醉早晨的細膩觀察
  // 隱藏連接：這是她少女／少婦時期的幸福時光，之後她會失去一切
  447: {
    title: "如夢令-昨夜雨疏風驟",
    author: "李清照",
    summary: "她剛睡醒，宿醉未消，第一件事是問窗外那棵海棠怎樣了。她只有一個答案是對的：綠肥紅瘦。這是被愛的女子才有的細膩。",
    story: `跟你說我朋友清照少女時代的一個早晨。

清照（李清照）出生在宋代最富貴的一個書香家庭。父親李格非是蘇軾的門生，母親出身進士世家。她從小讀書，寫詩填詞，樣樣精通。她十八歲那年嫁給了金石學家趙明誠，兩人志趣相投，感情極好。

這首〈如夢令〉大約寫在她少女或少婦時期，日子過得非常幸福的階段。

那年春天某個晚上——大概三月——她跟明誠一起喝酒。窗外開始下雨，是那種疏疏落落的春雨，雨點不密但是配著大風。她喝多了。她也不怕。她跟明誠繼續喝，聊他們新買的一件金石拓片。

那晚她睡得很沉。深夜的疏雨跟大風她都沒醒。

第二天早晨她醒了。太陽已經高了。她頭有點疼——昨晚的酒還在。她躺在床上不太想動。

丫鬟進來，把窗簾捲起來。陽光一下照進屋子。她瞇著眼看外面。

她忽然想到——昨晚下了那麼大的雨，院子裡那棵海棠怎樣了？

海棠是她家院子最重要的一棵樹。前幾天花才剛開，一整樹粉紅色，她跟明誠每天在院子裡坐著看。

她問丫鬟——外面的海棠怎樣了？

丫鬟往窗外一看，隨口回答——照舊。

清照心裡搖頭。她知道丫鬟根本沒仔細看。她告訴自己——你不懂。經過昨晚那場雨，海棠一定不會照舊。花瓣被打落了。應該是葉子綠得更多、花瓣紅得更少——綠肥紅瘦。

她起身寫下這首詞：

昨夜雨疏風驟，濃睡不消殘酒。試問卷簾人，卻道海棠依舊。知否，知否？應是綠肥紅瘦。

她寫的其實不是海棠，是她自己的細膩。世界上真的關心一朵花的人，會知道雨後那朵花變成什麼樣。世界上真的關心一個人的人，會知道對方臉上表情最細微的變化。

她此刻不知道自己這輩子後半段會有多慘。她二十六歲後北宋就滅亡了，她跟明誠南逃。四十六歲那年明誠病逝。她此後獨自漂泊南宋，一輩子沒能真的安定下來。

可是這個「昨夜雨疏風驟」的早晨，是她一生最好的時光之一。她躺在床上，宿醉未醒，關心院子裡一朵花。這種細膩，是幸福才有的細膩。

千年後每個心思細膩的女人讀這首詞，都能懂那個早晨的清照——她其實是在說：我看得懂這朵花，是因為我還在被愛。`
  },

  // id=456 南宋 辛棄疾 〈青玉案-元夕〉rating=6
  // 詩眼：在人群喧鬧中找到一個「不隨流俗」的靈魂
  // 隱藏連接：辛棄疾一輩子在主戰派主和派之間找共鳴，那人就是他自己
  456: {
    title: "青玉案-元夕",
    author: "辛棄疾",
    summary: "全臨安最熱鬧的一夜，他在人群裡找一個人。他找了千百次沒找到。回頭一看——那人在燈火最冷清的角落。那不是他愛的人，是他自己。",
    story: `跟你說我朋友幼安（辛棄疾）某個元宵夜的故事。

幼安是南宋最強硬的主戰派詩人。他二十二歲那年在山東組織義軍抗金，親自帶五十人衝進五萬人的敵營抓叛徒，把叛徒生擒回南宋朝廷。那年他名震江南。南宋朝廷本以為他會成為抗金主力——結果沒有。他被派去當地方官，一路東調西調，一輩子沒被真正重用。因為朝廷主和派當道。

這首〈青玉案·元夕〉大約寫在他人生中期，人在南宋首都臨安（今杭州）。元宵節那天晚上，整個臨安張燈結彩。他一個人走進燈會。

那晚的臨安美到不像話。東風把樹上的花燈一朵一朵吹亮，像千棵樹在夜裡同時開花。天上時不時放煙火，像星星從天上掉下來，一夜下不完。街上到處是寶馬拉的雕花馬車，車裡的貴族小姐擦著香水，整條街都飄香。鳳形簫在吹，玉壺形狀的燈籠在轉，河邊有人扮成魚龍在跳舞。

這是南宋最熱鬧的一夜。

幼安在人群裡走。他看見身邊女子頭上戴著蛾形的、雪柳形狀的、黃金絲繡的髮飾，一路笑著、聊著、香氣一路飄過去。

幼安一直在找一個人。

不是他的妻子。不是他的朋友。是某個他也說不清楚的人。他不知道那個人是誰、長什麼樣，可是他覺得——今夜這座城裡，一定有那麼一個跟他一樣的人。也不歡呼、也不融入、也在人群裡默默走。

他找了千百遍。他從燈最亮的地方走到人最多的角落。都沒看見。

他忽然停下來，轉頭回望——那人就在那裡。在整座燈會邊緣、燈火已經稀落下去的一個角落，一個人站著。

那個人是誰？沒人知道。也許是他心裡另一個自己。他一輩子在主戰派跟主和派之間、在朝廷跟江湖之間、在熱鬧跟孤獨之間找。他找的是那個「不隨流俗」的靈魂——而那個靈魂總是在最冷清的角落。

他寫下的是這樣一首詞：

東風夜放花千樹，更吹落，星如雨。寶馬雕車香滿路。鳳簫聲動，玉壺光轉，一夜魚龍舞。蛾兒雪柳黃金縷，笑語盈盈暗香去。眾裡尋他千百度，驀然回首，那人卻在，燈火闌珊處。

幼安這輩子沒能真的收復北方。他晚年被貶回江西上饒鄉間，寫詞、種田、喝酒。他六十八歲那年病重，臨終前大喊——殺賊！殺賊！他到死都沒能上戰場。

可是他留下了這首詞。千年後每一個在人群裡找不到共鳴的人、每一個不隨流俗的靈魂——都能在燈火闌珊處找到自己。`
  },

  // id=457 南宋 辛棄疾 〈醜奴兒-書博山道中壁〉rating=6
  // 詩眼：五十歲的老兵在牆邊想寫盡半生的愁，最後只寫得出一句「天涼好個秋」
  // 隱藏連接：二十歲那個在濟南城樓上強說愁的少年，跟三十年後這面白牆前的自己隔空對望
  457: {
    title: "醜奴兒-書博山道中壁",
    author: "辛棄疾",
    summary: "半生的愁塞在喉嚨裡，最後只吐出一句天氣真好。",
    story: `跟你說我朋友幼安五十歲那個秋天。他站在博山道旁一面白牆前，手裡一支毛筆，蘸好了墨，遲了好一會沒下筆。旁邊隨從有點慌——這可是辛棄疾啊，二十二歲率五十騎衝進五萬金兵大營、活捉叛徒張安國那個辛棄疾，走到哪裡都被人求題字。這面牆這麼白，路過的人這麼多，他怎麼站著不動？

風有點涼。牆邊幾棵樹，葉子已經開始落。他抬頭看天，天很高，藍得乾淨。他手上那點墨快乾了，自己都沒發覺。

三十年前他不是這樣的。十六七歲的時候，他在濟南跟一群年輕人喝酒，喝完就爬城樓，爬到最高那層倚著欄杆往北看。那時候北方在金人手裡，他們一心想打回去。他寫過詩，寫過詞，寫過一堆連自己都覺得肉麻的愁——什麼西風落葉，什麼白髮愁生，那時他頭髮還黑得發亮。他就是覺得要寫詞嘛，總要有點愁；愁不夠就擠一擠往紙上寫。他跟朋友還會比誰的愁寫得更狠。二十歲的男孩子，就是這樣。

後來他真的率五十人衝進金營了。後來他真的南歸了。後來他一次又一次上書要收復北方，一次又一次被派去別的地方——去湖南剿匪，去江西賑災，去福建整理鹽務。他四十二歲被彈劾罷官，退到江西上饒帶湖邊蓋了間屋子，叫稼軒。他學種田，學釀酒，看鵝在池塘裡走。偶爾出來遊山，走著走著就走到博山。

這面牆他其實路過好幾次了。今天他忽然想寫點什麼。隨從把筆墨備好，等著看他寫什麼驚天動地的東西。

可是他站在那裡，一句話都寫不出來。他這輩子攢了太多愁。北方到現在還沒回來。當年跟他一起衝金營的兄弟，一半死了，一半散了。朝廷用他，是把他當一個好用的地方官；不用他，就把他扔在山裡。他五十歲了，頭髮白了，膝蓋也不好了。他想寫殺賊，想寫金戈鐵馬，想寫那些死掉的兄弟的名字——他張了張嘴，又閉上。話堵在喉嚨裡，一個字都吐不出來。

他最後提起筆，蘸了墨，在牆上寫下：

少年不識愁滋味，愛上層樓。愛上層樓，為賦新詞強說愁。而今識盡愁滋味，欲說還休。欲說還休，卻道天涼好個秋。

寫完他把筆遞回隨從手裡，看了一眼天，說走吧。隨從跟在後頭，一路都想不明白——這麼強的一個人，寫愁怎麼寫成這樣？

那面牆後來當然被風雨淋過、被別人抹過，字早就沒了。幼安六十八歲病重臨終，躺在床上大喊了三聲殺賊，那三個字是他一輩子沒喊夠的。他到死都沒能上戰場。可是博山道邊那個秋天下午，他咽下去的那一整口氣，變成了千年之後每一個真的懂了什麼叫愁、卻怎麼也講不出來的人——嘴邊那一句「天氣真好」。`
  },

  // id=459 南宋 岳飛 〈滿江紅〉rating=6
  // 詩眼：三十幾歲的將軍站在雨後樓閣上，仰天長嘯前那一口還沒吐出來的氣
  // 隱藏連接：他 24 歲親眼看過汴京淪陷，十幾年後在南方樓上還在想那條回不去的路
  459: {
    title: "滿江紅",
    author: "岳飛",
    summary: "三十幾歲的將軍在雨後的欄杆邊，把一口壓了十幾年的氣，一次吐出來。",
    story: `跟你說我朋友鵬舉的一個下午。他站在鄂州一座樓上，欄杆是溼的，剛下過一場很大的雨。他的頭髮被風吹得亂七八糟，連將軍的帽子都吹歪了，可是他沒有動手去扶。他就這樣站著，看著雨後的江面發呆，看了很久很久。跟他一起上樓的隨從遠遠站著不敢過去，因為這個平常話不多的將軍，這一刻臉色沉得像鐵，眼睛死死盯著北方，一個字都沒說。

那年鵬舉三十幾歲。他從軍十幾年了，他帶的那支部隊叫岳家軍，金人聽到都會退兵三十里。他打過的仗自己也數不清，功名、勳章、朝廷賜的宅子和錢，對他來說都跟這場雨後的塵土差不多，濕了就成泥，乾了風一吹就散。他真正記得的，是這十幾年他從南到北、又從北到南，加起來八千里的路，路上見過的雲、走過的月光下的營地、還有一個個問他什麼時候能回家的士兵。他總是想著北方。他二十四歲那年，就是在北方。汴京被金兵攻破的那一年，他親眼看見兩位皇帝被押著往北走，親眼看著自己的家鄉相州淪陷。徽宗、欽宗，兩個皇帝被裝在牛車上運去五國城，從此再沒回來。十幾年了，那條路一直橫在他心裡。他今天站在這座樓上，其實想的還是那條路怎麼走回去。

他忽然抬起頭，仰著臉朝天叫了一聲。那一聲很長。隨從嚇了一跳，可是鵬舉沒理他。他走到欄杆邊，從懷裡掏出紙筆，就著欄板寫下去：怒髮衝冠，憑欄處，瀟瀟雨歇。抬望眼，仰天長嘯，壯懷激烈。三十功名塵與土，八千里路雲和月。莫等閒，白了少年頭，空悲切。靖康恥，猶未雪。臣子恨，何時滅。駕長車踏破，賀蘭山缺。壯志飢餐胡虜肉，笑談渴飲匈奴血。待從頭，收拾舊山河，朝天闕。

他寫完看了一眼自己的鬢角，那裡真的已經有一根白頭髮了。他今年才三十幾歲，可是頭髮已經開始白。他想到自己再不打回去，這根白髮就會變成一頭白髮，那時候恨也沒用了。雨後的欄杆很快又乾了。鵬舉三十九歲那年，被秦檜以莫須有的罪名下獄，死在臨安風波亭。他到死沒能踏過賀蘭山缺，沒能把那條八千里路走完，沒能替兩位皇帝雪那個靖康的恥。可是那個雨後的下午，他一個人站在鄂州樓上仰天嘯出來的那口氣，八百多年還在。每一個看見不公不義、自己卻打不動的人，心裡都有那一口氣憋著。`
  },

  // id=463 元 馬致遠 〈天淨沙-秋思〉rating=6
  // 詩眼：中年男子牽著瘦馬走過別人家門口，卻不能進去
  // 隱藏連接：他年輕時在大都追過功名，這條古道是他一次次奔波後某個秋日的具體場景
  463: {
    title: "天淨沙-秋思",
    author: "馬致遠",
    summary: "他站在小橋這邊，看著別人的家，看了很久很久。",
    story: `跟你說我朋友致遠的一個黃昏。他牽著一匹瘦得肋骨看得見的馬，走在一條沒什麼人的古道上，走了大半天。他不是不想騎，是那匹馬也累了，他捨不得。西風一陣一陣吹過來，把他的袍角、馬的鬃毛、路邊的枯草都往同一個方向吹。他抬頭看了看天，太陽已經下到山邊，再走一段就要天黑了。可是這一路他都沒看見一個能住的地方。

致遠今年四十幾歲了。他年輕的時候也曾經在大都跑過幾年，寫過幾齣戲，交過幾個朋友，據說還在江浙行省當過一段時間的小官。可是元朝這種局面，一個漢人讀書人能爬到哪裡，他自己心裡清楚。他這幾年多半時間都在路上，從這個州到那個州，去求人、去謀事、去看看能不能替家裡多掙一點。這條古道他不是第一次走了，走到後來，他已經分不清是自己在走路，還是路在推著他往前走。道路兩旁的老樹都長了幾百年，樹上纏著的枯藤黑得像老人手背上的青筋，樹枝上停著幾隻昏鴉，看見他走過來也懶得叫一聲。他和那幾隻烏鴉互看了一眼，都沒說話，因為他們知道彼此都累了。

他往前又走了一段，忽然聽見流水的聲音。他抬頭一看，前面有一座小橋，橋那邊有兩三戶人家，屋頂上飄著炊煙。有個婦人正在門口喊小孩回家吃飯，聲音很尋常，可是致遠聽到的時候，忽然站住了。他站在橋這邊，看著橋那邊的人家，看了很久。他知道自己不能過去。那不是他的家。他的家在很遠很遠的地方，他這輩子恐怕都回不去了。他牽著那匹瘦馬，就這樣站在夕陽底下，站成了一個影子。他想，如果有人此刻從遠處看他，一定會覺得他很像一幅畫，一幅誰都不會想活在裡面的畫。

那個瞬間他心裡有個聲音自己冒出來：枯藤老樹昏鴉，小橋流水人家，古道西風瘦馬。夕陽西下，斷腸人在天涯。他沒有紙，就在心裡默念了一遍。他知道這幾句以後會變成什麼樣的東西，可是那不重要。重要的是他把這個下午留下來了，把這條古道、這座小橋、那幾隻烏鴉、這匹瘦馬、還有站在橋這邊的自己，都留下來了。他覺得如果哪一天真的走不動了，至少還有人能透過這幾句話，看見他今天站的位置。

太陽終於落到山後面去了。致遠拍了拍馬的脖子，牽著牠繼續往前走。他還沒找到今晚可以睡覺的地方。那座小橋、那戶人家、那縷炊煙，很快就被他甩在身後了。相傳致遠後來活到七十歲，晚年隱在杭州，據說算是善終。可是他這個秋天的黃昏，這個站在別人家門口卻不能進去的中年男人，七百多年來一直站在那條古道上，替所有離家太久、還沒走到頭的人，站著。`
  },

  // id=464 明 楊慎 〈臨江仙-滾滾長江東逝水〉rating=6
  // 詩眼：曾經站在權力最中央的六十歲老頭，被一個不認識他的老漁夫遞來一壺酒，忽然明白自己已經是江邊看戲的人了
  // 隱藏連接：這闋詞原本是《廿一史彈詞》的開場，一百多年後才被毛宗崗父子搬到《三國演義》第一頁
  464: {
    title: "臨江仙-滾滾長江東逝水",
    author: "楊慎",
    summary: "六十歲的老狀元在雲南江邊，被不認識他的漁夫遞來一壺酒",
    story: `跟你說我朋友用修的一個下午。他六十好幾了，坐在雲南永昌衛外一條大江的江邊，白頭髮被江風吹得亂七八糟，膝蓋上橫著一根竹杖。你可能想像不到，這個曬得黝黑、腳上還沾著紅泥的老頭，年輕時是整個大明帝國的狀元。二十四歲那年殿試第一，授翰林院修撰，父親楊廷和是內閣首輔，用修自己隨手一篇文章能傳遍京城茶樓。他那時候騎著馬進宮，覺得這條路他會走一輩子。

然後嘉靖三年，那場左順門的哭諫發生了。新皇帝硬要把自己的生父追封為皇帝，用修帶著兩百多個大臣跪在宮門外磕頭磕到血流滿面。皇帝一怒之下，把這批人全部拖出去廷杖。用修被打了兩次，一共三十九棍，差點沒了命。醒過來的時候，他已經被判永遠戍守雲南永昌衛。那年他三十七歲。從三十七到今天，中間過了二十多個年頭，北京再也沒有召他回去過。父親過世那次朝廷特准他回家奔喪，喪事一辦完又被押回雲南，一次都沒有例外。

這個下午，他沿著江渚慢慢走，看見一個老漁夫和一個老樵夫並排坐在江灘上，兩個人共用一壺酒，看見他走過來，笑咪咪地招手叫他一起喝。用修在那壺濁酒前面坐了下來，喝了一口，發現那漁夫根本不認識他是誰，也不在乎他從前是誰。兩人只跟他聊今年江水漲得早、秋天山上什麼野果熟了、村口誰家的女兒嫁給了誰。江水就在他們腳邊嘩啦嘩啦地流，一浪推著一浪往東去。用修抬起頭，看見對岸的青山還是二十年前那個樣子，夕陽正紅得像燒著，晚風掀動他花白的頭髮。他忽然明白過來，這一輩子他一直以為自己是舞台上的那個人，其實他早就是江邊看戲的人了。

那天夜裡回到住處，他正在編《廿一史彈詞》，寫到說秦漢那一段的開場，就把江邊那壺酒寫了進去：滾滾長江東逝水，浪花淘盡英雄。是非成敗轉頭空。青山依舊在，幾度夕陽紅。白髮漁樵江渚上，慣看秋月春風。一壺濁酒喜相逢。古今多少事，都付笑談中。七十一歲那年，用修死在雲南，沒能回到北京。一百多年後，毛宗崗父子在整理《三國演義》，把這闋詞放到全書第一頁。從此每個翻開三國的人，第一眼看見的都是他那個下午——那個坐在江渚上、和不認識他的漁夫共喝一壺酒的六十幾歲老頭。`
  },

  // id=5 漢 佚名 〈長歌行〉rating=5
  // 詩眼：小時候聽母親哼過的那個調子，多年後躺在病中才聽懂
  // 隱藏連接：漢代採詩官把這首民間歌謠記進樂府，作者的名字沒能留下，但那個下午留了下來
  5: {
    title: "長歌行",
    author: "佚名",
    summary: "沒有留下名字的漢代母親，把一首歌唱進兒子的骨頭裡",
    story: `跟你說一首漢代歌謠的來歷。它沒有作者的名字，只留下這樣一個早上。關中鄉下一個男孩，蹲在自家菜畦邊，看著葉子上的水珠往下滑。他大概八九歲，被母親叫起來澆水，一邊揉眼睛一邊往園子裡走。母親蹲下身撥開一片葵葉，指給他看：你看，這一顆一顆的，太陽一出來就沒了。男孩摸了摸，指尖涼涼的，過一會兒真的乾了。

母親一邊拔草一邊哼一段調子。那調子沒有名字，是她小時候聽外婆哼的，外婆又是聽誰哼的，早就沒人記得。哼到某個轉折的地方，她會拉長聲音，把一整片葵葉都唱得晃起來。男孩不太懂歌詞，只覺得那節奏跟母親手裡的動作對得上，一下拔草，一句歌。那時候是三月，田埂邊的草綠得發亮。母親說，這叫陽春，一年裡最好的日子，你看什麼都在長。

到了七月，園子換了個樣子。葉子從綠變成黃，邊緣捲起來像烤焦的餅皮，母親順手把枯掉的一整枝拔起來丟在牆角。男孩追問，那不是還在長嗎？母親沒回答，只是又哼起那個調子，這一段比之前的沉一點。傍晚父親從田裡回來，聽見她哼，接了下一句，男孩才知道這歌不是母親一個人的，村裡上了年紀的人都會。有的人多哼秋葉枯黃那一段，有的人多哼江河東流那一段，誰哼哪一段，跟誰過了什麼日子有關。

男孩十二歲那年，跟著父親去河邊挑水。那條河是渭水的支流，一路往東流，父親說再往下幾百里就進黃河，再往下就到海。男孩問，河水到了海還會回來嗎？父親說不會，往東的水沒有一滴回頭的。他忽然想起母親那個調子裡好像就有這一句，回家的路上小聲哼了一遍，母親在灶邊笑他，說你這年紀哼這一句還太早。

真正聽懂是很多年以後。他已經四十幾歲，母親走了七年，自家的葵園是他兒子在照顧。那年秋天他病了一場，躺在炕上，聽見院子裡兒子在澆水，忽然聽見兒子哼那個調子，哼得七零八落，只有頭兩句像樣。他躺著沒動，眼淚就順著鬢角流下去，想起三月那個早上，母親撥開葉子指給他看朝露的樣子。他一輩子沒去過京城，沒讀過幾個字，可是他忽然懂了，歌裡那個少壯不是別人，就是那個蹲在菜畦邊沒把母親的話聽進去的小孩。

漢朝有一批人叫採詩官，朝廷派他們到各郡各縣，把民間傳唱的歌謠記下來帶回長安。這首歌被哪一個採詩官記進竹簡的，沒人知道，只知道最後收進了樂府，題目叫長歌行：青青園中葵，朝露待日晞。陽春布德澤，萬物生光輝。常恐秋節至，焜黃華葉衰。百川東到海，何時復西歸？少壯不努力，老大徒傷悲。記歌的採詩官沒了名字，哼歌的母親也沒了名字，可是兩千年後的今天，還有人在早上看見葉子上的水珠往下滑，會突然想起這幾句。那個蹲在菜畦邊的小孩，成了每一個聽過這首歌的人。`
  },

  // id=14 盛唐 李白 〈關山月〉rating=5
  // 詩眼：沒去過玉門關的李白，替戍客與思婦寫下同一夜的兩個月亮，也替自己寫
  // 隱藏連接：他二十五歲出川再沒回過家，「不見有人還」寫的也是他自己
  14: {
    title: "關山月",
    author: "李白",
    summary: "沒到過邊塞的他，替戍客與思婦寫下同一夜的月亮",
    story: `跟你說我朋友太白這一夜。他人在長安，翰林院發下來的差事做完了，晚上被人拉去參加一場小宴。席上樂師抱著琵琶唱樂府舊題，唱到一半，他抬頭看窗外的月亮，就決定要重寫一首同名的歌。這首舊題叫關山月，從漢代唱到唐代，唱的都是戍邊士兵想家。太白這輩子沒去過玉門關以西，甚至沒摸過河西走廊的沙子，但這一夜他決定寫，寫給那些沒辦法替自己開口的人。

樂師還在唱，他叫僕人拿紙拿墨，就在席邊鋪開。他閉上眼睛，開始在腦子裡搭那個場景。他先讓月亮從天山後面升起來，那是西邊很遠的一座大山；月光升到某個高度，底下就是連綿的雲海，一片一片壓在祁連山北。他讓一陣長風從東邊起，一路吹過幾萬里，翻過雪嶺、掠過驛道，最後撞到玉門關的城樓上。玉門關是關內和關外的分界線，過了那道關，就是漢唐幾百年打不完的戰場。他順手把兩個舊戰場也擺進去：漢高祖被匈奴圍困七天的白登、還有這幾年老聽人提起的青海灣。這些地方，他一個也沒真的到過，但從史書上、從邊塞回來的老兵嘴裡，他把每一寸地都聽熟了。

寫到一半他停下來。他忽然想到一件事：自己也是二十五歲那年離開四川，這麼多年了，一次都沒回去。他也是那個「不見有人還」的另一個版本，只是他打的不是仗，是自己的名聲、自己的抱負。他這才懂了那個蹲在玉門關城牆下的士兵，那個人此刻正抬頭看同一個月亮，臉上滿是想回家的苦。同一夜，士兵家鄉的高樓上，他的妻子也在望月，一聲聲嘆息壓在夜裡沒斷過。太白替他們把這一整段夜寫下來：明月出天山，蒼茫雲海間。長風幾萬里，吹度玉門關。漢下白登道，胡窺青海灣。由來征戰地，不見有人還。戍客望邊色，思歸多苦顏。高樓當此夜，嘆息未應閒。

樂師那邊還在唱舊詞，他把新寫的這一首收起來，沒交給樂師，也沒拿去給玄宗看。他只是把它放在自己的稿匣裡，像是替那些沒法發聲的戍客、替那些整夜嘆息的妻子、也替二十五歲就離家再沒回過頭的自己，留了一份收據。一千三百年過去，玉門關的城牆早垮了，白登和青海灣也不再打仗了，可是每一個離家很遠的人，深夜一個人抬頭看月亮的時候，還是會忽然想起有個叫李白的人，替他們把這件事先說過了。`
  },

  // id=19 盛唐 李白 〈俠客行〉rating=5
  // 詩眼：雨夜旅館裡讀史記讀到拔劍起舞的少年，把自己寫成朱亥身邊那個舉杯的人
  // 隱藏連接：太白從十五歲就練劍，行囊裡的吳鉤與史記是他當時全部的家當
  19: {
    title: "俠客行",
    author: "李白",
    summary: "少年李白讀史記讀到坐不住，拔劍舞了一陣，把自己寫進信陵君那場酒席。",
    story: `跟你說我朋友太白年輕時的一個晚上。他住在洛陽城外一間便宜旅館，行囊裡只有兩樣東西，一柄劍，一套翻爛了的史記。他二十幾歲，還沒進長安，還沒見過玄宗，還沒被人叫「謫仙」。他只是一個從四川一路東遊、四處找機會的年輕人，白天騎著匹瘦馬在街上晃，晚上回旅館點一盞油燈讀書。這一夜他讀到信陵君列傳。

他其實已經讀過很多遍了，可是這回讀到朱亥揮鎚的那一段，忽然坐不住。窗外正好下著細雨，屋簷滴水，他把書往桌上一擱，起身把牆角那柄劍拔了出來。這劍是他十五歲就開始練的吳鉤，磨得亮，燈下一晃像刷了一層霜雪。他在那個不到三坪的小房間裡舞了一陣，出手很快，落腳很輕，僕人在門外聽見金屬破空的聲音，探頭看了一眼又縮回去。他舞到滿頭汗，才把劍插回鞘裡，坐下重新翻開那一頁。

他讀的那一段，是秦國圍邯鄲、趙國向魏國求救，魏王膽小按兵不動。信陵君的門客侯嬴出了個主意，找來屠戶朱亥，一柄鐵鎚打死魏將晉鄙，硬把兵權奪過來救趙。這件事在史記裡不過幾百字，可是太白讀了心臟砰砰跳。他想，如果換成是他，他也會跟朱亥一起吃那頓烤肉，也會替侯嬴斟那杯酒，三杯下肚就把命交出去。他甚至在腦子裡把自己塞進那場酒席：他把劍解下來橫在膝上，坐在信陵君旁邊，朱亥切一塊烤肉丟過來，他接住咬一口，回手替侯嬴斟酒。這一刻他覺得自己也是那個穿胡纓的趙國俠客，銀鞍白馬像一顆流星從街上馳過，十步之內取人性命，事情辦完拂拂衣服就走，連名字都不留。

心裡那口氣壓不住了。他鋪好紙，磨好墨，一氣呵成寫下去：趙客縵胡纓，吳鉤霜雪明。銀鞍照白馬，颯沓如流星。十步殺一人，千里不留行。事了拂衣去，深藏身與名。閒過信陵飲，脫劍膝前橫。將炙啖朱亥，持觴勸侯嬴。三杯吐然諾，五嶽倒為輕。眼花耳熱後，意氣素霓生。救趙揮金鎚，邯鄲先震驚。千秋二壯士，煊赫大梁城。縱死俠骨香，不慚世上英。誰能書閣下，白首太玄經。最後兩句他寫得特別用力。太玄經是漢代揚雄關在書齋裡寫了一輩子的大書，是讀書人心裡的功名頂點。太白偏偏挑這個來嗆，白頭埋在那樣一部書底下，跟朱亥揮鎚救趙的那一夜比起來，算什麼？

寫完他把筆一擱，油燈快燒到底了。他沒把這首詩投給誰，就這麼收進行囊，第二天繼續往東走。那一年他還沒進長安，還沒被高力士脫過靴，還沒在流放夜郎的船上遙望三峽。他只是一個年輕人，在一個下雨的夜晚，讀到千年前一場俠義救國的故事，就相信自己有一天也能像朱亥那樣，把手裡這柄吳鉤揮出去，替天下辦一件真正的大事。這個夜晚他寫下的畫面，一千三百年後還在替每一個心裡藏著俠客夢的少年，把那口氣撐著。`
  },

  // id=22 盛唐 杜甫 〈望嶽〉rating=5
  // 詩眼：二十四歲的杜甫在山下對自己說「我一定會登頂」——一句年輕預言，撐住他一輩子沒兌現的人生
  // 隱藏連接：三十年後的〈旅夜書懷〉「天地一沙鷗」與此刻站在山下的少年遙相對照
  22: {
    title: "望嶽",
    author: "杜甫",
    summary: "苦哈哈的老杜，二十四歲那年還相信自己會凌絕頂",
    story: `跟你說我朋友子美——後來大家熟的那個滿臉憂國憂民的老杜——他二十四歲那年，站在泰山腳下抬頭望山的時候，臉上完全沒有後來那副表情。那時他剛從洛陽的進士考場摔了一跤，可是他一點也不覺得那算什麼。他祖父是武則天朝寫詩最紅的杜審言，家裡書堆到天花板，他自己十四五歲就在洛陽文人的酒席上被誇是神童。落一次榜？他覺得自己還早得很。

考完他沒回鞏縣，直接往東北走，一路晃到齊、魯這一帶。那個年紀的他還很輕，包袱裡塞著幾件換洗衣裳、一疊詩稿、幾兩銀子，就這麼跟同齡的朋友在山東平原上騎馬打獵、寫詩喝酒，一混就是好幾年。有一天他跟一個朋友從兗州往北走，走著走著，遠遠地在地平線那頭看見一團青綠色。朋友先開口：那就是岱宗。子美勒住馬，沒說話，就那麼抬著頭看。整個齊、魯大地，從他們腳下一路鋪到山腳，青色的田、青色的丘、青色的樹林，一望無際，全是被那座山染出來的。天光從山脊上劈下來，山陽那面亮得刺眼，山陰這面卻還壓著昏黃的雲，同一座山硬是把白天和黃昏切成兩半。

朋友在旁邊問他：老弟，你將來想幹嘛？子美這才把眼神從山頂挪下來。他看著朋友，笑了一下，說：等我哪一天，一定要上到那個最高的地方，站在絕頂上往下看，看四周所有的山，都變得小小的。朋友被他嗆得一時說不出話。當晚他們在山下的客棧歇腳，他掏出紙筆，趁著那口氣還在，一氣寫下去：岱宗夫如何？齊魯青未了。造化鍾神秀，陰陽割昏曉。盪胸生層雲，決眥入歸鳥。會當凌絕頂，一覽眾山小。他寫的時候，胸口那團雲還在翻，眼睛盯著窗外幾隻歸鳥一路飛進山裡，眼眶都要撐裂了。

三十年後，他五十四歲，一個人在長江上漂，寫下飄飄何所似天地一沙鷗的時候，大概早就忘了齊魯那個下午。他一輩子做過最大的官不過是左拾遺，凌絕頂那件事在人生和政治上從來沒實現。可是那一夜他在客棧裡寫下的那個少年——那個相信自己會登頂、相信眾山會在腳下變小的年輕人——一千三百年來就那樣一直站在泰山腳下，替後來每一個站在山下望山的年輕人，把那口氣先撐住。`
  },

  // id=24 盛唐 杜甫 〈佳人〉rating=5
  // 詩眼：一個剛丟官的中年人在山谷外看見另一個更落魄的人，發現對方就是自己
  // 隱藏連接：秦州流亡途中，子美替山谷裡一個沒落貴族女子代言，其實是替自己說話
  24: {
    title: "佳人",
    author: "杜甫",
    summary: "他不敢上前打擾，只回旅館替她寫了二十四行，其實是替自己說話。",
    story: `跟你說我朋友子美，那年他四十八歲，剛剛把華州司功參軍那個小官辭了，帶著一家老小往西邊逃，一路逃到秦州。秦州在隴山腳下，比長安冷得早，八月天樹葉就開始掉。有一個午後他一個人在城外一條山路上走，山路彎進一道空谷，谷裡孤零零幾間茅屋。遠遠的，他看見一個女子靠在竹子旁邊。他停住腳，沒敢過去。

那女子他一眼就看出來歷不對。穿的翠色衣袖已經洗得發白，可是站姿還是良家子的站姿，背挺得直，兩手交在身前，看人不看眼。子美後來從山下打柴的老人嘴裡拼出她的故事。關中那場仗，她的兄弟死了好幾個，官做得越高的越慘，屍骨到現在都沒收回來。她本來嫁得不錯，可是丈夫嫌她家垮了，另娶了一個年輕漂亮的新人，聽說新人像玉一樣。她一個人躲進這條空谷，只帶著一個侍婢，把首飾一件一件拆下來給侍婢拿去山下賣珠換米，屋頂漏了就自己去砍藤蘿補茅屋。子美聽的時候一句話都沒說。他自己不也是這樣嗎，曾經也是好家庭的孩子，曾經也在朝堂邊上排過班，如今棄官逃難，一家人擠在借來的破屋裡，米缸見底。他和這個他不敢上前打擾的女子，其實是同一種人。

那天傍晚他要回旅館，繞回山路口再看了一眼。天忽然冷起來，谷風從山口灌下來，那女子還站在原處。她袖子那麼薄，一定冷，可是她沒進屋。她剛從屋後采了滿把的柏葉，摘了幾朵野花捏在手裡，卻沒插進髮上。合歡樹到晚上還會合葉，鴛鴦到晚上還是成雙睡，只有她一個人靠在一叢細竹旁邊，直到日頭沉下山背，翠色的袖子在暮色裡淡成一縷影。子美掉頭走。回到旅館，他就著一盞燈，替她也替自己寫。開頭那句他改了好幾次，最後定成八個字：絕代有佳人，幽居在空谷。他寫的時候心裡清楚，這也是在說自己。山泉在山裡是清的，出了山就要變濁；他和她都選擇留在山裡。

三年後子美在成都草堂住下，日子稍稍緩過來。他寫了很多後人琅琅上口的詩，可是很少人記得，他剛到秦州那個秋天，曾經在一座空谷外站了很久，替一個素不相識的女子代言。二十四行寫下來，她的故事和他的故事織在同一塊布上，分不出誰是誰。那個倚著細竹的下午，就這樣一直留到現在。`
  },

  // id=26 盛唐 杜甫 〈夢李白二首之二〉rating=5
  // 詩眼：以為摯友死在流放路上，連夢三夜替他寫下告別，其實那時對方剛遇大赦活著回頭
  // 隱藏連接：杜甫寫這首的同一年春天，李白在白帝城遇赦，寫下「朝辭白帝彩雲間」，兩首詩隔著長江對望
  26: {
    title: "夢李白二首之二",
    author: "杜甫",
    summary: "他連夢三夜替偶像寫下告別；其實那個人剛遇大赦，還活著",
    story: `跟你說我朋友子美的一個秋天早上。地點在秦州，隴山腳下一間借來的土屋，天還沒完全亮，他忽然睜眼坐起來。這是他連著第三個晚上夢見同一個人。第一晚他以為是巧合，寫了一首。第二晚他心裡有點慌。到第三晚醒來，他確定不是巧合了——太白哥出事了。

要說清楚這個早上，得先倒回兩年前。至德二載那場永王李璘的兵敗，太白因為進了永王幕府，判了流放夜郎。那是嶺南再往南、比嶺南還荒的地方，蜀道之外的蜀道。之後太白就斷了音訊。子美這時候人在秦州——他年初剛把華州司功參軍那個小官辭了，帶一家老小往西邊逃安史之亂，逃到這個偏遠的西北邊城。他手頭沒有邸報，沒有長安的舊識能寫信給他，只有江湖上零星傳來的一句話：太白死了，死在流放路上。子美信了。

從那以後他睡不好。這幾天更是連著三夜都夢見那個人。夢裡太白總是匆匆忙忙要走，開口就先抱歉——路太遠，來一趟不容易。江上風浪那麼大，一條小船隨時會翻，不敢多待。夢裡太白轉身出門，一邊走一邊搔自己那頭白髮，那個姿勢子美太熟，是一輩子沒兌現志向的人才有的姿勢。他們兩個上一次見面是十四年前，開封、山東那幾次同遊，喝酒、爬山、被一群年輕人簇擁著，那時候誰都以為前面還有幾十年。

天亮了一點。子美走到門口，看見一朵浮雲貼著隴山慢慢橫過去——雲一天到晚在動，遊子卻久久不回。他忽然想到，此刻的長安，戴著高冠、坐著華蓋馬車的達官貴人擠了滿滿一街，只有太白哥一個人，遠遠困在南邊，落魄憔悴。他坐回屋裡的木桌，鋪紙研墨。寫到最後幾句他停了下來。他知道太白這個名字千秋萬代都會有人記得，可是那對現在死掉的太白有什麼用？名字是活人拿去傳誦的，寂寞是死人自己扛的。他一口氣寫下：浮雲終日行，遊子久不至。三夜頻夢君，情親見君意。整首二十行寫完，天已全亮。

其實太白那時候還活著。同一年三月他在白帝城遇到大赦，順長江一路東下，還興沖沖寫了朝辭白帝彩雲間那首得意的詩。可是這消息還沒傳到偏遠的秦州。子美這個秋天早上寫的，是他心裡替太白提前辦的一場告別。十一年後他自己也走了，死在湘江一條船上；那場告別後來成了他們兩個人友情的紀念碑，一直立到今天。`
  },

  // id=56 初唐 張若虛 〈春江花月夜〉rating=5
  // 詩眼：揚州人在江邊看月，突然意識到今夜江上千萬人各自望著同一輪月、思念一個具體的人
  // 隱藏連接：一輩子只留下兩首詩的人，其中一首寫的是全宇宙
  56: {
    title: "春江花月夜",
    author: "張若虛",
    summary: "一個一輩子只留下兩首詩的揚州人，在江邊寫下了全宇宙的相思",
    story: `跟你說我朋友若虛的一個春夜。地點在揚州城外長江邊上，大概是瓜州渡口附近。那天他一個人走出城，走到江邊。潮水正在漲，江面一寸一寸鋪開，遠遠望過去跟海連在一起。他抬頭，一輪月亮剛從海那頭升上來，好像是被潮水一起托著出水面的。這個畫面他站了很久。你可能沒聽過張若虛這個人，沒關係，唐朝當時很多人也沒聽過。他一輩子留下來的詩只有兩首，兩首而已。可是那個春夜他在江邊寫下的東西，一千三百年後被清代學者聞一多說成是詩中的詩、頂峰上的頂峰。就是這個晚上。

若虛是揚州人，跟賀知章、張旭、包融一起被人合稱吳中四士，江南四個會寫東西的年輕人。揚州人熟悉的春天就是這樣，潮生、月圓、江邊一片花林開得像下過一場薄霜。那晚月光太亮，他低頭看汀岸上的白沙，白沙跟月光混在一起，反而看不見了。江面天上下一整片乾淨到不像人間。他站在那裡，忽然想到一件事：這輪月今晚同時也照著別的地方。江上一定有一艘扁舟正順流而下，船上那個遊子也在抬頭；長江下游某個小樓裡，一個妻子在窗邊等她的丈夫，簾子怎麼捲都捲不走窗上的月光，砧板上剛拂掉的月色又落了回來。他們互相看得見月亮，卻聽不見對方。他們共享的其實只是這輪月。

若虛忽然覺得，這輪月從第一個人抬頭看它的那天起，就一直在做同一件事——替那些被隔開的人捎話。他自己也是被隔開的人之一。他在江邊坐下來，把身上帶的紙筆攤在膝上，就著月光寫。開頭四句他寫得很慢：春江潮水連海平，海上明月共潮生。灩灩隨波千萬里，何處春江無月明。寫完他沒停，一路往下寫，總共三十六句。從眼前這片江天，寫到天地間第一個抬頭看月的人；從一葉扁舟，寫到千里之外那個閨中的女子；從鴻雁飛不出這片月光，寫到明天早上月亮沉進海霧裡。他把宇宙、時間、一整代人的相思，全部塞進這一夜的江邊。

天快亮的時候，月亮慢慢往西邊沉，最後藏進了海上的霧裡。他把紙收起來，順著江邊往城裡走。潮水已經退了，江樹上還晃著最後一點月光。他不知道這一夜寫的東西後來能傳多遠，也不知道自己一輩子只會再寫一首詩就從歷史裡消失。可是今夜他替所有在江邊抬頭的人抬了頭，替所有等不到人的樓上人望了一次月。那個晚上他留下的江邊畫面，一千三百年還在江面上蕩著。`
  },

  // id=58 盛唐 李白 〈夢遊天姥吟留別〉rating=5
  // 詩眼：一場夢讓他終於承認長安那三年也是一場夢，決定不再回去低頭
  // 隱藏連接：夢裡的金銀臺 = 長安宮廷。醒來後兩座臺一起在他心裡塌掉。
  58: {
    title: "夢遊天姥吟留別",
    author: "李白",
    summary: "他做了一個夢，才敢說出憋了三年沒說出口的那句話",
    story: `跟你說我朋友太白最近的一個早上。地點在山東兗州附近，他借住在一個朋友家裡，前一晚上大家喝到很晚，他一個人回房睡了。天還沒亮他忽然坐起來，額頭有汗，胸口跳得很快。他剛剛做了一個好長的夢。太白這一年四十五歲，去年才剛被玄宗「賜金放還」，說白了就是被禮貌地趕出長安。他在宮裡當翰林待詔待了三年，天天寫應制詩、天天陪皇帝身邊那群人陪笑，他終於受不了了。醒過來他坐在床沿，發現自己還在山東，不在夢裡那座山上。他決定把夢寫下來，寫成一首告別詩，告訴山東這幫朋友：我要南下了。

夢裡的地方叫天姥山。天姥在今天浙江新昌一帶，旁邊就是天台山。他年輕時候在江湖遊，聽過越人講起這座山——雲霞明滅、時隱時現，海客講的瀛洲太虛渺，越人講的天姥還算摸得著。他一直記在心裡幾十年沒去過。夢裡他一夜之間飛過了鏡湖，湖上的月亮把他的影子送到剡溪邊。他腳上穿的是謝靈運當年上山那雙木屐，一路踩上青雲梯，半山看見海上的太陽，空中傳來報曉的天雞。走著走著雲變黑，熊在吼、龍在嘯，山泉迴響，他一時腿軟。忽然一聲霹靂，山崩開一個大洞，洞裡是一座金銀砌的高臺，日月同時照在上面。仙人們穿著霓虹做的衣服、騎著風，虎在鼓瑟、鸞鳥拉車，一個接一個從天上下來。他站在那邊看得整個人愣住，然後心臟一跳，就醒了。

醒來他覺得比睡前更清醒。他坐在山東朋友家的枕席上，剛剛那一片煙霞什麼都沒剩下。他忽然想通一件事：長安那三年也是一場夢。宮裡的金階玉樹、貴妃的笑、高力士替他脫過那雙靴子——所有他曾經以為抓在手上的東西，跟剛剛那座金銀臺一樣，睜眼就沒了。古來萬事都是東流水。既然都是夢，他何必再回長安去給那些人低頭？他要走了，他要真的去看天姥山，不再是聽越人講。他要放一頭白鹿在青山邊上，想上山的時候就騎著鹿去。至於什麼時候回山東見這幫朋友，他答不上來。他把心裡想了三年沒說出口的那一句寫在紙的最後：安能摧眉折腰事權貴，使我不得開心顏！寫完他自己都笑了。

那天早上他把整首詩交給山東的朋友，全詩四十五句，從海客談瀛洲一路寫到白鹿青崖。朋友一邊讀一邊皺眉，讀到最後一句就懂了：這個人真的不回去了。太白後來果然南下遊吳越，也真的去了天姥山腳下轉了一圈。剩下的十六年他一路漂到當塗，最後死在那邊，再也沒有回過長安。他這一夜在山東枕席上做的夢，救了他後半生。一千兩百多年過去，讀他這首詩的人還是會記得那句他寫給自己也寫給每一個必須低頭的人的話。`
  },

  // id=61 盛唐 李白 〈把酒問月〉rating=5
  // 詩眼：朋友在酒宴上慫恿他去問月亮，他真的把杯子放下，抬頭問了
  // 隱藏連接：三百年後蘇軾中秋喝多了，抬頭問「明月幾時有」，替太白續這場酒
  61: {
    title: "把酒問月",
    author: "李白",
    summary: "朋友在酒宴上慫恿他問月亮，他真的把杯子停下來，抬頭問了。",
    story: `跟你說我朋友太白那一夜的事。長安城外賈淳家的院子裡擺了一桌酒，月亮剛從屋簷後爬上來，青天上白得像剛洗過的瓷。太白正舉著杯，賈淳忽然把酒壺往桌上一擱，笑著說，太白啊，你這輩子寫月亮寫了幾百次，你倒是替我們問問它，它到底什麼時候開始掛在那裡的？滿桌人都笑了，等著看他怎麼接。太白沒接話，他把杯子輕輕放下，抬起頭看那顆月亮，看了很久。

你要曉得太白這個人跟月亮的關係。他二十六歲在揚州客舍寫過床前明月光，四十幾歲一個人喝酒還要邀月亮同飲，他這一輩子都攀著月亮走。可他也知道月亮這東西真去攀是攀不到的，人爬不上去，它卻一路跟著你走，你往哪它就往哪。年輕時候他在蜀中山裡看它，供奉翰林那幾年他在長安宮裡看它，被賜金放還之後他在江上看它，到了賈淳家的酒宴上它還在。此刻它像一面剛擦亮的飛鏡，貼在丹紅色的宮闕之上，周圍那層綠煙淡下去，清亮的光就整片鋪出來。太白心裡想，這麼多年只見它晚上從東邊海上爬起來，卻沒有一個人真的看清它清早往哪一片雲裡沉下去。它從來不解釋自己。

賈淳還在旁邊追問，太白卻已經走遠了。他想起小時候聽人講月亮上有一隻白兔，搗一種從秋天到春天都搗不完的藥。旁邊那位嫦娥飛上去以後，這一千年到底跟誰做鄰居？他一個人在酒桌上把這些人挨個想過來，忽然覺得有點冷。他抬起頭再看一眼那輪月，此刻坐在這桌前的他，看不到屈原李陵那個時代的月亮；可是現在這輪月亮，一定曾經照過秦皇漢武，也照過蘇武李廣。古人今人就像一條流不停的水，來了又去，去了又來，唯獨每一代人抬頭看到的，都是這同一輪月。他把賈淳丟給他的那個問題順勢寫下來：青天有月來幾時，我今停杯一問之。

整首詩寫下來十六句，賈淳讀完半天沒說話。太白把筆放下，又把剛才停住的那杯酒端起來，這一次沒再放下。他跟賈淳講，別的都無所謂，只希望往後每次朋友聚在一起唱歌喝酒的時候，這輪月光都能長長地照在他們的金樽裡就夠了。三百多年後，蘇軾中秋夜裡喝多了，抬頭問了一句明月幾時有，把酒問青天，那一夜他其實是在替太白續這場酒。太白在賈淳院子裡問出去的那個問題，一直有人替他問下去。`
  },

  // id=62 盛唐 李白 〈南陵別兒童入京〉rating=5
  // 詩眼：等了二十年的召見詔書終於到了，一個四十二歲的男人在自家院子裡大笑出門
  // 隱藏連接：道士吳筠與玉真公主在玄宗面前替他說話，這是他等這一天的暗線
  62: {
    title: "南陵別兒童入京",
    author: "李白",
    summary: "四十二歲那年秋天，詔書終於送到南陵——他仰天大笑，跨馬西去長安。",
    story: `跟你說我朋友太白最爽的一個下午。

那年他四十二歲，秋天，住在南陵鄉下。院子裡幾隻黃雞剛養肥，正低頭啄著新收的黍米，走路屁股一晃一晃。山上剛釀的白酒也熟了，他自己揹了一罈下山。他推開籬笆門的時候，兒女從屋裡衝出來，一把抱住他的腿，牽著他的衣角，吵著要他把肩上那罈酒趕快開。你以為這只是一個普通的秋天下午嗎？不是。他一邊接過小孩塞來的酒杯，一邊眼睛瞟向門口——他在等一個從長安來的人。

這一等，已經二十年了。

跟你講，太白從二十四歲離開四川就沒再回去過。他上過益州長史蘇頲的門，拜過渝州刺史李邕，寫詩給荊州長史韓朝宗，又跑去洛陽找元丹丘，在會稽住過，在山東住過，認識的節度使、宰相家人一大堆，乾謁詩寫了兩百多首。沒有一個朝廷正式的位子給過他。老婆劉氏跟他嘔氣好幾年了，說他整天不務正業，還不如去田裡種點瓜。他自己心裡也清楚，再拖下去就四十五、五十歲了，遊說萬乘這件事真的太晚。就在他快撐不住的這一年，道士吳筠在玄宗面前提了他的名字，玉真公主也在旁邊幫忙敲邊鼓。徵召的詔書就是在這個秋天下午送到南陵——他剛好從山裡回來，一手接住。

他把白酒罈子擱到桌上，詔書放在旁邊，喊小孩去把院裡那隻黃雞抓來烹了。一家人圍著桌子吃飯，劉氏也給他斟酒。他喝到興頭上，站起來高歌，又跳起舞來，窗外的落日剛好從屋簷斜進來，落在他袖子上，他就跟那道光比誰亮。他跟劉氏講漢代那個朱買臣的舊事——當年會稽有個婦人嫌丈夫窮，鬧著離了婚，後來丈夫做了會稽太守，她後悔也來不及。劉氏聽了，笑著把他按坐下。他就著這股酒勁，抓起筆把整個下午寫成一首詩：白酒新熟山中歸，黃雞啄黍秋正肥。呼童烹雞酌白酒，兒女嬉笑牽人衣。高歌取醉欲自慰，起舞落日爭光輝。遊說萬乘苦不早，著鞭跨馬涉遠道。會稽愚婦輕買臣，餘亦辭家西入秦。仰天大笑出門去，我輩豈是蓬蒿人！

寫完他仰頭大笑一聲，推門就走了。院子裡那罈白酒還剩大半罈，黃雞的骨頭還在桌上，小孩追到門口沒追上他的馬。他不知道自己這一去，在長安只會待三年，玄宗會賜金放還讓他重新滾回江湖。但那個下午，他兒女牽著他衣角、他跟落日搶光的樣子，已經被他自己親手抄了下來，活到現在。`
  },

  // id=66 盛唐 李白 〈行路難三首之一〉rating=5
  // 詩眼：被踢出長安的中年男子在餞行酒席上為自己掛帆
  // 隱藏連接：兩年前他從南陵大笑出門去長安，這場酒席是那個下午的反面
  66: {
    title: "行路難三首之一",
    author: "李白",
    summary: "他吃不下這頓餞行飯，卻替自己掛上了往後半輩子的那張帆",
    story: `跟你說我朋友太白的一頓飯。桌上擺著長安城裡最貴的酒，一斗一萬錢；盤子上是玉盤盛的珍羞，一頓菜的價錢夠一戶人家過大半年。可他一口都吃不下。他把酒杯停在半空，又把筷子丟回桌上，拔出隨身的劍，回頭看了四周一圈。滿座的朋友沒人敢說話。這一年他四十四歲，是天寶三載春天，他剛被玄宗從翰林院踢出來。

兩年前他還興沖沖地騎馬進長安。道士吳筠替他敲了邊鼓，玉真公主又幫忙推了一把，玄宗召他進宮做翰林待詔。他以為終於等到那個位子，可以議政、可以做事、可以把胸口裡那套治國的想法端出來。結果玄宗只把他當寫詩的寵物——楊貴妃想聽新曲子，他被叫去寫清平調；牡丹開了，他被叫去寫牡丹；宴會助興，他被叫去湊句子。他想開口談國事，玄宗打個哈欠就換了話題。高力士看他不順眼，楊國忠也跟他過不去。兩年下來他悶到骨頭裡。今年春天玄宗塞了他一筆錢，叫他離開長安——說得好聽叫賜金放還，說白了就是掃地出門。此刻長安東門外，朋友替他設了這頓餞行席。

酒過幾巡，他還是喝不下。他心裡在算自己接下來能往哪走。想過黃河？黃河結冰把河道整個塞住。想爬太行？太行雪厚到走不動。他忽然想起姜太公當年在磻溪垂釣，想起伊尹作夢乘船經過太陽旁邊——那些老古人也曾經卡在他這樣的路口，最後不都翻身了嗎。他喝完杯裡的酒，站起來連喊了兩聲：行路難！行路難！然後他坐下來，把整晚所有的話都抄進那張紙上：金樽清酒斗十千，玉盤珍羞直萬錢。停杯投箸不能食，拔劍四顧心茫然。欲渡黃河冰塞川，將登太行雪滿山。閒來垂釣碧溪上，忽復乘舟夢日邊。行路難！行路難！多歧路，今安在？長風破浪會有時，直掛雲帆濟滄海。

他把詩留給朋友，跨馬東去。兩年前他從南陵仰天大笑出門去，說我輩豈是蓬蒿人；兩年後同一個人在長安東門外拔劍四顧，吃不下這頓最貴的餞行飯。他還不知道自己之後十幾年會被永王李璘牽連下獄，會被流放夜郎，會在江南江北一直漂到六十二歲死在當塗。可就是在這個春天的下午，那盤動不了的珍羞、那把拔出來又收回鞘裡的劍旁邊，他替自己也替後面所有走到路口的人，先把那張雲帆掛了上去。長風破浪的時候會來的——他這樣跟自己講，然後真的靠這股勁撐了後半輩子。`
  },

  // id=68 盛唐 李白 〈行路難三首之三〉rating=5
  // 詩眼：同一個人前陣子才把雲帆掛得高高的，這下午改口說有酒就喝
  // 隱藏連接：與之一「長風破浪會有時」對讀，兩種答案在他心裡輪流跑
  68: {
    title: "行路難三首之三",
    author: "李白",
    summary: "剛喊完長風破浪的人，秋風一起，改說有酒就喝",
    story: `跟你說我朋友太白的另一個下午。這次不是餞行席，不是拔劍四顧，是他借宿在洛陽一個朋友家的小院裡。秋天，樹上的鳥叫得很細碎，桌上就一壺酒、一個杯子、一疊還沒動過的紙。他前陣子才寫完那首說長風破浪會有時的詩，把雲帆掛得高高的；這個下午，同一個人坐在這裡，替自己寫另一種答案。
離開長安已經有一段日子。玄宗塞給他的那筆賜金花得差不多了，他一路往東走，走到洛陽就沒再急著往前。朋友留他住幾晚，他就住下來。窗外的鳥叫聲一陣一陣，他忽然想到古人裡有兩個他一直不太懂的角色。一個是許由，堯要把天下讓給他，他嫌那話髒了耳朵，跑去潁川邊上把耳朵洗了洗。一個是伯夷叔齊，商朝完了不肯吃周朝的米，跑到首陽山上摘蕨菜過日子。他年輕時覺得這些人真高潔；這個下午他覺得，這種孤高比雲比月的做法，其實也是一種累。
他把酒倒進杯裡，開始在心裡點名。伍子胥當年替吳王打天下打到齊國，功勞大到沒人比得上，最後被夫差賜死，屍體用皮袋一裝丟進吳江。屈原一輩子替楚國操心，被楚王一貶再貶，走到湘水邊上一句話沒留就跳了下去。陸機那樣的雄才，捲進八王之亂被誣陷處死，臨刑那一刻他嘆了一句，華亭那邊的鶴叫，我這輩子是聽不到了。李斯替秦朝寫了那麼多國策，被趙高害到腰斬，臨死前他抱著兒子哭，當年帶著黃狗出上蔡東門追兔子的日子，怎麼就一去不回。太白一個一個想過去，酒喝了半壺。
窗外的秋風忽然吹了一陣，他想到張翰。西晉那個張翰在洛陽當官當得好好的，秋風一起，他想起江東家裡的蓴菜鱸魚，第二天就辭官坐船回去了。太白笑了一下，把那壺酒往杯裡再倒了一次。他攤開紙，一口氣寫下去：有耳莫洗潁川水，有口莫食首陽蕨。含光混世貴無名，何用孤高比雲月？吾觀自古賢達人，功成不退皆殞身。子胥既棄吳江上，屈原終投湘水濱。陸機雄才豈自保？李斯稅駕苦不早。華亭鶴唳詎可聞？上蔡蒼鷹何足道！君不見吳中張翰稱達生，秋風忽憶江東行。且樂生前一杯酒，何須身後千載名？
寫完他把杯裡那口酒喝乾。前陣子他還在信長風破浪，這個下午他信一杯酒就夠了。同一個人，在同一段路上，兩種答案輪流跑出來。他其實兩邊都沒完全放下。十年後他還是會跟錯永王差點被砍頭，還是會再回頭去追那個他這下午勸自己別再追的位子。可就是這個秋天，他替所有心裡放不下又不敢完全放下的人，先把那杯酒認真喝了一次。`
  },

  // id=99 中唐 李賀 〈金銅仙人辭漢歌〉rating=5
  // 詩眼：24 歲被迫離開長安的年輕詩人，把自己的心情借給 500 年前一尊被拆走的銅像
  // 隱藏連接：長吉東歸走的咸陽道，正是三國魏官運銅人出長安的同一條路
  99: {
    title: "金銅仙人辭漢歌",
    author: "李賀",
    summary: "被推出長安的 24 歲詩人，讓 500 年前一座銅像替自己流淚",
    story: `跟你說我朋友長吉的一個晚上。813 年的秋天，他 24 歲，剛從長安棄官往洛陽走。人在咸陽道邊上一間破旅店，油燈點著，桌上一本翻開的舊書。他讀著讀著忽然停在一頁，眼神愣住。書上寫的是三國那年，魏明帝派人到長安拆一尊銅像的事。這尊銅像在長安宮裡站了四百多年，是漢武帝當年鑄的，手上端著一個銅盤接甘露，武帝相信喝了那個能長生。武帝早就葬在茂陵，銅人卻替他一路站到現在。
長吉往窗外看了一眼。他自己走的這條咸陽道，五百年前那尊銅人也走過。他被免官出京的心事還沒消化完。他父親名字裡一個晉字諧音進，他這輩子連考進士的資格都被人挑掉。韓愈當年替他寫了整整一篇辯詞，也沒扳回來。他在長安當那個管禮儀的九品奉禮郎，站了三年，站到自己都覺得可笑，就把烏紗丟了。這幾天他往東走，路邊的蘭花開始枯，秋風硬得像沙子往眼裡打。他讀著書上那段，魏官牽著車把銅人推出宮門，銅人眼睛裡流出鉛一樣沉的眼淚，一路往東搬到洛陽——長吉忽然覺得那不是別人，就是他自己。他跟那尊銅人一樣，被一個叫不出理由的規矩推出長安，往東走。
他把燈挑亮，攤開紙。他讓那尊銅人替自己把話說出來。他把畫欄邊的桂樹香、三十六座長滿青苔的宮殿、東關的酸風、路上枯掉的蘭花，一樣一樣搬進紙上；他寫魏官牽車指千里，寫銅人捧著漢朝的月亮走出宮門，寫眼淚沉得像鉛水，寫渭城遠了、河邊的水聲越來越小。寫到中間他停了一下，一句話浮上來——如果老天也有情感，老天也會老。他把它按進紙裡，接著一口氣把整首寫完：茂陵劉郎秋風客，夜聞馬嘶曉無跡。畫欄桂樹懸秋香，三十六宮土花碧。魏官牽車指千里，東關酸風射眸子。空將漢月出宮門，憶君清淚如鉛水。衰蘭送客咸陽道，天若有情天亦老。攜盤獨出月荒涼，渭城已遠波聲小。
他把筆放下，吹熄油燈。窗外的秋風還在吹。十年後他 27 歲就死了，沒等到誰替他翻案，那尊銅人也早在洛陽的路上散成了鏽片。可就是這個晚上，一個沒能考進士的年輕人，借一座被拆走的銅像，把整個王朝離場的樣子刻了下來，也把自己被推出長安時那一次回頭望，永遠留在了咸陽道上。`
  },

  // id=112 盛唐 李白 〈送友人〉rating=5
  // 詩眼：送別的太白其實是在送另一個版本的自己——那株漂了一輩子的孤蓬
  // 隱藏連接：連兩匹一路同行的馬都不肯分開，替兩個人先哭出來
  112: {
    title: "送友人",
    author: "李白",
    summary: "太白騎馬送朋友出城，發現要走萬里路的那個人其實就是自己",
    story: `跟你說我朋友太白的一個下午。他騎著馬送一個朋友出城，兩個人並肩走了很遠。城的北邊橫著一道青山，山勢是斜的，像有人拿手掌從東往西壓過去；城的東邊繞著一條白水，水面在秋陽下亮得刺眼。他們從東門出來，一路慢慢走，話越說越少，馬蹄在土路上啪嗒啪嗒。這個朋友的名字他這輩子沒告訴任何人，後人翻遍所有的信也對不上號，只知道那天下午每一個彎、每一次勒馬，他都記得。
太白這輩子送別多。他 25 歲從蜀中出來，第一次坐船順長江東下的時候心想這是要去做大事，結果一晃三十年過去，他還在到處走。他在長安給皇帝寫過詩，被人趕了出來；他在山東娶過妻，妻子死了；他在洛陽跟杜甫喝過酒，那是他這輩子最快樂的一段。可他從來沒有一個真正意義上的家。他就是那株被風從一個地方吹到另一個地方的孤蓬，落在哪裡就在哪裡開一朵小花，然後又被吹走。今天他送的這個朋友要往北走，要走上萬里的路，他心裡明白，這個朋友其實就是他自己的另一個版本。他站在這裡送朋友，也是隔著時空替某一個從前的自己送行。
他們走到河邊一片開闊的地方，停下來。太陽開始往山那邊沉，天上一朵浮雲慢慢飄過去，飄的方向跟朋友要走的方向一模一樣。太白抬頭看著那朵雲，忽然覺得那就是朋友心裡的樣子，飄不定，也不知道要落在哪。落日一點一點把河水染紅，他心裡明白，這道光很快就要收走，就跟一個老朋友坐在你旁邊，天黑之前非走不可。他勒住韁繩，看著朋友的臉，把幾句話在心裡擺好：青山橫北郭，白水繞東城。此地一為別，孤蓬萬里征。浮雲遊子意，落日故人情。揮手自茲去，蕭蕭班馬鳴。
他們互相揮了揮手。朋友撥轉馬頭往北，他撥轉馬頭往南。兩匹馬一路同行走了整個下午，此刻要分開，忽然都不肯走，仰起脖子一直嘶叫，替兩個不好意思哭的人先哭了。太白騎在馬上回頭看了一眼，青山還橫在那裡，白水還繞在那裡，只是那朵浮雲已經飄得很遠了。後來他又走了三十年，最後客死當塗。那個朋友叫什麼名字沒人知道，可是那個下午兩匹馬不肯分開的嘶叫聲，一千三百年了還在響。`
  },

  // id=127 盛唐 王維 〈山居秋暝〉rating=5
  // 詩眼：一個中年男人在秋天雨後傍晚散步，替自己寫下一份決定不回長安的通知書
  // 隱藏連接：反用《楚辭·招隱士》「王孫兮歸來，山中兮不可久留」
  127: {
    title: "山居秋暝",
    author: "王維",
    summary: "他沒說要辭官，他只是在山裡替自己寫了一份留下來的通知書",
    story: `跟你說我朋友摩詰的一個傍晚。他從山下辦完事往回走，剛下過一場秋雨，鞋底沾了濕葉子，袍子邊角吸了水，走起路來沉沉的。他沒撐傘，也沒帶隨從，就一個人慢慢往山上走。天已經涼了，涼到他要把手籠進袖子裡。你要知道，他這輩子大部分時間住在長安，穿的是官服，坐的是馬車，聽的是朝會的鐘聲。可最近幾年，他一有空就往這座山裡鑽。這座山叫終南山，這個別業叫輞川。他從前朝詩人宋之問的後人手裡把這塊地買下來，替裡面每一個景點都取了名字，替每一個景點都寫了詩。今天他要走的這條山路，他走過不下一百遍。

你要明白他為什麼老往這裡跑。他早年一路順風，二十出頭就中了進士，做官做到尚書右丞。可四十歲之後事情變了。他母親開始吃齋念佛，家裡多了一股香火味；沒幾年安史之亂爆發，叛軍打進長安，他跑不掉，被抓去強迫做了偽官。戰亂平定後朝廷清算，這種帽子扣下來是要砍頭的，他弟弟王縉拼命替他求情才把他撈回來。從鬼門關走一圈回來的人，看官場的眼神就不一樣了。他還在做官，該上朝就上朝，可他心裡替自己開了一條後路：只要輞川還在，他就有地方可以躲。今天他走進山口，雨剛停，空氣裡有一種被洗過的乾淨。他抬頭，看見一輪明月已經悄悄爬到松樹梢上；他低頭，看見雨水匯成清泉，從石頭上一路流下山。他停下腳步，聽見竹林那邊有人說笑，是幾個洗完衣裳的女子準備回家；蓮池那邊水面一動，一艘小漁船從蓮葉之間慢慢滑出來。

他就站在那裡看了很久。你知道他在想什麼嗎？他在想《楚辭》裡有一句話，叫「王孫兮歸來，山中兮不可久留」，是幾百年前有人寫給隱士的，勸他們別在山裡耗著，該回城裡幹活了。可他今天站在這座剛下過雨的山裡，覺得那句話反過來說才對。管它春天的花草有沒有凋謝，管長安那邊在忙什麼，他就是要留下來。他慢慢走回住處，把濕袍子換掉，坐到燈下鋪開紙，寫下八句話：空山新雨後，天氣晚來秋。明月松間照，清泉石上流。竹喧歸浣女，蓮動下漁舟。隨意春芳歇，王孫自可留。

他寫完把筆放下。你細看整首詩會發現，裡面沒有一個「我」字，可是每一行都是他親眼看見的東西：月、松、泉、石、竹、蓮、洗衣的女子、下山的漁舟。他把自己藏得乾乾淨淨，只留下最後一句「王孫自可留」，那才是他真正想說的話。這其實不是一首寫景詩，這是他寫給自己的一份通知書，告訴自己以後就這樣了，別再指望長安，別再等哪個皇帝重用你。後來他六十一歲死在輞川，那條他走過一百遍的山路，那場秋天傍晚的雨，那輪爬上松梢的月亮，一千三百年了還在那裡等著下一個念這首詩的人走進去。`
  },

  // id=130 盛唐 王維 〈酬張少府〉rating=5
  // 詩眼：他決定不用文字回答朋友的大哉問，讓漁夫的歌聲代替他去港灣深處
  // 隱藏連接：安史之亂偽職事件讓他徹底放棄「窮通」的討論
  130: {
    title: "酬張少府",
    author: "王維",
    summary: "朋友問人生成敗的道理，他讓一支漁歌替他把答案送進港灣深處",
    story: `跟你說我朋友摩詰的一個下午。他剛從山上散步回來，衣服上沾了松針，手裡拎著一封信。信是山下一位姓張的縣尉託驛使送上來的。這個張少府他認識，早幾年在長安見過一兩面，話不多但眼神懇切，看得出來還想在官場上做點事。信裡的問題只有一句：晚年老兄過得如何？窮通之理，可否賜教。摩詰把信翻來覆去看了好一會兒。他今年五十七了，住在輞川已經第八個年頭。以前收到這種信，他會回一封長的，寫得四平八穩。今天他坐在門口的石階上，看著日頭往山那頭斜下去，忽然覺得他不想再寫那種信了。

你要知道摩詰不是一開始就這樣的。二十一歲他就進士及第，年輕時寫過「大漠孤煙直，長河落日圓」那種豪邁的邊塞句子，那時候他也是想做事的人。可安史之亂把一切都改了。叛軍打進長安時他沒跑掉，被抓去強迫任了偽職；戰後朝廷清算，這種帽子扣下來是要砍頭的，他弟弟王縉削官替他求情才把他撈回來。從鬼門關走一圈回來的人，看什麼都不一樣了。他還掛著尚書右丞的頭銜，可他的心思早就搬到山裡來了。他每天做的事情變得很少：早上澆花，中午讀經，下午看松，晚上彈琴。所謂萬事不關心，不是他裝的，是他真的關不了了。他坐在石階上想，張少府問的那個「窮通之理」，他年輕時大概也追過答案。可他現在明白，這種問題沒有答案，或者說，答案不能用字寫。他自己這幾十年也沒攢下什麼安邦定國的長策，只知道往舊林裡走。要他把這些寫給張少府，他寫不下手。

太陽落下去了，月亮就從東邊的松枝上探出頭來。山風一陣一陣吹過來，他順手把腰上的帶子解開一點，讓風進到袍子裡。他站起身，把琴從案上端出來，就著月光坐下，慢慢彈了一支曲子。彈到一半他停下，走回書房鋪開紙，寫了八句話：晚年惟好靜，萬事不關心。自顧無長策，空知返舊林。松風吹解帶，山月照彈琴。君問窮通理，漁歌入浦深。他寫完最後一句，把筆放下。他沒有回答那個問題。他讓一個唱著歌的漁夫，替他把答案送進港灣深處去。

他把信折好，準備明天讓驛使送下山。你可以想像張少府收到這封回信時的表情。他問的是道理，摩詰給他的是一支歌聲往水面深處走的畫面。可摩詰知道，如果張少府哪天走到他這一步，他自然會懂。摩詰六十一歲那年死在輞川。他寫給張少府的這個下午留下來了：那封只回了八句的信、那條被松風吹開的衣帶、那輪剛上松梢的月亮、那支彈到一半的曲子，一千三百年後還在山裡，等下一個念這首詩的人接住。`
  },

  // id=135 盛唐 王維 〈使至塞上〉rating=5
  // 詩眼：一個南方文人被朝廷擠出去，第一次撞見大漠這麼直接的自然
  // 隱藏連接：這是摩詰一輩子唯一一次寫大漠，之前之後寫的都是輞川松月
  135: {
    title: "使至塞上",
    author: "王維",
    summary: "他一輩子只寫過一次大漠，就是被朝廷派出去的那個春天下午",
    story: `跟你說我朋友摩詰這輩子只寫過一次大漠，就是開元二十五年的春天。那時候他三十九歲，坐在一輛簡單的驛車上，從長安一路搖了一個多月，往涼州去。車伕不太說話，車輪碾過沙路發出乾乾的聲音。他自己也不太說話。他從來沒走這麼遠過。他之前的日子都在關中、在江南、在輞川的松林裡，寫的是明月松間照、清泉石上流。這回他被派了一輛單車，一路往西問邊塞。

那年河西節度使崔希逸剛在西邊大破吐蕃，玄宗挑了他代表朝廷去慰問前線、宣讀獎賞。名義上是件榮譽事。可他心裡明白，這也是李林甫在朝廷裡把張九齡一派人一個一個擠出去的手筆——他就是張九齡當年提拔上來的人。派去大漠，就是派出朝廷。他一路過居延方向的屬國，抬頭看見大雁一隻一隻往北飛，鑽進他從沒見過的胡人天空。他忽然覺得自己這個人也像一顆被風吹起來的蓬草，從漢朝的關塞被一送就送出去，再也回不了頭。他這輩子沒這樣被連根拔起過。

某一天下午車走到大漠深處，他讓車伕停下。他跳下車，四面看了一圈。從南邊繞過來的黃河在沙漠盡頭轉了一個彎，太陽正好貼在那道彎上，圓得像一塊剛從爐子裡拿出來的銅盤。更遠一點，一縷狼煙從地平線上直直往天上竄，一點都不歪。這裡沒有風，直得像一根線。他站在原地愣了好幾秒。他這個南方出身、平常寫松林細泉的人，第一次看見這麼大、這麼直接、這麼沒有裝飾的自然。當晚他在驛站鋪紙，把八句寫下：單車欲問邊，屬國過居延。征蓬出漢塞，歸雁入胡天。大漠孤煙直，長河落日圓。蕭關逢候騎，都護在燕然。

再往前走，他到了蕭關那一帶，果然遇上一小隊偵察兵。他問都護在哪裡，候騎告訴他，崔大人已經深入到燕然山那邊繼續打仗了，一時半刻回不來。他站在候騎旁邊笑了一下，把行李重新繫緊。這趟差他走了大半年才回長安。回去以後他就再沒寫過一次大漠。晚年他寫給張少府的還是松風山月，寫給裴迪的還是輞川的水色。只有這個下午被留下來了：那縷直直往天上升的孤煙、那輪貼在長河上的落日，一千三百年後還在替他問邊。`
  },

  // id=140 盛唐 孟浩然 〈過故人莊〉rating=5
  // 詩眼：一個不當官的中年男人，在朋友家的窗邊喝了一頓有下次約定的酒
  // 隱藏連接：漢代范式雞黍之約 + 四十歲落第放歸襄陽後的另一種活法
  140: {
    title: "過故人莊",
    author: "孟浩然",
    summary: "四十歲的落第書生，在朋友家的窗邊喝了一頓有下次約定的酒",
    story: `跟你說我朋友浩然的一個下午。那年他四十出頭，剛從長安落第回來，玄宗一句「卿自不求朕，奈何誣朕」把他放歸襄陽，他也就真的回來了，住到鹿門山半耕半讀。這天秋收剛過，鄰村一個老朋友托人捎口信來，說雞已經殺了、黃米飯也蒸上了，讓他過去吃飯。他放下書，找出那件洗得發白的青布袍，去牲口棚牽了驢就出門。

他是知道「雞黍」兩個字份量的。漢代范式跟張元伯約定兩年後那天來吃雞黍，張元伯的媽媽不信人真的會遠道而來，張元伯只說范式是信人一定會來，結果范式真的來了——這是讀書人從小背爛的故事。他這位鄉下朋友大概沒讀過那段書，但那個意思是懂的：雞是提前一天養肥的、黃米是今年新收的、火候是算準了他大概哪個時辰到的。這頓飯不是隨便一頓飯，這是拿性命賭下來的一句「你來，我一定給你煮」。他騎驢慢慢晃過去，路上一排排綠樹把整個村子攏住了，抬頭一看，遠處那道青山斜斜地掛在城郭外面，像是專門替這個下午擺好的背景。

到了朋友家，兩人把桌子搬到窗邊，推開軒窗，外頭正對著打穀場和菜園。朋友給他滿上一杯酒，話題就從今年桑葉厚不厚、麻收得怎麼樣起了頭。沒人問他長安考得如何，也沒人打聽玄宗那句話是什麼意思。他喝著喝著就笑了，忽然覺得這樣坐著，比在含元殿前排三個時辰的隊要踏實得多。太陽偏西他起身要走，朋友送到院門口。他回頭說：等到九月九號重陽那天，我再來喝你們家的菊花酒。這是他跟朋友下的下一次雞黍之約。

回鹿門的路上他把這一天默了一遍，回到家鋪紙落筆，寫下四十個字——故人具雞黍，邀我至田家。綠樹村邊合，青山郭外斜。開軒面場圃，把酒話桑麻。待到重陽日，還來就菊花。他這輩子真的沒當上官，五十出頭病死在襄陽，連王維那幫在長安做官的老朋友都來不及趕回來看他一眼。可他答應朋友的那個重陽也真的赴了，那壺菊花酒也真的喝了，田家的那扇軒窗、那片場圃、那盤雞黍，就這樣被他一併收進了那四十個字裡頭。一千三百年後，還有人替他惦記著那個曬穀場、那盤雞黍、那句在院門口說出來的「還來」。`
  },

  // id=148 盛唐 張九齡 〈望月懷遠〉rating=5
  // 詩眼：被貶到荊州的老宰相，在夏夜庭院滅了燭、披了衣，只為了跟遠方那個人共享同一片月光
  // 隱藏連接：張九齡曾勸玄宗殺安祿山，玄宗不聽；十九年後安史之亂，玄宗逃蜀路上派人到子壽墓上致祭
  148: {
    title: "望月懷遠",
    author: "張九齡",
    summary: "被李林甫擠出長安的老宰相，在荊州庭院裡把一把月光捧給看不見的那個人。",
    story: `跟你說我朋友子壽的一個夏夜。他當時快六十歲了，剛被貶到荊州當長史沒幾個月。這天晚上他從屋裡走出來，在庭院裡站了很久，也沒個要做什麼的樣子。丫鬟給他送了茶他也不喝，只是仰著頭看那輪月亮從東邊那片海的方向升上來——不是長安的月亮了，是荊州的月亮。

他叫張九齡，字子壽，韶州曲江人。十幾年前他是玄宗身邊的中書令，主張任賢、主張整頓吏治，也主張把那個從范陽送來受審的胡人將領安祿山依軍法處死。他跟玄宗說，祿山狼子野心，面有逆相，不殺必為後患。玄宗笑一笑，把安祿山放回范陽去了。後來李林甫得寵，一步步把他從中書令的位子上擠下來、擠出長安、擠到這個南方潮濕、蟬叫個不停、離朝廷幾千里遠的荊州任上。他心裡很清楚，這輩子再也回不去了。他不是不會想。他遠在長安那位髮妻此刻不知道睡了沒有，那位當年肯聽他一句話的老皇帝此刻不知道還記不記得他這個人。天涯這麼遠，可是月亮就一個。他想到這裡就苦笑了一下。

夜越來越深。他一直坐到滿院的月光都亮起來，才發覺自己屋裡那根燭火反倒把月色壓住了。他起身走進去，把那根燭吹熄。屋裡一下子暗下來，門外的月光就滿滿地漫了進來，鋪在階石上、鋪在他鞋面上，像浸過水一樣涼。他捧起手接了接，手心裡明明就是滿滿的一把光，可他也知道——這一把光沒法子送去給那個人。他嘆了口氣，回屋拉了件外袍披在肩上再走出來，才發覺不知道什麼時候夜露已經把袍子沾濕了一片。他就這樣一個人在庭院裡站到後半夜，看月光一寸一寸地移，看自己那條影子一寸一寸地被拉長。

回到案前他鋪紙落筆，一氣寫下八句——海上生明月，天涯共此時。情人怨遙夜，竟夕起相思。滅燭憐光滿，披衣覺露滋。不堪盈手贈，還寢夢佳期。寫完他就上床睡了，想著或許能在夢裡跟那個人見上一面。他不知道的是，三年後他就會病死在曲江老家；也不知道十九年後，那個他當年主張要殺的胡人真的反了，玄宗倉皇逃到蜀地的半路上想起子壽當年的話，抹著眼淚派人到他墳上致祭。可是那個荊州夏夜他捧在手心裡的一把月光，一千三百年後還在被人念——只要天上還有月亮，海這邊、天涯那邊，就永遠有兩個人在共享同一個時辰。`
  },

  // id=151 中唐 常建 〈題破山寺後禪院〉rating=5
  // 詩眼：一個官途不得志的人，走到古寺後院最深處，才發現放下這麼容易
  // 隱藏連接：他跟王昌齡同榜進士，兩人最後都被丟到小地方當小官
  151: {
    title: "題破山寺後禪院",
    author: "常建",
    summary: "開元進士走進破山寺後院最深處，在一方小潭前把幾年堆在心裡的東西一件件放下。",
    story: `跟你說我朋友常建的一個夏天清晨。那天太陽才剛剛升上來，他一個人走進江蘇常熟虞山上那座南朝就已經蓋好的古寺廟——破山興福寺。寺門口還沒有人，鐘也還沒敲，山門的石階上掛著昨夜留下來的露水。他踩上去，鞋底立刻濕了一片，但他也沒回頭。他是特地趕早上山的，就想趁著沒人的時候一個人進去走一走。剛升起來的日頭斜斜地打在寺裡那片高高的樹林上，把最頂端那一層葉子照得整片發亮，底下卻還是一片青綠色的陰。他仰著頭走了幾步，忽然覺得長安、官場、這幾年他一直放不下的那些事情，好像在踏進山門的那一刻就已經被留在外頭。

他叫常建，開元十五年的進士。你聽我講一件事就明白他當時是什麼心境。他跟王昌齡是同榜。那一榜金光閃閃，全長安的人都在傳，可是十幾年過去了，王昌齡被丟到江寧當一個小小的丞，他自己也不過在盱眙當一個更小的尉。兩個當年一起在曲江池邊喝酒賀新科的少年，到頭來都被朝廷擱在不上不下的小地方磨了大半輩子。他不是沒有抱負，只是抱負這種東西他這輩子看樣子是拿不回來了。這一年他請了幾天假，一個人跑到常熟散心，昨晚就住在山下的客棧。今天早上天剛亮他就上山了。這座寺廟後院有一條小徑，據說彎彎曲曲能一直通到後山最深的地方。他一邊走一邊聽腳下的落葉聲，走了不知道多久，那條路越走越窄、越走越暗，兩旁的樹葉幾乎要遮住他的頭頂。他心想這樣走下去到底通到哪裡，可是也捨不得回頭。

轉過最後一個彎，眼前忽然開了。他看見一間小小的禪房，被一整院的花木深深地圍在中間，門是掩著的，屋簷底下掛著一串沒有響的風鈴。禪房前有一方小小的潭，潭水黑亮亮的，把上方的天光和樹影原封不動地照了下來。他走過去在潭邊坐了下來。過了一會兒他發現一件奇怪的事——山那頭的鳥叫得比他印象裡任何一次聽到的都要自在，像牠們也知道這裡不會有人來打擾；而他盯著潭裡那個自己的影子看久了，忽然覺得心裡那些堆了好幾年的東西，一件一件地被水面吸走了。他就那樣坐著，久到連寺裡的鐘磬都敲響了，他才回過神來——原來這整片山，除了那口鐘，什麼聲音都沒有。

他起身往回走，走到寺門口跟一位老僧要了紙筆，就地在牆上題下八句：清晨入古寺，初日照高林。曲徑通幽處，禪房花木深。山光悅鳥性，潭影空人心。萬籟此都寂，但餘鐘磬音。寫完他把筆一擱就下山了。一千三百年過去，那間禪房早已經不在了，那位老僧的名字沒人記得，連他自己晚年隱居鄂州的墳都找不著了。可是「曲徑通幽處」後來變成中文裡形容彎彎曲曲通往幽靜之地的固定講法——只要有人走進一條看不見盡頭的小徑，就等於替他把那個清晨又走了一次。`
  },

  // id=155 中唐 劉長卿 〈尋南溪常山道人隱居〉rating=5
  // 詩眼：他去找朋友，朋友不在，他不敲門也不等，繼續往山裡走，在溪邊跟一朵花對看，忘了自己來幹嘛
  // 隱藏連接：被貶睦州時期，袖子裡揣著一張始終沒交出去的拜帖
  155: {
    title: "尋南溪常山道人隱居",
    author: "劉長卿",
    summary: "他袖子裡揣著拜帖走了一下午，最後那張帖子連遞都沒遞出去",
    story: `跟你說我朋友文房那年一個秋天下午的事。他袖子裡揣著一張前一晚就寫好的拜帖，走了大半個下午，帖子還沒交出去。他要去南溪拜訪一位道士朋友——這人的名字沒留下來，他自己在詩題裡叫這人常山道人。文房這一路走得慢，走到山腳下抬頭看，才發覺天光已經斜了。

他叫劉長卿，字文房，開元二十一年的進士。這件事還得從他被貶睦州司馬那幾年講起。他一輩子被貶過兩次，兩次都不算什麼滔天大罪，只是他這個人嘴硬，遇到看不慣的官場作為就要頂兩句，頂完就被丟到江南這些偏遠州縣裡去消磨。他自稱五言長城，這種話擺在朝廷高位的人聽了刺耳，擺在山野道人耳裡卻是笑話一則。常山道人就是這幾年他在附近山裡結識的一位朋友，隔幾個月他就會揣著寫好的拜帖上山來走一趟。這一年秋天他又動了念頭，昨晚一夜沒睡好，天剛亮就從州衙裡溜出來，一路走到南溪這座山下。他不是要來吐苦水的，也不是要來問路的，他只是想在朋友那間茅屋前坐一個下午，聽對方煮茶的聲音。

從山腳往上走，一條小徑穿過整片矮矮的雜木林。他走到半途忽然停下來看地面——濕潤的莓苔上壓著一串清清楚楚的鞋印，方向是從山裡往山外去的。道人今天出門了。他還是往上走。走到那間熟悉的茅屋前，屋前那片靜渚上白雲慢慢地飄過去，門口那簇芳草長得比他上次來還高了半截，門是掩著的，門閂上的銅環都蒙了一層灰。他沒有敲門，也沒有把袖子裡那張拜帖遞進去。他在門口站了一會兒，忽然覺得再等下去也沒意思，就轉身沿著茅屋後邊那條山路繼續往上走。

一陣雨剛剛過，他抬頭看兩旁的松，松針上還掛著水珠，被斜過來的日頭一照，整片松林亮得像重新染過一次。他順著山勢走，走到一處水聲很近的地方——原來這條路一直通到山泉的源頭。他找了塊石頭在溪邊坐下，把袖子裡那張拜帖拿出來看了一眼，又摺好放回去。水面上漂著幾朵不知名的野花，他盯著離自己最近的那朵看了很久，忽然覺得自己好像也不用見那位道人了。他心裡的話原本要跟朋友講，此刻對著這朵花，居然也講得清清楚楚，只是講到最後一句，他自己也講不出口了。他從懷裡摸出紙筆，就在溪邊寫下八句：一路經行處，莓苔見履痕。白雲依靜渚，芳草閉閒門。過雨看松色，隨山到水源。溪花與禪意，相對亦忘言。

他寫完把紙摺起來，塞進袖子裡那張沒送出去的拜帖旁邊，起身下山了。一千兩百多年過去，南溪那間茅屋沒有人知道確切在哪，那位常山道人的名字也沒人記得，連文房自己晚年葬在哪座山裡都眾說紛紜。可是每次有人上山去找一位朋友、走到門口發現朋友不在、卻捨不得掉頭就走的那個下午，都算是替他又走了一次那條溪邊的路。`
  },

  // id=165 中唐 李益 〈喜見外弟又言別〉rating=5
  // 詩眼：一輩子寫離別的人，總算逮到一次重逢，卻只有一夜
  // 隱藏連接：安史之亂那一代人，「見一次」就是「見最後一次」
  165: {
    title: "喜見外弟又言別",
    author: "李益",
    summary: "十年後在街上被喊住，回頭看見走散的表弟，然後明天他就要走了",
    story: `跟你說我朋友君虞的一個秋天下午。他那時候路過一個小城，走在街上，忽然聽到後面有人喊「請問先生貴姓」。他回過頭，站在面前的是一個風塵僕僕的中年男子，眉眼陌生，卻又不完全陌生。

那年距離安史之亂結束已經好多年了。君虞小時候就在那場動亂裡跟大半個家族走散——他是隴西人，戰火一起，父輩帶著能走的孩子往南逃，能走散的親戚就走散了。他從小記得母親娘家有個表弟，比他小幾歲，家裡人叫他小名。可是十歲之後那個名字他就沒再聽到過。他以為這輩子大概不會再見了。

眼前這個人先自報了姓。姓對了。君虞心裡咯噔一下，又問了名字。對方講出來的那一刻，他忽然想起十歲那年在某個院子裡，一個更小的孩子被大人推著跟他行禮的樣子。是那張小臉，長成這樣了。兩個大男人站在街上愣了半晌，說不出話，然後一起哭了一場，笑一場，拉著彼此的袖子去找了間酒館。那天下午他們坐下就沒再起來。君虞問他這些年在哪，他問君虞這些年在哪。兩個人講的都是「後來我到了⋯⋯」「後來又聽人說⋯⋯」「差一點就死在⋯⋯」的故事。他們把彼此走失之後的十年，一段一段對起來——誰死了，誰嫁了，誰去了哪個州、又流落到哪個郡，母親那邊的老屋還在不在。桌上的酒不斷續，天色慢慢黑下去，君虞抬頭才發現遠處寺廟的暮鐘已經敲了一輪。他一驚：他們從中午講到晚上，一句話都沒停過。

那個瞬間他胸口很堵。他這一輩子寫過那麼多離別——寫過邊塞的兵、寫過閨中的婦、寫過整個時代的離散——今天總算逮到一次重逢了，可是逮到的同時，另一件事也擺在眼前：他明天就要走了。君虞要往巴陵去，表弟要往另一個方向，兩個人明天一早分道。那晚回到旅舍，他點了燈，把整個下午在心裡翻了一遍，提筆寫下：十年離亂後，長大一相逢。問姓驚初見，稱名憶舊容。別來滄海事，語罷暮天鐘。明日巴陵道，秋山又幾重。

第二天君虞真的上路了。走出城不久就是山，翻過一座還有一座，秋天的葉子紅得刺眼。他心裡清楚，這一別，這輩子大概真的不會再見了——他那個時代的人，見一次往往就是見最後一次。一千兩百年過去，李益一輩子寫的離別詩多到自己都數不清，可是後人記得最牢的偏偏是這一首「喜見」——因為那個下午他碰巧沒在寫離散，他在寫他總算逮到的、只有一夜的重逢。而那位表弟後來到底叫什麼名字、走到哪裡去了，君虞自己都沒在詩裡留下來，只留下街上那一聲「請問先生貴姓」。`
  },

  // id=170 中唐 賈島 〈題李凝幽居〉rating=5
  // 詩眼：為了一個字反覆比劃到撞上京兆尹，撞出中文史上最有名的一次改字
  // 隱藏連接：韓愈就是那位京兆尹，這一撞撞出了他一生最重要的朋友
  170: {
    title: "題李凝幽居",
    author: "賈島",
    summary: "他為了一個字騎在驢上比手勢，一頭撞進了京兆尹的儀仗隊。",
    story: `跟你說我朋友浪仙那天在長安街上鬧的笑話。他騎在驢背上，一隻手往前推，又縮回來換成握拳輕輕敲空氣，推一下，敲一下，嘴裡念念有詞，眼神完全飄走。街上人來人往他一律看不見。就在他手勢做到第不知道幾次的時候，前面忽然一陣鑼響——他一頭撞進了京兆尹韓愈的儀仗隊裡。隨從把他從驢上拽下來，按在地上要治他衝撞的罪。浪仙一臉茫然，開口第一句居然還是：對不起，我剛才在想一個字。

事情要從幾天前那個晚上講起。浪仙有個朋友叫李凝，隱居在長安城外很偏的一處荒園裡。浪仙自己早年當過和尚，法名無本，這幾年還俗了考科舉，可是走路的節奏還留著，慢，安靜。那晚他一個人去找李凝。園子四周沒鄰居，只有一條長滿野草的小徑通到門口。他走了很久才到，抬頭時月亮已經爬得老高。池邊的樹上有隻鳥被他驚了一下，抖了抖翅膀又睡回去。他站在門前伸手想推門——手停在半空。要不要先敲一下？主人這麼晚了應該已經睡了。可是直接推進去，好像也太不客氣。他站在那裡猶豫了半天，最後還是輕輕敲了兩下。李凝披著衣服來開門，兩人坐到天快亮，聊到過橋看見的田野景色，聊到夜裡走山路石頭挪動雲彷彿也跟著動，聊到什麼時候再約。分手時他跟李凝說：我暫時走，還會再回來，不會辜負這一次約定。

回長安的路上，他就一直在想門前那個手勢：到底該用推，還是用敲。推顯得他跟主人熟，敲又更貼那晚的靜。他反覆做，做到撞了韓愈的儀仗。韓愈聽完隨從轉述，把他叫到跟前。這位韓文公自己也是詩人，他沒罵，反而低頭想了一會兒，說：用敲比較好。夜那麼靜，忽然一聲門響，那份寂才被撐開。浪仙當場愣在原地，然後幾乎是抖著手，把心裡念了一路的那首詩改成定稿：閒居少鄰並，草徑入荒園。鳥宿池邊樹，僧敲月下門。過橋分野色，移石動雲根。暫去還來此，幽期不負言。

從那天起，浪仙跟韓愈成了朋友。韓愈後來替他改詩、替他寫序、替他撐過好幾段沒錢的日子。至於那個晚上他站在門前猶豫的手勢，一千兩百年之後還在被人用——凡是有人為了一個字翻來覆去拿不定主意，中文裡就管那件事叫「推敲」。浪仙那天騎在驢上撞了官，撞出了他這輩子最重要的朋友，也撞出了後來所有寫作的人共用的一個詞。`
  },

  // id=190 盛唐 李白 〈登金陵鳳凰樓〉rating=5
  // 詩眼：晚年李白在鳳凰臺上，還想把三十年前黃鶴樓那口輸掉的氣吐回去
  // 隱藏連接：多年前登黃鶴樓看見崔顥題詩、放下筆的那一刻，一直沒過去
  190: {
    title: "登金陵鳳凰樓",
    author: "李白",
    summary: "六十一歲的李白，還在跟三十年前那個沒寫出來的自己拼一場",
    story: `跟你說我朋友太白晚年那天登金陵鳳凰臺，六十一歲的人，站在臺上望著長安的方向。天上一整片浮雲把太陽壓得看不見，他瞇著眼看了很久也沒看穿。這個仰頭望西邊的動作，他做了快三十年，從那次登黃鶴樓開始。他手裡的筆一直沒動。同行的人以為他還在等靈感，其實他在等一個人不在場、卻壓了他半輩子的對手。

事情要從很久以前那次登黃鶴樓講起。年輕的太白登樓，本來想寫一首壓場的詩，結果一抬頭看見牆上崔顥題的〈黃鶴樓〉，昔人已乘黃鶴去，此地空餘黃鶴樓。太白把毛筆放下，跟身邊人說了他這輩子唯一一次認輸的話，眼前有景道不得，崔顥題詩在上頭。他當場沒寫。可是那口氣他一直嚥不下去。這些年他南下北上，被玄宗放出翰林，被李璘拖進亂軍，被朝廷判了流放夜郎，又在白帝城半路上遇了赦，一路顛簸到江東。他一直在心裡挑地方，哪一座樓、哪一個角度，能讓他把那口沒吐出去的詩吐出來。他終於選中了金陵這座鳳凰臺。他聽人說古時候有鳳凰在這裡遊過，如今鳳凰飛走，臺空著，只剩江水自顧自流。他心裡清楚，這個開頭夠了，跟崔顥的黃鶴一樣夠了。

太白抬眼往四下望。曾經是東吳宮殿的那片地方，如今花草埋沒了一條幽徑；曾經穿高冠華服在此進進出出的東晉達官貴人，如今都堆成古老的墳丘。他望向遠處，江邊三座山峰半藏在青天之外，白鷺洲把秦淮河切成兩道水。他再回頭看長安的方向。浮雲還在，日還被遮著。他心裡最痛的其實不是崔顥，是那個「日」，是那個他這輩子再也回不去的朝廷。他手裡的筆終於動了。鳳凰臺上鳳凰遊，鳳去臺空江自流。吳宮花草埋幽徑，晉代衣冠成古丘。三山半落青天外，二水中分白鷺洲。總為浮雲能蔽日，長安不見使人愁。

寫完他自己站了很久。他心裡明白，這首還是沒贏過崔顥。崔顥的樓是空的，他的樓也是空的；崔顥收在鄉愁，他收在長安。同樣的骨架，他只是多裝了自己一輩子的政治委屈進去。第二年他就客死當塗，沒等到浮雲散，沒等到長安重新看見他。可是他那天在鳳凰臺上仰頭望西邊的動作，還有那片一直壓在他心頭、也壓在後世每一個懷才不遇的人心頭的浮雲，從那個下午被他寫下來之後，就再也沒散過。`
  },

  // id=191 盛唐 李白 〈上李邕〉rating=5
  // 詩眼：被大官冷落的年輕人，當晚寫詩把大官頂回去，還搬孔子出來壓場
  // 隱藏連接：多年後李邕被李林甫杖殺，太白反過來替他鳴不平
  191: {
    title: "上李邕",
    author: "李白",
    summary: "被大官冷笑打發的少年，回旅店連夜寫了一首詩，把孔子搬出來嗆回去。",
    story: `跟你說我朋友太白二十歲出頭那年做過一件很有名的事。他跑去拜見一位大官，被冷冷地打發出來，當晚回到旅店，連夜寫了一首詩嗆回去。那位大官叫李邕，是全大唐最出名的拔才之人，書法第一，文章第一，朝野人脈第一，天下讀書人都想繞道去見他一面。太白從蜀地翻山出來遊歷，第一站走到渝州，就打定主意要見他。他在旅店裡把最好的一件青衫換上，把腰帶勒緊，出門前還特別對著銅盆水照了照臉。同行的朋友勸他嘴巴放收一點，李刺史又不是玄宗。他笑著回，就是因為不是玄宗，所以更值得他去。他抬頭看了看刺史府那道高門，深吸一口氣，跨了進去。

李邕坐在堂上，眼皮抬也沒抬。太白行過禮，開口就是一整篇。他跟李邕說自己讀過《莊子》裡那隻大鵬，一日隨著風起，扶搖直上就是九萬里，翅膀掠過北海，簸得滄溟水都翻。他說自己就想做那樣的人，此番出蜀，是想跟著天下最大的一場風飛一次；他還說他寫的詩不甘於平調，志向也不甘於小局。他越講聲音越響，堂上迴著他自己的迴音。李邕的眉毛一直沒動，只是端起茶盞喝了一口，又慢慢地放下。屋簷外的日光斜進來，照到太白鞋尖那一小塊。李邕終於開口，說了兩三句不鹹不淡的場面話，就示意左右送客。太白從刺史府退出來的時候，脖子紅到耳根。同行的朋友在門外等他，一看他的臉就知道結果。兩個人一路走回旅店，誰也沒說話。

回到房間，太白坐在燈下發了半晌呆。他忽然想起剛才李邕嘴角那個一閃而過的弧度，那分明是冷笑。世人早就習慣他這種殊調、這種大言，也早就習慣在他背後笑。可他偏偏不服氣。他想到孔子，唐朝人尊稱宣父，宣父親口說過後生可畏。連宣父都懂得敬畏年輕人，你李邕算什麼。他一把把紙鋪開，蘸墨，運筆，一口氣寫下：大鵬一日同風起，扶搖直上九萬里。假令風歇時下來，猶能簸卻滄溟水。世人見我恆殊調，聞餘大言皆冷笑。宣父猶能畏後生，丈夫未可輕年少。天還沒亮，他就叫醒僕人，把詩封好，送回李邕府上。

李邕收到詩後沒有回音。太白也沒等，第二天就繼續往東走。這件事他此後再沒提過。很多年之後，李邕被李林甫誣陷，七十歲那年被朝廷杖打致死。消息傳到太白耳裡，他寫了另一首詩替李邕鳴不平——原來他一直記得渝州那個下午，也一直敬重那個看不上他的老人。可他二十歲那個夜裡在旅店燈下寫下的那隻大鵬，那口沒吐出去的氣，卻早已飛出渝州、飛出盛唐，飛進後世每一個被冷落過、卻還相信自己能九萬里的年輕人心裡。`
  },

  // id=196 盛唐 杜甫 〈登高〉rating=5
  // 詩眼：一個沒有酒的重陽節，五十六歲的老頭把一輩子壓進八句話
  // 隱藏連接：三十二年前二十四歲登泰山寫下〈望嶽〉的同一個人，如今拄杖登臺
  196: {
    title: "登高",
    author: "杜甫",
    summary: "沒有酒的重陽節，他一個人拄著拐杖爬上臺",
    story: `跟你說我朋友子美那個重陽節。那年他五十六歲，人在夔州。牙齒掉了大半，右耳已經聾了，風濕犯起來連筆都握不穩。九月九這天，按唐人規矩，家家戶戶都要跟家人一起登高、佩茱萸、喝菊花酒。可他家人一個都不在身邊，弟弟散在山東河南，妻小遠在幾百里外。他一個人拄著竹杖，慢慢往夔州城外那座高臺走。走到一半他停下來咳，咳完抬頭看天，三峽的天秋天特別高，高到讓人心裡發空。他腰上還掛著一個空酒杯，那是這幾年隨身的老習慣，可醫生剛叫他戒酒，這是他這輩子第一個沒酒的重陽節。

他終於爬上臺。風在耳邊刮，很急，把他花白的鬢邊吹亂。江邊猿在叫，那種淒厲的聲音一聲接一聲。他順著風看下去，江中央那塊沙洲白得刺眼，鳥兒一群群在渚上盤旋、又飛回。頭頂的樹一直在掉葉子，沒有邊、沒有盡頭，蕭蕭地下著。腳下的長江滾滾往東流，一波接一波，也沒有停過。子美站在那裡看了很久。他忽然想起自己二十四歲那年爬泰山，那時他寫過會當凌絕頂，一覽眾山小，覺得整座天下都是他要去的地方。三十二年過去了，同樣是登山，他這次爬得動的只有夔州這座小小的臺。

他忽然很想把這輩子的路，從長安到華州、從秦州到成都、從梓州到夔州，那萬里的漂泊、那一個又一個作客的秋天、那被病拖著走的百年、還有此刻一個人站在臺上的孤獨，全部說出來。他從懷裡掏出紙筆，就著風一口氣寫下八句話：風急天高猿嘯哀，渚清沙白鳥飛回。無邊落木蕭蕭下，不盡長江滾滾來。萬里悲秋常作客，百年多病獨登臺。艱難苦恨繁霜鬢，潦倒新停濁酒杯。

寫完他把紙折起來收進懷裡，拄著竹杖慢慢下山。腰上那個空酒杯還是空的。兩年後，子美死在湘江的一條小船上，沒能再回一次長安，也沒能再登一次泰山。可他那個下午在夔州臺上寫下的八句話，把一個五十六歲老頭的萬里漂泊、百年疾病、和一個人登臺的孤獨全部壓了進去。明代的胡應麟後來讀到，說它是古今七律第一。子美不會知道這件事。他只是在那個沒有酒的重陽節，一個人爬上臺，把該說的話說完，然後拄著拐杖下山。`
  },

  // id=215 中唐 白居易 〈望月有感〉rating=5
  // 詩眼：一個年輕人在戰亂饑荒的深夜，同時寫一封信寄給五個散在五處的親人
  // 隱藏連接：同一輪月亮此刻正照在浮梁、於潛、烏江、符離、下邽五個地方
  215: {
    title: "望月有感",
    author: "白居易",
    summary: "戰亂饑荒的深夜，他寫一封信，同時寄給五個地方的親人",
    story: `跟你說我朋友樂天那個秋夜。他人在符離，屋裡點著一盞油燈，桌上鋪了五張紙。你沒看錯，是五張。他今晚不是要寫一首詩寄給一個人，他是要同時寫給五個人。二十八歲的樂天已經好幾個月沒見著自家兄弟姐妹了。大哥幼文遠在浮梁當縣主簿，七哥在於潛，十五哥在烏江，弟妹一半還留在符離、一半在下邽老家。五個人，五個地方，中間隔著幾千里江山。他把紙攤好，坐下來看了看窗外。那晚月亮很亮，亮得他握筆的手都有點抖。

樂天那幾年過得不太好。貞元十五年前後，河南先鬧藩鎮的兵，李師古、吳少誠這些節度使輪流打仗，把中原攪得雞犬不寧；關內又碰上大旱，關中一整片田地都荒了，餓死人的事情天天在傳。他家本來就不算什麼望族，這樣一鬧，僅剩的那點田產也守不住了。兄弟姐妹被逼著各自逃難，投一點遠親、投一點朋友，就這樣散在了五個州縣。樂天算過，這五個人沒有一個能團聚，連寫封信都要繞好幾個月才能到。他坐在符離的燈下想他們此刻在做什麼：大哥或許剛下衙門，七哥可能替朋友寫著什麼，十五哥在江邊喝一杯冷酒，弟妹也許正躲著鄰居的閒話。想著想著，他抬頭看月亮，忽然發現一件很簡單的事：這輪月亮，此刻也照在浮梁、也照在於潛、也照在烏江、也照在下邽。五個人抬頭看的，是同一個月。

樂天忽然覺得眼睛發熱。他這麼一想，五個人的臉在他腦子裡同時浮起來，像被誰抓亂的一把線，怎麼都抖不開。他把筆蘸了墨，就著月光，在第一張紙上寫了下去：時難年荒世業空，弟兄羈旅各西東。田園寥落干戈後，骨肉流離道路中。弔影分為千里雁，辭根散作九秋蓬。共看明月應垂淚，一夜鄉心五處同。寫完他放下筆，把手在袖子上擦了擦，拿出第二張、第三張，一張一張抄下去，一直抄到五張都抄完。他要讓大哥、七哥、十五哥、符離的弟妹、下邽的弟妹，五個人今晚都收到同一份月亮。

天快亮的時候，樂天把五封信一一封好，寫上五個地址，交給第二天要出門的驛夫。他推開門到院子裡站了一下，月亮還在，只是低了些。他知道這幾封信要走很久才會到，到的時候戰事也許已經過去、饑荒也已經緩過來，可他此刻這一夜的心，只有這樣才能傳到五處。一千兩百年後，我們讀到這首詩，還是會抬頭看看窗外那輪月亮，想起自己也有幾個親人此刻在別的城市，看著同一個月。樂天寫給五個人的信，最後寫給了所有離家的人。`
  },

  // id=223 中唐 元稹 〈遣悲懷三首之二〉rating=5
  // 詩眼：三十一歲的鰥夫捧著亡妻的針線盒，怎麼樣都不敢揭開盒蓋
  // 隱藏連接：這個下午的深情是真的，兩年後他遇上新人也是真的，同一個人的兩段
  223: {
    title: "遣悲懷三首之二",
    author: "元稹",
    summary: "他把她的衣裳一件一件送出去，只有那個舊針線盒，他捧在手上怎麼樣都不敢打開",
    story: `跟你說我朋友微之那個下午。長安城裡一個平常的午後，屋子裡安靜得聽得見窗紙抖。他坐在地板上，前面攤著一堆衣裳，都是韋叢的。他把一件一件疊好，交給下人拿去分送——分給窮親戚、分給鄰家沒了娘的孤女、分給廟裡幫忙的婢子。一疊一疊送出去，眼看就要送完了。他手不停，眼神卻沒真對著手上的活。三十一歲的男人，臉上沒什麼表情。你要說他冷靜嗎？不，冷靜的人不會把這件事情，一個下午一個下午拖著做這麼久。

微之跟韋叢結婚的那一年，他才二十四歲。那時候他只是個校書郎，一個月的俸祿薄得可憐。韋叢是京兆尹韋夏卿家的大小姐，滿長安都知道那是名門的閨秀。當年韋家把女兒嫁給他，多少人在背後嘀咕：這小子憑什麼。韋叢自己一句怨言都沒有。她跟著微之搬進小巷子，自己下廚、自己洗衣、自己坐在燈下拿針縫補。有一回微之想喝酒沒錢，她二話不說，把頭上的金釵拔下來換酒——只要他高興。他們就這樣一起熬了七年窮日子。他好不容易熬上監察御史，日子才要好一點，去年韋叢就病倒了。她走的時候二十七歲。婢僕還在，屋子還在。微之對這些人特別憐惜，有時看見她生前用過的那個丫頭在院子裡曬東西，他就別開臉走過去。前些天他還夢見韋叢在冥間跟他要錢用，他半夜起來，燒了一疊紙錢。

那個下午他終於把衣裳送得差不多了。他忽然停下來——桌角有一個舊木盒，是韋叢生前做針線用的。盒蓋一角還垂著一根線頭。他把盒子捧起來，卻沒有打開。他知道裡面應該還有她沒縫完的一件衣、幾根縫衣針、幾團線。他捧著、捧著，怎麼樣都不敢揭那個蓋。他想起去年夏天她還在的時候，有一晚跟他半開玩笑地說過一句：我要是先走了，你怎麼辦？他那時只當她在鬧他，笑一笑就過了。屋子裡光線斜斜地落下來，他放下木盒，鋪紙研墨，寫下：昔日戲言身後意，今朝都到眼前來。衣裳已施行看盡，針線猶存未忍開。尚想舊情憐婢僕，也曾因夢送錢財。誠知此恨人人有，貧賤夫妻百事哀。

微之寫完，把筆放下。屋子還是那間屋子，木盒還是那個木盒。他伸手摸了摸盒蓋，還是沒打開。你要是問他這一生最疼哪一個人，他這個下午的答案毫無疑問是韋叢。我還是得老實跟你說一句：兩年後他遇上新的人，三年後他就再婚了。人的心從來不是只有一種形狀。可他這個下午，捧著針線盒不忍揭蓋的樣子，是真的。一千兩百年後我們讀到這幾行字，還是能看見那個三十一歲的男人坐在午後的光裡，手裡有東西，卻不敢打開。`
  },

  // id=237 晚唐 李商隱 〈無題二首之一〉rating=5
  // 詩眼：詩人躲進一個女子的口氣裡，替自己縫、替自己等、替自己問那句不敢問的話
  // 隱藏連接：末句「西南好風」化用曹植〈七哀詩〉「願為西南風，長逝入君懷」
  237: {
    title: "無題二首之一",
    author: "李商隱",
    summary: "他寫了將近二十首無題，這一首多加了一層——他躲進一個女子的口氣裡替自己說話",
    story: `跟你說我朋友義山的一個晚上。他一個人坐在燈下，紙擺好了，墨也磨開了，卻遲遲沒動筆。他今晚要寫的不是他自己——他要寫一個女子。他要學她的口氣、學她的手勢、學她夜裡縫東西的節奏。他心裡有這樣一個女子，可能是他很多年前遇過的，可能是他想出來的，也可能兩者都是。義山年輕時在玉陽山學道那幾年，相傳遇過一位女道士叫宋華陽，兩人短短相處過一段，後來不了了之。她真的存在嗎？學界到現在還吵。反正義山今晚要她活過來，替他說一句他自己不能說的話。

他先寫她的手。她坐在深夜的燈下，手裡是一疊薄薄的香羅，紋是鳳尾。她拿針，把好幾層疊起來慢慢縫，要縫一個碧色圖案的圓頂帳幕。這帳幕是為了他們兩個人。她不敢在白天縫，只能等所有人睡了才做。義山寫到這裡停了一下，他知道這種只能在夜裡進行的準備是什麼滋味，他自己一輩子都在寫這種不能公開的關係。他讓筆繼續替她走下去。他讓她想起某一次見面。她拿一把團扇，扇面剪得像一輪月魄，她想遮臉，可是遮不住害羞。他遠遠來了。他的馬車經過得太快，車輪響得像雷，人還沒對到眼，車就過去了。他們一句話都沒說上。她愣在原地，扇子還舉著，那半邊臉還紅著。義山寫到這裡又停了一下——他年輕時就是那種走得太快的人，來不及看見別人在等他。

他讓她整夜點燈等消息。燈心一寸一寸燒下去，變成黑色的金燼，屋子裡光越來越暗，她一個人坐到天快亮。等到五月，院子裡那棵石榴開了花，一朵一朵的紅。她想，這下總該有消息了吧。等到六月，石榴的果子都紅透了。什麼消息都沒有。他那匹身上有斑點的馬還繫在垂楊岸邊，她知道他就在不遠的地方。可她走不過去，他也不肯過來。她抬頭問了一句——義山把筆蘸滿了墨，一氣把最後一句寫下去。紙上是：鳳尾香羅薄幾重，碧文圓頂夜深縫。扇裁月魄羞難掩，車走雷聲語未通。曾是寂寥金燼暗，斷無消息石榴紅。斑騅只繫垂楊岸，何處西南待好風？

他知道最後那句「西南好風」是偷曹植的。曹植當年寫過：願為西南風，長逝入君懷。義山讓這個女子在千年後接住那陣風，從自己的心口再吹出來一次。他寫完，把紙收起來，沒給任何人看。這一首他自己知道就好。義山一輩子寫了將近二十首無題，每一首都藏著他不能公開講的心事。這一首他多加了一層——他躲進一個女子的口氣裡，讓她替他縫、替他等、替他問那句他自己不敢問的話：我在哪裡等一陣好風，把你送到我身邊？屋外天快亮了，燈也差不多燒完了。他吹熄燈，那疊紙壓在桌角。一千一百年後我們讀到它，還能看見那個夜裡，燈下有兩個人：一個縫著碧文圓頂帳幕的女子，和一個借她的手替自己活了一晚的男人。`
  },

  // id=238 晚唐 李商隱 〈無題二首之二〉rating=5
  // 詩眼：明知相思無益，仍執意惆悵到底——他借她的口，替自己一輩子的姿態命名
  // 隱藏連接：與 237 為姊妹作，同一夜寫成；他躲進女子口氣裡替自己說話
  238: {
    title: "無題二首之二",
    author: "李商隱",
    summary: "他借那個女子的口，替自己說出「明知沒用，我還要繼續」",
    story: `跟你說我朋友義山那一晚的後半段。他寫完鳳尾香羅那張紙，把它壓在桌角，本來要吹燈睡了，結果他又坐下來。他覺得那個女子還沒說完。他讓她縫了帳幕、讓她搖了扇子、讓她等了石榴紅，可是那些都是動作，那些不是話。他想聽她說一句話。他把紙重新鋪好，墨再磨了一次，替她開口。

他先把場景收得更緊。他不讓她再站在院子裡數石榴了，他讓她回到屋子裡，讓她把厚厚的簾幕一層一層放到底。他讓她躺下來。屋子叫甚麼名字呢？義山想了一下，借了南朝那個叫莫愁的歌女的名字，把她的堂屋叫做莫愁堂——這個名字取得諷刺，住在裡頭的人偏偏最愁。義山知道很多人一輩子就住在這樣一間名字寫得漂亮、裡頭卻空的屋子裡，他自己就住在其中一間。他讓她在莫愁堂裡躺下，把清冷的長夜拉得又細又慢，像有人拿針把時間一寸一寸挑開。

他讓她開始想事情。她想她這輩子曾經以為自己會有像巫山神女那樣的愛——雲雨繾綣，郎君會在夢裡按時出現。想著想著她自己笑了一下，那本來就是一場夢啊。她又想到自己現在的處境。她是小姑，是那種還沒嫁、獨自住著的女子，她的屋簷底下本來就沒有男人。義山寫到這裡，筆鋒忽然重了一下。他知道自己也是這種本無郎的處境。他一輩子想靠上一個靠得住的長官都靠不成，牛黨李黨兩邊看他都不順眼，他等的那陣風從來沒吹過來。他讓她替他把這件事說出去。

她接著想，命運為什麼要這樣對人。她想到河裡的菱枝——那麼細那麼脆，湖上一有風波就打上來，風波才不管你脆不脆。她又想到桂樹上的葉子——葉子能香，是月光和露水偷偷給的，不是它自己爭來的。義山把筆放輕，替她把最後兩句說出來。她躺在莫愁堂的簾幕裡，對著黑漆漆的屋頂，輕輕對自己說：重帷深下莫愁堂，臥後清宵細細長。神女生涯原是夢，小姑居處本無郎。風波不信菱枝弱，月露誰教桂葉香。直道相思了無益，未妨惆悵是清狂。

義山寫完最後那句，自己愣了很久。他知道最後那半句是他寫給自己的——就算知道這場相思沒有用，就算知道那個女子他這輩子都不會再見到，就算知道朝廷不會給他位子、朋友不會替他說話、抱負會爛在袖子裡，他還是要繼續惆悵下去。這種明知沒用還要繼續的執著，他叫做清狂。清狂，是他一輩子的姿態。屋外天真的快亮了。他把這張紙疊到第一張的下面，兩張一起壓在桌角。一千一百年後我們讀到它，還能看見那個燈下有兩個人：一個躺在莫愁堂裡把長夜挑得細細的女子，和一個借她的口說出「我知道沒用，可是我還要繼續」的男人。`
  },

  // id=246 晚唐 秦韜玉 〈貧女〉rating=5
  // 詩眼：一輩子替權貴繡嫁衣的幕僚，替一個陌生貧女、也替自己哭了一次
  // 隱藏連接：秦韜玉投靠宦官田令孜當幕僚，跟貧女繡別人嫁衣是同一種姿勢
  246: {
    title: "貧女",
    author: "秦韜玉",
    summary: "工部侍郎在巷口看見一個繡嫁衣的女孩，忽然認出鏡子裡的自己",
    story: `跟你說我朋友仲明的一個下午。他從長安某條窄巷走過去，看見一戶蓬草編門的人家門口坐著一個女孩，膝上攤著一件紅底描金的嫁衣，正低頭壓金線。他停下來。他愣了一下，然後在那扇蓬門外站了很久。他知道那件嫁衣不是女孩自己的。

那時候仲明已經考了好多年科舉，屢試不中。他後來走了一條當時士人瞧不起的路——去投靠宦官田令孜當幕僚。田令孜是唐僖宗最寵信的宦官，權勢大得驚人。仲明替他寫過表章、擬過文書、應酬過宴會，做得又快又漂亮。中和年間他終於被特賜進士出身，掛上工部侍郎的官銜。他該高興，可是每次跟以前那些正途出身的舊識喝酒，人家看他的眼神都閃過那麼一下——「哦，田令孜家的秀才」。仲明知道那一下是什麼意思。

他把目光收回來，繼續看那個女孩。她的手很巧，十根指頭在紅緞子上翻飛。她臉上沒抹粉，眉毛也沒畫長。她從沒穿過綺羅，沒聞過那種富貴人家女兒身上熏了三天的香。她曾試著託人問過良媒，話還沒說完自己先難過起來。當下城裡姑娘們流行學宮裡那種儉樸打扮爭寵，她那點乾淨的高格調沒人稀罕。仲明看著看著，忽然覺得那個女孩就是他自己。

他回家，鋪紙，磨墨。他寫得很快，寫的時候手有點抖。

蓬門未識綺羅香，擬托良媒益自傷。誰愛風流高格調，共憐時世儉梳妝。敢將十指誇針巧，不把雙眉鬥畫長。苦恨年年壓金線，為他人作嫁衣裳。

寫完他把筆擱下，沒給任何人看。他知道舊識讀了會笑他矯情——你都當到工部侍郎了還哭什麼窮。可是仲明真的想哭。他這輩子替田令孜寫、替朝廷寫、替一個又一個掌權的人寫，那些字都是別人穿的嫁衣。他自己那件，永遠繡在別人身上。

一千年過去，晚唐早散了，田令孜早死了，那個午後坐在蓬門外的女孩沒人知道後來嫁了沒。仲明本人的名字，在正史裡也只剩下薄薄兩行「投靠宦官、特賜進士」的評語，其他詩幾乎沒人記得。可是他那天替她也替自己說的那句「為他人作嫁衣裳」，卻活得比誰都久。每一代都有人在燈下替別人壓金線，抬頭看見鏡子裡的自己，忽然就懂了那個晚唐的午後，站在一戶蓬門外久久不走的那個人。`
  },

  // id=249 北宋 黃庭堅 〈寄黃幾復〉rating=5
  // 詩眼：一個北方的中年男人，替十年沒見的南方老朋友，把當年的一杯酒接到今夜的一盞燈
  // 隱藏連接：兩個都姓黃的江西少年，年輕時同鄉同讀同飲，中年後一個渤海邊、一個南海邊
  249: {
    title: "寄黃幾復",
    author: "黃庭堅",
    summary: "北海南海之間，桃李春風的一杯酒接上江湖夜雨的十年燈",
    story: `跟你說我朋友魯直，就是黃庭堅，那一年春天的一個下午。

元豐八年，山東德平鎮，四十一歲的魯直站在官舍院子裡。院牆外幾株桃樹開得正好，天很藍。他抬頭看見一隻大雁往北飛，本來要走進屋，忽然停下來。他想到黃幾復了。他跟幾復已經整整十年沒見面。他站在渤海邊的德州當一個小小的監鎮官，幾復在南海邊的廣東四會當縣令，一個北海，一個南海，中間隔了幾千里。

跟你說幾復是誰。他本名黃介，字幾復，跟魯直同姓卻不同族，是老鄉，都是江西人。年輕時兩個姓黃的少年在江西一起讀書、一起考試、一起喝酒。桃花李花開的春天他們會湊錢買一壺酒，坐在花底下把整個下午耗掉，講以後要怎麼做官、要怎麼把日子過成想要的樣子。後來兩人都中了進士，然後就被打散。魯直輾轉汴京、葉縣、北京大名府、德州德平，幾復從此一路南下，越走越遠，最後掉進嶺南那個當時中原人聞之色變的四會。這十年之間，魯直寄過信，也託過人。可是相傳大雁只飛到衡陽就折返，飛不過南嶺，那些信不知道有沒有到。他站在院子裡，看著剛才那隻雁的影子沒進雲裡，覺得又可笑又難過。

他走回書房。他不是要哭，他是想寫點什麼給幾復。他坐下磨墨，磨著磨著就開始想像幾復此刻在做什麼。大概還在四會那個小縣衙裡，家裡窮得只剩四面光牆，白天替鄉民斷案治病，樣樣都行，根本不用像古人那樣折斷幾次手臂才學會怎麼當醫生。他想像幾復低頭讀書，抬頭已經是滿頭白髮，窗外隔著一條溪，猿猴在瘴氣裡叫，藤蔓長得亂七八糟繞滿溪邊。他愈想愈清楚，就把筆蘸飽，一口氣寫下去：

我居北海君南海，寄雁傳書謝不能。桃李春風一杯酒，江湖夜雨十年燈。持家但有四立壁，治病不蘄三折肱。想得讀書頭已白，隔溪猿哭瘴溪藤。

寫到中間他停了一下。那個桃李春風下一起喝的一杯酒，跟這十年來各自在江湖上、隔著風雨、對著一盞燈熬過去的夜晚，就這樣被他一句對上一句。他把紙折起來，交給要南下的人。信有沒有到四會，史書沒說。幾復後來早早就死了，兩個姓黃的少年再沒能坐在同一株桃樹下把那壺酒喝完。可是那十四個字一千年來替所有久別的朋友活著，每一個在燈下想起遠方某個人的夜晚，那盞燈都還亮著。`
  },

  // id=254 清 納蘭性德 〈木蘭花-擬古決絕詞柬友〉rating=5
  // 詩眼：擁有一切的年輕人在深夜替自己寫一封絕交信，收信的名字寫著朋友，其實留給的是自己
  // 隱藏連接：他借女子被辜負的殼寫給變心的朋友，可是同一個「初見」還藏著他 22 歲那年死去的妻子盧氏
  254: {
    title: "木蘭花-擬古決絕詞柬友",
    author: "納蘭性德",
    summary: "22 歲喪妻的一等侍衛，深夜替自己寫的一封絕交信",
    story: `深夜，容若把自己關在書房裡，桌上一盞燈、一支筆、一疊還沒動過的紙。門外是明珠相府整個秋天最安靜的時辰。白天他還是那個一等侍衛，跟康熙同齡，站在乾清宮外陪皇上騎馬打獵；此刻他二十六七歲，父親是當朝宰相，家裡有兒有女，全北京城的少年郎誰不羨慕他。可是他手裡捏著一封剛收到的信，看了三遍，把信丟在燭火旁邊，沒燒。他今晚要寫的不是普通回信，他要寫一首詞，寄給那個變心的朋友，斷。

容若這輩子最痛的事，是他二十二歲那年妻子盧氏死了。三年過去，他寫的悼亡詞一疊比一疊厚，同僚勸他別再鑽下去，他懂，他就是放不下。他放不下的其實不是盧氏一個人，他放不下的是「初見」那兩個字。跟盧氏成親前隔著窗子互看第一眼的那個下午，兩人一句話都沒說；就是那一眼，他往後多少個秋天都想回去。而今坐在燈下，這封信讓他忽然意識到——他這個朋友，當年也跟他有過那樣的下午。兩人在誰家的院子喝酒喝到深夜，說以後要一起怎樣，也拍胸脯講過比翼、講過連理。這封信裡，這個朋友字字翻臉，把當年的話說成是他容若一個人在痴想；變心的明明是他，還說是容若的心易變。容若坐在燈下笑了一聲。

他決定不寫絕交兩個字。他要用一個女子的口吻替自己講。他想起班婕妤——被漢成帝冷落之後把自己寫成秋天用不到的一柄畫扇；他想起唐玄宗——那個他跟著白居易讀了半輩子的老皇帝，在驪山長生殿跟貴妃私語到半夜，馬嵬坡兵變之後雨裡的鈴聲一路響進他心裡；可是玄宗到死沒怨過貴妃，貴妃到死也沒怨過玄宗。世人罵玄宗薄倖，玄宗至少還記得那一夜的誓言。窗外秋風把院子裡一枝樹搖得沙沙響。他蘸了墨，一口氣把八句寫完：人生若只如初見，何事秋風悲畫扇。等閒變卻故人心，卻道故人心易變。驪山語罷清宵半，淚雨霖鈴終不怨。何如薄倖錦衣郎，比翼連枝當日願。

他把紙折了兩折，明早讓家人送出去。他吹熄燈，可是沒睡著。黑暗裡他又想起盧氏，想起隔窗第一眼的那個下午。這首詞封面上寫「柬友」，那個朋友到底是誰，後世怎麼都查不清，也許是顧貞觀，也許是別的什麼人；被他寫絕的，也許根本不是任何一個朋友，是他自己這幾年放不下的執著。三年多後他三十歲病死了，那封信寄了誰、對方讀沒讀，史書沒留一個字。可是他那一夜落筆的第一句，三百多年來每一個被辜負過的人都替他念過一遍。那盞燈只亮了一夜，那七個字「人生若只如初見」亮到了現在。`
  },

  // id=260 盛唐 李白 〈獨坐敬亭山〉rating=5
  // 詩眼：五十三歲的漂泊者在山頂發現只剩這座山還肯陪他
  // 隱藏連接：他來宣州追偶像謝朓的腳步，這一趟卻只剩山
  260: {
    title: "獨坐敬亭山",
    author: "李白",
    summary: "五十三歲的太白爬上敬亭山，發現整個天地間只剩這座山還肯陪他坐",
    story: `秋天下午。太白從宣城的城門走出來，一個人往北邊的山走。這年他五十三歲，走得比十年前慢很多。路邊的稻子已經黃了，農人在收，沒人抬頭看他。太白穿的還是那件舊袍，腰上別著酒葫蘆，葫蘆裡沒剩多少酒。他不趕時間，也沒人在敬亭山上等他。他一步一步往山上走，太陽從雲後面透出來，把整條山路照成淡淡的金色。他停在半山腰喘氣，回頭看宣城，城裡也沒有一個人在等他回去。他笑了一下，繼續往上爬。

太白為什麼一輩子跑宣州跑了七次？因為他心裡有一個偶像——南朝的謝朓。將近三百年前，謝朓在這裡當太守，寫過「餘霞散成綺，澄江靜如練」，還在敬亭山蓋過一座小樓。太白年輕時讀到這些詩，發過一個志願：這輩子一定要走一趟謝公走過的路。可是這一次，他已經不是年輕的太白了。他離開長安九年。九年前玄宗把他從翰林院客氣地送出去，「賜金放還」四個字說得漂亮，說穿了就是不要他了。九年裡他從長安走到齊州、金陵、廬山、江夏，處處找人喝酒、處處寫詩，也處處被人請走。老朋友一個一個死了或散了，妻子不在身邊。這一趟他自己來宣州，沒帶書童，沒約人。他來看謝朓，也來看看自己。

他終於爬到山頂，找一塊平的石頭坐下。他抬頭看天。剛才還有一群鳥在盤旋，一群、兩群，過了一會兒全飛遠了，天上一隻也不剩。他低頭喘氣，再抬頭時，西邊飄來一朵孤零零的白雲，從他頭頂慢慢過去，也不停留，慢慢往東邊飄走。整座山靜下來，靜到他能聽見自己的呼吸。太白坐在那裡不動。他忽然發現——玄宗不要他、朋友散了、家人不在身邊、連天上的鳥跟雲都不肯陪他久一點——這整個天地間，此刻只剩下他跟眼前這座山還在原地。他沒有覺得難過，反而覺得踏實。他看山，山也看他。兩個都不急著離開。他從懷裡掏出隨身的小紙，把二十個字寫下來：眾鳥高飛盡，孤雲獨去閒。相看兩不厭，只有敬亭山。

他把紙折好收進袖子，站起來拍拍衣襟，慢慢下山。太白這輩子寫過幾百次月亮、幾百次酒、幾百次朋友，這一天他只寫了一座山。四年後他六十二歲，死在當塗族叔李陽冰家裡，沒能再回敬亭山一次。可是他那個下午留在山上的姿勢——一個五十三歲的老人坐在石頭上跟一座山對看——一千兩百年來，每一個發現身邊沒人可以講話的人，都替他坐過一次。敬亭山本來只是宣州城北一座不高的山，因為他那個下午在那裡坐了很久，從此變成中國人心裡孤獨的時候都會想起的那座山。`
  },

  // id=274 中唐 白居易 〈問劉十九〉rating=5
  // 詩眼：一個被貶的中年男人在下雪傍晚寫便條問朋友要不要來喝一杯
  // 隱藏連接：同一段江州司馬時期他也寫〈琵琶行〉，悲愴與家常並存
  274: {
    title: "問劉十九",
    author: "白居易",
    summary: "被貶江州的樂天，替自己留下的一個下雪傍晚",
    story: `冬天傍晚，樂天站在江州住處的堂屋裡，手上抱著一個小小的酒罈子。這是他自己前幾天釀的米酒，罈口的封泥今天剛剛敲開。他把嘴湊過去聞——一股新酒的甜氣衝上來，罈口浮著一層淡淡的綠色酒沫，像被誰灑了一把細碎的浮萍。他笑了一下，把酒罈捧到窗邊放好。窗外的天色已經灰下來，風開始從江面上灌進院子。他抬頭看了看雲，那雲厚得不像今晚會善罷甘休。今年冬天江州的第一場雪，看樣子就要來了。他心裡忽然有個念頭：這種酒、這種天，一個人喝實在沒意思。

樂天今年四十六歲。兩年前他被從長安一路貶到江州當司馬，一個沒什麼實權的閒官。剛到江州那幾個月他心裡是慌的，寫〈琵琶行〉那個秋天，他在潯陽江頭聽琵琶聽到自己的眼淚打濕青衫，一整篇長詩寫下來人都虛了。可是江州住久了，他慢慢也學會不再那麼往裡拗自己。他在城裡認了幾個當地的朋友，其中一個是山裡的隱士，姓劉，家裡排行十九，大家都叫他劉十九。劉十九不做官、不趕熱鬧，家裡有幾畝薄田，愛讀點書，愛喝點酒。樂天在他身上聞到一種長安永遠沒有的踏實。這一年多來兩個人常常互相走動，有時候樂天走過去，有時候劉十九提著一小袋炒栗子走過來。今天樂天把新釀好的酒抱出來，第一個想到的人就是他。他叫小僕把牆角那個舊火爐搬到堂屋中央，火爐是用紅泥新糊過一層的，泥還帶著手指抹過的痕跡。爐子裡的炭燒得正紅，一屋子都是烘烘的暖氣。

樂天坐到火爐邊，把手伸過去烤了一下，然後從案上拿出一張小箋、一支筆。他抬頭再往窗外看一眼，天更暗了，第一片雪已經飄下來，貼在窗紙上化成一個小水點。他低頭想了想，也不打草稿，就把心裡那句話直接寫下去：綠螘新醅酒，紅泥小火爐。晚來天欲雪，能飲一杯無？他寫完自己讀了一遍，笑出聲來。這哪裡是一首詩，這就是一張便條、一句大白話——來喝一杯嗎？他把便條折好，塞進小僕手裡，交代他跑一趟劉家，路上小心滑。小僕跑出門，樂天把酒罈端到火爐邊坐下，一邊聽風一邊等人。

樂天在江州當司馬那幾年，寫過〈琵琶行〉、寫過〈長恨歌〉這種一寫幾百句、聽的人流眼淚的長篇。可是同一個人，也在同一段日子裡，替自己留了這樣一個冬天傍晚：一小罈酒、一個紅泥小爐、一個朋友、一場快下的雪、一張很短的便條。他這一天沒問朝廷、沒問前程、沒問自己還會不會回長安。他只問了朋友一句：來喝一杯嗎？一千兩百年過去，我們大部分人一輩子都沒被貶過官、沒寫過〈琵琶行〉，可是每次冬天下班回家、看見窗外開始飄雪、想找一個人喝酒的時候，心裡冒出來的第一句話，還是他那個下午替我們寫好的那一句「能飲一杯無」？`
  },

  // id=302 清 袁枚 〈苔〉rating=5
  // 詩眼：滿園牡丹的老詩人繞到後牆，蹲下來看見那朵沒人看的小花也在拚命開
  // 隱藏連接：他當年當知縣時見過的那些沒進縣誌的小百姓，就是這朵苔花
  302: {
    title: "苔",
    author: "袁枚",
    summary: "滿園牡丹的老詩人，繞到後牆蹲下來看那朵沒人看的苔花",
    story: `子才七十多歲了，一個春天下午。他拄著一根竹杖，站在自己南京隨園的牡丹圃邊上。牡丹開得正兇，一朵比拳頭還大，粉的紫的白的，一叢一叢像從土裡湧出來。子才家的牡丹是全南京最有名的，每年這幾天城裡的太太小姐、文人雅士都約好了往他園子裡跑，就為了看這場花。子才拄著杖笑咪咪站在花前看了半天，忽然覺得有點膩了。他跟身邊的小僕說，我到後面走走。小僕想跟，他擺擺手，一個人繞過假山，往園子後面陰暗的那一角走。

子才這輩子活得比他寫的詩還離奇。他二十四歲中進士，做了幾任知縣，三十三歲就辭官不幹了。他跑來南京小倉山下，把當年曹家一座荒掉的舊園子買下來，改名叫隨園。從那年起他就沒再出仕。他在這園子裡蓋了小屋、種了花木、養了一大堆貓、收了一群學生（男女都有，這在當時是要被罵的），一邊寫詩、一邊寫食譜、一邊跟遠道而來的客人講他的性靈說——寫詩要真、要有性情、不要死板守規矩。園子裡人來人往，牡丹芍藥杜鵑桃李輪番開，熱鬧得像個小天下。可是這一天他忽然想繞開這些花。他慢慢走到後院牆根，那裡陽光整個下午都照不進來，青苔厚厚地鋪了一層。他停下腳步，用竹杖點了點牆根。青苔綠得發油，一片一片貼在磚縫裡。他當年在江浦、在沭陽當知縣的時候，見過太多這樣的角落——住在山溝裡的小百姓，一輩子沒被縣太爺以外的人看過一眼，也沒進過縣誌。他們就是這種顏色。

子才彎下腰，蹲在牆根前。他老花眼，眼睛湊得離青苔只剩一個拳頭遠。他看見了。青苔上真的有花。米粒那麼小的花，一朵一朵頂在細細的莖上，青綠中透著一點淡黃。他愣了一下。他園子前頭那幾百朵牡丹，此刻正被一群人圍著讚嘆；而這幾朵沒有名字、沒人抬頭看的小花，也在同一個下午，把自己開了。它開得跟牡丹一樣認真，跟牡丹一樣拚。子才蹲在那裡看了很久，膝蓋都有點麻。他慢慢站起來，回到書桌前，拿了張小箋，寫下二十個字：白日不到處，青春恰自來。苔花如米小，也學牡丹開。

子才後來又活了很多年，一直到八十二歲。這首小詩他自己不特別當回事，扔在幾千首詩裡，兩百多年沒什麼人注意。差不多兩百年後，貴州山區一位鄉村老師帶著一群山裡的孩子把這首詩唱出來，全國才忽然聽見它。那些孩子就是子才那天下午蹲下來看見的苔花——大山把太陽擋住了，可是他們也在那裡，米粒那麼小，也認認真真地學牡丹開。那個春天下午子才繞過自己的牡丹去看的那一朵苔花，其實一直開到了今天。`
  },

  // id=305 盛唐 李白 〈清平調三首之一〉rating=5
  // 詩眼：爛醉如泥被架去見貴妃，卻在半醒之間寫出千古最美的讚美詩，伴君如伴虎的驚險全藏在字裡行間。
  // 隱藏連接：奉旨去找他的樂師李龜年，四十年後在江南遇見了杜甫。
  305: {
    title: "清平調三首之一",
    author: "李白",
    summary: "這三句流傳千年的絕美讚美詩，其實是李白被人架著、潑醒酒意之後，在半醉半醒間搶出來的急件。",
    story: `跟你說我朋友太白的一個中午。他被兩個小黃門一左一右架著，腳尖幾乎沾不到地，往興慶宮的方向走。這個人昨晚根本沒打算今天要見到全天下最有權力的女人——他只是照例在長安的酒肆裡喝到不知今夕何夕。

那年是天寶二年，太白剛進翰林院當供奉才一年多，說是皇帝身邊的紅人，其實常常沒什麼正經差事，就是陪著吟詩取樂。這天正好興慶宮沉香亭前的牡丹開得最好，玄宗帶著剛冊封不久的貴妃去賞花，興頭上了，叫梨園弟子準備奏樂。可是有人提醒他，今天這場面，配的還是舊詞舊調，賞名花對妃子，唱舊曲多沒意思。玄宗一聽有理，當場下令，不許再唱舊詞，去把翰林學士李白找來，現寫新詞。

派去找人的，是宮裡最紅的樂師李龜年。他拿著皇帝親筆的金花箋，一路問到太白常去的那家酒肆，結果人已經醉倒在案邊，怎麼叫都叫不醒。侍從只好抬他上馬車，一路顛簸進宮，又拿冷水往他臉上潑，潑醒了大半，才勉強把人架到沉香亭前。

太白睜開眼，眼前就是滿園牡丹、欄杆邊露水正濃，貴妃就站在那裡，笑意盈盈地看著這個東倒西歪的翰林學士。他腦子還混沌著，可是筆一拿起來，那股混沌忽然變成一種奇怪的清醒——他也管不了什麼君臣分寸了，提筆就寫，把眼前的女人寫得像天上下凡的仙子：

雲想衣裳花想容，春風拂檻露華濃。若非群玉山頭見，會向瑤臺月下逢。

一連三首，一氣呵成。滿殿都靜下來，玄宗親自吹笛伴奏，李龜年開口唱，貴妃舉著玻璃七寶杯，聽得眼睛發亮。太白這輩子沒有比這一刻更像個天才的時候——可是沒人知道，寫下這幾句時，他其實還沒完全醒酒。

後來的事，他自己大概也沒想到。高力士被叫去替他脫靴，記了這個仇，回頭在貴妃耳邊嚼舌根，說三首詩裡有一句拿她比漢朝那位下場淒涼、最後被廢賜死的趙飛燕，貴妃從此對他心存芥蒂。三首詩讓他紅極一時，也讓他徹底得罪了宮裡最不能得罪的兩個人。兩年後他被賜金放還，體面地攆出了長安。那天架著他進宮的李龜年，後來也離開了皇宮，流落到江南，四十年後，在一個落花時節，遇見了另一個從長安走出來的老朋友。`
  },

  // id=308 盛唐 李白 〈客中行〉rating=5
  // 詩眼：明知這裡不是故鄉，還是要用一碗好酒騙過自己這裡就是故鄉。
  // 隱藏連接：倒酒的老闆也是異鄉人，卻早把異鄉活成了故鄉，跟李白形成對照。
  308: {
    title: "客中行",
    author: "李白",
    summary: "這句不知何處是他鄉聽起來很豁達，其實是李白說給自己聽、想騙過自己的一句謊話。",
    story: `跟你說我朋友太白的一個異鄉夜晚。他坐在蘭陵一家不起眼的酒肆裡，手裡端著一只玉碗，碗裡的酒是琥珀色的，對著窗外那盞昏黃的燈晃了晃，竟然捨不得一口喝乾。

那些年他一直在外面漂。開元晚期，他把家安在山東任城，家裡有幾個孩子等他，可是他大半時間都不在家——不是遊山玩水那麼浪漫，是到處求人引薦、到處碰壁。他想做官，想有一番作為，可是走到哪裡都被當成一個會寫詩的閒散客人，沒人真的把他當回事。蘭陵是他路過的其中一站，離任城不算太遠，可是那天晚上他一個人坐在酒肆裡，還是覺得離家很遠。

倒酒的老闆是本地人，見他一個外地口音的客人獨自喝悶酒，主動搭話，說這酒不是普通的酒，叫蘭陵酒，釀的時候要加一味鬱金草進去泡，泡出來的酒帶著花香，顏色才會這麼透亮，像琥珀。太白起初只是禮貌地應和，喝了第一口才愣住——這酒是真的好，好到他把手裡的碗又舉高了一點，對著燈光多看了兩眼。

老闆看他這個反應，笑著又倒了一碗，說自己年輕時也是從外地遷來的，在蘭陵落腳幾十年，早就不覺得這裡是異鄉了。太白聽了沒接話，只是又喝了一口。他心裡清楚，自己跟眼前這個老闆不一樣——老闆是真的把異鄉活成了故鄉，而他，是一年換一個地方，連任城那個家，一年也回不了幾次。

可是這碗酒是真的好。好到那一刻，他忽然覺得，管他鄉不鄉的，今晚這頓酒喝痛快，今晚這裡就是他的地方。他把碗裡剩下的酒一飲而盡，轉頭跟老闆說，再來一碗——碗底那點琥珀色的光晃了一下，他忽然就笑了，提筆寫下：

蘭陵美酒鬱金香，玉碗盛來琥珀光。但使主人能醉客，不知何處是他鄉。

寫完他把筆放下，沒有再多說什麼。這幾句話後來被很多離家在外的人翻出來讀，讀的人多半以為這是一種豁達，是真的不想家了。可是懂他的人都知道，太白這輩子從沒有一天真正不想任城那個家——他只是很會說服自己，在某個異鄉的深夜，先騙過自己這一晚。老闆後來再也沒等到那個外地客人回頭，但那只玉碗裡的光，倒是被他寫進了詩裡，留到了現在。`
  },

  // id=311 盛唐 李白 〈聞王昌齡左遷龍標遙有此寄〉rating=5
  // 詩眼：人到不了朋友被貶的天涯，就把擔心託付給一輪同時照著兩人的月亮。
  // 隱藏連接：相傳李白與王昌齡曾在江南把酒言歡，是彼此欣賞的同輩高手。
  311: {
    title: "聞王昌齡左遷龍標遙有此寄",
    author: "李白",
    summary: "這首詩沒有一句安慰的話，李白只是把擔心交給月亮，讓月光替他去看看被貶到天涯的朋友。",
    story: `跟你說我朋友太白收到一個消息的那個下午。他人在江東，大概是揚州附近，正是暮春，楊花落得差不多了，布穀鳥在遠處一聲一聲叫。有人從北邊捎來一句話：王昌齡被貶到龍標去了。太白手裡的酒杯停在半空，好一會兒沒放下。

王昌齡跟太白算是同輩詩人裡的頂尖高手，兩人都寫七言絕句寫到出神入化，時人常常把他們相提並論。太白沒少聽人講王昌齡的名聲——邊塞詩寫得蒼涼，送別詩寫得乾淨，尤其那句一片冰心在玉壺，太白自己都佩服。相傳兩人曾在江南見過面，一起喝過幾次酒，聊起邊塞、聊起仕途的不順心，惺惺相惜。可是這一次，惺惺相惜換不來什麼實際的幫助——王昌齡因為平時行事不夠謹慎，得罪過人，這回被人參了一本，一路貶到龍標去當縣尉。

龍標在哪裡，太白心裡有數。要過五溪，那是湘西一帶少數民族聚居的山區，路難走，瘴氣重，消息傳得慢，一封信寄過去，可能要走上一兩個月。太白算了算自己跟王昌齡之間的距離——他在江東，王昌齡要去的地方幾乎是那個年代能貶到的最偏遠角落之一。他想去看看老朋友，可是這個距離，人根本到不了。

他站在江邊，抬頭剛好看見一輪月亮升起來。他忽然想到，這輪月亮同時也會照到五溪、照到龍標、照到王昌齡此刻可能正走著的那條山路。人到不了的地方，月亮到得了。他心裡那份放不下的擔心，好像忽然找到了一個可以託付的東西——他不需要跑到龍標去，只要把這份心事交給月亮，月亮自然會帶著走。

他提筆寫下：

楊花落盡子規啼，聞道龍標過五溪。我寄愁心與明月，隨風直到夜郎西。

夜郎離龍標其實還有一段距離，太白用這兩個字，是借漢代那個荒僻古國的名字，形容那地方遠到快要走出中原人的想像範圍。他知道王昌齡讀到這首詩的時候，人可能還在赴任的路上，風塵僕僕，連個像樣的落腳處都沒有。但太白相信，只要這輪月亮還在，王昌齡就不會覺得自己是一個人被丟在天涯——因為此刻，長江邊上也有一個朋友，正抬頭看著同一片月光，替他發愁。這份牽掛後來活了一千多年，比夜郎這個地名本身，還要讓人記得。`
  },

  // id=312 盛唐 李白 〈贈汪倫〉rating=5
  // 詩眼：一個沒有權勢背景的普通人，用一封文字遊戲的邀請信騙來大詩人，卻用最樸素的歌聲證明真心比什麼都深。
  // 隱藏連接：無
  312: {
    title: "贈汪倫",
    author: "李白",
    summary: "這首送別詩的主角，其實是被一封假地名邀請信騙到皖南的李白，被騙了卻甘願被騙。",
    story: `跟你說我朋友太白收到的一封信。信上寫得很誘人：此地有十里桃花，有萬家酒店，先生若是來了，包管盡興。太白那陣子四處雲遊，一看這種邀約，二話不說就收拾行李，往皖南的涇縣去了。

寫信的人叫汪倫，涇縣本地的一個豪士，平時仗義疏財，交遊廣闊，可是說到底，就是個沒有官職、沒有背景的鄉紳。他仰慕太白的名聲很久了，想邀請這位天下第一號的大詩人來家裡作客，可是自己人微言輕，怕一封尋常的邀請信打動不了對方，就動了個心思，把兩個地名玩成了文字遊戲。太白興沖沖地趕到，一問才知道——所謂十里桃花，是十里外一處叫桃花潭的水潭，跟花一點關係都沒有；所謂萬家酒店，是村裡一家姓萬的人開的酒店，老闆姓萬，不是有一萬家酒店。

太白當場愣住，隨後大笑。他這輩子見過的權貴、見過的假意逢迎不少，這回被一個素不相識的鄉下人用這麼樸拙的辦法騙了過來，他不但沒生氣，反而覺得這個人有意思。汪倫是真心實意招待他，家裡有什麼好酒好菜都端出來，兩人喝酒、聊天，一聊就是好幾天，汪倫沒有一句話是在攀關係、求詩文，就是單純把這個偶像請到家裡好好招待。

到了要走的那天，太白一個人先上了船，船夫解開纜繩，順水往桃花潭下游划去。太白心裡多少有點失落，以為這場相遇就這樣悄悄結束了——他這輩子送別過太多人，也被太多人送別過，大多是官場上的客套。船划出去沒多遠，岸上忽然傳來一陣整齊的歌聲，一群人踩著節拍，邊唱邊跳地追出來，為首的正是汪倫。

太白站在船頭回頭望，眼眶有點熱。他低頭看了看腳下的桃花潭水，水色很深，深到看不見底，他忽然覺得，眼前這個沒有任何權勢背景、只靠一封文字遊戲信把他騙來的普通人，給他的這份情，比這潭水還要深。他提筆寫下：

李白乘舟將欲行，忽聞岸上踏歌聲。桃花潭水深千尺，不及汪倫送我情。

這首詩後來成了送別這個詞的另一種寫法。汪倫大概到死都沒想到，自己那封半真半假的邀請信，換來的不只是幾天的招待，還有一句寫了一千多年、至今還在替所有真心朋友說話的詩。`
  },

  // id=313 盛唐 杜甫 〈江南逢李龜年〉rating=5
  // 詩眼：曾經在盛世沙龍裡抬頭就能見到的當紅歌手，四十年後在亂世盡頭的江南街頭重逢，兩人都認出彼此是被時代拋下的人。
  // 隱藏連接：李龜年正是當年在沉香亭為李白清平調伴唱的宮廷樂師。
  313: {
    title: "江南逢李龜年",
    author: "杜甫",
    summary: "這首詩沒提安史之亂一個字，卻是杜甫寫給整個開元盛世最後的一次回眸，寫完那年冬天他就病逝了。",
    story: `跟你說我朋友子美晚年一個下著小雨的春天。他在潭州街頭，聽見附近有人在唱曲，那個嗓音蒼老了，可是調子一起，他整個人愣在原地——這曲子他年輕時聽過，不只一次，是那個年代最紅的人唱的。他抬起頭想看清楚是誰，眼淚差點先掉下來。

那個人叫李龜年，開元年間宮裡最紅的樂師，沒有之一。子美年輕的時候，曾經托著長輩的關係，在岐王李範的府邸、在崔九——就是那位深受玄宗寵信的殿中監崔滌——的堂前，不只一次見過李龜年演出。那是他一輩子見過最好的時代：滿座都是當紅的王公貴族，絲竹管弦，座上客個個意氣風發，子美當時還是個沒沒無聞的年輕人，能擠進這樣的場合聽李龜年唱曲，已經是一種奢侈的幸運。他甚至不知道，那位替玄宗、貴妃在沉香亭傳旨，唱過太白清平調的樂師，就是眼前這個人。

後來安祿山一路打進長安，盛世碎得比誰都快。岐王府、崔九的宅邸，連同整個開元天寶的繁華，全部成了回不去的過去。李龜年也從宮裡最紅的人，變成一個到處流浪、靠賣唱糊口的老藝人。子美自己的日子也沒好到哪裡去——這些年他從長安一路輾轉到夔州，再往潭州漂，一家人常常靠人接濟過活，身體也垮了，這一年他五十九歲，已經是他人生的最後一年，只是他自己還不知道。

那天在潭州的街頭，兩個曾經只在同一個盛世裡遙遙相望的人，終於面對面站在一起。子美看著眼前這個白髮蒼蒼、還在靠賣唱維生的老人，再想想自己這一身的病痛和潦倒，忽然覺得，他們兩個其實是同一種人——都是被那個時代選中過、又被那個時代狠狠拋下的人。窗外正是江南最好的春光，落花一片一片飄下來，像是替這場重逢配了一段收尾的音樂。子美提筆，寫下：

岐王宅裡尋常見，崔九堂前幾度聞。正是江南好風景，落花時節又逢君。

這四句話沒有一個字提到安史之亂，沒有一個字寫戰亂或衰老，可是所有讀過開元盛世的人，讀到這六個字，都會突然明白過來——那整個回不去的時代，全部藏在這一句重逢裡。這一年冬天，子美病逝在湘江的一條小船上。這場江南的重逢，是他留給那個盛世最後的一次回眸。`
  },

  // id=316 盛唐 杜甫 〈贈花卿〉rating=5
  // 詩眼：用最華麗的讚美詞，包住一句不能明說的警告。
  // 隱藏連接：花敬定是平亂功臣崔光遠部將，杜甫寓居成都草堂時與地方將領確有真實往來。
  316: {
    title: "贈花卿",
    author: "杜甫",
    summary: "這句被無數人當成千古最美讚美詩的句子，其實是杜甫寫給一個囂張武將的委婉警告。",
    story: `跟你說我朋友子美一次赴宴的經歷。那天他被請到成都城裡一位姓花的將軍家裡作客，還沒進門，老遠就聽見裡頭絲竹聲不斷，一曲接一曲，飄得滿城都是，順著江風飄一半，順著雲氣飄一半。子美站在門口聽了一會兒，臉上的表情有點微妙。

這位花將軍名叫花敬定，是劍南節度使崔光遠手下的部將。就在不久前，梓州刺史段子璋起兵造反，花敬定領兵平亂立了大功，聲勢一下子起來了。可是這個人打完勝仗之後，行事越來越張揚，縱兵大肆搜刮不說，家裡宴客的排場，樂曲的規格，用的都是照理只有天子才能用的那一套。子美當時寓居成都草堂，日子過得清貧，跟地方上這些帶兵的將領也算有些往來，聽多了旁人議論花敬定的驕橫，心裡其實不太贊同。

可是他這次來，是被正式請來作客的，總不能當著滿座賓客的面數落主人。子美坐下，一邊聽曲，一邊看著滿堂賓客陶醉的樣子。那曲子確實好聽，絲弦的聲音清亮，順著江風飄出去，又混進半空的雲裡，好聽到讓人生出一種錯覺，好像不該是人間會有的東西。子美聽著聽著，腦子裡轉的卻不是曲子好不好聽，而是這種只有天子祭祀、天子宴飲才配用的樂曲規格，怎麼會出現在一個地方將領的家宴上。

酒過三巡，有人起鬨，讓在座的文人即席賦詩，誇誇今天這場音樂盛宴。子美端起酒杯，笑了一下，提筆寫下：

錦城絲管日紛紛，半入江風半入雲。此曲只應天上有，人間能得幾回聞。

滿座賓客聽了都覺得這是天大的稱讚——把花將軍家的樂曲捧到天上去了，還能有比這更好聽的恭維嗎？花敬定本人聽了想必也很受用。只有真正懂子美的人才聽得出，這四句話裡藏著一把很鈍但很痛的刀——那五個字表面上是說好聽得像天籟，其實是在提醒眾人：這種規格的音樂，本來就只該屬於天子，不該出現在人間，更不該出現在一個將軍家裡。子美沒有明著罵，他用最漂亮的讚美，把最尖銳的警告包了起來，遞給了一個他惹不起、卻又看不下去的人。這首詩後來流傳下來，成了明褒暗貶四個字最好的示範。花敬定聽完這首詩，大概還沒品出那層弦外之音，畢竟能聽懂這種綿裡藏針的人，本來就不多。`
  },

  // id=317 盛唐 王維 〈渭城曲〉rating=5
  // 詩眼：明知這杯酒喝完可能是永別，還是笑著勸對方再喝一杯。
  // 隱藏連接：無
  317: {
    title: "渭城曲",
    author: "王維",
    summary: "這首送別詩被唱了一千多年，勸的那杯酒背後，是王維說不出口的這可能是最後一面。",
    story: `跟你說我朋友摩詰一個下雨的清晨。渭城這地方，離長安不算遠，一場夜雨把路上的塵土都打濕了，空氣裡有股清爽的泥土味。客舍外頭那排柳樹，葉子被雨水洗過，綠得發亮，看著像是剛冒出來的新芽。摩詰坐在客舍裡，對面是他一個姓元的朋友，排行第二，大家都叫他元二。

元二這次不是出遠門那麼簡單——他奉命出使安西都護府，那是大唐設在西域的軍政重鎮，遠在今天的新疆一帶。從長安出發，要一路往西，穿過河西走廊，出了陽關，前面就是大片的戈壁和陌生的邦國。這一路少說也要走上幾個月，而且安西那種地方，常年跟吐蕃、突厥各方勢力拉鋸，誰也說不準這一趟差事會遇上什麼。摩詰心裡清楚，這頓踐行酒喝完，兩人再見面，可能是好幾年後，也可能——誰也不敢往下想。

兩人坐在客舍裡，窗外的雨已經停了，柳色映著晨光，格外清新。這種天氣，這種光線，本來該是最適合出遊的日子，偏偏今天是送別。摩詰給元二倒了一杯酒，兩人先隨口聊了幾句路上該注意什麼、安西那邊的氣候人情，聊著聊著，話漸漸就少了下去，只剩下杯子碰在一起的聲音。

摩詰知道，眼前這杯酒喝完，元二就要上路了。西出陽關之後，再也沒有能跟他喝一杯、說幾句家鄉話的人——那邊的人不說長安話，不懂他們此刻聊的這些家常，連酒可能都不一定喝得慣。摩詰把杯子又斟滿，推到元二面前，笑著說了一句話，語氣很輕，像是隨口一提，其實是把心裡那份說不出口的擔憂全部壓進去了：

勸君更盡一杯酒，西出陽關無故人。

這句話前面還有兩句鋪墊，把眼前這場乾淨清爽的雨後晨景全寫了進去，好像故意要跟接下來的離別作對比：天氣這麼好，酒這麼暖，偏偏就是要分開。元二後來有沒有平安抵達安西，史書沒有留下記載，這位朋友的真實身份，後人也很難再考證清楚了。可是這杯酒，還有渭城那場雨後的柳色，後來被無數送別的場合反覆彈唱，叫作陽關三疊——一句勸酒詞，替一千多年來所有不知道能不能再見面的朋友，說了同一句話。一句陽關三疊，唱了一千多年，唱的從來不只是元二一個人，是每一個舉杯之後就要天各一方的離別。`
  },

  // id=321 盛唐 王昌齡 〈出塞〉rating=5
  // 詩眼：同一輪月亮照過秦漢的關隘，也照著眼前還沒回家的士兵，幾百年過去，只是換了一批望月想家的人。
  // 隱藏連接：王昌齡年輕時真的到過河西邊塞，親眼見過這些回不了家的士兵。
  321: {
    title: "出塞",
    author: "王昌齡",
    summary: "這首被譽為唐人七絕壓卷之作的邊塞詩，寫的不是想像中的蒼涼，是王昌齡親眼見過的那些回不去的人。",
    story: `跟你說我朋友少伯站在邊塞城頭的一個晚上。風很大，吹得人臉發疼，他抬頭看那輪月亮，忽然覺得，這輪月亮怎麼看都像是同一輪——不是說形狀，是說那種照法，好像從很久很久以前就一直這樣照著這座關，照著關下這條路，從來沒換過。

少伯年輕的時候真的到過河西一帶，不是在家裡對著地圖想像邊塞什麼樣子，是真的走過那條路，真的在城頭吹過那種風。他在那裡見到戍守邊關的士兵，有的年紀跟他差不多，有的已經是滿臉風霜的老兵。他跟這些人聊過天，聽他們講家鄉在哪裡，講家裡還有什麼人等著，講自己已經多少年沒回去過。有人講著講著就不說話了，因為連自己都不確定，這輩子還回不回得去。

少伯站在城頭，望著遠處連綿的山，那是陰山一帶，自古就是中原跟北方遊牧民族拉鋸的地方。秦朝的時候就在這一帶修長城防禦，漢朝接著修，接著打，一代一代的士兵被派過來戍守，一代一代的士兵老死在這裡，或者更年輕的時候就死在這裡。他想，眼前這輪月亮，秦朝的士兵抬頭看過，漢朝的士兵也抬頭看過，月亮沒換，關沒換，換的只是站在城頭底下、望著月亮想家的那一批人，一批換過一批，誰都沒能等到不用再打仗的那一天。

他想起漢朝那位讓匈奴聞風喪膽的飛將軍李廣，想起那個年代如果真的還有這樣的良將鎮守邊關，匈奴的騎兵大概連陰山都不敢靠近。可是眼前這個時代，這樣的人在哪裡？士兵一批一批被派來，一批一批死在異鄉，萬里之外的家人望穿秋水，人卻連影子都等不回去。少伯把這份感慨壓進四句話裡：

秦時明月漢時關，萬里長征人未還。但使龍城飛將在，不教胡馬渡陰山。

這首詩後來被後世的人捧為唐人七絕裡寫得最好的一首，壓卷之作。可是很少有人記得，寫下這幾句話的人，不是坐在長安書房裡憑空想像邊塞多蒼涼，他是真的在那座城頭吹過那陣風，真的看過那些沒能回家的士兵，眼睛裡帶著風沙的那種真實，才寫得出人未還這三個字裡藏著的重量。那份重量，隔著一千多年，讀的人依然能從紙面上感覺得到。這才是真正的邊塞詩，不是紙上談兵的想像，是用眼睛親自見過的荒涼寫出來的。`
  },

  // id=323 盛唐 王昌齡 〈芙蓉樓送辛漸〉rating=5
  // 詩眼：被謠言纏身的至暗時刻，送別詩裡一個字不辯解，只託朋友帶一句我心依然乾淨。
  // 隱藏連接：無
  323: {
    title: "芙蓉樓送辛漸",
    author: "王昌齡",
    summary: "這句一片冰心在玉壺不是文青金句，是王昌齡在滿城閒言碎語裡，寫給洛陽親友的一句無聲自白。",
    story: `跟你說我朋友少伯一個下著寒雨的夜晚。雨勢很大，順著江面一路打過來，吳地這一帶入夜之後濕冷得很，芙蓉樓外的江水被雨點打得一片白茫茫。他站在樓上，望著樓下漸漸積起水的石階，手裡端著一杯早就涼透的酒，心裡想的不是眼前的雨，是明天一早要送走的那個人。

少伯這些年過得不太順。他年輕時中過進士，也在邊塞待過，寫邊塞詩寫得比誰都好，一句「黃沙百戰穿金甲，不破樓蘭終不還」，當年在長安傳誦一時。可是官場上這種名氣，未必是好事——他做人做事其實算不上張揚，可是越是這樣，越容易被人拿來做文章。有人說他不護細行，言外之意是私德有虧、行事不夠檢點，這種話一旦傳開，查無實據也難以自證清白，就這樣一路跟著他，從一個任所傳到另一個任所，把他從中原一路貶到江寧，這回又要再往更南邊的龍標去。他當時在江寧當縣丞，官不大，可是這種閒言碎語，比丟官還讓人心煩——它會順著人脈一路傳回洛陽，傳到他那些老朋友、老長輩耳朵裡，變成茶餘飯後的談資。

辛漸是他的朋友，這次要北上，途經洛陽。少伯知道，辛漸到了洛陽，少不了要見那些他這些年沒機會見面的親友，而那些人多半也聽過關於他的閒話，少不了要探問幾句少伯這陣子在江寧，過得怎麼樣。他心裡清楚，自己沒辦法一個個去解釋，那些話一旦傳開，越描越黑，寫信辯白反而顯得心虛。倒不如趁著這一場雨夜送別，把心裡話一次說清楚。

天快亮的時候，雨停了。少伯陪辛漸走到江邊渡口，遠處的楚山在晨霧裡看起來孤零零的，跟他此刻的心情有點像。他沒有多說什麼委屈的話，也沒有替自己辯解半句，只是在臨別前，把一句話交給辛漸，讓他帶回洛陽：

寒雨連江夜入吳，平明送客楚山孤。洛陽親友如相問，一片冰心在玉壺。

冰心在玉壺這五個字，他借用的是前人形容清白高潔的說法——一塊冰，裝在一只玉壺裡，乾淨得看不到一絲雜質，任誰拿在手裡端詳，都挑不出半點雜色。他沒有為自己爭辯任何一件具體的事，也沒有點名是誰在背後嚼舌根，他只是想告訴洛陽那些還關心他的人：不管外頭怎麼傳，他這個人，心裡是乾淨的。辛漸帶著這句話北上，少伯站在渡口，看著船隻一點一點消失在江面上，江水依舊打著白浪，跟昨夜那場雨沒什麼兩樣。這場送別後來成了他一生最出名的自白——不是喊冤，不是求情，就是安安靜靜地告訴所有人，他問心無愧。多年後他輾轉又貶到更遠的龍標，仕途始終沒有真正翻身，可這一片冰心，倒是實實在在留到了今天。`
  },

  // id=327 盛唐 王之渙 〈出塞〉rating=5
  // 詩眼：連報春的風都到不了的邊城，士兵連想家的曲子都顯得奢侈。
  // 隱藏連接：相傳王之渙靠這首詩在旗亭打賭中贏過王昌齡與高適。
  327: {
    title: "出塞",
    author: "王之渙",
    summary: "這首詩相傳是王之渙跟王昌齡、高適打賭賭贏的關鍵一句，一千年後玉門關外的春風依然吹不進去。",
    story: `跟你說我朋友季凌一次跟同行打賭的經歷。那天他跟王昌齡、高適三個人約在旗亭小酌，隔壁正好有一班梨園的樂官帶著幾個歌妓在宴會上表演。三個人喝著酒，不知道是誰先起的頭，說不如來打個賭——看這些歌妓等一下唱的曲子裡，誰的詩被唱到最多次，誰就是今天在座三人裡最厲害的那個。

這個賭局對季凌來說，一開始不太妙。第一個歌妓開口，唱的是王昌齡的一首詩，王昌齡不動聲色地在牆上畫了一道記號。接著第二個歌妓唱了高適的一首。再來又一個歌妓唱起王昌齡的另一首，王昌齡笑著又畫了一道。季凌坐在旁邊，臉上有點掛不住——他在當時的詩壇也算是有頭有臉的人物，一生行事向來灑脫，年輕時仗劍任俠，喝酒擊劍，中年之後才收心讀書，詩寫得不算多，現存下來的也不過六首，可是首首都是精品。眼看兩輪過去，牆上一道記號都沒有他的份，他有點坐不住了。

季凌指著在座幾個歌妓裡長得最出眾、氣質也最不凡的那一個，跟兩個朋友說，等一下如果連她唱的都不是我的詩，我這輩子從此再也不跟你們爭這個高下。三個人都笑了，覺得這話說得挺有意思，倒要看看季凌這口氣撐不撐得住。

輪到那位歌妓，她清清嗓子，不緊不慢地唱出：

黃河遠上白雲間，一片孤城萬仞山。羌笛何須怨楊柳，春風不度玉門關。

季凌一聽，整個人都亮了起來，轉頭跟另外兩人說，我沒說錯吧。滿座的人跟著大笑，連那幾個歌妓聽明白怎麼回事之後，也一起笑了出來，爭著要跟這幾位當紅的詩人敬酒。

這首詩寫的是玉門關外一座孤零零的邊城。黃河從遠方蜿蜒而來，看起來像是一路流進了白雲深處；城池孤立在萬仞高山之間，顯得格外渺小。戍守在那裡的士兵想家，常常吹起折楊柳這支寄託思鄉之情的曲子，可是季凌想說的是，羌笛何必怨恨那首楊柳曲吹不出鄉愁，真正該怨的，是玉門關這種地方，連報春的風都吹不到。連想家的曲子都顯得奢侈。這首詩據說就是旗亭那天讓季凌贏下賭局的關鍵一句，一千多年後，黃河還是那條黃河，玉門關外的春風，依然吹不進去。`
  },

  // id=335 中唐 白居易 〈浪淘沙-借問江潮與海水〉rating=5
  // 詩眼：拿最守信的潮水去罵最不準時的人，罵到最後卻發現自己的思念比海還深
  // 隱藏連接：白居易主張歌詩合為事而作，常年在江南採風，相傳這首詩直接收錄了渡口女子的真實怨言
  335: {
    title: "浪淘沙-借問江潮與海水",
    author: "白居易",
    summary: "潮水都比他準時——白居易把一個渡口女人罵情郎的真心話，原封不動寫成了詩。",
    story: `跟你說我朋友樂天在蘇州當刺史那幾年，遇過一個女人，他一句話都沒跟她說過，卻把她的話原封不動寫成了一首詩，還讓這首詩傳唱了一千多年。

那是他在蘇州刺史任上的事。他管的是水利和民生，常常沿著運河一段一段巡視河堤，看船閘、查稅賦，一天下來要走好幾個渡口。渡口邊常年停著一整排船，船身漆得斑駁，桅桿上曬著漁網，船夫的婆娘們就蹲在岸邊石階上洗衣、搗衣、曬乾魚，順便等自家男人的船影出現在河灣那頭。

有一回他巡視到一個渡口，天色將暗，別的婦人都收拾東西回家了，只剩一個女人還蹲在石階上，一邊用力搗衣一邊自言自語，搗的力道一下比一下重，罵的不是江水，是她男人。

那男人是跑船的，走一趟少說半個月，說好中秋前回來，結果拖到重陽都沒個影。女人越說越氣，嘴裡念念有詞：江潮再怎麼陰晴不定，好歹漲一次退一次都有固定的時辰，你倒好，說好的日子從來不準，害她天天望著河灣那頭空等。

樂天站在不遠處聽住了，沒有上前搭話，也沒有出聲安慰。他這輩子主張「歌詩合為事而作」，走到哪都豎著耳朵收集這種民間的真心話，寫〈賣炭翁〉是這樣，後來在潯陽江頭聽琵琶女彈曲、寫〈琵琶行〉也是這樣。這一次他什麼都沒插嘴，只是把女人的怨氣一字一句記在心裡，等回到官署，攤開紙，想著怎麼幫她把這口氣理順成句子。

女人後來還說了一句更狠的。她說，本來以為大海深不見底，天下最深的東西大概就是海了。可是她這陣子天天坐在江邊等，才發現海哪有多深，跟她心裡這份思念比起來，海淺得很，簡直薄得像一張紙。

樂天提筆把這兩句話重新排過，寫成：借問江潮與海水，何似君情與妾心。相恨不如潮有信，相思始覺海非深。

他自己讀完也笑了。這哪裡是他寫的，分明是那個搗衣女人自己罵出來的，他只是負責把它記下來，不讓這句話跟著江潮一起流走，白白消失在渡口的暮色裡。

這首詩後來被收進他的〈浪淘沙詞〉六首裡，一路傳唱了一千多年。沒人知道那個女人叫什麼名字，沒人知道她的男人後來回沒回來，可是每一個被放過鴿子、等過一個不準時的人的人，讀到這兩句，都會覺得，這寫的就是自己心裡沒說出口的那句話。`
  },

  // id=340 中唐 崔護 〈題都城南庄〉rating=5
  // 詩眼：一年後只剩桃花對著春風笑，人已經找不到了
  // 隱藏連接：無，本詩本身已有唐代本事詩記載的既定傳說，不另外編織
  340: {
    title: "題都城南庄",
    author: "崔護",
    summary: "一年後他回到同一扇門前，桃花還在，人卻不見了——這是「人面桃花」成語的起點。",
    story: `跟你說我朋友崔護，他這輩子只見過那個女孩兩次面，中間隔了整整一年，而這首詩就是為了那一年的空白寫的。

那年他還沒考上功名，是個到長安應試的年輕書生，家鄉在博陵，帶著滿身書卷氣，卻屢試不第，心裡憋著一股悶氣。清明那天他一個人到城南郊外散心，走著走著又渴又累，抬頭看見前方有一戶人家，籬笆內種了一整片桃花，開得正盛，粉紅色的花瓣一路開到牆頭外面，映著春天的日頭晃眼。他上前敲門討口水喝。

開門的是個年輕女子，容色清秀。她端了一碗水出來，遞給他，自己就倚在門邊那株桃花樹下，靜靜看他喝。崔護後來回想那個畫面，總說記不清她說過什麼話，兩人幾乎沒有交談，只記得她的臉和身後那片桃花紅得幾乎分不出哪個是花、哪個是人。他喝完水，道了謝，行了個禮就走了，兩人什麼都沒約定，連名字都沒問，只是那張臉不知怎麼就這樣印進了他心裡。

一整年，他沒有再去。他在長安讀書、應考，日子一天天過，考場裡的失意、旅店裡的孤單，都沒能把那張臉沖淡。第二年清明，他終於忍不住，又一個人走回那條路，心裡又期待又忐忑，找到那戶人家。

籬笆還在，桃花還在，開得跟去年一樣好，甚至更盛。可是他敲了門，敲了很久，沒有人應。門扉深鎖，院子裡靜得只剩風吹花瓣的聲音，一片一片飄落在門檻前，沒有人打掃。他站在門口等了好一陣，人終究沒有出現，天色漸漸暗下來。

他從懷裡摸出筆，就著門板，寫下四句話：去年今日此門中，人面桃花相映紅。人面不知何處去，桃花依舊笑春風。

寫完他就走了，沒有留下姓名，也沒有多做解釋，只是把去年那個下午的畫面，原封不動地留在門上，讓下一個開門的人自己去猜這是誰寫的。

相傳後來這個故事還有下文，說女子出遠門回來看見門上的詩，思念成疾，臥床不起，崔護再訪時她竟因此甦醒，兩人終成眷屬，這段多半是後世話本添的戲，真假已不可考。但那扇門上的十六個字是真的流傳了下來，成了「人面桃花」這個成語的源頭，成了每一個錯過過什麼人的人，共同的一句台詞。`
  },

  // id=348 中唐 劉禹錫 〈烏衣巷〉rating=5
  // 詩眼：貴族門第會沒落，但燕子照樣年年飛回同一個屋簷
  // 隱藏連接：白居易讀後掉頭苦吟、讚嘆良久，是劉白唱和情誼的真實記載
  348: {
    title: "烏衣巷",
    author: "劉禹錫",
    summary: "曾經最頂級的門第，如今燕子飛進了尋常百姓家——劉禹錫沒去過金陵，卻寫出了整個時代的滄桑。",
    story: `跟你說我朋友夢得寫這首詩的時候，他其實根本沒去過金陵城裡那條巷子，是憑著書上的幾行字，硬生生把一整座六朝繁華想像了出來，這件事他後來也不太瞞人。

那是他被貶到和州刺史任上，離金陵不算太遠，只隔著一條江，但公務纏身，加上身上還揹著政治犯的名聲，行動多有顧忌，始終抽不出空親自去憑弔那些古蹟。他讀過太多關於金陵的記載：東晉時候，城南有一條巷子叫烏衣巷，因為王導、謝安兩大家族的子弟出門都愛穿黑衣，巷子因此得名。王導輔佐晉室在江南重新站穩腳跟，謝安在淝水之戰以八萬對八十萬，硬是把前秦大軍擋了下來，兩家子弟滿門朱紫，出入都有車馬隨從，門前終日絡繹不絕，是那個時代最頂級的門第，沒有之一。

朱雀橋就在烏衣巷口不遠，是通往皇城的必經要道，當年橋上還飾有一對銅雀，同樣車水馬龍，行人如織，橋下船隻往來，商賈雲集，是整座金陵城最熱鬧的一段。夢得把這些畫面在腦子裡反覆拼湊，一邊翻書一邊在紙上塗塗改改，拼出橋邊如今大概已經長滿了不起眼的野草閒花，巷口大概只剩一抹斜陽，再沒有從前那種鐘鳴鼎食、車馬喧囂的氣派，只剩幾戶尋常人家安安靜靜過日子。

他想到王謝兩家從烜赫到沒落的興衰，短短兩三百年，滿門朱紫也不過是史書上幾行字，又想到自己這些年被貶、起復、又被貶的起落，忽然抓住一個畫面：燕子。燕子每年春天都要飛回舊巢，牠們認的是屋簷的位置，不認門第的高低，也不會因為主人換了姓氏就飛去別處，王謝堂前的燕子，如今飛進的多半已經是尋常百姓家的屋簷底下了，牠們大概也不知道自己曾經棲息過怎樣的高門大戶，銜的泥、築的巢，跟從前一模一樣。

他提筆寫下：朱雀橋邊野草花，烏衣巷口夕陽斜。舊時王謝堂前燕，飛入尋常百姓家。

這組詩後來傳到洛陽，他的老友樂天讀到這四句，反覆吟誦，掉頭苦吟了半天，感嘆良久，說這樣的句子他自己是寫不出來的。兩人這些年常常隔著千里唱和往來，你寄一首我和一首，樂天這次是真心服氣，不是客套話。

一千多年後，王謝早已成了史書裡的兩個姓氏，誰也認不出當年哪一戶算是王家、哪一戶算是謝家。可那隻燕子還在，年年都飛，誰家屋簷底下有牠，誰家就算得上熱鬧。`
  },

  // id=357 晚唐 劉禹錫 〈秋詞〉rating=5
  // 詩眼：被扔到人生谷底，偏要證明谷底不輸巔峰
  // 隱藏連接：與柳宗元同屬永貞革新被貶的八司馬，兩人隔幾百里書信往來互相撐持
  357: {
    title: "秋詞",
    author: "劉禹錫",
    summary: "同樣被貶到天涯海角，柳宗元寫孤獨堅守，劉禹錫偏要唱反調說秋天勝過春天。",
    story: `跟你說我朋友夢得，他被貶到朗州那幾年，寫過一句話，跟他所有的朋友、甚至跟自古以來所有的文人都唱反調。

那是永貞革新失敗以後的事。他跟王叔文、柳宗元一批人本想從宦官手裡把權力搶回來，整頓朝政、削弱藩鎮，結果只幹了半年就垮了，領頭的王叔文被賜死，八個核心人物全部被貶到天涯海角，史稱「八司馬」。夢得分到朗州，宗元分到永州，兩地隔著幾百里山水，書信來往靠驛差輾轉傳遞，快則一個月，慢則半年才有回音，有時候信使自己都可能死在半路上。

宗元在永州那邊過得極清苦，常常一個人裹著蓑衣坐在江邊，一坐就是一整個下午，天地間安靜到只剩他一個人，鳥都不叫了。夢得雖然自己也是戴罪之身，日子過得不寬裕，但他知道，宗元那邊此刻大概也是差不多的光景，兩人各自扛著各自的孤獨。

可是夢得偏偏是那種不肯認輸的性子。秋天到了，朗州城外草木凋零，按照從前文人的老規矩，這時候該悲秋、該傷懷、該用最蕭瑟的字眼把秋天寫得慘兮兮的，宋玉悲秋以來，幾乎所有寫秋天的詩都是這個路數，一代傳一代，沒人敢反著寫。夢得心裡也悶，官職被削、抱負落空，可他偏偏不想順著那個調子往下寫，他覺得那樣寫太便宜了那些把他整下去的人，等於是幫敵人再踩自己一腳。

他走出門，抬頭看見一隻鶴，從一片晴空裡直直往上飛，穿雲而去，姿態一點都不狼狽，反倒帶著一股銳氣，翅膀拍得又穩又有力。夢得看著那隻鶴，忽然覺得，自己這幾年的處境跟這隻鶴很像，被扔到最荒僻的地方，照理該垂頭喪氣，可他偏要證明，秋天不必然比春天差，人在低谷的時候，也不必然比得意的時候差。

他提筆寫下：自古逢秋悲寂寥，我言秋日勝春朝。晴空一鶴排雲上，便引詩情到碧霄。

這首詩後來也輾轉送到了永州宗元手上。宗元那邊寫的是萬徑人蹤滅、獨釣寒江雪的沉靜姿態，夢得這邊寫的是一鶴排雲上的昂揚姿態。兩個老友，同一種困境，卻各自守著各自的骨氣，隔著幾百里山水互相撐著對方，直到二十多年後才終於等到召回長安的那一天，夢得始終沒有變，照樣不服輸，照樣嘴硬。`
  },

  // id=364 晚唐 李商隱 〈嫦娥〉rating=5
  // 詩眼：得到最想要的東西，卻永遠失去了陪伴
  // 隱藏連接：相傳李商隱年少在玉陽山學道時與一位女道士互有情愫，礙於觀規終究沒能在一起
  364: {
    title: "嫦娥",
    author: "李商隱",
    summary: "嫦娥得到了長生，代價是往後每一夜都只剩自己——李商隱借月亮寫一段沒能圓滿的感情。",
    story: `跟你說我朋友義山年輕時候在山裡學過道，那段日子他什麼都沒明說，卻把心事偷偷寫進了一首關於月亮的詩裡，藏了一千多年才被人半猜半懂地讀出來。

那是他還沒考上進士的年紀，家裡窮，父親早逝，靠著親戚接濟過活，有一段時間被安排到玉陽山的道觀裡念書，順便修道，圖個清靜也圖個省錢。山裡清修的日子單調，晨起誦經、白日抄書，道觀裡有幾位年輕的女道士，按規矩男女授受不親，觀規森嚴，稍有逾矩就要被逐出山門，但少年人朝夕相處，眉目間難免生出些心思。相傳義山對其中一位女道士動了真情，兩人礙於觀規，始終沒能挑明，更別說在一起，只能藉著抄經、遞茶這種小事偷偷傳遞一點心意。這段情事史書沒有明寫，是後人從他一整批寫得極隱晦的無題詩裡拼湊出來的，真假摻半，只能說相傳如此，不能坐實。

多年後某個深夜，義山一個人對著屏風上雲母石的天然紋路發呆，燭火忽明忽暗，映得屏風上的影子也跟著晃動不定，像有人在背後走來走去，他卻知道屋裡其實只有自己一個。窗外一點聲音都沒有，連更鼓都停了。他想起月亮上的嫦娥。傳說裡嫦娥本是后羿的妻子，偷吃了西王母給的長生靈藥，身子輕得飛了起來，一路飛到清冷的月宮，從此長生不死，卻也從此獨自守著那座月宮，誰都見不到，誰也見不到她，連跟她說一句話的人都沒有。

義山盯著窗外，天快亮了，銀河漸漸西沉，啟明星也快隱沒在晨光裡。他忽然覺得嫦娥這個決定很矛盾：她得到了誰都求不到的長生，代價卻是往後每一個夜晚都只剩她一個人面對碧海青天，連個說話的對象都沒有。得到最想要的東西，卻永遠失去了陪伴，這種矛盾，他自己心裡太清楚了。

他提筆寫下：雲母屏風燭影深，長河漸落曉星沈。嫦娥應悔偷靈藥，碧海青天夜夜心。

有人說這首詩寫的是他懷念那位沒能在一起的女道士，有人說寫的是他自己夾在牛李兩黨之間動彈不得、進退兩難的處境，義山自己從沒解釋過，一個字都沒多說。也許正是因為他什麼都沒說清楚，這輪月亮才照了一千多年，照著每一個為了得到什麼而失去了誰的人。`
  },

  // id=369 晚唐 杜牧 〈寄揚州韓綽判官〉rating=5
  // 詩眼：用一句風流的玩笑話，包住捨不得說出口的想念
  // 隱藏連接：杜牧曾在淮南節度使幕府與韓綽同僚，兩人共度過一段揚州歲月
  369: {
    title: "寄揚州韓綽判官",
    author: "杜牧",
    summary: "杜牧寫信給揚州老同事，開口只問哪裡還有人在吹簫——問的是簫聲，想念的是整座城市。",
    story: `跟你說我朋友牧之離開揚州以後，寫過一封信給留在那裡的老同事，信裡沒問公事，也沒提近況，劈頭就打聽揚州城裡還有沒有人在吹簫。

那幾年他在淮南節度使牛僧孺幕下當幕僚，官職不大，公務也不算繁重，駐地就在揚州。揚州在中唐是天下最繁華的商埠，運河貫城，商船晝夜往來，夜市不打烊，酒旗一路插到江邊，青樓歌館燈火通明到天亮，胡商、鹽商、詩人、歌伎全擠在同一條街上，是所有文人心裡的銷金窟，也是牧之這輩子最放縱的一段日子。牧之跟同僚韓綽當時交情不錯，兩人性子相投，一有空就相約出遊，一起在這座城裡過了好一陣子紙醉金迷的日子，秦樓楚館哪一家的姑娘唱得好、哪一家吹得一手好簫，兩人大概都摸得一清二楚，彼此還常拿這個開玩笑，比誰認識的姑娘多。

後來牧之被調回長安任監察御史，官位是升了，責任也重了，可長安的日子板正嚴肅，處處講規矩、講體面，同僚見面拱手作揖，公事一件接一件，跟揚州那種軟語笙歌、隨性自在的氣氛完全是兩個世界，連走路的步調都不一樣。他常常在批公文批到深夜的時候，忽然想起揚州，想起那座跨越運河、傳說有著二十四個橋洞的二十四橋，想起江南秋天草木遲遲不凋的溫軟氣候，想起夜裡橋上有人吹簫、簫聲順著水面飄得很遠，飄過一艘艘停泊的畫舫，也想起韓綽還留在那邊，日子過得依舊瀟灑，不像自己整天被公務綁著，連喝杯酒都要看時辰。

某個秋夜他批完公文，提筆給韓綽寫了一封信，信是這麼寫的：青山隱隱水迢迢，秋盡江南草未凋。二十四橋明月夜，玉人何處教吹簫。

他問的是月夜下那些教人吹簫的美人，語氣輕輕鬆鬆，像老朋友互相調侃、開玩笑，一點都不正經。可牧之心裡清楚，他想念的不只是簫聲和美人，是那整座城市，還有留在那座城市裡、還沒被長安的規矩磨掉的那個更年輕、更自在的自己，那個還敢通宵不睡、還笑得出來的自己。

這封信後來跟他另一首自嘲揚州舊事的〈遣懷〉常被人放在一起讀。一個問得輕鬆，一個嘆得沉重，拼起來才是牧之對那段揚州歲月完整的心情，表面上調侃，底下全是捨不得，捨不得那座城，也捨不得那個回不去的自己。`
  },

  // id=370 晚唐 杜牧 〈遣懷〉rating=5
  // 詩眼：把最深的悔恨，用最輕的語氣說出來
  // 隱藏連接：相傳上司牛僧孺暗中派人記錄保護杜牧夜訪風月場所的行蹤
  370: {
    title: "遣懷",
    author: "杜牧",
    summary: "十年後回頭看自己的荒唐歲月，杜牧沒有痛哭，只留下一句雲淡風輕的自嘲。",
    story: `跟你說我朋友牧之，他回頭看自己在揚州那幾年，沒有掉一滴眼淚，只丟下一句自嘲，聽著輕鬆，其實是他這輩子最沉的一句話。

那是他在淮南節度使牛僧孺幕府當幕僚的日子。揚州夜夜笙歌，牧之年輕、有才氣，文章寫得好，又不甘寂寞，常常晚上換了便服就往秦樓楚館裡鑽，流連在歌姬舞女之間，喝酒聽曲，一走就是大半夜，天快亮才踉蹌回府，第二天照樣準時當差，誰也看不出他昨夜幹了什麼。相傳牛僧孺看在眼裡，擔心這個有才氣的年輕人喝多了在外頭出事，怕他得罪什麼人或摔進哪條巷子的水溝裡，暗中派了幾個親信士卒遠遠跟著保護，牧之自己全不知情，還以為自己每次都是僥倖平安回家。等到牧之要調回長安，臨行前牛僧孺才拿出一疊記錄，上頭密密麻麻寫著他某年某月某日在哪條巷子平安回府、有沒有出事，牧之這才知道自己這些年的荒唐，全被人看在眼裡，還暗中替他兜著底，一時又驚又愧。

十年之後，牧之已經離開揚州許久，官場起起伏伏，調任了好幾個地方，人也老成了些，鬢角添了幾根白髮，看事情不再像年輕時候那樣意氣用事。他回頭想那段日子，想起那些身段纖細、楚腰一把、在他掌心裡輕盈起舞的歌姬，想起自己載著酒到處遊蕩、什麼正經事都不做的模樣，一晚換一家酒樓，一晚換一批朋友，心裡說不上是懷念還是自責，大概兩者都有一點，攪在一起分不清楚，像喝多了酒之後那種悶悶的感覺。

他沒有寫懺悔文，只寫下四句：落魄江湖載酒行，楚腰纖細掌中輕。十年一覺揚州夢，贏得青樓薄倖名。

十年像一場夢，醒來什麼實際的東西都沒留下，倒是在青樓裡混出了一個薄倖的名聲，說出去不算光彩，可他偏偏就這麼寫了，一個字都沒替自己遮掩。這話說得雲淡風輕，底下藏的是真正的悔意，他心裡明白，那些年他辜負的不只是幾個女子的情意，更是自己原本可以拿來做更多事的青春，那些揮霍掉的夜晚，一去就再也追不回來了。

牛僧孺後來對人提起牧之，只說這個年輕人終究是個做事的材料，荒唐歸荒唐，本事是真本事。牧之自己則把這份荒唐寫成了詩，讓一千多年後的讀者都知道，最深的悔恨，有時候說出來反而是最輕的語氣。`
  },

  // id=371 晚唐 杜牧 〈秋夕〉rating=5
  // 詩眼：連神話裡被拆散的戀人都比她幸運
  // 隱藏連接：無，這是杜牧擬作的宮怨題材，非寫實特定人物，不另外編織
  371: {
    title: "秋夕",
    author: "杜牧",
    summary: "深宮裡的女子寧願羨慕一年才能相會一次的牛郎織女，因為她連確定的日子都沒有。",
    story: `跟你說我朋友牧之寫過一個深宮裡的女子，她的夜晚長得像沒有盡頭，她唯一能做的事，是拿一把小扇子去追打飛來飛去的螢火蟲，打發一個又一個沒有人來的夜晚。

這個女子沒有名字，牧之也沒說她是誰的妃嬪，或許她根本不是特定的哪一個人，只是眾多困在宮牆裡的女子其中之一。她住的地方點著銀白色的蠟燭，燭光照在一扇畫屏上，屏風上畫的山水顯得又冷又靜，沒有一絲暖意，四壁靜悄悄的，連宮女走動的腳步聲都聽不見，整座宮殿彷彿早就睡去。夜深了，沒有人來找她說話，也沒有人捎來一句口信，她已經數不清這是第幾個這樣的夜晚了，一晚一晚疊起來，多得連自己都懶得算。她也沒有什麼事好做，只能拿起一把輕羅小扇，一下一下，追著幾隻閃著微光的螢火蟲玩，那把扇子本來是夏天拿來搧風的，如今秋涼已至，卻成了她打發時間唯一的工具，一下一下揮著，像是在跟某種說不出口的寂寞較勁。

宮裡的石階被夜露打得涼颼颼的，像結了一層薄水，涼意順著裙擺往上爬，她也懶得起身回房，就這樣坐著，任由那股涼意一點一點滲進來。她一個人坐在台階上，抬頭看天。天上是牛郎星和織女星，隔著一條銀河遙遙相望，傳說這兩顆星是一對被王母娘娘的髮簪劃開的戀人，一年只能靠鵲橋相會一次，見一面又得再等一年，年復一年，倒也從沒斷過。

牧之寫到這裡停下筆，替這個女子想了一件很殘忍的事：她此刻多半是在羨慕牛郎織女的。一年一次的相會聽起來很淒涼，可對她來說已經是奢望，她連一個確定的日期都沒有，不知道自己還要在這深宮裡坐多少個這樣的秋夜，才等得到一次哪怕短暫的寵幸或一個名分。

他把這個畫面寫成：銀燭秋光冷畫屏，輕羅小扇撲流螢。天階夜色涼如水，坐看牽牛織女星。

牧之從沒進過那樣深的宮闈，他寫的不是哪一個真人真事，是他想像裡千千萬萬個被困在深宮高牆裡、連盼頭都算不上盼頭的女子。這首詩流傳下來，那把小扇子撲的不只是螢火蟲，是所有等待著一個遙遙無期的人，共同的動作，一下一下，撲進了一千多年後讀者的心裡。`
  },

  // id=376 晚唐 杜牧 〈江南春〉rating=5
  // 詩眼：盛世的熱鬧底下，藏著勞民傷財的舊帳
  // 隱藏連接：祖父杜佑編通典梳理歷代興衰，杜牧從小耳濡目染朝代興亡的框架
  376: {
    title: "江南春",
    author: "杜牧",
    summary: "滿眼江南春色的盡頭，杜牧看到的是一整個朝代怎麼把自己拜垮的。",
    story: `跟你說我朋友牧之，他站在江南的春天裡，眼睛看的是鶯啼綠映紅的熱鬧，心裡想的卻是一整個朝代怎麼把自己拜垮的，這種心思外人大概很難懂。

牧之從小讀的書跟別人不太一樣。他祖父杜佑做過三朝宰相，窮盡半輩子心血編成一部兩百卷的通典，專門梳理歷代典章制度、賦稅兵制的興廢得失，是當時最厚重的一部政書，連朝廷議事都常拿來當參考。牧之打小翻著這部大書長大，家裡書房堆得到處都是竹簡卷冊，別的孩子背詩詞歌賦，他跟著背的是歷朝歷代怎麼興、怎麼亡，腦子裡裝的不只是文采，還有一整套朝代為什麼會垮的框架，看事情總喜歡往深一層想，別人看熱鬧，他偏要看熱鬧底下的帳。

那年他行經江南，正是春天，千里之內，黃鶯到處叫，花紅柳綠交映，水邊的村莊、依山的城郭，家家戶戶都掛著酒旗迎風招展，路上行人往來不絕，酒肆茶樓生意興隆，好一幅盛世光景，路過的人多半只會讚一句江南真美，然後就繼續趕路了，沒人多想一層。

可牧之的目光越過這片熱鬧，落在遠處若隱若現的一片片寺廟屋簷上。江南這一帶，寺廟多得數不清，南朝那幾個朝代，尤其梁武帝，晚年幾乎把整個國家的力氣都花在蓋佛寺、供養僧尼、動輒捨身出家上，史書記載光是建康城裡外就有寺廟四百八十座，僧尼數以萬計，勞民傷財到了荒唐的地步，結果國照樣亡了，梁武帝自己最後還餓死在台城。如今這些樓臺全籠罩在濛濛煙雨裡，看著飄渺又美，底下卻是一整個朝代把自己拜垮的證據，美麗和荒唐疊在同一個畫面裡。

牧之心裡清楚，眼下的大唐皇室同樣好佛、同樣大興土木，跟南朝的老路一模一樣，說不定哪天也要重蹈覆轍，只是眼下沒人願意把這句話說破。他沒有直接罵，只把眼前的畫面寫下來：千里鶯啼綠映紅，水村山郭酒旗風。南朝四百八十寺，多少樓臺煙雨中。

這首詩表面上寫的是江南春色，底下藏著他從通典裡讀出來的警告，一句都沒明說，全靠讀的人自己去接。一千多年後，煙雨裡的樓臺換了一批又一批，江山也換了好幾個朝代，這句借古諷今的話，還是照樣說得通，照樣能拿來對照眼前的世道。`
  },

  // id=378 晚唐 杜牧 〈過華清宮絕句三首之一〉rating=5
  // 詩眼：舉國戒備迎接的，只是博紅顏一笑的水果
  // 隱藏連接：無，史書明確記載楊貴妃嗜荔枝、設置快馬傳送之事，不另外編織
  378: {
    title: "過華清宮絕句三首之一",
    author: "杜牧",
    summary: "一匹快馬讓滿朝文武以為軍情緊急，打開一看只是幾顆荔枝——杜牧用這個荒謬對比釘住了一段奢靡史。",
    story: `跟你說我朋友牧之路過一座荒廢的行宮，腦子裡浮出一個畫面：一匹快馬狂奔進城，滿朝文武都以為是十萬火急的軍情，緊張得手心冒汗，結果打開一看，裡頭裝的只是幾顆荔枝。

那座行宮叫華清宮，建在驪山上，溫泉環繞，是唐玄宗晚年跟楊貴妃避暑享樂的地方，當年宮殿樓閣層層疊疊，金碧輝煌，夜夜笙歌不斷，連山下的百姓夜裡都能聽見隱約的樂聲。牧之路過驪山的時候，安史之亂已經過去幾十年了，曾經的繁華早就荒廢，山頭上只剩斷壁殘垣，雜草從磚縫裡鑽出來，連當年鋪地的琉璃瓦都碎了一地，長安城從山下望上去，還能看見當年層層疊疊的宮門遺跡，一道一道往上開，昔日的氣派隱約還在，卻透著一股說不出的荒涼。

他想起史書上記載的一件事：楊貴妃愛吃荔枝，可是荔枝產在嶺南或四川，離長安幾千里遠，偏偏這東西嬌貴，摘下來三天就變味變色，失了原本的鮮甜，比什麼名貴藥材都難伺候。玄宗為了讓貴妃吃到新鮮荔枝，下令設置一站接一站的快馬驛騎，晝夜不停地跑，一站換一匹馬、一站換一個人，中途不容耽擱，活活跑死了不知道多少匹駿馬、累垮了多少個驛卒，只為了讓荔枝能在還沒變味之前送到長安，代價沒有人細算過，史書也只淡淡記了一筆。

牧之想像那個畫面：山下塵土飛揚，一騎快馬狂奔而來，蹄聲急促，山頂上的千道宮門一道接一道打開，守衛和大臣們個個神色緊張，交頭接耳，以為邊關出了什麼大事，甚至已經在心裡盤算是哪裡的兵馬有異動。誰知道馬到了跟前，卸下來的不是軍報，是幾筐用濕布裹著的荔枝。貴妃看見荔枝，笑了，滿朝的戒備瞬間成了一場空，緊繃的氣氛一下子鬆掉。

牧之把這個荒謬的對比寫成：長安回望繡成堆，山頂千門次第開。一騎紅塵妃子笑，無人知是荔枝來。

他站在這片廢墟前，想著當年那些累死在半路上的驛卒和馬匹，沒有一個人的性命，抵得上貴妃嘴角那一抹笑，這筆帳算下來荒唐得讓人心寒。宮殿早就塌了，荔枝的滋味也沒人記得了，當年山呼萬歲的臣子也早已化成塵土，可這四句詩把那個荒唐的笑容，釘在了歷史裡，誰都拔不掉。`
  },

  // id=391 晚唐 韋莊 〈金陵圖〉rating=5
  // 詩眼：見過長安淪陷的人，才聽得懂柳樹年年一樣綠這件事有多殘忍
  // 隱藏連接：他寫這首詩前幾年剛親眼經歷長安被黃巢軍隊焚掠，並寫成轟動一時的秦婦吟，看六朝舊畫時心裡對照的其實是自己剛逃出的那座城
  391: {
    title: "金陵圖",
    author: "韋莊",
    summary: "這首詩表面在讚嘆一套六朝舊畫，其實是一個剛從陷落的長安逃出來的人，看著六個朝代輪流覆滅的畫冊，越看越心驚。",
    story: `跟你說我朋友端己有一年看畫看到坐立難安。那年他已經四十多歲，人在江南漂著，居無定所，有人拿出一套叫金陵圖的畫冊給他看——畫的是金陵，也就是今天的南京，六個短命王朝輪流建都的地方。他盯著其中一幅看了很久，久到旁邊的人都覺得奇怪，還以為他是在鑑賞畫工筆法。

端己不是第一次面對亡國的畫面，也不是隔著書本讀來的間接感受。就在幾年前，黃巢的軍隊打進長安，他人正好在城裡，親眼看著那座他住了大半輩子的都城被燒、被搶、被血洗了一整輪。米價漲到一斗米要好幾千錢，路上到處是餓死的人，他認識的鄰居一家一家消失，有的逃了，有的沒能逃出去。他後來把那幾天寫成一首叫秦婦吟的長詩，藉一個逃難婦人之口，把這場浩劫從頭講到尾，轟動一時，長安城裡人人傳抄，甚至有人叫他秦婦吟秀才。這首詩太寫實、太駭人，後來多年幾乎在正史文獻裡消失，直到近代才在敦煌重新被發現。那場面他這輩子沒辦法忘掉。

所以當他翻開這套金陵圖，畫裡是東吳、東晉、宋、齊、梁、陳，一個接一個在這裡建都、一個接一個垮掉，宮殿蓋了又拆，城牆建了又毀，他心裡想的不是六朝的事，是他自己剛剛才逃出來的那座城。原來一千年前的人，也曾經以為自己的朝代會千秋萬世，坐在同一座金陵城裡修宮殿、辦宴席，覺得眼前的繁華理所當然。原來繁華這件事，從來沒有例外過。

畫上江邊的雨下得又細又密，六個朝代的繁華，看起來都像一場夢，只剩幾隻鳥在空蕩蕩的舊宮牆邊叫，沒人回應。端己盯著畫裡那排種在臺城邊上的柳樹看，柳樹年年發新芽，年年一樣綠，好像什麼都沒發生過，也不管腳下曾經埋過多少座宮殿的地基。他提筆寫下：江雨霏霏江草齊，六朝如夢鳥空啼，無情最是臺城柳，依舊煙籠十里堤。

柳樹不會記得誰在這裡稱過帝、誰在這裡亡過國。它只是每年一樣綠，把六個王朝的興亡輕輕蓋過去，蓋得像沒發生過一樣。端己知道，再過幾十年，長安會不會也變成別人畫冊裡的一幅舊畫，有人翻開，盯著看很久，卻已經沒人記得曾經死在那裡的人叫什麼名字。

他闔上畫冊，窗外的江雨還在下，跟畫裡一模一樣。`
  },

  // id=393 晚唐 張泌 〈寄人〉rating=5
  // 詩眼：人回不去了，只剩夢還能走回那條再也沒有理由踏進去的迴廊
  // 隱藏連接：相傳他年輕時與鄰家女子相戀，赴京趕考期間分離，等他回來時對方已許配他人（見云溪友議，以相傳處理）
  393: {
    title: "寄人",
    author: "張泌",
    summary: "這首情詩寫的不是分手當下，而是分手多年後，他還在反覆夢見同一條迴廊、同一片月光下的落花。",
    story: `跟你說我朋友子澄年輕時做過一個夢，做了很多年，一次都沒有停過。

子澄早年住在淮南，家附近有一戶人家，家裡有個女孩，兩人算是自小相熟，一起在巷子裡長大，隔著一道矮牆就能喊到對方的名字。相傳兩人漸漸生出感情，只是子澄那時還沒有功名，家境也普通，說不上什麼門當戶對，這段感情從一開始就沒人替他們說話，兩家長輩誰都沒點頭。後來他要進京赴考，兩人約好等他回來再說，甚至私下講好了將來要怎麼安排。他人一走就是好幾年，路途遙遠，書信斷斷續續，有時候一整年都收不到一封回信，他心裡雖然掛念，卻總覺得功名一到手，什麼都能重新商量。

等他終於回到淮南，風塵僕僕還沒來得及進門，就先聽到了消息——那戶人家已經把女孩許配給了別人，聘禮都下了，婚期也定了，一切都定了，他連上門問一句都不合適，甚至連在巷口多站一會兒都覺得尷尬。他站在那道熟悉的矮牆外面，牆還是原來的牆，人已經不是原來可以隨意進出的人了。

子澄後來還是考中了功名，仕途也算過得去，只是這件事他一直沒放下。往後的日子裡，他有時走在路上、有時半夜醒來，會反覆夢見同一個地方，一座他再也沒有理由踏進去的宅院，一條熟悉的小迴廊繞過去，曲折的欄杆斜斜地立在那裡，跟他記憶裡分毫不差，連欄杆上那道舊年磨損的漆痕都一樣。他在夢裡總是走得很急，好像知道自己時間不多，怕一睜眼那條迴廊就會消失。

有一次他醒來，天還沒亮，夢裡那條迴廊還清清楚楚留在眼前，連夜裡庭院裡的月色都還殘留在眼底，他起身寫下四句話寄給對方，算是一種再也見不到面的告別：別夢依依到謝家，小廊回合曲闌斜。多情只有春庭月，猶為離人照落花。

他寫的是，人回不去那座院子了，能回去的只有夢。而院子裡的春夜月亮，倒是比人有情得多，不管誰還住不住在那裡，它照樣把光灑在滿地落花上，照給一個早就不會再回來的人看，一年一年，從不間斷。

子澄後來有沒有再見過她，史書沒有記載。只知道那條迴廊、那彎曲的欄杆，在他心裡從沒真正拆除過，即使人已經不在，夢照樣每隔一陣子就帶他回去繞一圈，繞完了再把他推回現實。`
  },

  // id=396 晚唐 王貞白 〈白鹿洞二首其一〉rating=5
  // 詩眼：一句千古勵志名言，原本是一個讀書讀到忘記換季的人，被朋友抓來笑一下的自嘲
  // 隱藏連接：白鹿洞早年是李渤帶白鹿隱居讀書之地，王貞白晚了幾十年在同一地方苦讀，延續同一處讀書人的隱居傳統
  396: {
    title: "白鹿洞二首其一",
    author: "王貞白",
    summary: "所有人都背過一寸光陰一寸金，卻沒人知道，這句話原本是一個讀書讀到不知道自己在哪一季的年輕人隨口寫下的自嘲。",
    story: `跟你說我朋友有道，他在廬山腳下一個叫白鹿洞的地方，把自己活活讀成了一個不知道現在幾月的人。

白鹿洞這個地方，聽名字浪漫，其實是幾十年前一個叫李渤的讀書人隱居的地方，據說當年他養了一頭白鹿相伴，出門散步都跟著，這個名字就這麼留下來了。等到有道進去讀書的時候，李渤早就不在了，但那種與世隔絕、一天到晚只有書和山的氣氛，一點都沒變，山裡連個像樣的市集都沒有，想買點紙墨都要走上大半天。有道那幾年幾乎沒下山，天沒亮就起來讀，就著一盞快耗盡的油燈讀到天黑，每天重複，連吃飯的時間都常常忘記，同住的人得提醒他碗裡的粥已經涼了。

問題是這樣讀書讀到一個地步，人會忘記時間。有道有一天忽然發現，窗外的樹已經全綠了，山風裡帶著花謝後的味道，春天不知不覺已經過完大半了，他完全沒感覺到，甚至一時想不起來自己是什麼時候換下冬天的厚衣裳的。他心裡咯噔一下：這一寸一寸過去的光陰，跟真金一樣貴重，就這樣被他讀書讀到不知不覺花掉了，一點都要不回來，而他甚至連花掉的過程都毫無印象。

他在洞裡待久了，性子也悶了，話越來越少，見了人也提不起精神寒暄。要不是有個一起隱居的道人三不五時跑來找他說話、拿些山裡的趣事逗他笑一下，他大概會一直悶頭讀下去，讀到自己都忘記怎麼笑、忘記自己還是個活人。他提筆把這件事寫下來：讀書不覺已春深，一寸光陰一寸金。不是道人來引笑，周情孔思正追尋。

周情孔思，指的是周公留下的情理、孔子留下的思想，他讀的全是這些。他寫的意思其實很直白：不是這個道人硬把他拉出來透透氣，他大概還會一頭栽進這些古人的道理裡，讀到忘記自己是誰、忘記外面的世界長什麼樣子。

有道後來考中了進士，離開了白鹿洞，往後的仕途生涯裡，他大概也常常想起這段近乎苦行的日子。可是他大概沒想到，他這句用來提醒自己別讀傻的話，後來變成全天下人惜時的座右銘，貼在多少學生的書桌前、寫進多少人的日記本。沒人記得他寫這句話的時候，其實是被朋友抓著笑出來的，那一刻他不是在教訓誰，只是被逗樂了以後隨手寫下的自嘲。`
  },

  // id=398 北宋 蘇軾 〈飲湖上初晴後雨二首-其二〉rating=5
  // 詩眼：天晴天雨都好看，這是一個被迫離開權力中心的人，學會的一種不用等世界變好才能過日子的活法
  // 隱藏連接：無
  398: {
    title: "飲湖上初晴後雨二首-其二",
    author: "蘇軾",
    summary: "這句被喊了快一千年的西湖比喻，其實是蘇軾自願離開京城權力核心那年，在湖上一邊喝酒一邊隨口說出來的。",
    story: `跟你說我朋友子瞻有一年在杭州的湖上喝酒，喝到把整座西湖比成一個美女，這個比喻一喊出來，喊了快一千年還沒有人推翻。

那年子瞻三十多歲，本來在京城當官，跟王安石那批人搞的新法看法不合，兩邊常常在朝堂上針鋒相對，他寫過不少奏章反對操之過急的變法，得罪的人不少，他也不想天天在朝堂上跟人吵架、看人臉色，索性自己請調外放，來杭州當一個管糧稅、管司法的通判，說白了是自願離開了權力核心，把自己從那場政治風暴的中心摘出來。這在旁人眼裡多少算是不得志，甚至有人替他惋惜，覺得這樣一個有才華的人窩在地方官任上可惜了，子瞻自己倒不這麼想，他到了杭州以後，幾乎天天往西湖跑，找朋友喝酒、划船、看山看水，公務之餘還修堤治水，日子過得比在京城還自在，心境也一天比一天寬。

有一天他跟人在湖上喝酒，一開始是大晴天，湖面被陽光照得波光粼粼，美得沒話說；喝著喝著，天說變就變，下起雨來，遠山被雨氣籠罩得一片朦朧，居然也美得讓人捨不得走，同座的人本來還嘀咕天氣掃興，子瞻卻看得入了神。他看著這一整天陰晴不定的西湖，忽然覺得，不管天晴天雨，這湖好像怎麼樣都好看，沒有一種天氣能把它變醜，反而每種天氣都給了它一種不同的樣子。

他想起了西施，那個吳越爭霸裡最有名的美人，據說不管濃妝豔抹還是素面朝天，怎麼打扮都好看，穿粗布衣裳照樣壓過滿座的錦衣。子瞻放下酒杯，笑著寫下：水光瀲灩晴方好，山色空濛雨亦奇。欲把西湖比西子，濃妝淡抹總相宜。

這幾句話後來傳得比他自己還遠。從那天起，杭州人開始管西湖叫西子湖，一叫就是快一千年，叫到現在還是，連地圖上的別稱都跟著沿用。子瞻自己大概也沒想到，他被迫離開京城那年在湖上喝的一頓酒，最後留給這座城市一個用到今天的名字。天晴也好，下雨也好，他這輩子後來遇過更慘的處境，被貶得更遠、日子過得更苦，好像都是從這天學會的：日子不用等它變好看才值得過，晴有晴的活法，雨有雨的活法。

他後來在杭州任上修了一道貫穿西湖的長堤，種上桃柳，這道堤後來也被百姓稱作蘇堤，一直用到今天。天晴時遊人如織，下雨時遊客反倒稀疏，可子瞻知道，那不代表雨天的湖不值得看，只是懂得看的人比較少而已。`
  },

  // id=412 清 龔自珍 〈己亥雜詩-其五〉rating=5
  // 詩眼：落花不是失敗退場，是換一種方式繼續盡一份力
  // 隱藏連接：同年（己亥年）好友林則徐南下廣州查禁鴉片，定盦臨行寫信替他打氣出主意（見送欽差大臣侯官林公序）
  412: {
    title: "己亥雜詩-其五",
    author: "龔自珍",
    summary: "他寫下落紅不是無情物的那天，是他自己辭官離開北京、覺得人生已經退場的那一刻，沒想到後來真的變成了養分。",
    story: `跟你說我朋友定盦，四十八歲那年騎著馬離開北京，走的時候心裡的難受大得他自己都嚇一跳。

定盦在京城做了大半輩子官，官不大，一路都不算得志，滿肚子改革的想法，寫過很多主張變法的文章，抨擊科舉的僵化、抨擊官場的暮氣，言辭犀利，得罪的人不在少數，卻始終沒能被真正重用，一輩子在幾個不痛不癢的位子上打轉。一八三九年，己亥年，他終於受夠了官場裡那種無事空轉的日子，辭了官，決定回南方老家，順道把多年積蓄的家眷也接回去。他離京那天是傍晚，太陽已經斜了，馬鞭一指，往東邊而去，他知道這一走，過去大半輩子的官場人生就徹底翻篇了，那種離愁湧上來，湧得又急又猛，一路上他寫了不少詩記這場離別，這首只是其中一首。

同一年，他的好朋友林則徐正好也在南下的路上，只是方向相反、任務天差地遠，林則徐是奉命去廣州查禁鴉片，肩上擔的是整個朝廷的期望和風險。定盦臨別前寫了一篇文章替他打氣，替他分析沿海形勢、出主意提防洋人反撲，這份交情史書上留得清清楚楚。一個是自請離場的失意官員，一個是即將在虎門銷煙、名留青史的欽差大臣，同一年各自出發，往人生完全不同的方向，一南一北，交錯而過。

定盦一路往南，走走停停，沿途看見路邊落花一片一片飄下來，鋪在地上，被過路的車輪馬蹄輾過也沒人在意。他忽然想到，這些花看起來是謝了、敗了、被春天拋棄了，其實一點都不是無情地枯萎，它們掉進土裡，會爛成養分，來年還是會把下一批花推上枝頭，甚至開得比去年更好。他想到自己這一場退場，未必是徹底結束，說不定日後還能以另一種方式派上用場。他把馬勒住，提筆寫下：浩蕩離愁白日斜，吟鞭東指即天涯。落紅不是無情物，化作春泥更護花。

定盦寫完這幾句話兩年後就過世了，沒能親眼看到任何一場真正的變法，也沒能等到林則徐後來被貶新疆的消息。可是幾十年後，康有為、梁啟超這一輩人重新翻出他的文章，把他的主張當成戊戌變法的養分，一路傳抄、引用。他自己說中了自己的結局，落花沒有白落，它真的變成了土。`
  },

  // id=414 元 施耐庵 〈水滸傳〉rating=5
  // 詩眼：曾經天下第一強的人，最後只留下一把連撿到的放牛孩子都不知道主人是誰的舊刀
  // 隱藏連接：無（此為楚漢史實與小說引用古謠，聚焦垓下之圍、虞姬別霸王典故本身，非施耐庵個人生平連結）
  414: {
    title: "水滸傳",
    author: "施耐庵",
    summary: "水滸傳裡引用的這首古謠，講的其實是項羽人生最後一夜，四面楚歌、與虞姬訣別、拒絕渡江，一代霸王就此收場。",
    story: `跟你說我這位朋友項羽最後一夜的事，這事情經過兩千多年，還被人編成歌謠傳唱，最後被寫進了水滸傳裡。

項羽被漢軍團團圍在垓下，兵力早已耗盡，糧草也所剩無幾，四面八方傳來楚地的歌聲，那是劉邦這邊故意安排的，目的是要讓項羽的士兵誤以為楚地全境都已經投降，軍心徹底崩潰。項羽半夜聽見這些歌聲，才真正明白自己輸定了，這場從鉅鹿之戰一路打到今天的爭霸，就要在這個寒冷的夜裡收場。他把心愛的人虞姬找來，兩人在營帳裡最後喝了一頓酒，帳外的篝火忽明忽暗。項羽唱了一首歌，力拔山兮氣蓋世，時不利兮騅不逝，唱到後面幾乎唱不下去，因為他不知道該拿虞姬怎麼辦，留下她，怕她落入敵手受辱；帶她走，戰場上根本走不了，只會拖累突圍的速度。相傳虞姬那晚也和了一首歌，唱完就在他面前自盡，不讓自己成為他突圍路上的拖累，用自己的命換他一條生路。

項羽帶著剩下的殘兵突圍，一路往南逃到烏江邊，身邊的士兵越打越少。渡口的船夫願意載他過江回江東，東山再起也不是不可能，江東那邊還有子弟兵可以重新招募。項羽卻怎麼都不肯上船，他覺得自己當年帶著八千江東子弟出來闖天下，如今一個人回去，沒臉見江東的父老，寧可死也不願背負這樣的愧疚活下去。他把心愛的烏騅馬送給船夫，自己留下來徒步力戰，一個人殺了漢軍數百人，最後力竭而死在江邊，一代霸王就此收場。

多年以後，九里山前那片曾經血流成河的舊戰場，早已看不出當年廝殺的痕跡，只剩放牛的孩子在地裡玩耍，偶爾從土裡撿到一把生鏽的舊刀舊槍，拿在手裡翻來覆去，不知道這曾是誰的兵器、誰握著它殺過人。有人路過此地，聽江風順著烏江水吹過來，覺得那聲音竟像極了當年虞姬向霸王作別的哭聲，寫下了這四句古老的歌謠：九里山前作戰場，牧童拾得舊刀槍。順風吹起烏江水，好似虞姬別霸王。

後來這首謠流傳進了民間故事，水滸傳裡也借它感嘆過英雄末路。那些曾經天下第一的強者，最後能留給世界的，往往只是一把連撿到的孩子都不知道主人是誰的舊刀。`
  },

  // id=415 南北朝 佚名 〈敕勒歌〉rating=5
  // 詩眼：一首牧民懷念草原的歌，被一支剛打了敗仗、快要崩潰的軍隊拿來當救命藥
  // 隱藏連接：真實史載546年玉壁之戰高歡大敗，軍心浮動謠傳其已死，命敕勒族出身的大將斛律金當眾高唱敕勒歌以安軍心
  415: {
    title: "敕勒歌",
    author: "佚名",
    summary: "這首課本裡的草原民歌，其實是一場慘敗的戰役裡，一支快要崩潰的軍隊靠著唱歌穩住軍心的真實故事。",
    story: `跟你說我朋友高歡打過一場這輩子最慘的仗，慘到他必須靠一首牧民的歌，才把自己的軍隊從潰散邊緣拉回來。

那是公元五四六年，高歡帶著東魏的大軍去打西魏守著的玉壁城，這座城地勢險要，守將韋孝寬又是個難纏的角色，圍城圍了快兩個月，挖地道、堆土山、各種攻城手段都用上了，怎麼打都打不下來，士兵死傷慘重，屍體堆得比城牆邊的土山還高。冬天又冷又缺糧，軍中甚至還傳出瘟疫，一批一批士兵病倒，士氣一天比一天低落。高歡自己也急出病來，一度病得下不了床，連軍務都要靠人代為傳達。營裡開始流傳一個謠言，說主帥已經死了，這種謠言在兩軍對峙的節骨眼上，比敵人的箭還要命，稍微傳開，整支軍隊可能自己就先垮了，不用等敵人來攻就會一哄而散。

高歡知道再不出面，這仗真的要輸得一敗塗地，連退兵的秩序都保不住。他硬撐著病體，讓人扶著自己出現在軍前，讓所有士兵親眼看到主帥還活著、還站得住。光是露面還不夠，軍心已經散得差不多了，他需要一件事把大家的心重新穩住。他身邊有一位大將叫斛律金，出身敕勒族，是草原上長大的漢子，高歡叫他當著全軍的面，唱一首敕勒族世世代代傳唱的草原老歌。

斛律金開口唱了，聲音蒼老又渾厚，在寒風裡傳得很遠。歌詞很簡單，唱的是敕勒族世代放牧的那片大草原，陰山腳下，天空像一頂巨大的氈帳，把四面的原野整個罩住；天空蒼蒼茫茫，草原也蒼蒼茫茫，風一吹過，牧草伏低下去，藏在草裡的牛羊一下子全都露了出來。敕勒川，陰山下。天似穹廬，籠蓋四野。天蒼蒼，野茫茫，風吹草低見牛羊。

士兵們聽著聽著，很多人是敕勒族或者草原出身的子弟，聽見這首從小聽到大的歌，忽然就想起了各自家鄉的草原、想起了等他們回去的牛羊和家人，一時之間，凍傷、飢餓、恐懼好像都被這熟悉的旋律稍微壓了下去。相傳高歡自己也跟著唱了起來，唱到落淚，一個久經沙場的主帥當著全軍的面掉眼淚。那一夜，軍心竟然真的被一首牧歌穩住了，這支差點潰散的軍隊，撐著退回了自己的地盤，沒有在半路上崩潰瓦解。

一千五百年後，沒人記得玉壁城下那場仗打得多慘、死了多少人，這首歌卻還留在課本裡，被一代一代的孩子背誦，沒人知道，這幾句描寫牛羊草原的家鄉話，當年其實是一支軍隊的救命藥。`
  },

  // id=417 盛唐 李白 〈清平樂-畫堂晨起〉rating=5
  // 詩眼：連學者都吵不清是不是他寫的，但沒人能否認——只有被封為謫仙人的那個男人，才寫得出仙人醉酒揉碎白雲的句子
  // 隱藏連接：賀知章初見李白讀完蜀道難驚呼謫仙人的真實記載（742年長安），用以連結詞中仙人意象與李白本人的外號
  417: {
    title: "清平樂-畫堂晨起",
    author: "李白",
    summary: "這首寫雪的詞是不是李白親筆，學者吵了很久，可是那句仙人醉酒揉碎白雲的想像力，怎麼看都像謫仙人才寫得出來。",
    story: `跟你說我朋友太白有一年冬天在長安的畫堂裡看雪，看著看著把自己看成了半個神仙。

太白四十二歲那年剛到長安，經人引薦見到當時已經是文壇前輩的賀知章。賀知章讀了他的蜀道難，讀到一半就驚呼出聲，手裡的酒杯都差點沒拿穩，說這個人根本不像凡人寫得出這種句子，直接叫他謫仙人，被貶到人間來的仙人。兩人那天索性當場解下身上的金龜換酒，喝了個痛快，這件事後來被寫進正史，傳為一段佳話。這個外號從那天起就跟了太白一輩子，連皇帝身邊的人都這麼叫他，玄宗召見他寫詩助興，也常常笑著喊他謫仙。

相傳這首清平樂就寫在他剛入翰林院、風頭正盛的那幾年冬天。那天他一早在畫堂裡醒來，還沒起身，就有人來稟報，說外頭下雪了。他撐起身子，把簾子高高捲起來看，外面白茫茫一片，雪光遠遠地鋪滿了整座庭院的臺階，看起來像什麼吉兆一樣，宮裡的人都說瑞雪兆豐年。屋裡爐子還燒著炭，煙氣被雪映得格外亮；院子裡結霜的草叢，安安靜靜地泛著一點清冷的光，像誰隨手灑了一把碎玉在地上。

太白盯著這片雪看了很久，翰林院裡的差事此刻好像都被拋到腦後，心裡忽然冒出一個念頭：這哪裡像凡間的雪，倒像是天上哪個仙人昨晚喝醉了酒，趁著夜色沒人瞧見，隨手把天上的白雲扯下來揉碎、灑了滿地，才留下這一院子的皓白。他提筆寫下：畫堂晨起，來報雪花墜，高捲簾櫳看佳瑞，皓色遠迷庭砌，盛氣光引爐煙，素草寒生玉佩，應是天仙狂醉，亂把白雲揉碎。

這幾句話後來被收進詞集，掛在太白名下流傳千年，只是後世的學者一直有爭論，那時候詞這種文體才剛剛起步，格律都還沒固定下來，太白到底寫過多少首詞，其實沒人能百分之百說清楚，有人甚至懷疑是後人偽託。可是不管真假，這幾句把雪說成仙人醉酒揉碎雲彩的想像力，怎麼看都像是那個被賀知章一句話定了終生外號的人才寫得出來的。太白這輩子被人叫了一輩子謫仙人，連下雪天，他都要把自己活成一個喝醉了鬧脾氣的仙人，好像凡間的規矩管不住他。

後世不管怎麼考證真偽，這首詞始終被歸在太白名下流傳，或許正因為除了他，再沒有第二個人的名號能撐得起這種把大雪想像成仙人耍酒瘋的狂放筆調，這本身就是對謫仙人三個字最好的註腳。`
  },

  // id=431 南唐 李煜 〈浪淘沙令-簾外雨潺潺〉rating=5
  // 詩眼：一個曾經的皇帝在夢裡騙過自己幾秒鐘忘了自己是囚犯，天一亮連被子都提醒他現在有多冷
  // 隱藏連接：無（具體史實：975年南唐亡國被俘至汴京，封違命侯，南北氣候落差為實際歷史背景）
  431: {
    title: "浪淘沙令-簾外雨潺潺",
    author: "李煜",
    summary: "這首詞寫的不是普通的傷春，是一個亡國皇帝每天清晨被北方的冷被子凍醒、想起自己現在是階下囚的那一刻。",
    story: `跟你說我朋友重光被關在汴京的那幾年，最難熬的不是白天，是每天快天亮的那一刻。

重光原本是南唐的皇帝，九七五年，宋朝的軍隊攻破金陵，他投降被俘，一路被押送到宋朝的首都汴京，身邊只帶了少數幾個舊臣。宋朝皇帝給他封了一個叫違命侯的爵位，聽起來是個爵位，其實是明擺著羞辱他，提醒他曾經違抗過朝廷、拒不歸順，這個封號他每次聽人喊起都覺得刺耳。他從一國之君，變成一個被軟禁、被監視的降臣，身邊處處是眼線，連寫詩填詞都要小心翼翼，深怕哪句話被人解讀成心懷不軌。

汴京在北方，冬天比他熟悉的江南冷得多，風一吹就是刺骨的乾冷，跟金陵那種濕潤的冷完全不同。他過去在金陵蓋著的那幾床薄薄的絲綢被子，在南方剛剛好，搬到這裡完全撐不住這裡的寒氣，他試過加蓋幾層，還是覺得寒意從四面八方鑽進來。每天快到五更天的時候，冷氣總會把他從睡夢裡凍醒。而那個夢，往往是他這一天裡唯一輕鬆的時刻，夢裡他常常忘記自己現在的身分，恍恍惚惚以為自己還是那個可以隨意享樂的人，身邊還是宮女樂伎環繞，貪戀著夢裡那一小段不真實的歡愉，捨不得那個夢太快結束。

窗外的雨淅淅瀝瀝下著，春天已經快要過完，他躺在冷被子裡，清醒過來的那一刻最難受，比夢裡的任何情節都更折磨人。他告訴自己，千萬不要一個人跑去憑欄眺望，欄杆外面是他再也回不去的萬里江山，離開它的時候那麼容易，一句投降就交出去了，可是這輩子大概再也見不到了，連再看一眼的機會都沒有。他提筆寫下：簾外雨潺潺，春意闌珊，羅衾不耐五更寒。夢裏不知身是客，一晌貪歡。獨自莫憑欄，無限江山，別時容易見時難。流水落花春去也，天上人間。

流水落花，春天就這樣過去了，一邊是天上，一邊是人間，他清楚知道自己已經被劃到了人間這一邊，再也回不到從前那個位置。這一年他還活著，離那杯真正要了他命的毒酒，還有一點點時間，只是他自己並不知道，那杯酒會在哪一個看似平常的晚上送到面前。

後人讀到這幾句，往往只當是尋常的傷春之作，很少有人真正體會，一個從九五之尊跌到階下囚的人，光是撐過每天五更天那陣寒意，就已經耗盡了他所剩不多的力氣。`
  },

  // id=432 南唐 李煜 〈相見歡-無言獨上西樓〉rating=5
  // 詩眼：有一種悲傷連悲傷兩個字都形容不準，因為想念的不是一個人，是一整個曾經是自己的世界
  // 隱藏連接：與431同為囚居汴京期間所作，聚焦無人可訴這個角度，與431的夢裡貪歡角度區隔
  432: {
    title: "相見歡-無言獨上西樓",
    author: "李煜",
    summary: "這句別是一般滋味在心頭，寫的不是失戀，是一個亡國皇帝發現連悲傷這個詞，都不夠精準形容他失去的東西。",
    story: `跟你說我朋友重光被關在汴京的日子裡，有一種心事，他試過，發現連他自己都找不到準確的字來講。

他從前是南唐的皇帝，現在是宋朝眼皮底下一個被軟禁的降臣，身邊雖然還有跟著他一起北上的妻子小周后，可是這種事不是說給誰聽就能減輕一分的，他失去的不是一個人、一件東西，是整整一個曾經完全屬於他的世界，江山、宮殿、朝臣、過去三十幾年的人生，包括他年輕時那些寫詞飲宴的日子，全部一次性沒了，連想回去看一眼都不可能。這種東西要跟誰說？宋朝這邊的人只會覺得他矯情，一個亡國之君還有什麼資格傷春悲秋，能留他一命已經是格外開恩，稍有不慎還可能招來殺身之禍。

有天晚上他一個人，一句話都沒說，就自己走上西邊的樓，連身邊的侍從都沒有帶。天上一彎月亮細細的，像一個鉤子掛在那裡，冷冷清清照著整座院子。院子很深，種著一棵梧桐樹，秋天已經很深了，葉子落了大半，整座院子安安靜靜的，好像被這片清冷的秋色鎖在裡面，誰都出不去，連風聲都顯得格外清楚。他站在那裡，心裡那團情緒纏在一起，怎麼理都理不清楚，像剪也剪不斷的絲線，越想整理，反而纏得越亂，理出一頭又冒出另一頭。

他知道這種感覺一般人會叫它離愁，可是他覺得不夠準確，離愁兩個字太輕了，裝不下他心裡那團東西。他提筆寫下：無言獨上西樓，月如鉤，寂寞梧桐深院鎖清秋。剪不斷，理還亂，是離愁，別是一般滋味在心頭。別是一般滋味，他寫得很清楚，這不是普通的離愁，是他自己都說不上來的另一種味道，混雜著羞辱、悔恨、思念和無處可逃的絕望。

千年後讀這幾句的人，未必都當過皇帝，未必都亡過國，可是每個人心裡都有過那種說不出名字的心事，站在自己的西樓上，看著自己的那彎月亮，體會著自己那份說不清是什麼滋味的滋味。重光那晚沒有找到準確的字，但他把那種說不出的感覺本身寫下來了，這就夠了，夠讓千年後的人一讀就懂。

後來的讀者未必經歷過亡國，卻總能在某個深夜，忽然懂了他那句剪不斷理還亂，因為那種說不清道不明的滋味，從來不是帝王才會有的，只是他碰巧先把它寫成了字。`
  },

  // id=433 南唐 李煜 〈相見歡-林花謝了春紅〉rating=5
  // 詩眼：花謝得太快，他連留住一段感情、留住一個人的資格都沒有了
  // 隱藏連接：相傳小周后被迫多次入宮，回來後常哭泣——「胭脂淚，相留醉」寫的可能就是這樣的夜晚（見宋人筆記，正史存疑）
  433: {
    title: "相見歡-林花謝了春紅",
    author: "李煜",
    summary: "這闋詞表面在寫花謝春殘，其實在寫一個連妻子今晚回不回得來都保護不了的亡國皇帝。",
    story: `跟你說我朋友重光的一個雨夜。汴京城裡一座圈起來的小院子，牆外是宋朝的天下，牆內只有他，還有幾株海棠。那天早上一陣雨，晚上又一陣風，隔天他推門出去看，滿地都是被打落的花瓣，紅得像誰哭花了的妝。

他原本不是該站在這個院子裡的人。三年前，他還是江南的皇帝，金陵城裡鳳閣龍樓，宮女成群，一句話能決定幾十萬人的生死。三年後，他是宋朝賜的一個爵位，違命侯，每個月要去朝見那個滅了他國家的皇帝，坐在最末的位置，喝酒的時候還得聽人明裡暗裡奚落幾句，問他當年怎麼不多守幾年。

他這座小院子，說是院子，其實更像一座漂亮一點的牢籠，門口常年有人守著，出入都要通報。以前在金陵，他嫌宮裡的規矩煩，如今才知道，那些規矩再煩，好歹是他自己定的；這裡的規矩，一條都輪不到他置喙。

比屈辱更難熬的，是他保護不了身邊的人。他的妻子小周后長得美，這在江南是驕傲，在汴京卻成了禍。據當時人的筆記記載，她時常被叫進宮裡去，一去就是幾天，回來的時候常常哭，看見李煜也不說話，只是哭，偶爾才聽見她低聲埋怨幾句。不是恨他，是恨這個處境，恨他連攔都攔不住。李煜知道發生了什麼，卻什麼都做不了。以前他是皇帝，一句話能護住整個後宮；現在他什麼都不是，甚至連自己的妻子今晚會不會回來，他都沒有把握。

那個雨夜之後的早晨，他站在滿地落花前，忽然覺得這些花跟她很像，被風雨打過，胭脂一樣的紅色混著水漬，像哭過的臉。他想留住春天，就像他想留住她，想留住從前那個還能保護人的自己，可是花已經謝了，太匆匆，誰都留不住。他低聲寫下：

林花謝了春紅，太匆匆，無奈朝來寒雨晚來風。胭脂淚，相留醉，幾時重，自是人生長恨水長東。

幾時重這三個字他寫得最慢。他不是在問花什麼時候再開，他是在問，那個還能陪她喝一杯酒、還能說一句別怕有我的自己，還會不會回來。

他後來沒有機會再問第二次。兩年後的一個七夕，他生日那天，宋朝皇帝送來一杯毒酒。滿地紅花早就謝盡，那年他四十二歲。`
  },

  // id=434 南唐 李煜 〈破陣子-四十年來家國〉rating=5
  // 詩眼：亡國那一刻，他心裡放不下的不是社稷宗廟，是眼前這群宮女——一個不合格的皇帝，卻誠實到讓人心疼
  // 隱藏連接：蘇軾在《跋李煜詞》裡批評他該在祖廟前痛哭謝罪、而非為宮娥垂淚，這句後世評語剛好點出了這闋詞最動人的矛盾
  434: {
    title: "破陣子-四十年來家國",
    author: "李煜",
    summary: "這闋詞被蘇軾罵了千年，說他亡國那天哭錯了對象，可正是這個哭錯對象的男人，寫出了最誠實的一闋亡國詞。",
    story: `跟你說我朋友重光的最後一個早晨。金陵城裡，宮女已經在教坊裡奏起送別的曲子，他站在祖廟前，卻一句話也說不出來，只是盯著自己的鞋尖。

那是開寶八年十一月，宋朝的軍隊圍城快一年了，糧草斷絕，城裡的人開始吃樹皮。李煜其實不是一個很想當皇帝的人，他更喜歡寫詞、彈琴、跟大臣談佛法，治國的事大半交給別人。他的江南，四十年來家國，三千里地山河，是他父親和祖父打下的基業，鳳閣龍樓連著天邊，玉樹瓊枝繞著宮牆，他從小到大幾乎沒見過真正的戰爭，幾曾識干戈，他是真的不認識。

他當皇帝的十幾年裡，最上心的是修訂佛經、整理古畫、跟大臣談論書法，朝政大半交給幾個信任的老臣。宋朝使者第一次來金陵議和時，他還在琢磨一幅新得的字帖，直到城外的軍隊真正逼近，他才慌了手腳，可惜這時候再慌，已經來不及重新學一遍怎麼當皇帝。

城破那天，他脫下龍袍，光著上身，率領臣子出城投降。這叫肉袒出降，是亡國之君最屈辱的姿勢之一。史書記載得很簡略，但他自己後來把那個早晨的細節都寫進詞裡：他形容自己是倉皇的，是慌亂的，連好好走一趟祖廟辭別列祖列宗的從容都沒有。教坊的樂工還不知道發生了什麼，照常奏起離別的曲子，宮女們一個個站在廊下，看著他們的皇帝要被押走了。他看著那些跟了他多年的宮女，忽然掉下眼淚。

沈腰潘鬢銷磨，他形容自己這些年被拖垮的身體，像沈約一樣清瘦，像潘岳一樣早生白髮。最是倉皇辭廟日，教坊猶奏別離歌，垂淚對宮娥，他寫下這幾句的時候，後人讀到都替他不值：城都破了，該哭的是列祖列宗，他哭的卻是眼前這幾張熟悉的臉。後來蘇軾讀到這闋詞，直接說他不懂事，該在宗廟前痛哭謝罪百姓，再上路，怎麼反倒在宮娥面前掉淚聽曲。

這句話罵得有道理，卻也剛好說中了他是個什麼樣的人。他從來不是能扛起社稷的皇帝，他只是一個誠實到連亡國那一刻都不演戲的普通人。眼前這些人要散了，他就哭給他們看，其他的，他顧不上了。

史書上記載這場投降的過程很簡略，寥寥數語帶過，可是李煜自己把那個早晨的每一個細節都留了下來。後人讀這闋詞，與其說是讀一場亡國，不如說是讀一個從沒準備好面對亡國的人，如何笨拙又誠實地把那個早晨過完。`
  },

  // id=435 南唐 李煜 〈子夜歌·人生愁恨何能免〉rating=5
  // 詩眼：每晚夢回故國，每天早上都要重新亡國一次——比絕望更折磨人的，是反覆燃起又被澆熄的希望
  // 隱藏連接：他在汴京遭嚴密軟禁，舊臣不得探視，故國夢重歸的夢境，幾乎是他唯一還能自由往返金陵的方式
  435: {
    title: "子夜歌·人生愁恨何能免",
    author: "李煜",
    summary: "這首詞寫的不是一次心碎，是李煜降宋後每天早上都要重新心碎一次的日常。",
    story: `跟你說我朋友重光在汴京的一個清晨。他張開眼睛，天花板是陌生的，窗外的聲音是陌生的，他愣了幾秒才想起來，這裡不是金陵，他已經在這裡住第三年了。

投降之後，宋朝把他和小周后安置在汴京一處宅子裡，表面上封了個違命侯，其實形同軟禁。原本的舊臣不許探望，出門有人跟著，連寫信都要小心。他從一個能決定幾十萬人生死的皇帝，變成一個連自己今天能不能出門都做不了主的人。白天他還能靠寫字、喝酒撐住，可是一到晚上，他控制不了自己的夢。

他試過白天靠處理一些瑣事分散注意力，練字、喝茶、偶爾跟小周后說幾句話，可是一到入夜，那些白天硬壓下去的念頭全部湧回來。他甚至開始怕睡覺，怕自己又夢見金陵，又要在天亮時重新經歷一次失去。

他常常夢見金陵。夢裡他又站上了那座熟悉的高樓，是他年輕時常跟臣子登高賦詩的地方，秋天天氣晴朗，能看到很遠的江面。夢裡什麼都沒變，宮牆還在，臣子還在，他還是那個皇帝。夢做得越真實，醒來的那一下就越殘忍——他發現自己躺在汴京，江南已經不是他的了，那些跟他一起登高的人，有的死了，有的降了宋做了別人的臣子，再也不會有人陪他上那座樓。

他坐起來，眼淚已經先流下來，才反應過來自己在哭。人生愁恨何能免，銷魂獨我情何限，故國夢重歸，覺來雙淚垂，高樓誰與上，長記秋晴望，往事已成空，還如一夢中。他把這些話寫下來的時候，手是抖的，不是因為冷。

這樣的早晨他後來又經歷了無數次。人不會因為哭過一次就不再想家，夢也不會因為醒來一次就不再重複。他這輩子剩下的日子，大概每天都要重新失去一次金陵，這才是最折磨人的地方，不是絕望，是每天早上都要重新抱一次希望，再親手把它捏碎。

後來的日子裡，他漸漸學會了一件事：不是不再做夢，是學會了在醒來的瞬間，先分清楚哪些是真的、哪些已經回不去了，再讓自己慢慢從那種撕裂感裡爬出來，一天一天，直到下一次夢又把他拉回去。

有人說，他這輩子最誠實的作品，不是那些寫給臣下看的詔書，而是這些夜半驚醒後隨手寫下的句子，因為那個時刻他來不及演任何角色，只剩下一個失去了一切、還在做夢的普通人。`
  },

  // id=438 北宋 蘇軾 〈西江月〉rating=5
  // 詩眼：從權力中心跌落谷底，中秋夜連喝酒都沒人陪，他仍要為看不見的弟弟舉杯
  // 隱藏連接：蘇軾與弟弟蘇轍情誼深厚，曾相約夜雨對床、退隱共處，這闋詞裡的北望，很可能就是望向遠方的子由與故人
  438: {
    title: "西江月",
    author: "蘇軾",
    summary: "這闋詞寫在蘇軾人生最狼狽的一年，他曾經是朝廷紅人，中秋夜卻連一杯像樣的酒都喝不起，只能舉杯遙敬看不見的弟弟。",
    story: `跟你說我朋友子瞻在黃州過的一個中秋。他一個人坐在江邊，手裡端著一杯酒，這杯酒賣得很便宜，因為他現在的身分，值不了什麼排場。

一年多前，他還是朝廷裡數一數二的紅人，詩文傳遍天下，見誰都能高談闊論。因為烏台詩案，他被抓進御史台的監牢關了一百多天，差點被砍頭，後來貶到黃州做一個沒有實權的團練副使，還規定不能隨便離開這個地方。以前他身邊總是圍著一群朋友，現在他寫信給誰，誰都怕受牽連，回信的人越來越少。他自己種地、自己蓋房子，自號東坡，日子勉強能過，可是中秋這種節日一到，冷清就藏不住了。

他到黃州之後，帶著一家老小開墾城東一塊坡地種糧食，自己扛鋤頭，日曬雨淋，早已不是當年那個名滿京城的翰林學士。有朋友輾轉捎信來問候，他回信總是報喜不報憂，只有寫給子由的信裡，才會露一點真正的疲憊。

他弟弟子由，是這輩子跟他最合得來的人。兩人年輕時讀書一起考試，做官後常常分隔兩地，約好將來要一起退休，睡在同一個屋簷下，聽一輩子的夜雨。這一年中秋，子由在遠方，兩人已經好幾年沒能好好聚一次。黃州這邊，風把院子外的樹葉吹得整晚在廊下響，他抬頭想看月亮，雲卻把月光遮去了大半。他想起自己這幾年一路跌的官，想起鬢邊漸漸冒出來的白髮，笑了一下，笑得有點勉強。

他端起那杯便宜的酒，對著北方舉了舉，弟弟大概在那個方向，他曾經熟悉的朝堂和故人也在那個方向。世事一場大夢，人生幾度秋涼，夜來風葉已鳴廊，看取眉頭鬢上，酒賤常愁客少，月明多被雲妨，中秋誰與共孤光，把盞悽然北望。

他把這杯酒喝完，一個人。後來他還會被貶得更遠，到惠州，到儋州，但這種一個人對著北方舉杯的夜晚，他早就在黃州先練過一次了。後來的每一次，他都撐得住，大概就是因為知道，總有一個方向，有人在等他回去。

多年以後，他被貶到更南更遠的惠州、儋州，寫信回去總說日啖荔枝三百顆，不辭長作嶺南人，讀的人都以為他真的過得逍遙自在。只有極少數人知道，這種笑著扛下去的本事，是他早在黃州那個中秋夜，一個人舉杯對著北方的時候，就已經練成了。`
  },

  // id=444 北宋 秦觀 〈鵲橋仙-纖雲弄巧〉rating=5
  // 詩眼：牛郎織女一年才見一次，他卻說這樣反而比天天相守更珍貴——寫給所有異地戀人的一句安慰
  // 隱藏連接：秦觀因黨爭屢遭外放貶謫，長年與家人分隔兩地，七夕牛女的傳說對他而言更像是自己生活的真實寫照（此為合理推論，非正史明載）
  444: {
    title: "鵲橋仙-纖雲弄巧",
    author: "秦觀",
    summary: "這首詞被後人當成情話金句傳頌千年，其實是一個常年被貶到天涯海角的男人，用自己的半生換來的體悟。",
    story: `跟你說我朋友少游在一個七夕夜寫的一首詞。那天晚上他抬頭看銀河，心裡想的不是牛郎織女的故事有多美，是自己這幾年到底有多少個晚上，是一個人在外地過的。

秦觀年輕時候，家在高郵，考了好幾次科舉才中，中了之後又常常被派到外地做官，後來捲進新舊黨爭，一路被貶，從汴京到杭州，到處州，到郴州，越貶越遠，家人多半留在原地，他自己拖著行李到處跑。這樣的日子，七夕這種一年見一次面的傳說，對別人是浪漫故事，對他卻是活生生的參照組，牛郎織女好歹每年七月七都能準時相會，他自己有時候一整年都見不到家人一面。

他每到一個貶所，總要先安頓好家小的溫飽，再想自己的仕途。有一年他被貶到郴州，寫信回家報平安，信送到時，孩子已經又長高了一截，他卻連這變化都是聽人轉述才知道的。

那晚他在驛站或者友人家中借宿，窗外的雲彩被晚霞染得特別巧，天上有流星劃過，像誰在傳遞一個遲來的消息。銀河那麼寬，那麼遠，兩顆星星卻年年都能在鵲鳥搭成的橋上相會一次。他想起自己這些年寫過的、收過的家書，有時候一封信在路上走幾個月，等收到的時候，說的事情早就過去了。可是奇怪的是，收到信的那一刻，再舊的消息都覺得新。

他忽然覺得，自己這些年好像一直在羨慕別人朝朝暮暮的日子，卻沒想清楚，朝夕相處和刻骨的想念，到底哪一種才算真正擁有過對方。他提筆寫下：

纖雲弄巧，飛星傳恨，銀漢迢迢暗度，金風玉露一相逢，便勝卻人間無數，柔情似水，佳期如夢，忍顧鵲橋歸路，兩情若是久長時，又豈在朝朝暮暮。

寫完他把筆放下，看著窗外的星星又坐了很久。這幾句後來成了寫給全天下異地戀人的一封信，原來距離從來不是感情的量尺，他用自己被貶謫、被迫分離的半生，換來了這個答案。

後來的讀者未必都經歷過牛郎織女式的長年分離，可是異地戀、遠距離婚姻，這些說法翻譯成現代語言，說的其實是同一件事——秦觀用自己被貶謫的半生，替所有這樣的人先想好了答案。

秦觀晚年病逝在被貶往雷州的路上，離家更遠，離團聚更沒有指望。可是他早年在七夕夜寫下的這幾句話，倒像是提前替自己往後的漂泊做好了心理準備，也替所有異地相思的人，先把答案想清楚了。`
  },

  // id=448 南宋 李清照 〈如夢令-常記溪亭日暮〉rating=5
  // 詩眼：所有人只記得她晚年寫愁，卻忘了她曾經醉到找不到回家的路
  // 隱藏連接：李清照成長於濟南書香門第，父親李格非治學嚴謹卻對女兒格外寬容，這種罕見的養育方式讓她少女時代擁有不受拘束的出遊經驗
  448: {
    title: "如夢令-常記溪亭日暮",
    author: "李清照",
    summary: "這首被當成李清照最歡快作品的小令，寫的其實是後來那個寫盡千古愁緒的女詞人，十幾歲時一次划船划錯方向的糗事。",
    story: `跟你說我朋友易安少女時候的一個傍晚。她划著一艘小船，喝得有點醉，天都快黑了還找不到回家的路，不是迷路，是她划錯了方向，一頭划進了滿滿一片荷花裡。

李清照後來被人記住的，多半是晚年那些寫愁寫恨的詞。可是在那之前，她有過一段很奢侈的少女時光。她父親李格非是當時有名的學者，家裡藏書多，治學嚴謹，對這個女兒卻格外縱容，別人家的女兒被關在閨房裡學女紅，他卻由著她讀書、寫詩、出門遊玩。這在當時的士大夫家庭裡，算是很難得的事。

李格非常常帶著她參加文人雅集，讓她跟著大人一起品評詩文，這在當時許多讀書人家裡是想都不敢想的事，多數人家的女兒連書房的門檻都進不去，更別說跟一群士大夫一起飲酒作詩。

那天她跟朋友在溪邊一座亭子喝酒，喝到興頭上，天色一點一點暗下來都沒察覺。等到終於想起該回家了，已經有點醉，划著船往回走，卻怎麼也划不對方向，一路划進了一片密密的荷花深處。她也不太慌，只是覺得好笑，拚命划槳想找出路，槳聲、笑聲吵得驚起了一整片棲息的鷗鷺，撲棱棱地從水面上飛起來，劃過暮色中的天空。

她後來把這個傍晚寫成一首小令：

常記溪亭日暮，沉醉不知歸路，興盡晚回舟，誤入藕花深處。爭渡，爭渡，驚起一灘鷗鷺。

沒有愁，沒有恨，只有一個喝多了、划錯方向、笑著跟朋友搶槳的少女。多年後她會經歷國破、家散、喪夫、再嫁又離婚的種種波折，寫下的詞一首比一首沈重。可是在她十幾歲的那個傍晚，她的世界只有一船的荷花香跟一灘被驚起的鷗鷺，如果沒有這段被父親縱容出來的自由歲月，後來那個能扛住所有苦難、把心事寫成千古絕唱的李清照，可能連筆都不會拿得這麼穩。

多年後有人讀到這首小令，很難把裡面那個笑著跟朋友搶槳的少女，跟後來寫出淒淒慘慘戚戚的李清照聯想在一起。可正是因為她曾經那樣毫無保留地快樂過，後來的傷痛才顯得格外真實，不是天生愁苦的人，是曾經擁有過快樂、後來一點一點失去的人。

多年以後有研究者統計，李清照傳世的詞裡，寫愁的占了大半，這首卻是少數幾首純粹寫快樂的作品，正因為稀少，才顯得格外珍貴，像是她留給後來苦難歲月的一點存糧。`
  },

  // id=450 南宋 李清照 〈一剪梅-紅藕香殘玉簟秋〉rating=5
  // 詩眼：想放下卻放不下的思念，剛從眉頭移開，就爬進了心裡——連自己都控制不了的重複
  // 隱藏連接：趙明誠婚後常年在外求學、訪碑，相傳這闋詞便是他外出期間李清照獨自登舟時所作
  450: {
    title: "一剪梅-紅藕香殘玉簟秋",
    author: "李清照",
    summary: "這首詞最後兩句寫的不是浪漫，是她想盡辦法要放下一個人，卻眼睜睜看著那個念頭自己搬進了心裡。",
    story: `跟你說我朋友易安一個秋天的下午。荷花謝了，只剩殘香，她房裡那張竹蓆睡起來已經有涼意，她一個人，把絲裙解開換上便裝，獨自登上一艘小船，不為別的，就是想找點事做，不要一直坐在屋裡想他。

她跟趙明誠成親沒幾年，兩人算是當時難得的一對，都愛書畫金石，常常一起校勘古籍、辨認碑文，是夫妻，也是同好。可是趙明誠常常不在家，有時是去太學讀書，有時是外出訪求古碑舊拓，一去就是幾個月。新婚的甜蜜還沒淡，人已經先分開了大半年裡的大半時間。她不是那種只會坐困閨房哭泣的女子，可獨處久了，還是會想。

趙家與李家都是當時有名望的讀書人家，兩人成親時，坊間都說這是一對難得的佳偶，可惜這樣的佳偶，往往聚少離多。她曾開玩笑跟人說，自己嫁的與其說是一個丈夫，不如說是半年才回家一次的客人。

那天她划船出去，也沒有目的地，只是看著水面發呆。她想，這時候會不會正好有大雁從北方飛回來，雲層裡會不會藏著他寄來的一封信。雁字排成一行從天邊飛過的時候，她抬頭望了很久，月光滿滿地照在西邊那座樓上，那是她常常一個人待到很晚的地方。花謝了自己飄零，水自己流，誰都留不住，可是那種想念，一個人在這裡想，一個人在那裡想，竟然是一模一樣重的。

她提筆寫下：

紅藕香殘玉簟秋，輕解羅裳，獨上蘭舟。雲中誰寄錦書來，雁字回時，月滿西樓。花自飄零水自流，一種相思，兩處閒愁。此情無計可消除，才下眉頭，卻上心頭。

寫到最後兩句時她自己也笑了，她想過很多辦法讓自己別再想他，皺著眉頭想了半天，好不容易鬆開眉頭，結果那個念頭已經自己搬到心裡去了，一步都沒少。這種身不由己的偷跑，後來變成無數等待中的人，讀到都會心一笑的共同經驗。

這首詞後來被無數等待伴侶歸來的人反覆傳抄引用，才下眉頭卻上心頭八個字，說盡了那種明明想放下、卻控制不住自己心思的無奈。李清照寫下它的時候，大概沒想到，自己不過是想找點事做打發一個秋天下午，卻寫成了千年後所有異地戀人的共同心聲。`
  },

  // id=451 南宋 李清照 〈醉花陰-薄霧濃雲愁永晝〉rating=5
  // 詩眼：她用一句比喻讓丈夫甘拜下風，不是吵贏的，是寫贏的
  // 隱藏連接：相傳趙明誠收到此詞後不服氣，閉門三日仿作五十闋，混入其中請友人評賞，友人卻獨獨挑中原屬李清照的三句（出自後人筆記，非正史）
  451: {
    title: "醉花陰-薄霧濃雲愁永晝",
    author: "李清照",
    summary: "這闋重陽詞讓一場夫妻之間的較量傳頌千年，比誰更愛誰不重要，比誰寫得更好，答案從一開始就沒有懸念。",
    story: `跟你說我朋友易安重陽節那天做的一件事，她把自己想他想瘦了的樣子，寫成一首詞，寄去給遠方的丈夫，結果把他將了一軍。

那年重陽，趙明誠又不在家，外出做事去了。屋裡霧氣濃，雲層厚，她一整天心情都提不起來，銅獸香爐裡的瑞腦香早燒完了也懶得添。到了晚上，玉枕鋪著薄紗帳子，半夜的涼意透進被子裡，她一個人翻來覆去。重陽是該闔家團聚、登高賞菊的日子，她卻只能自己一個人過。

她其實很少在詞裡直接寫思念這兩個字，更多時候是藉著一爐香、一場酒、一朵菊花繞著說，可是懂的人一讀就懂，那些繞來繞去的意象背後，全是同一件事——他又不在家了。

她索性起來，搬張小桌子到東邊的籬笆邊，倒了杯酒，學陶淵明採菊東籬下的樣子坐著。酒喝下去，暗暗的菊花香飄進了她的袖子裡，可是這點雅興填不滿一整天的空落。西風把簾子捲起來的時候，她低頭看了看自己的手腕，這陣子茶飯不思，人瘦了一大圈，比籬邊那些纖細的黃菊還要瘦。

她把這些寫成一首詞，託人送去給趙明誠：

薄霧濃雲愁永晝，瑞腦消金獸，佳節又重陽，玉枕紗廚，半夜涼初透。東籬把酒黃昏後，有暗香盈袖，莫道不銷魂，簾卷西風，人比黃花瘦。

相傳趙明誠收到之後很不服氣，自己的太太寫得比自己好，閉門謝客三天，不吃不睡，一口氣填了五十闋詞，故意把妻子這首也混進去，拿給朋友陸德夫看，問他哪幾句寫得最好。陸德夫看了半天，指出其中三句，正是李清照那句莫道不銷魂，簾卷西風，人比黃花瘦。這個故事出自後人的筆記，真假難以考證，但足夠說明一件事：在這場夫妻之間的較量裡，誰更愛誰不重要，誰寫得更好，答案從來沒有懸念過。

這個故事後來被反覆傳頌，未必每個字都經得起考證，可是它精準地捕捉到了這對夫妻之間一種罕見的平等——趙明誠不是輸不起的人，他心甘情願地認了這一場敗仗，還讓後人幾百年都在替他們津津樂道。

後人讀這個故事，未必真的相信趙明誠會服氣到閉門三日不吃不睡，可是這個流傳下來的版本，恰好說明了世人心裡怎麼看待這對夫妻——才華這件事，跟誰是丈夫、誰是妻子，從來沒有關係。`
  },

  // id=453 南宋 李清照 〈聲聲慢-尋尋覓覓〉rating=5
  // 詩眼：曾經寫過的雁、寫過的菊，多年後又出現在眼前，卻已經沒有人再幫她摘、再幫她寄信，自己的詩句回頭反噬自己
  // 隱藏連接：此詞相傳寫於趙明誠病逝、她歷經再嫁又離異的官司之後，獨居江南期間；詞中的雁與黃花，呼應她早年〈一剪梅〉〈醉花陰〉裡的同一批意象
  453: {
    title: "聲聲慢-尋尋覓覓",
    author: "李清照",
    summary: "這首詞裡飛過的雁、堆積的菊，都是她年輕時寫過的老朋友，只是這次牠們回來，不是報喜，是討債。",
    story: `跟你說我朋友易安晚年一個黃昏。她守著窗子，天怎麼都黑不下來，又怎麼都亮不起來，她已經不知道自己這樣坐了多久。窗外飛過一群大雁，她抬頭看了一眼，忽然愣住：這些雁，好像是她從前認識的那些。

靖康之難後，她跟趙明誠帶著半輩子收藏的金石拓片、古籍字畫一路南逃，大半在戰亂中散失、被搶、被燒。趙明誠後來在建康病重去世，她一個人拖著剩下的幾箱書畫繼續往南走。後來她曾經再嫁，遇人不淑，對方看重的是她手裡還剩的一點東西，她受了虐待，豁出去告官求離異，在那個年代，女人告丈夫，就算贏了官司，自己也要先擔一陣子牢獄之苦。她贏了，也代價不小。晚年她一個人住在江南，身邊沒有子女，故人零落，金石書畫十不存一。

她年輕時寫的那些詞句，本來是拿來撒嬌、拿來炫耀夫妻情深的，如今卻一句一句變成了刺，扎進她自己心裡。她大概沒想過，有一天自己會被自己年輕時的文字反過來提醒，提醒她曾經擁有過什麼。

那天黃昏，她想找點事做，翻遍屋子，喝了兩三杯淡酒，風卻一陣比一陣急，酒根本擋不住冷。窗外的雁群飛過，她想起自己年輕時寫過雲中誰寄錦書來，雁字回時，那時候她盼雁，是盼它帶來丈夫的信。如今雁還在飛，信卻再也不會有人寄了，這些雁只是她舊時相識，認得，卻再無用處。地上的菊花開了又謝，堆得滿地，她想起自己年輕時寫過人比黃花瘦，那時候是嬌嗔，是撒嬌給丈夫看的瘦。如今菊花堆積，憔悴凋零，卻沒有人會再心疼地說一句該摘了。

她提筆寫下：

尋尋覓覓，冷冷清清，悽悽慘慘戚戚。乍暖還寒時候，最難將息。三杯兩盞淡酒，怎敵他，晚來風急。雁過也，正傷心，卻是舊時相識。滿地黃花堆積，憔悴損，如今有誰堪摘。守著窗兒，獨自怎生得黑。梧桐更兼細雨，到黃昏，點點滴滴。這次第，怎一個愁字了得。

雨滴在梧桐葉上，一點一點，敲到天黑。她年輕時寫過的雁、寫過的菊，這一刻全部飛回來找她算帳，原來最狠的重逢，不是遇見舊情人，是遇見當年那個還相信會有人寄信、會有人摘花的自己。`
  },

  // id=454 南宋 李清照 〈武陵春·春晚〉rating=5
  // 詩眼：她想去看春天，卻怕自己的悲傷連一艘船都裝不下，把抽象的哀愁秤出重量
  // 隱藏連接：此詞相傳作於李清照避難金華期間，雙溪為當地真實風景名勝，丈夫趙明誠已病逝數年，這是她晚年顛沛中一次少見卻失敗的振作嘗試
  454: {
    title: "武陵春·春晚",
    author: "李清照",
    summary: "她難得動念想去划船看春天，轉念卻算了一筆帳，自己這些年積攢的哀愁，恐怕連一整條雙溪都裝不下。",
    story: `跟你說我朋友易安在金華的一個春天傍晚。外頭風總算停了，空氣裡還飄著塵土混著落花的味道，她坐在鏡子前，頭髮亂了一整天也懶得梳，這是她這陣子每天的樣子。

那些年她一路往南逃，從山東到江南，再到浙江金華，身邊能帶的東西越來越少，趙明誠已經病逝好幾年，她一個人拖著剩下的幾件行李，寄居在別人的屋簷下。物是人非事事休，她住的地方風景還是那個風景，人卻全變了，能開口說的事一件都不剩，話還沒出口，眼淚先流下來。

她試著想像划船出去的畫面，想像自己坐在船頭，兩岸桃花夾道，可是越想像，越覺得那個畫面裡缺了一個人，缺了那個以前總愛跟她辯論金石年代、爭到面紅耳赤還捨不得認輸的人。

金華當地有個叫雙溪的地方，春天景色出名地好，附近的人都愛去划船賞景。有人跟她提起，雙溪那邊春天還很美，她聽了，心裡動了一下，難得地，她想，要不要去划划船，看看風景，讓自己好過一點。這是她這陣子少數幾次，還想為自己做點什麼的念頭。

可是那個念頭剛冒出來，馬上又被自己壓下去。她想像自己坐上那艘小船，船身那麼小，雙溪的水那麼淺，她這幾年攢下來的悲傷，喪夫、逃難、文物盡失、被人欺負又離異的官司，壓在心裡那麼重，萬一那艘小船承受不住，連人帶愁一起沉下去怎麼辦。

她把這個念頭寫成一首詞：

風住塵香花已盡，日晚倦梳頭，物是人非事事休，欲語淚先流。聞說雙溪春尚好，也擬泛輕舟，只恐雙溪舴艋舟，載不動許多愁。

最後她沒有去划船。鏡子前的頭髮還是亂的，窗外的風已經停了，可她心裡那場風雨從來沒停過，她把悲傷秤出了重量，秤出來的結果是，連一整條雙溪都載不動。

這首詞後來被許多研究者拿來跟她早年寫過的閒愁相比，年輕時的愁是可以被排解的，划划船、喝喝酒就能沖淡幾分；晚年這種愁，卻是連一整條河的水都沖不淡、連一艘船都載不動的重量，這中間隔著的，是她整個下半生的顛沛流離。

她這輩子收藏過的金石字畫，散的散、燒的燒，能留住的東西越來越少，最後留得住的，反而是這幾句寫在紙上、任誰都搶不走的文字，重量算不清，卻是她晚年僅剩、真正屬於自己的東西。`
  },

  // id=462 南宋 劉過 〈唐多令‧蘆葉滿汀洲〉rating=5
  // 詩眼：二十年後故地重遊，發現買得回桂花美酒，買不回當年相信明天會更好的自己
  // 隱藏連接：劉過一生屢試不第、布衣終老江湖，與辛棄疾、陸游交好，這首詞正寫於二十年後重遊武昌南樓、故人凋零的酒席上
  462: {
    title: "唐多令‧蘆葉滿汀洲",
    author: "劉過",
    summary: "他繫船的繩子在柳樹下繞了兩圈還沒繫穩——不是手笨，是他忽然想起二十年前，自己也曾在這個渡口繫過船。",
    story: `蘆葉滿汀洲的那個秋天，一艘小船靠岸，繫船的繩子在柳樹下繞了兩圈，卻遲遲沒繫穩。撐船的人蹲在岸邊，手上的動作停了下來——他忽然想起，二十年前他也曾在這個渡口繫過船。

這人是劉過，字改之，江西泰和人，江湖上都叫他龍洲道人。他一輩子沒有功名，考了六次鄉試、四次省試都不中，史書上只淡淡寫他不遇兩個字，就把大半生的辛苦帶過去了。他沒有靠山，也沒有俸祿，靠的是一身詩詞才氣，在江湖上跟辛棄疾、陸游這些人稱兄道弟——他們敬重他，卻也幫不了他一個正經官職。

二十年前他第一次來武昌南樓，那時候他還年輕，落第歸來路過此地，心裡想的是下一次科考。南樓底下是黃鶴磯頭，江水日夜東流，他那時候還相信，只要再等一次機會，一切都會不一樣。

這二十年裡他不是沒有機會轉運。有人賞識他的文采，舉薦他去考詞科，想給他謀一條正經出路，他去考了，還是沒中。江湖上的名氣再大，換不來一紙功名，他心裡其實比誰都清楚這一點，只是不肯在朋友面前露出來。

二十年後他重回這裡，已經是嘉泰年間，身邊多了滿頭風霜。安遠樓上有人設宴，一個姓黃的歌姬向他討詞，他望著眼前的黃鶴磯頭、望著舊江山，忽然開口問同席的人，故人曾到否。沒有人答得上來。那些他二十年前認識的朋友，有的已經不在了，舊江山還是那片江山，他心裡卻裝滿了新的愁。

眼看又是中秋，桂花將開，有人提議買桂花、載一船酒，像年輕時那樣痛快遊一場。劉過笑了笑，提筆寫下：欲買桂花同載酒，終不似，少年遊。

酒可以買，桂花也可以買，能載得動的東西太多了，唯獨買不回那個二十歲、還相信下一次會考中的自己。

寫完這幾句，他起身走到船邊。船還沒繫穩，繩子在柳枝下輕輕晃著，跟二十年前一模一樣。只是這一次，他沒有再想著要去哪裡考試了。他知道，有些渡口，這輩子只能來兩次——一次帶著希望，一次帶著看透了的溫柔。

後來的讀者未必都經歷過科舉的挫敗，可是誰沒有過那種故地重遊、發現自己再也回不去當年心境的時刻。劉過用一句終不似少年遊，替所有這樣的重逢先寫好了結語。`
  },

  // id=466 中唐 劉禹錫 〈陋室銘〉rating=5
  // 詩眼：被知縣一路刁難搬進半間小屋的人，用一篇銘文證明自己的格局比誰的房子都大
  // 隱藏連接：柳宗元819年病逝前把遺稿與孩子託付給劉禹錫，他此後一直替宗元編訂文集、照應遺孤
  466: {
    title: "陋室銘",
    author: "劉禹錫",
    summary: "知縣三番兩次把他的住處越換越小，最後只剩一間半——他沒吵沒鬧，只是找石匠刻了幾句話，立在門前。",
    story: `跟你說我朋友夢得在和州當刺史時吃的一個悶虧，還有他怎麼把這個悶虧，寫成了一篇千古名文。

那是他被貶去和州的頭一年。按規矩，刺史該住在城南的官舍，三間屋子，還算過得去。可是當地有個知縣，看他是個被貶下來的罪臣，存心刁難。先把他從城南三間屋，遷到城北，面對著江水，屋子小了一半。夢得倒也不惱，在門上題了兩句，面對大江觀白帆，身在和州思爭辯，他還挺自得其樂。

知縣一看，他不但沒被氣走，還有心情寫對聯，更加不痛快了，又把他的住處往德勝河邊挪，換成一間更小的屋子。最後索性給了他城中一間半的小屋，窄得只放得下一床一桌一椅。

他在和州待了不算長的一段時間，卻寫下不少後來流傳的句子。他自己心裡明白，這些為難他的人，不出幾年就會被朝廷調走、被人遺忘，而他留在牆上的這幾句話，未必真能傳多遠，但至少此刻，他不想讓對方看見自己被逼到牆角的樣子。

夢得這個人，你要知道他這輩子經歷過什麼。當年他跟柳宗元、王叔文一起搞永貞革新，失敗後被貶了二十三年，輾轉朗州、連州、夔州、和州，一路被整。宗元815年被貶到柳州，819年就病死在那裡，臨終前把遺稿和孩子都託付給他。夢得後來一直記掛著這件事，替宗元編訂文集，幫忙照應他留下的孩子——一個被貶到半間屋子的人，心裡裝的事情，比誰的房子都大。

面對這一間半間的小屋，他沒有抗爭，也沒有低頭。他找了塊石頭，請人刻字，立在門前：山不在高，有仙則名。水不在深，有龍則靈。斯是陋室，惟吾德馨。苔痕上階綠，草色入簾青。談笑有鴻儒，往來無白丁。可以調素琴，閱金經。無絲竹之亂耳，無案牘之勞形。南陽諸葛廬，西蜀子雲亭。孔子云，何陋之有。

知縣想用一間屋子矮化他，他用一篇銘文告訴全天下：你可以決定我住多大的房子，決定不了我心裡裝著多大的世界。這塊石碑後來立了一千兩百年，陋室早就不在了，這幾句話卻還在。

一千兩百年後，和州城早已幾經改建，當年那間一間半的小屋連遺址都找不太到了，可是陋室銘這篇短短的文章，卻還在無數學生的課本裡，年復一年地被抄寫、被背誦。`
  },

  // id=1 秦 詩經 〈蒹葭〉rating=4
  // 詩眼：你知道那個人就在那裡，可是不管逆流順流怎麼追，都走不到她面前
  // 隱藏連接：無（先秦民歌無個人作者，故事圍繞《詩經》采詩制度與秦風傳唱背景鋪展）
  1: {
    title: "蒹葭",
    author: "詩經",
    summary: "這首三千年前的秦地情歌，主角追了三章，逆流也追、順流也追，卻始終沒讓後人知道他到底追到了沒有。",
    story: `深秋的清晨，渭水邊上一片蘆葦，葉子還是青蒼色，葉尖上凝著白霜。有個年輕人沿著岸邊來回走，嘴裡反覆念著同一句話，所謂伊人，在水一方。旁邊採詩的小吏聽見了，停下腳步，把這句話記進了竹簡。

這是三千年前的事了，沒有人知道那個年輕人叫什麼名字，連他追的到底是心上人、還是傳說中的賢士，後人都吵了兩千多年沒有結論。相傳周代設有采詩之官，每年秋天到民間走訪，把百姓隨口唱出來的歌謠記錄下來，送回朝廷，讓天子藉此知道民間的悲喜——這首詩相傳就是這樣，被一個沒有留下名字的官員，從秦地的河邊帶回朝堂的。

那個年輕人在做什麼呢？他逆著水流往上走，想去找那個人，可是路又險又長，怎麼走都走不到。他又順著水流往下走，遠遠望見那個身影，好像就站在水中央，可是等他靠近，人又不見了。白露從結霜，到還沒乾，到快要收盡，他就這樣一次次地在河邊來回，一次比一次走得艱難，一次比一次望得更遠，卻始終沒能真正走到那個人面前。

後人考證，秦地民風本就慷慨任俠，這首詩卻寫得格外纏綿婉轉，跟後來人印象中大氣硬朗的秦風不太一樣，也讓不少學者懷疑，或許這根本不是寫給某個具體的人，而是借一場求而不得的追尋，寄託某種更抽象的嚮往。

三章疊唱，幾乎是同一句話反覆說：蒹葭蒼蒼，白露為霜。所謂伊人，在水一方。溯洄從之，道阻且長。溯游從之，宛在水中央。只換了幾個字，蒼蒼換成萋萋、采采，水一方換成水之湄、水之涘，像同一個人在同一條河邊，一遍又一遍地告訴自己再試一次。

沒有人知道結局。他到底有沒有見到那個人，詩裡沒寫，或許連他自己都不知道答案。這首沒有署名的秦地歌謠，後來被收進《詩經》，兩千多年後，每一個曾經拚命追過一個人、一個夢、一個怎麼都構不到的目標的人，讀到這幾句，都會突然明白，原來這種求而不得的心情，三千年前的人，早就替你唱過了。

後世讀這首詩的人，未必都在追一個具體的人，有人讀出的是求道的艱難，有人讀出的是理想的可望不可即，三千年前那個站在渭水邊的身影，就這樣被一代一代的讀者，讀成了自己心裡那個怎麼都追不到的東西。`
  },

  // id=4 盛唐 李白 〈三五七言-秋風詞〉rating=4
  // 詩眼：相思重到讓人願意用沒認識過去換一個不痛的自己
  // 隱藏連接：此詩是否真為李白親筆歷來存疑，故事誠實處理為相傳之作
  4: {
    title: "三五七言-秋風詞",
    author: "李白",
    summary: "這首人人以為是李白寫的秋夜情詩，其實連是不是他親筆，學者到現在都還沒吵出結論。",
    story: `跟你說一件關於我朋友太白的公案，到現在都還沒吵出結論——這首後來人人都說是他寫的秋風詞，其實連是不是他親筆，學者們都還在爭。最早的版本很晚才出現，有人說是他真跡流傳散佚後被人拾回，也有人懷疑是後代文人假托他的名字寫的。可是幾百年來，大家還是願意相信，這幾句話就該是太白寫的，因為它寫的那種被相思困住的感覺，實在太像他會有的口氣。

姑且就依著相傳的說法，說說那個秋夜可能發生的事。相傳那年太白人在江南，秋風剛起，月色很亮，落葉聚了又散，一隻寒鴉棲在枝頭，被風一吹又驚飛起來。他想起一個很久沒見的人，是誰，詩裡沒說清楚，後人猜是故友，也有人猜是早年分開的人。太白這輩子四處漂泊，家裡人等過他很多次，朋友也等過他很多次，他比誰都清楚等待是什麼滋味。

相思這種東西，他寫得很直白：相思相見知何日，此時此夜難為情。他甚至沒有拐彎抹角，直接把這股情緒攤開來講，入我相思門，知我相思苦，長相思兮長相憶，短相思兮無窮極。長的相思也好，短的相思也好，反正都沒有盡頭。

太白傳世詩作裡，真偽存疑的不止這一首，古代詩文集抄錄流傳的過程本就容易摻雜、附會，尤其是他這種名氣太大的詩人，後人寫了好句子，也樂得掛在他名下增色。

寫到這裡，他忽然停筆，想起這股苦，忍不住寫下最後兩句：早知如此絆人心，何如當初莫相識。

這句話後來被無數失戀的人反覆引用，可是仔細想，這不是後悔認識對方，是相思太重，重到讓人願意用沒認識過去換一個不痛的自己。至於這幾句話到底是不是太白親手寫下的秋夜，一千多年後的我們，大概永遠沒辦法確定了，但這份相思的重量，倒是騙不了人。

不過即使真偽存疑，這幾句話流傳的力道絲毫沒有減弱，早知如此絆人心、何如當初莫相識，至今仍是描述相思之苦最直白也最動人的句子，這份重量，比作者是誰更禁得起時間考驗。

有意思的是，這種真偽難辨的處境，本身就有點像相思這件事——你分不清那份牽掛究竟源自對方，還是源自自己心裡投射出來的想像，可不管源頭是哪裡，痛起來都一樣真實。`
  },

  // id=7 盛唐 張九齡 〈感遇四首之一〉rating=4
  // 詩眼：看穿危險卻沒人聽的人，用一隻孤鴻寫給得意者一封沒有署名的警告信
  // 隱藏連接：張九齡曾當面警告唐玄宗安祿山面有反相，玄宗未採納，二十年後安史之亂應驗
  7: {
    title: "感遇四首之一",
    author: "張九齡",
    summary: "他早就跟皇帝說過那個胡人面有反相，皇帝沒聽——二十年後漁陽鼙鼓響起，才有人想起這首詩。",
    story: `跟你說我朋友子壽被貶到荊州那幾年，寫給朝堂上那些得意的人的一封警告信，沒有署名，也沒有人敢說是寫給誰。

張九齡，字子壽，廣東韶州曲江人，是開元盛世最後一位敢直言的宰相。他當宰相的時候，唐玄宗身邊已經有不少人開始鑽營拍馬，其中一個是後來當上范陽節度使的安祿山。相傳安祿山有次打了敗仗被押到長安，子壽當場就跟玄宗說，這個人面有反相，將來必成禍患，建議依軍法處死。玄宗沒聽，還放了安祿山一馬。二十年後安史之亂爆發，天下大亂，朝中不少人才想起子壽當年這句話。

可惜那時候沒人聽他的。開元二十四年，他被李林甫聯合其他人排擠，罷了相位，貶為荊州長史。他從權力中心一路南下，離開了他經營大半輩子的朝堂，只帶著一肚子沒說完的話。

子壽被貶之後，朝中局勢也並未因此好轉，李林甫獨攬大權長達十幾年，排除異己、堵塞言路，把整個開元盛世的最後一點清明也一併帶走了，直到安史之亂爆發，才有人真正意識到，當年那個提出警告的人有多麼難得。

在荊州，他看著天上飛過的一隻孤鴻，忽然覺得那就是自己，不敢靠近池塘邊的水潭，怕人多眼雜惹禍上身。他又看見枝頭兩隻翠鳥，築巢築在最高最珍貴的樹梢上，得意得很。他心裡想，這兩隻鳥難道不怕獵人的金彈丸嗎？爬得越高、穿得越漂亮，招來的嫉妒和殺機也越大。

他提筆寫下：孤鴻海上來，池潢不敢顧。側見雙翠鳥，巢在三珠樹。矯矯珍木巔，得無金丸懼。美服患人指，高明逼神惡。今我遊冥冥，弋者何所慕。

他把自己寫成一隻飛向遠方、飛到獵人射程外的孤鴻，你們儘管在枝頭得意，我飛得夠遠夠高，你們的弓箭夠不著我，也不必再羨慕我了。這封沒有收件人的信，寫給朝堂上所有正在得意的人，可惜沒有人回信，也沒有人聽懂，直到二十年後，漁陽鼙鼓真的響起。

多年後，杜甫在安史之亂的烽火裡寫下感時花濺淚，後人讀到子壽這首孤鴻詩，才驚覺盛唐由盛轉衰的種子，其實早在開元末年，就已經被這位敢言的宰相看穿，只是沒有人願意在歌舞昇平裡聽進一句逆耳的警告。`
  },

  // id=8 盛唐 張九齡 〈感遇四首之二〉rating=4
  // 詩眼：蘭桂開得好從來不是為了等誰來摘，是它自己活該這樣開
  // 隱藏連接：張九齡家鄉韶州曲江自古盛產蘭桂，被貶後把家鄉草木種進荊州院子裡
  8: {
    title: "感遇四首之二",
    author: "張九齡",
    summary: "他被貶到荊州後種了一院子蘭花，卻從來沒摘下來送過人——因為他終於想通，蘭花開得好，不是為了等誰來摘。",
    story: `跟你說我朋友子壽被貶到荊州之後，種在院子裡的一叢蘭花，還有他為什麼從來不摘下來送人。

子壽的老家在廣東韶州曲江，那一帶山裡自古就長蘭花，春天蘭葉茂密，秋天桂花皎潔飄香，是他從小看慣的景色。被貶到荊州長史之後，他把這些家鄉常見的花草種進了自己的院子，與其說是排遣，不如說是他想留住一點還沒被朝堂搞壞的東西。

他這輩子最風光的時候，是開元名相，跟玄宗提過無數次治國的建議，連安祿山該不該殺，他都看得比誰都準。可惜後來李林甫得勢，他被排擠出朝廷，昔日跟他稱兄道弟的同僚，很多轉頭就倒向了新貴。他終於明白，朝堂上的賞識，跟山裡的蘭花完全是兩回事，蘭花開得好，不是為了等誰來摘，是它自己活該這樣開。

後來的讀書人讀到這首詩，常常拿它跟屈原的香草美人傳統相提並論，同樣是用草木寫心志，屈原寫的是不見容於世的悲憤，子壽寫的卻是想通之後的坦然，這份坦然，來得比屈原晚了近千年，卻一樣動人。

一個春天的早晨，他蹲在院子裡看那叢蘭草，葉子在晨光裡繁茂地伸展著，旁邊的桂樹到了秋天會結出皎潔的花。他忽然想通一件事，草木從來沒有想過要討好誰，它們按著自己的時節生長、開花，欣欣向榮，自成一段好時光，誰知道有沒有人在山林裡聞著香氣走近，對它產生了好感，那也只是剛好而已。

他提筆寫下：蘭葉春葳蕤，桂華秋皎潔。欣欣此生意，自爾為佳節。誰知林棲者，聞風坐相悅。草木有本心，何求美人折。

寫完這幾句，他把筆放下，望著那叢蘭花，不摘，也不必等誰來摘。他被貶出了長安，失去了皇帝的賞識，可是他終於活得像院子裡這叢蘭草，不必看誰的臉色開花。多年後他病逝在返鄉途中，再也沒能回到朝堂，但這院子裡的蘭桂，幾百年後還在每個讀到這幾句的人心裡，安安靜靜地開著。

子壽晚年病逝於返鄉途中，沒能再回到朝堂，可他留下的這幾句詩，卻讓後世無數失意的讀書人得到安慰，原來被辜負不代表要跟著枯萎，草木自有本心，人也可以。

後人讀到蘭葉春葳蕤這幾句，常常拿來跟他早年在朝堂上意氣風發的文字對照，同一個人，得意時寫的是治國方略，失意時寫的卻是院子裡一叢蘭花，境界不但沒有變小，反而更加開闊。`
  },

  // id=13 盛唐 李白 〈春思〉rating=4
  // 詩眼：两地的季节要花时间才追得上彼此，连想他的心情都要慢半拍
  // 隱藏連接：李白自己常年漂泊在外，家中妻兒也曾長期等他，或許正因如此才寫得出這份委屈
  13: {
    title: "春思",
    author: "李白",
    summary: "她替遠方的丈夫算了一筆時差——他那邊的草才剛冒芽，她這邊的桑葉已經垂低了枝條，連想家都要慢半拍才追得上。",
    story: `跟你說我朋友太白替一個長安女子寫的一封信，收信人是她遠在燕地當兵的丈夫，但這封信，她大概寄不出去。

太白這輩子最擅長替別人說話，尤其是那些等在家裡、說不出口的女人。這一次他寫的是個秦地女子，住在長安附近，丈夫被徵去了燕地，也就是現在的河北北方，離家幾千里。

他替她算了一筆帳：燕地天氣冷，春天來得晚，現在那邊的草才剛剛冒出頭，細得像碧綠的絲線。可是秦地暖，她家院子裡的桑樹葉子已經長得茂密，壓得枝條都低垂下來了。同樣是春天，燕草才發芽，秦桑已經茂盛，丈夫那邊的季節，永遠比她這邊晚了一截，連想家的心情都要慢半拍才追得上。

這類代言體的閨怨詩，太白寫過不止一首，有人說他天性浪漫，寫這些反倒比寫自己的心事更投入。可仔細想想，一個常年在外漂泊、把妻兒丟在家裡的人，要寫出這種等待的滋味，未必全靠想像，多半也摻著幾分將心比心的愧疚。

太白替她說出那句最實在的話：當君懷歸日，是妾斷腸時。等你終於想起要回家的那一天，我可能早就已經斷腸斷過好幾回了，因為她天天都在想，他卻要等到某一天才會想。

太白自己這輩子也四處漂泊，家裡的妻兒常常一等就是好幾個月、好幾年。他大概比誰都清楚，被留在家裡的人是什麼心情，所以春風吹進門的時候，那女子才會又氣又酸地問：春風不相識，何事入羅幃？連春風都是不相干的陌生人，卻大剌剌地闖進她的帳幔裡，好像在提醒她，真正該回來的那個人還沒到。

信終究是沒有寄出去的，燕地那麼遠，信使未必能平安送到。可是這幾句話留了下來，一千多年後，每一個算過兩地天氣時差、算過對方是不是也在想自己的人，讀到這首詩都會愣一下，原來這種心情，連季節都跟不上。

一千多年後，異地戀、長期分居兩地的人讀到這首詩，依然會心一笑，原來這種算時差、算節氣、算對方到底想不想自己的心情，從古至今，換了朝代，也沒有換過滋味。

太白寫這種代言體閨怨詩時，用詞總是特別具體，燕草秦桑、羅幃春風，沒有一句空泛的感嘆，卻比任何直接喊苦的句子都更讓人揪心，這大概就是他厲害的地方，把抽象的思念，過秤成了看得見摸得著的畫面。`
  },

  // id=20 盛唐 李白 〈長干行〉rating=4
  // 詩眼：青梅竹馬這個甜蜜成語的下半段，其實是一個女人天天數門前青苔有多深的漫長等待
  // 隱藏連接：李白出身商人家庭、自己也常年在外行商遠遊，對商人夫妻聚少離多的辛酸有切身觀察
  20: {
    title: "長干行",
    author: "李白",
    summary: "青梅竹馬這個詞你以為是甜蜜開頭，其實這首詩寫的是甜蜜之後，一個女人天天數著門前青苔有多深的漫長等待。",
    story: `你現在說起青梅竹馬這個詞，大概只會想到兩個小孩感情好。可是這個成語最早出現的地方，寫的其實不是甜蜜，是一個女人數著門前的青苔，算丈夫還有多久回家的故事。

這個故事，是我朋友太白替長干里一個商人的妻子寫的。長干里是金陵城外的一片街坊，住的多半是往來做生意的商人家庭。她說，自己頭髮才剛剛蓋過額頭的時候，常在門前折花玩；隔壁那個男孩騎著竹竿當馬跑過來，繞著井欄轉圈，拿青梅丟她鬧著玩，兩個孩子一起長大，從沒起過什麼嫌隙。

十四歲那年，她嫁給了那個男孩，成了他的妻子。她說自己害羞得從沒展開過眉頭，低著頭對著牆壁，喊她一千次都不肯回一次頭。到了十五歲，她才漸漸放開，願意跟他說，就算死了也要跟他化成同一捧塵土，像古時候那個守信到寧可抱著橋柱淹死也不肯離開的人一樣，她從沒想過自己有一天會變成那種天天爬上望夫臺張望的女人。

後人讀到這首詩，往往只記得前半段兩小無猜的甜蜜，忘了它其實是一封寫給遠行商人的家書，字裡行間全是等待的重量。長干里的商人妻子不是特例,那個年代往來於江河之上做生意的男人,身後幾乎都有一個這樣數著日子的女人。

十六歲那年，丈夫要出遠門經商，得走過瞿塘峽那段最凶險的水路，灩澦堆的暗礁五月水漲時根本碰不得，兩岸猿猴叫得淒厲。他走了以後，她天天看著門口，他當初出門走過的腳印，一個一個都長出了青苔。青苔太深，她掃都掃不動；秋風一起，落葉就落得比往年更早。到了八月，連蝴蝶都成雙成對地飛進西邊的園子，牠們有伴，她卻沒有，看著這景象，她心裡難過，覺得自己的容顏都要在等待裡憔悴老去。

她託人帶信給遠方的丈夫：你不管什麼時候要下三巴回來，提前寫封信告訴我，我一定去接你，不管多遠，哪怕要走到長風沙那麼遠的地方，我都去。

李白後來寫的這首長干行，也讓青梅竹馬這個原本只是隨口描寫的畫面，變成了流傳千古的成語，只是絕大多數後人用這個詞的時候，早就忘了它背後那個天天數著青苔深淺的女人。

這首詩後來被無數後人反覆引用改寫，青梅竹馬四個字流傳到今天，早已跟原詩的情境脫了鉤，變成形容感情基礎深厚的泛稱，很少有人記得，它最初描寫的，其實是一段從嬉戲玩鬧走向漫長等待的完整人生。`
  },

  // id=21 盛唐 李白 〈妾薄命〉rating=4
  // 詩眼：曾經被許諾一座金屋的女人，最後連君王的車駕都不肯往她那個方向多拐一步
  // 隱藏連接：有人認為李白寫這些失寵宮怨詩時，也在寫自己曾受玄宗恩寵、後又被賜金放還的心境
  21: {
    title: "妾薄命",
    author: "李白",
    summary: "金屋藏嬌大家都記得前半段的甜話，卻很少人記得，那個被藏進金屋的女人後來連君王的車駕都等不到。",
    story: `跟你說一個成語背後，被大家漏掉的下半段，金屋藏嬌，大家都只記得前面那句甜話，沒人記得後面那個女人，是怎麼被放生的。

這個女人叫陳阿嬌，是漢武帝劉徹的表姐，也是他第一任皇后。相傳劉徹小時候有人逗他，問他長大想娶誰，他指著阿嬌說，若能娶到阿嬌，要蓋一座金屋子把她藏起來。這句話後來變成了金屋藏嬌這個成語，聽起來像天底下最甜的情話。

她真的等到了那座金屋。劉徹即位以後立她為后，她一度尊貴到什麼程度，史書形容她打個噴嚏、咳一聲，旁人都覺得像珠玉從天上灑下來，隨風化成寶物，那是何等的恩寵。可是她沒有生下皇子，又善妒，劉徹身邊漸漸多了別的女人，她的恩寵一點一點被掏空，最後因為巫蠱之事被廢，打入長門宮，終生沒能再見劉徹一面，長門宮離劉徹常去的地方，說遠不遠，可他連車駕都不肯往那個方向多拐一步。

太白這輩子寫過不少借古諷今的宮怨詩，阿嬌不是唯一的主角，還有班婕妤、王昭君這些同樣曾經風光、後來失勢的女子，一次次被他寫進詩裡。有人說，他寫得越多，越像是在反覆咀嚼自己那段從雲端跌落的日子，寫別人，其實也是寫自己不肯輕易說出口的那份不甘。

太白寫這首詩的時候，借的就是阿嬌這段舊事。他自己也曾經風光過，當年他被召進長安，唐玄宗愛惜他的才氣，親自降階迎接，命他當翰林待詔，伴駕寫詩，何等榮耀。可是好景不長，朝中權貴容不下他的狂放，沒幾年他就被賜金放還，體面地請出了長安。有人說，太白後來寫這些宮怨詩，寫的不只是那些失寵的女人，也是他自己，曾經被捧到最高處，轉眼就被放棄，恩寵和才氣一樣，說斷就斷。

他寫下：寵極愛還歇，妒深情卻疏。長門一步地，不肯暫迴車。雨落下來不會再飛回天上，水潑出去也收不回來，君王的情意和她的心意，終究各自往東往西流走了。昔日開得最好的芙蓉花，如今成了斷了根的草，他在末尾寫下一句誰都聽得懂的提醒：以色事他人，能得幾時好。

太白晚年回想起自己在長安翰林院的那幾年，或許也會想起阿嬌這樣的人物，恩寵來得快，去得也快，能留下來的，終究只有那句以色事他人、能得幾時好，替所有曾經風光一時又被辜負的人，留了個清醒的註腳。`
  },

  // id=23 盛唐 杜甫 〈贈衛八處士〉rating=4
  // 詩眼：重逢當晚就知道明天要再分開，於是拼命喝酒拼命留住這一夜，因為誰都清楚可能是這輩子最後一次
  // 隱藏連接：無（衛八處士生平不見於正史，僅存此詩；隱藏連接改以安史之亂時代背景服務詩眼）
  23: {
    title: "贈衛八處士",
    author: "杜甫",
    summary: "二十年沒見的老友半夜冒雨去剪了一把春韭菜招待他——這頓飯兩人喝了十杯酒都沒醉，因為誰都知道，明天分開後可能這輩子都見不到了。",
    story: `跟你說我朋友子美二十年後，在一個下雨的晚上，重新見到一個老朋友的事。那一夜他們喝了十杯酒，誰都沒醉，可是誰心裡都清楚，這頓飯吃完，可能這輩子就再也見不到了。

那是安史之亂還沒平息的年月，長安剛剛收復，子美因為替房琯說話得罪了肅宗，被貶為華州司功參軍。他從洛陽要回華州任上，路過一個地方，順道去看少年時候的朋友衛八處士。這人姓衛，排行第八，是個隱居不出仕的處士，正史上找不到更多關於他的記載，只有這首詩替他留了名字。

二十年沒見了。子美推門進去的時候，兩人幾乎認不出彼此，鬢角都已經花白。子美心裡先是驚，接著是喜，兩種情緒撞在一起，絞得胸口發熱。他想起臨走前打聽過的那些老朋友，將近一半人已經不在了，聽到消息的時候他忍不住驚呼出聲。人生在世，能重逢一次有多難，他們就像參星和商星，一個在東一個在西，這輩子幾乎不會同時出現在天上，可是今晚，他們居然真的坐在同一盞燈燭底下。

衛八這個人，正史上再也找不到第二筆記載，如果不是子美這首詩，他大概早就跟那個年代裡千千萬萬普通人一樣，連名字都不會留下來。反倒是這頓臨時張羅的酒菜、這一夜沒有醉的十杯酒，替他在一千多年後，保住了一個具體的模樣。

當年分別的時候，衛八還沒成親，如今孩子已經一個接一個地站成一排，懂事地向父親的老友行禮，問他從哪裡來。問答還沒說完，衛八已經招呼孩子去張羅酒菜，外頭下著雨，他還是冒雨去剪了新長出來的春韭菜，配上剛燜好的黃米飯，拿出家裡最好的東西招待這個二十年沒見的朋友。衛八端起酒杯說，難得見一面，今晚不醉不歸，一連敬了十杯，兩人竟然一杯都沒醉，醉的不是酒，是這份沒有變淡的老交情。

子美心裡明白，明天一早他就要繼續上路，兩人又要被高山阻隔，天下事這麼亂，誰也說不準下次是什麼時候。這一夜的燈燭、這一碗春韭黃粱，他們都知道，可能就是這輩子最後一次。

多年後子美自己顛沛流離、貧病交加，寫過更多動亂與離散的詩篇，可這個雨夜剪韭菜、十杯酒都不醉的畫面，始終是他詩集裡少見的一點暖色，提醒著後人，亂世裡最珍貴的，往往就是這樣一頓來不及道別的晚飯。`
  },

  // id=27 盛唐 王維 〈送別〉rating=4
  // 詩眼：朋友心灰意冷要歸隱，他不追問原因也不出言安慰，只給一句由著你去的尊重
  // 隱藏連接：王維自己曾因黃獅子舞事件被貶濟州，深知仕途失意的滋味，因此格外能體會朋友的心情
  27: {
    title: "送別",
    author: "王維",
    summary: "朋友說了三個字不得意就沉默了，王維沒有追問也沒有安慰，只遞上一杯酒，說你去吧，白雲什麼時候看都在。",
    story: `跟你說我朋友摩詰的一個黃昏。輞川的莊子外面，山色一點一點暗下來，他扶著一個朋友的馬韁，看那人翻身下馬。那人風塵僕僕，臉上帶著長途趕路的疲憊，眼神卻比疲憊更沉。兩人誰也沒先開口，先各自倒了一杯酒，酒杯碰在一起，也沒發出什麼聲音。摩詰後來想起這件事，總覺得最奇怪的地方是，他問了一句你要去哪裡，對方隔了好一會兒才低聲說了三個字，好像連自己都還沒想清楚要往哪裡去，也還沒想清楚該怎麼跟人開口。

那年摩詰自己剛從濟州回來沒幾年。早幾年他在朝中做太樂丞，因為屬下一場舞獅子的表演出了差錯，那舞本來只能在御前演，底下的人卻拿去別處演了，他被連坐貶到濟州當司倉參軍，一貶就是四五年。那幾年他遠離長安，管的是糧倉裡的雜事，跟他原本擅長的詩畫音律一點關係都沒有，日子過得又悶又慢，寫過的詩沒人看，彈過的琴沒人聽。回到長安後，他把輞川那塊地買下來，種竹子，養鹿，半官半隱地過日子。他懂那種被大道拋下的滋味，比誰都懂。

眼前這位朋友，史書沒留下名字，只知道他跟摩詰交情不淺。他在長安考了又考，謀了又謀，這次是真的心灰意冷了，聽說這回主考官連他的卷子都沒仔細看完。他說，不得意，三個字，說完就沒有下文。摩詰也沒追問哪裡不得意，是考試落第，是官場排擠，還是家裡出了事，這些都不重要了，重要的是，對方已經決定要回南山腳下，找個地方把自己藏起來，這輩子大概都不打算再回長安了。

摩詰把酒杯遞過去，又倒滿一杯。他心裡其實有一百句話想說，勸他別灰心，勸他再等等，朝廷總有用人的時候，這些場面話他年輕時也曾經聽別人這樣勸過自己。可是這些話他自己聽過太多次，每一句都是安慰，沒有一句真的有用。他索性什麼都不勸，只說，你去吧，以後不用再托人問我這邊的消息了。南山那邊的白雲，什麼時候去看都在，不會有一天沒有。

那人翻身上馬，往南山的方向去，身影在暮色裡越走越小。摩詰站在原地，看馬蹄踏起的塵土落定。他後來寫下這六句話：下馬飲君酒，問君何所之。君言不得意，歸臥南山陲。但去莫復聞，白雲無盡時。

沒有一句安慰的話，卻是他能給的最大的尊重，不追問，不阻攔，由著一個人去過自己選的日子。多年後摩詰自己也常常在輞川的雲影裡坐一整個下午，才明白當年那句話，其實也是說給自己聽的。南山那片雲從沒少過一天，人卻各自散了，只是散得各有各的方向。`
  },

  // id=52 中唐 孟郊 〈烈女操〉rating=4
  // 詩眼：一首用來替年輕寡婦擋下逼婚壓力的委託詩，井水的平靜底下藏著外人看不透的心思
  // 隱藏連接：相傳孟郊應婆家之託替一位守寡婦人寫詩申請旌表，藉此保護她不被娘家逼迫改嫁
  52: {
    title: "烈女操",
    author: "孟郊",
    summary: "婆家想替年輕寡婦申請旌表護她安穩留下，孟郊見她低頭做針線只淡淡說了句不想，便提筆寫下這首詩替她擋下逼嫁的壓力。",
    story: `跟你說我朋友東野接的一樁委託。那年他還沒考上進士，窮困潦倒地待在洛陽附近一處親戚家借住，有戶人家托人找上門，捎了些薄禮，想請他替家裡新近守寡的媳婦寫一首詩，好呈報官府請求旌表。東野起初有點猶豫，這種替人歌功頌德的詩他寫得不多，怕自己筆力不夠，配不上人家的心意。

他見過那個年輕婦人一面，才二十出頭，男人得急病死了不到半年，兩人成親也不過三四年光景，孩子都還沒來得及生。婆家有意留她，日子過得雖然清苦，倒也待她不薄，可是她娘家那邊卻不斷有人上門，說她還年輕，人又長得端正，不如趁早改嫁，彩禮都已經有人在打聽了，話裡話外都是替她著想，聽著卻讓人不舒服。婦人自己什麼都沒說，只是每天早上照樣去院子裡的井邊打水，傍晚照樣坐在那兩棵並排種下的梧桐樹下做針線，那是她跟丈夫成親那年一起栽的，如今男人不在了，樹卻一年年又高了一截，枝葉都快連成一片了。

東野問她，家裡人這樣勸，你自己是怎麼想的。她說，不想。就這兩個字，說完低頭繼續縫衣服，指尖被針扎了一下也沒吭聲，好像多說一句都是浪費力氣。東野看她低頭的樣子，忽然想到院子裡那口井，水面看起來一絲波紋都沒有，可是井底深不見底，誰也不知道底下藏著什麼樣的心思，是委屈，是不甘，還是真心認定了這條路，外人猜不透。

婆家的意思是，如果能有一首像樣的詩，證明這婦人心志堅定，呈報上去或許能免了她被逼改嫁的麻煩，官府那邊的旌表也能讓她往後在夫家立得住腳，不至於被人指指點點趕出門，往後在村裡抬頭做人也有個憑據。東野想，這大概是他這支筆眼下能替她做的，唯一實在的事。

他提筆寫下：梧桐相待老，鴛鴦會雙死。貞婦貴殉夫，捨生亦如此。波瀾誓不起，妾心井中水。

寫完他把詩稿交給來人，交代一定要送到官府去，還特意叮囑對方把她娘家那頭的說法也一併寫清楚。他知道這首詩用的是很老派的說法，聽起來像是在歌頌一種犧牲，可他心裡想的其實是那口井，那婦人的心思，外人看不透，也沒人能替她決定。這首詩能為她擋掉多少閒言閒語，東野不知道，但至少那天以後，再沒聽說她娘家上門提過改嫁的事，院子裡那兩棵梧桐樹，依舊一年年往上長，長到後來，竟真的連成了一片綠蔭。`
  },

  // id=54 中唐 白居易 〈無題〉rating=4
  // 詩眼：病弱老人捨不得放手，卻更明白把兩個年輕女子綁在自己身邊並不公平
  // 隱藏連接：樊素、小蠻是白居易晚年真實的家伎，史料記載他晚年因病放歸樊素，此詩即寫於他們相伴的歲月裡
  54: {
    title: "無題",
    author: "白居易",
    summary: "白居易晚年中風臥病，卻誇讚身邊歌伎舞伎的美貌，幾年後他真的放樊素自行擇人而去，兌現了詩裡沒說出口的成全。",
    story: `跟你說我朋友樂天晚年最捨不得的兩個人。一個叫樊素，唱曲子唱得整個洛陽城都知道；一個叫小蠻，跳舞跳得腰肢軟得像柳枝一樣。樂天常常跟人誇，我家那兩位，一個嘴像櫻桃，一個腰像楊柳，別處找不著，客人來訪，他總要留人多坐一會兒，就為了讓她們露一手。

這話聽著像老人炫耀家產，其實藏著一段他自己都不太願意細想的心事。樂天晚年身體垮得快，先是腳氣病反覆發作，走幾步路就氣喘，後來又中風，半邊身子有陣子動不了，話也說不利索，連握筆寫字都得歇好幾次。他請的醫生換了好幾個，家裡人都替他捏把汗，夜裡常有人守在房外聽動靜。那幾年他大多數時間只能坐在洛陽履道里的宅子裡，靠樊素的歌聲和小蠻的舞打發長夜，聽著聽著，有時竟也能忘記自己身上的病痛。

他心裡清楚，自己這身子骨撐不了太久了。樊素才二十出頭，小蠻更小，兩人跟著他這些年，學的是歌舞，指望的也是能一直在他身邊有口飯吃、有個依靠。可是萬一哪天他人不在了呢，一個歌伎、一個舞伎，沒了主家，能去哪裡，是被家裡人轉賣，還是流落到別處酒樓賣藝，樂天想到這裡，常常半夜睡不著，聽著隔壁房裡兩人低低的說話聲，心裡越發過意不去。

有天晚上小蠻跳完一支舞，額頭上還帶著細汗，樊素接著唱了一曲，兩人站在燭光底下等他點評。樂天看著她們，忽然覺得心口很悶，他捨不得放，可他也知道，把兩個正當年紀的女孩子綁在一個隨時可能撒手的病人身邊，不是疼愛，是自私。他提筆寫下：櫻桃樊素口，楊柳小蠻腰。

寫完這兩句，他盯著紙看了很久，底下還有兩句沒寫完的話，是關於他自己越來越不中用的身子，寫了又劃掉，劃掉又重寫，始終沒能寫得像前兩句那樣痛快。後來又過了幾年，樂天真的把家裡養的那匹老馬賣了，把樊素也放了，讓她自己選人家去。他在詩裡誇她們誇得毫不吝惜，捨不得的話卻一句也沒說出口，可是他做到了。那兩句留了下來，倒成了後人記得樊素和小蠻最鮮活的樣子，不是誰的附屬品，是曾經被一個病弱老人，用全部的溫柔認真誇過的兩個名字。`
  },

  // id=59 盛唐 李白 〈金陵酒肆留別〉rating=4
  // 詩眼：一群年輕人誰也不肯先開口說再見，只好拿江水的長度來比賽誰更捨不得
  // 隱藏連接：李白初離蜀地遠遊，在金陵結交一批仰慕他的富家子弟，這場酒局是他們送別的真實場景
  59: {
    title: "金陵酒肆留別",
    author: "李白",
    summary: "一群金陵少年不肯先開口說再見，只顧著一杯接一杯地敬酒，最後起鬨拿東流江水比一比離情的長短。",
    story: `跟你說我朋友太白在金陵一家小酒館度過的一個下午。那年他二十五歲，仗劍離開四川老家沒多久，一路沿江東下，遊歷天下，身上盤纏不算多，卻交了一堆朋友。金陵城裡他認識了一批新朋友，都是些家境不錯、成天無所事事的富家子弟，聽說城裡新來了個會寫詩又會喝酒的年輕人，出口成章、談吐又豪爽，一個個都湊過來想結識，沒幾天工夫就混得熟稔。

那天他要離開金陵，往下一個地方去，行囊早早收拾好放在客棧櫃檯。消息傳開，這群子弟一大早就在城西那家熟悉的酒館占了位子等他，桌上的酒菜都點好了，就等他一到便開席。店裡賣酒的吳地女子正忙著壓新釀的酒，酒香混著窗外飄進來的柳絮味，滿屋子都是，風一吹，柳絮還飄進了酒杯裡。她一邊篩酒一邊招呼客人嘗新酒，聲音又脆又亮，誰也沒想到今天這桌客人要辦的是場送別。

太白坐下沒多久，酒杯就沒停過。金陵子弟一個個輪番敬酒，誰也不提你什麼時候走這種話，好像只要沒人問出口，這場酒局就能一直喝下去。太白自己心裡也犯嘀咕，是該起身告辭了，天色再晚些恐怕就趕不上船，可是看著滿座的熱情，一張張年輕又真誠的臉，他又坐了下來，再乾一杯。想走又不想走，這杯就先乾了再說。

酒喝到後來，有人起鬨說，別老這麼悶頭喝了，不如比一比，你這一走，心裡的離情跟門外那條秦淮河一路往東流的水，到底誰更長。旁邊立刻有人接話，說這比法不公平，水流沒有盡頭，人的情意哪有那麼長。太白聽著，覺得這問法有意思，比河水更貼切的，大概就是拿一整條江來秤一場離別的重量。他借著酒意脫口念出：請君試問東流水，別意與之誰短長。

一群人聽了都不說話了，只顧著碰杯，誰也沒再追問答案是什麼，好像答案根本不重要，重要的是這句話說出來了。有人紅了眼眶，趕緊低頭喝酒遮掩過去，怕被人看見自己這點捨不得。太白後來離開金陵，沿江繼續往東，見過的酒館換了一家又一家，可是那年輕人湊在一起、誰也不肯先說再見的下午，他記了很久，連那吳姬篩酒的手勢都還記得清清楚楚。多年後他名滿天下，走到哪裡都有人設宴款待，排場一次比一次大，可是再沒人敢那樣隨隨便便拉著他喝一整個下午的酒了。`
  },

  // id=64 盛唐 李白 〈長相思二首之一〉rating=4
  // 詩眼：被禮貌地請出長安的人，分不清自己想念的到底是一個人還是整座回不去的城
  // 隱藏連接：相傳此詩寫於李白被玄宗賜金放還離開長安之後，思念對象或指具體之人、或暗喻長安宮廷，學界至今未有定論
  64: {
    title: "長相思二首之一",
    author: "李白",
    summary: "被玄宗客氣賜金放還的李白，半夜被井邊蟲鳴吵醒，望著月亮才發現自己也分不清想念的是一個人還是整座回不去的城。",
    story: `跟你說我朋友太白離開長安後，有整整一段日子，晚上總睡不著。那是天寶三載，他被玄宗賜了一筆錢，客客氣氣地打發出宮，面子上說得好聽，說他不是廟堂裡的人才，其實誰都聽得出來，這是被排擠出去的委婉說法。他在翰林院待了不到三年，天天陪在皇帝身邊，醉裡寫詩，醒來論政，宮裡的宴席、朝堂的爭論、同僚遞來的眼色，他都親身經歷過，那是他這輩子離權力核心最近的一段日子，也是他後來想起來最五味雜陳的一段日子。

離開長安那年秋天，他借宿在外地一間客棧裡，屋子小，牆壁薄，隔壁的說話聲都聽得一清二楚。半夜被井邊的蟋蟀叫聲吵醒，那聲音又細又淒，像是在數著夜有多長，一聲接一聲，怎麼捂著耳朵都甩不掉。他摸了摸身下的竹席，才發覺上頭已經結了層薄霜，涼得像鐵，身子縮成一團也暖不起來。屋裡一盞燈搖搖晃晃，亮不起來，他的心思也跟著那點微光，忽明忽暗，理不清楚。

他起身捲起窗簾，想看看月亮，望了半天卻只是白白嘆了口氣，月亮倒是圓的，可他怎麼看都看不出個所以然。他心裡想的那個人，說是美人也好，說是長安城本身也好，對他來說其實是同一回事，那是他曾經觸手可及、如今卻隔在雲霧那頭的一切。天這麼高，水這麼遠，他就算作夢，魂魄也飛不過去，飛到半路就會被那道看不見的關山攔住，怎麼繞都繞不過去。

他坐回桌前，把這些翻來覆去的心事寫成一首詩，開頭四個字就是：長相思，在長安。中間寫到絡緯秋啼金井闌，微霜淒淒簟色寒，孤燈不明思欲絕，卷帷望月空長歎，美人如花隔雲端。寫到最後，他擱下筆，窗外的蟋蟀還在叫，一聲一聲，像是在替他數著這夜還有多長，他索性也不睡了，就這麼坐到天光微微發白。

後來他又漂泊了十幾年，長安待過，離開過，再也沒能真正回去，連那座他曾經天天出入的宮門，後來也只能遠遠望著。這首詩裡他沒點名到底想的是誰，是人是城，千百年後讀的人各自猜測，有人說是懷人，有人說是懷君，可是那種明明什麼都看得見、卻怎麼也碰不到的滋味，誰讀了都懂，這大概就是他當初沒說清楚、卻也不必說清楚的原因。`
  },

  // id=67 盛唐 李白 〈行路難三首之二〉rating=4
  // 詩眼：曾被皇帝親自接進宮門的人，如今又要拖著衣袍在別人家門口低聲下氣求引薦
  // 隱藏連接：相傳玄宗曾降輦相迎並親手為李白調羹，此後不過兩三年他就被賜金放還，這份反差是他晚年屢屢求人引薦時最深的刺痛
  67: {
    title: "行路難三首之二",
    author: "李白",
    summary: "曾被玄宗降輦相迎、傳說還親手調羹款待的李白，離開長安後又得拖著衣袍在權貴門前求人引薦，這份反差讓他夜裡輾轉難眠。",
    story: `跟你說我朋友太白離開長安以後，有一次在路上想起自己這些年到底是怎麼過的。長安城裡那些五陵少年，鬥雞走狗，拿梨子栗子當賭注，成天在市井裡混日子，太白年輕時瞧不上這種活法，覺得胸中自有丘壑，不屑跟這些人為伍，可是離了長安，他發現自己過得比那些人還不如，至少人家鬥雞走狗還有本錢輸，還有家世能撐腰，他連跟人賭一把的資格都沒有。

他想起自己早年到處投書求人引薦的日子。最落魄的時候，他站在某位權貴家的大門外面，拖著袍子的下擺，一等就是大半天，門房愛理不理，遞進去的名帖石沉大海，他心裡那股滋味，說不出口。他寫過信給荊州刺史韓朝宗，信裡那句生不用封萬戶侯，但願一識韓荊州，說出來風光，寫的時候其實是把自尊心放到最低，求一個素不相識的人賞臉見一面，換來的答覆卻總是含糊其辭。

更諷刺的是，他不是沒風光過。天寶元年他被召進京，玄宗親自下輦相迎，甚至傳說皇帝還親手替他調羹嘗味，滿朝文武看在眼裡，那是多少讀書人一輩子求不到的殊榮。可是不過兩三年，酒醉時得罪了得寵的人，他就被禮貌地請出了宮門。從天子身邊的座上客，到如今又得低聲下氣求人引薦，這中間的落差，他一個人夜裡想起來，常常氣得睡不著，翻來覆去到天亮。

他想起淮陰市井那些人曾經當眾羞辱過韓信，讓他從胯下爬過去；想起賈誼滿腹才學，還是被朝中那些老臣容不下，最後鬱鬱而終。這些人後來有的證明了自己，有的沒能等到那一天，可是要熬過中間那段被人看輕的日子，談何容易。他又想起更早以前，燕昭王築黃金臺招賢，對郭隗那樣的人以禮相待，樂毅、劇辛這些人才，感恩戴德，把一身本事都掏出來報效燕國，君臣之間那份互相成全的情義，讀史書讀到都讓人動容。那樣的君王，那樣的時代，如今上哪裡找。

他提筆寫下：昭王白骨縈蔓草，誰人更掃黃金臺。寫完擲筆長歎，行路難，歸去來，這條路走不通，不如暫且退一步。他不知道往後還有沒有人記得，他也曾經是那個被皇帝親手調羹款待過的人，那份風光終究只是他人生裡短短兩三年的插曲。`
  },

  // id=71 盛唐 杜甫 〈丹青引贈曹霸將軍〉rating=4
  // 詩眼：曾讓御馬在畫紙上活過來的宮廷畫師，如今淪落街頭替陌生人畫像換幾個銅板
  // 隱藏連接：杜甫與曹霸確實在安史之亂後的成都相遇，此詩即為兩人在困頓歲月裡重逢所作
  71: {
    title: "丹青引贈曹霸將軍",
    author: "杜甫",
    summary: "杜甫在成都街角認出一位替路人畫像維生的佝僂老人，竟是當年讓御馬在畫紙上與真馬相互對望的宮廷畫師曹霸。",
    story: `跟你說我朋友子美在成都街頭遇見的一位老人。那年安史之亂還沒平息，子美自己也是拖家帶口逃難到蜀地，一家人擠在草堂裡，日子過得緊巴巴，寫詩換不來米糧。有天他在街角看見一個佝僂著背的老畫師，擺個小攤子，替過路人畫像，一張畫像收幾個銅板，勉強糊口，攤子旁邊還擺著幾支用禿了的舊筆。子美多看了兩眼，那人抬頭的一瞬間，他才認出來，這人是曹霸將軍。

這個名字子美太熟悉了。曹霸出身曹魏皇族後裔，開元年間是宮廷第一畫手，常常被召進南熏殿，替凌煙閣裡那些功臣畫像重新上色，那些畫像年代久了，顏色都褪了，是曹霸一筆一筆讓它們活過來。玄宗最喜愛的御馬玉花驄，滿朝畫工誰都畫不像，一連換了好幾位，畫出來的總是差著那麼一口氣，直到有一天那匹馬真的被牽到丹墀之下，曹霸盯著看了很久，屏氣凝神，才落筆，一畫出來，滿殿的人都愣住了，真馬站在台階前，畫馬掛在絹上，兩邊竟像在互相對望，分不出哪個才是真的。玄宗當場笑著賞了金子，旁邊侍馬的官員看得又是羨慕又是失落，一時說不出話來。

子美記得曹霸還收過一個學生叫韓幹，後來也畫馬出了名，宮裡照樣召他進去作畫，可曹霸私底下總說，韓幹畫馬只畫得出肉，畫不出骨頭，少了那股精神氣。這話聽著像挑剔，其實是曹霸自己心裡那把尺，他要的不是像，是活。

如今曹霸淪落到在市井裡替陌生人畫像維生，畫的不再是御馬功臣，是趕路的商販、擺攤的小販，隨便什麼人給幾個錢都畫。子美站在攤子前看他，想起這人當年見過至尊天子含笑賞金的風光，如今卻要看那些窮眼睛看人的臉色，連個像樣的畫室都沒有。子美自己這幾年也窮怕了，一家老小的溫飽都成問題，兩個人在亂世裡遇見，誰也沒比誰過得好。他提筆寫下這首長詩，把曹霸的來歷、他親眼見過的那場丹墀對馬的盛景都寫了進去，寫到最後嘆道：但看古來盛名下，終日坎壈纏其身。

寫完他把詩稿念給曹霸聽。老人沒說話，只是繼續低頭畫下一張陌生人的臉，手還是穩的，眼神卻淡了許多。子美知道，這世上大概沒有比這更公平也更殘忍的事了，名氣越大，命運欠你的帳，好像也就跟著越大。`
  },

  // id=95 中唐 韓愈 〈八月十五夜贈張功曹〉rating=4
  // 詩眼：大赦天下卻被地方官壓下名單，兩個死裡逃生的人只能對著好月色喝悶酒
  // 隱藏連接：韓愈與張署確實同時遭貶、同時獲赦又同時被地方官延誤調任，兩人一同北歸途中共度了這個中秋夜
  95: {
    title: "八月十五夜贈張功曹",
    author: "韓愈",
    summary: "韓愈與張署同時遇赦，滿心以為能回京，卻被地方官壓下名單，只調去更卑微的職位，中秋夜兩人對月喝著悶酒各自唱了一曲。",
    story: `跟你說我朋友退之跟張十一署共度的一個中秋夜。那年是永貞元年剛過，新皇帝登基，天下大赦。退之三年前因為一篇替百姓喊冤的奏狀，得罪了當權的人，被貶去陽山當縣令；張署也在附近的臨武同時遭貶，兩人官職不同，處境卻一模一樣，這幾年書信往來，靠著彼此打氣才熬過來。這回大赦的消息傳來，兩人都以為苦日子終於到頭了，特意約好一路同行，北上的路上兩人有說有笑，滿心以為能回到長安，重新在朝堂上有個位置。

走到半路，兩人先在郴州停下來，等候朝廷正式的改調文書，這一等就是好些天，公文遲遲不到，兩人心裡都有點不安，卻誰也不肯先把這份不安說出口。那天正好是八月十五，天上一絲雲都沒有，清風把月光吹得一波一波地淌，江邊沙灘平整，水面靜得沒有一點聲響，連蟲鳴都稀稀落落的。退之叫人備了一壺酒，兩人對坐，他跟張署說，你先唱一曲吧。

張署開口唱了，聲音又酸又苦，沒唱完，眼淚先掉了下來。他唱的是這幾年的遭遇，洞庭湖連著天，九疑山高聳，湖裡蛟龍出沒，山裡猩猩野鼯哀號；他們九死一生才到貶所，躲在住處像逃犯一樣過日子，下床怕踩到蛇，吃東西怕中毒，終日被瘴氣濕熱熏著。好不容易前些日子城前擂起大鼓，傳來新皇登基、大赦天下的消息，赦書一天能傳一萬里，連死罪都赦免了，流放在外的人一個個被召回，可是州府明明已經申報了他們的名字，上頭的官員卻把名單壓了下來，最後只把他們調去荊蠻之地當個判司，這種卑微的小官連提都不值得一提，還隨時可能被人拿板子打。同一批遭貶的人，大多都已經走在回京的路上了，只有他們兩個，離朝廷越來越遠。

退之聽著，沒等唱完就哭出聲來。他接過話說，你先別唱了，聽我唱。他說，一年裡頭今晚的月亮最亮最圓，人這一生是命裡註定，不是誰能爭來的，有酒不喝，辜負這月色，又能怎麼樣呢。

那晚兩人喝到很晚，誰也沒再提升遷的事，只是一杯接一杯地陪著彼此，把心裡那點不甘一點一點喝淡。後來張署真的死在了那個判司任上，沒能等到回京城的那一天，退之聽到消息時，正好又是接近中秋的季節。退之後來官越做越大，回過長安，也離開過長安，可是每年中秋，他大概都會想起郴州江邊那一夜，兩個人的酒，兩個人的歌，和那句一年明月今宵多。`
  },

  // id=97 中唐 韓愈 〈石鼓歌〉rating=4
  // 詩眼：一個人只靠一首詩想搬動三千年前的十塊石頭，眼看著它一年年被牧童敲火磨角
  // 隱藏連接：韓愈確實在元和年間上書建議將石鼓遷入太學保存，史載未獲採納，石鼓最終歷經輾轉在後世妥善保存
  97: {
    title: "石鼓歌",
    author: "韓愈",
    summary: "韓愈看著鳳翔石鼓的拓本震動不已，多方奔走想把它遷入太學保存卻無人理會，千年後這十面石鼓終究被好好收藏進了故宮博物院。",
    story: `跟你說我朋友退之遇上十塊石頭的故事。元和初年他剛被任命做國子博士，一天他的朋友張籍帶著一份拓本來找他，說鳳翔那邊山野裡有十面石鼓，上面刻著古字，勸退之替它寫一首詩宣揚宣揚。退之接過拓本一看，整個人都愣住了。

那些字他認得沒幾個，可是那份氣勢他看得出來。相傳那是周宣王當年平定四方之後，在岐陽狩獵閱兵，把功績刻在鼓形的石頭上，要告訴後世萬代，當年跟隨他的臣子個個都是第一等的人才，刻工也是精挑細選出來的。石鼓在山裡擱了近兩千年，淋過雨，曬過太陽，燒過野火，居然沒有毀壞，拓本上的每一筆都還在，幾乎沒有缺損。退之盯著那些筆畫看，覺得字體不像隸書也不像蝌蚪文，有的筆畫被歲月磨斷了一角，斷得乾淨，像快刀砍斷了一條蛟龍；有的地方筆勢盤旋，像鸞鳥飛翔、眾仙降臨，像珊瑚碧樹的枝椏交纏在一起，像金繩鐵索緊緊鎖住，又像古鼎在水裡跳躍、蛟龍騎著織布的梭子游走。他心裡想，詩經的編者當年怎麼就沒把這個收進去，孔子周遊列國怎麼偏偏沒走到秦地來看一眼，他們揀選的是星星月亮，漏掉的卻是這輪太陽。

退之覺得自己生得太晚，對著拓本掉下淚來。他託在鳳翔一帶當差的老朋友幫忙，測量地形，把石鼓從土裡起出來，自己齋戒沐浴，去跟國子監祭酒稟報這件事，說這樣的至寶不該擱在荒郊野外，幾匹駱駝就能馱進京城，獻進太廟供起來，比古代那些傳世寶鼎還要珍貴百倍；若能留在太學裡，學生們天天能對著研究切磋，連洛陽鴻都門觀經的盛況大概都會被比下去。

可是朝中那些做慣了官的老臣，誰也不肯為這件事出力，一年年拖著。退之六年來屢屢望著鳳翔的方向白白嘆氣，眼看著放牛的孩子拿石鼓敲火，牛在上頭磨角，誰都不當一回事。他忍不住想，寫字寫得討喜的王羲之，幾張字帖都還能換到白鵝，這十面刻著三代真跡的石鼓，怎麼就沒人肯出力保住。

他寫到最後，擱下筆嘆道，石鼓之歌止於此，嗚呼吾意其蹉跎。退之終究沒能在自己手上把石鼓搬進太廟。可是千年之後，這十面石鼓真的被好好地收了起來，如今就安安穩穩擺在故宮博物院裡，證明他當年那份急切，一點都沒有錯。`
  },

  // id=103 中唐 白居易 〈賣炭翁〉rating=4
  // 詩眼：老人凍得發抖，心裡卻盼著天再冷一點，而這份卑微的指望最後還是被宮市的人奪走
  // 隱藏連接：白居易任左拾遺時聽聞的真實宮市掠奪案例，可能是這首詩的直接原型
  103: {
    title: "賣炭翁",
    author: "白居易",
    summary: "賣炭老人凍得直哆嗦，心裡卻盼著天更冷一點好讓炭賣個好價錢，這份卑微的指望，最後被宮裡強徵的人一車拖走。",
    story: `跟你說我朋友樂天在長安城南門外見過的一個老人。那時他做左拾遺，職責就是替皇帝聽民間的苦處，寫成詩上呈，盼著能傳到御前，這是他自己給自己定下的規矩，寫詩不是為了風花雪月，是為了讓上頭的人聽見下頭的聲音。那陣子他聽衙門裡的人私下議論一樁事，有個農夫進城賣柴，半路被宮裡派出來的人攔下，說是奉旨採買，不由分說把柴搬走，只塞給他幾尺絹布，他一開口爭辯，還挨了打，事後連個說理的地方都沒有。樂天聽完，坐了很久沒說話，手邊的公文都擱在一旁沒動。

他想起自己在街市上也見過類似的老人。那老人整天在終南山裡砍柴燒炭，一張臉被煙火熏得又黑又灰，兩鬢花白，十根手指頭全是炭黑色，指甲縫裡都洗不乾淨。他靠賣炭換來的錢，不過是圖身上有件衣服穿，嘴裡有口飯吃，日子過得緊巴巴。他身上那件衣裳單薄得很，冷風一吹就直哆嗦，可是他心裡卻盼著天再冷一點，天越冷，城裡人越需要炭取暖，炭才能賣上好價錢。這種拿自己的凍餓去換一點指望的心思，樂天想起來就覺得堵得慌，那不是不懂得疼惜自己，是窮到連疼惜自己的餘地都沒有。

昨夜城外下了一尺深的雪，那老人天不亮就趕著牛車出門，車輪輾過結冰的路轍，一路顛簸進城，牛蹄子在雪地裡打滑。牛累了，人也餓了，日頭已經升得老高，他才在集市南門外的泥地裡歇下腳，想著今天這批炭火，總算能換點過冬的錢，給自己添件厚衣裳，也給家裡添點米糧。

就在這時候，兩個人騎馬過來了，一個穿黃衣是宮裡的太監，一個穿白衫是他的隨從。那人手裡拿著文書，嘴上說是奉旨採辦，不由分說，掉轉車頭，吆喝著把牛牽往北邊去。一車炭，足足一千多斤，就這樣被拉走了，老人心裡再捨不得，也不敢多說一句，只能眼睜睜看著牛車遠去。最後那太監把半匹紅紗和一丈綾隨手繫在牛頭上，算是付了帳，連頭都沒回。

樂天把這件事寫成詩，題目叫賣炭翁，自己在旁邊注了一句苦宮市也。他知道自己人微言輕，這首詩未必真能傳到皇帝耳朵裡，可他還是把那老人凍得發抖卻盼著更冷的心思，一字一句寫了下來，賣炭得錢何所營，身上衣裳口中食。他想，至少讓寫詩的人記得，這世上有人的指望，卑微到只是盼著自己再更冷一點，而這一點指望，最後也沒能留住。`
  },

  // id=110 盛唐 李白 〈贈孟浩然〉rating=4
  // 詩眼：太白這輩子很少真心佩服誰，這一次他是真的認輸了
  // 隱藏連接：兩人在襄陽鹿門山一帶結為忘年之交，日後太白在黃鶴樓送別孟浩然（送孟浩然之廣陵）
  110: {
    title: "贈孟浩然",
    author: "李白",
    summary: "這個狂到自稱天子呼來不上船的人，一輩子沒服過幾個人，孟浩然是少數的例外。",
    story: `跟你說我朋友太白剛出蜀那幾年的一件事。他在安陸落腳沒多久，襄陽城裡人人都在講一個名字，孟夫子。傳言講得神，這人年輕時候把送到手邊的官帽官服往外推，一頭栽進鹿門山，從紅顏到白首，只跟松樹雲霧作伴。太白還沒見過本人，已經把這個人當成偶像。這件事很反常，因為太白這輩子很少真心服誰，往後幾十年他寫詩罵過權貴、頂撞過皇帝身邊的紅人，唯獨對這個素未謀面的隱士，先低了頭。

他託人引薦，終於在鹿門山下見到孟浩然本人。那年孟浩然已經四十出頭，太白才二十七八歲，兩人差了十二歲，卻一見如故。孟浩然帶他喝酒，喝到月亮升到最高，兩人醉得七倒八歪，這叫中聖，喝清酒喝到微醺，是古人的雅稱。孟浩然又帶他在山裡到處走，看見一叢好花就蹲下來看半天，完全不管日頭已經西斜，公事俗務統統擺一邊。太白起初以為這是灑脫，看久了才發現，這人是真心把仕途放下了，不是裝出來的姿態。他自己心裡那團想建功立業的火，跟孟浩然身上這種雲淡風輕，形成一種奇怪的對照。太白後來也考過功名、求過人引薦，四處碰壁的滋味他嘗過不少，可是眼前這個人，好像壓根不在意這些起落，一心只顧著山、水、酒、花。他忍不住開始揣摩，這個人到底是怎麼做到的，一個活人怎麼能把功名利祿看得這麼輕。

有一晚兩人又喝到微醺，鹿門山的月色照進窗子，太白坐在燈下，把這些日子看到的畫面一句一句寫下來，吾愛孟夫子，風流天下聞。紅顏棄軒冕，白首臥松雲。醉月頻中聖，迷花不事君。高山安可仰，徒此挹清芬。寫完最後一句，他放下筆愣了一下，這輩子沒對幾個人說過這種仰望的話，連他自己都覺得有點意外。

這份仰慕後來持續了很多年，兩人的交情也沒有因為太白後來聲名越來越大而變淡。幾年後，太白在黃鶴樓上送孟浩然坐船去揚州，站在江邊看那艘船從清楚看到只剩一個影子，捨不得移開視線。鹿門山那晚喝的酒早就醒了，但那份高山仰止的心情，太白一直沒有放下過。他後來成了誰都不太服氣的謫仙人，可提起孟夫子三個字，語氣始終跟年輕時一樣恭敬。`
  },

  // id=111 盛唐 李白 〈渡荊門送別〉rating=4
  // 詩眼：一個人明明在歌頌壯闊天地，最後一句卻悄悄把鏡頭轉回了家鄉
  // 隱藏連接：這是李白出蜀遠遊、此後三十餘年再未歸鄉的那趟旅程的起點
  111: {
    title: "渡荊門送別",
    author: "李白",
    summary: "二十五歲的李白第一次離開四川，滿口都是天地壯闊，最後一句卻洩了底，他捨不得的是那條從家鄉流出來的江水。",
    story: `跟你說我朋友太白第一次離開四川的那個下午。船行到荊門外，兩岸的山忽然往後退開，江水一下子鋪展成一片大荒野。他站在船頭，才二十五歲，這是他生平第一次走出蜀地，身後那些他從小看到大的山，正在眼前一寸一寸消失。

他這一路是仗劍出來的，帶著劍、帶著詩稿，還有滿肚子建功立業的念頭，準備去長安闖一番天下。臨行前他跟家人告別，說得雲淡風輕，好像只是出去遊歷一陣子就會回來，行李也收拾得很輕便，沒帶多少家鄉的東西。蜀道難走，外面的人都知道，李白自己後來也寫過蜀道之難難於上青天，可他是那種寧可信自己也不肯信別人講的險，執意要親眼去看看蜀地以外的天地長什麼樣子。船過三峽，江水一路湍急，兩岸的山峰高得遮天，猿聲在山谷裡此起彼落，走了幾天幾夜，到了荊門，忽然天地開闊起來，山不見了，江水流進看不到邊的原野。這種開闊，是他在蜀地山谷裡從沒見過的，他站在船頭，一時不知道該高興還是該心慌。

夜裡他抬頭看月亮，倒映在江面上，像一面天上飛下來的鏡子；白天雲氣蒸騰，在江上結成海市蜃樓一樣的樓閣，一層疊著一層，看得他移不開眼。他一路往荊楚而去，心裡明明裝滿了壯闊天地，寫詩也句句都在誇這片新天地有多開闊，可是船行到夜深人靜，四下只剩水聲，他還是忍不住回頭想家。那條江水是從蜀地一路流出來的，等於是故鄉的水陪著他走完這一程。他提筆寫下，仍憐故鄉水，萬里送行舟。表面上寫的是江水送他遠行，其實他自己心裡明白，是他捨不得那片水。

這一走，太白再也沒有回過蜀地。往後三十幾年，他在江南、在長安、在無數個異鄉的旅店醒來，偶爾會想起荊門外那個瞬間，山一寸一寸退開，江水鋪展成大荒，而他站在船頭，第一次意識到自己真的離家了，只是那時候的他，還以為自己還會回去，還以為蜀地的山水隨時等著他回頭。

後人讀這首詩，常常只注意前面幾句寫得多麼壯闊，山隨平野盡、江入大荒流，氣象開闊得不像一個二十五歲年輕人第一次出遠門該有的筆力。可是真正讓人記住這首詩的，反而是最後那句悄悄轉回故鄉的溫柔，壯闊是他寫給世界看的，眷戀才是他寫給自己看的。`
  },

  // id=113 盛唐 李白 〈聽蜀僧濬彈琴〉rating=4
  // 詩眼：離家幾十年後，在陌生人的琴聲裡聽見了故鄉的山
  // 隱藏連接：琴名綠綺相傳源自同樣是蜀人的司馬相如，借一段童年就聽過的老家傳說
  113: {
    title: "聽蜀僧濬彈琴",
    author: "李白",
    summary: "一個和尚抱著一張借了老鄉名字的琴，替離家幾十年的李白，把峨眉山的風一口氣送到了眼前。",
    story: `跟你說我朋友太白中年以後，在異鄉聽到一段讓他愣住的琴聲。彈琴的是個從峨眉山下來的和尚，法名濬，懷裡抱著一張琴，風塵僕僕，看樣子是剛下山不久。太白瞄了一眼那張琴的名字，心裡咯噔一下，是綠綺。

綠綺這個名字，蜀地人從小聽到大。相傳漢代那位同樣是蜀人的司馬相如，就是彈著一張叫綠綺的琴，把卓文君從屋裡引出來私奔的，這段故事在蜀地流傳了幾百年，家家戶戶的老人都能講上一段。太白小時候在蜀地長大，這個故事聽過不知道多少遍，那時候他還沒想過，自己有一天會離家萬里，在異鄉聽見同一個名字。眼前這個和尚未必真拿著司馬相如那張琴，但光是這個名字，就已經把太白拉回了老家，連帶峨眉山的雲、山腳下的溪水，都好像一併跟著回來了。

濬和尚不多話，對著太白一揮手，開始彈。琴聲一下，太白覺得自己好像同時聽見了萬壑松濤，那種聲音只有蜀地深山裡才有，是他離家幾十年前，天天聽到的聲音，如今隔著千山萬水，竟然在一個陌生人的指尖底下重新響起。他閉上眼，恍惚間又回到少年時代，坐在自家門前的石階上，聽風吹過整片山林。一曲彈完，他覺得整顆心像被流水洗過一遍，連日趕路的塵埃全沖乾淨了。餘音還沒散盡，山寺的鐘聲已經隨著秋天的霜氣一起響起來，兩種聲音疊在一起，分不清哪個是琴聲的尾巴，哪個是鐘聲的開頭。

太白坐在那裡沒動，直到不知不覺間，青翠的山色已經被暮色染暗，秋雲一層一層堆上來，他才驚覺天快黑了，提筆把這個下午寫成了詩，最後兩句寫得很淡，不覺碧山暮，秋雲暗幾重。他沒有多寫一個想家的字，只寫天色晚了、雲堆厚了。他離開蜀地已經幾十年，再也沒回去過，這幾十年他寫過無數壯闊的詩句，唯獨這一次，是靠著別人的琴聲才想起故鄉的樣子。這一個下午，一個陌生和尚抱著一張借了老鄉名字的琴，替他把峨眉山的風、蜀地的松濤，統統送到了眼前，淡淡兩句底下，壓著的是他這輩子沒說出口的鄉愁。

後來太白又輾轉去過很多地方，聽過很多樂師彈琴，可是很少有一次像這個下午這樣，讓他坐到忘記時間。有人說，真正的鄉愁不是天天掛在嘴邊喊想家，而是像這樣，平常壓在心底一動不動，直到某個瞬間被一個意外的聲音、一個熟悉的名字輕輕碰到，才整個湧上來。`
  },

  // id=125 盛唐 杜甫 〈春夜喜雨〉rating=4
  // 詩眼：杜甫這輩子最快樂的一首詩，起因只是一場不聲不響的雨
  // 隱藏連接：這場雨落在草堂菜圃上，關係著劫後餘生一家人明天的口糧
  125: {
    title: "春夜喜雨",
    author: "杜甫",
    summary: "詩史杜甫寫過太多苦難，難得有一首題目帶著喜字，起因只是半夜下了一場不聲不響的雨。",
    story: `跟你說我朋友子美這輩子難得高興的一個晚上，起因只是一場雨。那年他在成都浣花溪邊蓋了間草堂，總算有個地方能安穩住下來，這是他逃難逃了大半個中國以後，難得踏實住下的一段日子。半夜他被一點動靜吵醒，側耳一聽，是雨聲，很輕，落在屋頂上幾乎聽不出來。

子美這輩子見識過太多場大雨，戰亂裡的雨、逃難路上的雨、兒子餓死那年的雨，那幾年他扶老攜幼從長安一路逃到秦州、逃到同谷，山路難走，糧食常常斷炊。可是眼前這一場落得特別安分。春天正是萬物要發芽的時候，這場雨偏偏選在這個節骨眼上來，好像懂事一樣。他躺在床上聽了很久，聽出這雨是趁著夜色、隨著風，悄悄滲進泥土裡的，一點聲音都不張揚，完全不像要邀功的樣子。子美心裡清楚，這場雨對他有多重要，草堂周圍那幾畦菜地是他跟家人下半年的口糧，前幾年他窮到連鹽都買不起，這場雨等於是替全家把明天的飯補上了。

他乾脆起身推門看，田間小路一片漆黑，連雲都是黑的，只有江上一艘船的燈火還亮著，孤零零地照著一小片水面，襯得四周更靜了。他站在那裡看了很久，覺得這場雨落得又準時又體貼，一點都不像老天爺在示威，倒像是專程來幫他的忙，心裡默念出幾句話，好雨知時節，當春乃發生。隨風潛入夜，潤物細無聲。

隔天一早他又出門看，雨停了，花瓣被打溼，沉甸甸地垂著，整座錦官城的花好像都被這場雨澆得更重了一分，連空氣裡都是溼潤的泥土味。他繞著菜圃走了一圈，發現地面被雨水浸透，正好省了他這幾天挑水澆灌的力氣。這是杜甫存世的詩裡少數題目就帶著喜字的一首。他這輩子寫過太多苦難，戰亂、飢餓、生離死別，字字句句都是別人的、也是自己的傷痛，這一晚，他只是單純為一場雨感到高興，因為這場雨，他們家明天有飯吃。

這首詩後來成了寫雨的典範之作，隨風潛入夜、潤物細無聲這兩句，被後人用來形容一切不張揚卻影響深遠的好事。很少有人記得，這句流傳千古的讚嘆，最初其實只是一個窮困潦倒的父親，半夜聽見雨聲時，鬆了一口氣的心情。`
  },

  // id=139 盛唐 孟浩然 〈歲暮歸南山〉rating=4
  // 詩眼：一句沒忍住的牢騷，關上了他這輩子離官場最近的一扇門
  // 隱藏連接：相傳王維曾私邀孟浩然入翰林院，唐玄宗突然駕到，孟浩然倉皇躲入床底，被叫出來當面念詩
  139: {
    title: "歲暮歸南山",
    author: "孟浩然",
    summary: "皇帝親自點名要聽他的詩，這是孟浩然這輩子離官場最近的一次，結果被自己脫口而出的一句牢騷，親手關上了門。",
    story: `跟你說我朋友浩然這輩子最後悔的一句詩。那天他人在長安，王維的官署裡，兩人正聊著天，忽然外頭傳來消息，皇帝駕到。浩然嚇了一跳，來不及走，慌忙鑽到床底下躲起來，連鞋都來不及穿好。

浩然那年已經四十多歲，考了很多年科舉都沒考上，一直是個布衣，襄陽鹿門山出身的他，這幾年為了求一官半職，在長安待得又累又煩。王維敬重他的才華，常常私下邀他到翰林院聊天，這原本不合規矩，兩人也就是圖個清靜，聊聊詩、喝喝茶，誰也沒想過會出岔子。誰知道那天唐玄宗竟然親自過來巡視。王維不敢欺瞞天子，只能老實回稟床底下藏著一個人。玄宗一聽，倒是來了興致，孟浩然的詩名他早就聽過，乾脆叫他出來，當面念一首詩聽聽，語氣還算和善。

這本來是孟浩然一輩子難得的機會，皇帝親自點名要聽他的詩，只要念得好，說不定當場就有官做，多年的懷才不遇一朝翻盤。浩然爬出來，衣衫還沒整理好，心裡一團亂，腦子裡一片空白，脫口念的偏偏是這首歲暮歸南山，北闕休上書，南山歸敝廬。不才明主棄，多病故人疏。白髮催年老，青陽逼歲除。永懷愁不寐，松月夜窗墟。

念到其中抱怨自己不受重用的那一句，玄宗臉色就變了。這句話明擺著是在抱怨，你自己從來沒認真求過官，朕何曾棄過你，你這是在冤枉朕。玄宗說完，拂袖起身就走，一個字的機會都沒再給他，滿屋子只剩下王維跟浩然兩人面面相覷，燭火還在搖晃，誰也不敢先開口。

浩然後來再也沒能做官，這件事很快在長安的文人圈子裡傳開，有人替他惋惜，也有人笑他不會說話。這輩子他四十歲進京趕考落第，這是他離朝廷最近的一次，近到皇帝親自坐在他面前，卻被自己一句沒忍住的牢騷，關上了唯一一扇門。他晚年回到襄陽鹿門山，過起隱居的日子，跟太白喝酒論詩，兩人交情深厚，浩然卻從不再提這件事，只是每次提到自己不受重用這件事，語氣都特別輕，好像那不過是別人的故事。

多年後有人讀到這段往事，總覺得惋惜，覺得孟浩然只要當場換一首應景的詩，說不定後半生就完全不同了。可是了解他的人卻覺得，這大概就是浩然，寫詩向來直來直往，連在皇帝面前也改不了這個脾氣，或許正因為這份改不掉的直率，才有了後來那個放浪山水、被太白引為知己的孟夫子。`
  },

  // id=149 盛唐 王灣 〈次北固山下〉rating=4
  // 詩眼：太陽比夜色搶先一步升起，他才驚覺自己已經在外漂泊太久
  // 隱藏連接：相傳宰相張說讀到此詩後，親手題在政事堂牆上，讓滿朝官員當範本學習
  149: {
    title: "次北固山下",
    author: "王灣",
    summary: "一個想家想到睡不著的清晨，隨手寫下的兩句話，後來被宰相親手題在了天下最有權力的那面牆上。",
    story: `跟你說我朋友王灣行船到北固山下那個清晨。船停在江邊，他站在甲板上，看見一件很奇怪的事，太陽已經從海面升起來了，可是夜色明明還沒完全退乾淨，天邊一半亮一半暗，看得他愣在原地。

王灣是洛陽人，那些年常年在江南、吳楚一帶跑船辦事，一年到頭很少回家，逢年過節也常常趕不上，家裡的信也是斷斷續續才收得到。這趟船從北方一路南下，行到鎮江附近的北固山下過夜。潮水漲得又平又穩，兩岸看起來格外開闊，風向也順，船帆鼓得滿滿的，一路懸掛著幾乎不用人管，船夫都說這是難得的好天氣。他就是在這種順風順水的清晨，看到那個奇怪的景象，殘夜還沒散盡，海上的太陽已經先升起來了；江上明明還是舊年的最後幾天，春天的暖意卻已經先鑽了進來。時間好像走得比曆法快，季節搶跑了，把他一個人丟在原地。

王灣站在船頭愣了一下，才意識到自己心裡真正在意的，不是太陽跟季節誰先誰後，是他已經在外面待了太久，連過年都趕不回洛陽，家裡的年夜飯他已經好幾年沒趕上了。船夫在一旁忙著收拾纜繩，沒注意到他站在那裡發呆了多久。他提筆把眼前的景象跟心事一併寫下，海日生殘夜，江春入舊年。鄉書何處達，歸雁洛陽邊。寫完盯著這幾句看了很久，他也不知道家書該往哪裡寄，只能盼著北歸的大雁，如果剛好飛過洛陽，替他捎個平安。

這首詩後來傳到了當朝宰相張說手上，他讀到那兩句寫殘夜與舊年的句子，覺得寫得極好，親手題在政事堂的牆上，讓滿朝官員都拿來當範本學習，往來的官員路過都要停下看一眼，這件事後來還被收錄進當時的詩集裡。王灣自己大概沒想到，他在船頭一個想家的清晨隨手寫下的句子，只是為了紓解自己趕不回家的鬱悶，後來竟然會掛在天下最有權力的那間屋子裡，被那麼多人反覆讀。

多年後，這首詩連同它背後被宰相題字的故事，一起被收進了當時的詩選集裡，成為讀書人爭相傳誦的名篇。王灣後來的仕途生涯史書記載不多，可是這兩句想家的話，卻替他在唐詩裡佔下了一個誰都繞不過去的位置。這件事後來也成為文人津津樂道的一段佳話，畢竟不是每個人寫詩感嘆思鄉，都能被宰相親自題上政事堂那面牆。`
  },

  // id=193 盛唐 杜甫 〈客至〉rating=4
  // 詩眼：那條從沒為客人掃過的花徑，那天終於派上用場
  // 隱藏連接：崔明府相傳是杜甫母親崔氏那邊的親戚
  193: {
    title: "客至",
    author: "杜甫",
    summary: "院子裡那條花徑，杜甫從來沒為誰掃過，直到那天，一位許久沒見的親戚登門，他把柴門推開得特別大。",
    story: `跟你說我朋友子美草堂那年迎來的一位貴客。他家南邊北邊都是漲滿的春水，平常來的客人只有一群一群的鷗鳥，天天報到，人卻幾乎沒有。院子裡那條開滿花的小路，子美從來沒為誰掃過，直到那天，崔明府登門，他一大早聽到消息就開始忙活。

崔明府大概是子美母親那邊的親戚，具體是舅家哪一位，後人已經考據不清楚，只知道那天子美聽說他要來，高興得不得了，把柴門推開得特別大，比平常招呼任何人都用心。子美這幾年過的是什麼日子，他自己最清楚，戰亂裡逃了大半個中國，兒子餓死過，一路靠朋友接濟才在成都安頓下來，安史之亂那幾年，他幾乎沒有一天睡過安穩覺。草堂蓋好之後，他其實很少有正經的客人上門，平常門一關就是好幾天沒人說話，只有江上的鷗鳥每天固定飛來，算是他唯一的熟面孔。

崔明府一到，子美忙前忙後，心裡卻有點過意不去，離市集太遠，菜色湊不齊幾樣像樣的，酒也只有自家釀的濁酒，不是什麼好酒，連個像樣的下酒菜都端不出來。他一邊招呼一邊解釋，語氣裡帶著窮人家待客的不好意思，生怕怠慢了客人，話說得又急又快。可是他心裡的高興壓不住，兩人喝著喝著，子美忽然福至心靈，扭頭朝籬笆外喊了一聲，問鄰居老翁肯不肯過來一起喝，把剩下的酒喝完，他捨不得這場難得的熱鬧只有兩個人，恨不得整條巷子的人都來湊個熱鬧。事後他把這頓飯寫進詩裡，盤飧市遠無兼味，樽酒家貧只舊醅。肯與鄰翁相對飲，隔籬呼取盡餘杯。

這頓飯吃得寒酸，可是子美事後把它整首寫進了客至，一字一句都捨不得刪。那條從沒為客人掃過的花徑，那天終於派上用場，往後很長一段日子，草堂依然清冷，鷗鳥依然天天報到。對一個大半輩子活在戰亂與孤獨裡的人來說，有人願意登門喝一杯舊酒，比什麼山珍海味都金貴。

這首客至後來常被拿來跟他早年在長安寫的那些憂國憂民的長詩對照，同一個杜甫，寫過感時花濺淚那樣沉重的句子，也寫過隔籬呼取盡餘杯這樣瑣碎又溫暖的日常。對一個大半輩子顛沛流離的人來說，能安安穩穩張羅一頓待客的飯菜，本身就已經是一種幸福。`
  },

  // id=217 中唐 韋應物 〈寄李儋元錫〉rating=4
  // 詩眼：曾經在長安街頭橫行的紈絝少年，後來為了自己領的俸祿睡不著覺
  // 隱藏連接：相傳南宋朱熹讀到邑有流亡愧俸錢一句，感嘆當世官員少有這種心思
  217: {
    title: "寄李儋元錫",
    author: "韋應物",
    summary: "十五歲就仗著皇帝寵信在長安街頭橫行的紈絝子弟，多年後當上地方官，卻為了自己領的那份俸祿，愧疚到睡不著。",
    story: `跟你說我朋友韋應物年輕時候幹過的荒唐事。他十五歲就當上唐玄宗的貼身侍衛，仗著皇帝寵信，在長安街上橫著走，喝酒鬧事，欺負鄰里，賭錢、鬥雞、藏匿逃犯，什麼都做過，書也讀得不多，是出了名的紈絝子弟。誰能想到，這個人後來會在深夜裡，為了自己領的那份俸祿睡不著覺。

安史之亂打碎了他的靠山，玄宗倉皇出逃，韋應物一夕之間失去侍衛身分，流落在外，昔日呼朋引伴的酒肉朋友一個都不見蹤影，說散就散。這場變故反倒把他敲醒了，他關起門來苦讀，從一個連字都認不全幾個的街頭混混，一路讀成了正經的地方官，中間吃了不少苦，年紀一大把才重新從書本學起，常常讀到深夜。多年後，他當上刺史，管著一方百姓。這年他病了很久，身體一年不如一年，心裡老想著乾脆辭官回鄉種田算了。可是他管的地方，連年有百姓因為交不起賦稅、躲不過災荒而拋家棄業，四處流亡，田地荒了大半。他每個月照樣領著朝廷的俸祿，一想到治下還有這麼多流離失所的人，就覺得自己這份薪水領得心虛，夜裡常常翻來覆去睡不著。

那年跟老朋友李儋、元錫分別，是去年花開的時候，轉眼又是一年花開。世事這麼難料，他常常春愁滿腹，一個人睡不著。他把這些心事寫進信裡寄給兩位老友，身多疾病思田里，邑有流亡愧俸錢。一邊是自己想歸隱的私心，一邊是放不下百姓的責任，兩句話擺在一起，誰看了都覺得揪心。後來南宋的朱熹讀到這兩句，感嘆說，現在的官員裡，還有幾個能有這種心思。

信末他還加了一句掛念，聽說兩位老友原本說要來看他，卻一直沒有動身，他望著西樓的月亮，已經數不清圓了幾回，一封信寫了又改，改了又寫。那個曾經在長安街頭橫行、連書都懶得翻的少年，如今對著一封寫不完的信，字字句句斟酌，惦記的全是別人。

這封信寄出去之後，李儋和元錫最終有沒有動身前往，史書沒有記載。韋應物晚年在多個地方任職，始終保持著這種矛盾又誠實的心境，一邊想歸隱，一邊放不下百姓，這種掙扎，比起那些只顧著風花雪月的官員，反而顯得格外真實可貴。`
  },

  // id=233 晚唐 李商隱 〈流鶯〉rating=4
  // 詩眼：歌聲裡藏著明確的心意，但聽的人從來不是能幫他的人
  // 隱藏連接：流鶯漂盪無枝可依的意象，相傳暗指他捲入牛李黨爭、被昔日恩人令狐綯冷落多年的處境
  233: {
    title: "流鶯",
    author: "李商隱",
    summary: "一隻黃鶯的歌聲裡，藏著李商隱一輩子沒能對令狐綯說出口的請求。",
    story: `跟你說我朋友義山這些年一直在做一件事，換樹枝。他像一隻到處漂盪的黃鶯，飛過一條條小路，越過一道道溪流，連自己都控制不住方向，每停在一根新枝頭，都以為這次終於能落腳，結果沒多久又得挪窩。

義山年輕時受知遇於令狐楚，這位前輩不只教他駢文的本事，還待他如同己出，衣食住行都替他打點，後來還透過兒子令狐綯的關係，幫他考中了進士。照理說，這條路走下去，義山該有一個穩妥的前程，這份師生情誼也該一直延續下去。偏偏他娶了王茂元的女兒，而王家跟令狐家分屬當時朝廷裡對立的兩派，一邊是他的恩師舊識，一邊是他的岳家。這樁婚事在旁人眼裡是背叛恩師，令狐綯從此對他冷了臉，昔日無話不談的至交，見了面也只剩客套，連寒暄都省了。義山後來一次又一次寫詩寄給這位昔日至交，想解釋、想求助，逢年過節也不忘去信問候，得到的多半是沉默，偶爾一兩句回應，也是不冷不熱，像是應付差事。

義山看著園子裡一隻流鶯，忽然覺得那就是自己。牠的叫聲那麼婉轉動聽，分明藏著明確的心意，可是聽的人未必是懂牠、也未必是能幫牠的人。牠一路飛，一路換棲息的地方，好天氣不一定等於好機會，美妙的歌喉不一定等得到對的知音。義山提筆寫下，巧囀豈能無本意，良辰未必有佳期。風朝露夜陰晴裏，萬戶千門開閉時。這幾句，他寫的是鳥，講的全是自己，也是他這些年來回換過的每一根樹枝。

千家萬戶的門一次次開了又關，春天一次次來了又去，他早就聽膩了那些傷春的曲調，再美的旋律都不想聽了，連自己的詩被人稱讚，他都提不起太多興致。他最後在詩裡問，長安城裡到底哪裡有一根真正屬於他的枝頭，這個問題，義山問到晚年都沒有答案，他始終在兩派之間漂著，才情有目共睹，官職卻一直做得不高不低，卡在中間動彈不得，沒有一邊真正肯接住他。

義山這輩子寫過很多首以物喻己的詩，流鶯只是其中最委婉的一首。他從沒有直接寫過一句怨恨令狐綯的話，全部的心事都藏在這些鳥獸草木的意象裡，這種寫法後人稱為朦朧，其實不過是一個被昔日至交冷落的人，最後僅存的一點體面。`
  },

  // id=236 晚唐 李商隱 〈隋宮〉rating=4
  // 詩眼：一個皇帝放的螢火蟲、種的垂柳，活得比他的江山還久，如今只剩腐草跟烏鴉
  // 隱藏連接：相傳李商隱行經隋代運河舊道、聽聞煬帝放螢舊事後有感而作，借古諷今暗指當朝
  236: {
    title: "隋宮",
    author: "李商隱",
    summary: "螢火蟲和垂柳都是隋煬帝自己安排的排場，如今排場散盡，只剩腐草和一群不說話的烏鴉，替他守著這段歷史。",
    story: `跟你說我朋友義山有一次經過運河邊，聽當地人講起前朝一個皇帝的荒唐事，回去就寫了一首詩，句句都是在罵人，卻一個字都沒提到當朝，聰明人一讀就懂他在指桑罵槐。

那條河是隋煬帝開的，河邊那一排垂楊柳，也是隋煬帝下令種的，為的是他每次坐船南下揚州，兩岸能有陰涼遮著，龍舟一走就是幾千里。他嫌長安的宮殿不夠氣派，一心想把蕪城，也就是揚州，改建成自己的新都城，好幾次興師動眾地南巡，勞民傷財，沿途百姓苦不堪言。相傳他還下過一道旨意，叫人捕捉幾斛螢火蟲，晚上放出來，滿山遍野都是光，只為了自己出遊時看著好玩。這些排場，史書上寫得清清楚楚，不是誇張的傳說，義山小時候讀史書讀到這段，都覺得不可思議。

義山站在河邊，聽當地老人講這些陳年舊事，講的人語氣裡帶著幾分唏噓，好像那場繁華還沒走遠。義山忽然想到，如果不是天命轉到了唐朝開國那位額頭生得方正、面相帝王的李淵身上，隋煬帝那艘錦緞做帆的龍舟，大概還會一路開下去，開到天涯海角都不會停。可是眼前的河堤，只剩腐草叢生，連傳說中該從腐草裡生出來的螢火蟲都沒有一隻；那些曾經替皇帝遮陰的垂楊柳，如今只有黃昏歸巢的烏鴉落在上頭，叫聲又冷又啞，河水靜靜流著，一點當年的熱鬧都留不住。

義山想起南朝陳後主，那位同樣因為貪圖享樂、沉迷一首後庭花而亡了國的皇帝。他提筆寫下最後兩句，地下若逢陳後主，豈宜重問後庭花。兩個亡國之君若真在地底下碰了面，大概也沒什麼好聊的，他們這輩子已經把享樂的功課，做得太徹底了。

義山寫這首詩，表面在說前朝往事，心裡想的其實是自己身處的這個朝代，眼看著當朝也漸漸有了同樣奢靡的苗頭。運河邊的螢火蟲早就熄了，可是歷史這面鏡子，他希望當朝的人，能看懂。

這首詩寫成之後，在當時的文人圈子裡悄悄流傳，讀懂的人心照不宣，都知道義山罵的不只是前朝，寫史書的人往往比誰都清楚，歷史最愛重複同一個錯誤，只是換了一批人、換了一個朝代的名字而已。運河兩岸如今只剩水聲，可歷史這面鏡子，義山寫得再隱晦，懂的人終究看得懂。`
  },

  // id=243 晚唐 李商隱 〈無題二首之二〉rating=4
  // 詩眼：明知念舊沒有用，還是忍不住要寫、要惦記
  // 隱藏連接：少年恩師令狐楚之子令狐綯後來官至宰相，卻因義山娶王茂元之女而與之決裂
  243: {
    title: "無題二首之二",
    author: "李商隱",
    summary: "一封寫給女子的情詩，字字句句其實都在說給那個十年不肯回頭的令狐綯聽。",
    story: `跟你說我朋友義山最近的日子。深夜，洛陽城裡他租住的小院，一層又一層的帷幕低低垂下，燭火已經快燒盡了。他翻來覆去睡不著，這一夜長得沒有盡頭。旁人以為他又在想哪個女子，其實他腦子裡轉的，是一個叫令狐綯的名字。

義山十六歲那年，被令狐楚看中。令狐楚是當時的太原公，官居高位，卻願意收一個窮秀才做弟子，親自教他寫駢文奏章，還讓自己的兒子令狐綯跟他同窗共讀。少年義山在令狐家的書房裡，第一次覺得自己的才氣被人看見。他跟令狐綯稱兄道弟，一起熬夜對詩，一起挨老師的罵，兩人常常爭到半夜誰也不肯認輸，第二天照樣勾肩搭背去上學。那幾年，是他這輩子最安穩的日子。

令狐楚死後第二年，義山做了一個決定，他進了涇原節度使王茂元的幕府，還娶了王茂元的女兒。他大概沒想太多，只覺得這是個安身立命的機會，能讓一個窮書生有俸祿、有靠山。可是他沒算到，王家屬於李黨，而令狐家是牛黨的核心人物。這一娶，在旁人眼裡等於義山背叛了恩師的門派，投靠了對立陣營。令狐綯從此對他冷了臉，連舊日的書信都不太回了。

往後十幾年，牛李兩黨輪流得勢，義山夾在中間，誰都不肯真正用他，官職始終在六七品打轉。他一次次寫信給已經當上宰相的令狐綯，信裡從不提舊怨，只是低聲下氣地問候，盼著對方念在少年情分上拉他一把。回信總是很短，或者根本沒有回信。他心裡清楚，寫這些信大概沒有用，可他還是一封一封地寫。

這一夜，他又想起這件事，提筆寫下這首詩，借一個深閨女子的口氣說話。他想起那位傳說中曾與楚王在巫山夢中相會、事後杳然消失的神女，那段情緣原來不過是一場夢；想起傳說裡獨居的青溪小姑，家中始終沒有夫婿相伴。他又想到菱角的嫩莖何等纖弱，偏偏風浪不肯相信，還要一次次去折騰它；月光和露水那樣吝嗇，誰又曾經許過桂葉一次真正飄香的機會。他把這些念頭，一句一句寫成完整的八行：

重帷深下莫愁堂，臥後清宵細細長。神女生涯原是夢，小姑居處本無郎。風波不信菱枝弱，月露誰教桂葉香。直道相思了無益，未妨惆悵是清狂。

他明知道這份念舊沒有意義，令狐綯不會回頭，恩情也回不去了。可他還是任由自己惆悵，任由自己像個發瘋的人一樣繼續惦記。

義山四十六歲病死，終身沒有真正被令狐綯原諒。這首詩後人讀了一千多年，有人說寫的是思婦，有人說寫的是他跟令狐綯回不去的少年情分。沒人能確定。也許連他自己也分不清，那重重帷幕後面，他到底是在想一個女子，還是在想一個早就走遠的朋友。`
  },

  // id=247 晚唐 許渾 〈咸陽城東樓/咸陽城西樓晚眺/西門〉rating=4
  // 詩眼：大禍將至前，一個人先感覺到了那陣誰都不肯明說的風
  // 隱藏連接：無明確歷史人物連接，屬詩人自身病弱漂泊經歷與晚唐時局的呼應
  247: {
    title: "咸陽城東樓/咸陽城西樓晚眺/西門",
    author: "許渾",
    summary: "他在秦漢故都的城樓上，看見了一整座王朝還沒承認的天氣。",
    story: `跟你說我朋友仲晦的一次登樓。那天他走到咸陽城樓上，才站定沒多久，人就開始發愁，這一愁還不是小愁，是望不到邊的那種愁。城樓下面，蘆葦和楊柳長得亂七八糟，遠遠看去，竟然像江南水邊的沙洲。這裡明明是關中乾燥的黃土地，他卻恍惚覺得自己站在別的地方。

許渾這個人身體一直不好，年輕時考了好幾次進士都落第，好不容易中第、做了官，又三天兩頭因病告假，後來乾脆在丹陽丁卯橋邊蓋了間屋子，病一犯就回去躺著養病，後人也常拿丁卯橋來稱呼他的詩集。他這輩子走過很多地方，尤其愛在赴任、辭官的路上，繞去看那些前朝的廢墟，一站就是大半天，同行的人都催他，他總說再看一會兒。這一次他路過咸陽，順道登樓，腳下這片土地，兩千年前是秦國的宮苑，幾百年前是漢朝的宮闕，如今只剩荒草跟斷牆。

他站在樓上往西看，溪雲剛剛聚起來，太陽已經沉到閣樓後面去了；風一陣一陣灌進衣領，他知道，山那頭的雨馬上就要下下來了，滿城的風，已經先一步灌滿了這座樓。這時候的大唐，朝廷裡宦官專權，藩鎮擁兵自重，誰都看得出天要變，誰都不肯先開口說破。許渾常年在外飄零，見過太多地方官府的荒腔走板，也聽過太多百姓私底下的怨言，他心裡那種說不清楚的不安，跟眼前這片要下雨的天，忽然對上了。

樓下的飛鳥，一隻隻落進秦朝苑囿的荒草裡歇息，黃昏就這樣沉沉落下來；蟬在枯黃的葉子間叫著，那裡曾經是漢朝宮殿的地基。他忽然覺得，不必問了，不必問秦朝怎麼亡的，不必問漢朝怎麼衰的，也不必問眼前這個朝代還能撐多久。他提筆將整首詩寫成：

一上高城萬里愁，蒹葭楊柳似汀洲。溪雲初起日沉閣，山雨欲來風滿樓。鳥下綠蕪秦苑夕，蟬鳴黃葉漢宮秋。行人莫問當年事，故國東來渭水流。

寫完最後兩句，他望著渭水，那條河從秦朝流到漢朝，又流到眼前這個他效力的朝代，水從來沒停過，興衰卻一輪換過一輪。過路的人啊，不必再問當年那些事了，只有渭水依舊不聲不響地往東流。

許渾自己大概沒料到，其中一句後來會變成所有人形容大禍將至的口頭禪。四十多年後，黃巢的軍隊真的打進了長安，大唐真的垮了。他站在城樓上感覺到的那陣風，後來真的下成了那場誰也躲不掉的雨。`
  },

  // id=251 北宋 蘇軾 〈正月二十日與潘郭二生出郊尋春忽記去年是日同至女王城作詩乃和前韻〉rating=4
  // 詩眼：功業屈辱都是留不住的春夢，唯有朋友年年赴約才是真的
  // 隱藏連接：潘丙、郭遘是黃州本地平民友人，在烏台詩案後京城名士避而遠之時仍與蘇軾往來
  251: {
    title: "正月二十日與潘郭二生出郊尋春忽記去年是日同至女王城作詩乃和前韻",
    author: "蘇軾",
    summary: "被貶黃州的罪官，靠著兩個賣酒教書的小人物，和一場年年赴約的春遊，把日子撐了下來。",
    story: `跟你說我朋友子瞻在黃州的一個正月二十。那天他跟兩個朋友一起出城尋春，走著走著，忽然停下腳步，這條田埂，他去年這個日子走過一模一樣的一趟，連田邊那棵老樹的姿勢都沒變。

元豐二年那場烏台詩案，把子瞻從湖州知州的位子上直接抓進御史台大牢，審了一百多天，牽連了幾十個親友，他自己一度以為要沒命了。放出來以後，朝廷把他貶到黃州，掛了個團練副使的空銜，不准簽署公事，形同半個囚犯。他帶著一家老小，擠在城裡的定惠院，後來又搬到一塊叫東坡的荒地，自己開荒種菜、蓋屋燒瓦，自稱東坡居士。京城裡認識的那些名士，這時候大半都不敢跟他通信，生怕被牽連進去，信寄出去也常常石沉大海。

倒是本地開酒坊的潘丙、教書的郭遘這樣的黃州人，不嫌他是罪官，常常來找他喝酒聊天，什麼朝廷大事都不提，只聊眼前的柴米油鹽。他弟弟蘇轍當時也被貶到筠州，兄弟兩人隔著千里，書信往來要一兩個月才收得到一封，子瞻心裡常惦記著，卻無能為力，倒是潘丙郭遘這兩張近在眼前的臉，成了他每天真正能說上話的人。子瞻在黃州最艱難的頭幾年，天天跟他們泡在一起，反倒覺得踏實。元豐三年的正月二十，他們三個一起出東門，走到城東的女王城，找了間野店喝了幾杯江城的白酒，野老蒼顏，笑得溫厚，那天他寫了一首詩記下這趟出遊。

整整一年過去，又是正月二十，子瞻跟這兩人又一次走到了城外。景色差不多，人也還是這三個，他忽然想起去年那首詩，提筆和了前韻，把整首詩寫下：

東風未肯入東門，走馬還尋去歲村。人似秋鴻來有信，事如春夢了無痕。江城白酒三杯釅，野老蒼顏一笑溫。已約年年為此會，故人不用賦招魂。

烏台詩案沒有痕跡嗎？當然有。可是站在這片春天的田野上，跟兩個不計較他官位高低的朋友喝著劣酒，那些痕跡忽然不那麼重了。人就像秋天的大雁，年年如期歸來，守著約定；可是做過的那些事，那些曾經以為天大的功業與屈辱，回頭看竟像一場春夢，一點痕跡都留不下。他們當場又約定，以後每年這一天都要再來一次，不用誰特別邀請，自己就會來，像秋鴻一樣守信。他甚至用不著誰來為他招魂，他自己就好好地活著，年年赴約。後來子瞻一路輾轉惠州、儋州，走得更遠、日子更苦，可是每年正月二十前後，只要身邊還有能喝酒的朋友，他總會想起黃州這兩場春遊。人到了最低的谷底才看得清楚，真正撐住一個人的，從來不是官位高低，而是這種一年一次、不必特意邀請、自然就會出現的陪伴。`
  },

  // id=255 民國 魯迅 〈自嘲〉rating=4
  // 詩眼：對敵人絕不低頭，對弱小甘願彎腰，兩種姿態在同一人身上並存
  // 隱藏連接：左聯青年柔石等人遇害的悲痛，是俯首甘為孺子牛的情感底色
  255: {
    title: "自嘲",
    author: "魯迅",
    summary: "被通緝、戴著破帽穿過鬧市的男人，在一場飯局的玩笑話裡，寫出了他一生最硬的兩句話。",
    story: `跟你說我朋友豫才那年秋天，戴著一頂破舊的氈帽，低頭快步穿過上海鬧市的一幕。那頂帽子壓得很低，幾乎遮住半張臉，不是趕流行，是他這陣子被國民黨當局盯上了，住處換了一間又一間，連寫信都得用化名，出門更得學會躲。

一九三一年初，跟他一起搞左聯的幾個年輕作家，柔石、殷夫他們，在龍華被祕密槍決，罪名不過是印過幾本進步刊物。這幾個人裡，柔石是他帶得最熟的學生之一，常常跑來他家坐，兩人一起校對稿子、討論翻譯，有時聊到半夜還捨不得走，柔石甚至學他寫字的筆勢，被豫才笑說學得有點像。噩耗傳來那幾天，豫才把自己關在屋裡，誰都不見，後來提筆寫文章紀念這些孩子，說自己是在夜半燈下，聽著遠處貓頭鷹的叫聲寫成的。往後很長一段時間，他一提筆就想起這幾個年輕人。

那年秋天，郁達夫請客吃飯，席上還有柳亞子夫婦。席間有人隨口打趣，說豫才這一年諸事不順，怕是交了華蓋運，民間說法，人犯了太歲，做什麼都碰壁。豫才聽了不惱，笑著接話，說可不是嘛，翻身都沒翻成，腦袋先撞了一下。滿座人跟著笑起來，他卻順勢把這陣子的狼狽都倒了出來：戴著破帽子躲過熱鬧的街市，怕被人認出來；家裡窮得像條漏船，還敢載著酒在水中央晃盪，危險得很，偏偏還要喝。

柳亞子在旁邊起哄，要他當場寫一首。豫才也不推辭，取了張紙鋪開，提筆就寫，一口氣寫完整首七律：

運交華蓋欲何求，未敢翻身已碰頭。破帽遮顏過鬧市，漏船載酒泛中流。橫眉冷對千夫指，俯首甘為孺子牛。躲進小樓成一統，管他冬夏與春秋。

那些拿筆拿槍對著他的人，千夫所指，他冷眼看著，絕不低頭；可是對著像他兒子海嬰那樣的孩子，對著柔石那樣還沒來得及長大的年輕人，他甘願彎下腰，像一頭老老實實的牛，任孩子騎、任孩子牽。滿座人這才懂，他方才的笑，底下墊著多重的東西。

寫完他把稿子送給柳亞子，自己回到躲藏的小樓裡，關上門。外頭的追捕、內部的圍剿，隨他們去，他這一小方天地，還能寫，還能罵，還能護著該護的人。那頂舊氈帽，後來他又戴著穿過了好幾年的上海街頭，戴著它躲過搜查，也戴著它去看望過幾個還沒長大的孩子，直到他自己病重去世，這頂帽子底下那份橫眉與俯首，始終沒有換過。`
  },

  // id=258 盛唐 李白 〈怨情〉rating=4
  // 詩眼：連自己都說不清楚在怨誰的怨，才是最深的怨
  // 隱藏連接：相傳為李白任翰林供奉期間於宮廷宴會所見一瞬景象寫成，映照他自身有名無實的處境
  258: {
    title: "怨情",
    author: "李白",
    summary: "珠簾捲起的一瞬間，他看見一張哭過的臉，卻連自己心裡那份鬱悶，都說不出在恨誰。",
    story: `跟你說我朋友太白在長安宮裡瞥見的一幕。那天他被召進宮裡陪宴，穿廊過殿的時候，眼角瞄到一間偏殿的珠簾忽然被人捲起，一個年輕女子坐在裡頭，眉頭深深蹙著，一閃而過。他腳步沒停，可那張臉留在他腦子裡走不掉，一整晚宴席上的絲竹聲，他都聽得心不在焉。

那幾年太白剛被玄宗召進長安，封了個翰林供奉，聽著風光，實則說白了就是皇帝身邊的御用文人，宴會上寫詩助興，詔書要潤色也找他，真正的朝政大事，一句都插不上嘴。他滿懷經世濟民的抱負進京，日子久了才發現，自己不過是皇帝身邊眾多擺設裡最會寫詩的那一件，連奏對的機會都輪不到他，倒是每逢賞花宴飲，總少不了叫他即席賦詩湊興。宮裡養著成百上千的女子，有的是嬪妃，有的是歌舞伎，一輩子鎖在幾道宮牆裡，連名字都未必有人記得。他常常出入這些場合，見過太多這樣一閃而過的臉，珠光寶氣裹著，眼睛裡卻空空的。

那天他多看了那女子一眼，才發現她的眼角有淚痕，濕濕的一小片，還沒乾。他心裡一動，想上前問一句，你在恨誰？話到嘴邊又咽回去，宮裡的規矩，不該問的事情，問了也是自找麻煩，弄不好還連累對方。他只能遠遠地看著，看她深坐在那間殿裡，珠簾放下去又捲起來，一天又一天。

他忽然覺得，自己好像也懂那種感覺。翰林供奉這身份聽著體面，說到底跟宮女沒什麼兩樣，都是被人擺在漂亮的位置上，供人觀賞，卻沒人問他們心裡到底想什麼。他自己心裡那股鬱悶，連他自己都說不清楚在恨誰、恨什麼，是恨皇帝把他當成弄臣，還是恨自己那身抱負沒地方使。回到住處，他鋪開紙，把那個瞬間寫成四句：

美人捲珠簾，深坐蹙蛾眉。但見淚痕濕，不知心恨誰。

他沒有寫出那女子的名字，也沒有替她編一個原因。他就讓那滴淚掛在那裡，誰也不知道她在恨誰，因為連他自己那份說不出口的怨，也一樣找不到一個可以指名道姓的對象。兩年多後，他被賜金放還，離開了長安，那間珠簾深垂的偏殿，他再也沒有機會經過，倒是這四句詩，跟著他一路漂到了南方，往後每次有人問起他在宮裡的日子，他總是笑而不答，大概那滋味，也跟那女子的淚一樣，說不清楚該恨誰。`
  },

  // id=264 盛唐 王維 〈竹里館〉rating=4
  // 詩眼：不被任何人看見，才是真正的安全與自由
  // 隱藏連接：安史之亂中被迫受偽職、凝碧池賦詩自證忠心後僥倖躲過清算的經歷
  264: {
    title: "竹里館",
    author: "王維",
    summary: "劫後餘生的人，好不容易找到一處不必表演忠誠、不必被誰看見的角落。",
    story: `跟你說我朋友摩詰，晚年在輞川一片竹林深處待著的樣子。他一個人坐在竹叢裡，彈了一段琴，彈完又對著空山長嘯一聲，聲音在山谷裡繞了一圈才散掉。四下沒有人應。他也不指望有人應。

這樣的安靜，對摩詰來說得來不易。安史之亂那幾年，叛軍攻進長安，他來不及跟著朝廷南逃，被叛軍抓住，押到洛陽。安祿山知道他的才名，逼他做官，他假裝吃藥拉肚子推辭，還是被硬按著接下了偽職。最難堪的一次，是叛軍在凝碧池辦宴會，逼著唐朝的宮廷樂工奏樂助興，樂工們一邊彈一邊哭，其中一個樂工氣得摔琴痛罵，當場被殺，摩詰也被迫坐在席間，親眼看著這一切。他事後偷偷寫了一首詩，寫自己聽到那些哭聲，心裡想念的是被困在別處的皇帝。

叛亂平定以後，凡是在叛軍手底下做過事的官員都要被清算，有的殺頭，有的流放。摩詰也在被審查的名單上，那陣子他天天提心吊膽，連睡覺都不安穩，半夜常常驚醒，以為官差已經上門。多虧那首凝碧池詩流傳出去，肅宗讀了心軟，加上他弟弟王縉願意用自己的官位替兄長求情，他才保住性命，只是降了職。從那以後，他很怕再被架到人前，被架著表演忠誠、表演立場、表演任何一種身份，哪怕只是跟同僚寒暄兩句，他都要先在心裡斟酌好幾遍。

他把輞川那座別業修整出來，一有空就往那裡躲。裴迪常來陪他，兩人在別業裡挑了二十個地方，一人一首唱和。竹里館是其中一站，一片幽深的竹林，搭一間小屋。摩詰坐在裡頭，不必解釋自己為什麼在這裡，不必解釋自己彈的是什麼曲子，更不必擔心彈的這首曲子會不會被人拿去做文章、扣上什麼帽子。他把眼前的一切寫成四句：

獨坐幽篁裡，彈琴復長嘯。深林人不知，明月來相照。

深林裡沒有人知道他在，只有月亮爬上來，照著他。這四句聽起來像在寫閒適，底下藏著的，其實是一個劫後餘生的人，好不容易找到一處不必被誰看見、不必向誰交代的角落。月亮不會審問他，也不會要他表態，更不會拿他的話去告發誰。他晚年多半就是這樣過的，白天勉強應付朝中差事，一有空就躲回輞川，把官服脫下，把心事也一併脫下。這大概是他這輩子，難得可以徹底做自己的時刻。`
  },

  // id=265 盛唐 王維 〈送別〉rating=4
  // 詩眼：送別時真正害怕的，不是對方路上出事，是對方從此不想回來了
  // 隱藏連接：無明確具體友人記載，隱藏連接為王維自身終生擺盪於出仕與歸隱之間的心境投射
  265: {
    title: "送別",
    author: "王維",
    summary: "送走一個決心歸隱的朋友，他關上柴門，卻沒能把心裡那個問題一起關上。",
    story: `跟你說我朋友摩詰送朋友進山的那個傍晚。人送到山裡，轉身往回走，天已經黑透了。他回到家，把柴門關上，動作很平常，像是什麼都沒發生。可他站在門後，愣了好一會兒，手還搭在門閂上沒放開。

摩詰這輩子活得有點兩頭不靠。他年紀輕輕就中了進士，官也做得不算小，可是他心裡一直有一半住在山裡。他在輞川買了塊地，一有空就往那裡跑，種竹子、養魚、跟和尚下棋、抄經打坐，朝廷有事召他，他再換上官服回長安應付。旁人都說他這樣亦官亦隱活得聰明，兩邊的好處都佔了。只有他自己知道，這樣兩頭跑，心裡其實常常沒著沒落，說不清自己到底屬於哪一邊，有時候在長安應酬到一半，忽然就想起輞川那片竹林，恨不得立刻脫身。

那天送走的這個朋友，是準備真的往山裡去，不打算再回來做官的那種，據說是厭倦了官場裡那些言不由衷的應酬。摩詰陪他走了一段山路，兩人沒說太多話，這種話說開了矯情，不說又憋得慌，只是偶爾指一指路邊的野花、聊兩句無關緊要的閒事，像是要把離別拖得長一點。到了該分手的地方，朋友拱拱手，往山的深處走去，摩詰站在原地看，直到那個背影拐過一道山梁看不見了，才轉身往回走，腳步比來時慢了不少。

回程的路上，他心裡冒出一個念頭，跟一般送別詩想的不太一樣。他不擔心朋友路上會不會出事，他擔心的是另一件事，這個人會不會，就這樣被山留住了？明年春天草綠的時候，他到底還會不會想著要出山？

他推開柴門，天色已經暗下來，順手就把門關上，像每天傍晚一樣。可那個問題還懸在他心裡沒有放下。他把這個念頭寫成了四句：

山中相送罷，日暮掩柴扉。春草明年綠，王孫歸不歸。

這問句他問朋友，其實也是在問自己。他自己每年也在出仕與歸隱之間來回好幾趟，誰知道哪一年，他會不會也像今天送走的這個人一樣，一頭走進山裡，就再也不想出來了。柴門關上了，問題卻沒有關上。後來他確實愈住愈久，晚年幾乎把輞川當成了正職，長安反倒成了偶爾才回去的地方，只是這首詩裡那個沒有答案的問句，他始終沒有機會回頭問一問，那位朋友，到底有沒有回來過。`
  },

  // id=278 中唐 裴迪 〈送崔九〉rating=4
  // 詩眼：半途而廢的歸隱，比不歸隱更可惜
  // 隱藏連接：裴迪、王維、崔興宗同屬輞川別業詩友圈，崔九即王維內弟崔興宗
  278: {
    title: "送崔九",
    author: "裴迪",
    summary: "送朋友進山隱居前，他把別只是去玩玩這句話說得比誰都重。",
    story: `跟你說我朋友裴迪，在藍田山口送崔九上山的那一次。崔九轉身要走，裴迪忽然喊住他，把已經到嘴邊的尋常道別話咽回去，換了另一句更重的話，說完自己都愣了一下。

裴迪這個人，大半輩子的朋友圈子都圍著一座輞川別業轉。他跟王維走得最近，兩人在別業裡挑了二十個景點，一人一首唱和，寫了整整一冊輞川集，山裡哪塊石頭、哪片竹林都留下過他們的詩。崔九，大名崔興宗，是王維的內弟，也是這個小圈子裡的常客，三個人常常一起爬山、下棋、喝酒，誰家有酒就往誰家跑，日子過得閒散又親近。這回崔九說要正式歸隱山林，裴迪特意跑到山口送他。

裴迪自己也是半個隱士，他沒怎麼做過大官，大半時間陪著王維在輞川晃盪，對進山這件事，他比誰都清楚裡頭的門道。他見過太多人，一開始興沖沖說要歸隱，進山住了幾天，新鮮勁一過，又惦記著長安的熱鬧、市集的喧嘩，找個藉口就下山了，回頭還跟人吹噓自己曾經隱居過，好不風光，說起山裡的雲霧鳥鳴，眉飛色舞，卻絕口不提自己其實只撐了三天。這種半吊子的歸隱，裴迪看不上，覺得比從來不曾動念要歸隱的人還要可惜。

他望著崔九，想起陶淵明筆下那個武陵漁夫，那漁夫誤打誤撞進了桃花源，看了滿山的美景，吃了幾頓飯，轉頭卻想著要回家報信，結果再也找不到回去的路，白白錯過了一整個桃花源。裴迪不想崔九也做那個漁夫，進去看一眼就想著出來，最後兩頭都落空。他鄭重地把心裡的話說了出來：

歸山深淺去，須盡丘壑美。莫學武陵人，暫遊桃源裡。

這座山不管你進去得深或淺，既然去了，就把那些山丘溝壑，一處一處看透看夠，別學那個武陵漁夫，把整片桃花源當成一趟短暫的觀光，看完拍拍屁股就想著回程。

崔九聽完，對他點了點頭，轉身往山裡走，這次腳步比剛才沉穩了一些。裴迪站在山口，一直看到那個身影徹底融進林子裡，才轉身下山，路上還在想，自己這句話會不會說得太重了。多年後裴迪自己也常常想起這句話，不只是說給崔九聽的，也是他提醒自己，這輩子留在輞川陪王維的日子，不能只是暫遊，得像真正住進去的人那樣，把每一塊石頭、每一片竹林都看熟看透。`
  },

  // id=284 中唐 王建 〈新嫁娘〉rating=4
  // 詩眼：摸清楚上頭的脾氣，比手藝本身更重要的生存智慧
  // 隱藏連接：王建早年出身寒微、輾轉依附幕府謀生的經歷，與新嫁娘初入陌生環境的處境相通
  284: {
    title: "新嫁娘",
    author: "王建",
    summary: "新媳婦不敢直接問婆婆的口味，先讓小姑試味探路，這步棋，作者自己也走過。",
    story: `跟你說我朋友仲初寫過的一個新嫁娘。成親第三天一早，她挽起袖子走進廚房，那是這家的規矩，三朝入廚，新媳婦得親手做一頓飯給公婆嘗嘗手藝。她把手洗了又洗，洗到指尖發紅，才動手熬那鍋羹湯。

這新娘子心裡其實七上八下。她嫁進來還不滿三天，婆婆平常愛吃鹹一點還是淡一點、喜歡濃還是喜歡清爽，她一概不知道。婆家這些年的規矩、婆婆的脾氣，都還是一團霧，連廚房裡調料罐擺在哪裡她都還在摸索。這鍋湯要是做壞了，婆婆嘗第一口就皺眉頭，往後這個家幾十年，她大概都要被貼上笨手笨腳的標籤，再想翻身就難了。這一鍋湯，賭注不小。

她想了個辦法。婆婆進門之前，先端了一小碗，叫來自己的小姑，婆婆的親生女兒，自小在這個家裡長大，最清楚母親的口味。她把碗遞過去的時候，手心其實還在冒汗，臉上卻裝得若無其事，只說想請小姑幫忙掌掌眼。讓小姑先嘗。小姑要是說太鹹，她還能趕緊加水；小姑說剛好，她心裡才有底，才敢把湯端到婆婆面前。這一步棋，既不用直接開口去問婆婆口味如何顯得笨拙，又能借小姑的嘴，悄悄摸清楚真正的答案，兩邊都不得罪。

王建自己出身寒微，早年家裡窮，讀書之餘還得幫著種地，後來投奔幕府，靠著給節度使們寫文書糊口，輾轉了好幾個地方，見過太多新人初到一個陌生班底，得先摸清楚上頭的脾氣，才知道話該怎麼說、事該怎麼做，貿然出頭往往吃虧。他自己就是這樣一路謹慎試探著走過來的，深知那種還沒摸清楚規矩、一步都不敢走錯的心情。

他把這份體會，寫進了一個新嫁娘的廚房裡：

三日入廚下，洗手作羹湯。未諳姑食性，先遣小姑嘗。

短短二十個字，沒有一句寫她害怕，可那份小心翼翼全在動作裡。這首詩後來被人記住，不只是因為寫活了一個新媳婦，更因為每一個初來乍到、還沒摸清楚上頭脾氣的人，讀到這四句，都會心一笑，這種先找人探路、再往前走一步的謹慎，誰的人生沒經歷過幾回。至於那鍋羹湯最後合不合婆婆的口味，詩裡沒說，倒也不必說，摸清楚該怎麼走這一步，比湯本身鹹淡如何，更值得記上一筆。`
  },

  // id=292 中唐 盧綸 〈塞下曲四首之三〉rating=4
  // 詩眼：真正的勇氣不是衝鋒的姿態好看，是明知艱難仍然往前
  // 隱藏連接：盧綸曾任河中節度使渾瑊幕府判官，隨軍駐紮邊塞，親歷軍旅生活而非憑空想像
  292: {
    title: "塞下曲四首之三",
    author: "盧綸",
    summary: "弓刀都快被雪埋住了，那隊輕騎兵還是照樣策馬衝進了黑夜。",
    story: `跟你說我朋友允言在邊塞軍營裡的一個雪夜。斥候連夜跑回大帳稟報，說單于的營帳空了，人已經連夜逃了。帳外沒有月亮，黑得伸手不見五指，只聽見頭頂雁群被驚起，撲棱棱飛得老高，叫聲劃過黑暗的天空。

盧綸這輩子考科舉考得不順，趕上安史之亂，家鄉一片兵荒馬亂，考場好幾次都因為戰亂開不成，一連蹉跎了好些年，眼看著同齡人陸續有了出路，他還在等一個機會。熬到後來，是宰相元載看中他的文才，把他推薦進了官場，可是走的不是尋常科舉正途，官運一直不算順遂，起起落落。後來他索性到河中節度使渾瑊的幕府裡當判官，做的是替將軍處理軍務文書的差事，跟著大軍一起駐紮邊塞。這跟大多數坐在長安寫邊塞詩的文人不一樣，他是真的在軍營裡過冬，真的聞過那股寒氣鑽進骨頭裡的滋味。

那一夜，主帥聽了斥候的稟報，二話不說，點了一隊輕騎，要連夜追出去。盧綸就在帳篷裡，看著將士們摸黑披甲上馬，動作快得幾乎沒有聲音，誰都知道這一追，未必追得上，但誰也沒有猶豫。手裡的弓和刀，才拿出來沒多久，就已經落了一層雪。這雪不是斯斯文文飄的那種，是那種一沾上就化不掉、越積越厚的邊塞大雪，追兵頂著這樣的雪往黑暗裡衝，連自己下一步踩在哪裡都看不清楚，馬蹄踏過去，身後只留下一串很快就被覆蓋的印子，彷彿這支隊伍從沒出現過。

盧綸站在帳篷邊，看著這隊人馬的背影消失在雪夜裡，忽然覺得，這才是真正的勇氣，不是白天擂鼓衝鋒那種好看的勇氣，是明知道弓刀都快要被雪埋住了，還是照樣策馬追下去的那種。他回帳提筆，把這一幕寫成四句：

月黑雁飛高，單于夜遁逃。欲將輕騎逐，大雪滿弓刀。

這四句他寫得極省，沒有一個字寫苦，可那種雪夜奔襲的艱難，全藏在那三個字裡。多年後盧綸離開了軍營，重新回到官場浮沉，寫過不少應酬詩，也送往迎來過不少貴人，可那個雪夜看見的背影，他一直沒忘，那才是他在邊塞幕府那幾年，真正見識到的，一支軍隊該有的樣子，也是他日後每次動筆寫邊塞詩時，心裡真正的標準。`
  },

  // id=298 晚唐 李頻 〈渡漢江〉rating=4
  // 詩眼：越靠近家門，越不敢開口問消息——因為答案揭曉之前，還能抱著一絲希望
  // 隱藏連接：無（此詩作者歸屬本身在史料上另有一說為宋之問，此處依專案詩詞資料所標之李頻撰寫）
  298: {
    title: "渡漢江",
    author: "李頻",
    summary: "越走近家門，他反而越不敢開口問一句家裡還好嗎——這首詩寫的就是答案揭曉前最後一刻的沉默。",
    story: `跟你說我朋友李頻的一段路。渡口的風吹得有點冷，漢水的水面泛著灰白的光，船已經靠岸，艄公坐在船頭捲著褲管，等著客人上船，其他幾個旅人都陸續上了船，只有他一個人站在原地，看著北岸，遲遲不肯邁出那一步。三步之外就是回家的路，他卻像被什麼東西釘住了腳，連艄公喊了他兩聲，他都沒回過神。

他這一趟走得很遠。年輕時屢試不第，一次一次從睦州老家出發，往長安趕考，一次一次落榜，盤纏用盡就在外頭找活路過日子，替人抄書、當幕僚，這一走，往南又往南，走到了嶺外，五嶺以南，離家鄉幾千里的地方，連當地人講的話他都聽不太懂。他不記得自己在外頭漂了幾年，只記得音信斷了不知道多久。剛開始還託人捎信回去，一封要走大半年，後來連願意捎信的商隊都找不著了，家裡的消息，他一個字都收不到。

嶺外的冬天很短，他在那裡熬過一個又一個沒有家書的冬天，熬到又一個立春，草木才剛開始轉綠，他才終於湊夠盤纏，決定回家看看。出發前他心裡是雀躍的，一路上翻山過嶺，他一天一天數著，離家鄉越來越近了。可是走著走著，那股雀躍慢慢變了味。

他開始怕。怕的不是路遠，是不知道。這麼久沒有音信，家裡會不會出事了？父母還在不在？屋子還在不在？他離家的時候鄰居張家伯伯身體就不太好，這幾年是不是已經。他越靠近漢水，離家鄉越近，腦子裡冒出來的壞消息越多。以前他總覺得，只要走到家門口，一切就會知道答案。現在他才發現，答案還沒揭曉之前，什麼都不知道，反而是最安穩的。

渡口邊剛好有個從對岸過來的行商，看樣子像是這一帶的人，說不定認得他家附近。他抬起腳想走過去問一句，話到嘴邊卻又縮了回來。他站在那裡，看著江面，好一會兒才低聲說出一句話，不是問行商，是說給自己聽的：嶺外音書絕，經冬復立春，近鄉情更怯，不敢問來人。

他終究還是沒問。他把這四句話記在心裡，上了船，一路無話，直到看見自家的屋簷。

後來的事，史書上沒有寫。沒人知道他推開家門那一刻看見的是誰，聽見的是什麼消息。這首詩留下的，只有渡口邊那個遲遲不肯開口的瞬間，比起知道壞消息，更難熬的，是還沒揭曉答案的那一刻。一千多年後，每一個久久沒回過家、心裡七上八下的人讀到這四句，大概都會懂，他當時為什麼寧可再多站一會兒。`
  },

  // id=300 北宋 王安石 〈梅花〉rating=4
  // 詩眼：沒有人看，也依然要把自己活得完整地開一次
  // 隱藏連接：相傳此詩寫於晚年罷相、退居江寧鍾山之後，以牆角寒梅自況變法孤軍奮戰仍不改其志
  300: {
    title: "梅花",
    author: "王安石",
    summary: "牆角那幾枝梅，沒人來看照樣開得滿樹——這是王安石罷相後，寫給自己的一句沒關係。",
    story: `跟你說我朋友介甫晚年的一個牆角。金陵鍾山腳下，他自己起的一座簡陋宅子，屋子不大，牆也是就地取材壘的，牆角背陽，終年曬不到什麼太陽，種了幾枝梅，天寒地凍，誰也沒空搭理它們，它們卻自顧自地開了。他常常一個人穿著厚棉袍站在牆角看，看很久，家裡的僕人喊他吃飯，喊兩三次他也不理。

介甫這輩子最風光的時候，是神宗一句話，把他從江寧知府一路拉到宰相，主持熙寧變法。青苗法、免役法、市易法，一條一條推下去，想把積弱的大宋翻新一遍，收回豪強兼併的田地，減輕農民的稅賦。那幾年他是朝廷裡最忙也最硬的人，天不亮就進宮議事，深夜還在燈下批公文，誰勸他都不聽。司馬光跟他辯論了幾個回合，話不投機，索性絕交；蘇軾寫詩諷刺新法，被他排擠出朝，貶到杭州；連他自己一手提拔、一路栽培的官員，後來見風向不對，也倒戈反對他。變法推行到一半，反對的聲浪越滾越大，連他弟弟王安國都站到對立面去，家宴上兩人為了新法吵到摔筷子。神宗動搖了，介甫兩度罷相，最後一次徹底離開權力中心，退居江寧，種花、寫詩、跟山上的和尚下棋，再也沒回過朝廷。

罷相之後最難熬的不是沒了官位，是沒了聲音。當年跟著他辦事的人，一個一個散了，各自找了新的靠山，連舊日的朋友寫信來，語氣都客氣得像陌生人，問候幾句就沒了下文。介甫沒有辯解，他知道辯解也沒用，史書要怎麼寫他，不是他能決定的。他只是每天照樣起早，澆花、讀書，冬天最冷的那幾天，牆角那幾枝梅照樣開，花瓣薄得像紙，一碰就要掉。沒人來看，暗香卻順著風飄得很遠，連隔壁院子都聞得到。

有天一個舊識路過，遠遠看見牆頭一片白，還當是又下雪了，特地繞過來問一句。介甫搖搖頭，領著他到牆角看，提筆寫下四句話：牆角數枝梅，凌寒獨自開，遙知不是雪，為有暗香來。

沒人來看，不代表沒開。開得好不好，從來不是靠有沒有人鼓掌決定的。介甫後來一直住在鍾山下，直到病逝，史書上對他毀譽參半，吵了近千年還沒吵完，有人罵他固執誤國，也有人說他是被時代辜負的改革者。可是牆角那幾枝梅，年年冬天照樣開，誰也擋不住，誰也不需要誰承認。`
  },

  // id=314 盛唐 杜甫 〈絕句-其三〉rating=4
  // 詩眼：從窗口看見萬里之外的船，才第一次真正確定天下太平了
  // 隱藏連接：好友嚴武在成都對杜甫多有照應資助，是這份難得安穩心境的靠山
  314: {
    title: "絕句-其三",
    author: "杜甫",
    summary: "窗邊兩隻黃鸝一聲叫，杜甫忽然笑了，因為門前那幾艘萬里外來的船，代表戰爭終於結束了。",
    story: `跟你說我朋友子美，在成都草堂的一個春天早晨，突然笑出聲來。這些年他很少笑，日子過得緊巴巴，臉上常年是一副愁容，這一次，是看著窗外兩隻黃鸝在翠柳間叫，才笑出來的，笑聲把在灶前忙活的妻子都嚇了一跳，探頭進來看他是不是又病糊塗了。

子美這輩子大半時間都在逃。安史之亂那幾年，他從長安逃出來，一路顛沛，丟了官，差點丟了命，親眼看過潼關屍橫遍野，親耳聽過石壕村裡老婦人被差役抓走服役的哭聲。他寫過三吏三別，每一首都是眼淚換的，寫完自己也睡不著覺。後來他帶著一家老小輾轉逃到成都，靠著朋友嚴武照應，才在浣花溪邊蓋起一座草堂，茅草屋頂，一下大雨就漏水，勉強安頓下來。

嚴武是他這輩子少數還撐著的朋友。子美窮到吃飯都要靠人接濟，米缸常常見底，嚴武幾次派人送米送酒，還幫他弄了個檢校工部員外郎的虛銜，好歹有份俸祿。子美嘴上總說不敢當，寫詩回謝也帶著幾分過意不去，心裡其實清楚，沒有嚴武，他這一家人早就散了，妻兒可能都要餓肚子。

這年春天，叛亂總算漸漸平息，他推開草堂的窗子，看見的不再是逃難的景象。兩隻黃鸝停在翠綠的柳枝上叫個不停，一行白鷺展翅飛過去，直直上了青天。他抬頭再看遠一點，西邊的岷山雪頂終年不化，像是被窗框剛好裝進來的一幅畫。他又低頭看向門前的江面，幾艘商船正停泊在那裡，船身上寫著東吳的字樣，那是從長江下游、幾千里外的江南來的船，船夫正忙著卸貨，喊著號子。

戰亂的時候，這條江上什麼船都沒有，商路斷了，連消息都傳不過來，一封家書要輾轉好幾個月才收得到。子美看著那幾艘萬里之外來的船，忽然明白過來，這代表天下真的要太平了。他提筆寫下四句：兩個黃鸝鳴翠柳，一行白鷺上青天，窗含西嶺千秋雪，門泊東吳萬里船。

沒有一個字提到戰爭，可是每一個字都在說，終於不用再逃了。子美後來又離開了成都，晚年依然顛沛，輾轉湘江一帶，病死在一條破舊的小船上，連個像樣的歸宿都沒有。但草堂窗邊那個笑出聲的早晨，他記了很久很久，那大概是他這輩子最接近安穩的一刻，也是他難得沒在詩裡哭過的一次。`
  },

  // id=318 盛唐 王維 〈秋夜曲〉rating=4
  // 詩眼：有些人不是捨不得手上的事，是捨不得回到那個空蕩蕩的房間
  // 隱藏連接：相傳王維年少時以琵琶技藝出入岐王、寧王府邸（見《集異記》鬱輪袍軼事），因而得見深宮歌伎夜宴後獨自流連的畫面
  318: {
    title: "秋夜曲",
    author: "王維",
    summary: "她彈了一整夜的箏，不是捨不得曲子，是不敢回那個空蕩蕩的房間。",
    story: `跟你說我朋友摩詰年輕時候，在長安一場夜宴上看到的一幕。那是初秋的夜裡，宴席設在府邸的花園裡，燈籠一路掛到迴廊盡頭，池塘裡的荷葉已經開始枯黃，蟲鳴聲此起彼落，宴席散了大半，賓客三三兩兩告辭離去，底下伺候彈箏的女子卻遲遲不肯放下手裡的箏，一個人留在原地又彈了一段又一段，指法還是那樣仔細，一點也看不出是宴席快散的懶散樣子，反倒像是有意要多留一會兒似的。

摩詰那時候還不到二十歲，已經憑著一手好琵琶在長安貴族圈子裡出了名。相傳他曾在岐王的引薦下，扮成樂工的樣子去見公主，一曲鬱輪袍彈得滿座動容，公主聽完當場動容，才華藏不住，最後索性表明身分，靠著這一手音樂本事，再加上滿腹詩文，很快就在京城貴人之間傳開了名聲，成了長安宴席上炙手可熱的座上客。也因為這樣，他常常出入岐王、寧王這些皇親府邸的宴席，見過的樂工歌伎不知凡幾，各自的心事，他多少也看在眼裡。

那一晚的宴席跟平常沒什麼兩樣，賓客盡歡，酒過三巡陸續散去，僕役開始收拾杯盤。摩詰起身要走的時候，回頭看了一眼，發現那個彈箏的女子還坐在原位，身邊的燈已經被收走了大半，只剩一盞。夜露已經很重了，秋天的桂花香混著露氣飄過來，她身上那件輕羅衣裳單薄得擋不住夜涼，肩頭微微聳著，她卻沒有起身去添衣裳，也沒有起身回房，就這樣一直彈，一遍又一遍，像是在跟時間較勁。

摩詰站在廊下看了一會兒，忽然懂了。不是她捨不得這曲子，是她捨不得回那個空蕩蕩的房間。深宮或者深院裡的女子，白天有宴席、有樂器、有人聽她彈，那些時候她不是一個人。可是宴席一散，曲子一停，推開房門，迎面就是黑漆漆的空房，連個說話的人都沒有，燭火滅了也沒人替她重新點上。與其面對那份空，不如把箏再多彈一會兒，哪怕只是多爭取這一刻鐘。

摩詰回去以後，把那一夜的畫面寫成了四句：桂魄初生秋露微，輕羅已薄未更衣，銀箏夜久殷勤弄，心怯空房不忍歸。

他沒有寫那女子叫什麼名字，史書上也查不到，連她後來去了哪裡、有沒有人接她回家，都沒有下文。可是這四句留下來一千多年，每個熬夜不想回空房間的人讀到，都覺得那說的就是自己，連那盞捨不得熄的燈，都像是為自己點著的。`
  },

  // id=320 盛唐 王昌齡 〈長信怨〉rating=4
  // 詩眼：連烏鴉都比我更靠近陽光，這種被權力中心徹底遺忘的處境
  // 隱藏連接：借七百年前班婕妤的失寵往事，寫自己屢遭貶謫、被朝廷遺忘的處境
  320: {
    title: "長信怨",
    author: "王昌齡",
    summary: "連烏鴉都比她幸運，至少烏鴉還能從得寵的宮殿飛過去沾點陽光。",
    story: `跟你說我朋友少伯寫過一個從沒見過面的女子。班婕妤，西漢成帝的妃子，死在王昌齡出生前七百多年，兩人隔著幾百年的時光，少伯卻把她清晨掃地的樣子，寫得像親眼看見一樣，連她握著掃帚的手勢都寫得出來。

班婕妤原本是成帝最寵愛的妃子，才學好，人品端正，能詩能賦，成帝甚至想跟她共乘一輦出遊都被她拒絕，說古代賢君身邊坐的都是名臣，哪有像亡國之君那樣讓寵妃伴駕的，一番話說得成帝又慚愧又佩服。成帝聽了反而更敬重她，一時傳為美談。可是後來趙飛燕姐妹進宮，一個能歌善舞，一個媚態逼人，把成帝迷得神魂顛倒，日夜宿在昭陽殿，班婕妤很快就從專寵變成了棄婦。趙氏姐妹容不下她，誣陷她行巫蠱之術詛咒皇帝，班婕妤怕禍及自身，主動退到長信宮去侍奉太后，從此再也沒回過成帝身邊，日子過得清冷，往日的宮女也漸漸不再來走動。

少伯這輩子仕途也不順。他中進士以後，官越做越小，一路被貶，先貶嶺南，後來又貶到更遠的龍標，走的都是最偏遠的路，幾千里的路，一貶再貶，朝廷把他忘得乾乾淨淨，連升遷的名冊上都懶得寫他的名字。他寫這首詩的時候，大概也在想自己的處境，一個人被權力中心徹底遺忘，是什麼滋味，那種等消息卻永遠等不到的日子，他比誰都清楚。

他想像班婕妤清晨拿著掃帚，打掃長信宮的宮門，宮門一開，外頭的天光照進來，冷冷清清，她百無聊賴地拿團扇當玩意兒把玩解悶，扇柄轉了一圈又一圈。她抬頭看見一群烏鴉從遠處飛過來，那些烏鴉剛從昭陽殿的方向飛來，身上似乎還沾著那邊透出來的一點日光。她忽然覺得又好笑又心酸，連烏鴉都能沾到昭陽殿的光，我這張臉，卻連烏鴉都不如。

少伯提筆寫下：奉帚平明金殿開，且將團扇共徘徊，玉顏不及寒鴉色，猶帶昭陽日影來。

寫的是七百年前的班婕妤，想的未必不是自己。這首詩後來被叫做長信怨，怨的是那道永遠照不到的日光，不管是宮牆裡的，還是朝廷上的。少伯自己這輩子，也始終沒能等到那道光重新照過來，一千多年後讀來，依然戳中每一個被組織、被權力中心徹底遺忘過的人。`
  },

  // id=325 盛唐 王昌齡 〈從軍行其四〉rating=4
  // 詩眼：鎧甲被黃沙磨穿了，可是那句誓言始終沒被磨掉
  // 隱藏連接：相傳王昌齡早年曾親身漫遊西北邊塞，見過戍卒鎧甲磨穿仍死守關隘的畫面
  325: {
    title: "從軍行其四",
    author: "王昌齡",
    summary: "鎧甲被黃沙磨穿了一層又一層，可是那句不破樓蘭終不還，始終沒被磨掉。",
    story: `跟你說我朋友少伯年輕時候去過的一個地方。青海湖邊，長雲壓著雪山，天色暗得像隨時要塌下來，風裡帶著沙粒，打在臉上生疼，連馬蹄踩在乾裂地面上的聲音都被風聲蓋了過去。他站在孤城的城頭，裹緊身上的衣裳，遠遠望向玉門關的方向，那是回家唯一的路，可是誰也不知道還要等多久才走得回去，城牆上的旗幟被吹得獵獵作響。

少伯年輕時不是一直待在書齋裡的人。相傳他曾經離開家鄉，跑到西北邊塞漫遊過一段日子，親眼見識過戍邊將士的日子有多苦。那不是詩裡寫的壯闊風光，是實打實的黃沙、缺水、缺糧，一年到頭打不完的仗，冬天冷得帳篷裡的水都能結冰，夏天又熱得人喘不過氣。將士們的鎧甲，本來是鐵打的，穿久了在風沙裡磨，一天一天磨，磨到金屬都薄得快透光，打一場仗，鎧甲上又添幾道新的刮痕，有的地方甚至已經磨出了破洞，卻沒人有空去修補。

他在城頭認識了幾個守關的老兵，晚上圍著篝火，聽他們講過去幾年打過的仗。有人說自己從十幾歲被徵召來，現在頭髮都白了大半，家裡的孩子出生的時候他都不在場，還沒等到回鄉的命令。有人問他們苦不苦，老兵們反倒笑了，露出一口被風沙磨壞的牙，說苦是苦，可是樓蘭那邊的敵軍一天不退，這道關就一天不能鬆手，不然背後就是自己的家鄉，是他們的妻兒老小。

少伯站在城頭，看著那些鎧甲磨得發亮的老兵，忽然明白了一件事，這些人心裡的苦，遠遠比不上他們心裡那股不肯退的勁。黃沙可以磨穿鎧甲，磨不穿他們的誓言。他自己這一趟邊塞之行，走得再遠，說到底還能回去，可是這些老兵，連歸期都沒有一個準數。

他把這個畫面寫成四句：青海長雲暗雪山，孤城遙望玉門關，黃沙百戰穿金甲，不破樓蘭終不還。

少伯後來一生仕途坎坷，屢遭貶謫，從嶺南一路貶到更偏遠的地方，晚年天下大亂，死於安史之亂的亂軍之中，死得有些淒涼，連個像樣的收場都沒有。可是他在邊塞城頭聽見的那句誓言，比他自己的官運活得更久，一千多年後，還有人記得那句不破樓蘭終不還，記得那些鎧甲磨穿也不肯後退的人，記得那道被風沙吹得獵獵作響的旗幟。`
  },

  // id=330 盛唐 賀知章 〈詠柳〉rating=4
  // 詩眼：把看不見的風，寫成看得見的剪刀，才讓春天有了具體的形狀
  // 隱藏連接：相傳與李白有金龜換酒的忘年交情，映照他晚年依然赤子般的性情
  330: {
    title: "詠柳",
    author: "賀知章",
    summary: "他站在柳樹下問了一句這麼細的葉子是誰裁的，自己想出了答案，是春風拿風當剪刀。",
    story: `跟你說我朋友季真晚年一個尋常的春天。長安城裡，剛下過一場小雨，路面還濕著，一棵柳樹剛冒出新綠，他站在樹下看了很久，看得旁邊的人都覺得奇怪，一棵柳樹有什麼好看的，年年春天都長，哪年不是這樣。

季真這個人，在長安是出了名的性子曠達，好酒，活得比誰都瀟灑。他官做到秘書監，可是一點官架子都沒有，年紀一大把了，照樣跟年輕人稱兄道弟，喝起酒來一點不含糊，醉了就靠著牆睡，也不覺得丟臉。相傳有一次他讀到一個剛到長安、還沒什麼名氣的年輕人寫的蜀道難，讀著讀著站起來直呼此人是謫仙人下凡，當場解下身上佩戴的金龜換酒，拉著人喝了一整天，兩人一見如故，從詩文聊到人生，聊到後半夜都不肯散。那個年輕人就是李白。這段金龜換酒的交情，後來成了長安城裡人人愛講的一段佳話，也讓李白的名字一夜之間傳遍了京城。

那個春天的午後，季真跟幾個朋友喝了點酒，微醺著走在路上，經過一棵柳樹。柳條新發的葉子綠得像剛剝殼的碧玉，一整棵樹垂下來的枝條，細細密密，像誰用絲線編成的裙擺，風一吹，整棵樹都在輕輕晃。他站住不走了，伸手摸了摸柳葉，忽然問身邊的人一句話，你們說，這麼細的葉子，是誰裁出來的。

同行的人都愣住了，沒人答得上來，有人猜是園丁修剪的，季真搖搖頭，說這柳樹沒人打理，根本沒有園丁伺候。季真自己笑了，說不是誰裁的，是春風裁的。你看那風一吹，葉子的邊緣齊齊整整，哪裡是自然長出來的樣子，倒像是一把看不見的剪刀，把冬天剩下的枯枝，一條一條剪出新葉子來，比繡娘的手還細。

他站在柳樹下，把這個念頭寫成了四句：碧玉妝成一樹高，萬條垂下綠絲絛，不知細葉誰裁出，二月春風似剪刀。

季真晚年告老還鄉，回到闊別幾十年的浙江老家，寫下了那首人人會背的回鄉偶書，感嘆兒童相見不相識，鄉音雖然沒改，鬢角卻早就花白了。可是長安這棵柳樹底下的春天，他大概也一直記得，那是他還沒老到要回家的年紀，風一吹，什麼都是新的，連一棵柳樹都值得站著多看一會兒，值得跟朋友多聊上幾句閒話。`
  },

  // id=338 中唐 白居易 〈暮江吟〉rating=4
  // 詩眼：終於離開黨爭漩渦，第一次只是單純看一條江，什麼都不想
  // 隱藏連接：白居易自請外放杭州刺史以避開牛李黨爭，此詩即赴任途中所見
  338: {
    title: "暮江吟",
    author: "白居易",
    summary: "逃離了長安的黨爭漩渦，白居易在船頭第一次只是單純看一條江，什麼都不想。",
    story: `跟你說我朋友樂天離開長安那年秋天的一個傍晚。船行到江中，太陽剛好要落下去，他站在船頭，任江風吹著衣袍，看著江面，忽然覺得肩膀鬆了下來，好像有什麼東西終於卸掉了，那種輕鬆感他自己都覺得陌生。

樂天在長安做官這些年，過得並不輕鬆。朝廷裡牛僧孺跟李德裕兩派人馬鬥得厲害，史稱牛李黨爭，樂天兩邊都不想沾，可是官場哪有真正置身事外這回事，他左右為難，寫奏疏也要字字斟酌，深怕哪句話得罪了哪一派，連跟誰喝酒吃飯，都會被解讀成站了哪一邊。做了幾年，他自己心裡清楚，再這樣耗下去，遲早被捲進去，索性主動請調外放，離開這個漩渦，去杭州當刺史，圖個耳根清淨。

出長安那天，他心裡是輕的，可是一路上還是忍不住想，這一走是不是就把長安這些年的抱負都丟下了，早年寫新樂府、上書言事的那股銳氣，是不是也要跟著收起來了。他沒有答案，只能繼續往前走，船艙裡的書卷也懶得翻，就這樣看著兩岸的景色一段一段往後退。船順著運河往南，走了好些天，這天傍晚剛好行到江面開闊的地方，夕陽斜斜地照下來，江水被染成一道一道的顏色，靠近船邊的水面還是原本的青綠色，遠一點被夕陽照到的地方，整片江水紅得像鋪了一層綢緞，船夫搖著槳，槳聲一下一下，很安靜。

他站在那裡看了很久，直到天色再暗一點，抬頭才發現，那天剛好是九月初三，夜露已經開始凝結，江邊的草葉上一顆一顆亮晶晶的，像撒了一把珍珠，天上一彎新月掛著，細得像一把弓，掛在漸暗的天色裡，特別清晰，船上的隨從也都安靜下來，沒人出聲打斷這一刻。

他把這一刻寫下來：一道殘陽鋪水中，半江瑟瑟半江紅，可憐九月初三夜，露似真珠月似弓。

沒有一句提到黨爭，沒有一句提到朝廷。這是樂天很多年沒有過的心情，單純看著一條江，什麼都不想，連寫詩的筆都拿得比平常輕鬆。杭州那幾年，他修了白堤，種了花，過得比在長安舒坦得多，這道殘陽鋪在水面上的樣子，大概是那一路上他記得最清楚的畫面，多年後想起杭州，他第一個想到的常常還是這個傍晚，還是那彎細得像弓的新月。`
  },

  // id=339 中唐 崔郊 〈贈婢詩〉rating=4
  // 詩眼：近在同一座城裡，卻比天涯更遠的距離感
  // 隱藏連接：相傳於頔讀詩後成人之美，把婢女歸還崔郊（見唐代筆記《雲溪友議》）
  339: {
    title: "贈婢詩",
    author: "崔郊",
    summary: "一首寫給搶了自己心上人的權貴的詩，本該惹來殺身之禍，卻換來一場成全。",
    story: `跟你說我朋友崔郊的一段舊事，史書上幾乎找不到他的名字，生平只留下寥寥幾筆，這件事全靠唐代筆記雲溪友議留下來，真真假假，只能用相傳兩個字帶過。

相傳崔郊年輕時候家境清寒，寄住在姑蘇的姑母家裡，姑母家有個婢女，兩人年紀相仿，時常在院子裡碰面，端茶倒水，日子久了，情愫暗生，兩人常常趁著沒人注意的時候，在後院多說幾句話。可是崔郊家境不好，連娶妻的聘禮都湊不出來，更別說替一個婢女贖身，這份心意，從一開始就帶著沒有出路的味道。他們沒有名分，只能偷偷來往，連話都不敢說得太明白，怕被人瞧見了說閒話。

後來姑母家裡缺錢，把那個婢女賣給了當地的權貴於頔，一個連帥，家財萬貫，出手闊綽，府裡光是伺候的僕役就有上百人。崔郊得到消息的時候，人已經被送進於府深宅，高牆大院，他連見上一面的機會都沒有。他每天在於府附近晃來晃去，像丟了魂一樣，誰勸都沒用，飯也吃不下幾口，夜裡也睡不安穩。

寒食節那天，城裡家家戶戶禁火，只能吃冷食，街上比平常熱鬧，到處是踏青賞春的人。崔郊照樣在於府附近徘徊，沒想到迎面剛好撞見那個婢女，跟著一群公子王孫的隨從一起出門遊春。她一見到崔郊，眼淚當場就掉下來，滴濕了手上的絲巾，兩人卻什麼話都不敢說，只能在人群中擦身而過，連腳步都不敢停留太久。

崔郊站在原地，看著她的背影消失在人群裡，心裡那句話堵了很久，最後提筆寫在紙上：公子王孫逐後塵，綠珠垂淚滴羅巾，候門一入深似海，從此蕭郎是路人。

這首詩後來不知道怎麼流傳到了於頔手上。照理說寫這種詩，等於指著權貴的鼻子罵他奪人所愛，崔郊大概做好了掉腦袋的準備，這幾天連家門都不敢出。沒想到於頔看完，反而把崔郊請來，問清楚原委，竟然把那婢女還給了他，還送了一筆豐厚的財物，成全這對苦命鴛鴦。這段結局是不是史實，誰也說不準，可是後人寧可相信它是真的，畢竟一首詩能讓深似海的候門重新打開一次，已經是這世間難得的善意，也讓崔郊這個幾乎沒留下什麼記載的名字，留在了千年後的詩集裡。`
  },

  // id=341 中唐 岑參 〈逢入京使〉rating=4
  // 詩眼：最深的牽掛，來不及寫成信，只能用嘴巴捎一句平安
  // 隱藏連接：無
  341: {
    title: "逢入京使",
    author: "岑參",
    summary: "想寫封信回家，摸遍全身卻連紙筆都沒有，最短的家書，只能靠一張嘴捎過去。",
    story: `跟你說我朋友岑參第一次出塞那年，在半路上遇到的一個陌生人。那人騎著馬，從西邊往東走，方向跟岑參完全相反，岑參往安西去，那人正往長安回，兩人的馬在路上交會，揚起一陣塵土。

岑參這一年三十出頭，第一次離開熟悉的中原，受命前往安西都護府，在節度使高仙芝底下當幕府書記。這一路要走的，是往西幾千里的路，過了長安再往西，越走人煙越少，越走風沙越大，連個像樣的驛站都難找，有時候一整天遇不上一個人影，夜裡紮營還得輪流看守，提防馬賊。他心裡清楚，這一去少說也要好幾年，家人在長安的家，他這一走，不知道什麼時候才能再見，臨行前家人送他到城外，誰也沒多說什麼，怕一開口就忍不住。

離家越走越遠，他心裡那股不安越積越重。每次經過岔路，看到往東走的人，他都忍不住多看兩眼，那是回家的方向。這天他終於遇上一個真正要回長安的人，一問才知道，是進京奏事的使者，馬不停蹄地趕路，連歇腳都捨不得多耽誤，話沒說幾句就急著要走。

岑參心裡一動，想寫封信託他帶回長安去，伸手往懷裡一摸，才發現自己什麼都沒帶，沒有紙，沒有筆，兩個人都騎在馬上，連停下來的時間都沒有。他這一路風沙吹得眼睛都睜不太開，袖子擦過臉，已經濕了又乾，乾了又濕，擦不乾淨，也分不清是沙子還是淚水。

他知道這次錯過，下次再想捎信，不知道要等到什麼時候，也許要等到明年，也許更久。可是使者已經等不及要上路了，他只能勒住韁繩，湊近幾句話，拜託對方見到家人的時候，替他捎一句話回去，就說一切平安，別的什麼都不用多說。

他後來把這個瞬間寫成了四句：故園東望路漫漫，雙袖龍鐘淚不乾，馬上相逢無紙筆，憑君傳語報平安。

沒有紙筆的那一刻，反而寫成了最短也最重的一封家書。兩人拱手作別，一個繼續往西走進風沙裡，一個繼續往東趕路，誰都沒有回頭，可是那句平安，終究還是送到了長安。岑參後來在安西一待就是好幾年，這首匆匆口傳的家書，是他那趟出塞路上最先寫下的一首詩，也是他這輩子想家想得最直白的一次。`
  },

  // id=342 中唐 韋應物 〈滁州西澗〉rating=4
  // 詩眼：曾經囂張跋扈的貴公子，安史之亂後才學會去愛一株沒人看的野草
  // 隱藏連接：少年時當三衛郎橫行長安、家藏逃犯的荒唐往事，與晚年滁州任上「邑有流亡愧俸錢」的自省互為對照
  342: {
    title: "滁州西澗",
    author: "韋應物",
    summary: "這首寫幽草野渡的閒適小詩，作者年輕時其實是長安城最橫的紈袴子弟之一",
    story: `跟你說我朋友韋應物年輕時做過的事，你大概不會相信。十五歲那年他就進宮當三衛郎，貼身伺候唐玄宗，仗著皇帝的寵信，白天聚眾賭博，晚上翻牆去勾搭鄰家女子，家裡還窩藏著逃犯朋友，整條巷子的人看到他都要繞道走。那時候的他，大字認不得幾個，卻是長安城最橫的紈袴子弟之一。

安史之亂一夜之間把這一切砸碎。玄宗倉皇西逃，禁軍潰散，韋應物失了差事，也失了靠山，一個曾經橫行無忌的貴公子突然發現自己什麼都不是。他躲進太學閉門讀書，從識字開始重新學起，把年少荒唐的十幾年，一點一滴補回來。等他再出現在人前，已經是個溫和自省的地方官，先後做過滁州、江州、蘇州刺史。

這年他在滁州做刺史，公務之餘常去城外一條無人在意的小澗散步。澗邊長著一片幽草，沒有花，不起眼，路過的人誰也不會多看一眼。可他偏偏就愛這一叢草。他在澗邊站了很久，聽見林子深處傳來黃鸝的叫聲，一聲一聲，聽不出方向。到了傍晚，春天的潮水裹著雨勢急急漲上來，渡口那條船沒有船夫，就那樣被水流推著，自己橫在水面上。

他那幾年閉門讀書讀得極苦，年紀已經不小，卻要跟十幾歲的學生一樣從基礎經典啃起，身邊當年一起鬼混的酒肉朋友，沒有一個跟著他一起吃這份苦，散得一乾二淨，倒讓他徹底斷了念想，一心只剩讀書這一件事。

他想起十幾年前那個囂張的自己，那時候他眼裡只有權貴顯要，誰會多看一株長在澗邊的野草。如今他反而懂了，被人忽略的東西，未必不值得被愛。他提筆寫下：獨憐幽草澗邊生，上有黃鸝深樹鳴。春潮帶雨晚來急，野渡無人舟自橫。

後來他在滁州任上還寫過另一句更直白的話，身多疾病思田里，邑有流亡愧俸錢，為治下百姓流離失所而慚愧，不是那個少年時代連良心是什麼都不知道的韋應物寫得出來的話。那個當年橫著走的貴公子，最後把自己活成了那條無人問津卻安靜自在的渡船。

後人讀這首詩，多半只看到一片閒適的山水小景，很少有人知道，能寫出獨憐幽草這四個字的人，年輕時根本不會多看路邊的草一眼，這份轉變，是他用大半輩子的荒唐和悔悟換來的。`
  },

  // id=344 中唐 韓翃 〈寒食〉rating=4
  // 詩眼：一首暗諷權貴獨享特權的詩，最後卻成了讓詩人自己被皇帝欽點做官的敲門磚
  // 隱藏連接：據記載唐德宗因京城有兩個同名韓翃，親自提筆指名要人，點名的正是寫下這首詩的詩人
  344: {
    title: "寒食",
    author: "韓翃",
    summary: "這首詩本來在諷刺權貴徇私，沒想到多年後皇帝就是靠這首詩把他欽點做了官",
    story: `跟你說我朋友韓翃差點被自己的名字害得仕途蹉跎，最後又被自己寫的這首詩救回來。

那是寒食節，全長安一整天不准生火，只能吃冷食，傳說是為了紀念春秋時寧死不受賞的介子推。韓翃那天走在城裡，看見滿城的柳絮到處飛，御苑的柳枝被東風吹得傾斜，好一片春意。可他心裡清楚，這個規矩看似人人平等，禁火這件事其實從來不是人人平等。到了傍晚，皇宮那邊果然點起新火，一支支蠟燭被太監分送出宮，輕煙一路飄進那幾家最得寵的權貴府邸，尋常百姓家裡照樣黑燈瞎火，守著冷灶挨到天亮。他把這一幕寫成四句詩，沒罵一個字，可誰都看得出那股諷刺的意思。

韓翃當時只是個混跡下僚的小官，這首詩寫完後在文人圈子裡傳了很多年，他自己大概也沒指望靠它翻身。偏偏多年後，朝廷缺一個駕部郎中知制誥的位子，中書省擬了名單呈上去，恰好當時京城有兩個人都叫韓翃，一個是這位詩人，一個是刺史。唐德宗看著名單，提筆在旁邊批了四個字：與韓翃。中書省的人拿不準是哪一個，又去請示，德宗這才親自寫下那句春城無處不飛花，點名要的就是寫這首詩的韓翃。

韓翃年輕時就以詩名聞於長安，跟李端、盧綸等人並稱大曆十才子，可才名歸才名，官運卻一直不順，中年以後還在各地幕府裡輾轉當差，眼看著同輩一個個升遷，自己卻總在原地打轉，寫這首詩的時候，他大概也沒想過會靠著這幾句話翻身。

一首暗諷權貴獨享特權的詩，最後成了讓詩人自己被皇帝親自欽點做官的敲門磚。韓翃後來當上了中書舍人，算是熬出頭了。可你猜他心裡怎麼想，那年寒食節傍晚，他看著輕煙飄進五侯家門，寫下這首詩的時候，大概怎麼也想不到，多年後那縷輕煙會繞一圈，飄進他自己家門。

這件事後來成了唐代文人圈子裡津津樂道的佳話，一首詩救活一個仕途，聽起來像傳奇，可對韓翃自己來說，那不過是他在寒食節傍晚，看著輕煙飄進權貴人家時，隨口寫下的一點不甘心，沒想到皇帝竟然也讀懂了。韓翃後來當上中書舍人，算是熬出了頭，只是這份遲來的際遇，多少帶著點造化弄人的意味。`
  },

  // id=349 中唐 劉禹錫 〈春詞〉rating=4
  // 詩眼：困在深宮的美人，與困在朝廷看不見角落的才華，是同一種滋味
  // 隱藏連接：相傳這是劉禹錫晚年與白居易同題唱和之作，兩人在洛陽以詩互相較勁
  349: {
    title: "春詞",
    author: "劉禹錫",
    summary: "這首宮怨詩其實是劉禹錫晚年跟老朋友白居易較勁寫的，藏著他被貶二十三年的心事",
    story: `跟你說我朋友劉禹錫晚年做過一件挺浪漫的事，寫詩跟老朋友白居易較勁。

那些年他跟白居易都已經是半退休的身分，住在洛陽，職位掛著閒差，日子過得清閒。兩人三天兩頭寫詩唱和，你寫一首，我接一首，像兩個老頑童互相較勁誰的句子更好。相傳白居易先寫了一首春詞，寫一個深宮女子春日的愁緒。劉禹錫讀完不服氣，提筆也寫了一首同題的春詞回敬過去。

他寫的是一個剛梳妝好的女子，臉蛋上妝容正合適，從朱紅色的樓閣裡走下來。滿院子的春光明明那麼好，她卻被鎖在這個院子裡出不去，一整院子的愁悶。她百無聊賴地走到院子中央，一朵一朵數著花，不是真的想數，是這一天實在太長太空了，找點事情打發。就在這時，一隻蜻蜓飛過來，停在她頭上的玉簪子上。

劉禹錫這輩子最出名的脾氣，就是不肯低頭認慫。當年他被貶出長安十年後奉召回京，本可以夾著尾巴做人，偏偏跑去玄都觀看桃花，寫下那句暗諷新貴的詩，結果又被貶了十四年，等他終於再度回到長安，昔日種桃的道士都已經不知去向，他還要再寫一首詩把這件事重提一遍，倔強了大半輩子。

劉禹錫想寫的其實不只是哪個具體的宮女。他這輩子被貶了二十三年，從朗州到連州到夔州到和州，一路被貶到最偏遠的地方，好不容易熬回長安，又因為一句玄都觀裡桃千樹，盡是劉郎去後栽，得罪了新貴，再度被外放。才華這種東西，困在一個誰也看不見的深院裡，跟美貌困在深宮裡，是同一種滋味。他把這種滋味寫進那句新妝宜面下朱樓，深鎖春光一院愁。行到中庭數花朵，蜻蜓飛上玉搔頭。

這首詩後來被公認寫得比白居易那首更含蓄，更有畫面。兩個加起來一百多歲的老朋友，一個寫愁，一個和愁，你來我往寫了大半輩子詩。劉禹錫真正想說的，或許不是深宮裡的女子多寂寞，是他自己這一生，才華被鎖在朝廷看不見的地方，關了整整二十三年。

後人讀這首春詞，多半只當是一首尋常的宮怨小品，很少人把它跟劉禹錫自己的遭遇連在一起看。可懂他的人都知道，這位活到七十多歲、寫下人生易老天難老的倔老頭，筆下每一個困在深院的女子，多多少少都有他自己的影子。`
  },

  // id=356 晚唐 劉禹錫 〈竹枝詞二首-其一〉rating=4
  // 詩眼：一個被貶到蠻荒峽江的朝廷大員，蹲在江邊聽鄉下年輕人唱曖昧不明的情歌
  // 隱藏連接：無
  356: {
    title: "竹枝詞二首-其一",
    author: "劉禹錫",
    summary: "這首情意曖昧的民歌小調，其實是被貶到三峽邊的朝廷大官親自採風寫成的",
    story: `跟你說我朋友劉禹錫五十歲那年，在長江邊蹲了一整個春天，聽鄉下年輕人唱情歌。

那時候他被貶到夔州當刺史，夔州在長江三峽邊上，是巴人跟蜀人雜居的地方，朝廷大員被貶到這裡，等於半隻腳踩進蠻荒。可劉禹錫沒有把自己關在刺史官署裡自怨自艾。他常常走到江邊，看當地年輕人聯手唱一種叫竹枝的民歌，吹短笛，敲鼓，邊唱邊甩袖子跳舞，歌詞土裡土氣，可情意婉轉得很，他聽著聽著，覺得比長安城裡那些精雕細琢的宮廷曲子還動人。

有一天他又去了江邊。江水平緩，兩岸楊柳青青，忽然聽見江上傳來一個年輕人踏著節拍唱歌的聲音，是個女孩子在唱，聲音裡帶著點藏不住的心事。她唱的是心上人到底對她有沒有意思，這種曖昧最折磨人，說不清楚，猜不透，像天氣一樣忽晴忽雨。劉禹錫聽出了那個女孩子的心思，索性提筆把這種心事寫成了詩句。

巴渝一帶的竹枝詞原本沒有固定曲譜，唱腔隨性，歌詞也常常是即興編出來的，劉禹錫是少數把這種鄉野俚曲正式寫進文人詩集的士大夫，他自己後來也承認，這種直白的表達方式，比朝堂上拐彎抹角的奏對，讀著痛快多了。

他寫東邊出著太陽，西邊卻在下雨，你說這天氣算晴還是不算晴，晴這個字，跟感情的情同音，一語雙關，說的哪裡是天氣，是那個男孩子心裡到底有沒有她。楊柳青青江水平，聞郎江上踏歌聲。東邊日出西邊雨，道是無晴卻有晴。

劉禹錫自己那些年也活得像這忽晴忽雨的天氣，才剛從朗州被召回長安，一句詩得罪權貴，又被貶去更遠的地方，二十三年裡起起落落，誰也說不準朝廷哪天晴哪天雨。可他偏偏沒有把這種滄桑寫進竹枝詞裡，反倒蹲在江邊，把一整個峽江的民歌採進了唐詩，讓後來的人讀到的，是年輕人清清爽爽的心事，不是他自己那些苦。

這首竹枝詞後來被收進他的文集，成了劉禹錫流傳最廣的作品之一，比起他那些諷刺權貴、屢屢惹禍的詩句，這首單純寫少女心事的小調，反倒讓他在被貶謫的歲月裡，留下了一點少見的輕快。劉禹錫晚年回顧這段夔州歲月，仍常提起江邊聽歌的情景，那大概是他二十三年貶謫生涯裡，少數幾段單純快樂的時光。`
  },

  // id=366 晚唐 杜牧 〈將赴吳興登樂遊原〉rating=4
  // 詩眼：把自己說成沒用的閒官，其實是為了照顧雙眼幾乎失明的弟弟，甘願放棄京城要職
  // 隱藏連接：杜牧多次上書請求外放地方，真實原因是弟弟杜顗眼疾需要用較高俸祿就近照料
  366: {
    title: "將赴吳興登樂遊原",
    author: "杜牧",
    summary: "這首自嘲無能求閒的詩，背後其實是一個哥哥為了照顧瞎眼弟弟主動放棄京城要職",
    story: `跟你說我朋友杜牧離開長安那天，特地繞路去了一趟樂遊原。

那年他四十八歲，在京城當著考功郎中知制誥，算是站到了中央要職的門口。可他自己上表請求外放，要去吳興，也就是湖州，當刺史。旁人聽了都覺得他傻，好不容易熬到能接近權力核心，居然主動往外跑。可杜牧心裡有自己的算盤，他弟弟杜顗這些年眼睛幾乎瞎了，四處求醫，一直缺錢缺人照顧，他早幾年就多次上書，寧可去黃州、池州這種偏遠地方當刺史，圖的就是刺史俸祿高一點，離弟弟近一點，能親自照看醫藥。這一次去湖州，盤算的也是同一件事。

臨走前他登上樂遊原，那是長安城南一處地勢最高的地方，天氣好的時候能望見很遠。他望向北邊，那裡是昭陵，太宗皇帝長眠的地方。貞觀年間那個政治清明、人才濟濟的盛世，離他這個時代已經隔了兩百多年。杜牧年輕時就熟讀兵法，親自替孫子兵法作注，一心想著能像貞觀年間的名臣一樣做點大事，可眼下的他，卻主動請求離開權力中心，去一個遠地方當個閒散刺史，理由還說不出口，只能寫成一句自嘲。

杜牧這輩子寫過不少大氣磅礡談論軍國大事的文章，也註過兵法，滿肚子經世濟民的抱負，可真正落到自己家裡的事，他從沒猶豫過要不要犧牲仕途，弟弟的眼睛一天看不好，他心裡那份牽掛就一天放不下。

清時有味是無能，閒愛孤雲靜愛僧。欲把一麾江海去，樂遊原上望昭陵。他把自己的離去說成無能者才有的清閒福氣，把真正的理由，一個瞎了眼睛、需要人照顧的弟弟，藏在詩句背後，一個字也沒提。

後來他到了湖州，俸祿確實寬裕了些，弟弟的醫藥有了著落。樂遊原上那一眼望向昭陵的回頭，後人讀起來像是懷才不遇的嘆息，其實是一個哥哥用退讓成全的責任，悄悄藏進了史書都懶得寫的角落裡。

多年後有人翻查史料，才把杜牧屢次求外放的真正原因拼湊出來，原來那些被解讀成懷才不遇、消極避世的詩句背後，藏著的是一個兄長最樸素也最沈重的牽掛，比任何仕途野心都更早被他放在心上。杜牧到了湖州之後，果然把大半俸祿都寄回去給弟弟治病，這件事他終究還是沒有寫進任何一首詩裡。`
  },

  // id=367 晚唐 杜牧 〈赤壁〉rating=4
  // 詩眼：一支在江邊撿到的斷戟，讓一個只能紙上談兵的人幻想了一場自己沒機會打的仗
  // 隱藏連接：杜牧曾親自替孫子兵法作注，一生卻沒有機會真正帶兵，這一帶相傳正是他撿到斷戟的赤壁舊戰場
  367: {
    title: "赤壁",
    author: "杜牧",
    summary: "這首懷古詩其實是杜牧撿到一支斷戟後，幻想自己若是周瑜會怎樣的白日夢",
    story: `跟你說我朋友杜牧在黃州江邊撿到一截鐵疙瘩，愣是幻想出了整場赤壁大戰。

他這幾年被外放做黃州刺史，離長安很遠，官不大，事也不多。有一天他在江邊沙地上閒晃，腳底下踢到一個硬東西，挖出來一看，是一支折斷的戟，鐵鏽厚得快看不出原本的形狀。他把戟帶回去，拿磨石一點一點磨洗，鏽跡褪掉之後，露出前朝的鑄造痕跡，他認出這是三國時候的兵器，而黃州這一帶，相傳正好就是當年赤壁大戰的舊戰場。

杜牧這個人不只會寫詩，他年輕時花了很大功夫替孫子兵法作注，滿腦子行軍布陣，一直覺得自己要是生在亂世，未必比周瑜差。可他這輩子沒帶過一天兵，連個像樣的官職都要靠自己一次次上表爭取。他捧著這截斷戟，想起了那場決定三國命運的大戰，曹操號稱八十萬大軍南下，東吳只有周瑜手上幾萬人馬，靠的是一場恰好吹起的東風，火燒連環船，才把曹操打回北方。他忽然想，如果那晚風向反過來呢。

杜牧一生輾轉黃州、池州、睦州等地做刺史，離權力中心越來越遠，年輕時滿腔的軍事抱負，始終沒有機會真正施展。有人說，正因為他從沒上過戰場，才更容易把一場真實的血戰，想像成一局假設換個條件就能翻盤的棋局。

如果東風沒有站在周瑜這邊，東吳輸了，天下就是曹操的。曹操晚年在鄴城蓋了一座銅雀台，享樂用的宮殿。杜牧想像那個畫面，大喬小喬，東吳最出名的兩位美人，一個嫁了孫策，一個嫁了周瑜，若那年真的輸了，兩人下場恐怕就是被關進銅雀台，鎖一輩子春光，誰也救不了她們。他把這個念頭寫成：折戟沈沙鐵未銷，自將磨洗認前朝。東風不與周郎便，銅雀春深鎖二喬。

杜牧沒有機會證明自己是不是真的懂兵法。他這一生大多數時間都在寫奏章、當幕僚、做刺史，離戰場很遠。可那截在江邊撿到的斷戟，替他過了一次自己從沒機會過的癮，原來歷史上那些驚天動地的大事，有時候贏的不是誰更厲害，只是誰那晚剛好等到了風。

這首赤壁後來成了懷古詩裡最常被引用的作品之一，東風不與周郎便七個字，被後人反覆用來討論歷史的偶然性，很少人記得，這場思想實驗的起點，不過是一個外放小官在江邊隨手撿到的一截鏽鐵。`
  },

  // id=372 晚唐 杜牧 〈贈別二首之一〉rating=4
  // 詩眼：見過整座城的風月，才發現自己心裡念著的是那個最不起眼的女孩
  // 隱藏連接：相傳杜牧在揚州夜夜流連秦樓楚館時，上司牛僧孺其實一直暗中派人護送他平安
  372: {
    title: "贈別二首之一",
    author: "杜牧",
    summary: "這首誇少女貌美的詩，其實是杜牧在揚州荒唐幾年後，離別前才看清自己真心的告白",
    story: `跟你說我朋友杜牧在揚州那幾年，活成了整座城裡最有名的浪蕩子。

他在淮南節度使牛僧孺手下當幕僚，官不大，工作也不算重，揚州城的夜生活正好接住了他。秦樓楚館，他幾乎家家都熟，城裡人都認得這個常常深夜才回幕府、身上帶著酒氣的年輕文官。多年後他自己都承認，那幾年活得像一場沒醒過來的夢。可外人不知道的是，牛僧孺表面上什麼都沒說，私底下相傳早就派人暗中跟著他，一來怕他惹上麻煩，二來怕他出事沒人知道。

在無數個秦樓楚館的夜晚裡，有一個女孩子被他記住了。她十三歲多一點，身量還沒完全長開，娉娉婷婷的樣子，像二月初剛冒頭的豆蔻花苞，還沒完全綻放，卻已經看得出以後會有多好看。杜牧那些年見過揚州城裡數不清的美人，珠簾一卷，個個濃妝豔抹地站出來讓客人挑，可他一眼就覺得，這些人裡沒有一個比得上她。

揚州那幾年，杜牧後來自己回憶起來也覺得恍如隔世，他寫過十年一覺揚州夢，贏得青樓薄倖名這樣的句子，語氣裡帶著幾分自嘲，可是對這個十三歲出頭的女孩，他從沒有用過薄倖這種輕浮的字眼來形容。

要離開揚州的那個晚上，他想起這幾年見過的滿城風月，回頭再看這個女孩，忽然明白自己心裡真正惦記的原來一直是她。他提筆寫下：娉娉嫋嫋十三餘，豆蔻梢頭二月初。春風十里揚州路，卷上珠簾總不如。整條十里揚州路，珠簾捲起來的每一張臉，都比不過她這一張。

杜牧後來被調回長安當監察御史，離開了這座他荒唐了好幾年的城。臨走前牛僧孺才把這幾年的暗中照應攤開給他看，他才知道自己以為誰也不知道的深夜，其實從沒有一次是真正孤身一人。可那個晚上，他心裡想的不是這些，他滿腦子只有珠簾捲起時，那張比誰都好看的臉。

多年後有人統計杜牧一生寫過的贈別詩，寫給揚州歌姬美人的不在少數，唯獨這一首，沒有一句誇張的辭藻，只是老老實實地說，滿城的美人，都比不過她一個人，這種樸素的認真，在他所有風流詩句裡反而顯得格外難得。這份藏在誇讚裡的深情，後人讀了千年，依然能從字裡行間，讀出那份說不出口的認真。`
  },

  // id=373 晚唐 杜牧 〈贈別二首之二〉rating=4
  // 詩眼：最深的感情往往長得最不像感情，笑不出來才是捨不得到了極點
  // 隱藏連接：相傳離別當晚牛僧孺交出多年暗中護送杜牧平安的記錄，讓他明白自己從未真正孤身一人
  373: {
    title: "贈別二首之二",
    author: "杜牧",
    summary: "這首寫離別笑不出來的詩，背後藏著兩份說不出口的深情，一份給女孩，一份是上司多年的暗中守護",
    story: `跟你說我朋友杜牧離開揚州那晚，在酒桌上笑不出來。

前一夜他已經寫過一首詩，說整條揚州路上，再多美人也比不過那個十三歲出頭的女孩。可到了真正要走的這個晚上，面對面坐在酒桌前，他發現自己一句俏皮話都說不出口。他這輩子在揚州的秦樓楚館裡出了名地會說話，會逗人笑，可這一晚，他端著酒杯，對著那張熟悉的臉，竟然連一個笑容都擠不出來。

也是這一晚，他的上司牛僧孺把他叫去，交給他一疊紙。杜牧翻開一看，愣住了，是這幾年他每次深夜出門後，相傳暗中護送他的人寫回來的平安帖，一張一張，寫著某夜杜書記去了某處，平安無事。他以為自己這幾年獨來獨往，誰也不知道他的行蹤，原來牛僧孺早就看在眼裡，什麼都沒說，只是默默派人守著他。牛僧孺這個人，表面上治軍嚴厲，話不多，誰也看不出他心裡裝著多少關心。

牛僧孺後來官至宰相，史書上記他治軍嚴謹、識人有度，卻很少有人知道，他曾經替一個放浪形骸的年輕幕僚，默默安排了好幾年的暗中護送，一句表功的話都沒說過，直到杜牧要走了，才把那疊記錄拿出來。

杜牧忽然懂了一個道理，最深的感情，往往長得最不像感情。他自己此刻也是這樣，明明捨不得眼前這個女孩，滿肚子話，偏偏一句都說不出來，別人看著，大概只覺得他很冷淡。他把這種擰巴寫成了詩：多情卻似總無情，唯覺樽前笑不成。蠟燭有心還惜別，替人垂淚到天明。桌上那支蠟燭，燒到天亮，一路滴著蠟淚，倒像是替兩個笑不出來的人，把眼淚都哭完了。

第二天杜牧啟程回長安，牛僧孺沒再多說什麼，那疊平安帖也沒再提起。這座城裡最會說俏皮話的年輕文官，離開的時候什麼漂亮話都沒留下，只留下滿桌燒了一整夜的蠟燭。

這兩首贈別詩後來常被合在一起讀，一首寫給女孩的深情，一首寫給無聲關照的感激，杜牧這輩子留下不少輕薄浪蕩的名聲，可這兩個笑不出來的夜晚，或許才是他真正把心交出去的時刻。牛僧孺那疊沒有署名的平安帖，後來也沒有留存下來，唯一留下的，是杜牧這兩首詩裡藏著的兩份謝意。`
  },

  // id=374 晚唐 杜牧 〈金谷園〉rating=4
  // 詩眼：繁華全部散盡之後，人們記得的不是石崇多有錢，是綠珠跳樓的那一躍
  // 隱藏連接：杜牧自己的家族也曾顯赫一時卻逐漸敗落，路過金谷園時對繁華易散格外有感觸
  374: {
    title: "金谷園",
    author: "杜牧",
    summary: "這首懷古詩表面在哀嘆財富散盡，其實真正讓人記住千年的是一個女人的縱身一躍",
    story: `跟你說我朋友杜牧路過一座廢園，想起了一個跳樓的女人。

那座園子叫金谷園，主人是西晉的石崇，當年是全天下最有錢的人之一，相傳他跟王愷鬥富，拿蠟燭當柴燒，拿綢緞鋪路，金谷園裡樓台水榭，一擲千金。石崇有個寵愛的姬妾叫綠珠，長得美，又會吹笛跳舞。後來朝中權臣孫秀看上了綠珠，派人去要，石崇不肯給。孫秀惱羞成怒，誣陷石崇謀反，派兵去抓人。士兵闖進金谷園那天，綠珠就站在園子裡最高的樓上，對石崇說了句多謝待我這些年的話，轉身從樓上跳了下去。

杜牧走過這座園子的時候，金谷園已經荒廢了幾百年，樓台早就塌了，只剩下荒草跟一道溪水。他站在那裡，想起自己家裡的事，他祖父杜佑當過三朝宰相，家業盛極一時，可等到杜牧這一輩，家道已經敗落，祖傳的樊川別業一度典當出去，他年輕時甚至窮到要靠親戚接濟。石崇的萬貫家財，跟杜家的門楣，說到底都逃不過同一句話，繁華這種東西，散得比想像中快。

杜佑晚年官至宰相，家中門庭若市，等到杜牧成年，家道已經中落，他年輕時甚至寫過詩描述自己借住在親戚家、靠人接濟過日子的窘迫，這種親身經歷過的興衰起落，讓他路過金谷園時，格外能體會繁華散盡是什麼滋味。

眼前的溪水照樣不停地流，一點都不管誰家興誰家亡；春天照樣把野草染綠，誰也攔不住。傍晚起了風，林子裡傳來鳥叫，聽起來像在埋怨著什麼。杜牧看著風裡飄落的花瓣，一片一片打著旋往下掉，忽然覺得那畫面很像很多年前那個從樓上一躍而下的女人。他把這些寫成了詩：繁華事散逐香塵，流水無情草自春。日暮東風怨啼鳥，落花猶似墜樓人。

金谷園裡那些鬥富的金銀珠寶，如今一件都留不下來。真正流傳下來、還能讓一千多年後的人讀了心裡一揪的，不是石崇有多少錢，是綠珠那一躍。杜牧站在廢園的黃昏裡，忽然覺得，原來能活過時間的，從來不是財富。

這首金谷園後來被視為杜牧懷古詩裡最精煉的一首，短短二十八字裡裝下了一整座園林的興衰，也裝下了他自己家族的影子，繁華這件事，他不是聽說的，是親眼看著自己家從有到無，一步一步走過來的。`
  },

  // id=380 晚唐 高蟾 〈金陵晚望〉rating=4
  // 詩眼：有一種傷心連天下最厲害的畫師都畫不出來，因為那是好幾百年的興亡疊在一個人一輩子的辛苦裡
  // 隱藏連接：高蟾出身寒門無人提攜，落第多年才中舉，個人辛酸與六朝古都的興亡感疊合在一起
  380: {
    title: "金陵晚望",
    author: "高蟾",
    summary: "這首懷古詩裡畫不出的傷心，其實是一個寒門子弟考了很多年科舉才熬出頭的心酸",
    story: `跟你說我朋友高蟾，一個寒門子弟考了好多年科舉，才總算擠進進士的窄門。

高蟾出身不好，家裡沒有背景，考場上那些世家子弟從小就有名師教，有長輩打點，他什麼都沒有，只能一次一次自己硬考。落榜那些年他寫過一首發牢騷的詩，說天上的碧桃跟著雨露種在皇宮裡，太陽邊的紅杏靠著雲彩栽在貴人家門口，拿這些比喻那些出身好、被春風眷顧的考生；他把自己比成一朵長在秋天江邊的芙蓉，開得不合時節，可他不願意對著東風抱怨自己沒能早點開花。這股倔強，後來也一路帶進了他的官場生涯。

好不容易考中之後，有一年他到了金陵，也就是六朝古都建康，東晉、宋齊梁陳先後在這裡建都，又先後在這裡滅亡。他站在傍晚的城頭往外望，浮雲慢慢飄回遠山，山色染上一層黃昏的翠色；落日也還沒完全沉下去，陪著秋天的風聲一起坐在天邊。這片景色其實很美，可高蟾看著看著，心裡湧上來的不是讚嘆，是說不出的難受。

唐代科舉考試裡，出身寒門的考生要跟世家子弟同場競爭，本就處於劣勢，高蟾能一路熬過重重落第考中進士，靠的不是誰的提攜，是他自己一次又一次不肯放棄的倔強，這份倔強，跟他筆下那朵不肯對著東風抱怨的芙蓉，其實是同一回事。

他想起這座城裡埋葬過的幾個王朝，一個接一個興起又崩塌，跟他自己這些年考場上的起落，好像是同一種道理，再怎麼努力，有些事情終究擋不住。他提筆寫下：曾伴浮雲歸晚翠，猶陪落日泛秋聲。世間無限丹青手，一片傷心畫不成。他說天底下有那麼多畫技高超的畫師，可誰都畫不出他此刻心裡這一片說不清楚的傷心，因為那不是眼前的風景，是好幾百年的興亡，疊在一個寒門出身的人一輩子的辛苦裡。

高蟾的生平記載不多，只知道他咸通年間中了進士，一路靠自己熬出頭。金陵城頭那片畫不出來的傷心，後來成了他流傳最廣的一句詩，一千多年後讀到的人，大概也說不清楚自己為什麼會被這四個字打中，世間無限丹青手，畫不成的，從來就不只是風景。

高蟾流傳下來的詩不算多，這一首金陵晚望卻成了他最被後人記住的作品，一句世間無限丹青手，一片傷心畫不成，讓多少懷才不遇的讀書人讀到都心有戚戚，原來這種說不清道不明的傷心，從來不是他一個人的。`
  },

  // id=389 晚唐 鄭畋 〈馬嵬坡〉rating=4
  // 詩眼：一個政治人物用翻案詩肯定忍痛犧牲摯愛才是明智之君該做的決斷
  // 隱藏連接：鄭畋晚年在黃巢之亂中身居要職、力主抗敵，親身面對了與玄宗相似的存亡抉擇
  389: {
    title: "馬嵬坡",
    author: "鄭畋",
    summary: "別人替楊貴妃喊冤，鄭畋卻寫詩替玄宗辯護——多年後他自己也站上了同樣的十字路口。",
    story: `跟你說我朋友鄭畋年輕時寫的一首翻案詩。他寫這首詩的時候還沒當上宰相，誰也想不到，多年後他自己會站在跟玄宗一樣的十字路口上，替一個搖搖欲墜的王朝做出同樣艱難的決定。

故事要從馬嵬驛說起。天寶十五年，安祿山打進長安，玄宗帶著楊貴妃倉皇往四川逃。走到馬嵬坡，隨行的禁軍嘩變，殺了楊國忠，又逼著玄宗交出楊貴妃——不殺她，這隊人馬就不再往前走一步。玄宗掙扎了很久，最後叫高力士把貴妃帶到佛堂前，用一條白綾了結了這段感情。史書上寫得很簡略，可是誰都能想像，一個皇帝要親口下令賜死自己最寵愛的女人，那個瞬間有多難熬。

一百年後，鄭畋讀到這段歷史，心裡想的不是玄宗好可憐，也不是楊妃好無辜，而是另一個問題：如果換成別的皇帝，會怎麼選？

他想起一個對照組，南朝陳後主。當年隋兵打進建康，陳後主嚇得抱著寵妃張麗華、孔貴嬪，一起躲進景陽宮一口枯井裡。士兵找到井口，往下喊話，他不敢應聲；最後士兵拿繩子把三個人一起吊上來，狼狽得成了千古笑柄。同樣是國破家亡的關頭，同樣是要不要保住身邊的女人，陳後主選擇了藏，玄宗選擇了斷。

鄭畋提筆寫下：玄宗回馬楊妃死，雲雨難忘日月新。終是聖明天子事，景陽宮井又何人。他的意思很直白：玄宗回鑾長安、楊妃賜死收場，這段魚水情固然難忘，但天下重新見到日月，終究是聖明天子該做的事——你敢問一句，景陽宮那口井裡狼狽被拖出來的，又算什麼東西？

這首詩寫完沒多久，鄭畋自己也一路做到了宰相。晚唐藩鎮割據，宦官弄權，黃巢起兵造反，僖宗一路逃到成都，長安城又一次淪陷，跟玄宗那年幾乎是同一齣戲重演。鄭畋當時是鳳翔節度使，手裡兵力不多，朝中主和的聲音更大，好多人勸他別硬碰硬。他偏偏聯合附近幾鎮的兵馬，堅持要打，一度真的把黃巢的人馬打退，替搖搖欲墜的大唐爭回一口氣。

沒有人知道他提筆寫下終是聖明天子事那一刻，有沒有想過自己有一天也要在保全與犧牲之間做選擇。但看著他後來在鳳翔硬扛住的樣子，你會覺得，那首詩其實不只是替玄宗說話，也是他先替自己將來可能要面對的難關，預先想好的答案。

千年之後我們讀這首詩，多半只記得那句諷刺陳後主的收尾，讀完拍案叫絕。可是真正讓人記得住鄭畋的，不是他寫過這四句漂亮的翻案文章，是他後來真的在自己的馬嵬坡前，沒有躲進那口井裡。`
  },

  // id=392 晚唐 陳陶 〈隴西行〉rating=4
  // 詩眼：前線士兵早已化為白骨，家中妻子卻仍在夢裡等他升官還鄉
  // 隱藏連接：相傳陳陶雲遊邊塞時，聽聞驛丞刻意隱瞞陣亡消息、遲遲不敢告知家屬的實情
  392: {
    title: "隴西行",
    author: "陳陶",
    summary: "五千精銳全軍覆沒埋骨邊疆，家裡的妻子卻還在夢裡，想著他升官回鄉的樣子。",
    story: `跟你說我朋友陳陶雲遊到邊地小鎮那一年，遇到的一件事。他一輩子考不上進士，乾脆把功名心思收起來，帶著一身道家的散淡到處走。走到陝北一帶，他撞見了一件讓他很多年都忘不掉的場景。

那是無定河邊一個不起眼的驛站。當地有個規矩，朝廷打了敗仗，陣亡將士的名冊要層層轉發到各州縣，再由地方官通知家屬。可是邊塞戰事一多，公文常常滯後大半年，信使也常常死在半路上，消息永遠比戰場慢一步。陳陶落腳那晚，正好看見驛丞在整理一疊剛到的舊名冊，上面記的，是幾個月前一場慘敗裡陣亡的五千名精銳，史書裡管這種穿著華貴戰袍出征的部隊叫貂錦軍，意思是他們出發時，鎧甲鮮亮得像穿著貂皮錦緞。可是這五千人，最後全數埋骨在無定河邊，連屍首都找不齊。

驛丞跟他閒聊時提了一句，說前幾天還有個婦人來打聽丈夫的下落，驛丞看著名冊上的名字沒敢說實話，只推說還沒查到，讓她先回去。陳陶問他為什麼不直說，驛丞苦笑，說這幾個月他已經騙過七八個婦人了，每次她們臨走前都說，那就再等等，他這個月又託人捎信回來說要升官了呢。

陳陶心裡明白，那些信多半是幾個月前寄出、途中被扣住或耽誤的舊信，丈夫可能早就死了，可信還在路上，家裡的女人捧著那封信，晚上還會夢見他升官回鄉的樣子。前線的白骨已經在無定河邊風吹日曬，深閨裡的夢，卻還停在他離家那天最鮮活的樣子。

他當晚沒睡，坐在驛站的燈下，把這件事寫成了一組詩，隴西行一共四首，寫的都是邊塞征戍的事。其中一首，他寫下：誓掃匈奴不顧身，五千貂錦喪胡塵。可憐無定河邊骨，猶是深閨夢裡人。他沒有寫戰場多慘烈，也沒有罵朝廷謊報軍情，他只是把兩個畫面並排放著，河邊的骨頭，和夢裡的人，讓讀的人自己去感覺那個落差有多深。

後來陳陶繼續往南走，晚年在洪州西山一帶隱居下來，自稱三教布衣，史書對他的記載很少，連確切的生卒年都說不準。但這四句詩留下來了。每次有人讀到深閨夢裡人這五個字，都會想起，曾經有一整代女人，守著一封遲到的信，不知道自己等的人，早就成了無定河邊的一堆白骨。`
  },

  // id=399 北宋 蘇軾 〈惠崇春江晚景〉rating=4
  // 詩眼：劫後餘生的人看見一幅畫，想的不是筆法，而是又到了能吃河豚的季節
  // 隱藏連接：蘇軾與已故六十年的惠崇素未謀面，隔著一甲子在畫前完成一場跨時空的神交
  399: {
    title: "惠崇春江晚景",
    author: "蘇軾",
    summary: "蘇軾看一幅六十年前和尚畫的舊畫，看著看著，只想起黃州那幾年拚死也要吃的河豚滋味。",
    story: `跟你說我朋友蘇軾看畫看到肚子餓的一件事。元豐八年前後，他在汴京看到一幅六十多年前的舊畫，畫的人叫惠崇，是北宋初年一個會畫畫也會寫詩的和尚。蘇軾盯著那幅春江晚景看了很久，越看越餓。

惠崇這個人，蘇軾這輩子從沒見過，也不可能見過，惠崇大約在真宗年間就過世了，那時候蘇軾都還沒出生，兩人差了快一甲子。可是畫留下來了，輾轉收藏了幾十年，某天出現在蘇軾眼前。畫面上，竹林外面斜斜探出兩三枝桃花，江水看起來還帶著涼意，岸邊幾隻鴨子已經下水，好像牠們比人更早感覺到春天回來了。

蘇軾這幾年剛從黃州回來。那是他這輩子最灰暗的幾年，因為烏臺詩案被貶到黃州當一個有名無實的團練副使，薪水少得可憐，自己開荒種地，還迷上了一樣便宜又要命的東西，河豚。長江下游那一帶，每年桃花開、江水回暖的時候，河豚正好洄游到近海，肉質最肥美，可是處理不好會中毒致死，當地人有句老話叫拚死吃河豚，意思是明知道有毒也要吃。黃州、常州一帶的人明知道危險，還是搶著吃，蘇軾也是其中一個，據說他吃的時候曾說過一句話，大意是這個滋味，就算真的要死也值得。

那幾年他常常請教當地會處理河豚的漁人，看他們怎麼小心翼翼地去掉魚肚裡那些致命的內臟，再拿蔞蒿、蘆芽一起煮成一鍋湯。他一邊看一邊咽口水，心裡想的不是萬一中毒怎麼辦，而是這一鍋要煮多久才能上桌。

看著畫裡的鴨子和江水，蘇軾一下子就想起了那個滋味，還有蔞蒿長滿了地，蘆葦才剛冒出短短的芽，這都是煮河豚湯配的野菜，正是河豚要洄游上市的季節。他沒有去分析畫裡的筆法多高明，他想的是，這個季節到了，又可以吃了。

他提筆在畫上題了兩句四言絕句，其中一首寫道：竹外桃花三兩枝，春江水暖鴨先知。蔞蒿滿地蘆芽短，正是河豚欲上時。他把一幅安安靜靜的畫，寫成了一張會讓人流口水的季節提醒。

這首詩後來被拿來當成觀察力細膩的範本，說鴨子最先感覺到春江水暖，是多麼會寫景。可是對蘇軾自己來說，這幾句更像一種劫後餘生的踏實感，黃州最苦的那幾年他都熬過來了，現在他還活著，還能站在一幅六十年前和尚畫的舊畫前面，惦記著又要到吃河豚的季節了。跟一個從沒見過面的人隔著六十年的時間對話，蘇軾用的不是傷感的懷念，是一句最實在的，又要開飯了。`
  },

  // id=400 北宋 蘇軾 〈戲贈張先〉rating=4
  // 詩眼：一群老朋友笑著調侃八十歲重新戀愛的老頭，笑聲裡藏的其實是羨慕
  // 隱藏連接：蘇軾與張先為忘年之交，相傳在張先八十納妾的喜宴上即興賦詩調侃
  400: {
    title: "戲贈張先",
    author: "蘇軾",
    summary: "八十歲新郎娶十八歲新娘，蘇軾當場寫詩調侃，卻調侃出了一句流傳千古的成語。",
    story: `跟你說我朋友蘇軾去喝一場很特別的喜酒的事。新郎官八十歲，新娘子十八歲，底下賓客一半在笑，一半在羨慕，蘇軾就坐在其中，喝到興頭上，當場編了一首詩調侃老朋友。

新郎是張先，北宋有名的詞人，寫詞喜歡用影字，一輩子寫出雲破月來花弄影、嬌柔懶起簾押捲花影這類句子，人稱張三影。這位老先生活得長，活到八十八歲，而且一輩子風流，年紀越大，家裡納的妾反而越年輕。這回是他八十歲那年，又新納了一房十八歲的小妾，消息傳出去，親朋好友沒人罵他老不修，反倒一起湊過來喝喜酒，看熱鬧。

蘇軾跟張先差了差不多五十歲，論輩份是晚輩，可兩人交情好，說話沒那麼多顧忌。喜宴上蘇軾看著滿頭白髮的張先，身邊坐著一個十八歲、臉頰紅撲撲的新娘，兩個人年紀差了一甲子還多，場面既好笑又有點動人，這老頭子活到八十歲，心裡那點對生活的興致，居然一點都沒老。

有人起鬨，要蘇軾當場給這對新人寫幾句賀詞。蘇軾也不含糊，提筆就寫：十八新娘八十郎，蒼蒼白髮對紅妝。鴛鴦被裡成雙夜，一樹梨花壓海棠。梨花是白的，海棠是嬌豔的粉紅，一棵開滿白花的老樹，壓在鮮豔的海棠花上頭，這個畫面既是寫實，也是明擺著調侃張先這身雪白頭髮，壓在新娘子的紅顏上。

滿座賓客聽完哄堂大笑，張先自己也笑得合不攏嘴，一點都不覺得被冒犯。這種玩笑能開得起來，是因為底子是真交情，蘇軾這輩子最擅長的就是拿朋友的糗事開玩笑，可是玩笑背後從來沒有真的看輕誰，他打心底佩服張先這把年紀還能這麼熱烈地過日子。後人考證這首詩是不是真出自蘇軾之手，其實仍有爭議，但這段軼事流傳了幾百年，多數人還是把這個玩笑記在蘇軾帳上。

這首詩後來流傳開，梨花壓海棠五個字慢慢變成一句成語，專門用來形容老夫少妻。很多人只記得這句話拿來調侃別人，卻忘了它最早的樣子，是一群老朋友在酒席上，笑著看一個八十歲的老頭重新開始戀愛，誰都沒有真的嘲笑他，反而帶著點羨慕，原來人活到八十歲，還可以這樣不管不顧地，再愛一次。`
  },

  // id=402 北宋 王安石 〈泊船瓜洲〉rating=4
  // 詩眼：被重新召回權力中心的人，望著近在咫尺的家鄉，問自己還回不回得去
  // 隱藏連接：王安石罷相退居鐘山後又被召回拜相，途經瓜洲時反覆推敲綠字的煉字過程確有記載
  402: {
    title: "泊船瓜洲",
    author: "王安石",
    summary: "王安石在瓜洲渡口把一個字改了十幾遍，改到最後才發現自己真正想問的是能不能回家。",
    story: `跟你說我朋友王安石在瓜洲渡口，對著一個字改了十幾遍的事。船已經停了，天黑得差不多了，他還坐在艙裡，拿著筆對著同一句詩，劃了又寫，寫了又劃。

那一年他被神宗重新召回京城拜相。幾年前他因為變法得罪了太多人，先是被罷相，退居到金陵鐘山，過了一段清靜日子，種菜、讀書、跟鄰居老農閒聊，幾乎習慣了那種不當官的生活。忽然一道詔書下來，要他重新出山，他心裡其實五味雜陳，重新掌權當然是機會，可是上一次變法樹敵太多，這次回去，誰知道會不會又是一場硬仗，搞不好比第一次更難收場。

他從江寧出發，沿著長江北上，船行到瓜洲停靠過夜。瓜洲跟京口就隔著一條江，而他心心念念的鐘山老家，算起來也只隔著幾重山，不算太遠。可是他知道，一旦踏進京城那道宮門，再想回鐘山，就不知道是猴年馬月的事了。

隨行的小廝見他遲遲不睡，端了熱茶進艙，順口問了一句，相爺這趟回京，是不是很快又能衣錦還鄉。王安石沒有立刻回答，只是望著艙外漆黑的江面出神。他想起上一次變法，多少新政推行到一半就被人攔腰砍斷，多少同僚因為站在他這邊被連累貶官，他心裡清楚，這一次回去，未必比上一次輕鬆。

他望著江對岸，想寫下此刻的心情，先寫春風又到江南岸，覺得到字太平淡，劃掉；改成過，過字太快，一晃就沒了，還是不滿意；又試了入、滿，都覺得少了點什麼。他反覆念著，想像的是離開鐘山那天，院子裡的草木還是冬天的枯黃色，如果這時候春風吹過江南，那些山頭應該已經整片整片地綠起來了。他要的不是風吹過的動作，是那片綠色鋪滿眼前的畫面。最後他寫下綠字，把風寫成了一個動詞，一夜之間把江南岸染綠。

他提筆寫完整首：京口瓜洲一水間，鐘山只隔數重山。春風又綠江南岸，明月何時照我還。前面兩句在算距離，近得幾乎伸手可及，最後一句卻是在問一個沒有答案的問題，他不知道這一去要幾年，不知道這次變法能不能成，更不知道自己還能不能像春風一樣，說回就回去。

後來他真的又做了幾年宰相，又是一輪風雨，新法幾度反覆，他晚年還是回到了鐘山，終老在那裡。那晚在瓜洲改了十幾遍的一個字，後人拿出來當作煉字的範本反覆稱讚，可是對王安石自己來說，那個晚上他要的從來不是一個漂亮的字，只是想確認，家鄉的春天，真的能等到他回去的那天。`
  },

  // id=405 南宋 朱熹 〈春日〉rating=4
  // 詩眼：一個理學家因為聖地淪陷異國、終身去不了，只能用想像完成一趟朝聖
  // 隱藏連接：泗水一帶在南宋時已被金國佔領，朱熹終身未曾親至孔子講學之地，這趟遊春純屬神遊
  405: {
    title: "春日",
    author: "朱熹",
    summary: "這首人人會背的遊春詩，其實寫的人一輩子都沒能踏上那片土地。",
    story: `跟你說我朋友朱熹寫過一首春遊詩，可是他寫這首詩的時候，人根本沒有離開過家。

這件事聽起來有點矛盾，詩裡明明寫著他在泗水邊賞花，陽光正好，風景一片新綠，萬紫千紅開得到處都是，怎麼看都是實實在在出去玩了一趟。可是泗水在山東曲阜附近，是孔子當年講學的地方，而朱熹活在南宋，那時候整個中原、包括山東在內，早就被金國佔去了。一個南宋的讀書人，想去泗水邊踏青，得先過長江，再過淮河，一路穿過敵國防線，這是完全不可能的事。朱熹這輩子，從來沒能踏上那片土地一步。

他心裡其實一直有個過不去的坎。他一輩子讀聖賢書，講理學，教弟子，認的祖師爺就是孔子，可是孔子講學的地方，如今是異族的疆土，連去看一眼、去孔廟磕個頭，都成了奢望。這種求道求了一輩子，卻連源頭都摸不到的感覺，他沒辦法對誰明說，只能自己憋著。

有個弟子曾經問他，先生講學總說要親近聖人之道，那我們什麼時候能去泗水邊、去曲阜看看孔夫子講學的地方。朱熹當時沉默了很久，才緩緩說，山河阻隔，去不了的地方，未必就摸不著它的道理。弟子聽得似懂非懂，朱熹自己心裡卻比誰都清楚，這句話說出口，一半是安慰學生，一半是安慰自己。

有一年春天，他坐在自己的書齋裡，窗外剛好風和日暖，他忽然起了個念頭，身子過不去，心可以先過去。他閉上眼睛，想像自己真的走在泗水邊，趁著這個難得的好天氣去尋訪春天的蹤跡，眼前無邊無際的風景一下子全都煥然一新。原本平常到不會特別留意的東風，這一刻卻好像第一次被他認出了模樣，也才明白過來，那萬紫千紅開得漫山遍野的花草，說到底，不過都是同一個春天的臉。

他把這趟只在心裡走過的旅程寫下來：勝日尋芳泗水濱，無邊光景一時新。等閒識得東風面，萬紫千紅總是春。字面上是遊春，他心裡想的，其實是求道，那個東風，是聖人的教化；那片萬紫千紅，是他讀過的千經萬典，說到底都通向同一個道理。

朱熹終其一生沒能踏上北方那片土地，泗水濱他去不了，曲阜的孔廟他拜不了。可是這首詩留下來以後，反而變成後世小孩子最早學會的春天詩，大家念著萬紫千紅總是春，想的都是真的去踏青賞花。沒有人知道，寫下這幾句話的人，其實從頭到尾，只是坐在自己書齋的窗邊，神遊了一趟他這輩子去不了的遠方。`
  },

  // id=406 南宋 陸游 〈冬夜讀書示子聿〉rating=4
  // 詩眼：一個一輩子只能在紙上打仗的人，教兒子紙上談兵沒有用
  // 隱藏連接：陸游四十八歲曾在南鄭前線短暫從軍四十多天，是他一生唯一躬行戰場的日子
  406: {
    title: "冬夜讀書示子聿",
    author: "陸游",
    summary: "教兒子要親自實踐的陸游，自己這輩子只有四十幾天真正上過戰場，其餘都在紙上打仗。",
    story: `跟你說我朋友陸游七十五歲那年冬夜，把小兒子叫到跟前說的一句話。子聿當時正埋頭苦讀，想在書本裡把天下道理都弄懂，陸游看著他，忽然問了一句，你這些年讀的書，有哪一句是你自己真的做過的？

子聿一時答不上來。陸游沒有責怪他，只是坐下來，慢慢說起自己年輕時候的事。

陸游這輩子最想做的一件事，是上戰場，把被金人佔去的中原打回來。可是他大半輩子只能在紙上喊，在詩裡罵，真正離戰場最近的一次，是四十八歲那年，在四川南鄭投效宣撫使王炎的幕府。那四十幾天，他真的騎過馬，穿過鎧甲，在渭水前線望過對岸金兵的旗幟，甚至還親手獵過老虎。這是他一輩子唯一一段真刀真槍的日子。可惜沒多久王炎被調走，幕府解散，他也跟著調任閒職，從此再沒機會回到前線。往後幾十年，他寫了幾千首詩，鐵馬冰河入夢來，王師北定中原日，這些句子寫得慷慨激昂，可寫的人自己心裡最清楚，那些畫面都只存在紙上，他再也沒能真的躬行一次。

坐在冬夜的燈下，他想起自己曾經以為，讀懂兵書、寫透詩文，就等於懂了天下事。直到南鄭那四十幾天，他才知道，紙上的兵法跟真正上馬打仗，完全是兩回事。他記得有一次跟著斥候夜巡，馬蹄踩在結冰的河灘上，四周黑得伸手不見五指，那種真實的緊張，是他讀再多兵書都想像不出來的。他不希望子聿走他的老路，把一輩子力氣都花在紙上，卻沒有機會，或者沒有勇氣去真正做一次。

他對子聿說，古人做學問，沒有一個是輕輕鬆鬆的，年輕時候下的工夫，往往要到老了才真正有點成就。他頓了一下，想起南鄭那段日子，又補了一句，書上讀來的東西，終究是淺的，真正要弄懂一件事，得自己去做過才算數。他提筆把這幾句話寫下來：古人學問無遺力，少壯工夫老始成。紙上得來終覺淺，絕知此事要躬行。

子聿後來把這句話記了一輩子。陸游自己直到八十五歲過世，也沒能等到北伐成功的那天，示兒詩裡還在交代家人，王師北定中原日，家祭無忘告乃翁。可是那個冬夜他教給兒子的道理，他自己在南鄭前線的四十幾天裡，是真正做到過的，這輩子只有那一次，他不是在紙上打仗。`
  },

  // id=407 南宋 楊萬里 〈小池〉rating=4
  // 詩眼：曾經滿紙用典的詩人，後來學會了把眼睛留給一片荷葉尖角
  // 隱藏連接：相傳楊萬里曾焚毀早年模仿江西詩派、堆砌典故的舊稿千餘首，轉而師法自然
  407: {
    title: "小池",
    author: "楊萬里",
    summary: "他先燒掉了一千多首堆滿典故的舊詩，才學會蹲在池塘邊看一隻蜻蜓搶先停上荷葉尖角。",
    story: `跟你說我朋友楊萬里燒掉自己一千多首詩那件事，跟他後來寫小池，其實是同一個故事的前後兩半。

楊萬里年輕時候學寫詩，學的是江西詩派那一套，講究字字有來歷，句句要用典，一首詩裡塞滿了前人的句子和學問。他寫了很多年，寫了一千多首，某一天忽然覺得不對勁，這些詩堆滿了典故，讀起來卻一點都不像他自己說話的樣子。他把這些年寫的舊稿翻出來，一把火全燒了，誰勸都不聽。

燒完稿子那天，有個學生跑來勸他，說那些詩好歹也是心血，燒了太可惜。楊萬里搖搖頭，說留著也是騙自己，寫得再工整，裡頭沒有一句是真的看見了什麼，不如燒乾淨，重新學怎麼睜眼睛看東西。

燒完稿子之後，他開始重新學著寫詩，可是這次他不再往書本裡找材料，他往自己家院子裡找。院子角落有個小池塘，平常沒什麼人在意，他倒是常常一個人蹲在池邊，一看就是老半天，家裡人起初還笑他，一個做過官的讀書人，怎麼跟小孩子一樣蹲在水邊發呆。

有一年初夏，他又蹲在池邊。池水是從一道細細的泉眼裡滲出來的，流量小得幾乎沒有聲音，好像連泉水自己都捨不得往外流。池邊有棵樹，枝葉的影子倒映在水面上，被曬得暖洋洋的水波看起來也跟著柔和了起來。他正看得入神，忽然注意到水面上冒出一片才剛剛捲起、還沒展開的小荷葉，尖尖的一個角剛探出水面沒多久。

就在這片荷葉冒尖的瞬間，他看見一隻蜻蜓，不知道什麼時候已經穩穩停在那個尖角上頭了，比誰都快，比誰都早，搶在荷葉還沒完全展開之前，就先佔了那個位置。

楊萬里看呆了。以前他寫詩，腦子裡想的都是該用哪個典故、哪句前人的話能撐場面；這一刻他眼前只有一片剛冒尖的荷葉和一隻蜻蜓，什麼典故都用不上，可是這個畫面比他寫過的任何一句用典的詩都更讓他捨不得移開眼睛。他把這個瞬間原封不動地寫下來：泉眼無聲惜細流，樹陰照水愛晴柔。小荷才露尖尖角，早有蜻蜓立上頭。

這首詩後來被歸進他自成一家的誠齋體，人人都說他寫景寫得細膩生動。可是很少人記得，能寫出這樣一隻蜻蜓的楊萬里，是先燒掉了滿滿一千多首堆砌典故的舊詩，才學會蹲在自家池塘邊，把眼睛留給一片荷葉尖角的。`
  },

  // id=408 南宋 葉紹翁 〈遊園不值〉rating=4
  // 詩眼：被拒在門外的失落，卻在牆角意外看見了關不住的春天
  // 隱藏連接：無（葉紹翁生平史料不足，友人身分不可考，僅以相傳處理拜訪情境）
  408: {
    title: "遊園不值",
    author: "葉紹翁",
    summary: "敲了半天門沒人應，轉身要走時卻看見一枝紅杏探出牆頭，原來被拒之門外也能撞見更好的風景。",
    story: `跟你說我朋友葉紹翁吃了一次閉門羹，反而覺得很值得的事。

那天他去拜訪一位交情不錯的朋友，這人在城裡有座小園子，平常深居簡出，不太愛應酬，葉紹翁偶爾去看看他，也算是老交情了。巷子很窄，兩旁的牆頭都爬滿了藤蔓，走到底才看見那扇低矮的柴門，門板已經有些斑駁，看得出很久沒有人常來常往。他一路走到朋友家門口，鞋底那木頭屐齒踩在潮濕的青苔上，留下一排淺淺的印子。他心裡想，這園子的主人大概也捨不得讓人踩壞這片苔蘚，所以才這麼少有人來訪，這片青苔長得這麼厚實均勻，想必平日裡也真的沒什麼人踏進來過。

他站在柴門前，輕輕敲了幾下，等了一會兒，沒人應。他側耳聽了聽，園子裡靜悄悄的，連狗叫聲都沒有。他又敲了幾下，還是沒有動靜。他猜這位朋友大概是存心不想被打擾，這種深居簡出的人，有時候就是想一個人待著，連朋友上門也不一定想開門，倒也不是什麼稀奇事。他站在門外又等了片刻，心裡盤算著要不要再多敲幾下，最後還是決定算了，硬闖進去打擾人家清靜，反而失了禮數。

葉紹翁沒有多想什麼，也沒生氣，只是有點失落地準備轉身離開。就在他快要走出巷口的時候，一抬頭，看見牆頭伸出一枝紅色的花，是杏花，不知道是長得太茂盛，還是園子裡春色太滿，竟然探出牆外，開在了誰都能看見的地方。

他站在牆外看著那枝紅杏，忽然覺得剛才那種被拒之門外的失落感，一下子淡了下去。他想，任憑主人把柴門關得再緊，把滿園的春色關在裡頭，終究還是關不住，只要春天到了，總會有一枝花，自己找到一個縫隙，探出頭來讓人看見。

他站在原地把這個念頭寫成了詩：應憐屐齒印蒼苔，小扣柴扉久不開。春色滿園關不住，一枝紅杏出牆來。前兩句寫的是他吃的這頓閉門羹，後兩句卻是他自己想通了的答案，你關得住一扇門，關不住整個春天。

葉紹翁這個人，史書上留下的記載不多，連他本來姓李、後來過繼給葉家的身世，都是後人拼湊出來的。可是這首因為敲不開一扇門而寫成的詩，卻流傳了八百多年。後來的人讀到這首詩，大概都不會記得他那天有沒有見到朋友，只會記得那枝紅杏，原來被擋在門外，有時候反而看見了比開門更好的風景。`
  },

  // id=409 明 于謙 〈石灰吟〉rating=4
  // 詩眼：十二歲寫下的少年豪語，四十多年後被自己用生命兌現成真
  // 隱藏連接：無（石灰吟本身即是于謙一生真實遭遇的寫照，非虛構連接）
  409: {
    title: "石灰吟",
    author: "于謙",
    summary: "十二歲寫下粉身碎骨全不怕的少年狂語，四十多年後，他真的用性命把這句話還給了世界。",
    story: `跟你說我朋友于謙十二歲那年寫的一首詩，四十多年後，他真的把這首詩活成了自己的一生。

那年他跟著大人去看石灰窯燒石灰。石灰石本來就是深山裡再普通不過的一塊石頭，要經過千百次的錘打鑿鑽才能開採出來，運到窯裡之後，還得放進烈火裡整整燒上幾天幾夜，燒到石頭整個崩解、粉碎，最後才變成雪白的石灰粉，可以拿去砌牆刷牆。十二歲的于謙站在窯邊看著這個過程，看得比誰都專注。旁邊的大人只顧著閒聊，沒人多留意這個安靜的孩子在想什麼。別人看的是工匠怎麼幹活，他看的卻是那塊石頭，千錘萬鑿都不喊疼，烈火焚燒也跟沒事一樣，就算最後粉身碎骨，好像也一點都不怕，為的不過就是要在人間留下一片乾乾淨淨的白。他站在那裡想了很久，覺得一塊石頭尚且能這樣豁得出去，人活一輩子，怎麼可以連一塊石頭都不如。

他當場把這個念頭寫成了詩：千錘萬鑿出深山，烈火焚燒若等閒。粉身碎骨全不怕，要留清白在人間。旁邊大人聽了都笑，說這孩子小小年紀口氣倒不小，將來要嘛做大官，要嘛惹大禍。于謙也跟著笑了笑，沒有多解釋什麼。誰都沒把這幾句話當一回事，以為不過是小孩子讀書讀多了，學著寫幾句豪言壯語，過幾年自己都會忘記。

沒有人想到，這幾句話後來會變成一句讖語。于謙長大後做到兵部尚書，正統十四年，皇帝御駕親征瓦剌，結果在土木堡全軍覆沒，連皇帝自己都被俘虜，朝廷亂成一團，好多大臣主張遷都南逃。于謙站出來，力主堅守北京，擁立新君，親自督戰，硬是把瓦剌大軍擋在城外，保住了大明江山沒有像南宋一樣被逼著南遷。

可是保住了國家的于謙，後來卻在一場宮廷政變裡被誣陷謀反，判了死刑。抄他家的時候，官差原本以為能搜出多少金銀財寶，這麼大的功臣，做了這麼多年的兵部尚書，家裡卻幾乎什麼值錢東西都沒有，只有皇帝當年賜下的一件蟒袍和一把寶劍，鎖在正屋裡，連個像樣的箱子都配不上。

那一刻，所有人才想起他十二歲寫下的那首詩。千錘萬鑿，烈火焚燒，粉身碎骨，這些原本只是少年人隨口說說的狠話，他用整整一輩子去把它兌現了。他真的不怕粉身碎骨，也真的什麼都沒留下，除了那一片，他堅持要留在人間的清白。`
  },

  // id=411 清 鄭燮 〈竹石〉rating=4
  // 詩眼：一個因為救人而丟官的縣令,用畫裡扎在石縫中的竹子告訴世人他沒被壓垮
  // 隱藏連接：相傳彈劾消息傳來那天,他站在濰縣衙門後院看著石縫裡的竹子,提筆畫下此圖並題詩明志
  411: {
    title: "竹石",
    author: "鄭燮",
    summary: "他因為擅自開倉救飢民而被彈劾罷官,罷官前,他畫了一叢長在石頭縫裡的竹子,說那就是他自己。",
    story: `跟你說我朋友克柔,在濰縣衙門後院種了一小叢竹子的故事。乾隆年間鬧大饑荒的那個冬天,城外的災民一批一批湧進城裡討飯,有人已經餓死在城門口,屍體用草蓆一裹就地掩埋。他站在後院那叢竹子前面看了很久很久,看到後來,提筆畫了一張畫。

鄭燮這個人你可能更熟悉他另一個名字,鄭板橋。他是江蘇興化人,四十四歲才中進士,考了大半輩子的科舉,家境一直不寬裕,深知窮人日子有多難熬。後來他在山東范縣、濰縣當過知縣。他這個人有個毛病——太把百姓的命當回事。乾隆十一年,濰縣大旱,糧價漲到平常的十倍,路上到處是餓死的人。師爺勸他,按規矩,開官倉放糧要先層層上報,等公文批下來,少說也要一兩個月,可是這一兩個月裡不知道要餓死多少人。鄭燮沒等公文。他直接下令開倉,先救人,事後自己扛責任,還把自己的部分俸祿也拿出來買糧。

這一開倉,救活了濰縣好幾萬條命,也把自己架在火上烤。上級官員最恨的就是不按規矩來的下屬,尤其是這種做對了事、卻讓所有人顯得無能的下屬。彈劾的奏摺一份一份遞上去,說他擅權、說他目無上官,連他修的水利工程都被人挑毛病。鄭燮心裡清楚,這一仗他大概贏不了,但他從沒後悔那個決定。

据說彈劾的消息傳來那天,他一個人站在後院,看著石頭縫裡硬生生鑽出來的一叢竹子。那塊石頭又硬又擠,竹根卻偏偏往那裡扎,一年一年長,長得比種在肥土裡的竹子還挺。風一吹,竹葉沙沙作響,竿子卻紋絲不動。他站在那裡想,自己這輩子大概就是這樣——擠在誰都不肯讓路的縫裡,還得站得比誰都直,還不能倒。

他鋪開紙,提筆畫下那叢竹石,題了四句:

咬定青山不放鬆,立根原在破巖中。千磨萬擊還堅勁,任爾東西南北風。

不久之後,他真的被罷了官,沒有退休金,也沒有安置,五十幾歲的人,拍拍身上的灰,回揚州靠賣畫過日子。他成了後來人們說的"揚州八怪"之一,身邊沒有靠山,也沒有官印了,可是他把這幅竹石圖帶在身邊,一畫再畫,一題再題,賣給揚州城裡識貨的商人換米糧。他畫的那叢竹子,比在濰縣當官時畫得更挺、更硬。千磨萬擊,他是真的撐過來了,而且沒把自己撐彎。`
  },

  // id=418 盛唐 李白 〈菩薩蠻〉rating=4
  // 詩眼：一首連作者是誰都吵了千年的詞,寫一個在樓上等人等到絕望的女子
  // 隱藏連接：相傳為李白所作,但盛唐詞體尚未成熟,真正作者至今仍是文學史懸案
  418: {
    title: "菩薩蠻",
    author: "李白",
    summary: "這首詞掛著李白的名字流傳千年,連學者都吵不清楚是不是他寫的——但樓上那個等人等到絕望的女子,騙不了任何人。",
    story: `跟你說一個連我都搞不清楚是不是我朋友太白寫的故事。這首菩薩蠻,詞牌底下明明白白寫著他的名字,可是打從宋朝開始,就有人吵——盛唐哪來的詞這種文體,不是該再晚個一百多年才成熟嗎?這樁公案吵了快一千年,誰也沒能拿出鐵證。

先不管這樁公案,你且看看詞裡那個畫面。黃昏,一片平坦的樹林籠罩在像織布一樣密的煙裡,遠山連綿一整排,顏色藍得讓人心裡發疼。暮色一點一點爬上高樓,樓上有個人,愁著。她扶著玉石欄杆站了很久很久,久到腳下的石階彷彿都染上了她的等待。歸巢的鳥一隻一隻急急忙忙飛過天空,趕著回家,一隻接一隻,天色越暗,飛得越急。她卻不知道自己等的人,這會兒人在哪一段路上,是已經上路,還是根本還沒動身。她不是普通人家的女子,玉階、高樓,這種規格顯然是官宦門第,能推想她等的多半是遠行趕考或戍邊的丈夫。她從白天等到黃昏,又從黃昏等到暮色完全籠罩,茶涼了好幾回,人還是沒有半點消息,只能眼睜睜看著別人家歸巢的鳥都到家了。

這首詞最早收在北宋人編的集子裡,題著太白之名,後人稱它跟另一首憶秦娥是"百代詞曲之祖"——意思是後世所有的詞,往上追根,都追得到這兩首。這個名號夠響亮,響亮到沒人捨得輕易否定它。可是學者翻遍太白現存的詩文集,找不到第二首風格相似的長短句,越查越覺得像是後人假托他的名字寫的,借重他的聲望流傳下去,至今仍是文學史上的一樁懸案。

不管作者到底是誰,這個人肯定懂什麼叫做等一個人等到絕望。他寫樓上的女子,不寫她哭,只寫她問一句話:哪裡才是回家的路?

何處是歸程,長亭更短亭。

一程接一程的長亭,一程接一程的短亭,望不到盡頭。這句詞流傳了一千多年,沒人知道原作者到底是誰在等,又在等誰。可是每一個在異鄉趕路、盤算著還要過幾個驛站才能到家的人,讀到這一句,都會突然停下腳步,想起自己也曾經是那個數著長亭短亭的人。真正的作者也許永遠是個謎,但這份望穿秋水的心情,顯然騙不了任何人,也不需要一個確切的名字來替它背書。`
  },

  // id=419 盛唐 李白 〈憶秦娥〉rating=4
  // 詩眼：一首詞從兒女私情寫起,幾句話後鏡頭忽然拉遠到整個王朝的廢墟
  // 隱藏連接：相傳為李白所作,身世同樣成謎,後人猜測是中晚唐人假托其名寫下的亡國之嘆
  419: {
    title: "憶秦娥",
    author: "李白",
    summary: "簫聲響起是兒女私情,西風殘照卻是整個帝國的廢墟——這首詞用幾十個字,把個人的等待寫成了王朝的輓歌。",
    story: `跟你說另一首掛在我朋友太白名下、身世同樣成謎的詞,連詞牌的來歷都要牽扯上一段古老傳說。這首憶秦娥比菩薩蠻更誇張——它前面幾句寫一場小小的兒女私情,寫到最後兩句,鏡頭忽然拉到了幾百年前一整個王朝的廢墟。

詞的開頭,一縷簫聲嗚咽著響起,聲音低沉,像是含著什麼說不出口的心事。相傳吹簫的是秦穆公的女兒弄玉,她在秦樓上,夢裡驚醒,望著那輪照過秦樓的月亮出神,一夜沒能再睡著。年年柳色依舊,年年都在灞陵橋頭送人離別——長安人送客有個習慣,走到灞橋就折一段柳枝送給遠行的人,柳跟留同音,算是挽留的意思。這位女子大概也曾在灞橋折柳送別過什麼人,從此音信全無,一年一年地等,柳條年年綠了又枯,人卻始終沒有回來。

後世給這首詞的評價高得嚇人,稱它跟菩薩蠻一起撐起了詞這個文體最早的源頭,可是也正因為寫得太老練、太蒼涼,不像是一個剛誕生的文體該有的青澀模樣,懷疑的聲音才始終沒停過。

上半闋還只是一個人的相思,下半闋忽然跳到樂遊原上一個清秋的節日,遊人如織,熱鬧得很,車馬絡繹不絕,像是要把上半闋的傷心一筆抹去。可是鏡頭再往遠拉——通往咸陽的古道上,再也沒有一絲行人的動靜和消息。音塵斷絕四個字重複念一次,像是把最後的希望徹底掐斷。最後兩句,鏡頭拉到最遠最冷:西邊的風,照著殘破的落日餘光,照著漢朝那些皇帝的陵墓,空空蕩蕩杵在那裡,沒有一個人守著。

西風殘照,漢家陵闕。

一首詞從兒女情長寫到帝國興衰,只用了寥寥數十個字,轉折大得驚人,這也是後人懷疑它未必出自盛唐、更像是歷經滄桑之後才寫得出的手筆的原因之一。有人猜是中晚唐人假托太白之名寫成,藉著他的聲望,把亡國之痛悄悄夾帶出去流傳下來,也有人猜是更晚的五代文人,眼看著一個又一個王朝崩塌,親身經歷過城破家亡,才寫得出這種蒼老的口氣。是誰寫的,一千多年來誰也沒有確切答案。但那句西風殘照,從此變成所有人講述繁華落盡的固定畫面——不管出自誰的手筆,那份蒼涼是真的,誰念起來都會沉默一下。`
  },

  // id=421 中唐 白居易 〈憶江南〉rating=4
  // 詩眼：一個老人閉著眼睛都能精準說出的顏色記憶,證明那個地方真的刻進了骨頭裡
  // 隱藏連接：晚年定居洛陽與劉禹錫比鄰而居,兩人互相唱和填寫同一詞牌的憶江南
  421: {
    title: "憶江南",
    author: "白居易",
    summary: "他已經六十幾歲、離開江南幾十年了,可是只要一提起江南,他立刻能準確說出那裡的太陽是什麼顏色。",
    story: `跟你說我朋友樂天晚年在洛陽,一閉上眼睛就能精準說出江南顏色的故事。他已經六十幾歲了,腿腳不好,眼睛也花了,連提筆寫字都要人扶著手腕,可是只要有人提起江南,他立刻能講出那裡的太陽是什麼顏色,那裡的水是什麼顏色——準得像昨天才去過。

樂天年輕時沒去過江南做官,他真正跟江南結緣,是五十歲以後的事。他先當杭州刺史,任內修了一條堤——後人叫它白堤——蓄水灌田,救了不少乾旱的年頭,還常常騎馬繞著西湖巡視,看哪裡淤積了要清。三年後他又調到蘇州當刺史,雖然只做了一年多就因病辭官,但那段時間他幾乎走遍了姑蘇城裡城外的河道園林,連哪座橋邊種了什麼花都記得住。

離開江南以後,他輾轉洛陽、長安,官越做越大,官場的應酬越來越多,可他心裡總惦記著杭州、蘇州那兩年。他常跟晚輩提起錢塘江的潮水多壯觀,提起靈隱寺後山的桂花香得能飄進夢裡,說著說著自己都會笑出來,像是又活了一次那段日子。晚年他定居洛陽,和劉禹錫是鄰居也是老友,兩個人常常喝著酒聊起江南舊事,聊到最後乾脆比賽似地各自填起了同一個詞牌,一寫就是好幾首,互相唱和,誰也不服誰寫得比較好。

樂天寫的第一首,劈頭就是三個字的斷言,不是猜測,不是懷念的語氣,是斬釘截鐵的判斷:江南好。好在哪裡?他挑了兩個最極端的顏色去比——太陽出來的時候,江邊的花紅得像火燒起來一樣;春天江水漲起來,綠得像藍草染出來的顏色。這兩句擺在一起念,眼睛裡幾乎能看見那片紅配那片綠,鮮明得不像是回憶,倒像是正看著。

江南好,風景舊曾諳。日出江花紅勝火,春來江水綠如藍。能不憶江南?

這五個字的反問,他寫得雲淡風輕,底下卻是幾十年反覆咀嚼過的心情。寫完這句反問,他其實沒指望誰回答。那年他人在洛陽,離杭州幾千里,腿腳已經走不了那麼遠了,連想再去看一眼白堤都是奢望。可是只要顏色還記得那麼準,那個地方就沒有真正離開過他。後來劉禹錫也寫了三首憶江南應和他,兩個老頭隔著詞牌互相確認:我們都還記得,誰也沒把江南忘掉,這比誰能不能再回去,重要多了。`
  },

  // id=423 中唐 張志和 〈漁歌子-西塞山前白鷺飛〉rating=4
  // 詩眼：一個把烏紗帽換成蓑衣的人,用一句不須歸回答所有勸他回朝的人
  // 隱藏連接：與顏真卿是朋友,顏真卿任湖州刺史時想幫他換新船,他寫此詞婉拒
  423: {
    title: "漁歌子-西塞山前白鷺飛",
    author: "張志和",
    summary: "老朋友顏真卿看他的船破舊漏水,想幫他換一艘新的,他寫了一首詞回應——他根本不打算回去了。",
    story: `跟你說我朋友子同把烏紗帽換成蓑衣以後的一個下雨天。那天他撐著一艘小船,停在西塞山前的水面上,看白鷺一隻一隻飛過去,看桃花瓣被水沖著漂,水裡的鱖魚肥得很,他釣竿都懶得認真甩,就這麼晃著,雨絲斜斜地打在斗笠上,一點都不覺得冷,反而覺得這種天氣最適合什麼都不做。

張志和年輕時很風光,十六歲就考中科舉,唐肅宗還親自賜他"志和"這個名字,派他做官,前途看起來一片光明。可是官場沒讓他待多久,他因事被貶了一次官,眼看著同僚為了升遷爾虞我詐,他心裡越來越不是滋味,從此心灰意冷,索性連官都不要了,把船一買,自稱"煙波釣徒",在江湖上四處漂,想去哪就去哪,想停就停,身邊也不帶什麼行李,一副蓑衣一頂斗笠就是全部家當。

他跟顏真卿是朋友。顏真卿後來做了湖州刺史,張志和撐著船晃過去看他。顏真卿一看,老朋友的船破得不成樣子,底下漏水,篷子也補丁摞補丁,心裡過意不去,提議要幫他換一艘新船,還說自己認識一個造船的師傅,幾天就能交船。張志和婉拒了,還提筆填了幾首漁父詞回應,一邊寫一邊笑,說這艘船漏得剛剛好,這首西塞山前白鷺飛就是其中最有名的一首。

詞裡他把眼前的畫面一件一件擺出來:西塞山前白鷺展翅飛過,桃花瓣落進水裡跟著流,水裡的鱖魚養得又肥又壯,連釣客都懶得跟牠們較勁。他自己頭上戴著青色的箬笠,身上披著綠色的蓑衣,任憑斜風細雨打在身上,一點都不急著回去。

青箬笠,綠蓑衣,斜風細雨不須歸。

這四句唱給顏真卿聽的時候,張志和連釣竿都沒放下,語氣輕輕鬆鬆,像是隨口一提,可是話裡的意思誰都聽得懂。顏真卿聽完大概就懂了,不用再勸換船的事,那艘破船對他來說剛剛好,能載他去想去的水面就夠,兩人喝了一整晚的酒,誰也沒再提造新船的事。張志和後來一直沒再回朝廷,四十來歲的時候,相傳一次泛舟時落水,再也沒上岸——他這一生,好像從那句"不須歸"開始,就沒打算走回頭路。那艘破船漏了一輩子的水,卻從沒漏掉他想要的自由,直到最後一刻。`
  },

  // id=424 晚唐 韋莊 〈菩薩蠻（其三）〉rating=4
  // 詩眼：一個亂世流亡者,用發誓不再回去把思鄉的念頭鎖起來,因為想起來太痛
  // 隱藏連接：親歷黃巢之亂逃亡江南,晚年入蜀終老成都,終究沒能再回中原
  424: {
    title: "菩薩蠻（其三）",
    author: "韋莊",
    summary: "他晚年在蜀地寫下這首詞,回憶年輕時江南的花天酒地,寫到最後卻是一句給故鄉的訣別誓言。",
    story: `跟你說我朋友端己,一個發誓再也不回家的人的故事。他晚年在蜀地寫了一組五首菩薩蠻,一首一首回頭看年輕時候的江南,這是其中第三首。他寫的時候心裡明白,自己這輩子大概是回不去中原了,寫這首詞,幾乎是跟自己攤牌。

韋莊年輕時候,趕上了黃巢之亂。長安城被攻破那幾年,他人就在戰火邊上,親眼見過屍橫遍野的慘狀,家人也在戰亂中失散,連生死都好一陣子沒有消息,後來寫了一首長詩秦婦吟,把亂世寫得太真實,一時傳遍天下,一度連他自己都不太願意再提起裡面的細節。戰亂之後,他一路往南逃,在江南漂泊了好幾年,靠著幾個地方官朋友接濟過日子,居無定所,今天在這座城,明天可能又要換一個地方落腳。

那幾年他還年輕,春衫穿得很薄,騎著馬倚在小橋邊,滿樓的歌伎探出頭來招手叫他上去。畫著金色花紋的翠綠屏風後面,他喝醉了就地睡下,醒了接著喝,誰也不去想明天的事。那是他一生裡少數不用擔心明天的日子,是亂世之中偷來的一段浮華,他自己也知道這種日子不長久,只是捨不得先醒過來。

後來他年紀大了,河北中原還在打仗,故鄉音信斷絕,連想寄一封信回去都找不到人送,他輾轉入蜀投靠割據一方的王建,起初只是幕僚,慢慢才因為文才受重用,一路做到宰相,老死在成都,終究沒能再回中原一步。晚年他坐下來寫這組菩薩蠻,寫著寫著就寫到了當年江南的花天酒地,寫到如今又見到滿樹花開,忽然一句話衝口而出:

此度見花枝,白頭誓不歸。

這句話聽起來像是說給江南的舊人聽的,其實他心裡想的是整個回不去的中原。故鄉已經是別人的天下,再想回去也沒有意義了,不如把這份念想連根拔起,發誓不回去,反而還輕鬆一點。他這一生從長安逃到江南、又從江南逃到蜀地,終於在這句誓言裡,給自己的漂泊找了個可以停下來的理由,也給自己一顆不敢再想家的心,找了個不用再痛的交代。多年以後蜀地的人讀這首詞,只當是一個老臣在懷念少年風流,沒幾個人猜得到,那句誓言底下埋著的,是一整座他再也踏不進去的長安城。`
  },

  // id=425 晚唐 韋莊 〈菩薩蠻（其四）〉rating=4
  // 詩眼：亂世裡今朝有酒今朝醉不是頹廢,是一個見過長安淪陷的人唯一能抓住的東西
  // 隱藏連接：與前一首菩薩蠻同組,寫作背景同為親歷黃巢之亂後在江南漂泊的歲月
  425: {
    title: "菩薩蠻（其四）",
    author: "韋莊",
    summary: "他勸酒席上的朋友今晚喝醉,不要談明天的事——因為他親眼見過,明天從來不是理所當然會到來的東西。",
    story: `跟你說我朋友端己勸朋友喝酒的一個晚上。那不是普通的勸酒,是亂世裡的勸酒——他跟座上的人心裡都清楚,誰都說不準明天會發生什麼事,今晚能坐在一起喝酒,已經是運氣,誰也不敢保證下個月還能不能再見面。

這是他菩薩蠻組詞裡的第四首。前一首他才剛發誓白頭不歸,語氣還帶著決絕,這一首調子忽然一轉,變成了勸酒的口氣。端己一輩子躲過黃巢之亂的戰火,見過長安城破的樣子,見過原本錦衣玉食的人一夕之間變成路邊的屍體,見過昨天還在的鄰居,今天就不知去向,甚至有一段時間連家人都失散在逃難的路上,音信全無。這種經歷之後,他對"明天"這兩個字,已經沒辦法再輕易相信了。

那晚不知道是在江南哪一處酒席上,燈火搖曳,絲竹聲斷斷續續傳來,他舉杯對著同座的人說,今晚你就痛痛快快喝醉吧,不要在酒杯前面談論明天的事。這話聽起來像及時行樂的老套,可是從一個親眼見過長安淪陷的人嘴裡說出來,分量完全不一樣——明天從來不是保證會來的東西,昨天的太平日子說沒就沒了。

他接著說,今晚承蒙主人一片心意,能坐在這桌上的都是懂得彼此處境的人,大家要好好珍惜這份情誼,酒喝得深,情也喝得深。他勸座上人不要愁著更漏太短、天快亮了,也不要推辭酒杯已經斟得太滿——與其愁著時間不夠用,不如趁著還在,把眼前這杯喝完,把眼前這群人記住,誰知道下次還能不能再聚齊。

勸君今夜須沉醉,樽前莫話明朝事。遇酒且呵呵,人生能幾何。

那個"呵呵"兩個字用得很輕,像是硬擠出來的笑聲,底下藏著的其實是他不敢說出口的憂慮。他一邊笑一邊給身旁的人斟酒,手卻頓了一下,像是想起了什麼不願意細想的畫面。同座的人也許沒人真的聽懂這句笑聲底下的重量,只當他是喝多了才這麼說。這一組菩薩蠻寫到這裡,從追憶江南舊夢,寫到勸人及時行樂,說穿了都是同一件事:他把回不去的故鄉和靠不住的明天,一起打包收進了這杯酒裡,喝下去,好歹今晚是真的,好歹這杯酒是真的,好歹眼前的人也是真的,這就夠了。`
  },

  // id=437 北宋 蘇軾 〈江城子-乙卯正月二十日夜記夢〉rating=4
  // 詩眼：一個十年不敢細想亡妻的人,被一場夢打回原形,才發現自己這十年老得多快
  // 隱藏連接：妻子王弗葬於四川眉山,蘇軾親手在墳邊種下三萬棵松樹
  437: {
    title: "江城子-乙卯正月二十日夜記夢",
    author: "蘇軾",
    summary: "妻子死後十年,他沒敢細想過她。直到密州的一個正月夜裡,他夢見她仍在梳妝,而自己已經滿臉風霜。",
    story: `跟你說我朋友子瞻半夜哭醒的一件事。那年他四十歲,在山東密州當知州,正月二十日那天晚上,窗外還有殘雪,他做了一個夢,夢裡見到了死去十年的妻子。醒來以後,他坐在桌前把整個夢寫成了一首詞,窗外天還沒亮,寫完自己看了一遍,手還在抖。

子瞻的第一任妻子叫王弗,十六歲嫁給他,兩個人感情很好。王弗識文斷字,子瞻寫文章,她常常安靜地在屏風後面聽,聽出毛病了才提醒他,平常話不多,心思卻細,連子瞻自己都沒察覺的交際陷阱,她往往一句話就點破。可惜她二十七歲那年就病死了,葬在四川眉山老家的山上,子瞻親手在墳邊種了三萬棵松樹,一棵一棵種下去,像是在替她留一個永遠不會荒廢的家。這事一晃過去十年,子瞻沒再細想過,一來是官場的事忙得他沒時間,二來大概也是不敢細想。

密州這幾年他過得不順。旱災、蝗災接連來,他常常帶著官吏下鄉勘災,晚上回府累得倒頭就睡。新舊黨爭的風波也波及到他,頭髮白了一半,臉上風霜也重了,快四十歲的人看起來蒼老了不只十歲。那個正月二十日的夜裡,他不知怎麼就夢見了王弗,夢裡的場景是老家的小窗子,她正對著鏡子梳妝打扮,動作跟十幾年前一模一樣,連梳頭的姿勢都沒變。

兩個人四目相對,一句話都說不出來,只有眼淚一行一行流下來。子瞻心裡明白,就算真能重逢,她也未必認得出自己這張佈滿風塵、鬢角早白的臉——十年前的丈夫,和眼前這個蒼老的男人,中間隔著太多沒說出口的辛苦,那些辛苦她一件都沒趕上,也一件都不知道。

十年生死兩茫茫,不思量,自難忘。縱使相逢應不識,塵滿面,鬢如霜。

醒來以後他把整個夢寫下來,連夢裡沒說出口的話也寫了進去——他想她那座墳,年年最讓人肝腸寸斷的地方,大概就是明月照著的那片矮松山岡,那些他親手種下的松樹,如今應該已經長得比人還高了。他這輩子後來又寫過很多首悼亡的句子,但沒有一首比這個正月的深夜更真實,因為那是他十年來第一次,終於讓自己夢見她,也終於承認自己老了、想她了、這十年真的很難熬。`
  },

  // id=441 北宋 蘇軾 〈念奴嬌-赤壁懷古〉rating=4
  // 詩眼：一個被貶到荒地的官員,站在一塊可能認錯的古戰場前,拿自己的一事無成對比年輕氣盛的周瑜
  // 隱藏連接：黃州赤壁磯與三國真正的赤壁之戰古戰場並非同一地點,後世分稱文赤壁與武赤壁
  441: {
    title: "念奴嬌-赤壁懷古",
    author: "蘇軾",
    summary: "他站的地方,可能根本不是真正的三國古戰場——但這不妨礙他在這裡,把自己一生的抱負與失落全部倒進長江。",
    story: `跟你說我朋友子瞻站在一塊可能認錯了的石壁前面,寫下他一生最有名的一首詞的故事。那年他被貶到黃州,閒著沒事常去城外江邊一座赤褐色的山崖走走,當地人叫它赤壁磯,江水拍打著崖壁,聲音很大。

子瞻心裡其實清楚——這裡未必是三國時候周瑜火燒曹軍的那個真赤壁。真正的古戰場在湖北另一個地方,黃州這座只是同名而已,連當地老百姓也是聽著聽著、口耳相傳就信了這個地名的巧合。可是他懶得計較,反正江山如畫,適合站在這裡遙想當年那場驚天動地的大戰,想多久都行,反正他現在有的是時間。

他這時候是什麼處境呢。四十好幾的人,因為烏臺詩案差點被砍頭,坐了大半年的牢,撿回一條命後貶到黃州當一個沒有實權的閒官,俸祿少得要自己開荒種地才夠吃,連住的房子都是朋友幫忙張羅的。這跟他年輕時候意氣風發、以為自己能做出一番大事業的樣子,落差大得驚人,他心裡不是不明白。

站在江邊,他想起周瑜——那個跟他一樣年輕就出名的人物。周瑜二十幾歲就當上東吳的大都督,那年剛娶了小喬,春風得意到不行,聽說打仗時連正裝都不用換,搖著羽毛扇子,一身閒適打扮,談笑聊天的功夫就把敵軍幾十萬艘戰船燒成了灰。子瞻越想越覺得自己這輩子跟周瑜完全是兩個活法——人家是真的建功立業,自己卻只能站在一塊可能是假的古戰場前面,對著江水發呆,連一場真正的仗都沒打過。

他自嘲自己想這些事想得太多情,難怪早生了滿頭白髮。人生就像一場夢,不如舉起酒杯,把這杯酒灑向江心,敬給那輪照過赤壁、也照過所有已經死去的英雄的月亮,反正誰也帶不走什麼。

大江東去,浪淘盡,千古風流人物。人生如夢,一樽還酹江月。

這塊石壁後來被叫做"文赤壁",跟湖北那個真正打過仗的"武赤壁"分開稱呼,兩邊各自留名,誰也不必爭誰更正宗。子瞻認沒認錯地方,一千年後好像也沒那麼重要了——他在這裡想通的那些事,比地點本身流傳得更遠,也比周瑜的戰功更貼近普通人的一生,因為大多數人這輩子也都不是周瑜,只能站在江邊,學著跟自己的落差和解。`
  },

  // id=443 北宋 晏殊 〈浣溪紗〉rating=4
  // 詩眼：一句話卡了他一年多,最後靠身邊的人一秒鐘幫他對出來
  // 隱藏連接：据傳與幕僚王琪飲酒時隨口念出上聯求對,王琪應聲對出下聯
  443: {
    title: "浣溪紗",
    author: "晏殊",
    summary: "堂堂北宋宰相,寫詩填詞是他的拿手好戲,偏偏一句對聯卡了一年多,最後是幕僚一秒鐘幫他對出來的。",
    story: `跟你說我朋友同叔卡在一句話上一年多,最後靠別人幫忙才解套的故事。晏同叔是北宋做到宰相的大官,一輩子過得順風順水,十四歲就以神童身份被推薦進京應試,後來官運亨通,詞裡卻常常藏著一種說不清楚的空虛感,這首浣溪紗就是最有名的一首。

他寫的都是眼前的小事——聽一支新填的詞,配上一杯酒,忽然想起去年這個時候,天氣一樣,亭臺一樣,連座位大概都沒換,人卻不一樣了。夕陽每天都會西下,可是誰知道它什麼時候才會再回來。這幾句寫得平平淡淡,沒有大悲大喜,可就是這種平淡,讓人心裡發空,好像什麼都擁有,又好像什麼都留不住。

寫到下闋,他想出了上聯——花落下去了,誰也沒辦法,一點辦法都沒有。這句"無可奈何花落去"他自己很滿意,可是接下來的對句,他想了很久很久都想不出來,据說前前後後卡了一年多,走路想、吃飯想、睡前也想,幕僚提過好幾個對句,他都覺得差了那麼一點意思,搖搖頭又推翻。堂堂宰相,寫詩填詞是他的拿手好戲,偏偏就這一句對聯過不去,寫了又刪,刪了又寫,總覺得差一口氣。

後來有一次跟幕僚王琪一起飲酒聊天,窗外正好也是花落燕歸的季節,晏同叔隨口把這句卡住的上聯念出來,說自己怎麼都對不出滿意的下聯。王琪幾乎沒怎麼想,張口就接了一句——似曾相識燕歸來。晏同叔一聽,整個人愣住,拍案叫絕,這正是他一直在等的那句,一年多的糾結,一秒鐘就解開了。

無可奈何花落去,似曾相識燕歸來。小園香徑獨徘徊。

一句花落去的無奈,配上一句燕歸來的似曾相識,兩件事本來毫不相干,湊在一起卻精準地說中了人生的一種感覺——有些東西留不住,有些東西卻好像繞了一圈又回來了。晏同叔後來又把這兩句用進另一首詩裡,反覆用、捨不得放,可見他有多滿意這句得來不易的對句。王琪後來也因為這一句對得漂亮,在同僚間出了名,常有人半開玩笑地說他是幫宰相解圍的功臣。一句差一年,一句一秒就到,人生裡這種巧妙的落差,大概誰都遇過,只是不是誰都能寫成這麼工整的兩句話。`
  },

  // id=446 北宋 柳永 〈雨霖鈴-寒蟬淒切〉rating=4
  // 詩眼：兩人心裡有千言萬語，離別那一刻卻一句話都說不出口
  // 隱藏連接：相傳與他多次因失意離開汴京時反覆告別的一位歌姬有關，史料未能確證
  446: {
    title: "雨霖鈴-寒蟬淒切",
    author: "柳永",
    summary: "他們十指緊扣，眼淚在眼眶裡打轉，卻連一句再見都說不出口——因為知道這一別，再好的風景也沒人能一起看了。",
    story: `跟你說我朋友柳七的一個傍晚。長亭外，寒蟬叫得淒切，一場驟雨剛停。他跟她面對面坐著，桌上擺著送別的酒，卻誰都沒心思喝。三十幾歲的男人，這輩子寫過幾百首讓整個汴京傳唱的詞，此刻卻一個字都擠不出來。

柳七本名柳三變，年輕時就愛往秦樓楚館裡鑽，寫的詞市井小唱都愛聽，據說凡是有水井的地方，就有人在唱他的詞。可是這樣一個紅到街知巷聞的才子，考進士卻屢戰屢敗。有一年他寫了首發牢騷的詞，被仁宗皇帝看到，皇帝批了一句話，大意是這種人還是別來做官，回去填詞吧。柳三變乾脆把這句話當成勳章，自稱奉旨填詞柳三變，在青樓瓦舍裡繼續混，一混就是半輩子。功名這條路走不通，他索性把全部心力都放進詞裡，寫市井男女的悲歡，寫青樓歌姬的心事，久而久之，倒也在另一條路上闖出了名氣。

這天他又要離開汴京了。這一次不是遊山玩水，是又一次在仕途上碰了壁，只能收拾行囊南下謀生路。城外的碼頭，蘭舟已經在催他上船，船伕一遍一遍喊，岸邊人聲嘈雜，唯獨他們這一桌，安靜得不像話。都門外搭起帳篷擺酒，酒杯滿了又空，可是誰都提不起興致，那壺酒喝起來，一點滋味都嚐不出來。他跟她十指緊扣，眼淚在眼眶裡打轉，兩個人對看著，竟然一句話也說不出口，只能任那口氣哽在喉嚨裡，蘭舟的催促聲卻越來越急。

他想到接下來要走的路——千里煙波，一路往南，傍晚時分楚地的天空低垂著沉沉暮靄，像是把整個世界都壓下來。他知道多情的人自古以來就是這樣，一到離別就特別傷心，何況又撞上這個冷落蕭瑟的秋天。他甚至已經能想見明天早上：船靠了岸，酒也醒了，四周只剩楊柳岸邊，一輪殘月掛在拂曉的風裡。

他低頭看著她的手，忽然把心裡那句話說了出來：

多情自古傷離別，更那堪冷落清秋節。今宵酒醒何處，楊柳岸，曉風殘月。

說完他自己也愣住了。他知道接下來這一年，哪怕遇到再好的風景、再好的日子，對他來說也等於白搭，因為身邊沒有這個人，就算心裡有再多的柔情蜜意，又能說給誰聽。

蘭舟終於還是催發了。柳七收起眼淚上船，回頭望了一眼長亭，長亭外的人影越來越小，很快就被岸邊的樹叢擋住了。多年後汴京的歌姬還在傳唱他的詞，酒樓茶坊裡到處都聽得見這幾句，可是很少有人記得，那個寫出執手相看淚眼的男人，後來一輩子輾轉在外地做小官，官做得又小又窮，最後窮死在客棧裡，是幾個交好的歌妓湊錢，才把他安葬。她們說，這個男人把所有的深情都給了詞，卻沒人能替他留住長亭外的那個人。`
  },

  // id=449 南宋 李清照 〈點絳脣-蹴罷鞦韆〉rating=4
  // 詩眼：既想看清來人又不敢正面回頭，只好假裝聞青梅偷偷張望
  // 隱藏連接：相傳詞中來客即後來的丈夫趙明誠，二人確實在相近年紀訂親，但無確證
  449: {
    title: "點絳脣-蹴罷鞦韆",
    author: "李清照",
    summary: "她慌慌張張跑向門口，鞋襪都沒穿好，卻又停下腳步回頭多看一眼——這是宋朝第一才女，曾經也只是個心慌意亂的少女。",
    story: `跟你說我朋友清照少女時代的一個下午。她剛盪完鞦韆下來，兩隻手還懶懶地不想動，衣服被薄汗浸得半透，額頭上沾著幾滴汗珠。院子裡的花上還帶著露水，一朵朵開得又濃又瘦。她整個人還沉浸在盪鞦韆的暈眩裡，連頭髮鬆了都沒發覺。

清照那時候還沒嫁到趙家，住在濟南老家，是個被寵得有點無法無天的官家小姐。她爹李格非在朝裡做官，家裡藏書多得離譜，堆得比人還高，她從小就翻遍了那些書，寫的詞比很多成年文人都老練，家裡上上下下都拿她當寶貝，沒人捨得管她。可是再怎麼早慧，她畢竟才十幾歲，骨子裡還是個貪玩的女孩子，盪鞦韆能盪到滿頭是汗、盪到手都痠了還不肯下來，就是最好的證明。

院子裡靜悄悄的，只有花瓣上的露水偶爾滴落的聲音，她整個人還懶洋洋地站在鞦韆架旁，一點都沒想到接下來會發生什麼事。正鬆快的時候，忽然聽見院門外有人進來，說話聲、腳步聲都清清楚楚傳過來。她整個人一驚，想都沒想就往回跑。跑得太急，鞋子沒穿好，襪子也是歪的，連頭上的金釵都晃鬆了、快要掉下來，她也顧不上撿，任由它晃盪著。她害羞得臉都紅了，一路跑到門邊，心跳得比剛才盪鞦韆時還要快。

跑到門口，她忽然又停下腳步。來的人是誰她其實沒看清楚，可是心裡那股好奇心比害羞還強一點。她不敢正面回頭看，只好裝作若無其事的樣子，靠在門邊，低頭聞了聞旁邊那株還帶著青澀氣息的梅子，眼角卻悄悄往來人那個方向瞄過去。

這個又想看又不敢看的瞬間，被她自己寫進了詞裡：

見客入來，襪剗金釵溜，和羞走。倚門回首，卻把青梅嗅。

後人常常拿這闋詞去猜，那天到底是誰進了院子。相傳那可能是後來成為她丈夫的趙明誠，二人也確實是在相近的年紀相識、訂親的，只是這說法終究無從確證，只能當一段流傳的佳話來聽。誰也沒辦法完全考證是不是真是那一天，可是那個又想回頭看、又假裝聞青梅的少女動作，卻成了一千年後所有人讀到都會會心一笑的畫面。她後來嫁給趙明誠，兩人賭書潑茶、鑑賞金石，成了歷史上少有的神仙眷侶，只是那些美好的日子，都比不上這個下午單純——鞋襪未穿妥，金釵鬆脫著，一個少女倚在門邊，聞著青梅，眼角卻忍不住往院門那頭多瞄了一眼。原來宋朝第一才女，也曾經是個心慌意亂的小女生。`
  },

  // id=455 南宋 李清照 〈夏日絕句〉rating=4
  // 詩眼：用項羽寧死不渡的骨氣，當著臨陣脫逃的丈夫的面說出誅心的話
  // 隱藏連接：她所寫的很可能正是諷刺身邊縋城逃跑的丈夫趙明誠，此事見於後世筆記記載
  455: {
    title: "夏日絕句",
    author: "李清照",
    summary: "丈夫連夜縋城逃跑保命，她一句責備都沒說，只寫了四句詩，句句都說給他聽。",
    story: `跟你說我朋友清照人生最憋屈的一段路。建炎三年，金兵南下，她跟丈夫趙明誠倉皇往南逃。這時候的趙明誠已經不是當年那個跟她一起賭書潑茶、在書齋裡鬥智鬥趣的年輕人了，他當時是江寧知府，是城裡的守官，本該是守土有責的人。這些年他們兩人省吃儉用，走遍大江南北收集金石碑帖、古書字畫，裝了滿滿好幾大車，那是他們半輩子的心血，比命還金貴。

可是那一夜，城裡發生兵變，御營統制官王亦圖謀作亂，消息傳來，滿城人心惶惶。趙明誠沒有組織抵抗，也沒有先安頓好家眷，反而在天還沒亮的時候，自己一個人用繩子從城牆上縋下去，倉皇逃了出城，留下滿城驚慌的百姓，也留下清照一個人和一屋子他們夫妻半輩子收藏的金石字畫。等到亂事平息，他這個知府臨陣脫逃的事傳開，朝廷追究下來，他被撤了職，兩人只能灰頭土臉地繼續南下。

清照沒有當面罵他。她是那種寧可一輩子不提，也不會撒潑吵鬧的女人。可是她心裡清楚，自己嫁的這個男人，在最該挺身而出的那一刻，選擇了轉身逃跑。夫妻倆繼續南逃的路上，兩人之間那種曾經的默契，一點一點裂開了縫。

有一天，他們的船經過烏江邊。清照抬頭，想起兩千年前，項羽兵敗到了這裡，江東子弟願意撐船送他過江逃生，他卻不肯——他覺得自己帶出去八千子弟，如今全軍覆沒，無顏面對江東父老，寧可就地自刎，也不肯獨自偷生渡江。

她站在船頭，看著同一條江，又看了一眼身邊這個縋城逃命的丈夫，一個字都沒有對他說，只是提筆寫下四句話：

生當作人傑，死亦為鬼雄。至今思項羽，不肯過江東。

趙明誠聽人念完，據說當場臉色發白，站在船頭愣了很久，一路沉默，再也沒提起那晚縋城的事，那四句詩比任何責罵都更重。他們兩人的婚姻，從這天以後，再也回不到當年賭書潑茶時的樣子，話說得越來越少，眼神也不太敢對上。第二年趙明誠病死在赴任途中，清照一個人帶著半船殘存的金石書畫，繼續在亂世裡漂流了二十幾年，晚年孤苦無依，還遭人算計財物、鬧上官司。那艘駛過烏江的船早就不在了，可是那四句寫給丈夫聽的詩，一千年來替所有讀過的人問了同一句話——你敢不敢，在該挺身而出的時候，不轉身就跑。`
  },

  // id=458 南宋 辛棄疾 〈破陣子-為陳同甫賦壯詞以寄之〉rating=4
  // 詩眼：夢裡打完一場酣暢淋漓的仗，醒來卻只看見自己滿頭白髮
  // 隱藏連接：這首詞是寫給同樣壯志難酬的摯友陳亮，兩人徹夜長談北伐大計後留下的寄詞
  458: {
    title: "破陣子-為陳同甫賦壯詞以寄之",
    author: "辛棄疾",
    summary: "他在夢裡打贏了這輩子最痛快的一仗，醒來卻只看見自己滿頭白髮。",
    story: `跟你說我朋友幼安的一個夜晚。他喝得半醉，伸手把油燈的燈芯挑亮一點，就著那點光，盯著牆上掛的那把劍看了很久。那把劍已經很久沒有出鞘了。

辛棄疾這個人，年輕時是真的上過戰場的。二十出頭，他在北方組織義軍抗金，甚至單槍匹馬闖進五萬人的敵營，把叛徒張安國從酒席上直接綁走，押回建康處決。那一年他名震南北，所有人都以為，這樣一個猛人，遲早要帶兵北伐，收復中原。

可是南渡之後，朝廷根本不敢重用他。主和派掌權，他這種主戰的悍將處處被排擠，一路被調來調去做些管錢糧、管治安的閒職，好幾次還被彈劾罷官，最後乾脆隱居在江西帶湖，蓋了間屋子，種田讀書，一晃眼就是快二十年。他的劍，掛在牆上，一年到頭沒人碰，劍鞘上都積了一層灰。

這天晚上來找他的，是陳同甫，也就是陳亮，另一個一輩子喊著要北伐、卻同樣被朝廷冷落的狂人。兩個同病相憐的中年人喝了一整夜的酒，聊的全是當年、以及那個永遠等不到的機會。同甫走後沒幾天，辛棄疾提筆，把那晚的心事寫成了一場只有在夢裡才能實現的沙場。

他寫夢裡自己又回到軍營，八百里連著的營帳，分食著烤肉，五十弦的瑟翻奏出塞外的曲調，秋天的沙場上正在點兵，那匹叫的盧的快馬相傳曾馱著劉備一躍飛過檀溪、逃過追殺，此刻馱著他飛奔，弓弦拉開時像打雷一樣響。他在夢裡替君王完成了收復天下的大業，也替自己掙下了生前身後的名聲。

醉裏挑燈看劍，夢迴吹角連營。八百里分麾下炙，五十弦翻塞外聲，沙場秋點兵。馬作的盧飛快，弓如霹靂弦驚。了卻君王天下事，贏得生前身後名。

夢到這裡戛然而止。他睜開眼，人還在帶湖的屋子裡，窗外沒有連營，沒有點兵的鼓聲，只有他自己，一頭已經花白的頭髮。他把最後五個字補上：可憐白髮生。

那把劍後來一直掛在牆上，直到他六十八歲病逝，都沒能等到朝廷真正交給他一支能打仗的軍隊。臨終前他還大喊了幾聲殺賊，聲音已經很虛弱，身邊人都聽得心酸。可是那個醉裡挑燈的夜晚，那場只做了一半就醒來的夢，卻替後世所有懷才不遇的人，留下了一句最痛的閉環，夢有多快意，醒來就有多殘忍。`
  },

  // id=460 南宋 蔣捷 〈虞美人-聽雨〉rating=4
  // 詩眼：同一場雨，年少時是背景音樂，老年時卻是唯一的陪伴
  // 隱藏連接：無
  460: {
    title: "虞美人-聽雨",
    author: "蔣捷",
    summary: "同一場雨，他這輩子聽過三次，一次比一次孤單。",
    story: `跟你說我朋友勝欲晚年的一個雨夜。窗外下著雨，他坐在一間破舊僧廬底下，聽著雨點打在屋簷上，鬢角的頭髮已經稀稀落落地白了幾撮。他忽然想起，這輩子他已經在三個完全不同的地方，聽過三次很像的雨聲。

蔣捷，字勝欲，是南宋末年的進士，考中沒幾年，南宋就亡了。他不肯到元朝去做官，一輩子拒絕出仕，寧可漂泊隱居，人稱竹山先生，鄉里人都佩服他這份骨氣。他的一生，幾乎跟著那個朝代一起碎掉，年輕時是承平世家的公子哥，家裡不愁吃穿，只管風花雪月，國破之後，家產也保不住了，變成了一個到處躲、到處逃的遺民，一年換好幾個落腳的地方。

第一次聽雨，是他年少的時候。那時候他常常泡在歌樓裡，紅色的蠟燭點著，羅帳低垂，身邊有酒有曲，雨聲不過是窗外的背景音樂，聽都懶得聽，那時候的他，覺得日子往後還長得很。

第二次聽雨，是他壯年漂泊在外的時候。國家已經亡了，他常常一個人待在一艘客船上，四處躲避戰亂，居無定所。有一次夜裡下雨，他抬頭看江面，江很寬，雲壓得很低，西風裡傳來一隻離群孤雁的叫聲，淒厲又孤單。那一刻他才知道，原來雨聲底下，可以什麼依靠都沒有。

如今他已經老了，國破家亡三十幾年，四處寄居，這天夜裡他落腳在一間僧廬底下躲雨。雨還是那個雨，聽在耳朵裡卻完全是另一種味道——不再有紅燭羅帳的軟，也不再有孤雁哀鳴的痛，只剩下一種空空的、什麼都不想再爭辯的平靜。

他望著簷下的雨滴，一滴一滴落到台階上，慢慢寫下這輩子聽過的三場雨：

少年聽雨歌樓上，紅燭昏羅帳。壯年聽雨客舟中，江闊雲低，斷雁叫西風。而今聽雨僧廬下，鬢已星星也。

他擱下筆，想起這一生的悲歡離合，終究誰也留不住，誰也帶不走，索性不再多說什麼。窗外的雨還在下著，一點一滴，一直落到天快亮。僧廬裡沒有別人，只有他自己，跟這場雨，還有滿頭稀疏的白髮。他任由那雨聲繼續下去，不再去分辨那是哪一年、哪一種心情的雨，反正到了這把年紀，不管台階前的雨滴到天明，他都只是靜靜聽著，像聽著自己這一生，原原本本地流過去，一滴都沒漏掉。`
  },

  // id=465 中唐 孟郊 〈登科后〉rating=4
  // 詩眼：二十幾年落第的委屈，只用一天騎馬看花，全部揮霍光
  // 隱藏連接：多年來四處奔走替他揄揚、始終沒放棄他的韓愈，是他熬到這天的重要推手
  465: {
    title: "登科后",
    author: "孟郊",
    summary: "他二十幾年落第的委屈，只用騎馬看遍長安城的一個下午，全部花光。",
    story: `跟你說我朋友東野四十六歲那年的一個下午。他騎在馬上，在長安城裡一路狂奔，馬蹄踏得又急又快，一整個下午的時間，他幾乎把整座長安城的花都看遍了。旁人可能以為他就是愛玩，其實沒人知道，他這輩子有多少年，是靠著這一天撐過來的。

孟郊考進士，考了整整二十幾年。二十出頭就開始跑長安，考一次落一次，一路考到四十歲出頭還在落第。那些年他過得極其拮据，常常一個人窩在租來的小房間裡，冬天沒炭火可燒，夏天蚊蟲亂飛，日子過得又緊又窄，連件像樣的新衣服都置辦不起，出門赴考還得跟人借件體面點的衣袍。他後來自己形容那段日子是昔日齷齪，齷齪不是髒，是拘束、憋屈的意思，說的是那種被貧窮和失敗逼得喘不過氣的處境，日子過得縮手縮腳，連走路都不敢抬頭。

那些年一直沒放棄他的，是韓愈。韓愈比他小十幾歲，卻一直把他當作真正的詩人看待，四處替他揄揚，寫信鼓勵他繼續考。每次孟郊落第，韓愈都寫詩安慰他；每次孟郊病倒窮困，韓愈也想辦法接濟。旁人都笑孟郊老不中用，只有韓愈一直相信，這個人遲早會出頭。

終於在他四十六歲那年，放榜那天，他的名字真的出現在榜上。多年的委屈，一瞬間全部鬆開。他也顧不上矜持，翻身上馬就往城裡衝，今天他什麼都不想忍了，以前那些拘束、那些看人臉色的日子，今天通通不算數，他要把心裡積了二十幾年的暢快，一次揮霍完。

馬跑得飛快，春風拂在臉上，滿城的花一朵接一朵從眼前掠過。他忍不住喊了出來似地，把心裡那句話寫成了詩：

昔日齷齪不足誇，今朝放蕩思無涯。春風得意馬蹄疾，一日看盡長安花。

這一天，他其實也惦記著遠方的韓愈，那個從二十幾歲就一路看著他落第又落第、卻始終沒放棄他的人，若是韓愈這時候也在長安，兩人少不了要痛痛快快喝上一場。可是母親不在長安，韓愈也不在長安，能陪他一起瘋的，只有胯下這匹馬和滿城的花，路人看他一介中年書生策馬狂奔，多半以為他失心瘋了，卻不知他這是把二十幾年的委屈一次還清。四年後他才被派到溧陽當縣尉，位子很小，俸祿也少，但總算能把母親接來身邊，後來還寫下更有名的那首遊子吟。但這一天的暢快，他誰都沒有讓，一個人騎著馬，把二十幾年的委屈，通通看盡、通通花光。`
  },

  // id=2 三國 曹操 〈觀滄海〉rating=3
  // 詩眼：打完這輩子最兇險的一仗，站在沒見過的大海前，野心反而被撐得更大
  // 隱藏連接：無
  2: {
    title: "觀滄海",
    author: "曹操",
    summary: "打完這輩子最兇險的一仗，他站在沒見過的大海前，忽然覺得自己的野心還不夠大。",
    story: `跟你說我朋友孟德建安十二年秋天的一件事。他剛打完一場極其兇險的仗，遠征塞外的烏桓，大軍走的是一條連嚮導都心裡發毛的祕密小路，穿過缺水的沙地，士兵渴到挖井挖了幾十丈深才見水，連軍糧都快斷了，好幾次差點全軍覆沒。這一仗如果打輸，他半輩子在北方打下的地盤，可能全部翻盤，連退路都沒有。

曹操那時候已經五十三歲，鬢角早就摻了白髮。他從一個小小的騎都尉起家，一路靠打仗打出了半壁江山，滅袁紹、平烏桓，把北方基本統一，麾下謀臣猛將雲集，可他心裡清楚，這些年打下的一切，隨時可能因為一場敗仗全部歸零。這場仗打贏之後，他班師回朝，走的是碣石這條路，那是一座靠著海邊的山。行軍途中他聽當地人說起山下就是茫茫大海，他索性登上碣石，想看看傳說中的那片海，他這輩子生在內陸，戎馬半生，很少有機會見過真正的海。

站上山頂那一刻，他整個人愣住了。海水浩浩蕩蕩，一望無際，山島就那樣孤零零地聳立在海面上。岸邊的樹木長得密密麻麻，秋天的草還是那麼茂盛。海面上起了風，秋風一吹，浪頭一波接一波湧起來，聲音很大。

他站在那裡看了很久。忽然覺得，自己剛打完的那場仗，自己苦心經營半輩子的地盤，在這片海面前，好像都變得很小很小。可是奇怪的是，他心裡並沒有覺得自己渺小，反而覺得胸口裡那股野心，好像被這片海撐得更大了，太陽和月亮的運行，好像都是從這片海裡升起來的；連銀河星辰的燦爛，看起來也像是從這片海裡冒出來的。

他站在碣石山頂，把這片海寫進了詩裡：

水何澹澹，山島竦峙。樹木叢生，百草豐茂。秋風蕭瑟，洪波湧起。日月之行，若出其中；星漢燦爛，若出其裡。

寫完他又照著慣例，在末尾加上一句這組詩固定的收尾，幸甚至哉，歌以詠志——這四個字，他在同組的其他幾首詩裡都用過，算是一種收束心情的口頭禪，像唱完一段就要喘口氣。

一年後，他會在赤壁碰上他這輩子最大的一次慘敗。可是這一年秋天，站在碣石山頂看海的曹操，還不知道那場敗仗在等著他。他只知道，眼前這片海，比他這輩子見過的任何戰場都遼闊，而他心裡那股連日月星辰都能從中升起的野心，此後再也沒有小過。`
  },

  // id=25 盛唐 杜甫 〈夢李白二首之一〉rating=3
  // 詩眼：分不清夢裡走來的老友是活人還是魂魄，卻還是忍不住開口相問
  // 隱藏連接：十餘年前兩人曾在梁宋一帶策馬同遊，結下情同兄弟的交情
  25: {
    title: "夢李白二首之一",
    author: "杜甫",
    summary: "他分不清夢裡走來的到底是活著的李白，還是他的魂——路途太遠，讓人不敢分辨。",
    story: `跟你說我朋友子美流落秦州那段日子做的一個夢。夜裡他睡得並不安穩，恍惚間看見一個熟悉的身影走進他夢裡，是李白。他心裡一驚，又驚又喜，卻怎麼也高興不起來，因為他已經很久沒有這位老友的確切消息了。

安史之亂爆發那幾年，天下亂成一團。李白當時已經名滿天下，卻因為投靠了永王李璘的幕府，永王起兵失敗被定為叛逆，李白也跟著被牽連下獄，後來雖然保住性命，卻被判流放到夜郎，那是當時被視為瘴癘之地的偏遠角落，消息傳到杜甫這裡的時候，已經斷斷續續，誰也說不準李白到底是死是活。

杜甫跟李白的交情，是十幾年前在梁宋一帶結下的。那時候兩人一起騎馬打獵、飲酒論詩，杜甫那時候還是個沒沒無聞的年輕人，李白已經名動天下，卻絲毫沒有架子，兩人一見如故，情同兄弟。分別之後，天各一方，再也沒能見上一面。

如今聽聞李白下獄流放，生死不明，杜甫日夜懸心，接連好幾晚都夢見他。可是這個夢卻讓他越夢越怕，死別的時候，人尚且哭得說不出話，可活著的離別，卻是那種說不清、放不下，天天都惦記的難受。江南那種瘴氣瀰漫的地方，被貶去的人往往連一封平安信都送不出來。今晚故人終於走進他夢裡，讓他清清楚楚地感覺到，這些日子自己有多想他。

杜甫在夢裡盯著李白看，越看越不對勁。他心想，李白如今應該還被困在羅網一樣的官司牢籠裡，怎麼可能有翅膀飛到這麼遠的地方來見自己？他甚至懷疑，這恐怕不是老友活著的魂，是路途太遠，自己想太多想出來的幻覺。夢裡的李白從楓林那頭青蒼蒼地走來，轉眼又要往關塞黑沉沉的方向回去，月光落滿了整個屋梁，恍惚間好像還照著李白的臉。

他在夢裡忍不住喊出心裡最怕聽到的擔憂：

恐非平生魂，路遠不可測。魂來楓林青，魂返關塞黑。

杜甫醒來，窗外月光真的落滿屋梁，恍惚間彷彿還留著李白的臉色。他趕緊又添了一句，像是在跟遠方那片深不見底的江水說話，水深浪闊，千萬別讓蛟龍把人給害了。這場夢後來連著做了兩夜，可是不管夢裡的李白是死是活，那份十幾年前梁宋策馬的情誼，杜甫這輩子都沒放下過。`
  },

  // id=31 盛唐 王維 〈西施詠〉rating=3
  // 詩眼：同一張臉，貧賤時沒人多看一眼，富貴後連皺眉都成了風情
  // 隱藏連接：相傳暗喻詩人自己靠貴人提攜一步登天，對照同輩懷才不遇者的處境，此為後世解讀，非正史明載
  31: {
    title: "西施詠",
    author: "王維",
    summary: "同一張臉，貧賤時沒人正眼看一眼，富貴後連皺眉都成了風情。",
    story: `跟你說我朋友摩詰年輕時寫過一首替西施翻案的詩。故事很多人都聽過，西施本來只是浣紗溪邊一個普通的浣紗女，後來被選進宮，一路送到吳王夫差身邊，一夜之間從溪邊洗衣的女孩，變成了吳宮裡最受寵的妃子。

摩詰寫這首詩的時候，自己也才二十出頭，卻已經是長安城裡最炙手可熱的年輕才子。他不只詩寫得好，還精通音律、擅長彈琵琶，靠著這一身才藝，得到岐王和玉真公主的賞識，據說還特地為公主獻藝一曲，一路被引薦、被讚譽，年紀輕輕就中了進士，一步登天，同輩人望塵莫及。可是同一批同樣有才華的讀書人裡，多少人在長安城裡蹉跎十幾年，熬白了頭，連個像樣的功名都沒混到，最後灰溜溜地回鄉，差別往往不在才華，而在有沒有人願意抬舉一把、給一個被人看見的機會。

他想起西施的故事，忽然覺得這裡頭藏著同一個道理。西施在浣紗溪邊的日子，難道容貌就比別人差嗎？當然不是。她卑微的時候，身邊的人誰也沒把她當回事；等到她得寵入宮，身邊的人卻爭著替她塗脂抹粉，連她穿衣服都不用自己動手。得到吳王的寵愛之後，她的嬌態被人稱作可愛，她的一舉一動，連是非對錯都沒人再去計較。

最諷刺的是，她從前在溪邊一起浣紗的姐妹，眼看她飛上枝頭，誰也沒能跟她一起坐上回宮的車，只能留在原地。旁邊還有一個鄰家女孩，聽說西施皺眉的樣子很美，就學著她皺眉，以為這樣也能讓自己變美，卻沒人多看她一眼。

摩詰把這整段感慨寫成了詩：

艷色天下重，西施寧久微。朝為越溪女，暮作吳宮妃。賤日豈殊眾，貴來方悟稀。邀人傅脂粉，不自著羅衣。君寵益嬌態，君憐無是非。當時浣紗伴，莫得同車歸。持謝鄰家子，效顰安可希。

寫完這首詩，王維並沒有直接說自己在講什麼。可是懂的人都看得出來，他寫的哪裡只是西施，那些沒被伯樂看見、一輩子懷才不遇的讀書人，不就跟溪邊那些浣紗姐妹一樣嗎？這首詩後來流傳了一千多年，每次有人讀到那句卑賤時容貌本不比人差、富貴後才驚覺原來如此稀世的感慨，都會想起自己身邊那個明明才華洋溢，卻始終沒被看見的人。`
  },

  // id=36 盛唐 王昌齡 〈塞上曲〉rating=3
  // 詩眼：老兵勸年輕人別學耍帥的遊俠兒炫耀寶馬，真正的邊關是要老死沙場的
  // 隱藏連接：相傳詩人年輕時曾親赴河西隴右一帶遊歷戍邊生活，詩中場景取材自親身見聞
  36: {
    title: "塞上曲",
    author: "王昌齡",
    summary: "老兵指著耍帥的遊俠兒搖頭嘆氣——真正的邊關，是要老死沙場的。",
    story: `跟你說我朋友少伯早年真正在邊塞待過的一段日子。那時候他還沒考中進士，家境不算好，一個人揹著行囊跑到河西、隴右一帶遊歷，走的路又遠又苦，親眼見過蕭關道上的荒涼，秋天的桑林裡蟬叫得空空蕩蕩，聽起來格外淒涼，八月的邊塞已經冷得刺骨，穿再厚的衣服都擋不住那股寒意，滿地都是枯黃的蘆草，一望無際，看久了讓人心裡發慌。

少伯在那裡遇到過不少常年戍守邊關的老兵。這些人大多是幽州、并州一帶出身的漢子，那裡自古民風彪悍，男孩子生下來就是準備上戰場的，家裡祖孫三代可能都當過兵。他們一年到頭在蕭關道上進進出出，守著同一段邊塞，春夏秋冬換了幾十輪，同袍換了一茬又一茬，人卻一直沒能回家，最後大半輩子都耗死在了沙場上，連個像樣的封賞都輪不到，家鄉的爹娘妻兒等到頭髮都白了，也未必能等到人回來。

有一次少伯跟一個老兵聊起天，老兵指著遠處一群騎馬耍槍、招搖過市的年輕遊俠兒，搖搖頭嘆氣。少伯問他嘆什麼，老兵說，你別看那些遊俠兒騎著紫騮馬，穿得光鮮亮麗，到處誇自己的馬多好、身手多利落，那都是還沒真正上過戰場的人才有的興致。真正在邊關耗上幾十年的人都知道，戰場上沒有什麼英姿颯爽，只有一年又一年重複的荒涼，還有身邊袍澤一個接一個倒下去，自己能活著變老，已經是運氣。

少伯把這番話牢牢記在心裡。他自己後來雖然考中了進士，當了官，一輩子卻始終沒忘記邊塞上那些老兵說的話。他把那個嘆氣的畫面寫成了詩，替所有耗死在沙場、卻沒沒無聞的老兵說一句公道話：

蟬鳴空桑林，八月蕭關道。出塞復入塞，處處黃蘆草。從來幽并客，皆向沙場老。莫學遊俠兒，矜誇紫騮好。

這首詩後來被歸進邊塞詩的經典之列，可是很少人記得，少伯寫這首詩之前，是真的去過那片蕭關道，是真的聽一個老兵親口說出那句別學遊俠兒炫耀寶馬的告誡。多少年後，當人們讚嘆邊塞詩寫得蒼涼真實的時候，其實他們讀到的，不過是少伯忠實轉述了一個老兵臨老回頭，對一群不知天高地厚的年輕人，最後的一點苦心。`
  },

  // id=37 盛唐 王昌齡 〈塞下曲〉rating=3
  // 詩眼：世人歌頌邊塞士兵的意氣風發,現實卻是白骨埋在無人記得的荒草裡
  // 隱藏連接：相傳王昌齡年輕時西行途經臨洮古戰場,聽老兵講述當年出征的意氣與如今的白骨
  37: {
    title: "塞下曲",
    author: "王昌齡",
    summary: "他在古戰場邊聽一個瘸腿老兵說起當年出征多麼意氣風發——可眼前的荒草底下,埋的正是那些同樣意氣風發卻沒能回來的人。",
    story: `跟你說我朋友少伯年輕時的一趟旅行。他還沒考上進士之前,家境不算好,一心想從軍功裡闖出一條路,曾經一個人西行,一路走到河西隴右,走到臨洮——秦代長城最西邊的起點,史書裡好幾場血戰都發生在這一帶。那天傍晚他牽著馬去飲水,渡過一條秋天的河,水冷得像刀子一樣割人,風也跟著像刀子一樣刮臉,他把披風裹得更緊了一點。

他在河邊遇到一個老兵。老兵瘸了一條腿,坐在石頭上曬著快要落山的太陽,說自己年輕時就是在臨洮附近打仗留下的傷,那一仗死了多少同袍他早就數不清了。少伯蹲下來跟他搭話,問他,聽說當年打仗的人個個意氣風發是真的嗎?老兵笑了一下,那笑容裡有點苦,說那當然,誰上戰場前不是意氣高昂,誰不覺得自己會活著回來領功、風風光光衣錦還鄉?他自己那一年也是這樣想的,結果一條腿就留在了這裡。

老兵說完就沉默了,望著遠方不再說話。少伯抬頭看,太陽還沒完全落下,平坦的沙地被染成一片昏黃,遠遠望見臨洮的城廓,黯淡模糊,像蒙著一層灰。他順著老兵的視線望向城外那片荒地——蓬蒿長得比人還高,風一吹,草叢底下隱約露出一截一截發白的骨頭。沒人知道那是誰。可能是老兵的同袍,可能是老兵自己那一年差一點變成的樣子。

少伯站在那裡很久沒說話,馬在旁邊安靜地喝著水。他忽然明白,所有人傳誦的「打仗意氣高」這句話,跟眼前這片蓬蒿裡的白骨,其實是同一件事的兩面——一面是出征那天的鼓聲和旗幟,一面是誰都不會再提起的收場。他回旅店點起油燈,提筆寫下:飲馬渡秋水,水寒風似刀。平沙日未沒,黯黯見臨洮。昔日長城戰,咸言意氣高。黃塵足今古,白骨亂蓬蒿。

這首詩後來被編進〈塞下曲〉四首之一。少伯後來真的考上了進士,一輩子起起落落,晚年還被貶到更偏遠的龍標。但他沒有忘記臨洮那個黃昏,沒有忘記那個瘸腿的老兵——黃塵年復一年地覆蓋著同一片戰場,誰的意氣風發,最後大多變成蓬蒿底下沒有名字的白骨,只有極少數人,能像他一樣把那個下午寫成字,留給一千多年後還會背這首詩的人。`
  },

  // id=38 中唐 邱為 〈尋西山隱者不遇〉rating=3
  // 詩眼：爬三十里山路撲了空,卻在撲空裡治好了自己的心病
  // 隱藏連接：邱為終生為侍奉高齡母親婉拒仕途,這趟難得的登山訪友呼應他自己對取捨的體悟
  38: {
    title: "尋西山隱者不遇",
    author: "邱為",
    summary: "三十里山路爬到頂,隱者不在家——他卻在門前坐了一會兒,發現撲空這件事本身,已經比見到人更值得。",
    story: `跟你說我朋友邱為的一趟白跑的山路。他這輩子難得出遠門——家裡有個年邁的母親要奉養,朝廷幾次要調他去更遠的地方任官,他都推掉了,情願領一份小小的俸祿,守在母親身邊,親自看著她起居飲食。街坊都說他是個孝子,可只有他自己知道,這些年放棄的機會有多少。這一次他終於逮到一個空檔,託人照看母親,自己一個人往西山走,說好要去找一個隱居的朋友,順便透透氣。

那間茅屋蓋在絕頂上,他一口氣直上三十里,山路又陡又長,走到後來腿都軟了才到門口。他敲了敲柴門,裡面沒有僮僕應聲,連個回話的人都沒有。他探頭往窗裡看,屋裡空蕩蕩的,只有一張案几擺著,主人顯然不在家。他猜想,若不是隱者駕著那輛柴車出門去了,就是這時候正在秋水邊垂釣——反正這種人向來行蹤不定,不會乖乖待在家裡等人。

他站在門口愣了一下,心裡有點失落。三十里山路,一路仰望著這位隱士的名聲爬上來,滿心期待著見面該說些什麼,偏偏就這樣錯過了,連句招呼都沒能打上。他原本想像好幾種重逢的場景,結果全落空,一時之間不知道該不該就這樣轉身下山。

但他沒有立刻走。他在門前的石階上坐了下來,看著剛下過雨的山色格外清亮,青草的顏色像剛洗過一樣鮮綠;傍晚的松風從窗縫裡灌進來,一陣一陣的聲音很好聽,像是山自己在說話。他坐著坐著,忽然覺得,就算沒見到那個人又怎樣?這種幽靜到極點的感覺,已經夠讓人心裡的浮躁沉澱下來了。雖然沒有主客對飲的熱鬧,他卻嚐到了一種說不出的清淨道理,比真的見到面聊上幾句還要熨貼。

興致盡了,他才起身下山,一點也不覺得可惜。他心裡想著:何必一定要等到那個人。就像他這些年放棄仕途留在母親身邊——有些路,走過就已經值得,不一定要走到終點見到誰。下山的路上他把這一趟寫成了詩:絕頂一茅茨,直上三十里。扣關無僮僕,窺室惟案几。若非巾柴車,應是釣秋水。差池不相見,黽勉空仰止。草色新雨中,松聲晚窗裡。及茲契幽絕,自足蕩心耳。雖無賓主意,頗得清淨理。興盡方下山,何必待之子。`
  },

  // id=44 中唐 韋應物 〈初發揚子寄元大校書〉rating=3
  // 詩眼：剛跟摯友道別,船已開走,他清楚知道連下次見面在哪裡都無法承諾,卻只能任由船把自己載走
  // 隱藏連接：韋應物早年恃寵驕縱,安史之亂後靠輾轉任官重新學會交友,此詩呼應他人生從縱情到浮沉的轉折
  44: {
    title: "初發揚子寄元大校書",
    author: "韋應物",
    summary: "船一開,朋友和整座城都被晨霧吞掉,只剩一聲鐘追著船尾——他知道自己回答不了下次何時重逢這個問題。",
    story: `跟你說我朋友韋應物在揚子渡口的一個早晨。船夫已經解開纜繩,他站在船頭,看著岸上那個人——元大,他這幾年在廣陵最談得來的朋友——越來越小,終於整個人跟碼頭一起,被一層晨霧慢慢吞掉。

韋應物年輕時完全不是這種容易感傷的人。他十五歲就當上玄宗身邊的三衛郎,仗著皇帝寵信,鬥雞走馬,横行鄉里,誰都不放在眼裡,街坊見了他都要繞道走。安史之亂一場兵禍,把他從雲端摔下來,長安淪陷,靠山沒了,他流離失所了好一陣子,才收起那股狂氣,一個一個地方任官,一個人一個人地重新學著交朋友。元大就是這樣認識的——兩人在廣陵校書、論詩,常常一聊就聊到深夜,誰也不覺得膩。

如今又要分開了。他要乘船北返洛陽,元大留在廣陵繼續當校書郎。船慢慢駛入江面的煙霧裡,他回頭望,廣陵城的樹影已經模糊成一片灰綠,只剩下一聲廟裡的殘鐘,斷斷續續地追著船尾傳過來,像是元大還站在那裡沒走,又像是廣陵這座城捨不得放人。

他想起前幾天兩人在江邊小酒館裡的最後一頓飯。元大喝到後來也沒說什麼豪言壯語,只是一直替他斟酒,說了句等你到了洛陽,記得寫信告訴我平安。他當時笑著應了,現在船已經開了,才想到自己連下一封信要寄到哪裡去都說不準——他這幾年調動得太頻繁,今天在揚子,明天說不定又要奉命去別的州縣,連自己都猜不準下一站落在哪裡,更別說遠在廣陵的元大要怎麼找到他。

他站在船頭,想著這一別,下次見面會是在哪裡、什麼時候,自己竟然一點把握也沒有。他低聲說了一句話,像是說給元大聽,又像是說給自己聽:今朝為此別,何處還相遇?世事波上舟,沿洄安得住。

船身晃了一下,順著江水的方向漂遠。他知道自己已經回答不了那個問題——人這輩子就像水面上的一艘船,水要往哪裡流,船就往哪裡去,想要停在原地,一次也不行,連想逆流回頭多待一天都做不到。他沒有再回頭看,只是任憑船把揚子渡口、廣陵樹影和那聲殘鐘,一起留在身後的霧裡,像是把年輕時那個橫行鄉里的自己,也一併留在了那裡,只帶著這幾年學會的珍惜,繼續往下一個未知的官職漂去。`
  },

  // id=57 盛唐 李白 〈廬山謠寄盧侍御虛舟〉rating=3
  // 詩眼：剛從流放夜郎的死劫裡被赦免放回來,劫後餘生第一件事,是用最狂放的姿態告訴世界他沒有被打垮
  // 隱藏連接：詩末盧敖與收信人盧虛舟同姓,李白藉雙關把友人和傳說中的求仙者接在一起,邀他同遊太清
  57: {
    title: "廬山謠寄盧侍御虛舟",
    author: "李白",
    summary: "剛從流放的死劫裡撿回一條命,他做的第一件事不是低頭認錯,而是寫信約朋友一起飛到雲霄外面去。",
    story: `跟你說我朋友太白剛從鬼門關前撿回一條命之後,做的第一件事。那年他因為捲入永王李璘的謀反案,被判流放夜郎,人都已經走到半路的巫山附近,一紙赦令追上來——他自由了。換作別人大概會嚇得從此夾著尾巴做人,規規矩矩過完下半輩子,太白不是。他掉頭往廬山去,一路上手裡拄著一根綠玉杖,清晨才剛從黃鶴樓那邊出發,身上還帶著一路風霜的痕跡,眼神卻一點也不像個剛逃過死劫的人。

他這輩子最愛做的事,就是往名山裡鑽,這回也一樣,五嶽都想尋遍。流放路上那段日子他其實想過很多——想過自己一輩子求仕求得那麼辛苦,一朝捲入永王的案子就差點連命都賠上,想過家人這陣子替他擔了多少心。可一旦人真的自由了,他發現自己並沒有變得謹小慎微,反而更想把壓在心裡那口氣一次吐乾淨。他寫信給一個朋友盧虛舟,官拜侍御,兩人交情不淺。信裡他先甩出一句狠話:我本來就是楚國那個狂人,唱著鳳歌譏笑孔丘的傢伙——當年接輿嘲笑孔子四處奔走求官毫無意義,太白說自己就是那種人,從來不吃這一套規矩,別人越是要他低頭認錯,他偏要把頭昂得更高。

他把廬山寫得像仙境一樣張狂:屏風九疊的山勢像雲錦鋪展開來,倒映在湖水裡泛著青黛色的光,金闕般的山峰左右對開,銀河似的瀑布掛在三石梁上,香爐峰的瀑布老遠就能望見,山崖層層疊疊聳入蒼天,朝霞映著翠影紅光,連飛鳥都到不了那麼遠的天邊。他還提到那面能照見人心的石鏡,提到南朝謝靈運當年走過的地方如今已經長滿青苔——連謝公都成了過去,他卻還在,還能站在這裡把山寫成這樣。

寫到最後,他索性把盧虛舟也拉進他的幻想裡。傳說秦代有個叫盧敖的人求仙訪道,遇見神人於九垓之上,飄然遠去不知所終。太白想,盧虛舟不也姓盧嗎?這個巧合讓他忍不住笑了出來——連老天爺都在提醒他,該去過另一種日子了。他提筆寫下:先期汗漫九垓上,願接盧敖遊太清。他等的不是官復原職,也不是誰來替他平反、還他清白,他只想拉著這位盧姓朋友,一起飛到雲霄外面去,再也不回這個容不下他的朝廷。這封信寄出去的時候,他人還站在廬山的瀑布邊,水聲很大,像是替他這句話打了拍子。`
  },

  // id=73 盛唐 杜甫 〈古柏行〉rating=3
  // 詩眼：一棵活了兩千年、被人瞻仰卻沒人敢砍下來用的神木,像極了他自己空有濟世之才卻終生沒被真正任用
  // 隱藏連接：杜甫晚年病困夔州時再度憑弔武侯祠,此前已寫過懷念諸葛亮的蜀相,這回把自己寄託在廟前古柏身上
  73: {
    title: "古柏行",
    author: "杜甫",
    summary: "一棵活了兩千年、粗壯到沒人敢砍的古柏,杜甫站在樹下站了很久——他忽然明白,這棵樹跟他自己一樣,才大到沒人捨得用。",
    story: `跟你說我朋友子美晚年在夔州做的一件事——他一個人拄著拐杖,走到孔明廟前,站在那棵老柏樹下,站了很久很久,誰喊他都沒聽見。

那時候他已經病得很重,五十好幾的人,牙齒掉了好幾顆,耳朵也開始聾,靠著地方官接濟才能勉強活下去,離他年輕時想著要致君堯舜的日子已經很遠了。這是他第二次寫諸葛亮了。幾年前在成都,他寫過〈蜀相〉,替這位鞠躬盡瘁的丞相掉眼淚。這回到了夔州,他看見的不是祠堂裡的塑像,是廟前這棵柏樹——樹皮皺得像青銅器的紋路,樹根盤得像石頭一樣硬,粗到要四十個人合抱才圍得起來,高得快有兩千尺,黛青色的樹影直插天際,遠遠望去像一片烏雲卡在那裡。

他想,這棵樹是先主劉備和武侯諸葛亮還在世的時候就種下的,君臣兩個人的緣分早就散了,樹卻還在,還被後人愛惜地留著,沒人捨得動它一斧一斫。雲從巫峽那頭飄過來,連得長長一片,月光穿過雪山灑下清冷的光,樹就這樣一年一年站在原地,經歷過多少次改朝換代,自己都數不清了。子美想起自己早年也曾在成都錦亭東邊繞過武侯祠一帶,那時候他還沒這麼老,腳程還走得動,如今物是人非,廟門口的壁畫都斑駁得快看不清了,窈窕的丹青褪成一片空白,崔嵬的枝幹立在荒郊古道上,顯得格外孤高,常年迎著烈風,一副誰也不靠的模樣。他忽然想,守著這種正直挺立的姿態,靠的到底是神明的扶持,還是造化本身就偏愛正直的東西?他一時也說不清楚。

他忽然覺得這棵樹跟自己太像了。一根能撐起整座大廈的梁木,萬頭牛想拉都拉不動,可正因為它太大太貴重,反而沒人敢真的砍下來用——就這樣白白站著,任由螻蟻在樹心裡蛀出洞來,只換得幾隻鸞鳳偶爾停在香葉間過夜。他喃喃念出一句:苦心豈免容螻蟻,香葉終經宿鸞鳳。志士幽人莫怨嗟,古來材大難為用。

他知道自己這輩子的才學,大概也就跟這棵柏樹一樣,活得夠久、夠大,被人仰望、被人愛惜,卻始終沒被真正用上一次。他拄著拐杖慢慢往回走,回頭又看了那棵樹一眼——它還站在原地,一動也不動,大概還會這樣站上幾百年,等著某個跟他一樣路過的人,忽然懂了它的意思。`
  },

  // id=79 盛唐 王維 〈洛陽女兒行〉rating=3
  // 詩眼：他真正心疼、暗自認同的不是那個嫁入豪門的洛陽女兒,而是結尾那個沒人看見的浣紗越女
  // 隱藏連接：王維早年靠音樂才華出入岐王、玉真公主府邸求人賞識,此詩以越女浣紗自比尚未被發現的自己
  79: {
    title: "洛陽女兒行",
    author: "王維",
    summary: "他寫了一整首詩描寫豪門貴婦的奢華,結尾卻筆鋒一轉,寫向江邊一個沒人多看一眼的浣紗女孩——那才是他自己。",
    story: `跟你說我朋友摩詰二十出頭時寫的一首詩,表面上是寫一個有錢人家的女孩,其實藏著他自己的心事。

那幾年他還沒考上進士,在長安、洛陽之間到處找機會,行李裡永遠帶著幾幅新畫的畫和幾首新寫的詩,見人就想找機會呈上去。他彈得一手好琵琶,畫也畫得漂亮,靠著這些本事,設法混進岐王和玉真公主的府邸,想讓那些能決定他前途的人注意到他。有一回他特意換上一身鮮亮的衣裳,在岐王府裡當眾彈奏一曲,滿座都安靜下來聽,散席後好幾個人圍上來問他師從何人。他心裡當然高興,但轉頭想想,這種被人圍住的滋味,今天有,明天未必還有。他很清楚,一個人光有才華不夠,還得被看見才算數,而在被看見之前,再好的東西也只是擺在角落裡,連自己都容易忘記自己有多好。

這首詩裡他寫一個洛陽女兒,對門而居,才十五多歲,已經嫁給一個騎著駿馬、玉勒鑲金的貴公子。她家裡侍女用金盤端上鯉魚膾,住的是畫閣朱樓,門前紅桃綠柳垂到屋簷。她出門坐七香車,羅帷層層,回家有九華帳迎接。丈夫年紀輕輕就富貴逼人,講排場比晉朝的石崇還誇張。她親自教侍女跳舞,珊瑚寶物送人眼睛都不眨一下。半夜燈火燒到天亮,妝化了、舞跳累了,也沒空好好彈一段曲子,成天只是坐著熏香,城裡認識的全是趙家李家那種豪門,日日夜夜穿梭在這些人家之間。

寫到這裡,摩詰忽然把鏡頭轉了個方向,寫下最後兩句:誰憐越女顏如玉,貧賤江頭自浣紗。他想的是那個傳說中在若耶溪邊浣紗的越國女子——後來被人發現、送進宮裡,成了改變一個國家命運的西施。可是在被發現之前,她也只是江邊一個沒人多看一眼的窮丫頭,天天洗著同樣的紗,誰也不會想到她會有那樣的一天。

摩詰寫這兩句時,心裡想的未必是那個洛陽女兒有多麼空洞,他想的是自己——才華再好,沒被看見之前,終究只是江頭一個浣紗的人,天天彈著沒人聽的曲子,天天畫著沒人看的畫。他還在等那雙眼睛,等哪一天有人像當年發現越女那樣,忽然發現他。這首詩後來確實傳到了該傳到的人耳朵裡,沒過幾年,他就考中了進士。`
  },

  // id=84 盛唐 李頎 〈琴歌〉rating=3
  // 詩眼：出公差聽到一段絕美琴聲,全場忽然安靜下來的那一刻,他心裡浮現的是不想再幹這份差事了
  // 隱藏連接：彈琴者被稱為廣陵客,這個稱號讓在座懂行的人聯想到嵇康臨刑彈奏廣陵散的絕響往事
  84: {
    title: "琴歌",
    author: "李頎",
    summary: "千里公差途中一場借宿的酒局,一位廣陵客彈到滿座鴉雀無聲的那個音符,讓他當場動了辭官歸隱的念頭。",
    story: `跟你說我朋友李頎奉命出差途中的一個夜晚。他要去清淮那一帶辦公事,路程超過一千里,一路上車馬勞頓,公文夾在懷裡,走走停停,心裡想的都是路程還剩多少、明天要趕到哪一站。走到半路,借宿在一戶人家裡,主人備了酒,說今晚高興,要請一位客人彈琴,李頎本來只想早點歇下,聽這麼一說也就留下來陪坐。

那客人被稱作廣陵客。這三個字一出口,在座懂行的人心裡都咯噔一下——當年嵇康在刑場上彈完最後一曲〈廣陵散〉,丟下一句「廣陵散於今絕矣」,從此這個曲名就帶著一股絕響的悲涼,誰用這三個字自稱,多少都有點狂氣在裡面。沒人知道眼前這位客人跟那段往事有沒有關係,只知道他名號取得極重,一開口就讓人另眼相看。

外頭月亮照著城頭,烏鴉睡得東倒西歪,一半還沒歸巢。深秋的霜氣讓滿樹葉子都凍得發白,風從門縫鑽進來,吹得人衣服發涼,李頎不自覺往銅爐邊挪了挪。屋裡點著銅爐和華麗的蠟燭,燭光一陣陣搖曳增亮,把每個人的臉都照得暖洋洋的。廣陵客坐定,先彈了一曲淥水,再轉調彈楚妃——都是古老的曲名,一般人聽不出門道,可是那一聲一聲彈下去,整屋子的人漸漸忘了說話,連酒杯都停在半空中沒人想放下。

李頎記得最清楚的是那個瞬間:一個音符落下,滿座忽然全靜了下來,連呼吸都放輕,主人手裡的酒杯懸在半空忘了放下,外頭的星星也彷彿跟著稀疏下去,好像整個世界都在等這一聲琴音落定。他坐在那裡,忽然覺得自己這趟千里公差、案牘公文、迎來送往,通通都變得沒有意義——比起這一聲琴,他這幾年在驛道上奔波的日子,竟像是白白浪費掉的。他提筆寫下:清淮奉使千餘里,敢告雲山從此始。

他沒有真的辭官歸隱,至少不是馬上。第二天一早他還是收拾行李繼續趕路,清淮的公事還在等著他。但那一晚廣陵客的琴聲,在他心裡種下一顆種子——原來人可以不必永遠奔波在公文和驛道之間,原來還有一種活法,是聽完一段琴就想扔下一切去投奔雲山的。多年之後他真的辭了官,隱居在潁陽一帶,不知道會不會偶爾想起那個霜夜,想起那個叫廣陵客的人,和那個滿座忽然安靜下來的瞬間。`
  },

  // id=91 盛唐 高適 〈燕歌行並序〉rating=3
  // 詩眼：前線士兵拚死拚活的同時,將軍帳裡卻有美人歌舞助興,高適聽朋友講述見聞後把這種荒謬落差寫成詩
  // 隱藏連接：序文明言此詩寫於朋友隨張守珪出塞歸來講述見聞之後,史載張守珪確曾隱瞞敗仗謊報戰功
  91: {
    title: "燕歌行並序",
    author: "高適",
    summary: "朋友從戰場回來講完見聞,高適一夜沒睡——寫下士兵在陣前拚死、將軍帳裡卻美人歌舞的那種荒謬落差。",
    story: `跟你說我朋友高適一個晚上聽完朋友講故事之後睡不著,起來寫了一首長詩。

那個朋友剛跟著御史大夫張守珪出塞打了一仗回來。張守珪這個人,打仗確實有兩把刷子,可官場上的手腕更老練——那一年他的部隊其實吃了敗仗,他愣是把消息壓下來,報上朝廷的卻是一場大捷,朝廷還為此嘉獎了一番。高適的這位朋友就在軍中,親眼見過前線和後方是兩個世界,回來一五一十講給高適聽,講到激動處,連酒杯都拍在桌上,說起那些死在陣前、連名字都沒被記下的士兵,聲音都啞了。

高適越聽越坐不住。他自己年輕時也在薊北一帶跑過,想靠軍功博個前程,住過破廟,也啃過乾糧,深知邊塞的苦不是嘴上說說。他想像那些從榆關出發的士兵,旌旗一路逶迤到碣石山,校尉的軍書像飛的一樣送過瀚海,敵人的狼煙在狼山那頭燒起來,漢家的天子還在朝上賜下顏色、嘉獎出征的將領。到了戰場,山川蕭條,胡人騎兵借著風雨衝殺過來,士兵們在陣前拚到一半死一半活著,可就在同一個時刻,將軍帳裡的美人還在唱歌跳舞助興,絲毫不覺得有什麼不對。大漠的深秋,草都枯了,一座孤城在落日底下,能打仗的兵越打越少,士兵們身受皇恩,常常輕敵冒進,力氣用盡了,關山的圍困還是沒能解開。

高適想到那些穿著鐵衣戍守邊疆多年沒能回家的人,想到他們在城南的妻子夜裡哭得眼淚都要凝成玉筯,想到薊北的丈夫回頭望也望不到家的方向。這種苦,不是靠邊庭風沙一句話能說完的。殺氣一天到晚凝成陣雲,刁斗的聲音一整夜傳來傳去,白刃相接,鮮血四濺,誰死節報國,從來也不是為了圖什麼功勳。

寫到最後,他想起史書裡那位真正愛惜士卒、與士兵同甘共苦的李廣將軍,忍不住寫下:君不見沙場征戰苦,至今猶憶李將軍。這句話不只是懷古,也是說給張守珪那樣的人聽的——是說給整個看不見前線苦難的朝廷聽的。天亮之後,朋友已經睡了,高適把這首詩又讀了一遍,才把筆放下。他知道這首詩傳不到那些將軍耳朵裡,更傳不進朝廷的耳朵,但至少他替那些沒有名字的士兵,把這件事寫了下來。`
  },

  // id=100 中唐 白居易 〈簡簡吟〉rating=3
  // 詩眼：一個完美到不像凡人的女孩,快出嫁前忽然病死,白居易的安慰話裡藏著自己喪女之痛還沒癒合的真相
  // 隱藏連接：白居易自己三歲的女兒金鑾子夭折,他寫過多首詩哭她,蘇家簡簡的死觸動了同一種父母的無力感
  100: {
    title: "簡簡吟",
    author: "白居易",
    summary: "親事都說定了,眼看明年要出嫁的女孩,今年忽然病死——白居易去安慰蘇家父母時,想的其實是自己那個沒能長大的女兒。",
    story: `跟你說我朋友樂天寫過一首詩,是替一個他認識的朋友哭女兒的。

那女孩是蘇家的小女兒,乳名叫簡簡。這孩子從小就出眾得不像話,臉頰像芙蓉花,眼睛像柳葉那樣彎彎的。十一歲就學著拿鏡子點妝,十二歲已經能拿針線繡出一整件衣裳,十三歲坐在人群裡,舉手投足都像調教過一樣得體,從來不隨便亂了分寸,不會像其他小孩那樣披頭散髮就出來見人。她的雲髻梳得花樣百出,衣袖飄起來還帶著一股薔薇的香氣。所有見過她的人都說,這樣的姿態,實在說不出是像什麼——只覺得她整個人一動起來就像會發光一樣。

樂天聽蘇家的朋友提起這孩子好幾次,言語間全是驕傲,說將來嫁到哪家都是那家的福氣,還笑說這孩子將來一定比自己有出息。眼看她一天天長大,親事都說定了,明年就要出嫁,連嫁妝都陸陸續續在備了,蘇家人見面就提起,語氣裡都是藏不住的期待。可是二月裡忽然下了一場反常的霜,把院子裡的桃花李花全凍死了。簡簡也跟著病倒,起初只是咳嗽,家裡人都沒太當一回事,沒幾天人就燒得說不出話來,大夫請了好幾個都束手無策,還沒等到明年的婚期,今年就沒了。

蘇家父母哭得死去活來,連話都說不清楚。樂天去看他們,想不出什麼話能安慰,只能說:這孩子本來就不是凡間的人,大概是天上的仙女被貶謫下來人間走一趟,老天爺原本就只准她活十三年,你們別太傷心了。他一邊說一邊想起自己那個三歲夭折的女兒金鑾子——他哭過她好幾次,寫過好幾首詩,那種痛到現在也沒真的癒合。他其實比誰都清楚,這種安慰話說出口,連自己都騙不了。

他提筆寫下:大都好物不堅牢,彩雲易散琉璃脆。這兩句與其說是說給蘇家聽的,不如說是他寫給自己的——好東西留不住,從來不是因為它不夠好,只是老天爺從來不管這個。他把這首詩念給蘇家父母聽,兩人聽完,哭聲反而輕了一點,好像有人替他們把那口說不出的悶氣,終於說了出來。樂天回家的路上,又想起金鑾子小小的樣子,想起她也曾學著大人的樣子拿針比劃,他沒有再哭,只是走得比平常慢了一些。`
  },

  // id=118 盛唐 杜甫 〈至德二載甫自京金光門出，問道歸鳳翔。〉rating=3
  // 詩眼：兩年前他冒死穿越同一道城門去投奔皇帝,兩年後皇帝卻只用一紙調令,把他從同一道門打發出去
  // 隱藏連接：史載杜甫757年從金光門逃出長安投奔肅宗獲授左拾遺,758年因替房琯辯護被貶,又經同一道門離京
  118: {
    title: "至德二載甫自京金光門出，問道歸鳳翔。",
    author: "杜甫",
    summary: "兩年前他拚死闖過這道門去投奔皇帝,兩年後,皇帝只用一紙調令,客客氣氣地把他從同一道門送走。",
    story: `跟你說我朋友子美站在金光門下的一個下午。這道門他兩年前來過一次,那次是拚著命闖出去的;這次,是被人客客氣氣送出來的。表面上待遇好多了,他心裡卻更難受。

757年那個春天,長安城被叛軍佔著,滿街都是安祿山的兵,搜查盤問的哨卡到處都是,城裡的百姓連說話都得壓低聲音。子美原本被困在城裡,一家人也顧不上,聽說肅宗皇帝已經在鳳翔另立了朝廷,他豁出去,揀了個機會從金光門摸出城,一路提心吊膽穿過叛軍的哨卡,衣服都磨破了,鞋底也磨穿了,才逃到鳳翔投奔皇帝。那趟路有多凶險,他自己後來都說,想起來還是嚇得肝膽俱裂,魂都沒有完全叫回來過。皇帝見他這麼拚命跑來投靠,還挺感動,封了他一個左拾遺——負責在皇帝身邊提意見的諫官,官不大,子美卻覺得這輩子的抱負總算有了著落,回京邑的路上一直覺得自己終於熬出頭了,連走路的步伐都輕快了一些。

好景不長。第二年他為了替被貶的宰相房琯講幾句公道話,惹惱了肅宗。皇帝表面上沒明說要罰他,可沒過多久,一紙調令把他從左拾遺調去華州當一個管糧倉雜務的小參軍——名義上是移官任職,誰都看得出這其實是變相的貶謫,只是沒人敢說破。他收拾行李,又一次走到金光門前,這次是要跟長安的親友一個個道別,沒有人知道該說什麼話送他。

站在門口,他忽然想起兩年前也是這道門,那時候西郊全是胡人的旗幟,他是拚命想進去見皇帝一面;如今換成拚命想留下來,卻被送出去。他低聲說:此道昔歸順,西郊胡正繁。至今殘破膽,應有未招魂。近得歸京邑,移官豈至尊。無才日衰老,駐馬望千門。

他勒住馬,回頭望了一眼長安城數不清的宮門,那些門裡住著他曾經拚命想靠近的人,如今卻連道別的機會都沒有。那道金光門還是原來的樣子,城磚一塊都沒變,守門的兵換了一批又一批,兩年就把一個人的命運,從拚死進去換成失意離開。子美這一走,再也沒有回到左拾遺的位置上,往後半輩子輾轉在秦州、成都、夔州之間,離長安一年比一年遠,可他始終記得,自己也曾經是那個拚了命想進這道門的人。`
  },

  // id=120 盛唐 杜甫 〈天末懷李白〉rating=3
  // 詩眼：遠方好友蒙冤流放，自己鞭長莫及，只能靠想像替他描摹路途、替他喊冤
  // 隱藏連接：杜甫想像李白途經汨羅江，或能與屈原冤魂對話
  120: {
    title: "天末懷李白",
    author: "杜甫",
    summary: "杜甫在秦州為流放夜郎的李白憂心忡忡，寫下這首詩時，李白其實早已在白帝城遇赦，正順流而下放聲高歌。",
    story: `跟你說我朋友子美這年秋天，人在秦州，幾乎每天都要抬頭望一次西南方的天空。他心裡惦記著一個消息，一個他還不知道其實已經不用再等的消息。

那是七五九年，安史之亂還沒平定，子美自己剛剛辭了華州司功參軍的小官，一路逃難似地帶著家小走到秦州，日子過得緊巴巴。可是他心裡最放不下的，不是自己這一攤子事，是太白。

十五年前，子美和太白在洛陽第一次見面，兩人一見如故，後來又約了高適一起同遊梁宋、齊魯，騎馬打獵、飲酒論詩，白天縱馬追鹿，晚上圍著篝火喝酒吹牛，誰也不提功名的事，那是子美一輩子最快活的一段日子。後來各自散去，子美偶爾還會收到太白的信，信裡總是那副天不怕地不怕的口氣。可是這幾年，消息越來越壞：太白捲進永王李璘的案子，永王起兵失敗被殺，太白也被朝廷當成叛黨抓起來，判了長流夜郎。夜郎在哪裡？在西南的深山裡，瘴氣重，路難走，一個五十幾歲的人，這一去恐怕就回不來了。

秋風從天邊吹過來，子美站在秦州城頭，想像太白此刻走到了哪裡。江湖上秋水正漲，一葉小船在其中，不知道還要漂多久。他想起太白這輩子的文章才氣，天下沒幾個人比得上，可是命卻一路坎坷——年輕時求官不成，四處碰壁，晚年好不容易有了施展的機會，卻惹上這種殺頭的官司，倒是那些看人倒楣就開心的小人們，個個都活得滋潤。子美越想越不甘心，這世道到底是怎麼回事，才氣越高的人，越是被命運捉弄。他又想到，太白此刻的路線，說不定要經過湘江一帶，那正是當年屈原投江的地方，若兩個滿懷冤屈的靈魂真能在江邊撞見，大概有說不完的話。他把這一整年的牽掛，一口氣寫成八句：涼風起天末，君子意如何。鴻雁幾時到，江湖秋水多。文章憎命達，魑魅喜人過。應共冤魂語，投詩贈汨羅。

子美不知道的是，太白其實已經在半路上遇赦了——就在這年春天，詔書追上他到白帝城，太白狂喜之下寫下「朝辭白帝彩雲間」，一路順流而下，兩岸猿聲都還沒停，輕舟已經過了萬重山，唱著歌回了江陵，跟一群老朋友喝酒慶祝去了。他早就自由了，而且過得比誰都痛快。

可是這封平安的消息，要過很久很久才會傳到秦州的子美耳朵裡。他還在城頭上，對著西南的天空，替一個已經沒事的朋友，白白揪著一顆心。這份牽掛雖然撲了個空，卻也是子美這輩子對朋友最實在的一種心意——他從來沒把太白的委屈當成別人的事。`
  },

  // id=122 盛唐 杜甫 〈別房太尉墓〉rating=3
  // 詩眼：為了替蒙冤的恩師仗義執言，賠上自己整個官運，仍不後悔地繞道去看一眼墳
  // 隱藏連接：杜甫因上疏營救房琯而被貶華州，兩人的仕途因此永遠交纏在一起
  122: {
    title: "別房太尉墓",
    author: "杜甫",
    summary: "杜甫這輩子最大的官運轉折，是為了替房琯說一句公道話；多年後，他特意繞道去房琯墳前，還這份沒有後悔過的人情。",
    story: `跟你說我朋友子美的一次繞路。那年他從閬州出發，本該直接往東走，卻硬是拐了個彎，去看一座墳。墳裡的人叫房琯，是他這輩子最不後悔的一次仗義執言，換來的代價。

安史之亂爆發後，房琯拜相，肅宗派他率軍收復長安，結果陳濤斜一戰慘敗，幾萬將士死在那裡，車戰的老辦法對上叛軍的騎兵，幾乎是送死。朝廷震怒，要治他的罪。子美那時剛被肅宗任命為左拾遺，官小言微，照理該明哲保身，可是他豁出去了，上疏替房琯說話，說房琯是治國之才，一次戰敗不該全盤否定，更不該因為一場敗仗就毀掉一個人的一輩子。肅宗看了奏疏大怒，覺得這個小小的左拾遺竟敢頂撞天子，子美差點被下獄治罪，幸虧宰相張鎬求情才免了牢獄之災，但仍然因此觸怒天子，不久就被貶為華州司功參軍——子美的仕途，從這一刻起，再也沒有起色過，此後半生輾轉流離，靠著朋友接濟才勉強度日。

房琯後來幾度被貶，先是被貶為邠州刺史，又轉了幾個地方，762年終於等到朝廷徵召他回京，走到閬州時卻突然病倒，病逝在一間僧舍裡，身邊沒有多少人送行，連一口像樣的棺木都是臨時張羅的。子美聽到消息時，自己也正流落在外，一貧如洗，家裡三餐都成問題，可是他還是想辦法繞道閬州，去房琯墓前看一眼。

墓地很偏僻，四周荒草沒過小徑。子美勒馬停在墳前，想起當年兩人的交情——不只是官場上的知遇，更像是兩個都相信讀書人該有點骨氣的老友。他想起房琯當年也曾像謝安那樣，在強敵壓境時仍能鎮定自若地與人對弈，那份氣度，子美一直記在心裡。他又想起季札的故事——季札出使途中路過徐國，見徐君喜歡他的佩劍卻沒開口要，心裡默默記下了，等回程徐君已死，季札還是解下劍掛在墓前的樹上，只因為心裡曾經那樣想過。子美覺得自己就像季札，房琯已經聽不見了，可是這份心意，還是要送到。

他跪下來，眼淚落在墳前的泥土上，泥土本來就濕，被他哭得更濕透，連一塊乾的地方都找不到，頭頂上低低的雲層斷斷續續地飄過，好像也捨不得走。他提筆寫下八句：他鄉復行役，駐馬別孤墳。近淚無乾土，低空有斷雲。對棋陪謝傅，把劍覓徐君。唯見林花落，鶯啼送客聞。

寫完那一刻，林間果然傳來花落的聲音，幾聲黃鶯的啼叫，一路送著他往外走。子美翻身上馬，沒有回頭。這輩子他因為這個人賠上了整個官運，如果重來一次，他大概還是會這麼做。`
  },

  // id=146 中唐 白居易 〈自詠〉rating=3
  // 詩眼：自己覺得又老又病又狼狽的樣子，卻被別人當成雅事畫進屏風裡
  // 隱藏連接：無
  146: {
    title: "自詠",
    author: "白居易",
    summary: "白居易晚年自嘲又病又醉、活得像個瘋老頭，卻沒想到，這副他自己都嫌狼狽的模樣，後來成了世人眼中最風流的晚年形象。",
    story: `跟你說我朋友樂天晚年一個尋常的下午。洛陽履道里家裡，他又喝多了，臉泛著微紅，鬍鬚已經全白，嘴裡哼著不成調的歌，自己搖搖晃晃地打著拍子。角落裡有個年輕人，正拿著筆，悄悄把他此刻的樣子畫下來。

這已經不是樂天第一次被人畫了。他自己都覺得好笑——當年他寫〈長恨歌〉〈琵琶行〉那陣子，是何等意氣風發，一句同是天涯淪落人，讓多少人跟著掉淚；朝廷裡多少人搶著跟他結交，出門走一趟，路人都能認出他來。可是如今這把年紀，他過的日子，說穿了就是每天喝點小酒，病懨懨地臥在床上，瘦得像個居士，興致來了就扯開嗓子亂唱，活脫脫一個放蕩的糟老頭。他自己心裡有數，這副樣子拿去給誰看，都不會覺得多體面，換作年輕時候的他，大概會嫌自己丟人。

年輕時候的他不是這樣的。江州司馬那幾年被貶得最慘，一個當年在長安意氣風發的翰林學士，被貶到潯陽江邊當個有名無實的閒官，可是他還撐著一股勁想做點事；後來輾轉忠州、杭州、蘇州，一路做到刑部尚書，官也算做到頭了。可是官場這種東西，他看得越來越透——名利這回事，不過是百年之間隨手翻過的一頁書，轉頭再看，什麼都留不下，早年拼了命想爭的那些東西，如今想來也沒什麼意思。想通了之後，他索性在洛陽買了塊地，自號香山居士，又給自己起了個醉吟先生的外號，不上朝，不奏事，就是喝酒、寫詩、聽曲子，日子過得懶散，卻是他自己選的懶散。

那天他喝到微醺，忽然覺得眼前的日子過得挺可笑——一個曾經名滿天下的翰林學士，如今躺在床上，病歪歪地，唱歌像個瘋老頭子，還聽說有人特別喜歡他這副醉醺醺的模樣，竟然要把他畫進屏風裡，當作雅事掛起來給人看。他自己都覺得哭笑不得，提筆寫下八句：須白麵微紅，醺醺半醉中。百年隨手過，萬事轉頭空。臥疾瘦居士，行歌狂老翁。仍聞好事者，將我畫屏風。

樂天大概沒想到，這幅他自己都嫌狼狽的醉態，後來真的成了後世畫家反覆描摹的樣子——一個鬢邊帶紅、半醉半醒的老翁，成了盛唐氣象散去之後，文人心中最放得下的一種活法。他自嘲的那個下午，不知不覺，變成了千年後的人心裡，對他最深的印象。`
  },

  // id=159 中唐 韋應物 〈淮上喜會梁川故人〉rating=3
  // 詩眼：十年後重逢，笑聲和從前一模一樣，卻在笑聲裡瞥見彼此都已鬢白
  // 隱藏連接：無
  159: {
    title: "淮上喜會梁川故人",
    author: "韋應物",
    summary: "十年沒見的老友在淮上意外重逢，把酒言歡笑聲如舊，笑著笑著才驚覺彼此都已鬢髮斑白。",
    story: `跟你說我朋友韋應物的一次意外重逢。那天他在淮水邊上辦完公事，正往回走，迎面撞見一個熟悉的身影——十年沒見的梁州老友，竟然就這樣站在他面前。

兩人年輕時同在梁州客居過一段日子，那時應物還沒當上什麼像樣的官，兩個人幾乎天天湊在一塊，喝了酒就聊到後半夜，誰也沒個正經事，快活得很。有一回兩人喝醉了，在梁州城外的江邊躺了一夜，隔天醒來渾身濕透，笑罵彼此一場，這種糗事後來成了兩人重逢時最愛提的話題。後來各自被派去不同的地方當差，一別就是十年——這十年裡，應物輾轉滁州、江州，官越做越遠，書信也越寫越少，有時候半年才收到一封，有時候乾脆斷了，中間換了幾個驛卒，一封信說不定就這樣遺失在半路上。他心裡偶爾會想起那個人，想起江邊那一夜的糗事，可是想著想著，也就以為這輩子大概不會再見了。

沒想到今天在淮上，兩人竟然真的又碰上了。剛開始還愣了一下，彼此打量了好幾眼，認出對方之後，兩人幾乎是同時笑出聲來——好像十年的光陰根本沒發生過一樣，拉著手就往就近的酒館走，一坐下來就開始碰杯，連客套話都省了。

酒喝到興頭上，兩人有說有笑，聊起當年梁州的糗事，笑聲跟十年前一模一樣，連酒館裡其他客人都被他們逗得側目。可是笑著笑著，應物忽然瞥見對方鬢角一片斑白，才驚覺自己這些年也老了不少，摸摸自己的鬢角，竟也是稀疏花白的模樣。原來十年不是一句一別就能概括的，它像浮雲一樣，看著輕飄飄地就那麼飄過去了，可是飄過去的地方，人已經整個變了樣。應物想起自己這十年，從梁州到滁州，再到江州，像水一樣流過一個又一個地方，一路流到今天，才又流回這個老朋友身邊，提筆寫下八句：江漢曾為客，相逢每醉還。浮雲一別後，流水十年間。歡笑情如舊，蕭疏鬢已斑。何因北歸去，淮上對秋山。

酒喝完，夜也深了，老友問他：你這些年在外頭跑，官也換了好幾任，怎麼還不想著回北邊老家去看看？應物一時語塞，望向窗外——淮水邊上，秋山連綿，暮色一層層壓下來，他自己也說不清，到底是什麼把他一直留在外面。這句話問的是老友，更像是問他自己。那晚兩人聊到很晚才散，誰都沒提下一次還要等幾年，只是分別時多看了對方一眼，像是想把這張臉多記住一會兒。`
  },

  // id=171 晚唐 劉禹錫 〈蜀先主廟〉rating=3
  // 詩眼：英雄一手打下的江山，兩代之內就因兒子不肖而拱手讓人，亡國舊人卻若無其事地在敵國宮廷裡繼續唱歌跳舞
  // 隱藏連接：劉禹錫被貶夔州時親臨劉備託孤諸葛亮的永安宮舊址，聯想自己參與的永貞革新也因順宗早逝而功敗垂成
  171: {
    title: "蜀先主廟",
    author: "劉禹錫",
    summary: "劉禹錫站在劉備託孤的舊址前，想起自己也曾參與一場半年就垮台的改革，對人亡政息四個字，比誰都懂。",
    story: `跟你說我朋友夢得經過白帝城的那一次。那年他被貶到夔州當刺史，一到任沒多久，就特地去了城裡那座蜀先主廟——供奉的是劉備，廟就蓋在當年劉備託孤諸葛亮的永安宮舊址附近。

夢得自己這輩子，也算是嘗過事業被連根拔起的滋味。二十多年前，他跟柳宗元、王叔文一夥人搞永貞革新，想把權力從宦官手裡搶回來，轟轟烈烈幹了半年，各項新政才剛推行下去，順宗一垮台，憲宗即位，他們這些人全被貶到天涯海角，一貶就是十幾年，柳宗元去了永州，他去了朗州，一晃眼十年過去，好不容易被召回長安，又因為一首詩得罪權貴，再度被貶。所以站在這座廟前，他看劉備的故事，看得比別人多了一層感觸。

劉備當年白手起家，從一個賣草鞋的織席販履之輩，一路打到能跟曹操、孫權三分天下，靠的就是一股英雄氣——那股氣，夢得覺得，千年之後站在這裡，還是能感覺得到，凜然逼人。劉備稱帝之後還特地恢復了漢朝的五銖錢，擺明了告訴天下人，他劉備，才是漢室正統的延續。

可惜這份基業，交到手上的是誰？劉禪。夢得想起諸葛亮鞠躬盡瘁，六出祁山，拼了命想撐住這個江山，得相能開國，靠的全是諸葛亮的本事；可是生的兒子不成器，劉禪投降那天，連一句像樣的抵抗都沒有。一個英雄打下的天下，兩代之內就拱手讓人，這種反差，夢得看得心裡發涼——他自己參與的永貞革新，何嘗不是因為順宗早逝，人一走，政就息了。

最讓他唏噓的，是蜀漢滅亡後那些舊時宮裡的歌妓。當年她們在成都的宮殿裡，為劉備、為劉禪唱歌跳舞，如今蜀漢亡了，她們被擄去魏國，照樣在人家的宮廷裡繼續跳著同一支舞——彷彿什麼都沒發生過，江山換了主人，她們的舞步卻絲毫不亂。

夢得站在廟前，把這份感慨寫成了八句：天地英雄氣，千秋尚凜然。勢分三足鼎，業復五銖錢。得相能開國，生兒不象賢。淒涼蜀故妓，來舞魏宮前。

寫完他轉身離開永安宮舊址，心裡想著自己那場半年就垮掉的改革。原來不管是三國還是本朝，英雄能打下江山，卻沒人能保證，江山能一直握在對的人手裡。`
  },

  // id=216 中唐 白居易 〈錢塘湖春行〉rating=3
  // 詩眼：一個被貶過很多地方的人，唯獨在這片湖光山色前，捨不得離開
  // 隱藏連接：白居易任內疏浚西湖、修築堤壩，這首寫景詩背後其實是他少見真正落地的政績
  216: {
    title: "錢塘湖春行",
    author: "白居易",
    summary: "白居易在杭州疏浚西湖、修堤蓄水，這首單純寫景的詩，藏著他仕途裡少見的一段踏實與眷戀。",
    story: `跟你說我朋友樂天在杭州當刺史那幾年，最喜歡幹的一件事，就是騎著馬繞西湖一圈，誰都攔不住他。

他來杭州之前，日子過得並不順——先是在朝廷裡得罪人被貶江州司馬，寫下〈琵琶行〉那年，心裡苦得很，覺得自己這輩子大概就這樣了，被邊緣化在一個誰都不記得的小城裡。後來輾轉幾任，終於在822年被派來杭州當刺史。杭州這地方，山溫水軟，跟他之前待過的地方完全不一樣，他到任沒多久，就一頭栽進了西湖的春天裡，幾乎每個晴天的清晨都要騎馬出門逛一圈，屬下都笑他像個第一次進城的孩子。

那天他從孤山寺北邊出發，一路騎到賈公亭西側，湖面剛剛漲平，跟遠處低垂的雲幾乎連成一片，好像伸手就能摸到。幾隻早來的黃鶯在爭搶向陽的樹枝，吵得歡快；不知道誰家的新燕子，正銜著春天的濕泥，一趟一趟飛回去築巢，忙得連歇一口氣的功夫都沒有。

樂天騎得慢，看得認真。路邊的野花開得正盛，紅的白的紫的堆在一起，開得他眼睛都花了；淺淺的春草才剛冒頭，馬蹄踩下去，幾乎要把整隻蹄子都陷進草裡看不見，他忍不住低頭多看了兩眼。他知道自己這幾年在忙什麼——杭州的水利年久失修，西湖淤積，灌溉不到周邊的農田，一到旱年百姓就苦。他上任後帶著人疏浚湖底，重修堤壩蓄水，把湖水的閘門調節得妥妥當當。這些事瑣碎又累人，不像寫詩那樣痛快，常常一整天泡在泥水裡，可是每次騎馬經過修好的堤岸，看著湖水一寸寸漲起來，他心裡就有一種說不出的踏實，比寫出一首好詩還要滿足。

騎到湖東邊那條白沙堤附近，兩排綠楊夾道，樹蔭底下涼風習習，樂天勒住馬，捨不得再往前走了。他想，這輩子被貶過那麼多地方，江州、忠州都待過，唯獨這裡，是他真心捨不得離開的。他提筆寫下八句：孤山寺北賈亭西，水面初平雲腳低。幾處早鶯爭暖樹，誰家新燕啄春泥。亂花漸欲迷人眼，淺草才能沒馬蹄。最愛湖東行不足，綠楊陰裏白沙堤。

後來樂天離任時，把剩下的官俸都留在州庫裡，交代後人拿去修水利用，一分都沒往自己家裡帶。他沒有留下多少財產，倒是這條堤、這片湖，還有這首詩裡騎不完的春天，留到了今天，成了西湖春天最好的名片，也成了後人記住他這幾年杭州刺史生涯，最溫柔的一個註腳。`
  },

  // id=225 中唐 李賀 〈雁門太守行〉rating=3
  // 詩眼：一個因避諱被剝奪科舉資格、永遠上不了戰場的人，用想像力打了一場最壯烈的戰爭
  // 隱藏連接：無
  225: {
    title: "雁門太守行",
    author: "李賀",
    summary: "李賀因父親名諱被擋在科舉門外，一輩子沒摸過戰場，卻在詩裡想像出了唐詩中最慘烈壯闊的一場血戰。",
    story: `跟你說我朋友長吉一輩子沒上過戰場，卻寫出了唐詩裡最慘烈的一場戰爭。

長吉是李賀，河南昌谷人，從小就聰明得嚇人，七歲能寫詩，韓愈聽說了都特地跑去考他，當場出題，長吉提筆立就，滿座賓客都驚得說不出話。照理說，這樣的才華，考個進士應該不成問題，家裡人也都指望他這一趟能光宗耀祖。可是他偏偏栽在一個荒唐的理由上——他父親名叫李晉肅，晉跟進士的進同音，按當時的避諱規矩，兒子考進士就是犯了父親的名諱。有人看他年少成名，眼紅得很，故意拿這個理由去攻擊他，逼得他不敢應試。韓愈氣不過，特地寫了一篇〈諱辯〉替他辯護，一條一條駁斥這種說法根本說不通，可是輿論這種東西，講不講理都沒用，眾口鑠金，誰也擋不住。長吉最後還是被擋在了科舉門外，一輩子只能靠著父蔭，做個從九品的奉禮郎，管一些祭祀的雜事，跟他心裡想的那種建功立業，差了十萬八千里。

一個能寫下驚天動地句子的人，連上戰場建功立業的資格都沒有。長吉心裡的那股不甘，白天在祭祀的雜務裡耗著，夜裡回到住處，就著一盞孤燈，沒地方發洩，就全灌進了詩裡。

他從沒真正見過戰場，可是他想像力比誰都猛。他想像敵軍壓境，黑雲厚得像要把城牆壓塌；我方將士的鎧甲在陽光下閃著金光，一片一片像魚鱗；號角聲響徹秋日的天空，塞外的胭脂色混著夜色凝成一片紫紅——那是他想像中，最壯烈也最悲涼的顏色。半卷的紅旗，趁夜急行軍趕到易水邊上，那是當年荊軻辭別燕太子丹的地方；霜降得又重又冷，連戰鼓都敲不響了，可是將士們還是咬牙往前衝。

長吉提筆，把這份他自己一輩子都沒機會兌現的豪情，全部寫進了這八句裡：黑雲壓城城欲摧，甲光向日金鱗開。角聲滿天秋色裏，塞上燕脂凝夜紫。半卷紅旗臨易水，霜重鼓寒聲不起。報君黃金臺上意，提攜玉龍為君死。黃金臺是燕昭王當年築台招賢的地方，他借這個典故，讓詩裡的將士說出自己最想說的話——如果有人真心賞識我，我願意提著劍，為他去死。

長吉自己二十七歲就病死了，一輩子沒摸過真正的戰場，也沒等到那個黃金臺上的知遇。可是他在詩裡打贏了，或者說，他在詩裡死得其所——那份沒能施展的豪情，靠著幾行字，硬是燒了一千多年，燒到現在都還亮著。`
  },

  // id=226 中唐 韓愈 〈早春呈水部張十八員外二首〉rating=3
  // 詩眼：早春草色若有若無最容易被錯過，趕緊寫信催老朋友別等花開才出門
  // 隱藏連接：無
  226: {
    title: "早春呈水部張十八員外二首",
    author: "韓愈",
    summary: "韓愈怕老朋友張籍錯過早春最美的那幾天，寫信催他快去看，還先堵住對方可能拿公務忙、人老了當藉口的話。",
    story: `跟你說我朋友退之寫給老朋友的一封快點出門的邀請信。那年春天一場小雨剛停，他人在長安，一大早推開門，就急著要把這個消息告訴文昌——不然等他自己去看到，可就晚了。

文昌就是張籍，官居水部員外郎，家裡排行十八，退之提攜他很多年了——當年張籍還是個窮書生的時候，就是退之一路引薦、一路提點,兩人亦師亦友，交情深到可以互相損兩句，誰的詩寫得不順手，也只有對方敢直接開口挑毛病。退之自己這時候已經做到吏部侍郎，公務堆得滿桌子，天天有處理不完的文書，按理說，這種級別的官，早該沒空管什麼草色不草色的閒事了。

可是那天早晨的雨後，他站在長安的街上，看見天街上的小雨把地面潤得像酥油一樣滑亮，低頭一瞧，草色似乎有了一點綠意，可是遠遠望過去分明看得見，湊近了仔細看，又幾乎什麼都沒有。這是早春才有的曖昧——早一步看，是若有似無的一層綠；晚一步看，草就長高了，綠得扎眼，反倒沒有這份剛剛好的驚喜。退之在街上站了好一會兒，心想，這種景色最容易被人錯過，過幾天等到滿城柳絮飛揚、煙柳滿城的時候再去看，人人都看得到，那有什麼稀奇，倒不如現在，趁著這股若有若無的綠意還在，趕緊叫上人一起去看。

他趕緊回府提筆寫信給文昌，怕他又用公務忙、人老了沒那個心情當藉口推辭——他太了解這個老朋友了，兩人年紀都不小，官也越做越忙，難免懶得挪動腳步，寧可窩在家裡喝茶看公文。退之乾脆先堵住他的嘴，話裡帶著幾分損友式的調侃，又不放心地叮嚀他順路去探探柳色，一口氣寫下八句：天街小雨潤如酥，草色遙看近卻無。最是一年春好處，絕勝煙柳滿皇都。莫道官忙身老大，即無年少逐春心。憑君先到江頭看，柳色如今深未深。

信送出去那天，退之自己心裡也有點期待，不知道文昌收到信會是什麼表情，會不會嘴上抱怨兩句，腳下卻已經往城外走了。這封信後來成了千古傳誦的早春名作，可是退之寫的時候，想的沒那麼多，他就是捨不得一個老朋友，錯過這年最好的那幾天，也捨不得自己一個人偷偷把這片春色看完。`
  },

  // id=242 晚唐 李商隱 〈無題二首之一〉rating=3
  // 詩眼：一輛擦身而過的香車，車簾裡似乎坐著認得的人，車聲太響、時間太短，一句話都沒能問出口
  // 隱藏連接：無（無題詩本事歷來眾說紛紜，考據不足，誠實以相傳處理）
  242: {
    title: "無題二首之一",
    author: "李商隱",
    summary: "李商隱這首無題詩，寫的是所有人都懂的心情：一輛擦身而過的香車，一句沒能問出口的話。",
    story: `跟你說我朋友義山有一年在長安，親眼看著一輛香車從自己面前隆隆駛過，車簾裡似乎有一張他認得的臉，可是車輪聲太響，那幾秒鐘太短，他一句話都沒能問出口。

這是義山許多首無題詩共有的底色——連他自己身邊最親近的朋友，後來讀到這些詩，都猜不透他寫的到底是誰。有人說是他早年在玉陽山學道時愛慕的女道士，有人說是令狐楚家裡某個他見過幾面的婢女，也有人說，不過是他借兒女情長，暗中寫自己在牛李黨爭裡進退兩難的處境——義山娶了李黨王茂元的女兒為妻，卻是牛黨令狐楚一手提拔起家的，這樁婚事讓他兩邊都不討好，一輩子仕途都困在夾縫裡。真相究竟是哪一種，連當時人都說不準，只能誠實地說一句，相傳如此，誰也不敢坐實。

但那種差一點就能說上話的心情，是真的。故事裡那個深夜還在縫製鳳尾紋絲羅、碧紋圓頂帳子的女子，或許正在為自己將要嫁作他人婦準備嫁妝，一針一線縫得又慢又細，彷彿想把時間拖長一點；她拿團扇遮住半張臉，那扇子裁得像月亮一樣圓，可是再怎麼遮，也擋不住那份羞怯，眼神卻忍不住往車窗外瞟。義山記得自己曾經在某個寂寥的夜裡，守著快燒盡的燭火等一個消息，燈燼一點一點暗下去，他也不捨得添油，就那樣坐到天亮，可是等到石榴花都開了，消息還是斷得乾乾淨淨，一點回音都沒有。

那天香車駛過的瞬間，他多想衝上前去，可是車輪滾滾像打雷一樣，一晃眼就過去了，什麼都沒能說出口。他站在原地，看見那匹拴在垂楊岸邊的青白花馬，不知道是不是她的坐騎。他心裡忽然湧出一句話——要是有一陣西南風，肯不肯替我把這句話捎過去。他把這份說不出口的悵然寫成了八句：鳳尾香羅薄幾重，碧文圓頂夜深縫。扇裁月魄羞難掩，車走雷聲語未通。曾是寂寥金燼暗，斷無消息石榴紅。斑騅只繫垂楊岸，何處西南任好風。

這首詩題目乾脆就叫無題——義山大概也想通了，有些心事本來就沒辦法安一個明確的名字，寫出來讓人猜，比說破了更接近他當時真正的心情。千年之後，讀的人依然在猜，而那陣他盼望的西南風，始終沒有吹來過。`
  },

  // id=245 晚唐 溫庭筠 〈蘇武廟〉rating=3
  // 詩眼：十九年含辛茹苦盼著回歸，回去才發現，等待你的那個世界早已不是你離開時的樣子
  // 隱藏連接：溫庭筠自己懷才不遇、仕途坎坷，或許正因如此才對蘇武物是人非的蒼涼格外有共鳴（此為推測，非史實記載）
  245: {
    title: "蘇武廟",
    author: "溫庭筠",
    summary: "蘇武熬過十九年北海牧羊終於歸漢，卻發現送他出使的皇帝早已駕崩多年，連宮殿的陳設都換了模樣。",
    story: `跟你說我朋友飛卿站在蘇武廟前，看著那兩株比廟還老的古樹，忽然覺得，十九年這個數字，比任何典故都更叫人心驚。

蘇武的故事飛卿從小就聽熟了：漢武帝派他出使匈奴，那時候他還是壯年，佩劍戴冠，意氣風發；結果匈奴扣住他不放，逼他投降，他寧死不從，被流放到北海去牧羊，說什麼時候公羊生了小羊，才放他回去——這擺明了是一句不會兌現的話。蘇武就這樣在冰天雪地裡放了十九年的羊，靠著僅有的節杖撐著，節毛都掉光了。相傳他靠著一封綁在大雁腳上的信，才讓漢朝知道他還活著，朝廷這才想辦法把他要了回來。

飛卿站在廟前想，十九年，一個人從壯年熬成了白頭老翁，北海那地方冬天冷得能把睫毛凍住，他就靠著幾隻野鼠和草籽撐過最難熬的日子，支撐他的是什麼？大概就是一個念頭——漢朝還在，家鄉還在，總有一天能回去。可是等他真的回到長安，才發現漢武帝早就死了十幾年，連皇帝寢殿裡的陳設都換了好幾輪，昭帝繼位、宣帝又繼位，朝堂上站著的都是他不認得的臉孔，當年送他出使的那個人，再也見不到了。他心心念念要回報的那個朝廷，已經不是他離開時的那個朝廷。

飛卿自己這輩子也是懷才不遇，考了好多年科舉都沒考上，還因為恃才傲物、行為放蕩，喜歡替人代筆應考，得罪了不少權貴，一輩子官場路走得坎坷，眼看著同輩一個個做了大官，自己還在四處奔波求一個安穩的差事。他站在這座古祠前，或許正是因為自己也嘗過那種等了很久、回頭卻發現世界已經不一樣的滋味，才對蘇武這份物是人非的蒼涼，格外有共鳴——當然這終究只是飛卿一個晚唐失意文人的自身投射，蘇武本人當年究竟是怎麼想的，已經沒人問得到了。

他提筆寫下八句：蘇武魂銷漢使前，古祠高樹兩茫然。雲邊雁斷胡天月，隴上羊歸塞草煙。迴日樓臺非甲帳，去時冠劍是丁年。茂陵不見封侯印，空向秋波哭逝川。

蘇武歸漢後，朝廷只給了他一個典屬國的閒職，並沒有封侯——他用十九年換來的，不過是一個不大不小的官銜，和一段誰都佩服卻沒人能真正體會的孤獨。飛卿寫完最後一句，對著秋天的江水看了很久，水一直在流，誰也留不住。`
  },

  // id=256 盛唐 李白 〈玉階怨〉rating=3
  // 詩眼：一整夜的沉默等待，用露水羅襪代替一個字的抱怨
  // 隱藏連接：李白自稱一生低首謝宣城，此詩明著承襲謝朓同題舊作，是向偶像遞出的一張戰帖
  256: {
    title: "玉階怨",
    author: "李白",
    summary: "整首詩沒有一個怨字，卻是李白刻意向偶像謝朓下的戰帖——用沉默寫盡了宮女等到露水濕透襪子的委屈。",
    story: `跟你說我朋友太白在翰林院當差的時候，做過一件怪事——他跟一個三百年前死透的人較勁了一整晚，對方甚至不知道有這回事。

那人叫謝朓，南朝的謝宣城。太白這輩子最佩服的詩人不是屈原，不是陶淵明，是這位英年早逝、四十幾歲就死於冤獄的謝朓。他常掛在嘴邊一句話，一生低首謝宣城，逢人就誇謝朓的詩乾淨得像秋水。謝朓曾經寫過一首宮怨詩，題目就叫玉階怨，四句話沒有一個怨字，卻把宮女等到腿軟的委屈寫盡了。太白年輕時讀過，一直記在心裡，想著哪天要跟這位偶像過過招，看看自己能不能寫出更狠的沉默。

天寶初年他被召進宮當供奉翰林，常常半夜被叫去起草詔書，一等就是幾個時辰，宮裡的規矩多，誰也不敢多說一句話。有一晚他候在偏殿外面，天氣已經轉涼，他看見一個宮女站在玉階上，久久沒有動。露水已經打濕了台階，她的羅襪早就濕透，貼在腳踝上，她卻還站著，不知道在等誰，也可能什麼都不等，只是站著也算一種活著的方式。太白站在遠處看她，一直沒敢上前打擾，忽然覺得這比任何典故都更像謝朓那首詩要寫的東西。

她終於轉身，放下水晶做的簾子，隔著簾子抬頭看外頭那輪秋月，一句話沒說，臉上也沒有表情，動作輕得像是怕驚動誰。太白站在陰影裡，看著那層薄薄的簾幕把她的側臉切成一道模糊的光影，忽然覺得，什麼話都不必說出口，這一站一望，比任何哭訴都更響。

太白回去之後，把這一幕寫成四句話，玉階生白露，夜久侵羅襪。卻下水晶簾，玲瓏望秋月。他刻意學謝朓，一個怨字都不用，連她在等誰、等了多久都不交代，只留下露水、羅襪、水晶簾跟月亮，讓看的人自己去補那份委屈。

有人後來評這首詩，說太白這回是真的贏了謝朓一次——謝朓寫的是想像，太白寫的是他親眼撞見的一個晚上。那個宮女後來怎麼樣，宮裡沒人記載，太白也沒再提起過，好像那晚之後，她就只活在這二十個字裡。只是這四句詩流傳了一千多年，每個讀到的人，都替那個素未謀面的女子，在心裡多站了一會兒，陪她看完那輪秋月。`
  },

  // id=259 盛唐 李白 〈夜宿山寺〉rating=3
  // 詩眼：日後天子呼來不上船的狂徒，此刻卻小心翼翼怕吵到看不見的神仙
  // 隱藏連接：相傳此詩寫於李白少年在蜀中匡山讀書、夜宿山寺的一次夜遊
  259: {
    title: "夜宿山寺",
    author: "李白",
    summary: "這個後來狂到敢讓皇帝等他上船的人，十幾歲那年站在百尺高樓上，卻小聲說話怕吵到天上人。",
    story: `跟你說我朋友太白十幾歲時的一件糗事——說糗事也不太對，應該說是他這輩子難得一次的小心翼翼，安靜到連自己都覺得陌生。

那時候他還沒出四川，老家在江油匡山一帶讀書，白天練劍讀書，晚上跟同伴到處亂跑。相傳有一次他跟著同伴上山遊玩，貪看風景走得太遠，天黑前趕不及下山，只好夜宿在山頂一座廟裡過夜。那廟蓋在懸崖邊，樓很高，傳說有百尺，晚上風一吹整座樓的木板都在吱呀作響。少年太白從沒住過這麼高的地方，一開始還嘴硬說有什麼好怕的，扯著同伴的袖子就往樓頂衝，結果爬到樓頂，伸手就摸到滿天星星那麼近，密密麻麻掛在頭頂，他整個人愣住了，連平常最愛耍嘴皮子的那張嘴，一時間都忘了要說什麼。

同伴還在旁邊大聲說話，講些山下的閒事，太白突然伸手做了個噤聲的手勢，壓低聲音說小聲一點。同伴不解，問怕什麼，這山上又沒有老虎野獸。太白搖搖頭說不是怕老虎，是這裡離天太近了，大聲講話怕吵到樓上住的神仙，人家好不容易安靜地掛在那裡，何必去驚動人家。

這句話後來被人當笑話講，說太白年紀輕輕就會胡扯瞎編。可是認識他的人都知道，這不是胡扯，是他那個年紀難得表現出來的敬畏。這個後來會寫出天子呼來不上船、我輩豈是蓬蒿人的狂徒，此刻站在百尺高樓上，手還懸在半空中沒敢真的碰到那些星星，卻怕自己的聲音驚動了誰。

他站在樓頂待了很久，風很大，吹得衣角獵獵作響，星星看起來確實伸手可及。他小聲跟同伴說，你聽，這裡什麼聲音都沒有，連風都是輕輕的，好像大家都在讓著這片天，誰也不敢造次。

回去之後他把那一夜寫成四句，危樓高百尺，手可摘星辰。不敢高聲語，恐驚天上人。

後來太白走遍大半個中國，見過長安的繁華，也見過流放路上的荒涼，狂傲了半輩子，什麼權貴都敢頂撞，什麼皇帝面前都敢擺架子。可每次有人提起這首少年時寫的詩，他都笑而不答，好像那個站在樓頂噤聲的少年跟後來那個狂徒是兩個人。也許他自己都忘了，曾經有一整夜，他小心翼翼到連呼吸都放輕，只因為怕吵到看不見的什麼人。那份謙卑，後來的他再也沒寫過第二次，卻被同伴悄悄記住，一路傳到今天。`
  },

  // id=261 盛唐 杜甫 〈八陣圖〉rating=3
  // 詩眼：功業做到滿分，卻被自己效忠的主公一個決定毀掉，這種輸法最沒地方喊冤
  // 隱藏連接：杜甫晚年漂泊夔州，境遇與諸葛亮生前未竟的抱負相互映照
  261: {
    title: "八陣圖",
    author: "杜甫",
    summary: "石頭擋得住江水沖刷千年，卻沒人擋得住劉備一意孤行——諸葛亮的遺恨，杜甫在夔州江邊全懂了。",
    story: `跟你說我朋友子美在夔州江邊站了很久的一個下午，他去看一堆石頭，別人覺得沒什麼好看的石頭。

那是諸葛亮擺下的八陣圖遺跡，幾百年前用鵝卵石堆成六十四堆，按照特定陣法排列，傳說能困住千軍萬馬，讓敵軍摸不清方向自亂陣腳。子美那年五十五歲，離開成都草堂，帶著一家老小順江漂泊到夔州，身體已經很差，肺病加上風濕，眼睛也花了，走幾步路都喘，還要靠拄杖。他去看八陣圖那天，江水很急，沖刷了五百多年，河床都改了好幾道，那些石堆卻紋絲不動，任憑水怎麼衝都衝不散，也沖不掉。

子美站在那裡，拄著杖，看了很久，想起諸葛亮這個人。三分天下，諸葛亮的功業已經做到頭了，劉備能在蜀地稱帝，一大半是他隆中對裡就定下的謀劃。可是諸葛亮這輩子有一個算不進去的變數，就是劉備這個人。諸葛亮一直主張聯合東吳抗曹，這是整個戰略的核心，關係到蜀漢能不能活下去。可是劉備為了給結拜兄弟關羽報仇，不聽勸，執意親自率軍伐吳，結果在夷陵一戰打得慘敗，幾十萬大軍幾乎全軍覆沒，蜀漢元氣大傷，聯吳抗曹的大局徹底毀了。諸葛亮當時遠在成都，眼睜睜看著自己一生的布局被自己最信任的主公一個決定毀掉，卻連攔都攔不住。

子美自己這輩子也在攔不住的事情裡打轉。他一直想效忠朝廷、匡扶社稷，年輕時寫過致君堯舜上，再使風俗淳這樣的話，可是安史之亂爆發，他自己被叛軍抓過，逃出來投奔朝廷做過小官又因直言被貶，一路漂泊到四川、到夔州，家人跟著他吃盡苦頭。他眼看著自己的抱負跟諸葛亮的遺恨一樣，永遠沒機會兌現了。他蹲下來看著江流石不轉那幾堆石頭，忽然覺得，這些石頭比任何人的功業都更長久，可是石頭擋得住江水，卻擋不住人心裡那一口氣咽不下去。

他站起來，對著江水，把心裡的話寫成四句，功蓋三分國，名成八陣圖。江流石不轉，遺恨失吞吳。

子美後來還在夔州住了將近兩年，寫下他一生最多的詩，卻始終沒能回到長安，最後病死在湘江的一條小船上。他大概是在那些石堆前面，第一次真正懂了諸葛亮的遺恨是什麼滋味——不是輸給敵人，是輸給自己最信任的人一個攔不住的決定。`
  },

  // id=262 盛唐 王維 〈息夫人〉rating=3
  // 詩眼：借六百年前的古人酒杯，在酒席上當眾逼一位親王讓步
  // 隱藏連接：相傳《本事詩》記載的寧王奪人妻軼事，是這首懷古詩的真正現場
  262: {
    title: "息夫人",
    author: "王維",
    summary: "王維沒有正面說一句話，卻用六百年前的息夫人，當眾逼親王把搶來的妻子還給了原本的丈夫。",
    story: `跟你說我朋友摩詰有一次寫詩，救了一個他從沒見過面的女人，而且是當著全場權貴的面救的。

相傳開元年間的長安，寧王李憲家裡辦宴席，高朋滿座，絲竹不斷。寧王是玄宗的親哥哥，當年為了讓弟弟順利繼位，主動讓出太子之位，換來一輩子的尊榮與權勢，家裡養了一堆歌姬舞女，出手闊綽誰都不敢惹。據說寧王府旁邊有個賣餅的人，妻子生得很美，皮膚白淨，寧王有一次路過看上了，直接叫人把人搶進府裡，賞了賣餅人一筆錢當作交代，賣餅人敢怒不敢言，只能眼睜睜看著妻子被抬走。過了一年多，寧王擺酒，賓客盡歡，他忽然想起這件事，覺得有趣，叫人把那個女人喚出來，又叫人把那個賣餅的丈夫也找來，想看看她還認不認得原來的丈夫，當作酒席上的一齣餘興。

那女人一出來，看見丈夫站在角落，粗布衣裳，手足無措，她的眼淚一下子就掉下來了，一句話都沒說，也不看寧王一眼，只是死死盯著丈夫。滿座賓客先前還在說笑，這下全都尷尬住了，氣氛一時僵在那裡。寧王也覺得沒趣，臉上有點掛不住，回頭叫在座的文人各自賦詩解圍，摩詰也在場。

摩詰沒有直接寫眼前這件事，他寫了六百年前春秋時代的一個女人，息國的夫人息媯。息媯當年被楚文王滅了息國，擄回楚國強納為妃，她跟著楚王生了兩個孩子，衣食無缺，卻始終一句話都不跟楚王說，連笑都很少笑。摩詰把息夫人的故事寫成四句，看著眼前那個賣餅人的妻子，借古人的酒杯，澆今人的塊壘，莫以今時寵，難忘舊日恩。看花滿眼淚，不共楚王言。

滿座賓客聽完都沉默了。這四句表面在講幾百年前的息夫人，誰都聽得出來說的是眼前這件事，摩詰的膽子讓在座的人都替他捏了把冷汗。寧王當場臉色一變，愣了半晌，相傳他當下就把那女人放回去，讓她跟原來的丈夫團圓，也算保住了自己的顏面。

摩詰後半輩子信佛，寫了很多空山無人的詩，人們常說他清淡出世。可是這首詩提醒人，他年輕時也曾經在權貴的酒席上，拿一首詩去逼一個親王讓步。那個賣餅人跟他的妻子後來過得怎麼樣沒有記載，但摩詰這四句詩，替一個不敢說話的女人，把話說完了。`
  },

  // id=269 盛唐 孟浩然 〈宿建德江〉rating=3
  // 詩眼：每次靠岸過夜，天一黑，鄉愁就重新長出一次，不是舊愁在延續
  // 隱藏連接：此詩寫於孟浩然長安應試落第、又因不才明主棄一語觸怒玄宗之後的吳越漫遊途中
  269: {
    title: "宿建德江",
    author: "孟浩然",
    summary: "他躲過皇帝的床底沒躲過皇帝的臉色，一句詩葬送仕途後，孟浩然在建德江邊，愁出了一個新的黃昏。",
    story: `跟你說我朋友浩然把船停在建德江邊的那個黃昏，他心裡湧上來的愁不是舊愁，是剛剛長出來的新愁，連他自己都覺得奇怪，怎麼又來一次。

浩然四十歲那年才第一次去長安考試，這之前他一直隱居在襄陽鹿門山，讀書寫詩，交遊四方，名氣早就傳開了，可就是遲遲沒去考試，一考就砸了。落第之後他沒有立刻回襄陽，留在長安晃了一陣子，心裡不甘，經人介紹認識了王維，兩人一見如故。有一天他在王維家裡作客，兩人聊得正好，唐玄宗忽然駕到，要來看看王維。浩然嚇得慌了手腳，躲到床底下，王維不敢隱瞞皇帝，如實稟報床下藏著一個落第書生。玄宗聽說是浩然，早就聽過他的詩名，反倒高興，叫他出來，要他當場唸一首近作聽聽。浩然戰戰兢兢唸了一首詩，裡頭有一句不才明主棄，多病故人疏。玄宗聽完臉色沉下來，說你自己不來求官，怎麼能怪我棄用你，從此再也沒有人敢舉薦他，這件小事把他半輩子的機會都堵死了。

這件事之後，浩然的仕途算是徹底斷了。他心灰意冷，離開長安，一路往南漫遊吳越，散心也好，逃避也好，走一步算一步。這天他把船划到建德江邊，傍晚天色暗下來，靠岸過夜。江面上煙霧繚繞，四周空曠，遠處的樹好像比天還低，倒是江水清澈，月亮的倒影近得好像貼在船邊，伸手就能碰到。

按理說景色這麼美，人該覺得安慰才對。可是浩然坐在船頭，裹著單薄的外衣，心裡湧上來的愁緒卻是新的，不是他從長安帶出來的舊愁，是每次停船過夜，天一黑，那份寄人籬下、有家歸不得的感覺就重新冒一次頭，像潮水一樣準時。江上的月亮看起來離他很近，家鄉卻遠得沒有邊，他知道再往前划幾天，也未必划得到心裡想去的地方。

他把眼前這一幕寫下來，移舟泊煙渚，日暮客愁新。野曠天低樹，江清月近人。

浩然這輩子沒有再進過長安的考場，一直到五十二歲病死在襄陽老家附近，因為背上生瘡又貪食舊友送來的鮮魚，病發身亡。他漫遊吳越那幾年寫的詩，後人讀起來總覺得比他年輕時寫得更好——大概因為那時候他終於不用再裝作雲淡風輕，新愁舊愁，都老老實實寫進了詩裡，不再遮掩。`
  },

  // id=271 盛唐 崔顥 〈長干行二首之一〉rating=3
  // 詩眼：陌生人之間一句大膽的搭訕，底子裡全是害怕自己是唯一一個想家的人
  // 隱藏連接：崔顥早年因豔情詩風被史書評為有文無行，與晚年寫下黃鶴樓的形象形成強烈反差
  271: {
    title: "長干行二首之一",
    author: "崔顥",
    summary: "一句或恐是同鄉，聽起來像搭訕，其實是江面上一個異鄉人，確認自己不是唯一想家的人。",
    story: `跟你說我朋友顥年輕時寫過一組情詩，寫得太好，好到後人常常忘記他還寫過黃鶴樓，忘記他也能寫出讓李白擱筆的句子。

顥年輕時是出了名的浪蕩才子，史書上說他有文無行，意思是文采好，人品和行事卻不太檢點，好賭博，喜歡喝酒，還換過好幾任妻子，選妻子的標準只看容貌，喜新厭舊換得很快。這樣的名聲讓他前半輩子一直不受朝廷重用，考中進士也沒得到什麼像樣的差事，寫的詩也多半是這種豔情風格，長干行就是其中最出名的一組，一共兩首，一問一答。

長干是金陵城外秦淮河邊的一片里巷，住的多半是做生意的商人跟他們的家眷。丈夫常年在外經商，一去經年，妻子獨守空船空屋，日子過得孤單，鄰里之間走動也少，江上往來的都是陌生的商船。顥想像了這麼一個場景，一艘船划過來，船上的女子聽見鄰船口音有點像家鄉話，心裡一動，忍不住停下船，隔著水面喊了一聲，問對方是哪裡人。她說自己住在橫塘，語氣帶著小心翼翼的試探，又補了一句，對方要是住得近，說不定還是同鄉。

這一聲搭訕，聽起來大膽，其實底子裡全是孤獨。她未必真的想認識這個陌生人，也不指望對方真能答上她的鄉音，她要的只是那一瞬間，聽見一個可能懂她鄉音的人，確認自己不是這片江面上唯一一個想家的人。顥把這個瞬間寫成四句，君家何處住，妾住在橫塘。停船暫借問，或恐是同鄉。

這首詩流傳出去，大家都誇顥寫閨情寫得傳神，把小女子的心思拿捏得又準又細，可也順帶坐實了他輕薄的名聲，覺得他就是個只會寫兒女情長的浪蕩子，難堪大用。沒人想到十幾年後，他登上黃鶴樓，寫下那首讓李白甘拜下風、擱筆不敢再題的黃鶴樓，才讓所有人重新認識他。

顥後來的人生從浪蕩才子變成受人敬重的邊塞詩人，風格轉了一個大彎，寫起邊關風沙也氣勢十足，連當年笑他輕薄的人都改了口。可是回頭看長干行這首小詩，那份藏在搭訕背後的孤獨，其實跟他後來寫的鄉愁，是同一種東西，只是換了個講法而已——年輕時想家想的是同鄉，年老後想的是整個故國，說到底都是同一顆漂泊的心，只是換了個江面，換了個嗓音。`
  },

  // id=276 中唐 白居易 〈池上〉rating=3
  // 詩眼：見識過官場最深的算計，反而被一個笨拙到藏不住秘密的孩子治癒了
  // 隱藏連接：白居易晚年子女早夭、過繼嗣子，膝下有一塊沒填滿的空缺，映照他對鄰家孩童的格外留意
  276: {
    title: "池上",
    author: "白居易",
    summary: "見過牛李黨爭、江州被貶那些算計人心的把戲，白居易晚年卻被一個連水痕都藏不住的偷藕小孩逗笑了。",
    story: `跟你說我朋友樂天晚年在洛陽家裡看小孩偷藕的一個下午，看著看著自己先笑出聲來。

樂天晚年退居洛陽履道里的宅子，院子裡挖了一方池塘，種滿白蓮，還養了幾隻鶴，日子過得清閒。他這輩子見識過官場最深的算計——早年因為寫詩太直白得罪權貴，被貶到江州當司馬，夜裡送客潯陽江頭，聽琵琶女彈一曲就哭濕了衣襟；後來又捲進牛李黨爭，兩邊都不敢得罪，做人做得步步小心，乾脆自請外放，輾轉杭州、蘇州，晚年才回洛陽半官半隱住下來。他一生看過的人心曲折，城府深淺，夠寫好幾本書。

膝下的孩子他也沒能留住，女兒金鑾子三歲夭折，兒子阿崔也沒能長大，晚年只能過繼侄子當嗣子，家裡雖然安靜，他對小孩子這種東西，心裡總有一塊沒填滿的地方，看見鄰家孩童總要多看兩眼。

那天他坐在池邊乘涼，搖著蒲扇，看見一個鄰家的小孩，划著一艘小船，偷偷摸摸把船划進蓮花叢裡，東張西望確認沒人看見，摘了幾支白蓮就急急忙忙往回划，划槳的動作又急又亂，恨不得快點上岸。那小孩以為神不知鬼不覺，得意得很，偷瞄了一眼岸上，發現沒人注意，臉上還帶著一絲得逞的笑。可是船划過的水面，浮萍被撥開一條明顯的水痕，從蓮叢一路連到岸邊，光明正大攤在那裡，比任何腳印都清楚，想藏都藏不住，連個轉圜的餘地都沒有。

樂天在岸邊看得又好氣又好笑，差點笑出聲來，又怕嚇著那孩子，硬是憋住了。這輩子他見過太多真正懂得掩飾的人，那些人城府深得讓人看不透心思，話裡藏話，笑裡藏刀，一句話能拐出好幾層意思，而眼前這個小孩，做了壞事卻笨拙到連痕跡都藏不住，反而讓他覺得說不出的輕鬆，好像回到了什麼都藏不住也不必藏的年紀。他把這一幕寫下來，小娃撐小艇，偷採白蓮回。不解藏蹤跡，浮萍一道開。

樂天晚年很少再寫諷喻詩去罵時政了，寫的多半是這種閒適小品。有人說他晚節不保、鋒芒盡失，可他大概是真的累了——見過太多算計人心的把戲，反而覺得一個藏不住秘密的孩子，比滿朝文武都更值得他多看幾眼，多笑一聲。`
  },

  // id=279 中唐 劉長卿 〈送靈澈〉rating=3
  // 詩眼：目送一個能乾脆轉身走進山裡的朋友，自己卻連去留都身不由己
  // 隱藏連接：劉長卿一生剛而犯上、兩遭貶謫，與僧人靈澈的雲遊自由恰成對照
  279: {
    title: "送靈澈",
    author: "劉長卿",
    summary: "他目送朋友的背影被青山一口吞掉，才發現自己這輩子求不到的自由，別人轉身就能走進去。",
    story: `跟你說我朋友長卿送朋友回山上那個傍晚，他站在原地看到人影完全消失才轉身走，一步都捨不得早走。

長卿這輩子過得不算順。他性格剛直，見不慣的事一定要說，眼裡揉不得沙子，得罪過不少人，一生兩次被誣陷下獄，兩次被貶官，史書上說他剛而犯上，受排擠了大半輩子，官運起起伏伏卻始終不肯圓滑一點。他跟幾個僧人交情很好，靈澈就是其中一個，兩人常常一起喝茶論詩，談的話題比官場上那些人有意思得多，靈澈修行的竹林寺在潤州附近的山裡，平日雲遊四方，講完經或者訪完友，總要回山裡去，行止來去毫不牽掛。

那天靈澈要回竹林寺，長卿送他到城外，兩人邊走邊聊，捨不得就此分別，話題從詩文聊到最近各自的處境，誰也沒先開口說再見。傍晚時分，遠處山上傳來寺廟的鐘聲，一聲一聲，很悠遠，像是催著靈澈該上路了，不能再耽擱，天黑之前總得趕回山門。靈澈背上斗笠，披著夕陽的餘光，跟長卿拱手作別，往青山的方向走去，一個人，誰都不用等，誰都不用交代，腳步輕快得像是要去赴一場約好的清閒，一點也不像要走一段孤單的長路。

長卿站在原地看著這個背影，沒有立刻轉身，連身邊隨從催他回城他都沒聽見。他自己這輩子做什麼事都身不由己，想說真話要挨罵，想做實事要看人臉色，連去哪裡當官都由不得自己，一貶再貶連辯解的機會都沒有，每次收拾行李都不知道下一站是哪裡。而眼前這個朋友，一句話不說，轉身就能走進山裡，再也不用管紅塵裡那些是非恩怨，不用揣摩誰的臉色，也不用擔心哪句話說錯了又要惹禍上身。他心裡有點羨慕，又有點說不出的滋味，看著靈澈的身影越走越小，慢慢被那片青山吞掉，連斗笠的輪廓都看不清了，直到山色和暮色連成一片，什麼都分不清了。

他把這個畫面寫成四句，蒼蒼竹林寺，杳杳鐘聲晚。荷笠帶斜陽，青山獨歸遠。

長卿後來還是繼續在官場浮沉，又被貶了一次，直到晚年才算安穩下來，做到隨州刺史。可是那個傍晚靈澈的背影，他大概記了很久——那是他這輩子少數幾次，親眼看著一個人乾乾脆脆地，把自己活成了他求不到的那種自由。`
  },

  // id=280 中唐 劉長卿 〈彈琴〉rating=3
  // 詩眼：彈一首沒人愛聽的老調子，明知沒有知音，還是要彈給自己聽
  // 隱藏連接：劉長卿自號五言長城，性格耿直守舊不肯迎合，與古調不受今人喜愛的處境互為映照
  280: {
    title: "彈琴",
    author: "劉長卿",
    summary: "滿長安都在聽胡樂新調，劉長卿卻在深夜彈一首沒人愛聽的古琴——彈給自己聽，也是彈給自己的性子聽。",
    story: `跟你說我朋友長卿一個人在家彈琴的一個晚上，彈的是一首沒什麼人愛聽的老調子，彈給空蕩蕩的屋子聽。

長卿自己給自己取過一個外號，叫五言長城，意思是他寫五言詩天下第一，城牆一樣攻不破，別人休想越過。這外號聽起來狂，可長卿這人確實有這個底氣，也確實這麼狂，向來不把同輩詩人放在眼裡。他性格耿直，眼裡揉不得沙子，看不慣的人事一定要講，講了就得罪人，一輩子兩次入獄兩次被貶，牢裡吃過苦，貶謫的路上也吃過苦，別人勸他收斂一點，見人說人話，見鬼說鬼話，他也沒真的改過，還是一副硬脾氣。

那天晚上他一個人在家，屋裡沒有旁人，連個端茶的僕人都打發走了，取出一張七絃琴，慢慢調好絃，一根一根試音，彈的是古調，一種早就過時、宮廷宴席上再也不流行的曲子。窗外松樹被風吹得沙沙作響，琴聲跟松風聲混在一起，聽起來清冷又乾淨，一個音一個音都很講究。他自己彈得很投入，彈到一半忽然想起，現在滿長安的人聽的都是胡樂新調，琵琶、羌笛，熱鬧又新鮮，酒樓裡夜夜笙歌，誰還耐煩坐下來聽這種老掉牙的古琴，慢悠悠一彈就是半個時辰。

他手上沒停，心裡卻在想自己這輩子——耿直、守舊、不肯迎合，寫詩是這樣，做人也是這樣，結果落得兩次下獄兩次貶謫，朋友一個個勸他變通一點，睜一隻眼閉一隻眼就過去了，他都聽不進去，還是照著自己認定的道理往前走。這首沒人愛彈的古調，跟他這個沒人愛用的性子，好像是同一件事，換了個樣子出現而已，都是老早就不合時宜，卻偏偏還在堅持的東西。

他彈完最後一段，指尖停在絃上，把心裡的話寫成四句，泠泠七絃上，靜聽松風寒。古調雖自愛，今人多不彈。

長卿晚年終於熬到一個穩定的官位，隨州刺史，人稱劉隨州。可他這輩子從沒真的學會迎合誰，見了上司也還是那副硬邦邦的脾氣。這首詩後來被人反覆引用，拿來說知音難覓，感嘆世風不古，可長卿當年彈琴那個晚上，大概心裡想的更簡單——就算沒人愛聽，這首調子，他還是要彈給自己聽，彈給窗外的松風聽，彈給那個不肯改變的自己聽。`
  },

  // id=281 中唐 劉長卿 〈送上人〉rating=3
  // 詩眼：想真正歸隱，卻連隱居的地方都要跟別人排隊撞名，名氣毀了清淨
  // 隱藏連接：沃洲山因東晉支遁隱居養鶴的典故而聞名，劉長卿化用支遁愛鶴的形象反過來勸僧人別去
  281: {
    title: "送上人",
    author: "劉長卿",
    summary: "劉長卿半開玩笑勸朋友別去熱門景點裝隱士——連地址都被人知道，那還算什麼歸隱。",
    story: `跟你說我朋友長卿送一個和尚朋友出門的時候，說了一句半開玩笑半認真的話，勸他別去人擠人的地方隱居，聽得對方一愣。

那位上人是長卿的方外之交，兩人平日常在寺裡對坐喝茶，一個談禪一個論詩，很合得來。上人決定要離開俗世，找一座山歸隱修行，收拾好簡單的行囊，臨走前跟長卿提起，想去沃洲山，就是浙江新昌那一帶，聽說風景清幽，正合隱居。長卿一聽就皺眉，倒不是嫌那山不好，是那山太有名了，名氣大得反而礙事。

沃洲山出名，是因為東晉的高僧支遁曾經在那裡隱居過。支遁這個人有意思，學問好，清談出眾，跟當時的名士都有往來，還特別愛養鶴。相傳有人送他一對鶴，他怕鶴飛走，把翅膀剪短了關著養，後來看鶴一副垂頭喪氣、不肯高飛的樣子，又覺得於心不忍，說鶴生來就該衝天，怎麼能因為我喜歡就折了牠的翅膀，乾脆把羽毛養回來，放牠們飛走。這個故事流傳了幾百年，沃洲山也跟著支遁一起出了名，後世但凡想歸隱的人，十個有八個都想去沃洲山朝聖，把那裡當成隱士的樣板間，路上絡繹不絕。

長卿覺得這就是問題所在。真正的隱士，應該像孤雲一樣飄著，像野鶴一樣自在，誰都找不到，誰都管不著，怎麼可以跟著人潮往一個地址明確、遊人絡繹不絕的名山跑呢。你去沃洲山隱居，跟你去鬧市擺攤有什麼兩樣，人人都知道你在那裡排隊修行，那還隱什麼，反倒成了另一種熱鬧。

他半是提醒半是打趣，拍拍上人的肩膀，跟這位上人說，孤雲將野鶴，豈向人間住。莫買沃洲山，時人已知處。

這首詩後來常被人拿來當作勸退的範本，凡是想附庸風雅、挑一個熱門景點裝隱士的人，都該讀讀這四句，讀完多半會臉紅。長卿自己這輩子沒能真正歸隱，一直在官場裡起起伏伏，說話直、脾氣硬，得罪的人比交到的朋友還多，可他心裡很清楚，什麼才是真正的自由——不是找一個有名的地方躲起來，讓人一提起那座山就想到你，而是連地址都沒人知道，連想去打擾都找不到門路，那才算真正脫身。這位上人聽完他的話，愣了半晌，最後還是笑著點頭，往別處去了。`
  },

  // id=283 中唐 李端 〈聽箏〉rating=3
  // 詩眼：一個女子故意彈錯，只為讓某個人抬頭看她一眼
  // 隱藏連接：云溪友議記載歌女鏡兒因傾慕李端而在郭曖宴上故意彈錯箏音，李端當場賦詩戳破她的心思，郭曖遂將鏡兒許給他
  283: {
    title: "聽箏",
    author: "李端",
    summary: "所有人都以為她彈箏彈得手生——其實她是故意的，就為了讓那個聽得懂音律的人多看她一眼。",
    story: `跟你說我朋友李端一次赴宴的事，說出去你可能不信，他這首人人都會背的〈聽箏〉，其實是被人半推半就，當著一整桌客人的面，臨場交出的一張考卷。

那天是郭曖家的酒宴。郭曖是駙馬，升平公主的丈夫，家裡富貴，最喜歡招攬文人清客，三天兩頭辦局。李端那時還沒什麼名氣，靠著這種場合混飯吃，也混機會。宴上照例有歌舞助興，一個叫鏡兒的歌女抱著箏坐在簾前彈奏。鏡兒眼睛一直往李端那邊瞟，彈得斷斷續續，好幾個音都彈岔了。旁人只當她手生，郭曖卻看出了名堂——這姑娘，是想讓某個人多看她幾眼。

郭曖起了興致，當場點名李端：你倒說說，這姑娘為什麼老是彈錯？能不能就此題一首詩？滿座賓客的眼睛全轉過來，連筷子都停在半空。這種場合，答得好是才名遠播，答得爛就是當眾出醜，李端連酒杯都沒放下，腦子已經在轉。他心裡清楚，這種即席題目最忌諱裝斯文繞圈子，一句話點不到位，接下來一整桌人都會覺得他名不副實。

他看著鏡兒的手——那雙手其實不笨，金粟柱一按一挑都是準的，只是每次快要碰到某個關鍵的音，她就故意慢半拍、故意錯半分，指尖一收又若無其事地繼續往下彈。這不是失誤，這是計算過的失誤。他想起三國時那個懂音律的周瑜，人稱周郎，據說樂師只要彈錯一個音，他坐在席間眉頭一動就聽出來了，連頭都不用抬。鏡兒要的不是彈對，是被看一眼，而她挑的辦法，偏偏是最不張揚也最聰明的一種——用錯音把人的注意力慢慢釣過來。

李端提筆，寫下四句：鳴箏金粟柱，素手玉房前，欲得周郎顧，時時誤拂絃。

滿座先是靜了一下，隨即笑聲炸開。郭曖拍案叫好，轉頭問鏡兒：他說中你心思了沒有？鏡兒滿臉紅著低頭不答，手指還按在絃上沒放，等於當眾認了。郭曖是個爽快人，看熱鬧看得高興，也不多囉唆，當場把鏡兒許給李端，成了他的妾。滿座賀聲一片，有人打趣說，這箏是白彈了，倒是彈出了一段姻緣。

一場酒宴，一個沒把握的即興命題，一個女子藏在錯音裡的心事，被一句詩全部拆穿，還順手成全了一段緣分。李端後來偶爾跟人提起這件事，總帶著幾分得意，又有點不好意思，說自己那天其實心裡也在打鼓，萬一猜錯了怎麼辦。後來的人讀這首詩，只當是寫彈箏姑娘的小心機，卻沒幾個人知道，那個姑娘後來真的跟這位替她說出心事的詩人在一起了。這大概是所有閨怨詩裡，少有的一個好結局。`
  },

  // id=286 中唐 元稹 〈行宮〉rating=3
  // 詩眼：曾經的盛世，如今只是幾個老婦人閒坐時的話題
  // 隱藏連接：元稹與白居易同科進士、交情深厚，同期共同關注被遺忘在深宮裡的老宮女議題（白居易同期寫有上陽白髮人）
  286: {
    title: "行宮",
    author: "元稹",
    summary: "花照樣年年開得鮮紅，卻沒人看——一整個盛世的繁華，最後全部縮成幾個老太太閒坐時隨口提的話題。",
    story: `跟你說我朋友元稹有一次出差，順道看見了一整個王朝由盛轉衰的縮影，就窩在幾個老太太的閒話裡。

那是他任監察御史前後，奉命出使洛陽一帶，途中經過一座早已冷清的行宮。這種行宮唐朝到處都有，是玄宗那個排場浩大的年代，皇帝出巡時沿途歇腳用的別院，當年修得雕梁畫棟，養著成群的宮女隨扈伺候，出巡的儀仗一到，鑼鼓喧天，方圓幾里的人都要跟著忙上好幾天。可安史之亂一過，玄宗死了，肅宗、代宗換了幾輪，誰還顧得上這些遠郊的行宮。宮牆爬滿了藤，屋瓦有的已經塌了一角，院子裡的花照樣年年開，卻沒人賞，紅得一片寂寞，風一吹，落了滿地也沒人來掃。

元稹進了院子，本來只想找個地方喘口氣，卻撞見幾個白髮蒼蒼的老宮女。她們大概是天寶年間就被選進宮、伺候慣了行宮這一帶，幾十年下來，青春耗光了，人也被朝廷遺忘了，乾脆就地住著，養老等死。這些人他的朋友白居易後來也寫過，叫她們上陽白髮人——被選進宮卻沒被皇帝看上一眼，一鎖就是一輩子，連放出宮都沒人記得辦手續。元稹和白居易同一年考上進士，交情極深，兩人常常互相寄詩討論該寫些什麼樣的題材，替這些沒人替她們說話的人講講話，正是他們那陣子最在意的事。

元稹站在廊下，沒有出聲打斷，只是聽著那幾個老婦人閒坐著說話，語氣輕鬆，像在講家常，偶爾還笑出聲。仔細一聽，她們說的居然是玄宗——當年皇帝穿什麼、寵誰、去哪裡巡遊，一件一件，說得又熟悉又鬆散，彷彿那是她們這輩子唯一值得反覆咀嚼的存貨。有個老婦人說起玄宗某次獵鹿時的興頭，另一個立刻接話糾正細節，兩人像是為了一件早已無關緊要的往事爭論了幾句，笑一笑又算了。

元稹提筆寫下：寥落古行宮，宮花寂寞紅，白頭宮女在，閒坐說玄宗。

二十個字，沒有一句控訴，沒有一滴眼淚，卻比任何哭訴都更讓人心裡發沉——一整個開元天寶的盛世，連同那些消耗在深宮裡的青春，最後全部縮成幾個老太太閒坐時隨口一提的話題。花還在紅，人卻早就老了，連恨都懶得恨了，說起從前的事，語氣比說今天的天氣還要平淡。元稹站在那裡看了很久，直到隨從催他該上路了才轉身離開，那幾個老宮女還在原地閒坐，好像時間在這座行宮裡早就停了。元稹把這首詩收好，後來的人讀到這二十個字，才知道盛世散場後，最先被遺忘的，永遠是這些連名字都沒能留下的人。`
  },

  // id=294 中唐 李益 〈江南曲〉rating=3
  // 詩眼：自然的潮汐比丈夫的承諾更可信
  // 隱藏連接：李益長年往來邊塞、遊歷南北，可能在瞿塘峽一帶親耳聽聞商婦怨言，並非寫自身婚姻，屬代言體
  294: {
    title: "江南曲",
    author: "李益",
    summary: "她苦笑著望向江面：早知道潮水這麼守信用，倒不如嫁給天天跟潮水打交道的人。",
    story: `跟你說我朋友李益一次在江邊聽來的怨言，他沒去問那個女人的名字，只把她這輩子最想罵的一句話，原封不動地寫成了詩。

李益走南闖北慣了，年輕時當過幾年邊塞的官，後來又四處遊歷，瞿塘峽這種長江上最險的一段峽口，他不知道經過幾次。瞿塘峽兩岸絕壁夾江，水流又急又猛，礁石密布，商船進出全看水勢和風向，稍有耽誤就得在峽口等上好幾天，行程說不準是常態——早一天晚一天，商人自己都說不清楚，更別提在家等的人。

他這次停船靠岸，天色將晚，就在江邊一戶人家借宿，聽附近的婦人閒聊，說起自己嫁的丈夫是跑瞿塘峽生意的商賈。這個女人年紀不大，手裡還縫著什麼，講起丈夫，語氣不是甜，是疲。她說剛嫁過去那幾年，還會扳著手指算丈夫回來的日子，天天到江邊張望。可每次約好的日子，他總是誤，一次兩次還安慰自己是水急耽誤，可十次八次下來，她算是看透了——商人重的是貨、是利，妻子的等待從來排不到前面。她約好的每一個日子，幾乎沒一次準，後來她乾脆不算了，反正算了也白算。

女人說著說著，忽然抬頭看江面。潮水這種東西倒是死心眼，幾點來、幾點退，漲跌年年不差，連漁民都能靠著它排班捕魚。她苦笑一聲：早知道潮水這麼守信用，我當初何必嫁給做生意的，嫁給那些天天弄潮、跟潮水打交道的人算了——至少潮水從不騙人。

李益把這句話聽進心裡，那晚回到船上，借著燈光提筆寫成：嫁得瞿塘賈，朝朝誤妾期，早知潮有信，嫁與弄潮兒。

這四句話裡沒有一個字寫委屈，卻把委屈寫到了骨子裡——她要的從來不是弄潮兒的本事，是一個說話算話的人。李益走遍邊塞看慣了將士的家書和寡婦的哭聲，這回在江邊聽到的，不是生離死別，只是一個女人日復一日的失望，反而更讓人心酸。他把詩念給船上的同行聽，有人笑說這話說得太狠，商人聽了要不高興的。李益倒不覺得，他說這不是說給商人聽的，是替那個女人把心裡話補上一句。這首詩後來被收進江南民歌的調子裡傳唱，沒人知道那個女人是誰，但每個等過人的女人，大概都懂她在說什麼。`
  },

  // id=296 晚唐 張祜 〈何滿子〉rating=3
  // 詩眼：一首歌曲，竟成了自己命運的預言
  // 隱藏連接：據本事詩記載，唐武宗妃孟才人病危時唱何滿子曲氣絕而亡，與此詩雙淚落君前的意境重合，成為後世傳誦的巧合
  296: {
    title: "何滿子",
    author: "張祜",
    summary: "他寫一個深宮女子聽曲落淚——沒想到多年後，另一個真實的女子，連死法都跟這首詩對上了。",
    story: `跟你說我朋友張祜寫過一首詩，詩裡那句話後來竟然一字不差地，應驗在另一個人的真實死亡上。

何滿子本來是個曲調的名字。相傳這曲子最早是唐朝一個名叫何滿子的歌人，臨刑前所唱，聲音悲切到旁邊監斬的人都聽得心裡發顫，聽的人沒有不落淚的，後來這名字就變成了曲調的代稱，宮裡教坊常拿來演唱，成了一種帶著哀音的固定曲牌。張祜這輩子沒在朝中做過什麼大官，考過功名也不順，一輩子在江湖上漂，靠著幾首好詩交朋友過日子，但他對宮廷裡的悲情故事特別敏感，尤其是那些被關在深宮裡、耗掉一生青春的宮女，這類題材他寫過不止一首。

他寫這首詩的時候，想的是一個具體的畫面：一個宮女，家鄉遠在三千里外，進宮那年還是個少女，梳著雙鬟，臉上還帶著鄉音沒改的口氣，如今已經在深宮裡待了二十年。二十年裡她見不到故鄉的山，見不到年少時的親人，宮裡的規矩一年一年磨掉她的脾氣，唯一還記得的，可能只剩幾句家鄉話和一張越來越模糊的臉。某天教坊裡起了樂聲，唱的正是何滿子那個曲子，悲涼的調子一下就鑽進她心裡，繞過她這些年學會的隱忍，她再也忍不住，在皇帝面前掉下眼淚，不敢哭出聲，只任眼淚一滴一滴落下來，怕被人看出失態。

張祜把這個畫面寫成四句：故國三千里，深宮二十年，一聲何滿子，雙淚落君前。二十個字，沒有一句抱怨朝廷，卻把宮女被困一生的委屈全交代清楚了。

這首詩流傳開後，發生了一件誰也沒料到的事。據記載，唐武宗晚年病重，臥床許久，宮裡氣氛沉悶，他寵愛的孟才人為了博他一笑，親自唱了一曲何滿子。武宗聽完，忽然問她，朕死後你打算怎麼辦？孟才人愣了一下，指著身邊的一條錠子答不出話，只是又唱了一遍那支曲子，唱到後半段聲音越來越顫，唱完氣就斷了，當場死在武宗面前，滿殿的人都嚇傻了。旁人事後想起張祜這首詩，那句雙淚落君前，竟像是提前替孟才人寫好的結局。

張祜寫的時候大概沒想過，自己筆下那個沒有名字的深宮女子，後來會被另一個真實的女子活生生演了一遍，連死法都對上了那一聲何滿子。`
  },

  // id=301 清 袁枚 〈所見〉rating=3
  // 詩眼：一個小孩從放聲高歌到瞬間噤聲屏息的心思轉變
  // 隱藏連接：無
  301: {
    title: "所見",
    author: "袁枚",
    summary: "前一秒歌聲震林，後一秒閉口站定——中間沒有任何過渡，這才是袁枚真正在意的詩。",
    story: `跟你說我朋友袁枚晚年最喜歡幹的一件事，就是什麼正事都不幹，在隨園附近瞎晃，專門看小孩子出洋相。

袁枚年輕時考中進士，做過幾年地方官，官聲不錯，可他四十出頭就辭官不做了，在南京買下一座荒廢的園子，取名隨園，重新修整了一番，一住就是四十幾年。他這輩子最看不上那種端著架子、非要寫大道理的詩，見過太多人把詩寫得像公文，句句都在教訓人，他覺得詩應該是活的，眼睛看見什麼、心裡動了什麼，寫下來就是好詩，用不著硬塞什麼教訓，這種主張他跟晚輩、跟慕名來訪的年輕人講過不知多少次。

這天他在隨園附近的鄉間閒走，也沒特別的目的，就是走走看看。遠遠看見一個牧童騎在一頭黃牛背上，大概是替家裡放牛，一個人也沒個伴，乾脆扯開喉嚨唱起歌來，調子隨性得很，想怎麼拖長音就怎麼拖。那嗓子毫不含蓄，山林裡的樹都被震得跟著晃，整片林子好像都在替他打節奏。袁枚站得老遠都聽得清清楚楚，忍不住笑，這孩子唱得比戲台上正經學過的還帶勁，一點不怕人聽見。

正看得有意思，牧童忽然不唱了。歌聲斷得又急又乾淨，連個尾音都沒留。袁枚一時沒反應過來，再一看才明白——牛背上的孩子整個人僵住，眼睛直直盯著路邊一棵樹，嘴巴閉得死死的，連呼吸都放輕了。原來他看見樹上停著一隻鳴蟬，那念頭比什麼都快，唱歌唱得再開心，也比不上抓一隻蟬的誘惑，他怕蟬聽見動靜飛走，連自己的歌聲都成了敵人，說停就停。

袁枚站在那裡看這一整齣，前一秒的張揚和後一秒的凝止，中間沒有任何過渡，乾淨得像被剪刀剪過。他把這個瞬間原封不動記下來：牧童騎黃牛，歌聲振林樾，意欲捕鳴蟬，忽然閉口立。

沒有一句說教，沒有一個道理，袁枚只是老老實實把他看到的東西寫下來，連自己看了忍不住笑的心情都沒多加渲染。這大概就是他一輩子追求的那種詩——不必說什麼，一個孩子閉嘴站定的模樣，比任何道理都讓人記得住。他收起紙筆繼續往前走，山林恢復了安靜，那個牧童還僵在牛背上，眼睛一眨也不眨地盯著那隻蟬，一隻手悄悄從牛背上探下去，也不知道結果到底捉住了沒有，袁枚也沒回頭多看，笑著自己往隨園的方向走了。`
  },

  // id=306 盛唐 李白 〈清平調三首之二〉rating=3
  // 詩眼：一句誇美的詩，被別人聽出了殺機
  // 隱藏連接：高力士曲解可憐飛燕倚新妝一句，暗指楊貴妃行止不端，向貴妃進讒言，種下李白被排擠出長安的禍根，見於松窗雜錄記載
  306: {
    title: "清平調三首之二",
    author: "李白",
    summary: "他喝醉了酒，寫下一句誇獎，卻不知道自己親手替日後的失勢，簽了第一張字條。",
    story: `跟你說我朋友太白這輩子最風光的一個下午，後來被證實，也是他倒霉的開始。

那年他剛被玄宗召進長安，封了個供奉翰林，說白了就是皇帝身邊專門寫應景詩文的文人，風頭正盛，長安城裡誰都知道皇帝身邊多了個愛喝酒的才子。這天興慶宮裡的沉香亭牡丹開得極好，一片一片開得像燒起來似的，玄宗帶著楊貴妃去賞花，一時興起，覺得光看花不夠，要有新曲新詞配著唱，派人急召太白進宮，現場命題。太白那天恰好在外面跟人喝得有點醉，被人半扶半架進宮，路上腳步還有點不穩，一進殿看見滿園牡丹和皇帝貴妃的笑臉，酒還沒醒，筆一提，連寫三首，一氣呵成，這就是清平調三首。

第二首他寫的是眼前這位貴妃的美——牡丹紅豔得像凝著露水的香，美得讓他想起傳說中巫山神女與楚王雲雨一夢的舊典，可眼前這位比神女還真實，不必去夢裡找。他又想，這樣的美，漢宮裡誰能比得上，想來想去，大概也只有那位曾經以美貌動搖朝局的趙飛燕，穿著新做的衣裳，才勉強能比一比。

他寫下：一枝紅豔露凝香，雲雨巫山枉斷腸，借問漢宮誰得似，可憐飛燕倚新妝。

這幾句在酒宴上被李龜年配著新曲當場唱出來，玄宗聽得眉開眼笑，楊貴妃也高興，滿座都覺得這是天大的體面。太白自己也沒多想，不過是即席應景，把眼前的美人捧到極致，誰會拿這種場合的詩去挑毛病。

可站在一旁的高力士心裡卻轉了別的念頭。趙飛燕這個名字不乾淨，史書上她跟人有私情，最後還牽連進宮闈醜聞裡，甚至跟姊姊一起被廢為庶人，太白拿她比楊貴妃，聽的人往深了想，就是在暗指貴妃行止不端。高力士當時沒說什麼，只是把這句話悄悄記在心上，尋了個機會，把這層意思添油加醋說給貴妃聽。貴妃聽完臉色沉了下來，從此對太白心存芥蒂，幾次在玄宗面前不點名地說些閒話，話裡話外都在使絆子。太白這輩子最耀眼的一個午後，寫的是最誠心的讚美，種下的卻是最終被逐出長安的一顆種子。他自己直到很久以後，被排擠出宮、四處漂泊時，才慢慢想明白，原來誇人這種事，有時候比罵人還危險，尤其是誇得太具體、太用心的那種。`
  },

  // id=307 盛唐 李白 〈清平調三首之三〉rating=3
  // 詩眼：盛世最美好的瞬間，後來變成離散年代裡讓所有人一起流淚的歌
  // 隱藏連接：據明皇雜錄記載，安史之亂後李龜年流落江南，在宴席上再唱這首曲子，滿座賓客聽而落淚
  307: {
    title: "清平調三首之三",
    author: "李白",
    summary: "十幾年後長安淪陷，那個唱這首歌的人流落江南，再唱一次，滿座的人全哭了。",
    story: `跟你說我朋友太白那個沉香亭的午後還沒完，故事後半段主角換成了唱他詞的那個人——李龜年。

太白那天一連寫了三首清平調，前兩首誇的是眼前的牡丹與貴妃，第三首他把鏡頭拉遠一點，寫整個場面——名花也好、傾國的美人也好，這一天兩樣都齊聚在沉香亭，玄宗看在眼裡笑意止不住，連春風裡多少陳年舊怨，好像都被這一刻的美好解釋開了。他寫下：名花傾國兩相歡，常得君王帶笑看，解釋春風無限恨，沈香亭北倚闌干。

寫完之後，詩交給當時最紅的樂師李龜年，配上新譜的曲子，當場唱給玄宗和貴妃聽。李龜年那時候是整個長安最搶手的歌手，皇帝的宴會沒有他幾乎辦不成，達官貴人請他唱一曲都要排隊。這天他唱得格外用心，亭子裡笛聲、箏聲、他的嗓音混在一起，連闌干邊的花香都好像被歌聲托得更濃。玄宗聽得高興，自己也拿起玉笛跟著和了幾句，貴妃在旁邊持著犀角杯，笑得眉眼彎彎。這是開元天寶最好的年代，好到讓人以為它會一直這樣下去，好到滿座的人都沒去想過有一天會結束。

可誰都沒想到，十幾年後安史之亂爆發，長安淪陷，玄宗倉皇逃往四川，楊貴妃死在馬嵬坡，曾經最風光的一群人，一夕之間全部四散。李龜年也跟著逃難，一路輾轉流落到江南，再沒有沉香亭，也沒有絲竹管弦的排場，他靠著僅剩的一點手藝，在江南街頭巷尾勉強維生。

據記載，有一次江南的宴席上，有人認出他是當年長安的名角，請他再唱一曲舊曲，他想了想，張口唱的，正是當年那首名花傾國兩相歡。滿座賓客本來還在喧鬧，聽著這幾句熟悉的詞，一下子全靜了下來，接著一個個掩面哭了出來——他們聽見的不是牡丹和美人，是再也回不去的那個年代，是自己家破人亡的這幾年。李龜年自己唱到一半，嗓子也哽住，眼淚跟著掉下來，唱不下去，半晌才把剩下的幾句斷斷續續唱完。

太白寫這首詩的時候，只想著眼前這一刻的圓滿。他沒想到，這幾句誇讚盛世的詩，後來會變成一整個時代崩塌後，讓倖存的人一起哭出來的歌。沈香亭北那道闌干，早就沒了，但那個午後的歌聲，竟然比亭子本身活得更久。`
  },

  // id=309 盛唐 李白 〈望天門山〉rating=3
  // 詩眼：第一次離開故鄉，看見世界比想像中更遼闊的興奮
  // 隱藏連接：無
  309: {
    title: "望天門山",
    author: "李白",
    summary: "他這輩子第一次離開四川，站在船頭看兩岸青山迎面而來，才明白世界比自己以為的大得多。",
    story: `跟你說我朋友太白二十五歲那年第一次做的一件事，後半輩子的漂泊，幾乎都是從那一趟開始的。

太白在四川長大，青城山、峨眉月，他從小看慣了蜀地的山，那種山是關起來的，四面都是牆一樣的高峰，把人困在裡頭，抬頭望去天空永遠只有一小塊。二十五歲那年，他終於下定決心離開四川，收拾行裝，順著長江往東走，說是要去看看外面的世界，其實心裡也帶著一點闖蕩功名的念頭，想著在外頭闖出名聲，總比困在蜀地強。這一走，他這輩子再也沒能回過四川。

船一路往下，過三峽，兩岸的絕壁一段比一段驚險，水勢一段比一段開闊，他的心情也跟著鬆開，像是連日子都跟著江水加快了速度。這天船行到天門山附近——長江邊上東西兩座山夾岸對峙，像是天生的一道門，江水從中間硬生生擠過去，水流又急又猛，船身都跟著顛了幾下，轉了個彎繼續往東奔。這種景象他在四川從沒見過，四川的山是把人圍住的，眼前這座天門山卻像是被江水硬生生劈開，不但沒攔住江水，還被沖出一個豁口讓它過去，江水贏了這一局。

他站在船頭，看兩岸青山迎著船頭一座座迎面而來，又一座座退到身後，好像整個世界都在朝他打開，又在他身後緩緩合上。江面上就他這一片孤帆，遠遠地，像是正從太陽升起的地方駛過來，又要載著他往更遠的地方去。那一刻他忽然覺得，自己這輩子第一次真正明白，世界比他以為的大得多。

他提筆寫下：天門中斷楚江開，碧水東流至此迴，兩岸青山相對出，孤帆一片日邊來。

二十八個字裡沒有一句提到害怕或不捨，只有滿滿的興奮和一種被打開的痛快，連水花打上船板的聲音都覺得帶勁。他當時不知道，這一路東去，他會遊遍大江南北，會在長安風光過，也會落魄過，中間還有過幾年被人排擠、四處投靠朋友的日子，晚年還會客死他鄉，再也沒機會回頭看一眼峨眉的月。但那個二十五歲的下午，他只顧著站在船頭，任江風吹亂衣袖，看青山一座座向他迎過來，覺得整個天地都在替他敞開大門，那種興奮，他往後幾十年碰過再多風浪，都沒有真正忘掉過。`
  },

  // id=315 盛唐 杜甫 〈贈李白〉rating=3
  // 詩眼：兩個都還沒混出頭的人，彼此心疼對方虛度的光陰
  // 隱藏連接：杜甫與李白744年於齊魯一帶同遊，曾一同前往王屋山尋訪道士華蓋君卻聽聞道士已死，此為兩人交往記載中的真實軼事
  315: {
    title: "贈李白",
    author: "杜甫",
    summary: "一個剛被朝廷冷落，一個功名還沒個影子——兩個都在飄的人，那年秋天看懂了對方。",
    story: `跟你說我朋友子美這輩子跟太白真正混在一起的日子，前前後後也就一年多，這首詩就是那段日子留下的一張隨手速寫。

那是天寶三載前後，太白剛從長安被玄宗客氣地送走——說好聽是賜金放還，賞了一筆錢體面地打發走，其實就是宮裡待不下去了，遭人排擠。他心裡不痛快，乾脆一頭扎進求仙訪道的世界，四處雲遊，想著人間混不下去，不如去山裡找點別的門道。子美那時候還是個沒考上功名的年輕人，正打算漫遊齊趙，兩人在齊魯一帶碰上，一見面就聊得投機，年紀差了一輪，卻一點不見外，索性結伴同遊，一起去王屋山找一位傳說中的道士華蓋君，想跟他學點修道煉丹的門道。兩人風塵僕僕趕了幾天路上山，才聽當地人說，那位道士早已經死了好幾年。這一趟白跑，兩人站在空蕩蕩的道觀前相對苦笑，倒也沒覺得多可惜——本來也沒真的多信這套，不過是想找個由頭一起走走。

那段時間他們幾乎天天在一起，喝酒，論詩，聊各自的不得志。太白比子美大十一歲，那時候名氣已經很響，可實際的處境跟子美差不了多少——兩個人都還在外頭飄著，一個功名沒有，一個剛被朝廷冷落，秋風一起，兩人都覺得自己像斷了根的蓬草，隨風滾，不知道要滾到哪裡去。

子美看太白，又佩服又心疼。太白整天嘴上說著要煉丹成仙，學那個修仙有成的葛洪，可鍊丹這事一年拖一年，連個影子都沒見著，倒是喝酒喝得越來越猖狂，寫詩寫得越來越放肆，成天痛飲高歌把日子混過去。子美想問他，你這麼張揚，這麼不管不顧地活著，到底是想證明給誰看？

他把這份又佩服又心疼的心情寫進詩裡：秋來相顧尚飄蓬，未就丹砂愧葛洪，痛飲狂歌空度日，飛揚跋扈為誰雄。

這首詩後來成了兩人交情最直白的證據——杜甫寫給李白的詩不多，肯這樣不留情面又滿是關切地問一句你到底圖什麼的，更是獨一份。他們此後各自流落天涯，再見的機會越來越少，子美自己後來也困在戰亂與貧病裡掙扎大半生，但那一年秋天，兩個都還沒混出名堂的人，曾經那樣互相看懂過對方，這件事他記了一輩子。`
  },

  // id=322 盛唐 王昌齡 〈閨怨〉rating=3
  // 詩眼：曾經以為光榮的追求，一瞬間才懂代價，從不知愁到悔的醍悟
  // 隱藏連接：王昌齡長年出入邊塞、深知從軍家庭處境，此詩是代言體想像之作，並非寫自身婚姻，非實錄
  322: {
    title: "閨怨",
    author: "王昌齡",
    summary: "前二十個字寫她渾然不覺，最後八個字翻了一個底朝天的跟頭——她終於懂了那句鼓勵的代價。",
    story: `跟你說我朋友少伯寫過一個女人，一輩子沒出現在史書裡，但她那一瞬間的後悔，比很多真實記載的故事還讓人記得住。

少伯這輩子去過邊塞，也在邊塞當過差，寫邊塞詩是他的招牌，黃沙、大漠、金甲、羌笛，他寫得比誰都熟。可這回他寫的不是戰場，是戰場另一端，一個留在家裡的女人。

這個女人年輕，家境不差，從小嬌養慣了，嫁的丈夫多半也是奔著邊塞軍功去的——那個年代，從軍立功封侯，是很多人家眼裡最體面的一條出路，比在家守著幾畝田強得多。丈夫走的時候，她心裡多少是有點驕傲的，甚至還催過他，說機會難得，你該去，將來封了侯，咱們家也風光，鄰居見了都要客客氣氣叫一聲夫人。她那時候是真心這麼想的，不知愁，不覺得離別有什麼大不了，覺得日子照樣過，梳妝照樣講究，等丈夫立功回來，這一切苦都會換成體面。

這天春光正好，她按著平常的心情，細細打扮了一番，對著銅鏡描了眉，抹了粉，又換上一套壓在箱底許久沒穿的衣裳，穿戴齊整，像往常一樣走上自家的翠樓，想登高看看這年的春色，順便讓自己心情好一點。她一路走一路想的，大概還是些尋常瑣事，家裡今天該辦什麼事、鄰居昨天說了什麼閒話，直到目光不經意落在街邊那一排楊柳上，才忽然頓住了腳步。

那些柳條抽了新綠，風一吹輕輕晃，還是去年送別時的那個模樣，連枝條垂下來的弧度都好像沒變過。少伯沒有寫她哭，也沒有寫她喊，只寫她忽見——就是那一眼，不知道為什麼，所有壓在心底沒細想過的東西全部湧上來：丈夫走了幾年，家裡冷了幾年，她自己一個人熬了幾年，白天要撐著臉面過日子，夜裡卻常常翻來覆去睡不著，而那個當初她催他去追的封侯，到現在連個影子都沒有，甚至連一封確切的家書都等不到。

她站在樓上，忽然就後悔了。少伯把這個瞬間寫成：閨中少婦不知愁，春日凝妝上翠樓，忽見陌頭楊柳色，悔教夫婿覓封侯。

短短二十八個字，前面二十個字鋪的全是渾然不覺，最後八個字翻了一個底朝天的跟頭。少伯常年出入邊塞，見過太多這樣的家庭——出征的人圖的是功名，家裡的人熬的卻是一整段人生，直到某個尋常的春日，某一排不相干的柳樹，才讓人看清楚自己當初到底鼓勵了什麼，而這個代價，從來沒人事先告訴過她。`
  },

  // id=324 盛唐 王昌齡 〈春宮曲〉rating=3
  // 詩眼：站在簾外的人凍著肩膀，冷暖只看那扇窗有沒有轉向你這邊
  // 隱藏連接：王昌齡自己仕途屢次外放、眼看別人被拔擢的心境投射進這首宮怨詩
  324: {
    title: "春宮曲",
    author: "王昌齡",
    summary: "他沒進過那道宮門，卻把宮裡點名承寵的邏輯，寫得跟自己屢次被外放的官運一模一樣。",
    story: `跟你說我朋友少伯這輩子寫過太多宮裡的女人，可是他自己一步都沒進去過那道門。

這種宮怨詩，長安城裡的詩人常寫，靠的不是親眼所見，是靠一整條消息鏈——宮裡的內侍、教坊的樂工，跟外頭相熟的官員、詩人喝酒閒聊時，會順口帶出一兩句宮牆裡的動靜。少伯交遊廣，這類消息聽得比誰都多，聽多了，他心裡自然拼出了一整套宮裡的規則。

他寫得最狠的一首，是那年聽人轉述的一個晚上。長安城裡有人偷偷傳：昨夜宮裡起了風，把御花園那口井邊的桃花吹開了。未央宮前殿，月亮升得特別高，好像特意要照亮某一場戲。

戲的主角是平陽公主府裡出來的一個歌舞伎。這個典故少伯用得刁——當年漢武帝的姐姐平陽公主府裡養著一批歌女，其中一個叫衛子夫，被公主特意安排在武帝面前跳了一支舞，武帝當夜就把人留下了，後來一路做到皇后。少伯借這個舊故事，寫的其實是眼前正在發生的一模一樣的事：某個原本沒名分的女子，一夜之間就被點名。

有意思的是簾外那句。宮裡消息傳出來，那晚春寒還沒退，簾子外頭的人凍得縮著肩膀，簾子裡頭那個剛承寵的，卻已經被賜下一件錦袍，暖得很。同一道簾子，隔出了兩種天氣，一邊的人連姓名都沒人記得，一邊的人一夜之間連衣裳都換了規格。

少伯自己也常年在等一道簾子轉向他。他考上進士、也有詩名，滿長安都知道「詩家夫子王江寧」這個名號，可官運偏偏不順，一次次被外放到偏遠的地方，龍標、江寧，離京城越來越遠。他常跟朋友說，自己這輩子好像也一直站在某道簾子外頭，寫得再好，也未必等得到那件錦袍。他心裡明白，朝廷點名這件事，跟宮裡點名一個舞伎，說到底是一樣的邏輯——不是你不夠好，是那晚的風有沒有恰好吹到你這邊。

他把這件事寫成四句，沒有一個字罵人，也沒有一個字喊冤，只是把畫面擺出來：

昨夜風開露井桃，未央前殿月輪高。平陽歌舞新承寵，簾外春寒賜錦袍。

寫完他把紙收好，沒有拿去給誰看。他知道長安城裡多少人，此刻也正站在自己的那道簾子外面，凍著肩膀，等一場誰都說不準的風。

多年後有人讀到這首詩，只當是一首宮怨小品。可少伯知道，那件錦袍穿在誰身上，跟他那些年被調來調去的公文，其實是同一張紙寫出來的兩種結果。`
  },

  // id=326 盛唐 王昌齡 〈採蓮曲〉rating=3
  // 詩眼：人可以躲進風景裡，聲音卻藏不進去
  // 隱藏連接：無
  326: {
    title: "採蓮曲",
    author: "王昌齡",
    summary: "採蓮女把自己藏進滿塘荷葉裡，卻藏不住那一嗓子歌聲——藏得再徹底，聲音還是洩了底。",
    story: `跟你說我朋友少伯有一年在江寧一帶當差，途中經過一片荷塘，看到一件事，他記了很多年。

那是夏天，日頭正烈，蟬叫得聒噪，塘裡的荷葉卻長得又密又高，遮出一整片陰涼。幾個採蓮的女孩子划著小舟鑽進荷葉深處，笑聲斷斷續續傳出來，一會兒又沒了聲音。少伯站在塘邊的小路上，一時竟找不到人——荷葉是綠的，女孩子們的羅裙也是同一種綠，剪裁得幾乎像從同一塊布上裁下來的。他往荷花深處多看了兩眼，才發現芙蓉花瓣兩邊開著，湊近了看，分明有一張臉正夾在花瓣中間，跟花長在一起似的，連眉眼都快分不清是人是花。

他心裡覺得好笑，又覺得有點佩服。這些女孩子大概是採蓮採久了，練出一種本事：知道什麼時候該低頭把自己藏進葉子堆裡，尤其是塘邊有生人經過的時候。少伯猜，她們大概也怕被岸上的閒漢盯著看，藏起來是最省事的辦法——不用躲進屋裡，一片荷葉就夠了。

少伯繼續往前走，以為那片荷塘裡什麼人都沒有了。他甚至懷疑自己是不是看錯，剛才那張臉會不會只是花瓣的錯覺，正打算搖搖頭把這件事丟開。

正走著，塘的深處忽然傳出一句歌聲，斷斷續續，像是划船的人隨口哼的調子，又像是講給同伴聽的閒話，一句接一句，還帶著點得意的笑腔，唱到一半又被同伴的笑聲蓋過去。少伯這才恍然：原來人根本沒走，一直都在那片荷葉深處待著，只是藏得太徹底，連他這樣站在岸邊留意、想找也找不到人的旁觀者都看不出來。

他把這一路的訝異寫成四句，沒有解釋，也不需要解釋：

荷葉羅裙一色裁，芙蓉向臉兩邊開。亂入池中看不見，聞歌始覺有人來。

少伯這輩子寫過不少邊塞的殺伐之氣，寫過宮牆裡的幽怨，但這一次難得寫了個輕鬆的下午。他後來跟人提起這件事，總說那些女孩子藏得再好，還是藏不住嗓子——人可以躲進風景裡，聲音卻藏不進去。這句話他自己聽著，竟覺得有點像在說自己：官場上他也一直想把自己藏起來遠離是非，可名氣這種東西，跟歌聲一樣，怎麼藏都藏不住，總有一天會從什麼地方洩出去，讓人一聽就知道是他。`
  },

  // id=336 中唐 白居易 〈浪淘沙-白浪茫茫與海連〉rating=3
  // 詩眼：親眼看見海真的在變成田，才明白沒有什麼是理所當然要恆久不變的
  // 隱藏連接：白居易任杭州刺史修築堤防、治理錢塘潮患的親身經歷，給了他直接目睹沙洲消長的第一手畫面
  336: {
    title: "浪淘沙-白浪茫茫與海連",
    author: "白居易",
    summary: "白居易在杭州修堤時親眼看見沙洲一年被沖沒、又淤出新的一片，才明白滄海桑田不是誇張的傳說。",
    story: `跟你說我朋友樂天在杭州當刺史那幾年，幹過一件跟寫詩完全無關的正經事——修堤。

錢塘江的潮水一年比一年凶，西湖跟附近的農田常常被淹，好幾個縣的百姓一到秋天就提心弔膽。樂天上任沒多久就帶著人去看堤防、看水勢，親自站在江邊的沙洲上，看潮水一趟一趟往岸上衝。隨行的小吏跟他說，這片沙洲三年前還能種菜，如今全沒了。樂天沒答話，只是站著看。他發現一件事：去年還在這裡的一片沙洲，今年已經沒了，潮水把它整片捲進海裡；而幾里外原本是淺灘的地方，今年反倒淤出一片新沙，已經有人牽牛去那邊試著犁地。

他站在江邊，看白浪一路翻滾過來，跟遠處的海連成一片，分不出哪裡是江、哪裡是海。往另一邊看，沙灘鋪得又平又遠，一眼望不到邊。潮水從早退到晚，晚上又漲回來，日日夜夜沖刷，沒有一刻停過，像是誰在底下不知疲倦地搬東西。

樂天想起小時候聽過的一個老說法：滄海會變成桑田。傳說裡那個叫麻姑的仙女活了很久很久，親眼見過東海三次變成陸地。以前他只當這是講給小孩子聽的神仙故事，現在自己站在潮水邊，親眼看沙洲一年就能沖沒、又淤出新的一片，他忽然覺得那個老說法一點都不誇張——只是仙女等的是幾百年，他等的是幾個潮汐。

他這輩子也算看過不少變化了。年輕時跟元稹一起意氣風發要改革朝政，滿心以為能改變什麼，後來被貶到江州，好友一個個散在天涯，回長安之後朝局又換了一輪人馬，昔日熟識的臉孔幾乎認不全。他當年覺得回不了頭的事，後來竟也一件件過去了，新的局面照樣長出來，跟這片沙洲一樣，沖走的沖走，淤出的淤出。

他站在潮聲裡，把這個念頭寫成四句：

白浪茫茫與海連，平沙浩浩四無邊。暮去朝來淘不住，遂令東海變桑田。

寫完他繼續去看堤防的進度，跟工匠商量哪一段要加厚。他知道這道堤修好，也擋不住潮水永遠不變——它只能延緩，不能凍結。可正是因為看懂了滄海桑田是真的會發生的事，他反倒不那麼執著要跟潮水對抗到底，只是盡力把堤修牢，讓眼前這一代人先過得穩當一點。`
  },

  // id=337 中唐 白居易 〈寄湘靈〉rating=3
  // 詩眼：寫給一個他清楚知道自己不可能再見到的人的一封信
  // 隱藏連接：相傳白居易青年時期在符離與鄰女湘靈相戀而未能結婚
  337: {
    title: "寄湘靈",
    author: "白居易",
    summary: "白居易年少時愛過一個門不當戶不對的鄰家女孩，這首詩就是那封他終究沒有寄出的信。",
    story: `跟你說我朋友樂天年輕時候，有一段感情，他這輩子沒跟很多人講過，倒是寫進了好幾首詩裡，〈寄湘靈〉就是其中一首。

那時他家裡跟著父親輾轉搬到符離，鄰居家有個女孩子，相傳叫湘靈。兩人算是從小一起長大的鄰居，樂天十幾歲的時候，兩家孩子常在門口的巷子裡碰面，一起在河邊玩水、看大人曬穀子，年紀小的時候誰也沒把這當一回事。他那時候還沒中舉，沒名氣，兩個人之間倒沒什麼身分的隔閡感，就是普通人家孩子的來往。年歲漸長，兩人漸漸有了避諱，見面反倒比小時候更少，可樂天心裡清楚自己對這個女孩子動了真感情，只是誰都沒把話說破。

可他家裡對這件婚事並不樂意。湘靈家世普通，樂天的母親對這門親事一直有意見，覺得配不上自家兒子將來的前程，樂天又是家裡指望能考出功名的兒子，這件事一年一年被家裡人壓著、拖著，始終沒個結果，樂天幾次想開口求母親鬆口，話到嘴邊又收回去。後來樂天要離開符離去別處求學、應試，兩人只能先分開，誰也沒把「等我回來」這句話說出口，怕說了反而更難受。

臨走那天很冷。樂天記得自己走出巷子的時候，眼睛裡有淚，可那個天氣凍得連淚水都流不動，凝在眼角，一路走一路覺得臉頰發僵。他走到一處高地，忍不住回頭望了一眼符離的方向——這一路走，他總在能望見來處的地方停下來，回頭看一眼，好像多看一眼就能把這個地方多留住一會兒。

他猜，自己走了以後，湘靈大概也會一個人爬上她家那座西邊的樓，靠在欄杆上，一個人發愁。她看不到他，他也看不到她，兩人隔著同一段距離，各自站在自己這一邊張望。

他把這份掛念寫成四句，沒有寄給誰，只是留在自己手邊：

淚眼凌寒凍不流，每經高處即回頭。遙知別後西樓上，應憑欄干獨自愁。

後來樂天入朝為官，成了名滿天下的白居易，娶了楊氏為妻，日子過得平順。可湘靈這個名字，他中年以後還在詩裡提起過幾次，像一件收在箱底、沒事不會拿出來、卻始終沒丟掉的舊物。那個站在高地回頭望的年輕人，後來走得很遠，可他那一眼，大概到老都還記得望向的是哪個方向。`
  },

  // id=345 中唐 劉方平 〈月夜〉rating=3
  // 詩眼：在別人都還沒察覺的深夜裡，一個人先聽見了季節翻頁的聲音
  // 隱藏連接：無
  345: {
    title: "月夜",
    author: "劉方平",
    summary: "全村人都還在睡，劉方平卻靠著一陣蟲鳴聲，比誰都早一步聽出春天已經來了。",
    story: `跟你說我朋友方平這個人，一輩子沒做過官，史書上關於他的記載薄得像一張紙，連他到底哪年生、哪年死都說不準，後人只能從他留下的幾十首詩裡，猜他大概是個什麼樣的人。可我認識他，知道他有個本事——別人還沒察覺的變化，他總是先聽見。

那天晚上他又沒睡。他這些年獨居慣了，夜裡常常醒著，索性起身坐在窗邊，也不點燈，就這樣任眼睛慢慢適應黑暗。夜已經很深，月光斜斜照進院子，只夠照亮半邊——另外半邊的屋子還沉在黑影裡，像是月亮也懶得把整個院子都照全。他抬頭看星象，北斗七星斜斜掛在天邊，南斗也已經偏過去了，這個角度他熟，一看就知道現在是後半夜，天快要轉向另一個季節的節骨眼上。

照理說，這種深夜什麼都該是安靜的。可他坐了一會兒，忽然聽出一件別人不會注意的事——窗紗外頭，蟲鳴的聲音跟前幾天不一樣了。不是變大聲，是變得更密、更透，像是趴在窗紗上似的，一下一下鑽進屋裡來，跟前幾夜那種斷斷續續、還帶點遲疑的叫聲完全不同。他心裡一動：今年的春天，比往年來得暖，而且是今天晚上才真正暖起來的。

別人要等到白天看見花開、看見樹綠，才知道春天真的到了。方平不用等，也沒人陪他一起等。他只靠這一夜的蟲聲，就已經確定了。這種本事說出來不稀奇，可只有真的常年獨自守著一個院子、把每一個夜晚都聽熟了的人，才會對這麼細微的差別這麼敏感。他一輩子沒什麼功名，沒什麼熱鬧的交際，鄰居大半也不知道他在寫詩，把日子過得極安靜，安靜到反而聽見了旁人聽不見的東西，這大概也是一種補償吧，他自己私下這麼想過。

他就在那扇窗邊，把這一夜寫成四句：

更深月色半人家，北斗闌干南斗斜。今夜偏知春氣暖，蟲聲新透綠窗紗。

寫完他也沒起身去看院子裡到底有沒有花開。他知道不用看，那點蟲聲已經把答案告訴他了。千百年後的人讀到這四句，大概都會有那麼一個深夜，忽然聽見窗外有什麼聲音不一樣了，才發現——原來季節早就悄悄翻頁，只是大多數人沒有方平那樣的耐心，坐到那麼晚才聽見。`
  },

  // id=351 中唐 韓愈 〈晚春〉rating=3
  // 詩眼：沒有天分去爭豔的人，把僅有的一招使到極致，那股不服輸的姿態本身就是才華
  // 隱藏連接：韓愈提拔詩風寒瘦的孟郊、賈島，借晚春花事對比楊花榆莢，借物喻人
  351: {
    title: "晚春",
    author: "韓愈",
    summary: "滿街紅紫爭豔時，韓愈卻盯著兩棵開不出花的樹看得入神——那正是他心裡孟郊和賈島的樣子。",
    story: `跟你說我朋友退之晚年在長安城郊散步，看見一整條巷子的花開得瘋，忽然想起自己這些年提拔過的幾個學生。

那年晚春，草木大概都知道春天快要過完了，一副拼盡全力的樣子——紅的紫的擠在一起爭著開，誰都不讓誰，巷子兩邊看過去，滿眼都是顏色，熱鬧得像在辦一場比賽，連風吹過都帶著香氣。退之站在那裡看了好一會兒，心裡卻想著另一件事。

他這輩子提拔過不少讀書人，裡頭有兩個他特別上心——一個是孟郊，考到四十六歲才中進士，詩寫得瘦硬，沒有那種讓人一看就驚豔的漂亮句子，常常一個字要磨上幾天；一個是賈島，考了一輩子也沒考上，一輩子清貧，寫詩琢磨字句琢磨到近乎自苦，聽說他曾經為了「推」跟「敲」兩個字，騎在驢背上想到撞了別人的轎子都沒察覺。這兩人放進滿城爭豔的詩壇裡，樣子確實不出彩，不像那些少年得志、詞藻華美的才子，一亮相就滿座讚嘆。

退之常替他們說話，別人笑孟郊、賈島詩寫得寒瘦，甚至私下叫他們窮酸，他偏偏覺得那份瘦硬底下藏著真本事——不靠天生的漂亮嗓子，靠的是死磨硬磨，一個字一個字磨出來的，磨出來的東西未必好看，卻經得起反覆讀，越讀越有味道。

他正想著，眼角瞥見巷子盡頭那兩棵楊樹跟榆樹。滿街紅紫爭得那麼熱烈，這兩棵樹卻什麼花都開不出來，只有滿樹的楊花跟榆莢，風一吹，就成片成片地飄，飛得漫天都是，像下雪一樣。旁人多半只當這是沒才情、沒本事開出好花色的樹，走過去看一眼就搖搖頭，退之卻站在那裡看得入神——他們沒有那種爭奇鬥艷的本錢，索性豁出去，把自己僅有的一招使到極致，飄得比誰都張揚，比誰都不肯輕易謝場。

他覺得這畫面像極了孟郊跟賈島。他把眼前的景象寫成四句：

草樹知春不久歸，百般紅紫鬥芳菲。楊花榆莢無才思，惟解漫天作雪飛。

寫完他笑了一下，把詩收進袖子裡帶回家。滿城紅紫終究會謝，可那場漫天飛雪般的楊花，反倒讓人記得更久。退之這輩子看人向來這樣——不看誰開得最豔，看誰肯把自己僅有的那一點本事，豁出去使到底。`
  },

  // id=354 晚唐 劉禹錫 〈台城〉rating=3
  // 詩眼：一個王朝真正垮掉的那一刻，往往是早幾十年前，一支曲子唱起來時大家聽得入神、沒人覺得有什麼不對
  // 隱藏連接：據傳劉禹錫寫金陵懷古系列時尚未到過金陵，全憑史書與想像，白居易讀後嘆服
  354: {
    title: "台城",
    author: "劉禹錫",
    summary: "劉禹錫一個地方都沒去過就寫下的懷古詩，讓白居易讀完直說後人不必再寫。",
    story: `跟你說我朋友夢得寫過一組懷古詩，題目底下自己加了一句話，老實得讓人意外——他說這些地方他一個都沒去過，寫的全是聽來的、讀來的，這種坦白在當時的詩人裡並不常見，大多數人寧可裝出一副親臨其地的樣子。

那時他人在外地，離金陵幾百里，手邊只有前朝的史書跟旁人轉述的傳聞。他寫的其中一首是台城。台城是六朝的宮城所在，從東吳到陳，一朝接一朝在那裡蓋宮殿，一朝比一朝奢華，誰都想蓋得比前一個朝代更氣派。到了陳後主那一代，登峰造極，蓋了結綺閣、臨春閣，雕梁畫棟，金玉滿目，傳說裡那是六朝豪奢的頂點，樓閣的窗戶都用香木鑲邊，風一吹滿屋子都是香氣。

夢得沒去過那地方，可他讀史書讀得夠透，知道結局。他知道陳後主整天躲在那兩座樓裡，聽著自己新編的曲子——後庭花，聽得渾然忘了城外隋朝的大軍已經渡江過來。等到兵臨城下，陳後主還在跟寵妃躲進井裡，萬戶千門的繁華，一夜之間全垮了，那口井後來還被人特意留下，當作亡國的笑談講給後人聽，說是連逃命都逃得不成樣子。

夢得閉著眼睛也能把那片廢墟想清楚——當年那些雕梁畫棟，現在大概只剩野草長得比人高，風一吹，草浪一片，連地基都快找不到，昔日的絲竹之聲換成了蟲鳴。他覺得可惜的不是奢華本身，是那整座城的人，眼睜睜看著一支曲子把國家聽垮了，還沒人肯醒過來，甚至還跟著一起唱。

他把這個念頭寫成四句：

台城六代競豪華，結綺臨春事最奢。萬戶千門成野草，只緣一曲後庭花。

後來這組詩傳到白居易手裡，白居易讀完，據說對著紙沉吟了很久，反覆看了好幾遍，直說這樣的題目，後面的人不必再寫了——夢得沒去過的地方，卻寫得比去過的人還準，連細節都對得上。

夢得聽到這個評語，心裡想的倒不是自己寫得多好，是那座從沒見過的台城教會他的事：一個朝代真正垮掉，往往不是敵人攻進來那一刻，是早幾十年前，某一晚，某一支曲子唱起來，大家都聽得入神，沒人覺得有什麼不對的那一刻，往後的結局，其實那一刻就已經寫定了。`
  },

  // id=358 晚唐 劉禹錫 〈遊玄都觀〉rating=3
  // 詩眼：十年後回來，故意用最輕描淡寫的一句話告訴當年整他的人：你們不過是我走了之後才被種下的花
  // 隱藏連接：與柳宗元同屬永貞革新八司馬，劉禹錫比柳宗元多活近三十年，親眼等到劉郎今又來的那一天
  358: {
    title: "遊玄都觀",
    author: "劉禹錫",
    summary: "被貶十年回長安，劉禹錫用一句看似寫景的詩，不動聲色地整了那些趁他不在時搶著栽花邀寵的人。",
    story: `跟你說我朋友夢得寫過一首詩，把整座長安城的新貴都氣得跳腳，連他自己都被害得又貶了一次——可他寫的時候，語氣輕鬆得像在講一件跟自己毫無關係的閒事。

夢得跟柳宗元是同一批人，當年一起搞永貞革新，一起垮台，一起被貶到天涯海角，史書上叫這八個人「八司馬」。宗元去了永州，夢得去了朗州，兩人隔著幾百里通信，一等就是十年，信裡從不敢多寫朝廷的事，只互相報個平安。宗元後來死在柳州，沒能等到回長安那一天。夢得比他運氣好一點，熬過十年，終於被召回京城。

回長安那天正是春天，滿城人都在傳一件事——玄都觀裡的桃花開了，滿滿一千多株，城裡的人踩著滿地紅塵，一個個都往那邊跑，看完花回來，人人都要提上一句，街頭巷尾聊的都是這件事。夢得也去看了。他站在觀裡，看著滿眼的桃花，忽然想起十年前他離開長安的時候，這觀裡根本沒有這些樹，連地都還是空的。

這一千多棵桃樹，分明是他被貶出京城之後，才有人栽下去的。也就是說，眼前這片讓滿城人爭著去看的盛景，壓根跟他這十年的死活沒有一點關係——他人在天涯受苦的時候，這些樹才剛剛種下；等他吃盡苦頭終於回來，樹已經長成滿觀的繁花，而栽樹的人，大概正是十年裡趁機爬上去的那些新貴，一個個換了位置、換了排場。

夢得心裡那股氣，沒有直接罵出來，他寫得客客氣氣，像是純粹寫景：

紫陌紅塵拂面來，無人不道看花回。玄都觀裏桃千樹，盡是劉郎去後栽。

這首詩傳出去，滿長安的新貴都聽懂了——這是在指他們。沒過多久，夢得又被貶出京城，這次去的地方更遠。可他沒有服軟。十四年後他又回到長安，再去玄都觀，發現滿觀的桃樹早就砍光了，只剩滿地青苔跟種菜的畦壟。他站在原本該是滿樹桃花的地方，忽然覺得好笑，又寫了一首，末句只有五個字：劉郎今又來。

那些趁他不在時搶著栽花邀寵的人，一個個早就不見了，連當年那些桃樹本身都不在了，只有他這個當年被趕走的「劉郎」，一次次被貶、一次次還是走回了這座城。桃花謝了又謝，栽花的人換了又換，他倒是熬到了最後。`
  },

  // id=361 晚唐 李商隱 〈為有〉rating=3
  // 詩眼：費盡千辛萬苦嫁進了讓所有人羨慕的門檻，換來的卻是每天清晨獨自守著空掉的被窩
  // 隱藏連接：李商隱自己也因政治聯姻捲入牛李黨爭夾縫，常年在外奔波，或有切身理解
  361: {
    title: "為有",
    author: "李商隱",
    summary: "外人都羨慕她嫁了個有品級的貴官丈夫，李商隱卻寫出她每天早晨摸到的，只是一床空掉的錦被。",
    story: `跟你說我朋友義山寫過一首詩，替一個他根本不認識的女子，把心裡話全講出來了。

那女子嫁的人家，是外人眼裡最不吃虧的一門婚事。她家境好，雲母屏風擋著滿室的嬌嬈，長安城裡的寒氣剛退，一到春天夜裡反倒更怕——不是怕冷，是怕天亮。她嫁的丈夫佩著金龜符，那是有品級的官員才能配戴的東西，外人一看就知道這是嫁對了人的金龜婿。街坊鄰居誰不羨慕，見面總要說一句這輩子不愁了，連她自己起初也這麼以為。

可義山寫的重點不是外人看到的那些，是這個女子自己心裡的落差。丈夫官職越高，早朝就越不能遲——天還沒亮就得起身，穿戴整齊，趕去宮門外候著，連一句話都來不及多說。女子每天在那張熏得暖香的錦被裡，才剛把丈夫的溫度焐熱，人已經走了，留下的只有半邊涼了的枕頭。她一個人守著滿室的富貴，守著誰都羨慕的門面，實際上過的是每天清晨對著空掉一半的被窩，日子久了，連怕天亮這件事，也成了習慣。

義山寫這個題材，用的是女子的口吻，心裡想的其實不只是這個女子。他自己這輩子的婚姻，也帶著點類似的味道——他娶的妻子王氏，是他一路捲進牛李兩黨政爭的關鍵，外人也覺得他攀上了好親家，可他真正得到的，是常年被兩邊都不信任，四處奔波當個小小的幕僚，一年裡在家的日子屈指可數，每次寫信回家，總是先問一句家裡都好嗎。他比誰都清楚，外人眼中「嫁得好、娶得好」這件事，跟屋子裡那個人每天早上醒來摸到的是不是一床空被，是完全兩回事，外人看的是門面，睡在被窩裡的人看的是溫度。

他把這個女子的心事寫成四句：

為有雲屏無限嬌，鳳城寒盡怕春宵。無端嫁得金龜婿，辜負香衾事早朝。

寫完他沒有署上自己的心事，詩裡從頭到尾只有那個女子。可讀熟他生平的人多少能猜到，他寫得這麼準，大概是因為那張空掉的被窩，他自己家裡也常年鋪著——只是換成他自己，是那個天不亮就要出門、把溫度留在原地的人，而遠方的王氏，大概也正對著同一張被子，想著跟詩裡那個女子一樣的心事，只是她從來沒抱怨過一句。`
  },

  // id=362 晚唐 李商隱 〈隋宮〉rating=3
  // 詩眼：一個王朝真正的滅亡徵兆，不是刀劍架到脖子上，而是滿朝的絲綢已經拿去做船帆而不是給百姓做衣裳
  // 隱藏連接：李商隱身處晚唐牛李黨爭邊緣，慣以借古諷今手法影射當朝奢靡
  362: {
    title: "隋宮",
    author: "李商隱",
    summary: "李商隱寫兩百年前那艘亡國的龍舟，說給看得懂的當朝人聽。",
    story: `跟你說我朋友義山寫詩罵人，從來不指名道姓，也不留把柄，他挑的辦法是往前翻兩百多年的舊帳，讓聽得懂的人自己去對號。

他寫的是隋煬帝。這個人史書上寫得很清楚——當皇帝沒幾年，就一心要往南邊的江都去玩，說走就走，連該有的戒備都懶得布置周全，好像天下太平到不需要防著誰，滿朝文武想勸都插不進話。宮裡九重深處，堆著多少大臣寫的諫書，勸他別這麼胡鬧，可那些奏章大概連拆都沒拆，更別說看進去半個字，壓在案頭跟廢紙沒什麼區別。

義山寫得最狠的是絲綢那兩句。隋煬帝要下江南，光是龍舟跟儀仗就要耗掉舉國織出來的錦緞——一半拿去給馬鋪障泥，免得泥水濺到馬腿；一半直接裁成船帆，好讓那一整支船隊浩浩蕩蕩地順流而下，兩岸的百姓還得跟著拉纖，喊著號子把船拖過淺灘。這些絲綢原本該織成尋常百姓身上的衣裳，現在全拿去給皇帝的排場鋪路擋泥、迎風招展，織布的人一年到頭織出來的東西，自己一件都穿不上，倒是給馬腿擋了泥。

義山寫這幾句的時候，心裡想的不完全是兩百多年前那個亡了國的皇帝。他自己活在牛李兩黨鬥得你死我活的晚唐朝廷邊緣，親眼看過當朝天子怎麼揮霍、怎麼聽不進諫言，那些場面跟史書上寫的隋煬帝，竟隔著兩百年還能對上號。他不敢明著罵當今皇上，借古人的舊帳來說今人的新帳，是他這輩子練出來的本事——寫史，其實是寫眼前，只是換了一個更安全的年號。

他把隋煬帝那場荒唐的南遊寫成四句：

乘興南遊不戒嚴，九重誰省諫書函。春風舉國裁宮錦，半作障泥半作帆。

這首詩傳開以後，懂的人都懂——隋朝亡在這場排場裡，而眼前這個朝代，離這個排場也沒有多遠，甚至連細節都能一一對上。義山寫這些詠史詩，從不指望能勸動誰回頭，他心裡清楚，真正聽得進諫言的皇帝，史書上向來寥寥無幾，寫了也未必有人肯看。他能做的，只是把兩百年前那條沉船的樣子畫清楚，留給後面看得懂的人——一整船的錦繡，鋪的不是路，是通往亡國的最後一程，而那艘船，遲早會換上另一個朝代的名字，重新出發一次。`
  },

  // id=363 晚唐 李商隱 〈瑤池〉rating=3
  // 詩眼：求長生的人，連再回來看一眼這種最基本的承諾都做不到
  // 隱藏連接：李商隱親身經歷唐武宗因服食丹藥暴斃，朝中方士的鬧劇他冷眼旁觀多年
  363: {
    title: "瑤池",
    author: "李商隱",
    summary: "他寫的是幾百年前周穆王的爽約，其實在寫眼前這位皇帝——同樣相信自己能求得長生，同樣連回來看一眼都辦不到。",
    story: `跟你說我朋友義山那幾年在長安冷眼看到的一齣鬧劇。宮裡新添了一批穿黃袍的方士，個個自稱能煉出讓人長生不死的仙丹，皇帝把他們當成救命恩人一樣供著。義山那時候在秘書省當差，官小話輕，只能在旁邊看，看得心裡發毛。

那年冬天他聽說宮裡又添了一座新的煉丹爐，爬上終南山採藥的方士絡繹不絕，宮女私下傳說皇帝這幾個月臉色越來越差，脾氣也越來越怪，卻越吃那些丹藥越勤，好像吃得越多、離神仙就越近一點。同僚私下議論的時候都壓低了聲音，沒人敢直接說皇帝服的東西可能有毒——那個話題,誰提誰倒楣。義山聽著這些議論,想起小時候聽過的一個更老的故事，周穆王的故事。

傳說西王母住在瑤池，窗子綺麗，她曾經接待過周穆王，兩人相談甚歡，穆王臨走時說好了以後會再回來看她。西王母就這麼等著，把窗子擦得亮亮的，一開就是幾百年。可是穆王沒有回來。穆王當年北巡的路上，遇見大雪，隨行的百姓凍死了不少，他寫下一首黃竹歌，聲音悲哀到驚動天地，那是他仁厚的一面。可他有八匹能日行三萬里的駿馬，天下再遠的地方都能去得到，偏偏就是回不到瑤池那扇窗前。義山每次想到這裡都覺得奇怪，一個能跑遍天下的人，怎麼會單單漏了一個承諾過的地方。

義山把這個故事寫成四句詩，擺在案頭很久，遲遲沒有拿出去。他心裡想的其實不是幾百年前的周穆王，是眼前這位皇帝，同樣相信自己能求得長生，同樣把大把心力砸進那些虛無的承諾裡。他甚至想過，那些方士對皇帝說的話,大概也跟西王母當年聽到的承諾差不多好聽，只是誰都沒把後果想清楚。他忽然覺得很諷刺，一個人擁有再快的馬、再高的權位、再多方士的吹捧，到頭來連回來看一眼這麼小的一件事都辦不到，更別說長生不死了。

他提筆寫下：瑤池阿母綺窗開，黃竹歌聲動地哀。八駿日行三萬里，穆王何事不重來。

沒多久，宮裡傳來消息，皇帝駕崩了，才三十出頭。方士們一夜之間全都不見了蹤影，煉丹爐也熄了火，像什麼都沒發生過，連當初信誓旦旦的那些話,也沒人再提起。義山把那四句詩收進自己的詩集裡，沒有加一個字的注解，也沒告訴任何人這寫的是誰，只是偶爾夜裡想起這件事,還是覺得心裡發涼。

千年後的人讀這首詩，大多以為只是在講一個古代神話。可義山當年寫下最後一句的時候，心裡想的分明是那扇他自己也見過的，始終沒等到人回來的窗。`
  },

  // id=365 晚唐 李商隱 〈賈生〉rating=3
  // 詩眼：皇帝聽得入神到不自覺挪近坐席，卻只問鬼神，不問活人怎麼活
  // 隱藏連接：李商隱自身也是被賞識卻不被真正任用的賈生，才華被看見卻困在牛李黨爭裡動彈不得
  365: {
    title: "賈生",
    author: "李商隱",
    summary: "皇帝聽賈誼講到坐席都不自覺往前挪，感動得不得了，聊了一整夜卻只問鬼神，一句都沒問老百姓怎麼活。",
    story: `跟你說我朋友義山常常掛在嘴邊的一個人，賈生，賈誼。這個人比義山早了快一千年，可義山覺得自己跟他像到有點難堪，每次讀到他的事,都忍不住想拍桌子。

賈誼二十出頭就被漢文帝看上，一路做到太中大夫，年紀輕輕就參與國家大政，朝裡老臣看他不順眼，說他年輕氣盛、想改的東西太多，聯手排擠，把他外放到長沙當太傅。那地方又遠又偏，離長安幾千里，濕熱多瘴氣，賈誼在那邊寫了一篇一篇的政論，句句都是講怎麼治國、怎麼安民、怎麼防患邊境,可是遠在長安的朝堂上,沒人在意,那些奏疏大概只是被歸檔了事。

後來文帝又想起他，把他召回宣室，那是皇帝接見親近臣子議事的地方，不是隨便誰都能進去的。賈誼進宮那天晚上，兩人一直聊到很晚，殿裡的燈一盞接一盞地換。文帝聽得太專注，身子不自覺一次一次往前挪，坐席都快挪空了，旁人看著都覺得誇張，一個皇帝對一個曾經被貶到蠻荒之地的年輕人，恭敬到這個程度，殿外守夜的人都覺得這場夜談大概要談出一番新政了。

義山每次講到這裡都會停一下，語氣裡帶著點無奈。因為接下來這句才是關鍵，文帝聊了整整一夜，問的全是鬼神的事，人死後去哪裡、天上有沒有神仙、命運能不能算得出來。賈誼滿肚子關於老百姓怎麼過日子、國家該怎麼治理的話，一句都沒能說出口，那些他在長沙夜裡熬燈寫下的政論,終究沒有機會派上用場。

義山自己也被幾個賞識他的人拉進過官場，人家誇他文章寫得好，誇他有宰相之才，可真正輪到要不要重用他的時候，牛李兩黨互相牽制，誰都不敢真的把位置給他。他被賞識，卻從沒被真正用過，跟賈誼那個晚上一模一樣，一個人的才華被看見了，眼神被看見了，可他真正想做的事，始終沒有機會做。

他把這件事寫成四句：宣室求賢訪逐臣，賈生才調更無倫。可憐夜半虛前席，不問蒼生問鬼神。

義山寫完把筆放下，想著這四句既是在講賈誼，也是在講他自己，也是在講他認識的每一個懷才不遇的朋友，被看見是一種幸運，被真正用上又是另外一回事，兩者之間隔著的距離，常常就是一整個人的一生。`
  },

  // id=379 晚唐 杜牧 〈嘆花〉rating=3
  // 詩眼：遲到十四年赴約，卻只能眼看果實已經滿枝
  // 隱藏連接：相傳杜牧年輕時與湖州女子母親有十年之約，因官場調動遲了四年才重回湖州
  379: {
    title: "嘆花",
    author: "杜牧",
    summary: "他跟一個女子的母親約好十年後回來娶她，結果十四年後才趕到，樹上的花早就被風吹光了。",
    story: `跟你說我朋友牧之年輕時做過一件事，後來想起來，他自己也覺得又好笑又心酸，講起來還會停頓好幾次，像是不太願意面對。

那年他還在江南一帶當地方官，路過湖州，遇見一場水戲表演，湖邊人聲鼎沸，人群裡有個女子，約十幾歲，長得清秀，眼神特別安靜，他一眼就記住了，回去之後好幾天都想著這件事。他託人去說親，女子的母親聽完，沒有立刻答應，只提了一個條件，女兒還小，再等十年，牧之若還沒娶妻，就回來娶她，家裡一定等他。牧之答應得又快又爽氣，覺得十年不過是一晃眼的事，還備了聘禮才走，心裡想著十年後自己一定準時出現。

可是官場的事身不由己。他被調來調去，一年拖過一年，一開始還記得數著日子，後來公務纏身，連日子都數不清了，十年過去他都沒能脫身，又拖了四年，總共十四年，他才終於有機會重回湖州。他心裡一直記著那個約定，趕過去的時候還帶著點年輕時的期待，甚至一路上都在想像重逢的畫面，以為自己還能趕上。

到了湖州才知道，女子早在三年前就已經嫁了人，如今兩個孩子都養得白白胖胖，一家人過得平順。牧之站在原地，一句怪不得誰的話都說不出來，不是女子的錯，也不是她母親的錯，是他自己把十年活成了十四年,把一個約定活成了一個遲到的笑話。

他去看了她家門前那株當年印象最深的花樹。花早就開過了，又被一場大風吹得一片不剩，只剩下滿樹濃綠的葉子，葉子底下已經結滿了果實，壓得枝條微微垂下來，風一吹,枝葉搖晃的聲音聽起來格外清楚。他站在樹下看了很久,一句話也沒說。

牧之提筆寫下四句：欲去尋春去羅遲，不需惆悵怨芳時。狂風盪盡深紅色，綠葉成蔭子滿枝。他寫的是遲到，寫的是別去怨恨花開得不是時候，是他自己來得太晚，花該開的時候他不在，如今只能看著早已經是別人家的滿枝果實。

這件事後來被人記在唐代的筆記裡，當作牧之風流卻也認真的一面流傳下來。相傳的細節或許有出入，但那株結滿果子的樹，和那個站在樹下無話可說的中年人，始終是這四句詩背後最清楚的畫面。`
  },

  // id=381 晚唐 韋莊 〈金陵圖二〉rating=3
  // 詩眼：看畫看到自己親身經歷過的亡國
  // 隱藏連接：韋莊親歷黃巢之亂圍困長安數年，寫過秦婦吟，後又輾轉入蜀見唐朝覆滅
  381: {
    title: "金陵圖二",
    author: "韋莊",
    summary: "別人只當那是幾百年前的古畫，他卻在畫裡的荒涼認出了自己親眼見過的長安淪陷。",
    story: `跟你說我朋友端己晚年在金陵城裡看畫的一個下午。那幅畫他盯了很久，久到旁邊的人都覺得奇怪，畫的不過是幾百年前六個南朝的舊事，有什麼好看得這麼入神，值得一個當朝的高官這樣站著不動。

端己年輕時候在長安讀書趕考，本來想的是好好考個功名，安穩過一生，誰知道黃巢的兵打進長安那幾年，他被困在城裡，米糧一天比一天貴，街上到處是燒過的屋子，他親眼看著這座天下第一大城怎麼一點一點被燒、被搶、被血洗。他把那幾年看到的慘狀寫成了一首很長的秦婦吟，裡面每一句都是他自己撿回來的命換來的,後來這首詩流傳極廣,甚至傳到了他自己都不知道的地方去。後來他又輾轉入蜀，一路走過殘破的關山,眼看著唸了幾百年的大唐王朝走向終點，連皇帝的位子最後都被朱溫奪了去,那種親眼看著一整個時代垂死的感覺,他一輩子都甩不掉。

所以那天在金陵，有人拿出一套六幅的畫，畫的是南朝，東晉之後宋齊梁陳接連建都在這裡，一個接一個興起，一個接一個滅亡，前後不過兩百多年。端己一幅一幅看過去，越看越沉默，手裡的茶都涼了也沒喝。旁人只當那是古畫家的技藝高明，端己卻覺得畫裡那種說不出來的荒涼感，他太熟悉了，熟悉到心裡發疼，那種荒涼跟他記憶裡燒過的長安街道,竟然是同一種顏色。

有人隨口問他，畫得好不好。端己說，沒人以為傷心的事情可以畫出來，可畫的人偏偏把人心裡最深的傷心事，畫進了世間人的常情裡,讓每個看畫的人都能懂那種說不出來的痛。

他提筆在畫旁題了字：誰謂傷心畫不成，畫人心逐世人情。君看六幅南朝事，老木寒雲滿故城。他寫的老木寒雲，不只是畫裡的南朝故城，也是他自己記憶裡那座燒過的長安，那條他走過的入蜀的路。

端己後來留在了蜀地，輔佐王建建立了前蜀，總算在亂世裡找到一個能安身的地方。可是那天他站在金陵城裡看畫的樣子，後人只從這四句詩裡看得到，一個親眼見過帝國崩塌的人，看著別人畫出來的另一次崩塌，忽然發現自己竟然一句話都不必多說，畫已經替他說盡了。`
  },

  // id=384 晚唐 張祜 〈集靈臺二首之二〉rating=3
  // 詩眼：美到不需要化妝的驕縱，正是盛世崩塌前最刺眼的畫面
  // 隱藏連接：張祜生於中晚唐，沒趕上開元盛世，從長輩講述裡拼湊出那個時代的鮮豔與危險
  384: {
    title: "集靈臺二首之二",
    author: "張祜",
    summary: "她天生麗質，嫌脂粉遮住了自己的顏色，天剛亮就素顏騎馬進宮見皇帝，長安人記了她好幾十年。",
    story: `跟你說我朋友承吉常常跟人講起一個他自己沒趕上、卻聽長輩講了無數次的畫面。那年頭他還沒出生，長安城裡卻已經流傳著一個女人騎馬入宮不施粉黛的故事，一講起來就是好幾十年，講的人換了一代又一代，細節卻始終沒斷過。

那是開元天寶年間，楊家因為出了個貴妃楊玉環，一家子跟著封官晉爵，楊貴妃的姐姐被封為虢國夫人，論寵愛、論排場，幾乎跟公主平起平坐，出門有儀仗，進宮不用通報。長安人都記得清清楚楚，虢國夫人天生麗質，不愛脂粉，別的貴婦人天沒亮就得起來梳妝，塗脂抹粉忙上大半個時辰，她卻嫌那些脂粉膏黛會蓋住她本來的顏色，只淡淡描了兩筆眉，天剛亮就騎著馬直接進宮門去見皇帝，馬蹄聲一響,街上的人都知道是她來了。

承吉聽長輩講這段往事的時候，語氣裡總帶著一種複雜的意味，既是讚嘆，又是嘆息。讚嘆的是那份天生的美貌和敢於素顏見駕的氣派，嘆息的是，這樣的驕縱正是後來那場大亂的前兆。楊家得寵的那幾年，朝政幾乎被楊國忠把持，邊將安祿山藉機坐大，沒過幾年，安史之亂就爆發了，長安淪陷，玄宗倉皇出逃，楊貴妃死在馬嵬坡，虢國夫人也死在逃難路上，一場鮮豔的盛況，收得比誰都快。

承吉出生的時候，那場亂已經過去了，他這輩子沒見過真正的開元盛世，只從長輩的講述和史書的字句裡，拼湊出那個時代的模樣，一邊聽一邊在心裡描摹那份繁華究竟是什麼樣子，想像著那座他從沒見過的、還沒被燒過的長安。他每次想起虢國夫人騎馬入宮的畫面，都覺得那種光鮮亮麗底下，其實已經埋著日後的崩塌，只是當時誰都沒看出來，連虢國夫人自己大概也沒想過，那身不施粉黛的美貌,幾年後會跟整個家族一起葬在逃難的路上。

他提筆寫下：虢國夫人承主恩，平明騎馬入宮門。卻嫌脂粉污顏色，淡掃蛾眉朝至尊。寫的是美，寫的也是那種美背後藏著的驕慢與危險。

承吉這輩子活在盛世的餘燼裡，他寫下這四句，不是羨慕那個女人的美貌，是想提醒後來的人，一個王朝最鮮豔的那個瞬間，往往已經是它開始下墜的那個瞬間。他把這幾句寫完,又讀了一遍,覺得字裡行間那份美,美得刺眼,美得讓人心裡發慌,比任何直接的責備都更能讓後人記住那段教訓。`
  },

  // id=386 晚唐 朱慶餘 〈宮詞〉rating=3
  // 詩眼：心裡的話堵在嘴邊，因為連一隻鳥都不能信
  // 隱藏連接：朱慶餘曾任秘書省校書郎，出入宮廷附近官署，聽多了深宮裡流傳出來的閒話
  386: {
    title: "宮詞",
    author: "朱慶餘",
    summary: "兩個宮女好不容易碰上面，滿肚子話想說，卻因為前面站著一隻會學話的鸚鵡，一句都不敢開口。",
    story: `跟你說我朋友可久當校書郎那幾年，常常在宮牆邊的官署裡進出，天天抱著一堆典籍文書走來走去。他管的是典籍文書，離那些深宮內院隔著好幾道門，尋常人根本進不去，可宮裡的閒話還是會飄出來一些，順著搬運文書的小吏、送膳的宮人,一點一點飄到他耳朵裡。

有一回他聽人講起一個畫面，說得很細，像是誰親眼見過一樣，寂靜的花開時節，院門緊閉，四周靜得只聽得見風吹過花枝的聲音，兩個宮裡的美人並肩站在玉石欄杆邊上，神色間帶著滿肚子的話想說。她們是同批選進宮裡的姐妹淘，剛入宮那幾年還常聚在一起說笑，後來各自被分到不同的院子,平日各自守著各自的院子，難得能碰上面，好不容易站在一起，心裡藏著的宮中種種心事全湧了上來，話都已經到了嘴邊，眼看就要開口。

可她們前頭站著一隻鸚鵡。那鳥被養在廊下，平時逗趣解悶，誰都不當心它，可這一刻，兩個女人卻突然都不敢說話了，彼此對看一眼，又都把嘴閉上。鸚鵡學人話學得極快，誰知道它會不會把剛剛聽到的一字一句學給別人聽，又傳到不該聽的人耳裡去。深宮裡，一句話說錯，可能就是一輩子的麻煩，輕則被罰,重則連命都保不住。

可久把這個畫面記在心裡很久，想了又想，越想越覺得那個瞬間比任何宮鬥的傳聞都更讓人心疼。他覺得可怕的不是宮裡規矩多，是連兩個關起門說知心話的姐妹，身邊都得防著一隻鳥。人和人之間本來最私密的一點空隙，在那道宮牆裡，連一隻鸚鵡都能把它填滿，什麼都不剩，連一句抱怨,一句想家的話,都得先在心裡過濾一遍才敢往外吐。

他提筆寫下：寂寂花時閉院門，美人相並立瓊軒。含情欲說宮中事，鸚鵡前頭不敢言。寫的不是鸚鵡多聰明，是那兩個女人臉上，話到嘴邊又硬生生吞回去的表情。

可久這輩子官不大，詩也不算頂出名，可這四句一直流傳下來。後來的人讀到，大多會想起自己也有過類似的時刻，不是宮裡，是任何一個明明想說真心話，卻因為旁邊多了一個人，話就這麼卡在喉頭的場合，那種欲言又止的滋味,隔了一千多年,依然一點都不陌生。`
  },

  // id=387 晚唐 朱慶餘 〈近試上張水部〉rating=3
  // 詩眼：用新嫁娘的心情問前輩，我這樣考，合不合主考官的胃口
  // 隱藏連接：真實的張籍酬詩往來，唐代筆記記載的科舉佳話
  387: {
    title: "近試上張水部",
    author: "朱慶餘",
    summary: "他把自己比成一個要見公公婆婆的新嫁娘，寫信問前輩，我畫的這個眉毛深淺，合不合現在的時興樣式。",
    story: `跟你說我朋友可久考進士前那個晚上，緊張到寫了一首詩，不是寫給皇帝，也不是寫給自己壯膽，是寫給一個他很敬重的前輩，叫張籍，當時擔任水部員外郎，在文壇上很有分量，提拔過不少後輩，一句話往往比考官的批語還管用。

可久那年已經準備了很久，文章改了又改，寫得他自己都覺得還算滿意，可越接近考試，他心裡越沒底，考場裡評卷的官員喜歡什麼樣的文風，自己完全猜不透，萬一風格不對,再好的文章也可能被冷落。這種事沒辦法直接開口問，顯得太急功近利，也怕張籍嫌他太露骨，可久想了很久，躺在床上翻來覆去，最後決定換一個比喻來問。

他寫的是一個新嫁娘的心情。洞房昨天晚上剛剛熄了紅燭，今天一早天還沒亮，她就得先去堂前拜見公公婆婆，規矩不能錯，一個新婦第一次露面,全家人都在看。她梳妝打扮完，對著銅鏡描了又描，臨出門前，忍不住低聲問了新郎一句，她畫的這個眉毛深淺，合不合現在時興的樣式。這不是虛榮，是她太清楚，第一次在公公婆婆面前露面，一個細節出錯，往後的日子都不好過。

可久把自己比成那個新嫁娘，把張籍比成那個新郎，把主考官比成堂前等著挑剔的公公婆婆。他想問的其實是，我這篇文章，合不合考官現在喜歡的樣子，能不能通過那一場最重要的檢視。這個比喻他想了整整一個晚上，改了幾次用詞,才覺得分量拿捏得恰好,既不失禮,也把自己的緊張全都藏進了畫面裡。

他提筆寫下：洞房昨夜停紅燭，待曉堂前拜舅姑。妝罷低聲問夫婿，畫眉深淺入時無。寫完自己看了幾遍，覺得這樣問，既體面又懇切，比直接開口討教漂亮多了。

張籍收到這首詩，顯然懂了他的意思，也很喜歡這個比喻，回贈了一首詩，誇他就像鏡湖邊剛梳妝好的越女，美得連自己都要沉吟半天，說他的文章早就夠格，不必再擔心。可久收到回信那一刻,懸著的心才算放下,一整晚的忐忑全化成了鬆一口氣的笑。他後來果然考上了。這件事被唐代的文人記在筆記裡流傳下來，成了科舉場外一段惹人會心一笑的佳話，才子問路，問得比誰都體貼周到，比誰都懂得把不安包裝成一句溫柔的問話。`
  },

  // id=388 晚唐 溫庭筠 〈瑤瑟怨〉rating=3
  // 詩眼：連夢都做不成的夜晚，只能任由思念隨雁飛走
  // 隱藏連接：溫庭筠自己屢試不第、常年輾轉異地代筆謀生，深知等待與孤獨的滋味
  388: {
    title: "瑤瑟怨",
    author: "溫庭筠",
    summary: "她夜裡怎麼也睡不成夢，只能聽著雁群飛向她思念的人所在的遠方，自己卻留在原地。",
    story: `跟你說我朋友飛卿寫這首詩之前，自己已經在外頭飄了很多年，考場屢屢不順，一次又一次進場,一次又一次落榜,靠著幫人代筆、寄住在別人家裡過日子。他自己也是那種天天盼著一個消息、卻總是等不到的人，所以寫閨中女子等人不至的心事，寫得格外貼切，不像隔著一層在講別人的故事，更像是把自己的日子挪進去。

那晚他借住的地方，夜裡很涼，竹席冰冰的貼著身子，銀飾的床架反著微弱的光。他躺著翻來覆去，怎麼也睡不著，腦子裡轉的都是白天奔波的瑣事和沒有結果的期待，索性起身推開窗子。夜空乾淨得像一片水，幾縷薄雲輕輕飄著，月色清得能看見很遠的地方，遠得讓人忍不住想,那個地方會不會也有人正望著同一片天。

他想起自己認識的一個女子，聽人說她常年一個人守著深閨，思念的人在很遠很遠的南方，遠到超過瀟水和湘水那一帶，遠到書信一年也未必能送到一次。他猜她這樣的夜裡大概也是這個樣子，翻來覆去，怎麼也睡不成一個安穩的夢。他想像著那個畫面，她也推開窗，也聽見天上有雁群飛過，雁鳴一聲接一聲，那群雁一路往南，飛向瀟湘，飛向她心裡那個人所在的方向，而她自己卻只能留在原地，連夢都留不住，只有十二座樓閣裡，那輪月亮還一如既往，自己明亮著，陪著她一整夜，什麼都替不了,卻也什麼都沒少陪。飛卿想著想著,竟覺得那輪月亮的處境,跟自己這些年靠著文章換一頓飯、一張床的日子,倒也有幾分相似——都是在等一個說不準什麼時候會來的東西。

他把這個畫面寫下來：冰簟銀床夢不成，碧天如水夜雲輕。雁聲遠過瀟湘去，十二樓中月自明。他寫的那個等不到人的女子，某種程度上也是他自己，同樣夜裡睡不著，同樣看著遠方，同樣沒辦法讓自己想要的東西靠近一點。

飛卿這輩子考了很多次都沒考上，靠才氣在文人圈裡闖出名聲，卻始終沒能真正安定下來，換過一個又一個借宿的屋子。他寫的閨怨詩總是特別動人，後來的人未必知道，那份對等待與孤獨的體會，其實是他自己漂泊多年，一點一點攢出來的，攢在每一個推窗看月、卻等不到任何人回應的夜裡。`
  },

  // id=394 晚唐 無名氏 〈雜詩〉rating=3
  // 詩眼：有家卻回不去，連鳥叫聲都要拜託牠別再提
  // 隱藏連接：無
  394: {
    title: "雜詩",
    author: "無名氏",
    summary: "相傳寒食節那場雨裡，一個回不了家的人聽見杜鵑啼叫，忍不住開口求牠別再叫了。",
    story: `跟你說一個流傳很久、連作者名字都沒能留下來的故事。這首詩相傳是寒食節前後，一個離家在外、回不去的人隨口寫下的，寫的人是誰，後來的人早就查不出來了，史書上只留了無名氏兩個字，連是哪個朝代的人都只能靠詩裡的風景猜個大概。

相傳那年寒食節前後，天下著小雨，已經下了好幾天，路邊的草長得又密又亂，田裡的麥苗被風吹得一陣一陣倒過去，河堤兩岸種的柳樹也被吹得枝條亂晃，整條路都濕答答的，走起來一腳深一腳淺。這種天氣本來就容易讓人心情低落，偏偏寒食節又是家家戶戶祭祖、團聚的日子，家家門口飄著紙灰味,在外地的人這時候格外想家,想得心裡發酸。

相傳這個人本來是要在這個節日趕回家鄉的，行李都收拾好了，甚至已經跟同行的人約好了出發的日子，可是不知道什麼緣故，趕不回去了，可能是路途太遠，可能是身上的錢不夠，也可能是有什麼事情臨時耽誤了，計畫一改再改，最後乾脆什麼都改不成了。反正家在那裡，人卻沒辦法到，這種心情，古今的旅人大概都懂。他一個人站在雨裡的柳堤邊，衣服都被打濕了也沒察覺，眼睛望著雨幕那頭，好像家鄉的方向就藏在那片灰濛濛裡，聽見遠處有杜鵑在叫。

杜鵑的叫聲在古時候的傳說裡帶著一種悲涼的意味，相傳杜鵑啼血，叫聲聽起來像是在說不如歸去，本來就容易勾起人的鄉愁，這個人心裡已經夠難受了，再聽這叫聲，簡直是往傷口上撒鹽，一聲接一聲，怎麼躲都躲不開。他忍不住開口，像是在跟那隻鳥講道理，又像是在求牠，同樣是有家歸不得的人，已經夠苦了，杜鵑啊，你就別再在我耳朵邊上叫了。

他把這句話寫成了詩：盡寒食雨草萋萋，著麥苗風柳映堤。等是有家歸未得，杜鵑休向耳邊啼。寫完之後,他把紙折起來塞進懷裡,繼續在雨裡走著,雨還在下,家鄉還是那麼遠。這幾句沒有留下他的名字，卻留下了他那個雨天站在柳堤邊的畫面，留給後來每一個抄錄這首詩的人自己去猜、去補上一個名字。千百年後，每一個在異鄉過節、有家回不去的人，讀到這四句，都會覺得那隻杜鵑好像也在對著自己叫。`
  },

  // id=401 北宋 蘇軾 〈六月二十七日望湖樓醉書〉rating=3
  // 詩眼：一場來得快去得快的暴雨，恰好照出他這階段起落無常的心境
  // 隱藏連接：蘇軾當時因反對王安石新法自請外任杭州通判，借酒與湖光暫時忘掉朝爭
  401: {
    title: "六月二十七日望湖樓醉書",
    author: "蘇軾",
    summary: "烏雲翻滾得像打翻的墨汁，雨還沒下完，一陣風就把整片天吹乾淨了，湖面又平靜得像天空一樣。",
    story: `跟你說我朋友子瞻在杭州那幾年最放鬆的一個下午。他這時候剛從朝廷退下來沒多久，因為反對王安石推行的新法，話說得太直，跟朝中不少人吵過幾次，在朝裡待不下去，自己請求外放，派到杭州當通判，官不大，事不多，倒是給了他難得的空閒,天天可以往西湖邊上晃。

那天是六月二十七日，天氣熱，子瞻跟幾個朋友到西湖邊上的望湖樓喝酒，一杯接一杯，喝得正暢快，天色忽然變了。他抬頭一看，遠處的天空湧上一片烏雲，黑得像剛剛打翻的墨汁，滾滾地翻過來，可還沒等把對面的山頭完全遮住，雨就先下起來了。那雨下得又急又大，白花花的雨點砸在湖面上，又跳著砸進他們的船艙裡，像撒了一把珍珠，噠噠地打在船板上。

子瞻和朋友們一時間顧不上喝酒了，又是躲雨又是笑鬧，酒杯裡都積了水，有人乾脆仰頭把雨水當酒喝了一口，惹得眾人哈哈大笑，樓裡的笑聲比雨聲還響。可這場雨來得凶，去得也快，一陣風捲地而來，沒多久就把那片黑雲吹得四散，天空重新亮了起來，陽光斜斜照在還沾著水珠的欄杆上，望湖樓下的湖面，雨後波平如鏡，映著天光，水天連成一片，乾淨得像什麼都沒發生過,連方才的雨聲都好像是聽別人講的故事。

子瞻看著眼前這一場暴雨的來去，心裡忽然覺得，這跟他這幾年的處境倒有幾分像，朝裡風雲一時翻得那麼凶，他被捲進黨爭裡，話說錯了幾句，一下子就被趕出了京城，可眼下這一刻，杭州的湖光山色又乾淨得彷彿什麼都沒發生。他趁著酒意還沒醒，提筆寫下：黑雲翻墨未遮山，白雨跳珠亂入船。卷地風來忽吹散，望湖樓下水如天。

這幾句寫的是眼前一場雨，寫的也是子瞻自己那幾年起落無常的心境。他把筆放下，跟朋友們碰了碰杯，笑說這雨來得比誰都乾脆,走得也比誰都痛快,倒是挺對他的脾氣。後來他的人生還會遇上更大的風浪，烏台詩案、貶謫黃州，一場接一場，比這場雨凶險得多，可望湖樓下那片雨後平靜如鏡的湖水，始終是他留給自己、也留給後人的一個提醒，再大的烏雲，終究會被風吹散,水面終究會亮起來。`
  },

  // id=403 北宋 王安石 〈登飛來峯〉rating=3
  // 詩眼：一個尚未當宰相的年輕縣官，站在塔頂告訴自己不怕浮雲擋路，這句誓言他日後真正用一生兌現
  // 隱藏連接：此詩寫在他日後推行熙寧變法、面對滿朝反對仍堅持己見的二十年前，可視為他政治性格的預告
  403: {
    title: "登飛來峯",
    author: "王安石",
    summary: "他站在飛來峰塔頂說不怕浮雲遮眼——二十年後真正當上宰相推行變法，面對滿朝罵聲，他還是那句話。",
    story: `跟你說我朋友介甫二十九歲那年的一個清晨。他在飛來峰腳下站了很久，遲遲沒往上爬。

那年他剛做完鄞縣知縣，任滿要回京城述職。路過杭州，聽人說靈隱寺旁的飛來峰上有座千尋塔，天沒亮爬上去，雞一叫就能看見太陽從雲海裡冒出來。他一個人半夜出發，摸黑走山路，就是想趕在天亮前站到塔頂。

介甫在鄞縣這幾年，其實過得不太順心。他修水利、貸糧給農民度荒、整頓縣裡的教育，一件一件都做了，可上頭要嘛不理，要嘛嫌他多事。他還試著把官倉裡的糧食借給缺種子的人家，約定秋收之後還一點利息，比找地主借高利貸划算得多。這個小小的嘗試效果不錯，可他寄回朝廷的公文，換來的多半只是一句知悉，沒有更多迴響。同輩的人不是都升了官，就是安於現狀混日子。他常常覺得自己說的話，被一層看不見的東西擋住，傳不到該聽見的人耳裡。

寺裡一個老和尚跟他講飛來峰的傳說——這座山原本不在這裡，據說是從天竺飛過來的，落在靈隱寺旁邊。介甫問他，既然是飛來的，會不會有一天又飛走。老和尚只是笑了笑，說山會不會飛他不知道，但天亮以前爬上去的人，都看得見同一個太陽。介甫聽完沒再說話，繼續往上爬。

天快亮的時候，他終於站到塔頂。腳下的雲一層一層鋪開，把山腰、把整座杭州城都蓋住了。他往下看，什麼都看不清，剛才走過的路、寺裡的鐘聲，全部隔在雲層底下。可是他抬起頭，太陽正從雲海邊緣升起來，金色的光把塔頂照得透亮。他站在雲的上面。

那一刻他忽然想通一件事：不是雲太厚，是他站得不夠高。只要站得夠高，任何雲都擋不住他往前看的視線。他把剛才聽和尚說的話、還有這一路摸黑爬上來的心境，一起寫進詩裡：飛來山上千尋塔，聞說雞鳴見日升。不畏浮雲遮望眼，只緣身在最高層。

寫完他自己也沒把這首詩當多大回事，只當是登山留念，隨手夾進行囊裡。他不知道，二十年後他真的站上了那個位置——當上宰相，推行新法，朝野罵他是拗相公，說他倒行逆施。反對的聲浪一年比一年大，像那天山腰的雲一樣厚。可他從沒退。他後來提過天變不足畏、人言不足恤，跟這首年輕時寫的詩，其實是同一句話換了個說法。

介甫晚年被罷相，退隱江寧。有人問他後不後悔，他沒直接回答，只說起了年輕時登過的一座塔——雲很厚，但站得夠高，就看得見太陽。`
  },

  // id=404 北宋 王安石 〈元日〉rating=3
  // 詩眼：一個剛推行新法飽受爭議的宰相，親手把自家門口的舊桃符換成新的，那個動作裡藏著他變法的全部信念
  // 隱藏連接：換桃符本是驅邪舊俗，他卻寫成了自己除舊布新變法理念的自白
  404: {
    title: "元日",
    author: "王安石",
    summary: "他在自家門口換桃符的除夕夜，寫下的不只是新年風俗，是他正在做的整場變法。",
    story: `跟你說我朋友介甫熙寧年間過的一個新年。那天他親自站在自家大門口，把舊的桃符摘下來，換上一塊新的。旁邊的人都覺得奇怪——這種事向來是僕人做的，宰相何必自己動手。家裡的老僕原本打算按往年慣例，一早替他換好，他卻擺手說這件小事，今年他自己來做。

那年他剛推行新法沒多久。青苗法、募役法、農田水利法，一條一條頒布下去，朝廷裡罵聲不斷。有人說他變亂祖宗成法，有人在背後喊他拗相公，連他一手提拔的官員裡，也有人陽奉陰違。他早年在鄞縣試辦過的貸糧小法子，如今放大成青苗法推行全國，支持跟反對的人吵得不可開交。他每天上朝，都像在逆著風走。

除夕那天，汴京城裡爆竹聲從天黑響到半夜，一家接一家，連綿不絕，把舊的一年炸得七零八落。介甫坐在屋裡喝著屠蘇酒——這酒是除夕特有的，據說喝了能辟邪解毒，一年不生病。他喝完，起身走到院子裡。

新年第一天的太陽照進千家萬戶的窗子，家家門口都貼著新桃符——那是用桃木刻的驅邪符，除夕夜家家戶戶都要把舊的換掉，換上新刻的一塊，求來年平安。介甫看著自家門口那塊已經斑駁的舊符，伸手把它摘下來，掂了掂手裡這塊新的，木頭還帶著剛刨過的香氣。

他站在門口想了一會兒。舊符跟著這家人已經一年了，舊的，不代表沒有用過，但它擋不住新一年的邪祟——就跟他現在在做的事一樣。舊的法令、舊的制度，跟著這個朝廷已經上百年了，不是說它從來沒有用過，可是時代變了，再用舊的東西去擋新的問題，擋不住。

他把新的桃符掛上去，退後兩步看了一眼，才寫下這首詩：爆竹聲中一歲除，春風送暖入屠蘇。千門萬戶曈曈日，總把新桃換舊符。

寫完他把筆放下，笑了一下。他知道朝廷裡那些罵他的聲音，明天太陽升起還是會繼續罵。但門口的桃符已經換了，新的一年，總要有新的東西去擋新的風雨。

介甫晚年兩次被罷相，新法最後被推翻大半。可是這首寫在新年早晨的詩，一千年後還被人讀著——每年新春，家家貼春聯的時候，總有人想起那句總把新桃換舊符，未必知道背後那個站在門口、一個人跟時代較勁的宰相。`
  },

  // id=410 明 文徵明 〈拜年〉rating=3
  // 詩眼：一個看穿人情虛偽的文人，還是乖乖跟著大家投了名帖——因為看穿和抵抗是兩件不一樣的事
  // 隱藏連接：無
  410: {
    title: "拜年",
    author: "文徵明",
    summary: "他看穿了新年投帖拜年有多虛偽，卻還是隨手裁了一疊，跟大家一起送了出去。",
    story: `跟你說我朋友徵仲過年的一個上午。他書桌上疊著一小堆裁好的名紙，鄰居家的僕人剛把主人的名帖送到，他還沒回，案頭已經又多了兩張。

徵仲是蘇州出了名的才子，字寫得好，畫也畫得好，年紀越大，登門求字的人越多。按理說，這麼一個名滿江南的人，新年應該不缺人上門拜訪、坐下來喝一杯茶，說幾句真心話。可蘇州城的新年不是這麼過的。這座城裡的士紳人家，新年頭幾天誰也不見誰，只讓僕人拿著一張寫了名字的紙，送到對方門口，算是拜過年了。名紙上的字不能隨便寫，照規矩要親筆簽名，字跡馬虎還會被人在背後笑話不懂禮數。徵仲的字向來漂亮，這反倒讓他每次寫名紙時更為難——字寫得越工整好看，襯得紙上那句應酬話越空。

那天一早，徵仲的僕人前腳剛把主人家的名帖送出去，後腳鄰居的僕人就把回帖送進來，兩人在門口交錯而過，誰也沒進誰家的門。徵仲坐在窗邊看著這一幕，笑不出來，也氣不起來。他這些年見得太多了——有的人名帖送得比誰都勤快，遇到真事卻躲得比誰都快；有的人一年到頭沒見過面，新年一張紙就算把交情續上了。

他案頭堆著的，是別人送來的名紙，滿滿一疊，幾乎堆到了他這間簡陋書房的門邊。他認得幾個名字，大多其實一年也說不上一句話。僕人問他要不要一併回帖，他點頭，順口說了一句，這些人明年還是會照樣送，我們也照樣收。他提起筆，想寫幾句諷刺的話，寫到一半又停下——他自己不也一樣嗎？他也讓僕人裁好了一批名紙，一戶一戶送出去，跟大家做的事沒有兩樣。

他想清楚了一件事：他看得穿這件事有多虛，但看得穿，不代表他能不做。這座城裡的人情，靠的就是這一張張薄紙撐著，誰也不敢先停下來，怕被當成不懂規矩、不合群的人。硬要跟世俗較勁，吃虧的只有自己。

他把筆重新蘸墨，寫下這四句：不求見面惟通謁，名紙朝來滿敝廬。我亦隨人投數紙，世情嫌簡不嫌虛。

寫完，他喊來僕人，把自己那疊名紙分派出去，跟著鄰里一起把這場沒有人臉的新年禮數走完。窗外爆竹聲斷斷續續，案頭的名紙又添了幾張，徵仲的字，依然是全城最好看的那種，可是紙上的話，跟誰寫的都一樣空。`
  },

  // id=420 盛唐 李白 〈雙燕離〉rating=3
  // 詩眼：一輩子躲禍，躲到哪裡厄運就跟到哪裡——最後只剩她一個人，還在想著死去的伴侶
  // 隱藏連接：相傳寫於他晚年因永王事件流放夜郎的顛沛歲月，借古題寄託自己躲不掉的災禍
  420: {
    title: "雙燕離",
    author: "李白",
    summary: "一對燕子躲過一場火，又躲進另一場火裡——李白寫到最後，忽然說這事也讓我心痛。",
    story: `跟你說我朋友太白某次趕路時，在一片燒過的屋樑廢墟裡，看到一隻孤零零的燕子繞著空巢打轉。牠不飛遠，就守在那根燒黑的梁上，叫聲又急又啞。

那年他已經不是意氣風發的翰林待詔了。永王璡起兵失敗，他被牽連下獄，好不容易保住一條命，判的是流放夜郎，要往幾千里外的西南走。沿路多的是戰亂留下的殘破村落，燒毀的屋舍，斷牆邊常常看得到燕巢的碎片掉在地上。有人說他就是在這樣一段路上，想起了漢代流傳下來的一個樂府舊題——雙燕離，才借題發揮寫下這首詩；也有人認為這是他年輕時練筆仿古之作，具體寫在哪一年，史書沒有確切記載，兩種說法都有人主張。

不管哪個時候寫的，他借的這對燕子，命運寫得極慘。牠們原本住在玉樓珠閣，金窗繡戶，雙宿雙飛，羨煞旁人——巢築在漢武帝當年造的柏梁台上，那是長安城裡數一數二氣派的地方，梁柱用香柏木蓋成，燕子選在這裡築巢，等於住進了皇城最好的地段。誰知道柏梁台後來一場大火燒成灰，燕子拖著幼雛倉皇逃到吳王宮，以為總算安頓下來，結果吳宮後來也燒了一場大火，這次連雛燕都沒能救出來，一整窩孩子跟著巢一起沒了。

太白寫到這裡，筆下的母燕形單影隻，守在燒毀的梁架間，反覆想著已經死去的老伴。曾經雙飛雙宿，如今再也湊不成一對。他寫著寫著，忽然把自己也擺進了詩裡——前面十句都是第三人稱，寫燕子的遭遇，寫到最後，他忍不住開口：

雙燕復雙燕，雙飛令人羨。玉樓珠閣不獨棲，金窗繡戶長相見。柏梁失火去，因入吳王宮。吳宮又焚蕩，雛盡巢亦空。憔悴一身在，孀雌憶故雄。雙飛難再得，傷我寸心中。

這最後一句跳出來的我，才是這首詩真正的重量。他這一輩子換過太多次屋簷——年輕時想靠從政施展抱負，一路碰壁；晚年卷進一場政治賭局，差點連命都丟了，好不容易留住性命，又要被送到幾千里外的荒地去。他好像也是那隻不斷從一場火裡，逃到另一座還沒燒起來的屋簷下的燕子，只是屋簷總有一天也會燒起來。

隊伍後來繼續往夜郎走。那隻守著空巢的燕子，他沒帶走，也沒再回頭看。可牠叫聲裡的那種不甘心，他記了很久——舊題材裡寫的是燕子，底下藏著的，是他自己。`
  },

  // id=426 晚唐 韋莊 〈菩薩蠻（其五）〉rating=3
  // 詩眼：一個漂泊半生、在異鄉漸漸老去的才子，隔著千山萬水想著一個不知道他仍在想她的人
  // 隱藏連接：相傳他青年時在洛陽曾與一女子相戀，後來她被前蜀王建強行奪走，韋莊後來卻入蜀做了王建的宰相，天天面對此人
  426: {
    title: "菩薩蠻（其五）",
    author: "韋莊",
    summary: "他站在魏王堤看鴛鴦戲水，想的卻是一個他這輩子都要不回來的人。",
    story: `跟你說我朋友端己在洛陽城外堤岸邊站到天色轉暗的一個下午。柳樹的影子把整條魏王堤都染暗了，他卻還沒有要走的意思。

端己這輩子最不缺的就是離開一個地方的經驗。他年輕時碰上黃巢之亂，長安、洛陽一帶兵荒馬亂，他跟著逃難的人流四處流離，親眼看過的慘狀後來寫進了他那首著名的長詩秦婦吟裡。那幾年他沒有一天不在想，什麼時候能安頓下來。

洛陽算是他年輕時待過比較久的地方。城裡春天的風光確實好，魏王堤兩岸種滿柳樹，一到春天柳色濃得像化不開的墨。相傳他當年在這座城裡，認識過一個他很在意的人——後來的事沒有正史記載清楚，只流傳一種說法：那個人後來被前蜀的王建看上，強行收進了宮裡，端己這輩子都沒能把人要回來。更諷刺的是，端己後來輾轉入蜀，還當上了王建的宰相，天天上朝面對的，正是相傳奪走他心上人的那個人，這件事他從沒在人前提過一句。這段往事真假難考，但端己晚年寫的一組菩薩蠻詞裡，反覆出現的那種欲言又止的怨，確實很難只用懷才不遇四個字解釋。

這天他又站到了魏王堤上。柳色暗得快要看不清枝條，他人到中年，論才氣，洛陽城裡沒幾個能跟他比，可他已經在外鄉漂泊了太多年，一年比一年更覺得自己老了。眼前的春光跟他年輕時看到的一樣好，可站在這片景色裡的人，已經不是當年那個人了。

他往堤下的河面看，桃花落在水裡，一群鴛鴦正成雙成對地在水面上戲水，一點也不知道有人在旁邊看著牠們。端己看著看著，心裡那點迷惘忽然轉成了更深的東西——他想到的不是眼前的鴛鴦，是那個他惦記了很久、如今音訊全無的人。

夕陽這時候已經斜斜地掛在堤岸盡頭，顏色又紅又暗，像燒到最後一點的炭火。他站在殘暉裡，把心裡那點又酸又硬的東西壓下去，寫下這幾句：洛陽城裡春光好，洛陽才子他鄉老。柳暗魏王堤，此時心轉迷。桃花春水淥，水上鴛鴦浴。凝恨對殘暉，憶君君不知。

寫到最後那句，他停了很久。他知道就算寫了，那個人也不會知道，自己此刻正在千里之外的一道堤岸上想著她。可他還是寫了。堤上的柳影越拖越長，端己收起紙筆，往洛陽城裡走，背後的殘陽跟著他，一路沒有熄。`
  },

  // id=428 南唐 李煜 〈木蘭花·曉妝初了明肌雪〉rating=3
  // 詩眼：一整夜奢華的宮廷夜宴，連亭台名字都借用了亡國之君的舊物——盛世裡藏著自己都沒察覺的預兆
  // 隱藏連接：臨春閣借用南朝陳後主為寵妃所建的閣名，而陳朝正因這種荒淫誤國，李煜的南唐日後也走上同一條路
  428: {
    title: "木蘭花·曉妝初了明肌雪",
    author: "李煜",
    summary: "他讓宮女踩著月光送他回去，借用的閣名卻是一百年前那個亡國之君用過的。",
    story: `跟你說我朋友重光，南唐宮裡一個通宵沒讓誰睡好的夜晚。天都快亮了，春殿裡的宮女還在一個接一個地排隊，妝才剛畫完，臉上的脂粉在燈下亮得像雪。

那些年重光還沒有嚐過什麼叫真正的苦。他繼位當南唐國主，底下的臣子知道打不過北邊的宋，能做的只是修修文書、拖延時間、盡量讓國庫裡的錢多撐一年。重光自己不太過問這些，他更擅長的是填詞、寫字、辦這種通宵的宮宴。

那晚的宴設在臨春閣。這座閣子的名字不是重光取的，借用的是一百多年前南朝陳後主給他寵妃張麗華蓋的那座名閣——同一個名字，同一種奢華排場。那位陳後主後來夜夜歌舞，把整個陳朝都玩沒了，隋兵打進建康城那一晚，他跟張麗華一起躲進一口井裡，最後被人從井裡拉出來，成了千古笑話裡的亡國之君。重光大概沒細想過這段舊事，只覺得臨春這個名字風雅氣派，配得上眼前的排場。

笙簫的聲音一路吹到雲霄邊，樂工重新演起了霓裳曲——那原是唐玄宗年間流傳下來的宮廷樂，如今在南唐的宮殿裡被重新按著調子唱了一整遍，一字不漏，歌聲遍徹整座宮殿。宮女魚貫排列，妝容一個比一個精細，有些人特地換了新調的香粉，就是想讓自己那陣香氣飄得比別人更遠，好讓國主多看一眼。

重光喝到半醉，起身走到闌干邊，伸手拍著欄杆的節拍，跟著曲子哼唸，那種情味濃到快要溢出來。他這一晚看見的，是自己國都裡最好的一切——最美的女子、最好的樂工、最盛大的排場，一樣都不缺。

夜深了，有人提議點起紅燭送他回寢殿。重光卻擺手，說了一句讓侍從都愣住的話——歸時休放燭光紅，待踏馬蹄清夜月。他不要紅燭，他想踩著月光，慢慢走回去。他寫下這一整夜：曉妝初了明肌雪，春殿嬪娥魚貫列。笙簫吹斷水雲間，重按霓裳歌遍徹。臨春誰更飄香屑，醉拍闌干情味切。歸時休放燭光紅，待踏馬蹄清夜月。

十幾年後，南唐真的被宋兵攻破，重光被押去汴京當了三年俘虜，才死在異鄉。那座臨春閣早就燒沒了，那晚的月光卻還留在這首詞裡——他借了一個亡國之君用過的閣名，自己也走上了同一條路，寫詞的時候，他一點都不知道。`
  },

  // id=429 南唐 李煜 〈菩薩蠻·花明月暗籠輕霧〉rating=3
  // 詩眼：一個國主躲開生病的妻子，半夜赤腳提鞋去見妻子的妹妹，兩人都清楚這有多冒險，卻還是抖著腿去了
  // 隱藏連接：相傳寫的是李煜與大周后之妹（後來的小周后）在大周后臥病期間的秘密戀情
  429: {
    title: "菩薩蠻·花明月暗籠輕霧",
    author: "李煜",
    summary: "她脫了鞋提在手上，踩過冰涼的石階去見他——這一晚，決定了她後半生的位置。",
    story: `跟你說我朋友重光年輕時一個提著鞋、赤著腳走路的晚上。他站在畫堂南邊的陰影裡等人，手心全是汗，其實他自己也說不清楚，這一晚到底在怕什麼。

那時候他的正妻娥皇——史書上稱大周后，正臥病在宮裡。娥皇是南唐宮裡少有的才女，通曉音律，還幫忙整理過失傳已久的霓裳羽衣曲殘譜，早年跟重光琴瑟和鳴，感情極好。她病重之後，常常是妹妹進宮陪她、照顧她，姊妹倆年紀差了十幾歲，妹妹入宮時還是個孩子，這些年一天天長大，出落得越來越有姊姊當年的風采。相傳這位妹妹——後來的小周后——就是在這段陪病的時間裡，跟重光漸漸生出了不該有的情意。史書沒有把細節寫清楚，只留下這麼一個輪廓，但南唐宮裡確實流傳過這樣的閒話。

那晚花色在月光下顯得特別亮，月亮本身卻躲進一層薄霧裡，看不真切。宮裡巡夜的侍衛每隔一段時間就會提著燈籠走過長廊，腳步聲和燈光都容易驚動人。妹妹決定要見他。她從自己住的院子出來，怕鞋跟聲驚動巡夜的人，索性脫了鞋，只穿著襪子，一步一步走過冰涼的石階，手裡緊緊提著那雙繡了金縷的鞋。

重光在畫堂南邊看見她的身影，兩人都沒說什麼多餘的話。她一走近，整個人就靠進他懷裡，抖得厲害——不是冷，是怕。她怕被人看見，怕姊姊知道，怕這件事一旦傳出去，誰都保不住她的名聲。

她低聲跟他說，自己出來一次有多難，要躲過幾層人的眼睛，才能挪到這裡。她說完這句，把自己更往他懷裡靠，意思很清楚：這樣的機會不多，今晚你想怎麼樣都隨你。

重光後來把這一夜寫成了詞，用的是她的口吻，一句一句像是她自己在說話：花明月暗籠輕霧，今宵好向郎邊去。剗襪步香階，手提金縷鞋。畫堂南畔見，一向偎人顫。奴為出來難，教君恣意憐。

娥皇沒能撐過那場病，幾年後就去世了。重光後來正式把她妹妹立為皇后，就是後來跟他一起被押往汴京、一起熬過亡國歲月的小周后。那個提著鞋走過冰涼石階的晚上，成了兩人一輩子糾纏的開端——史書留了懸念，這首詞卻把當晚的心跳，原封不動地留了下來。`
  },

  // id=439 北宋 蘇軾 〈西江月-平山堂〉rating=3
  // 詩眼：十年後重回恩師蓋的亭子，看見牆上恩師的字還在飛舞，人卻已經不在了
  // 隱藏連接：歐陽脩科考時誤將蘇軾文章當成自己門生所寫，刻意壓低名次避嫌，後來感嘆再過三十年沒人記得自己只記得蘇軾
  439: {
    title: "西江月-平山堂",
    author: "蘇軾",
    summary: "他第三次站到恩師蓋的亭子前，牆上的字還在，寫字的人已經走了十年。",
    story: `跟你說我朋友子瞻第三次走到平山堂下的那個下午。他抬頭看向堂上牆壁，恩師留下的字跡還在那裡，筆勢像龍像蛇一樣往上飛揚，可寫字的人已經死了十年。

平山堂是歐陽脩蓋的。二十一歲那年，子瞻進京考試，主考官正是歐陽脩。子瞻那篇文章寫得又快又好，歐陽脩看了愛不釋手，一度以為是自己得意門生曾鞏所寫，為了避嫌，故意把這篇文章的名次往下壓了一等，才沒讓它拿到第一。等真相揭開，發現作者是個誰都不認識的年輕人蘇軾，歐陽脩不但沒有惱，反而私下跟人說了一句話——這後生可畏，再過三十年，恐怕沒人記得我，只記得他。

子瞻後來一直把歐陽脩當老師看，雖然兩人年紀差了將近三十歲，見面次數也不算多，但這份提攜的情分，他一輩子沒忘。歐陽脩晚年在揚州做太守時蓋了這座平山堂，堂前種滿楊柳，常常在這裡宴客、寫詞，其中一首楊柳詞流傳很廣，揚州當地的歌女還在唱。

子瞻這一輩子先後路過平山堂三次。第一次是年輕時，跟著恩師的名聲來瞻仰一下這座亭子；第二次是中年，恩師已經過世，他心裡帶著沒能常伴老師身邊的遺憾又來了一趟。這一次，是第十年了。

他站在堂前，想起自己這半生——考中進士、外放做官、捲進烏台詩案、被貶到黃州、又輾轉調動，一路顛沛，快得像手指彈一下那麼快。回頭一看，十年、二十年，說沒就沒了。他抬頭看牆上歐陽脩留下的墨跡，那筆走龍蛇的字，還跟活著時一樣有精神，仿佛下一刻主人就會走進來，坐到那張常坐的椅子上。

堂外歌女還在唱著恩師當年寫的那首楊柳詞，曲調沒變，唱的人卻已經換過好幾輪。子瞻站在那裡，一時竟分不清自己是來悼念，還是來聽一首老歌。他提筆寫下：三過平山堂下，半生彈指聲中。十年不見老仙翁，壁上龍蛇飛動。欲弔文章太守，仍歌楊柳春風。休言萬事轉頭空，未轉頭時皆夢。

他寫完最後一句時想通了一件事——不必等到回頭才驚覺一切成空，因為人活著的每一刻，站在那一刻裡看，本來就跟夢一樣輕。堂前的楊柳被風吹得沙沙響，跟歐陽脩當年聽到的，該是同一種聲音。`
  },

  // id=442 北宋 歐陽修 〈蝶戀花-庭院深深深幾許〉rating=3
  // 詩眼：一個被困在深宅裡，連所愛之人去哪裡都看不到的女子，問花，花也不回答她
  // 隱藏連接：此詞作者歸屬歐陽脩與馮延巳有爭議；一百多年後李清照特別喜愛庭院深深深幾許一句，仿寫多首
  442: {
    title: "蝶戀花-庭院深深深幾許",
    author: "歐陽修",
    summary: "她問花，花不回答——這句一百多年後，被另一個困在深院裡的女子李清照，連寫了好幾首詞去回應。",
    story: `跟你說我朋友永叔寫過一首詞，題目底下藏著一個問題，連他自己可能都答不上來——這院子究竟有多深。

這首蝶戀花，後世有人說是永叔寫的，也有人考證說更像是五代詞人馮延巳的舊作，兩種說法爭了好幾百年，誰也沒能徹底說服誰。這篇故事，姑且照多數版本，當作永叔筆下的一位女子來講。

她住的院子，一層院牆接著一層院牆，誰也數不清究竟隔了幾重。院裡種著楊柳，柳枝密得像堆起來的一層煙，再往外是數不清的簾幕，一層又一層地把院子跟外面的世界隔開。她每天能看見的，就是這些簾子跟柳煙，再遠一點，什麼都看不見。貼身的丫鬟常勸她別老站在窗邊看，看久了也不會多看見什麼，她卻總是不聽，還是天天站在那裡。

她的丈夫，騎著鑲玉的馬勒、坐著雕花的馬鞍，經常往外跑，去的地方是章臺路那一帶——那是漢代長安城裡出了名的花街，後來變成所有文人筆下風流去處的代稱。她站在自家的樓上，想看清丈夫到底去了哪裡，可樓再高，也看不到章臺路那頭。她能守住的，只有這座越蓋越深的院子。

三月快要過完的一個黃昏，風突然狠了起來，雨也跟著橫著下，把院裡最後幾枝殘花都打落了。她讓人把院門關上，天一黑，連光都不進來了。她心裡清楚，春天留不住了——不是她不想留，是她根本沒有辦法留。

她站在庭院裡，看著滿地被雨打落的花瓣，忍不住紅著眼問那些花，問她們知不知道春天去哪了，花卻一句話都答不上來。一陣風過來，把那些殘紅捲起來，吹過院子裡那座她小時候還會盪一盪的鞦韆，飄得到處都是。

永叔把這一幕寫成了詞：庭院深深深幾許，楊柳堆煙，簾幕無重數。玉勒雕鞍遊冶處，樓高不見章臺路。雨橫風狂三月暮，門掩黃昏，無計留春住。淚眼問花花不語，亂紅飛過鞦韆去。

這首詞後來被一個女子讀到，愛得不得了。那是一百多年後的李清照，她特別喜歡庭院深深深幾許這一句，連著寫了幾首詞，句句都拿這句開頭。她從沒見過永叔，也未必知道這詞的作者其實有爭議，但那一句，穿過一百多年，還是找到了跟她一樣被困在深院裡的另一個人。`
  },

  // id=452 南宋 李清照 〈鳳凰臺上憶吹簫·香冷金猊〉rating=3
  // 詩眼：明明知道千萬遍陽關曲都留不住他，她還是一遍一遍唱——不是想留住人，是想把心意親手交到他手上
  // 隱藏連接：無
  452: {
    title: "鳳凰臺上憶吹簫·香冷金猊",
    author: "李清照",
    summary: "她起床懶得梳頭，梳妝盒積了灰——這是李清照送丈夫遠行前，連自己都沒察覺的深情證據。",
    story: `跟你說我朋友易安一個早晨賴床沒起的故事。太陽已經爬到窗簾鉤子那麼高了，她還躺在翻亂的被子裡，一點都不想起來梳頭。

平常的她不是這樣的人。她跟丈夫趙明誠感情極好，兩人一起收書、一起考訂金石碑刻、一起窮盡家財買古董字畫，常常為了一件真跡樂上大半天，日子過得又清貧又充實。她的梳妝台平時打理得整整齊齊，那天卻積了一層灰，她連看都不想看一眼。

因為趙明誠這次要出遠門了。相傳是要去外地任職，一去又是好一段時日。屋裡的香爐早就冷了，昨夜的香燒完之後她沒讓人再添，起床之後也懶得梳頭——不是沒力氣，是心裡堆著太多話，堵在那裡，怎麼梳都梳不順。

她心裡怕的不是丈夫走這一趟本身，是離別要來的那種疼——她想跟他多說點什麼，話到嘴邊又一次次吞回去，說了又能改變什麼呢。旁人這些日子見她瘦了不少，都猜是不是喝多了酒，或是秋天到了心情不好。她自己知道，都不是。跟酒沒關係，跟秋天也沒關係，是心裡那件事，一天天把她耗瘦的。

她想起送別時唱的陽關曲，一句一句唱，唱一遍是留，唱十遍也是留，可唱到一千遍、一萬遍，人終究還是要走。她乾脆不唱了。她想到丈夫這一走，人會像傳說裡誤入桃源又離去的武陵人一樣，越走越遠；她自己則像被鎖進雲霧裡的秦樓，哪裡都去不了，只能守著這座樓，等。

她起身走到樓前，看著樓下那條流水，忽然覺得，這世上大概只有這條水記得她這時候的樣子——她天天站在這裡，眼睛望向同一個方向，望到最後，那個望著的地方，又添上了一段新的愁。她把這一切寫進詞裡：香冷金猊，被翻紅浪，起來慵自梳頭，任寶奩塵滿，日上簾鉤。生怕離懷別苦，多少事，欲說還休。新來瘦，非干病酒，不是悲秋。休休，這回去也，千萬遍陽關，也則難留。念武陵人遠，煙鎖秦樓。唯有樓前流水，應念我，終日凝眸，凝眸處，從今又添，一段新愁。

那年頭她大概沒想到，多年後丈夫真的病逝在外，她獨自帶著兩人一輩子收藏的金石書畫，在戰亂裡輾轉逃難，能護住多少是多少。這一次的離別，回頭看，其實已經是最溫柔的一次——至少那時，趙明誠還會回來。`
  },

  // id=461 南宋 唐婉 〈釵頭鳳-世情薄〉rating=3
  // 詩眼：被迫拆散多年後重逢，只能在牆上題詞回應，人前還要裝出笑臉，把眼淚往肚裡吞
  // 隱藏連接：陸游同一面沈園牆上題了釵頭鳳（紅酥手），唐婉的世情薄是隔著時間對他的回答
  461: {
    title: "釵頭鳳-世情薄",
    author: "唐婉",
    summary: "陸游在沈園牆上寫下紅酥手那一刻，她正巧路過，認出那個字跡——世情薄，人情惡，她只能用一首詞，回應一段早就被迫斬斷的婚姻。",
    story: `跟你說我朋友唐琬的一個下午，在沈園。她原本只是隨丈夫趙士程出來散心，卻在迴廊轉角撞見一個她認得太熟的字跡，陸游的字，寫在牆上。

她跟陸游是表親，也是他的第一個妻子。兩人青梅竹馬，感情好到近乎黏在一起。壞事就出在這裡，陸游的母親看不慣兒子整天圍著媳婦轉，怕耽誤他考功名，也有一說是嫌唐琬多年無子。理由眾說紛紜，史料沒留下確切答案，只知道結果很殘忍，婆婆一句話，兩人被迫和離。唐琬後來改嫁趙士程，陸游也另娶了王氏。

十年過去，誰都以為這件事早該淡了。那天在沈園，兩人卻真的迎面碰上。陸游看著她，一時什麼都說不出口，只在園牆上題了一首詞，開頭是紅酥手，黃縢酒，滿城春色宮牆柳。字跡她一眼就認出來。

唐琬站在牆前看了很久。她原本已經把日子過成另一個人的妻子，笑得體面，茶飯規矩，誰都看不出破綻。可是這幾行字一出現，那些收好的東西全被翻了出來。世情這麼薄，人情這麼惡，一句雨送黃昏花易落，她想起這些年過的到底是什麼日子。曉風把眼淚吹乾了，又落下新的，擦了又擦，擦不完。

她想寫點什麼回他，卻連好好坐下來寫封信的資格都沒有。獨自倚著欄杆，想把心事一條一條理清楚，理來理去只是難，難，難。這幾年她自己一個人扛下來的東西，他不會知道，也沒有人會問。

她病得不輕，常常覺得心像鞦韆一樣晃來晃去，穩不下來。城裡的號角聲在寒天裡格外冷，夜深了睡不著，又怕被人看出異狀。人前她照舊裝出高高興興的樣子，把眼淚往肚裡吞，笑臉往外掛。她提起筆，一口氣寫下：

世情薄，人情惡，雨送黃昏花易落。曉風乾，淚痕殘，欲箋心事，獨語斜闌。難難難。人成各，今非昨，病魂常似鞦韆索。角聲寒，夜闌珊，怕人尋問，咽淚裝歡。瞞瞞瞞。

她把詞也題在牆上，跟陸游那首隔著不遠。據說沒過多久，她就鬱鬱而終，具體是哪一年，史書沒寫清楚。陸游活到八十五歲，幾十年後重回沈園，還在寫詩念她。那面牆早就塌了，可是這兩首詞，一首問紅酥手，一首答瞞瞞瞞，隔著八百多年，還在同一個園子裡回話。`
  },

  // id=10 盛唐 張九齡 〈感遇四首之四〉rating=2
  // 詩眼：有德有才卻被層層阻隔，送不到懂得欣賞的人面前，只能耐著性子等
  // 隱藏連接：張九齡當年力主先除掉安祿山，玄宗不聽，多年後安史之亂爆發印證了他的擔心
  10: {
    title: "感遇四首之四",
    author: "張九齡",
    summary: "他是玄宗身邊少見肯講真話的宰相，被排擠出朝廷後，望著院子裡一棵耐寒的橘樹，寫下自己一輩子送不出去的忠心。",
    story: `跟你說我朋友子壽被貶到荊州那幾年的心事。他寫這組感遇詩的時候，人已經不在長安，是被李林甫排擠出朝廷，掛個荊州長史的閒職，遠遠看著朝政一步步走向他最擔心的方向。

子壽早年在朝裡做到宰相，是玄宗身邊少見肯講真話的人。他出身嶺南，一路考科舉、寫文章闖出名聲，靠的全是自己的本事，不是誰家的門蔭。這樣的人講話向來直，不太懂得拐彎。開元末年，一個叫安祿山的胡將犯了軍法，依律當斬，張九齡簽了死刑令，玄宗卻大手一揮免了他的死罪，還誇這人將來有用。子壽當場勸阻，說這人臉相不善，將來必是禍害，不殺留著遲早後悔。玄宗沒聽，放了安祿山一條命。子壽自己後來也被李林甫一步步擠出權力中心，先降職，再外放，最後貶到地方去。

荊州的冬天，他常常盯著院子裡那棵丹橘。江南這一帶橘樹，經過整個冬天照樣是一片綠，別的樹早枯了，它偏偏耐得住寒。子壽心裡清楚，這不是地氣暖，橘樹本來就長著一顆耐得住歲寒的心，跟人的骨氣一樣，不是外頭環境給的，是自己長出來的。

這麼好的橘子，本該摘下來送去給宴席上的貴客嚐嚐，可是山高水深，一層一層的阻隔，橘子就是送不出去。他想到自己這些年在朝裡的處境，也是同一個道理，有本事有忠心，偏偏被小人跟距離擋在半路，誰都嚐不到你的好。

命運這種東西，不過是碰上了什麼人、遇上了什麼時候，一圈一圈轉，誰也說不清為什麼。他看著滿樹橘子，提筆寫下這幾句：

江南有丹橘，經冬猶綠林。豈伊地氣暖，自有歲寒心。可以薦嘉客，奈何阻重深。運命惟所遇，循環不可尋。

寫到最後兩句，他想起長安城裡那些種桃種李的人，人人搶著誇桃李好看好吃，卻沒人問過，這棵橘樹難道就沒有一片能遮蔭的葉子嗎，徒言樹桃李，此木豈無蔭。

十幾年後，安祿山真的反了，把整個大唐拖進戰亂，玄宗倉皇逃出長安，途中想起子壽當年那句提醒，只能對著空氣感嘆一句，悔不聽卿言，還特地派人去嶺南祭拜他的墳。子壽那時已經過世好幾年，沒能看見自己說中的這一切，也沒能等到那份遲來的懊悔當面說給他聽。可是荊州院子裡那棵橘樹，耐得住每一年的寒冬，不聲不響地綠著，替他把這口氣一直嚥到了後來，直到有人終於想起，這棵樹其實從沒讓誰失望過。`
  },

  // id=15 盛唐 李白 〈子夜四時歌（春歌）〉rating=2
  // 詩眼：一個沒有靠山的女子，用手裡的活計、該負的責任，硬氣地把有權有勢的人擋回去
  // 隱藏連接：李白一輩子拒絕對權貴低頭，重寫羅敷的故事其實是借她的嘴說出自己那句安能摧眉折腰事權貴
  15: {
    title: "子夜四時歌（春歌）",
    author: "李白",
    summary: "五匹馬的官員車駕停下來想多看她兩眼，採桑女羅敷連客氣都省了，直接說蠶餓著，大人您請讓路。",
    story: `跟你說我朋友太白寫這首春歌的時候，腦子裡想的是一個幾百年前的老故事。故事的主角叫羅敷，採桑女，漢朝樂府裡就有她，陌上桑那個羅敷。故事裡她長得極美，有一天在路邊採桑，一個路過的太守看上她，停下五匹馬拉的車，想搭訕。羅敷不理他，還編了一堆理由把自己丈夫誇得天花亂墜，把太守擋了回去。

太白很喜歡這個故事，他自己就是個不肯對權貴低頭的人。年輕時他被人請去見權貴，對方態度隨便了些，他轉頭就走，連飯都沒吃完。後來寫夢遊天姥吟留別，他直接說安能摧眉折腰事權貴，使我不得開心顏，這句話幾乎是他一輩子的座右銘。他這輩子寫過不少借古人故事說自己心事的樂府詩，子夜四時歌就是這一類，春夏秋冬各寫一首，借的都是舊題材，填的都是他自己的想法。他重寫羅敷這個故事的時候，心裡想的大概就是這股氣。

他把場景搬到秦地，春天，綠水邊。羅敷跟平常一樣去採桑葉，一身素手伸進青綠的桑條裡，身上那件紅妝，在太陽底下鮮豔得很。這畫面本身沒什麼稀奇，採桑女幹活天天如此。但太白要寫的不是她多美，是接下來這一刻，遠處來了一隊五匹馬的車駕，官員模樣，顯然是路過還想多看兩眼、多留一會兒的那種人。

蠶正餓著。這才是整首詩的關鍵。羅敷手裡的桑葉是要餵蠶的，蠶一天不吃葉子就會死，耽誤不得。她沒有跟這位大人客氣寒暄，沒有半分討好的意思，直接把話挑明，她要走了，蠶等著呢，大人您就別留她了。

蠶飢妾欲去，五馬莫留連。

這八個字看起來平淡，分量卻不小。一個沒有名分、沒有靠山的採桑女子，面對五匹馬代表的權勢，沒有低頭，也沒有虛與委蛇，只用她自己手裡的活計、她該負的責任，把對方擋回去。這不是撒嬌拒絕，是她清清楚楚知道自己在做什麼，誰也別想耽誤。

太白寫完這首，大概自己也笑了。他這輩子見過太多攀附權貴的人，也見過太多因為一句好聽話就飄了的人，能守住自己那一點分寸的反而少。他偏偏喜歡這種不假辭色的硬氣，哪怕主角只是個採桑女，分量一點不比朝堂上的硬話輕。羅敷用蠶擋住了五匹馬，他用他的筆，擋住了一輩子想讓他低頭的人。這首短短二十四個字的春歌，寫的是幾百年前的採桑女，其實也是他自己心裡那句沒說出口的話，借一個他從沒見過面的古代女子，把自己的骨氣又講了一遍。`
  },

  // id=16 盛唐 李白 〈子夜四時歌（夏歌）〉rating=2
  // 詩眼：她急著趕回去的家，其實是她再也回不去自己的起點
  // 隱藏連接：西施急著划船回去的越王家，後來把她訓練成送去吳國的美人計，這趟歸家路是她命運的轉折點
  16: {
    title: "子夜四時歌（夏歌）",
    author: "李白",
    summary: "她那天傍晚沒等月亮升起就急著划船回家，不知道這一趟回去，等著她的是被送去敵國、再也回不來的命運。",
    story: `跟你說我朋友太白寫夏歌時候想的那個女孩，西施。故事發生在會稽附近的鏡湖，方圓三百里，夏天荷花開得滿湖都是，菡萏一朶接一朶。五月裡，西施照樣跟其他村女一樣下水採荷。

她那時候還只是個浣紗女，在若耶溪邊長大，誰也沒把她當成什麼了不起的人物。可是她長得太好看，只要她出現在水邊，岸上就會擠滿人。這一次採荷，若耶溪兩岸擠得水泄不通，擠到路都快堵住了，人看隘若耶，這個隘字用得很準，不是熱鬧，是真的擠到動不了。

太白沒有直接寫她的容貌，他寫的是這種擁擠本身，讓讀的人自己去想像，到底是什麼樣的人，能讓整條溪岸擠得像過節一樣。

天色漸漸晚了，別的採荷女大概都想等月亮出來，趁著月色多留一會兒，看看湖面上倒映的荷花。西施沒有。她划著船，不等月亮升起，就往回趕。歸去越王家，這五個字看起來平淡，只是說她要回越王的地方去，可是熟悉這段歷史的人讀到這裡，心裡都會一沉。

越國那時候剛被吳國打得幾乎滅國，勾踐忍辱求和，回國後臥薪嚐膽，天天睡在柴草上，吃飯前先嚐一口苦膽，提醒自己別忘了這口氣，一直在找機會報仇。大臣范蠡奉命在民間訪查美人，四處打聽，終於在若耶溪邊找到了西施，把她帶回宮裡，教她宮廷禮儀跟歌舞，足足訓練了好幾年，準備把她送去吳國，用美色拖垮夫差，替越國換來反攻的機會。西施這一趟急著回去的家，不是終點，是起點，起點通往的地方，是她再也回不來的吳宮。

她那天傍晚急急划船回去，心裡想的可能只是家常的事，或許是家裡有事等她，或許只是單純想回家。她不會知道，這一趟回去，越王家的人已經在等她，等著把她訓練成一件要送出去的東西，從此她再也不是若耶溪邊那個採荷的女孩。

太白寫到這裡就停了，連歸去之後發生什麼都沒多說一個字。回舟不待月，歸去越王家。八個字，收得乾乾淨淨，可是每一個知道西施後來命運的人，讀完都會愣一下，她那麼急著回家，而那個家，後來變成她再也回不去的地方的入口。若干年後吳國真的被越國滅了，西施本人的下場，史書眾說紛紜，有人說她隨范蠡歸隱，有人說她被越王夫人賜死，誰也說不準哪個版本才是真的。太白沒有替她安排結局，只把鏡頭停在那個匆匆划船的黃昏，讓後人自己去想，一個女孩最後一次以浣紗女的身分回家，是什麼心情。`
  },

  // id=29 盛唐 王維 〈青谿〉rating=2
  // 詩眼：路過姜太公垂釣求仕的磻溪一帶，他卻只想單純釣魚，不想被誰發現、被誰請去做官
  // 隱藏連接：磻溪是姜太公釣魚等文王賞識的地方，王維在附近的青谿卻寫下完全相反的心願
  29: {
    title: "青谿",
    author: "王維",
    summary: "姜太公在磻溪釣魚，等的是周文王把他請去輔佐天下。王維路過同一帶溪水，寫下的卻是他只想留下來釣魚，誰都別來找他。",
    story: `跟你說我朋友摩詰路過青谿的一個下午。他當時大概是奉命出使或赴任途中，路線正好經過陝西這條溪，叫黃花川附近的青谿。這條溪水量不大，順著山勢彎彎繞繞，走了不到百里路，水聲卻一路熟悉得很。

王維年輕時候就以詩畫聞名長安，也做過官，大理寺、監察御史，一路走的是仕途正軌。可是他心裡一直有另一半，跟他母親崔氏有關，崔氏信佛三十多年，拜的是普寂禪師，家裡從小就是這種清淡持齋的氣氛，王維自己也常年參禪，寫詩作畫多半帶著空山、寂靜這一路的味道，晚年更把長安近郊的輞川別業直接改成半座寺院。半官半隱，是他一輩子的狀態，人在朝裡當差，心卻常常掛在山水間。

這條青谿他走過就知道，水聲在亂石堆裡吵得很喧鬧，可是流進松林深處，顏色又沉靜下來，一點聲音都沒有。水面上漂著菱角跟荇菜，隨著水波晃來晃去，岸邊的蘆葦倒映在清澄的水裡，連影子都看得清清楚楚。

走到這裡，他忽然想起這附近有個地名，叫磻溪。傳說姜太公當年就是在磻溪邊上垂釣，故意用直鉤釣魚，釣了幾十年，等的不是魚，是周文王有一天經過，發現他，把他請去輔佐周室，成就了後來的功業。這是天下讀書人都知道的典故，垂釣其實是等一個機會被賞識。

王維卻不想等這個機會。他心裡已經很平靜，清澄的溪水映著他此刻的心境，恰好對得上。他不想像姜太公那樣，把釣竿當成敲門磚，等哪個大人物路過賞識他，把他帶去做更大的官。他只想找一塊盤石坐下來，真的釣魚，不為別的，就是留在這裡，不走了。

我心素已閒，清川澹如此。請留盤石上，垂釣將已矣。

這幾句寫完，他自己心裡清楚，這不是一時興起的感嘆，是他一輩子在官場跟山林之間拉扯出來的答案。姜太公用釣竿換來了一整個西周的江山，王維卻寧願用同一個姿勢，換一個誰都不打擾他的下午。同樣是垂釣，一個人釣的是天下，一個人釣的，只是安靜，只是這一刻不必再往前趕路的自由。他後來果然大半輩子都在做這件事，一邊在朝裡領著俸祿當差，一邊把輞川的別業修成半座禪院，退朝回去就換上便服，坐在自己的院子裡，跟這條青谿當年給他的那份平靜，一次一次地重逢。`
  },

  // id=33 盛唐 孟浩然 〈夏日南亭懷辛大〉rating=2
  // 詩眼：想彈琴給知音聽卻等不到人來，把想念一路想到夢裡去
  // 隱藏連接：伯牙絕弦的典故——孟浩然自比伯牙，把辛大當成他唯一等的鍾子期
  33: {
    title: "夏日南亭懷辛大",
    author: "孟浩然",
    summary: "他伸手拿起琴，想彈一曲，卻在琴弦前停住——這附近沒有一個懂他的人，只好把想念一路想進了夢裡。",
    story: `跟你說我朋友浩然一個夏天的傍晚。他住在襄陽城外的南亭，天快黑的時候，山邊的日光忽然一下子就沉下去了，池塘上頭那顆月亮跟著慢慢爬上東邊。他把頭髮解開來，不梳不束，乘著晚上的涼氣，推開窗子，往竹床上一躺，四肢攤得很開，一點拘束都沒有。

浩然這輩子沒做過官。他年輕時隱居鹿門山，四十歲才第一次動身去長安考功名，結果落第，見過張九齡、王維這些朝裡的大人物，兩人都很欣賞他的詩才，王維甚至私下引他入宮，想找機會讓玄宗見他一面。相傳那次玄宗真的來了，浩然躲在床下不敢出來，王維老實回報，玄宗倒也沒生氣，叫他出來問有沒有新作，他一緊張唸了一句不才明主棄，玄宗聽了不高興，說你自己不想做官，又怎麼能怪我棄用你，這事就這麼黃了。真假難以考證，但他終身沒有做官，倒是真的。他心裡未必真的甘於平淡，只是一輩子都在等一個真正懂他的人，官場的門他敲過，卻始終沒真的走進去。

這個晚上，荷花的香氣被風一陣一陣送過來，竹葉上的露水滴在葉子上，發出清脆的聲響，安靜到這種細微的聲音都聽得一清二楚。他心裡忽然癢了一下，想起屋裡那把琴，伸手想拿起來彈一曲。

手都伸到琴上了，他又停下來。彈給誰聽呢。這附近沒有一個真正懂音律的人。就像當年俞伯牙在江邊彈琴，只有樵夫鍾子期一個人聽得懂他琴聲裡的高山流水，子期死後，伯牙從此絕弦，再也不彈，因為知音難得，彈給不懂的人聽，跟對牛彈琴沒兩樣。浩然想到這裡，那份想彈琴的興頭，一下子涼了下來。

恨無知音賞。他把琴放回原處，心裡卻沒有真的平靜下來。他想起一個人，辛大，他這輩子少數幾個能說得上話的朋友。這個晚上山光沉了，月亮升了，荷花香跟竹露聲都在，獨獨少了一個能一起坐下來聽琴的人。

感此懷故人，中宵勞夢想。他索性也不硬睡了，躺在竹床上，心思一路飄向辛大那邊，飄到半夜還沒停。這首詩寫的不是什麼大道理，就是一個等不到知音的夏夜，一個人翻來覆去，把想念一路想到夢裡去，直到天邊那顆月亮爬過了半個天空，他還沒睡著。他這一輩子沒等到玄宗的賞識，倒是等到了不少像辛大這樣真心相待的朋友，官場沒有他的位置，朋友之間的惦念反倒從沒斷過。`
  },

  // id=39 中唐 綦毋潛 〈春泛若耶溪〉rating=2
  // 詩眼：順水漂流沒有目的地，只想放下功名，變成一個安靜持竿的老人
  // 隱藏連接：無明確史料佐證的生平細節，誠實用相傳處理；若耶溪同時也是西施浣紗的傳說之地
  39: {
    title: "春泛若耶溪",
    author: "綦毋潛",
    summary: "他把船槳放下，讓船自己順水漂，心裡想的不是要漂到哪裡，是能不能就這樣一路漂成一個什麼都不求的持竿老人。",
    story: `跟你說我朋友季通，綦毋潛字季通，一個春天夜裡在若耶溪上划船的心事。這條溪在會稽附近，古時候還有個傳說，西施小時候就在這溪邊浣紗。溪水一路蜿蜒，兩岸開滿野花，常有隱士跟漁夫往來。

綦毋潛這個人的生平，史書留下的不多，只知道他是荊南人，開元年間中過進士，做過幾任小官，像是校書郎、右拾遺這類清閒的文職，官不算小，但也談不上顯貴。後來辭官歸隱，晚年究竟去了哪裡，史料語焉不詳，相傳他跟王維、儲光羲這些人交情不錯，王維還寫過送別詩給他，詩裡誇他心地清淨，舉止有隱士的風骨。他考中功名之後也沒有真的一路往上爬，倒像是一直在仕跟隱之間搖擺，這首詩大概就是寫在他還沒下定決心徹底歸隱前的某個春夜。

那天晚上，他划著船順水而下，心裡那股想要遁世的念頭一直沒斷過。他不特別選路，就這樣隨著水勢漂，漂到哪裡算哪裡。晚風把船吹得晃晃悠悠，往前推，兩岸開滿了花，花瓣落進水裡，一路跟著船漂進溪口。

天色漸漸黑透，船轉進一道西邊的深谷，抬頭隔著山頭，還能望見南斗星掛在天上。水面上升起一層薰薰的煙霧，溶溶地飄著，林梢的月亮低低垂著，船一過，月光就被甩到船後頭去。

這一路的景色，他看得很入神，心裡卻也漸漸浮出一個念頭，眼下的日子，說起來也是一團瀰漫沒個頭緒的樣子，考了功名又能怎樣，官場裡的事，誰也說不準哪一天風向就變了。不如就順著這條溪一路漂下去，學那個持竿的老人，什麼都不想，只管釣魚。

生事且瀰漫，願為持竿叟。

這兩句寫完，他把船槳放下，任船自己漂了一會兒。溪水靜靜地流，煙霧繼續往上飄，他不知道自己這輩子最後會不會真的變成那個持竿的老人，但至少這個晚上，他是真心這麼想的。若耶溪千百年來送走過浣紗的西施，也送走過無數個像他這樣，想要放下一切的讀書人，水一直在流，誰都只是暫時借住在它岸邊，漂過一段，就換下一個人接著漂。後來他確實辭官歸隱，史書沒說他去了哪座山，只留下這一船在春夜裡漂過的水痕，證明他這句願為持竿叟，不是隨口說說。`
  },

  // id=45 中唐 韋應物 〈寄全椒山中道士〉rating=2
  // 詩眼：曾是橫行街市的紈褲侍衛，如今卻惦記著一個素未謀面的清苦道士朋友，想送酒卻連他的行蹤都找不到
  // 隱藏連接：韋應物少年時是玄宗身邊驕縱的三衛侍從，安史之亂後家道敗落、性情大變，轉為清簡勤政的地方官
  45: {
    title: "寄全椒山中道士",
    author: "韋應物",
    summary: "外頭風雨交加，他想拎一瓢酒上山陪山裡的道士朋友喝一杯，卻發現滿山落葉蓋住了所有的路，連去哪裡找人都不知道。",
    story: `跟你說我朋友韋應物當滁州刺史那年冬天的一個念頭。他早年完全不是這種溫和性子。十五歲起就在宮裡當玄宗的三衛侍從，仗著身分橫行長安街市，鬥雞走馬，誰都不放在眼裡，史書上寫他年少的時候是個不學無術的紈褲子弟。安史之亂一來，長安淪陷，玄宗倉皇出逃，他失去了靠山，家道跟著敗落。這場亂世像一把刀，把他年輕時候的驕縱一刀削掉，削出一個完全不一樣的人，他開始認真讀書，後來一路做到地方官，治理滁州、蘇州，以清簡勤政聞名。

那個冬天的早上，官署裡冷得很。他一個人坐在郡齋，忽然想起全椒縣山裡那個道士朋友。這人隱居在山中，平日的日子過得極簡單，到山澤底下撿些荊棵當柴燒，回來就用來煮白石當飯吃。這個煮白石的說法，相傳出自古代仙人黃初平的故事，道士修煉的人常拿石頭當糧，吃了據說能延年。韋應物不確定這位朋友是不是真信這套，但他知道對方過得清苦，是真的。

他心裡越想越不安。外頭正在下著風雨，天氣壞得很，官署裡雖然生著炭火，他卻怎麼都想著山裡那間破屋子，漏不漏雨，道士有沒有夠厚的衣裳擋寒。他想拎一瓢酒，親自走一趟山裡，送去給這位朋友，權當在這樣的天氣裡陪他喝一杯，暖一暖身子。這個念頭很具體，幾乎已經在腦子裡走完那條上山的路，連要繞過哪一段溪流都想好了。

欲持一瓢酒，遠慰風雨夕。

可是這句話一寫下來，他自己也遲疑了。這位道士居無定所，行蹤本來就是隱士的特性，今天在這片山，明天可能又換了一處。他就算真的提著酒上山去，滿山落葉，把整座空山蓋得密密實實，連一條路的痕跡都認不出來，他要去哪裡找人。

落葉滿空山，何處尋行跡。

這兩句寫完，韋應物把筆放下，酒也沒有真的送出去。他這輩子從一個橫行街市的紈褲少爺，變成一個惦記著山裡朋友冷不冷、餓不餓的地方官，中間隔的是一整場改朝換代的亂世，是他親眼看著長安城破、皇帝出逃、自己家道中落的那幾年。他找不到那條上山的路，可是這份惦記本身，已經是他跟從前那個自己，徹底不一樣的證明。當年那個鬥雞走馬的少年，絕不會為了一個窮道士的冷暖，坐在冷冰冰的官署裡想上大半個早晨。這封信最後也沒真的送出去，倒是留下來，成了他這輩子最溫柔的一頁，比他年輕時任何一場鬥雞賭馬都更接近他後來真正想成為的樣子。`
  },

  // id=81 盛唐 王維 〈桃源行〉rating=2
  // 詩眼：找到了一個沒有戰亂、沒有朝代更迭的地方，離開之後拚命想再回去，卻永遠找不到那條路
  // 隱藏連接：故事原型是陶淵明寫在晉宋亂世交替時的桃花源記，王維十九歲在盛世重寫，卻原樣保留了那份逃離亂世的恐懼
  81: {
    title: "桃源行",
    author: "王維",
    summary: "漁夫好不容易找到一個幾百年沒經歷過戰亂的村子，離開後卻怎麼也找不到回去的路——他以為自己記得路，山谷卻早已不是原來的樣子。",
    story: `跟你說我朋友摩詰十九歲寫的一首長詩。他那時候還很年輕，已經是長安小有名氣的才子，琴棋書畫樣樣拿得出手。他重寫的這個故事，原型是陶淵明的桃花源記，那是三百多年前，晉朝快要亡、天下大亂的時候，陶淵明寫的一個寓言。

陶淵明寫的漁夫，划船順著水路一直往前走，兩岸桃花開得漫山遍野，看得入神，忘了自己走了多遠。船繼續往前，溪水越走越窄，眼看就要到頭，他還是不甘心，繼續往前走。

山口忽然開了一條窄縫，他鑽進去，走了一陣，眼前豁然開闊，平地展開來。遠遠望去，一片雲霧籠罩著聚在一起的樹林，走近一看，家家戶戶種著花竹，錯落有致。這裡的人，自稱是秦朝人的後代，為了躲避戰亂逃進山裡，幾百年下來，連漢朝都不知道有沒有存在過，身上穿的還是秦朝的衣服款式。

漁夫這個外來的客人一出現，整村人都驚動了，爭著把他請回自己家裡，問他外頭的世道。月光下松樹底下的屋子安安靜靜，日出時雲霧裡雞犬的叫聲此起彼落，一村子人過著陶淵明想像中最理想的日子，沒有稅賦，沒有戰亂，沒有一個朝代換過另一個朝代的血腥。第二天清早，村裡的巷子已經有人把落花掃開；傍晚時分，打漁砍柴的人才踏著水路陸續回來，日子過得像沒有時間流動一樣規律又安穩。

這村子的人當年為了躲亂世逃進來，一逃就是幾百年，再也沒想過要出去。可是這個漁夫不一樣，他心裡那份對故鄉的牽掛始終沒斷過，住了幾天，還是決定要出去看看外頭的世界。

出洞無論隔山水，辭家終擬長游衍。他一心想著，等外頭事情辦完，一定要再回來看看。可是等他真的想要重新回到這個地方，問題來了，自謂經過舊不迷，安知峰壑今來變。他以為記得路，山谷卻好像變了樣。

當時只記入山深，青溪幾曲到雲林。春來遍是桃花水，不辨仙源何處尋。

王維寫到這裡收筆。他十九歲，活在開元年間國力鼎盛的大唐，離陶淵明那場亂世已經隔了幾百年，可是他一字未改地保留了那份最原始的恐懼，這個世界上曾經真的有一個不會被戰爭、朝代、時間傷到的地方，而你一旦離開，就再也找不回去了。`
  },

  // id=108 初唐 沈佺期 〈雜詩〉rating=2
  // 詩眼：同一輪月亮，一半照著閨房裡的妻子，一半照著邊疆的軍營，戰爭把兩個人的思念活生生分成兩種形狀
  // 隱藏連接：沈佺期後來因宮廷醜聞被貶到嶺南極邊之地，與家人分隔多年，活成了自己詩裡那個等待的角色
  108: {
    title: "雜詩",
    author: "沈佺期",
    summary: "同一輪月亮，今晚照進她的閨房，明晚照進他的軍營——她的思念是今天一整個白天的心事，他的思念卻是昨夜早已過去的更深。",
    story: `跟你說我朋友沈佺期寫這首雜詩的時候，還在朝裡當官，是武后跟中宗兩朝有名的宮廷詩人，文筆好，官運也還算順。他寫這首詩，借的是一個閨中少婦的口氣，說的是邊疆打了太多年還沒打完的戰事。

聽說黃龍戍那邊，連著好幾年都沒能撤兵。黃龍是東北邊境上的一個軍鎮，唐朝跟東北方勢力拉鋸，戰事一年拖過一年，誰也說不準什麼時候能結束。前線的士兵一去，少則一年半載，多則好幾年回不了家，家裡等著的人，只能靠書信斷斷續續知道一點消息，更多時候什麼都不知道，只能對著一輪月亮猜他現在究竟是死是活、吃得飽不飽。

詩裡這位少婦，獨守著閨房，能陪她的只有一輪月亮。可憐閨裡月，長在漢家營。這輪月亮很妙，它不偏心誰，今晚照進她的窗子，明晚一樣照進丈夫駐紮的軍營。同一個月光，把兩個相隔幾千里的人，各自留在各自的黑夜裡，誰也碰不到誰。

少婦今春意，良人昨夜情。這一句更細，她的思念是今天春天裡，一整個白天堆出來的心事，他的思念是昨天晚上，在軍營帳子裡，一個人躺著翻來覆去想的那些話。時間點都對不上，一個是春天的日子，一個是昨夜的更深，中間隔著千里路跟好幾天的時差，連思念都沒法同步，一個人的白天，對上另一個人早已過去的黑夜。

沈佺期自己那時候還在長安做京官，寫這種邊塞閨怨詩，是當時宮廷詩人常見的題材，借別人的口說戰爭跟離別。他未必想過，自己有一天也會嚐到這種滋味，後來他捲入張易之一案，被貶到嶺南極南邊的驩州，那地方比黃龍戍更遠，一去經年，跟家人天各一方，信一封要走上好幾個月才能收到。

詩的最後，他借少婦的口，問出所有等著的人心裡都想問的一句話，誰能將旗鼓，一為取龍城。誰能真的帶兵打下龍城，把這場仗徹底結束，讓所有分開的人都回家。

這首詩寫在他自己還沒被貶謫之前，寫的是別人的離散。等他自己真正嚐到千里流放的滋味，才知道當年那句誰能將旗鼓，問的不只是少婦，也是他自己後來的人生，一個當年替別人寫思念的人，終究也活成了詩裡那個等信、等人、等一場仗打完的角色。同一輪月亮，他年輕時借它寫過別人的等待，老年時，它又照著他自己在驩州的夜裡，數著日子等一封從長安遲遲寄不到的家書。`
  },

  // id=121 盛唐 杜甫 〈奉濟驛重送嚴公四韻〉rating=2
  // 詩眼：「幾時杯重把」隨口一問的離別客套，最終沒能兌現
  // 隱藏連接：三年後嚴武暴卒，杜甫從此離開成都走向人生最後的漂泊，最終死在湘江舟中，呼應這場送別裡沒說出口的預感
  121: {
    title: "奉濟驛重送嚴公四韻",
    author: "杜甫",
    summary: "送別時隨口問的一句幾時杯重把，杜甫終其一生都沒等到答案。",
    story: `跟你說我朋友子美的一次送別，其實是同一場送別的第二回。

寶應元年七月，綿州城外的奉濟驛。子美已經送過嚴武一次了，從成都一路送到綿州，照理說該分手了，可他捨不得，又跟著送到驛站，送了第二次。

嚴武是他在成都最重要的靠山。當年子美帶著一家老小逃難到成都，一無所有，是嚴武把他當自己人看，常邀他去幕府喝酒，兩人在草堂前的月光下對飲，聊詩聊政聊天下事，一聊就到半夜。嚴武待他不只是客氣，還時常派人送米糧布帛過去，草堂那幾間茅屋能修得起，屋外那幾株桃樹能種得成，多半都靠這份接濟。子美這輩子官場潦倒，考不上什麼像樣的功名，一路顛沛流離，唯獨這幾年因為有嚴武，日子過得像個人。

現在嚴武被召回長安當京兆尹，一路升遷，前途大好。子美替他高興，可心裡空了一塊。嚴武這一路走過的郡縣，百姓聽說他要離開，紛紛出來唱歌相送，捨不得這個治理有方的節度使；嚴武本人歷經三朝天子重用，這一走是真正的榮耀加身。子美看著眼前的青山，覺得它此刻空有一片深情，卻誰都留不住人。

驛站前兩人又對飲一杯。子美忽然開口問：幾時杯重把？昨夜月同行。他是隨口一問，就像所有離別時說的那種話，約好了下次再喝，好像下次一定會有。他們昨夜確實在同一片月光下走了一段路，此刻卻要往兩個方向去了。

嚴武沒能給出確切答案，只說有機會一定再聚。子美獨自轉身，往江邊那個叫做草堂的小村子走回去，心裡想著往後大概只能一個人，在江村裡度過剩下寂寞的歲月。

他猜對了一半，卻猜錯了另一半。不久後成都發生徐知道之亂，兵荒馬亂之中，子美帶著家人倉皇逃出成都，在梓州、閬州一帶輾轉流離了將近兩年，日子過得比先前更苦。三年後，嚴武竟又回鎮成都，一回來就把子美接回幕府，安頓下一個檢校工部員外郎的虛職，後人稱他杜工部，就是從這裡來的。那段日子子美又能安心寫詩、安心喝酒了，兩人常在府裡對坐，好像那杯終於要重新舉起來了。可惜好日子沒撐多久，永泰元年嚴武暴卒，年僅四十歲。子美再也沒能等到那句幾時杯重把兌現。他離開成都，沿江東下，一路漂泊到夔州、江陵、岳陽，這一路寫下不少晚年最沉的詩句，直到死在湘江上的一條小船裡，那杯酒始終沒有重新舉起來。`
  },

  // id=124 盛唐 杜甫 〈登岳陽樓〉rating=2
  // 詩眼：眼前洞庭湖浩大無邊，自己卻只剩一條孤舟、一身老病
  // 隱藏連接：與奉濟驛送別的預感呼應：嚴武死後杜甫沿江漂泊多年才抵達岳陽，兩年後真的死在附近湘江的小船上
  124: {
    title: "登岳陽樓",
    author: "杜甫",
    summary: "他一輩子沒到過的洞庭湖，終於站上岳陽樓那天，卻只剩一條孤舟能陪他。",
    story: `跟你說我朋友子美晚年最後幾年的一個下午。他終於站上了岳陽樓，望著洞庭湖，那一年他五十七歲，離死只剩兩年。

年輕時他就聽過洞庭水的名氣，聽人形容那片水浩瀚得像沒有邊，心裡一直記著，總想著哪天親自去看一眼。他一直沒機會親眼去看，這些年他忙著逃難、忙著在成都靠嚴武接濟過活、忙著在嚴武死後離開那座讓他安心的草堂，一路往下漂。嚴武走了以後，再沒有誰能給他一個安穩的地方，他只能沿長江一路東下，經過嘉州、戎州、渝州、雲安，最後在夔州停了兩年，寫下不少感慨深重的詩句，身子卻也在那兩年裡越拖越垮。後來他終於又拖著病體出峽，一站一站地往南漂，像被水流帶著走，沒有方向，只剩眼前這條船知道下一站在哪裡。

大曆三年，他總算撐著病體出了三峽，經過江陵、公安，一路又漂了大半年，冬天總算到了岳陽，終於站到了這座樓上。眼前的景象把他嚇著了，吳地和楚地在東南方硬生生被這片水撕開一道裂縫，天地日夜都浮在水面上晃動，大得不像人間該有的景色，跟他這些年見過的所有江河湖泊都不一樣。可他一低頭，看看自己：親戚朋友一個字的音信都沒有，又老又病，身邊只有一條孤零零的小船，那就是他全部的家。

那種對比讓他站在樓上愣了很久。眼前的湖那麼大，浪一波一波地拍過來，好像要把整座樓都吞進去；他的世界卻小到只剩一條船，船上連個能說話的人都少。他這輩子寫過長安的繁華、寫過成都的春雨、寫過夔州的猿聲，也算見過不少大風大浪，可這一刻他忽然覺得，自己什麼都沒有了，功名沒有、田產沒有、連個能安身的家都沒有，只剩下這雙眼睛還能看，這口氣還能喘。

他又想到北方。那裡還在打仗，吐蕃還在侵擾，朝廷還在動盪，年輕時經歷過的那場安史之亂彷彿還沒真正結束，換了個地方繼續打。他這輩子最惦記的家國，始終沒能安穩過一天，連他自己也跟著漂了大半輩子。他趴著窗欄，眼淚就這麼流下來，寫下：親朋無一字，老病有孤舟。戎馬關山北，憑軒涕泗流。

沒有人扶他，沒有人陪他看這片水。兩年後，他真的死在了離這裡不遠的湘江一條小船上，跟詩裡寫的一模一樣，一個人，一條船，直到最後。`
  },

  // id=126 盛唐 王維 〈輞川閒居贈裴秀才迪〉rating=2
  // 詩眼：身居高位卻在柴門外等一個醉朋友狂歌而來，是亦官亦隱的心境
  // 隱藏連接：裴迪是王維晚年最重要的忘年之交，兩人合寫輞川集二十首唱和詩
  126: {
    title: "輞川閒居贈裴秀才迪",
    author: "王維",
    summary: "一邊在朝廷做大官，一邊在柴門外等朋友醉著唱歌回來，這就是王維的隱居方式。",
    story: `跟你說我朋友摩詰一個秋天傍晚的等待。他在輞川的柴門外，撐著拐杖站了很久，就為了等一個人喝醉了跑來找他。

摩詰這些年在長安做官，官越做越大，可他偏偏在藍田買了一處叫輞川的別業，把大把時間耗在山裡。這處別業原本是前朝一個文人留下的舊宅，他買下後又添了亭台、鑿了池塘，一到假期就往那兒跑。有人不懂，覺得他既然放不下官位，何必裝隱士，何必兩頭都占。可摩詰心裡有自己的算法：白天在朝廷是右丞王維，得寫奏疏、得應付人事，晚上在輞川是那個只關心秋水潺潺、寒山轉翠的閒人，兩個身分他都不打算放棄，也不覺得矛盾。

那年秋天，寒山一點一點轉成蒼翠色，山下的秋水日日潺潺流著。他站在柴門外，靠著拐杖，聽著傍晚的蟬聲一聲接一聲地叫，竟聽得入神。渡口那邊太陽快落下去了，只剩一點餘光灑在水面；遠處村落的炊煙一縷一縷地升起來，不急不慢的樣子，他看著看著，心裡也跟著靜下來。

真正讓這個傍晚變得不一樣的，是裴迪來了。這個年輕朋友是他晚年最要好的忘年交，兩人常常一起在輞川各處走，走到孟城口、華子岡、鹿柴這些地方就停下來，一路唱和寫詩，後來湊成了整整二十首的輞川集，一來一往，各自寫各自看到的景，倒也不覺得誰輸誰贏。裴迪這天大概是在別處喝多了，一路狂歌著走過來，那股放浪的勁頭，讓摩詰忽然想起楚國那個裝瘋拒官的接輿，同樣是在人前敢唱敢鬧，不管旁人怎麼看。

摩詰看著眼前這個醉醺醺唱著歌走來的年輕人，先是笑，笑完又有點羨慕，覺得自己這處柴門，竟也像陶淵明門前種的那五棵柳樹，一個隱士該有的樣子。他提筆寫下：復值接輿醉，狂歌五柳前。

他自己沒有醉，也沒有真的狂歌，他只是站在門口看著，笑了。他知道自己不是陶淵明，他還要回長安，還要上朝，還有官要做。可只要輞川還有這扇柴門，還有裴迪偶爾醉著跑來的這種黃昏，他這顆心就有個地方可以放。暮蟬還在叫，炊煙還在升，他轉身進門，把這個秋天的傍晚，收進了自己往後半生都能回來躲一躲的角落裡。`
  },

  // id=129 盛唐 王維 〈終南山〉rating=2
  // 詩眼：終南捷徑盛行的年代，他進山不為表演，只為讓自己真的迷路一次，體會渺小
  // 隱藏連接：終南山是當時假隱士博取徵召的舞台，王維進山的態度卻是真心的謙卑求助
  129: {
    title: "終南山",
    author: "王維",
    summary: "別人進終南山是為了被朝廷看見，他進山只是想找一次機會，向一個樵夫問路。",
    story: `跟你說我朋友摩詰一次故意讓自己迷路的登山。

終南山那時候名聲很怪，長安城裡一堆人跑去山裡搭個草棚，擺出隱士的樣子，粗茶淡飯撐個幾個月，就等著名聲傳到宮裡，皇帝派人來徵召，一徵召就順勢做官，朝廷裡都笑稱這叫終南捷徑。摩詰知道這套把戲，他身邊不少同僚年輕時都玩過這一招，可他自己是正經考上進士、一步步升上來的，他這天進山，不是去演給誰看的，山裡也沒人會認出他。他就是想找個下午，什麼身分都不帶，讓自己真的渺小一次。

終南山離長安不算遠，古名太乙，離皇城很近，可它連綿起伏，一路能接到很遠的海邊，這是山民口中的誇張說法，摩詰卻覺得站在山腳往上看，這話不算誇張。他往山裡走，回頭望，白雲在身後一層層合攏起來，把剛才走過的路都遮住了。再往前看，眼前那層青灰色的霧氣，他一走近，卻什麼都沒有，霧散得比他腳步還快。

山中的地勢變化讓他吃驚。同一座山，主峰這邊和那邊竟分屬不同的地界，翻過一道山脊，方言口音都變了；陰晴天氣也各不相同，這邊下著雨，那邊說不定還晴著，雲在山谷裡飄來飄去，一會兒把太陽遮住，一會兒又露出來。摩詰走著走著，看得入迷，竟沒注意天色漸漸暗下來，他這才發現自己走得比預想中遠，該找個地方投宿了，卻完全認不出方向，連自己是從哪個坡走上來的都想不起來。

他站在一條溪水邊，四周靜得只有水聲。往常在朝中，他習慣了自己拿主意，習慣了別人來問他。可這一刻，他什麼都不懂，只能隔著水，朝對岸一個正在砍柴的樵夫喊了一聲，問哪裡可以借宿。

欲投人處宿，隔水問樵夫。他把這一句寫下來時，心裡其實挺踏實的，一個每天在官場裡被人求教、被人恭敬對待的人，難得能這樣低下頭，隔著一條溪水，扯著嗓子問一個素不相識的人一句簡單的路，對方隨口指了指方向，他連謝都沒好好道完，樵夫已經扛著柴繼續走了。終南山那麼大，大到能讓他真的迷路，也大到能讓他借著一次迷路，重新記起自己有多小——那種感覺，他後來想起來，竟覺得比在朝堂上被誰誇讚幾句還要踏實。`
  },

  // id=131 盛唐 王維 〈過香積寺〉rating=2
  // 詩眼：連鐘聲從哪裡傳來都聽不出，卻正是這種迷失讓人能安坐下來，把心裡的躁動壓住
  // 隱藏連接：王維之名取自維摩詰經，一生與佛理相依，晚年常獨自焚香打坐
  131: {
    title: "過香積寺",
    author: "王維",
    summary: "他找不到寺廟的路，卻在深山裡的一片空潭邊，找到了安放自己的地方。",
    story: `跟你說我朋友摩詰一次找不到路的進香。他不知道香積寺到底在哪，只知道方向，一路走進雲霧繚繞的山峰裡，走了好幾里。

摩詰這個名字，本來就是從維摩詰經裡取來的，他自小跟佛教有緣，晚年更是常常一個人焚香打坐，把念經當成日常，家裡的僧衣、蒲團都備得齊齊整整。可打坐這件事，說來容易，真正坐得住的人不多，外頭的事一多，心裡那條毒龍就容易醒過來，翻騰得讓人坐立不安，就算閉著眼，腦子裡照樣跑馬燈似的轉個不停。他這天特意選了一處從沒去過的寺，聽人說寺名叫香積，卻沒人說得清具體怎麼走，他就想給自己找一塊真正安靜、誰都不認識他的地方。

古老的樹林裡沒有人走過的痕跡，樹幹粗得要兩人合抱，他一路穿林而入，連條正經的小徑都找不到，褲腳都被枯枝勾得破了幾道。深山裡傳來鐘聲，他聽得見，卻怎麼也判斷不出鐘是從哪個方向敲來的，一會兒像在左邊，一會兒又像在頭頂上，那種被聲音牽著走卻摸不著頭緒的感覺，反而讓他有點心安，像是暫時脫離了長安城裡那種什麼都得算清楚、想明白的日子。

泉水在陡峭的石頭縫裡擠著流，發出嗚嗚咽咽的聲響，像是被石頭卡著喉咽；陽光照進林子裡，被一片一片青翠的松樹擋住，落在地上都帶著涼意，不像外頭夏天那樣曬人，他走著走著，額頭上的汗都收了。他走到日頭快落下去的時候，眼前忽然開闊，一片空蕩蕩的潭水，水面靜得像鏡子，四周什麼人都沒有，連鳥叫聲都聽不太到了。

摩詰就在潭邊坐下來，也不管石頭涼不涼，直接盤腿坐了。他知道自己心裡那條毒龍這些年從沒真正安靜過，官場的進退、身邊人事的變化，都會時不時把它惹醒，有時半夜想起某件公事都能翻騰半天。他閉上眼，把呼吸放慢，一下一下地數著，試著把那條龍重新壓回去。他提筆在心裡默念下這一句：泉聲咽危石，日色冷青松。薄暮空潭曲，安禪制毒龍。

天黑透之前，他沒有起身。潭水沒有一點聲響，松林也安靜下來，連方才那道找不到方向的鐘聲都停了，只剩他一個人的呼吸聲。他就那樣坐著，像一個終於找到能安頓自己的人，把那條龍，一點一點哄睡著了。`
  },

  // id=133 盛唐 王維 〈漢江臨眺〉rating=2
  // 詩眼：眼前江山壯闊到城郭都像漂浮的小點，他卻想到的是幾百年前一個愛喝酒的太守
  // 隱藏連接：晉朝襄陽太守山簡好酒成癡，常醉倒被人拉回府中，王維借典故與這位古人共醉
  133: {
    title: "漢江臨眺",
    author: "王維",
    summary: "站在最高處看最壯闊的江山，王維想的卻是找個人一起喝到爛醉。",
    story: `跟你說我朋友摩詰一次站在高處卻想找酒喝的登臨。

那年他因公務經過襄陽一帶，一路舟車勞頓，好不容易得了半天空閒，順路登上高處眺望漢江。眼前的景象大到讓他一時說不出話，楚地的邊塞與三湘之地在遠方相接，荊門那邊九條支流全匯進這條江裡，江水浩浩蕩蕩，看起來簡直像是流出了天地之外；遠山忽隱忽現，有時候看得清輪廓，有時候又淡得像沒有山，隨著雲氣飄動，一整片山勢竟像會呼吸似的。

他站得越高，眼前的城郭看起來越小，那些郡縣城邑，竟像是漂浮在水面前方的小點，人來人往的街市在這個高度看下去，安靜得像沒發生過事情一樣；江上的波瀾起伏，連帶著遠處的天空都好像被震得晃動起來。摩詰從沒在別處見過這麼放得開的景色，比他在長安近郊看慣的那些溪流山丘大出了不知多少倍，連身邊隨行的幾個人都看得說不出話來，一時間竟覺得自己站得再高，也高不過眼前這片江山。

可就在這麼壯闊的時候，摩詰腦子裡冒出來的，卻是一個幾百年前的老太守。晉朝那會兒有個叫山簡的人，當過襄陽太守，是個出了名愛喝酒的官，常常在城郊習家池邊喝到爛醉，被下屬用車拉著，天天顛顛倒倒地送回府裡，清醒的時候沒幾回。當地百姓不但沒人告他失職，反而編了歌謠傳唱，人人都記得這個可愛的醉太守，比記得他判過什麼案子還清楚。摩詰望著眼前的襄陽城，忽然很想效仿他，找個像山簡那樣懂得縱情山水的老朋友，痛痛快快喝一場，把眼前這片壯闊的江山配著酒，一起吞進肚子裡。

他想到這裡，笑了笑，回頭問了一句隨從，這附近可還有像山簡那樣好客的人家，隨從答不上來，他也不強求答案，只是提筆寫下：襄陽好風日，留醉與山翁。

這句話與其說是寫給某個具體的人，不如說是他借著幾百年前那位醉太守，跟自己開的一個玩笑，眼前的風景這麼好，不喝上一場簡直浪費。他知道自己終究還要趕路，公務還等著他，馬車在山下等著，隨從也在催了，可這一刻，他就想學山簡那樣，由著自己醉一次，讓浩浩江山也沾一點酒氣，哪怕只有這麼一個下午，等回過神來再繼續趕路也不遲。`
  },

  // id=137 盛唐 孟浩然 〈與諸子登峴山〉rating=2
  // 詩眼：終身未仕的孟浩然，站在紀念一位名將的墮淚碑前，忽然懂了什麼叫值得被記住的活法
  // 隱藏連接：晉朝羊祜鎮守襄陽深得民心，死後百姓為他立碑，相傳讀碑者必落淚
  137: {
    title: "與諸子登峴山",
    author: "孟浩然",
    summary: "一塊讓所有人讀了都哭的石碑，讓考了一輩子科舉沒考上的孟浩然，懂了什麼才叫沒有白活。",
    story: `跟你說我朋友浩然一次登山讀碑，讀到哭出來的下午。

浩然是襄陽本地人，峴山他從小看到大，爬了不知道多少回。這天他跟幾個朋友又約著一起登山，原本沒打算特別做什麼，就是幾個人圖個熱鬧，走走看看。

爬到半山，他們停下來喝口水，順便看看腳下的風景。江邊那片叫魚梁的沙洲，水位低的時候露出淺淺的一片，能看見沙洲上幾隻水鳥低頭找食；遠處雲夢澤那一帶的天色陰沉，看起來水深得很，跟眼前這片淺灘正好是兩種樣子。浩然站在那兒，忽然想起自己站的這塊地，幾百年前也曾經站過一個人，晉朝的荊州都督羊祜。

羊祜當年鎮守襄陽，治軍嚴整又待百姓寬厚，深得民心，據說連對手陣營的人都敬重他，兩邊打仗歸打仗，私底下互通書信也不避諱。他常常在閒暇時登上這座峴山，眺望江漢一帶的風景，一站就是老半天。他死後，襄陽百姓感念他的恩德，就在他生前常來的地方立了一塊碑。相傳後來的人一讀到碑上記的事，想起羊祜這樣一個好官已經不在了，沒有一個不掉眼淚的，所以這塊碑後來被叫做墮淚碑。

浩然這天跟朋友一起走到碑前，把碑上的字讀完。他忽然想到，人來人往，一代換一代，今天站在這裡的自己，跟幾百年前站在這裡的羊祜，某種意義上沒什麼不同，都不過是這座山、這條江面前一個短暫經過的人。可羊祜留下了一塊碑，留下了讓後人還記得他的理由，而自己這輩子考了那麼多次科舉都沒考上，好像什麼都沒留下。

這個念頭讓他心裡一陣酸，眼淚就這麼掉下來。他沒有覺得自己丟臉，反而覺得這眼淚掉得值得，至少他懂了羊祜這塊碑真正打動人的地方，不是官做得多大，是活著的時候做了讓人記得的事。他把這份感觸寫下來：人事有代謝，往來成古今。江山留勝跡，我輩復登臨。水落魚梁淺，天寒夢澤深。羊公碑字在，讀罷淚沾襟。

朋友們後來陸續下山，浩然在碑前多站了一會兒。峴山還是那座峴山，江水還是那條江水，他知道自己這輩子大概不會有羊祜那樣的功業，可他至少懂得了，什麼樣的活法才配得上被後人記住。`
  },

  // id=138 盛唐 孟浩然 〈清明日宴梅道士房〉rating=2
  // 詩眼：本來臥病發愁春天要溜走，一個邀約卻讓他決定不再糾結留不住的東西，痛快喝一場
  // 隱藏連接：孟浩然體弱多病，對容顏易老格外敏感，這份渴望不是隨口客套
  138: {
    title: "清明日宴梅道士房",
    author: "孟浩然",
    summary: "發愁春天要走、自己在變老的那個下午，一封邀約把孟浩然拉進了一場神仙般的醉。",
    story: `跟你說我朋友浩然清明節那天，原本躺在家裡發愁的一個轉折。

那年清明，浩然身體又不太好，窩在家裡，看著窗外春天一天天要過去，心裡堵得很。他這些年身子一直弱，一年裡總有那麼幾段日子起不來床，這回又病了將近半個月，藥吃了幾回，人瘦了一圈。眼看著春光要溜走，自己卻只能躺著看它溜走，那種滋味不好受，尤其是聽見窗外有人說笑著出門賞花，自己卻連坐起來都嫌費力。

正悶著的時候，一個消息送到他家門口，他把這個消息形容得很有意思，說是像西王母派來的青鳥使者一樣，忽然飛來報信，聽起來比實際情況神氣多了。其實就是他的朋友梅道士派人來請他，說家裡備了酒，清明這天一起聚聚，別老悶在家裡養病。浩然一聽，心裡那塊悶氣一下子鬆開了，也顧不上身子還沒完全好，撐著就出門去了。

梅道士的住處，浩然形容得像神仙住的地方，他借用赤松子的名號，把這處道觀說成是自己被邀入了仙家。到了地方一看，梅道士剛把煉丹的爐子點上火，丹灶裡還冒著煙，滿院子都是一股藥草味；院子裡種的桃樹也巧，正趕上花開得最盛的時候，粉粉一片，襯著丹爐的煙氣，風一吹，花瓣落得滿地都是，真有點不像人間。

浩然坐下來喝了幾杯酒，看著滿院子的仙桃花，忽然生出一個念頭，如果人真能像傳說裡那樣，靠著這爐丹藥留住年輕的容顏，永遠不老下去，那該多好。他這些年身體一天不如一天，比誰都清楚老病是怎麼一點點找上門的，這個念頭對他來說不是玩笑話，是真心盤算過的渴望。

可他也清楚，丹藥能不能真的留住童顏，誰也說不準。既然說不準，那就別去糾結了，他索性舉起杯子，跟梅道士說，如果留不住這張臉，那就乾脆喝個痛快，把流霞美酒當仙丹喝下去。他寫下：童顏若可駐，何惜醉流霞。

那天他喝到很晚才回去，走路都有點打晃，是梅道士叫人扶著送他到門口的。出門前那種被春天要走、被病痛纏著的悶氣，到這會兒早就被酒氣沖散了。他知道自己終究會老，終究會走，這身子骨也未必能撐過幾個清明，可就是這一天，在梅道士的丹房裡，他好好地，痛快地，活成了一次神仙。`
  },

  // id=150 盛唐 岑參 〈寄左省杜拾遺〉rating=2
  // 詩眼：表面稱頌朝廷清明無過，實際暗指敢說真話的空間越來越窄
  // 隱藏連接：杜甫是岑參當時的同僚諍友，不久後真的因直言被貶離開長安
  150: {
    title: "寄左省杜拾遺",
    author: "岑參",
    summary: "一句聽起來像稱讚朝廷的詩，其實是岑參和杜甫兩個諫官之間，心知肚明的苦笑。",
    story: `跟你說我朋友嘉州年輕時，寫給杜甫的一首暗著諷刺的詩。

那幾年岑參在長安做右補闕，官職不大，卻是諫官，按理該替皇帝挑毛病，替百姓說話。他隔著宮牆，能看到左邊門下省那頭，坐著另一個諫官，左拾遺杜甫。兩人職位相近，一個屬中書省，一個屬門下省，說起來是分曹辦事，實際上常常一起進宮，一起在朝堂邊聊幾句，聊多了也會互相打聽對方最近上了什麼奏疏，算是彼此都懂彼此處境的同僚。

每天清早，岑參跟著儀仗隊伍，踩著台階走進皇宮，分別進入紫微省當值，一整天不是抄寫就是等著皇帝召見；到了傍晚，身上沾滿了整天在宮裡薰染的御香味，才拖著步子往家走，回到家連飯都懶得多吃就想躺下。這樣的日子過久了，他偶爾照鏡子，發現自己頭髮一點點白了，臉上也添了幾道紋路，再看看那些同僚裡升得快的人，一個個青雲直上，像鳥一樣飛得又高又遠，自己卻還在原地踏步，官職幾年沒動過，心裡難免有點酸。

可讓岑參真正憋著一股氣的，不是升遷的快慢，是諫官這個身分本身越來越沒意思。諫官該做的事是發現朝廷的過失然後上書提意見，剛上任那幾年他還常常憋不住寫個幾條，可這幾年他和杜甫都發現，能上的諫書越來越少，不是因為朝廷真的做得完美無缺，是因為敢說真話的空間越來越窄，說了也未必有用，漸漸地大家都學會了少說，多一句嘴不如少一句嘴。

岑參把這份心情寫進了寄給杜甫的詩裡。他表面上說聖明的朝廷沒什麼過失可以進諫，自己因此覺得諫書漸漸稀少，聽起來像是稱頌朝廷清明，可他跟杜甫都心知肚明，這句話底下藏著的是苦笑：白髮悲花落，青雲羨鳥飛。聖朝無闕事，自覺諫書稀。

寫完這首詩不久，杜甫就因為替房琯說話，惹惱了皇帝，被貶去當了華州司功參軍，離開了長安，兩個曾經隔著宮牆聊天的同僚，就這樣散了。岑參這才明白，自己詩裡那句諫書稀的苦笑，其實早就替兩人的處境寫好了注腳，諫官的話，從來都不是沒有，只是這個朝廷，漸漸聽不進去了，聽得進去的，也未必願意照做，一個諫官能做的，終究有限。`
  },

  // id=154 中唐 劉長卿 〈餞別王十一南遊〉rating=2
  // 詩眼：送別時站到連船影都看不見才肯走的那種捨不得
  // 隱藏連接：劉長卿自己一生輾轉貶謫，深知看著船走遠或被送走的滋味
  154: {
    title: "餞別王十一南遊",
    author: "劉長卿",
    summary: "船影早就消失在江面上了，劉長卿卻還站在渡口，捨不得轉身。",
    story: `跟你說我朋友長卿一次送人送到看不見船影才肯走的渡口。

那天他送一個叫王十一的朋友南遊，兩人交情不算頂深，說不上多年的知交，但足夠讓長卿願意站到最後，甚至比送一些更親近的朋友還站得久。船開的時候，長卿站在岸邊，望著江面上那片煙水茫茫，船越走越遠，越走越小，帆影從清清楚楚變成一個模糊的點，最後連個黑點都快看不清了，他還站在那裡，一直望著，捨不得挪動腳步。

揮手告別的時候，長卿的眼淚就掉下來了，濕了一整塊手巾，旁邊的隨從遞了塊乾淨的過來，他也沒接。他自己也說不清為什麼這次特別捨不得，也許是這些年他自己被貶來貶去，輾轉江淮一帶，換了好幾個地方任職，吃過太多次這種看著別人的船走遠，或者自己坐上船被人送走的滋味，格外懂這一刻的重量。

他抬頭看天上，幾隻飛鳥往遠處飛，飛進了看不見的地方，不知道落在哪裡；再看看兩岸的青山，青山依舊立在那兒，可對著一個要送客離開的人，青山什麼都做不了，只能那樣空空地對著他。長卿站在渡口，忽然覺得自己跟那青山有點像，想留人留不住，能做的只有陪著看這一程。

長江上那一片帆影漸漸遠去，長卿知道王十一這一路要往南邊去，路上要經過好幾個渡口、好幾座城，最終會到五湖那一帶，落日的餘暉那時候大概正灑在那片春色上。他甚至開始想像，朋友到了那邊的汀洲，一個人站著，面對著滿地的白蘋草，大概也會被同樣的思念纏住，想起這個渡口、這場送別，愁緒跟那片白蘋一樣，鋪得到處都是，收不回來。

長卿把這些畫面收進四十個字裡：望君煙水闊，揮手淚沾巾。飛鳥沒何處，青山空向人。長江一帆遠，落日五湖春。誰見汀洲上，相思愁白蘋。

寫完他才轉身往回走，手裡那塊濕透的手巾也總算捲起來收進袖子裡。江面上早已經看不見帆影，只剩水波一圈一圈散開，渡口的船夫已經在招呼下一批要過江的客人了。他知道這次送別，自己怕是要好一陣子才能想起來不難受，但他不後悔站到最後一刻才走，至少這段路，他陪王十一走到了眼睛能看見的最遠處。`
  },

  // id=157 中唐 錢起 〈送僧歸日本〉rating=2
  // 詩眼：一盞看不見盡頭的燈，是他能給黑暗大海唯一的證明
  // 隱藏連接：無考據僧人本名，但以鑑真六次東渡、晚年失明仍渡海弘法的真實史事，做反向映照（此僧西來求法多年，此刻東渡歸國）
  157: {
    title: "送僧歸日本",
    author: "錢起",
    summary: "他不知道那個日本僧人的法名，只知道對方在長安苦學多年，如今要帶著一整船的經文，獨自渡海回一個自己都快記不清模樣的故鄉。",
    story: `跟你說我朋友錢起，在江邊送一位素不相識的日本僧人回國的那個傍晚。

那年遣唐使的船隊又要啟程了，隨行的還有幾名在長安、洛陽學了多年佛法的日本僧人，其中一個特地繞路來向錢起辭行。錢起不知道他的法名，史料上也沒留下——那個年代太多這樣的名字，來的時候是遣唐使名冊上的一個編號，走的時候也差不多。錢起只知道，這個人在中土待了很多年，讀漢文佛典讀到能跟中原僧人辯經，如今要帶著滿肚子的義理，坐船回那座他自己都快記不清模樣的島。

錢起想起幾十年前的一段往事，那時鑑真和尚為了把戒律傳到日本去，一次又一次東渡，五次都失敗，有一次船翻了差點淹死，還有一次在海上漂到最南邊，最後一次終於成功時，鑑真已經雙目失明，是被人扶著上船的。錢起眼前這個年輕僧人走的方向正好相反，一個往東去，一個當年往西來——這條法脈，就這樣在海上來回渡了幾十年，靠著一批又一批這樣沒人記得名字的僧人接力著。

送別那天，僧人的行李很輕，除了幾卷經文，什麼都沒帶。錢起問他不怕海上風浪嗎，僧人只是笑了笑，說他來的時候就已經知道，這條命是交給海的，回去的時候，也一樣。

船漸漸離岸，錢起站在江邊，看那艘船怎麼一點一點被水汽吞掉。他想像僧人夜裡在船艙裡打坐，海水拍打船身，月光灑在浪頭上，安靜得像整片海洋都在聽他誦經，連水裡的魚、傳說中的蛟龍，都聽得入了神。錢起提筆，把這一幕寫成了送別詩：

上國隨緣住，來途若夢行。浮天滄海遠，去世法舟輕。水月通禪寂，魚龍聽梵聲。惟憐一燈影，萬里眼中明。

寫到最後兩句時，錢起想的不是船，是船艙裡那一盞小燈。茫茫大海什麼都看不清，可只要那盞燈還亮著，人就還在。就像當年鑑真雙目已盲，仍然靠著這樣一盞看不見的燈，一寸一寸渡過黑暗的海，最後把戒律送到了異國。

僧人的名字後來沒有人記得。他上船之後，錢起再也沒收到過任何消息，甚至不知道那艘船有沒有平安抵達。但這首詩留下來了，連著那一盞燈，一直亮到一千多年後，替所有渡海求法卻連名字都沒能留下的人，多亮了一會兒。`
  },

  // id=158 中唐 錢起 〈谷口書齋寄楊補闕〉rating=2
  // 詩眼：提前一天叫童子把路掃乾淨——這是他確定朋友一定會來的方式
  // 隱藏連接：谷口地名承接漢代隱士鄭子真『耕於巖石之下，名震京師』的典故（見《漢書》引揚雄語），錢起特意選址呼應這位拒官隱士的精神
  158: {
    title: "谷口書齋寄楊補闕",
    author: "錢起",
    summary: "他把院子裡爬滿藤蘿的小路仔細掃過一遍，不是因為愛乾淨，是因為他昨天已經跟朋友約好了，篤定到提前一天就開始準備。",
    story: `跟你說我朋友錢起，在長安城外谷口那間小書齋的一個傍晚。

谷口這個地名，懂典故的人聽了都會心一笑。漢朝的時候，這裡住過一個叫鄭子真的隱士，朝廷幾次徵召他做官，他都不理，一個人在山腳巖石下種田。奇怪的是，他越不出來，名氣反而越大，大到整個長安城都聽過他的名字。揚雄後來寫進書裡，說他不屈其志，耕於巖石之下，名震京師。錢起選在谷口蓋書齋，不是隨便挑的地方——他就是想沾一點這位老前輩的骨氣。

錢起這個人官不大，大曆十才子裡他算是混得還可以的，可他心裡一直有一塊地方留給山林。他在谷口這間小屋子住得簡陋，泉水繞著山壑流，茅草屋簷連著，雲霞低低地生在薜荔織成的門簾外頭。竹子剛淋過一場新雨，他看著特別喜歡——雨後的竹葉綠得發亮，他常站在窗邊看半天。到了傍晚，夕陽照在山頭，他又覺得這一刻的山比任何時候都好看。

他觀察這裡的節奏觀察得很細：白鷺總是習慣早早回巢棲息，秋天的花卻拖得比別處更晚才落——好像連時間在這裡都走得慢一點，懶洋洋的，不急著趕路。

這天他起了個念頭：昨天已經跟楊補闕約好了，對方要來拜訪。楊補闕在朝中當諫官，平常忙著上疏勸諫，日子過得比錢起緊繃得多。兩人是老交情，難得抽空跑這一趟山路，錢起心裡挺珍惜這份空檔。他一早就叫家裡的僮僕，把院子裡爬滿藤蘿的小路仔細掃過一遍——不是隨口交代，是真的在意，怕朋友來的時候路難走、心裡不舒坦，也怕自己這幾年過得閒散，招待起朋友來反而顯得怠慢。他一邊等，一邊提筆把這間書齋的整個下午都寫了下來：

泉壑帶茅茨，雲霞生薜帷。竹憐新雨後，山愛夕陽時。閒鷺棲常早，秋花落更遲。家童掃蘿徑，昨與故人期。

整首詩前面六句寫的都是谷口的閒散風景，泉壑、雲霞、竹、山、鷺、秋花，一句一句鋪陳得從容不迫，直到最後兩句才揭底——原來這不只是一首寫景詩，是一封等人的信。他把院子掃乾淨，不是因為愛乾淨，是因為他篤定朋友一定會來，篤定到提前一天就開始準備。

後來的人讀這首詩，最喜歡的往往就是這個轉折：前面看似寫給自己的隱居生活，最後才發現，他把最好的風景都留著，等一個懂的人來看。楊補闕那天有沒有準時到，詩裡沒說，但那條掃乾淨的藤蘿小路，替他等在那裡了。錢起自己大概也說不清楚，這間書齋到底是為了隱居而蓋，還是為了等這樣一次來訪而蓋——谷口這個地名底下藏著的骨氣，終究還是要有人懂，才顯得出價值，一個人的山水，總歸是寂寞的。`
  },

  // id=162 中唐 劉脊虛 〈闕題〉rating=2
  // 詩眼：去見一個人的路寫得比誰都清楚，連題目和那個人是誰卻都不見了
  // 隱藏連接：劉脊虛存詩僅十餘首、生平記載稀薄，相傳中年早逝，此詩題目經殷璠《河嶽英靈集》收錄時已佚失，故以『闕題』傳世
  162: {
    title: "闕題",
    author: "劉脊虛",
    summary: "這首詩連題目都不見了——後人只知道他去見一個朋友，那條路開滿落花，盡頭有一扇柴門，卻連對方是誰都沒能留下來。",
    story: `跟你說我朋友劉脊虛的一件怪事——他寫過的詩留下來的不多，其中最有名的這一首，連題目都不見了。

脊虛這個人，你如果去翻全唐詩，會發現他的名字底下只掛著十幾首詩，跟李白、杜甫動輒幾百首比起來，少得可憐。他二十出頭就中了進士，跟孟浩然、王昌齡、常建這些人都是朋友，那幾個人後來都成了盛唐詩壇響噹噹的名字，照理說脊虛也該是能寫一輩子詩的人，可他好像沒能活很久——史書上關於他的記載零零星星，連確切的生卒年都湊不齊，連他到底做過什麼官、後來去了哪裡，都只有片段的傳聞。相傳他中年就過世了，留下的詩稿大概還沒來得及好好整理，就這樣散佚了大半，剩下的十幾首，多半也是靠朋友輾轉抄錄下來的。

這首詩能留下來，多虧了殷璠編的河嶽英靈集，把它收進去的時候，題目那一欄已經是空的了——後人只好用闕題兩個字頂上，意思就是原本的題目找不到了。脊虛寫這首詩的時候，是去拜訪一個隱居讀書的朋友，那條路他大概走過不只一次，寫起來熟得很：白雲一路鋪到看不見盡頭，順著青溪走，溪水跟春天一樣長，走著走著偶爾有落花飄過來，跟著流水一路飄香。他知道這條路的盡頭有一扇柴門，門永遠對著山路開著，深深的柳蔭底下，藏著一間讀書堂。

脊虛沒有寫他到底去見了誰。那個朋友的名字，跟這首詩的題目一樣，也隨著時間不見了。他只把那條路、那間屋子給他的感覺，一字一句寫了下來：

道由白雲盡，春與青溪長。時有落花至，遠隨流水香。閑門向山路，深柳讀書堂。幽映每白日，清輝照衣裳。

幽靜的光影天天都在，日光清亮地照在衣裳上，好像那個地方自己會發光。

一千多年後，我們讀這首詩，知道的東西反而比題目更多：知道有一條開滿落花的溪邊小路，知道路的盡頭有一扇柴門和一間柳蔭下的讀書堂，知道那天陽光很好，清輝照在誰的衣裳上。唯獨不知道那個人是誰，那件事叫什麼名字。

有時候一首詩能留下來的，剛好就是最該記得的那部分——路怎麼走，光怎麼照，至於標題，反而沒那麼重要了。脊虛大概也沒想過，自己隨手寫的一首拜訪詩，會在題目丟失之後，靠著這條路本身，走了一千多年還沒走完。他那些朋友，孟浩然、王昌齡，後來都留下了整整齊齊的詩集，唯獨他這個人，連名字都要靠殷璠的一本選集才勉強撐住。可能也正因為留下的太少，這條開滿落花的溪邊小路，才顯得格外清晰——彷彿脊虛把自己一輩子沒能好好交代的東西，全都收進了這一條路裡。`
  },

  // id=169 中唐 張籍 〈沒蕃故人〉rating=2
  // 詩眼：想幫他辦喪事，卻又懷疑他可能還活著——這種矛盾比確定死亡更折磨人
  // 隱藏連接：中唐屢有唐軍征吐蕃全軍覆沒的戰例，張籍此詩應為真實友人從軍失蹤所作，姓名今已不可考，故僅以『故人』稱之
  169: {
    title: "沒蕃故人",
    author: "張籍",
    summary: "他不敢替朋友辦喪事——不是不傷心，是懷疑對方可能只是被俘虜、還活著，這種懸而不決的煎熬，比確定的死亡還要折磨人。",
    story: `跟你說我朋友張籍收到一個消息以後，整整幾天都魂不守舍。

前年，唐軍出兵討伐邊境一帶的部族，張籍有個朋友也在軍中。仗打得很慘，城下那一戰，整支隊伍幾乎全軍覆沒。消息傳回中原的時候，已經是七零八落的——沒有人能說清楚到底誰活著、誰死了。吐蕃和大唐之間的邊境，戰事一起，兩邊的消息就徹底斷了，活人死人，全部混在一團模糊裡，長久地分隔開來。

張籍認識這位朋友很多年，兩人年輕時候常在一起喝酒論詩，聊起邊塞的事，朋友總是一副躍躍欲試的樣子，說大丈夫就該去邊疆立一番功業，總比窩在中原考科舉來得痛快。朋友從軍那年還特地來看過他一趟，兩人喝了一整晚酒，說等打完仗就回來，還要再喝一次，到時候要張籍請客。誰知道這一去，就是這樣的結局——如果真的算是結局的話。

戰場上流傳回來的消息很零碎，有人說，戰後戰場上到處是被丟棄的軍帳，沒有人去收拾，任它們爛在風裡；還有一匹馬自己走回了唐軍的營地，馬鞍上還綁著一面殘破的旗子，旗子雖然破了，可還認得出是原來那支隊伍的番號。看到這匹馬的人都心裡一沉——馬認得旗子，可是騎馬的人呢？

張籍聽到這些傳聞，心裡最難受的不是朋友死了這個消息，而是他根本不知道朋友到底死了沒有。如果確定死了，他還能辦一場像樣的祭奠，燒點紙錢，哭一場，心裡好歹有個交代。可現在他不敢祭——萬一朋友只是被俘虜了，被扣在吐蕃某個地方，還活著，那他張籍在這頭替活人辦喪事，豈不是折了朋友的壽？

這種懸在生死之間、不上不下的煎熬，比確定的死亡還要折磨人。他提筆寫下：

前年伐月支，城下沒全師。蕃漢斷消息，死生長別離。無人收廢帳，歸馬識殘旗。欲祭疑君在，天涯哭此時。

寫到欲祭疑君在這五個字時，他停了很久。想祭奠，又懷疑你還活著——這句話裡藏著的，是一個人不敢徹底放棄希望，卻又幾乎撐不下去的矛盾。他人在中原，朋友生死不明地留在天涯的某個角落，他只能對著那個方向，哭這一次。

這位朋友最終有沒有回來，史書沒有留下答案。張籍後來還是照常過日子，寫詩、應考、當官，可每次聽到邊境又打了什麼仗，他心裡那個懸而未決的念頭就會被翻出來一次——那個朋友，到底是死是活。這首詩留下來了，替所有等不到消息的人，把那種懸而不決的痛，寫得清清楚楚。`
  },

  // id=179 晚唐 李商隱 〈北青蘿〉rating=2
  // 詩眼：被政治鬥爭纏到心力交瘁後，他跑去山裡問一個和尚：人世間的愛恨到底值不值得計較
  // 隱藏連接：李商隱受牛李黨爭夾擊（受知於牛黨令狐楚，卻娶李黨王茂元之女），兩邊不討好、仕途坎坷終生，此訪僧問禪之作很可能是他在黨爭夾縫中尋求解脫的心境投射
  179: {
    title: "北青蘿",
    author: "李商隱",
    summary: "他被兩邊政治陣營都當成外人，一個人跑進山裡找和尚——不是想出家，是想弄清楚人世間的愛恨到底值不值得他這樣拖著。",
    story: `跟你說我朋友義山有一次獨自跑去山裡找一個和尚，只為了想清楚一件事。

義山這輩子活得很擰巴。他年輕時候被令狐楚看重，收他當學生、教他寫駢文，還資助他考功名，令狐家是牛黨的人，這份恩情義山一輩子念著。後來令狐楚過世沒幾年，他又娶了王茂元的女兒，王茂元偏偏是李黨那邊的。這下好了，兩邊都覺得他是叛徒——牛黨覺得他忘恩負義，投靠了對頭；李黨又不完全信任他這個外人，覺得他終究是令狐家教出來的人。他一輩子在朝廷裡東奔西走，官做得起起伏伏，換了好幾個幕府當幕僚，卻始終進不了核心，說到底，就是被這場延續數十年的牛李黨爭給黏住了，怎麼撕都撕不乾淨，連他自己都說不清楚，這場婚姻到底是幸運還是拖累。

那天他心裡煩，一個人往山裡走。夕陽已經西斜，慢慢沉進崦嵫山那個方向——古人說太陽落山的地方就叫崦嵫，聽起來就有一種一天要結束了的疲憊感。他要去找一個獨居的僧人，茅屋就搭在山裡頭。

山路不好走。滿地都是落葉，把小徑蓋得看不清楚，義山走著走著，開始懷疑自己是不是找錯了地方——那個人到底在不在？頭頂上是一層一層的寒雲，路好像永遠走不到盡頭。他一邊走一邊想著這幾年朝堂上的事：誰又參了誰一本，誰又在背後說他忘恩負義，誰又因為他的姻親關係處處提防他。這些恩怨繞在他心裡，比山裡的路還要繞。

終於，天快黑的時候，他聽見了敲擊聲——是那位僧人在敲響入夜的第一聲磬。義山找到了茅屋，看見老僧人一個人悠閒地倚靠著一根藤杖，神情平靜得像什麼都沒發生過。

義山站在那裡，忽然覺得自己這些年計較的東西，好像也沒那麼重要了。整個世界在這位僧人眼裡，不過是漂浮的微塵罷了——既然如此渺小，人何必還執著於誰對誰錯、誰欠誰的恩情。他把這一趟訪僧的路，連同心裡這個念頭，一起寫成了詩：

殘陽西入崦，茅屋訪孤僧。落葉人何在，寒雲路幾層。獨敲初夜磬，閑倚一枝藤。世界微塵裡，吾寧愛與憎。

寫完這兩句，他沒有留下來出家，也沒有真的看破一切——第二天他還是要回到長安，繼續在牛李兩黨之間周旋，繼續被人猜忌，繼續數十年如一日地在夾縫裡走著沒有盡頭的路。但那個黃昏在山裡聽見的一聲磬響，他後來想起來，心裡總會靜一靜。義山後來寫了太多情感糾結、意象繁複的詩，這首北青蘿卻難得地簡單——一座茅屋、一位孤僧、一根藤杖、一聲磬，什麼都沒解決，卻好像什麼都不需要再解決了。`
  },

  // id=186 晚唐 杜荀鶴 〈春宮怨〉rating=2
  // 詩眼：因為長得太好看反而被耽誤了一生——她連該不該化妝都不知道該怎麼辦
  // 隱藏連接：杜荀鶴出身寒微，相傳是杜牧的私生子，身世成謎，屢試不第近三十年直到四十六歲才中進士，以宮女不受寵喻懷才不遇，是他自身處境的投射
  186: {
    title: "春宮怨",
    author: "杜荀鶴",
    summary: "她年輕時長得太好看，好看到反而誤了自己一生——這首寫宮女的詩，其實是杜荀鶴寫給屢試不第近三十年的自己。",
    story: `跟你說我朋友杜荀鶴寫過一個宮女的故事，其實寫的是他自己。

荀鶴的身世一直是個謎。相傳他是杜牧年輕時跟一個妾室生下的私生子，杜牧不敢認，把他託給旁人撫養，他一輩子頂著這樣模糊不清的出身，在科舉場上摸爬滾打了將近三十年，屢考屢敗，一直考到四十六歲才終於中進士。那個年紀，很多人早就放棄了，他還在考場裡跟二十歲的少年擠在一起。

這首詩表面上寫一個宮女，其實整首詩都是他自己的心情投射。他寫這個宮女，年輕的時候長得太好看，好看到反而誤了她——因為太出眾，容易被人忌妒，也容易被別的心機更深的女子聯手排擠掉，所以她一直沒能真正得到皇帝的寵幸。到了要梳妝打扮的時候，她對著鏡子提不起勁——化妝有什麼用呢？恩寵這種東西，從來不是靠容貌換來的，那她到底該怎麼裝扮自己，才能被看見？

荀鶴自己何嘗不是這樣。他年輕時候文章寫得好，照理說該早早出頭，可科舉這種東西，比的從來不只是文采，還有家世、人脈、考官的心情。他那模糊不清的出身，反而成了同輩私下議論的話柄，越是有人拿這件事說嘴，他就越不知道該怎麼證明自己是憑真本事考上的。他一次次落第，一次次不知道自己到底該怎麼打扮自己的文章，才能被考官看上眼——寫得太直白，怕被嫌粗淺；寫得太雕琢，又怕被說賣弄，這種進退兩難，跟詩裡那個宮女對著鏡子提不起勁，簡直是同一種心情。

窗外的風暖了，鳥叫聲一句一句碎碎地響著；日頭高起來，花影一層疊著一層，鋪在地上。這樣的春天景色寫得極美，可是越美，越襯出宮女心裡的閒置感——外頭春光正好，她卻什麼都不能做。

她只能想起以前在民間的日子——那些每年在溪邊採蓮的女孩子，自由自在，年年相約去採芙蓉，日子雖然普通，卻踏實。宮女被選進宮的時候，大概以為這是人生的躍升，誰知道進來以後，才發現困住她的，恰恰是曾經讓她驕傲的那張臉。

荀鶴把這種矛盾，連同這個宮女的一整天，寫成了這樣八句：

早被嬋娟誤，欲妝臨鏡慵。承恩不在貌，教妾若為容。風暖鳥聲碎，日高花影重。年年越溪女，相憶採芙蓉。

後來的人特別稱讚風暖鳥聲碎，日高花影重這一聯，說他把春天的閒散寫得極工整，卻又藏著說不出的落寞。這聯詩句相傳他自己也很得意，花了很長時間琢磨。

四十六歲那年，他終於考上了。回頭看這首詩，他大概會覺得，自己等的時間，比詩裡那個宮女還要久一點。`
  },

  // id=187 晚唐 韋莊 〈章臺夜思〉rating=2
  // 詩眼：家書寄不出去，連南飛的大雁都幫不上忙——因為他跟大雁飛的方向剛好相反
  // 隱藏連接：韋莊親歷黃巢之亂、長安淪陷，寫成秦婦吟名動天下，此詩相傳作於亂後輾轉江南、與長安家人音訊隔絕的漂泊歲月
  187: {
    title: "章臺夜思",
    author: "韋莊",
    summary: "連南飛的大雁都幫不上他的忙——因為他想寄的家書要往北送，雁群卻年年往南方飛，方向剛好相反。",
    story: `跟你說我朋友韋莊在江南一個秋夜裡，聽著雁叫聲，突然意識到一件很喪氣的事。

莊哥年輕時候在長安讀書，準備考功名，可他沒趕上太平年月。黃巢的軍隊打進長安那幾年，他人就困在城裡，親眼看著那座他熟悉的城市怎麼一步步被屠殺、被焚燒。他把親身經歷寫成了一首很長的敘事詩秦婦吟，裡頭寫的那些場面，慘烈到後來被人稱作秦婦吟秀才——這個名號聽起來風光，其實是拿一整座城的血淚換來的。

戰亂之後，他沒辦法留在長安，跟著逃難的人潮往南走，輾轉流落到江南一帶，一待就是好幾年，靠著替人寫文章、投靠地方官府勉強度日。家人還留在北方，兵荒馬亂裡，消息說斷就斷，他自己都記不清上一封平安信是多久以前收到的了。

這天晚上，他一個人在外頭住的地方彈瑟。瑟聲本來就帶著點哀怨的調子，纏繞在絃上，聽起來像風聲雨聲交織在一起，怨得讓人心裡發緊。他面前只有一盞孤燈，遠遠地，他聽見了楚地特有的號角聲——這裡是古代楚國的地界，跟他熟悉的長安完全是兩個世界的聲音。殘月低低地掛著，慢慢沉向章臺那個方向——章臺本來是長安城裡一條有名的街，如今卻成了他借用來稱呼異鄉夜色的名字，物是人非。

他望著窗外，芳草已經到了暮色深重的季節，一年又快過去了。他等的那個老朋友，說好要來的，卻遲遲沒有出現。這種等待，跟他等家鄉消息的心情很像——都是望穿秋水，望不到人。

他想寫封信回家，可是路斷了，兵荒馬亂的年頭，信使根本進不去，或者進去了也未必能活著把信送到。他抬頭，看見一行秋雁正往南飛——雁群每年都往南方過冬，而他的家鄉、他的親人，全都在北方。連雁都幫不上他的忙，因為牠們飛的方向，剛好跟他想寄信的方向相反。

他把這一整夜的心情，從瑟聲寫到雁影，寫成了這樣一首詩：

清瑟怨遙夜，繞絃風雨哀。孤燈聞楚角，殘月下章臺。芳草已云暮，故人殊未來。鄉書不可寄，秋雁又南迴。

連候鳥都靠不住的時候，一個人的鄉愁，就真的沒地方安放了。

後來他總算輾轉到了蜀地，晚年輔佐前蜀，做到宰相的位置，總算安定下來，也總算不用再靠一行大雁的方向去猜測家鄉的消息。但那些年在江南聽雁夜坐的秋夜，相傳他一直沒忘記——晚年寫詞時，那種望不到人、寄不出信的悵惘，還是會不時從字句縫裡滲出來，好像章臺那輪殘月，始終沒有真正落下去過。`
  },

  // id=210 盛唐 崔顥 〈行經華陰〉rating=2
  // 詩眼：他年輕時拚了命追名逐利，路過華山才忽然問自己：這些真的值得嗎
  // 隱藏連接：舊唐書記載崔顥年少『有俊才，無士行，好蒲博，嗜酒，娶妻擇美者，稍不愜意即棄之，前後數四』，此詩勸誡路人莫逐名利，很可能是他自我反省的心境投射
  210: {
    title: "行經華陰",
    author: "崔顥",
    summary: "他年輕時賭博、酗酒、換過好幾任妻子，路過華山漢武帝求仙的舊祠時，忽然問路上那些趕著求名逐利的旅人：這麼拚命，真的值得嗎。",
    story: `跟你說我朋友崔顥年輕時候幹過的事，說出來你可能會皺眉頭。

崔顥這個人才氣很高，年紀輕輕就中了進士，可是舊唐書裡白紙黑字寫著他的另一面：喜歡賭博，喝酒不節制，娶老婆專挑長得好看的，只要稍微不滿意，說休就休，前前後後換了好幾任妻子。這種名聲在當時傳得不太好聽，好一陣子他的才華都被這些行徑蓋過去了。

這天他路過華陰，就是華山腳下那片地方。太華山高聳入雲，俯瞰著底下的咸京——也就是長安。抬頭望過去，天外那三座主峰陡峭得像是刀削出來的，怎麼看都不像是人力能雕琢出的形狀。他忍不住停下腳步看了很久。

山腰上有一座漢武帝祠，是當年漢武帝為了求仙訪道建的。此刻雲霧正從祠前緩緩散開，另一邊，仙人掌峰——傳說是巨靈神劈開華山時留下的一個巨大掌印——山頭剛好雨過天晴，濕潤的岩石在陽光下閃著光。崔顥站在那裡，覺得眼前這片山河，北邊枕著險要的秦地關隘，往西看，驛道兩旁的樹木一路連到漢代祭天的畤壇，平坦地鋪展開來，整幅畫面壯闊得讓他心裡一震。

他想起漢武帝——那個擁有整個天下、要什麼有什麼的皇帝，晚年卻拚了命想求長生不老，花了大把力氣求仙問藥，最後還是老死了，什麼都沒求到。崔顥站在漢武帝祠前，忽然想到自己：他年輕時候拚命追逐的那些東西，賭桌上的輸贏、一時的美色、旁人眼裡的風光，跟漢武帝求的長生不老，本質上好像也差不多——都是一場抓不住的空。

他看著路上那些行色匆匆的旅人，一個個都往長安趕，趕著去搏一個功名、爭一份利祿。他忍不住想問他們一句話，也像是在問曾經的自己：這麼拚命地趕路，真的值得嗎？

他把眼前的山河、心裡的念頭，一起寫成了這樣一首詩：

岧嶢太華俯咸京，天外三峰削不成。武帝祠前雲欲散，仙人掌上雨初晴。河山北枕秦關險，驛樹西連漢畤平。借問路傍名利客，無如此處學長生。

他沒有真的留下來學道求仙。第二天他還是繼續往長安趕路，該做官做官，該周旋周旋。但後來他寫出了那首讓後人傳頌千古的黃鶴樓，把年輕時候那點浮躁，磨成了更沉的東西。相傳他晚年的詩風確實變得比早年質樸厚重了不少——華陰山下那個傍晚，或許就是轉變開始的地方。`
  },

  // id=221 中唐 劉禹錫 〈西塞山懷古〉rating=2
  // 詩眼：同一座山看著一個又一個王朝在這裡倒下，而山什麼都不用做，只是繼續枕著江水
  // 隱藏連接：相傳劉禹錫在一場以六朝興亡為題的詩會上當場寫下此詩，滿座賓客（相傳白居易也在座）讀後皆稱絕，紛紛擱筆不再寫，是唐代詩壇著名的軼事
  221: {
    title: "西塞山懷古",
    author: "劉禹錫",
    summary: "同一場詩會上，大家寫同一座山的興亡，劉禹錫寫完之後，相傳在座的人全都擱下筆——因為已經沒有更好寫的了。",
    story: `跟你說我朋友夢得的一件得意事——雖然他自己從沒說得意，但那場詩會上的場面，後來的人講起來都覺得痛快。

那年劉禹錫路過西塞山，正好在附近參加了一場文人聚會，主人出的題目是六朝興亡。在座的都是有頭有臉的詩人，相傳白居易也在座。大家輪流以這座山、這段歷史為題各自寫一首詩，比一比誰寫得更好。

夢得提筆想的，是幾百年前那一場滅國之戰。西晉的將軍王濬奉命討伐東吳，他造了巨大的樓船，從益州順江東下，浩浩蕩蕩開向金陵。東吳自以為守得住，在江面上拉起千尋長的鐵鎖，想擋住晉軍的船隊。結果王濬用火燒，鐵鎖熔斷，沉進了江底，晉軍長驅直入，兵臨城下，東吳末代皇帝只能舉著降旗，走出石頭城投降。曾經籠罩金陵城上空那股王氣，就這樣黯然收場。

夢得想的不只是東吳。西塞山這個地方，扼守長江要衝，從三國到六朝，一次又一次成為改朝換代的關口——每個占據金陵的政權，都以為天險能保住江山，最後幾乎都在這裡或類似的江防線上栽了跟頭，鐵鎖也好，樓船也好，說到底都攔不住一個決心要打過來的對手。人世間一次又一次為這些興亡往事傷懷感嘆，可西塞山呢？山的形狀幾百年來根本沒變過，還是那樣安安靜靜地枕著寒冷的江水，什麼都不用做，它連立場都沒有，只是看著一批又一批的人在山腳下爭來爭去。

夢得自己這些年也顛沛得很，跟著永貞革新那一夥人被貶了二十多年，輾轉好幾個偏遠的州郡，比誰都清楚興亡這兩個字有多沉。他把這種滄桑感受，全部濃縮進了這首詩。寫到最後，他想到眼下這個天下已經重新統一，四海一家，不再需要靠江防和鐵鎖去爭那口氣，可西塞山邊上那些殘破的舊營壘，秋天裡照樣長滿了蘆葦荻花，在風裡蕭蕭地響。

他把這段往事和眼前的心境，一氣呵成寫了下來：

王濬樓船下益州，金陵王氣黯然收。千尋鐵鎖沈江底，一片降旛出石頭。人世幾回傷往事，山形依舊枕寒流。從今四海為家日，故壘蕭蕭蘆荻秋。

詩會上，其他人讀了這首詩，一個個都沉默下來，相傳大家看完這首都覺得已經寫盡了六朝興亡的意思，再寫也寫不過，索性都擱下筆，不寫了。

那座山依舊立在長江邊，看過東吳，看過六朝，後來也看過劉禹錫這群人的貶謫與歸來。它什麼都沒說，只是繼續枕著江水。夢得那晚離開詩會的時候，心裡其實清楚，自己贏的不只是一場文人的較量——他把二十多年的顛沛，都摺進了這座山不動聲色的姿態裡，別人寫的是歷史，他寫的是自己還活著。`
  },

  // id=224 中唐 元稹 〈遣悲懷三首之三〉rating=2
  // 詩眼：他用整夜不睡覺的方式，想替妻子還一筆她活著時沒能享到的福
  // 隱藏連接：元稹妻子韋叢出身名門（其父韋夏卿），下嫁清貧的元稹後跟著吃了七年苦，元稹升官在望時她卻病逝，此詩即為亡妻所作組詩之三
  224: {
    title: "遣悲懷三首之三",
    author: "元稹",
    summary: "她跟著元稹吃了七年苦，好不容易熬到他快出頭的日子，自己卻一天都沒趕上——這首詩，是他用整夜不睡覺的方式，想替她多扛一點虧欠。",
    story: `跟你說我朋友微之，他這輩子最放不下的一件事，是他妻子沒能等到他出頭的那天。

微之年輕時候家裡窮，考上功名以後也還只是個芝麻小官，俸祿少得可憐。他娶了韋叢——韋叢的父親韋夏卿官做得不小，家世比他好上一大截，照理說這樣的女兒該嫁去更體面的人家。可韋叢還是嫁給了他，跟著他一起過苦日子。家裡沒有多餘的衣服，她自己翻箱倒櫃找出還能穿的舊衣裳給他；沒有酒錢待客，她就拔下頭上的金釵去當了換酒。這些事微之後來都記得清清楚楚，一件都沒忘。

苦日子熬了七年，微之的官運慢慢好轉，考上制科、當上監察御史，眼看著就要熬出頭了，日子總算開始有點盼頭。誰知道韋叢這時候病倒了，拖了一陣子，沒多久就走了，二十七歲。她跟著他吃了那麼多年苦，好不容易苦盡甘來的日子近在眼前，她卻一天都沒趕上，連一頓像樣的好日子都沒過上，就這樣走了。

微之寫了三首悼亡詩，前兩首已經把她生前的苦、走後的空落都寫盡了，寫到第三首，他坐在屋子裡，一個人發呆。悲的不只是韋叢，他也在悲自己——人活這一輩子，滿打滿算不過百年，扣掉童年和衰老，真正能一起過日子的時間，又能有多少呢？

他想起兩個古人。一個是晉朝的鄧攸，戰亂裡為了保全弟弟的孩子，捨棄了自己的親生兒子，後來竟然一輩子都沒能再有子嗣——這種事，除了認命，還能怎麼辦呢。另一個是潘岳，他妻子死後寫了一整套悼亡詩，寫得那樣情深，可微之覺得，潘岳寫得再多，那些辭藻終究還是不夠，因為文字本來就換不回一個人。

微之想，就算死後真能跟韋叢同穴而葬，黃泉底下幽暗渺茫，兩人是不是還能相認，誰也不知道；如果指望來生再續這段緣分，那就更加渺茫，難以期待了。這些寄託全都靠不住。

那他能做什麼呢？他只能想到一件事：讓自己整夜都睜著眼睛，不睡。他把這一整套心事寫成了詩：

閑坐悲君亦自悲，百年都是幾多時。鄧攸無子尋知命，潘岳悼亡猶費詞。同穴窅冥何所望，他生緣會更難期。惟將終夜長開眼，報答平生未展眉。

韋叢活著的時候，眉頭大概很少真正舒展過——嫁進來的頭幾年家裡窮到吃穿都要她想辦法，等微之終於能讓她過上安穩日子，她卻已經不在了。微之覺得自己虧欠她的，這輩子已經還不了了，他能做的，只剩下用整夜睜眼不睡的方式，替她把這份虧欠，多扛一點。三首悼亡詩寫完，他還會繼續在朝堂上起起伏伏很多年，但每次夜裡睡不著，他大概都會想起，自己曾經許下的，是要清醒地把這份虧欠記一輩子。`
  },

  // id=241 晚唐 李商隱 〈春雨〉rating=2
  // 詩眼：想送出去的信物，終究找不到地址可以寄
  // 隱藏連接：或與他自述的柳枝錯過姻緣有關（相傳，非定論）
  241: {
    title: "春雨",
    author: "李商隱",
    summary: "一對玉璫，他留了很多年，始終沒找到能寄去的地址。",
    story: `跟你說我朋友義山的一段心事。那年春天，他穿著一件洗得發白的夾衣，一個人窩在屋裡，誰也不想見。外頭下著雨，他就那樣躺著，一連躺了好幾天。

義山年輕時在洛陽有過一段差點成真的緣分。他自己後來在筆記裡寫過：有個賣絲綢人家的女兒叫柳枝，聽人唱他寫的詩，一聽就記住，還特地跑來問是誰寫的。兩人約好三天後見面。可是那三天裡，他跟著堂哥急著要去長安應試，同行的朋友還惡作劇偷走他的行李箱，一團亂，他終究沒能準時赴約。等他從長安回來，才知道柳枝已經被一個有權有勢的人娶走了。這件事他自己記得清清楚楚，寫進了柳枝五首的序裡。至於眼前這首春雨，是不是就是為柳枝而寫，沒人敢打包票——但後來的讀者總覺得，那種明明有機會卻錯過的悵然，兩件事對得上。

窗外的雨一直下。他起身走到門口，看見的是白門一帶的冷清——那裡曾經是他和她可能相遇的地方，如今空空蕩蕩，連個人影都沒有，一切都不如他當初設想的那樣。隔著雨，他望向她可能住的那棟紅樓，樓影模糊，連空氣都是冷的。天黑了，他一個人往回走，路過一戶人家門口垂著的珠簾，裡頭的燈晃啊晃，映著雨絲，他就這樣一個人回到住處，誰也沒等他。

他想起遠方，想起自己這一路奔波考試、四處漂泊的命，忍不住悲從中來——這樣的春天已經走到尾聲，人卻還沒個著落。那天晚上他睡得不安穩，殘夜將盡時做了一個模糊的夢，夢裡好像見到了她，醒來卻什麼都抓不住，只剩滿手的空氣。

他從匣子裡翻出一對玉璫——那是他一直留著，原本想找機會託人帶去給她的信物。他想寫封信，把玉璫一併寄去，可是提筆想了很久，終究不知道往哪裡寄，那人已經嫁作他人婦，連地址都問不到。他把信紙攤在桌上，抬頭看見窗外雲層很厚，一隻孤雁正往南飛，飛過那一整片望不到邊的雲。

玉璫緘札何由達，萬里雲羅一雁飛。

他把玉璫重新包好，放回匣子最底層，沒有寄出去。這封信終究沒有地址可以寫上去。義山後來的仕途也一路顛簸，捲進牛李黨爭，兩邊都不討好，一輩子都在寄人籬下。但那只玉璫，聽說他留了很多年——想送出去的心意，不一定送得到，可是留著，至少證明它曾經真實存在過。`
  },

  // id=244 晚唐 溫庭筠 〈利洲南渡〉rating=2
  // 詩眼：看著渡口眾人各自奔赴前程，他只想像范蠡一樣徹底放手
  // 隱藏連接：屢試不第、被令狐綯厭棄的溫庭筠，在渡口望著范蠡的五湖投射自身處境
  244: {
    title: "利洲南渡",
    author: "溫庭筠",
    summary: "才氣壓過同代人，卻屢試不第——那天他在渡口，忽然只想學范蠡徹底消失。",
    story: `跟你說我朋友飛卿在利州渡口的一個黃昏。夕陽把整條江水照得安安靜靜的，他一個人站在渡口，看著眼前這一幕，心裡卻想著一個完全不相干的古人。

飛卿是那種一眼就能看出才氣逼人的人。他寫賦特別快，據說考試的時候只要把手往懷裡一攏，叉手八次，一篇八韻的賦就打好腹稿了，旁人都叫他溫八叉。照理說這樣的才華，考功名應該手到擒來。可是他偏偏一次又一次落第，考了大半輩子，連個進士都沒撈到。有人說是他嘴太快，寫文章諷刺人不留情面，得罪了不少考官；還有一次他在考場裡見鄰座答不出來，忍不住出手幫了好幾個人，被監考的特別盯上，從此在官場的名聲更壞，主考官甚至公開點名要防他作弊。他還跟宰相令狐綯的兒子相熟，本來是條近路，卻常常拿令狐綯讀書不多這件事開玩笑，還把令狐綯私下請他代筆的詞洩露出去，一來一往，把自己的仕途也搭了進去，一輩子只能在各地幕府裡當個小小的從事，看著才氣不如自己的人一個個高升。

這天他從利州搭船南渡，天色將暗未暗，江面波光粼粼，映著斜陽，一片澹然。遠處幾座曲折的小島隱在蒼茫暮色裡，連著後頭青翠的山影。渡口這頭，馬兒在水波邊嘶鳴，他看著船夫搖著槳把客人一批批送過河去；柳樹底下，還有人坐著歇腳，等船划回頭來接。幾叢沙洲邊的水草裡，一群鷗鳥被人聲驚散，飛向遠方；萬頃江田上頭，一隻白鷺獨自掠過。

看著這一幕，他忽然想到范蠡。范蠡當年輔佐越王勾踐滅了吳國，功成之後什麼都不要，帶著西施悄悄駕一葉扁舟，消失在五湖的煙水裡，再也沒人找得到他。飛卿站在渡口，忽然覺得，這世上大概沒有幾個人真正懂范蠡在想什麼——放下所有能拿到手的權位，就這麼算了，乾乾淨淨地走。

誰解乘舟尋范蠡，五湖煙水獨忘機。

他自己這輩子，好像怎麼樣都甩不開那些糾纏——才氣惹來的嫉妒、嘴快招來的仇家、一次次落第的委屈。他沒有五湖可以去，也沒有西施相伴，只有眼前這條利州渡口的江。可是看著那隻白鷺一路飛遠，他忽然懂了范蠡那種算了、不玩了的心情——不是誰都有膽子真的做到，但至少此刻，他可以站在這裡，替自己想像一下那樣的自由。船夫喊他上船了，他收回目光，一步跨上船板，身後的渡口，又恢復成日常的樣子。飛卿後來到死都沒能正式考中進士，一輩子在各地幕府裡輾轉，晚年才靠著門蔭勉強混了個小官。可是這首詩留下來了，那個在渡口望著白鷺想起范蠡的黃昏，比他任何一次落第都更接近他真正想要的東西。`
  },

  // id=250 北宋 蘇軾 〈正月二十日往岐亭郡人潘古郭三人送餘於女王城東禪莊院〉rating=2
  // 詩眼：同一個日子，一年前後從淒惶獨行變成朋友溫酒相待
  // 隱藏連接：黃州平民朋友潘丙、古耕道、郭遘，與東坡居士稱號的由來
  250: {
    title: "正月二十日往岐亭郡人潘古郭三人送餘於女王城東禪莊院",
    author: "蘇軾",
    summary: "去年今天他在雨裡淋著梅花心碎，一年後同一天，朋友替他溫好了半瓶酒。",
    story: `跟你說我朋友子瞻在黃州過的第二個正月。正月二十號這天，他去岐亭看一個隱居的老朋友陳慥，潘丙、古耕道、郭遘三個當地朋友一路送他到女王城東邊的禪莊院才轉身回去。

子瞻會落腳黃州，是因為烏臺詩案。他寫詩被人斷章取義告了一狀，關進御史臺的牢裡，差點掉腦袋，最後從輕發落，貶到黃州當一個有名無實的團練副使，不准簽署公事，說白了就是被放逐在外面，誰都不知道朝廷哪天想起他來要不要他的命。剛到黃州那年冬末春初，他是一個人硬著頭皮翻過重重關山走過來的，身邊沒有一個相熟的人，那年正月二十號，他就是頂著細雨，踩過開得正好的梅花走這條路，心裡淒惶得不得了。

一年過去了。這一年他在黃州什麼都沒有，官不能當，俸祿沒有，一家老小十幾口人擠在破廟改成的臨時住處裡，日子過得緊巴巴。可是他交到了潘丙、古耕道、郭遘這幾個本地的普通朋友——賣酒的、種田的、行醫的，什麼身分都有，沒人管他曾經是名滿天下的翰林學士，也沒人在意他是不是戴罪之身，就當他是鄰居家一個愛喝兩杯的老哥。他們幫他張羅了一塊城東的荒地，他自己下田開墾，種麥子種菜，還給自己取了個號叫東坡居士。這個他隨口起的別號，後來變得比他本來的官銜還要響亮。這天他又踏上跟去年同一條路，十天的春寒讓他窩在屋裡沒出門，一出門才發現江邊的柳樹早就悄悄綠了，山谷裡的溪水叮叮咚咚流動，冰開始化了；去年山火燒過的荒地上，新草已經長得一片青翠，連燒痕的黑都看不見了。

到了女王城東禪莊院，他望著自己那幾畝荒園，笑著跟潘丙他們說，這地方就留我住下吧；郭遘溫了半瓶濁酒等著給他喝。喝著喝著，他忽然想起，去年今天，他還在關山路上，一個人，淋著細雨，看著梅花，心都要碎了。

去年今日關山路，細雨梅花正斷魂。

他把杯子放下，看看眼前這幾個朋友，一年前那個在雨裡踽踽獨行的自己，好像已經是很遠很遠的人了。命運沒有變好多少，他還是那個被貶的罪官，前程依舊沒個著落，可是身邊這幾張臉，是去年那條關山路上完全想像不到的事。子瞻後來又被貶到更遠的惠州、儋州，一路顛沛到六十幾歲才北歸，可是黃州這幾年交下的朋友，他一輩子都記得，往後每逢正月二十號，他還會忍不住想起這一天，甚至又提筆寫詩回應這段記憶——同一天，一年前後，命運沒等他，可是人心等到了。`
  },

  // id=275 中唐 白居易 〈冬至夜懷湘靈〉rating=2
  // 詩眼：一年最長的夜晚，兩個被拆散的人各自數著同樣的黑
  // 隱藏連接：母親反對的初戀湘靈，貫穿他多首詩的隱藏主角
  275: {
    title: "冬至夜懷湘靈",
    author: "白居易",
    summary: "母親一句不答應，拖垮了他一生忘不掉的初戀。",
    story: `跟你說我朋友樂天年輕時候，一段誰都不准他提起的心事。

樂天十幾歲那年住在符離，隔壁住著一戶姓湘的人家，家裡有個女兒，乳名湘靈，比他小四歲。兩個孩子從小玩在一起，一個彈琵琶一個吟詩，長大了，情分也跟著長大，私底下早就認定了彼此，樂天心裡盤算的是將來要正正經經下聘娶她過門。樂天後來寫過好幾首詩提到她——寄湘靈、潛別離、長相思，那些詩裡藏著的名字，隱晦得很，後人翻遍他的詩集、對照年份和地名，拼湊了很久才敢確認，說的就是這個女孩子。有一首他甚至直白地寫過，自己這輩子沒有一天不想著她，可是這樣的句子，他也只敢寫在詩裡，從沒敢真的說給誰聽。

可是這件事，他母親陳氏死活不答應。湘靈家世普通，樂天家雖然也不算顯貴，母親卻認定門第配不上，說什麼都不肯點頭。樂天求了很多年，一直拖到快三十歲，連續好幾次外放、應試都刻意選擇符離附近，就是捨不得走遠。可是母親態度一年比一年硬，最後樂天終究沒能娶到湘靈，自己也不敢公然違逆母命——那個年代，一個讀書人如果真的忤逆母親，仕途基本上就毀了。

這年冬至夜，他一個人在外地過節。冬至是一年裡黑夜最長的一天，他躺在被窩裡翻來覆去睡不著。她那張漂亮的臉，他已經好一陣子見不著了——不知道是因為距離遠，還是因為他心裡清楚，兩人大概再也見不到了。被子冷冰冰的，身邊沒有人，連挨著取暖都做不到。他想著，這一年最長的夜晚，怎麼熬得過去；再往下想，湘靈那頭，大概此刻也是一個人躺著，兩個人隔著千里，同樣熬著這個漫漫長夜，誰也給不了誰一點溫度。

豔質無由見，寒衾不可親。何堪最長夜，俱作獨眠人。

樂天後來還是照著母親的意思，娶了楊氏，仕途也一路做到左拾遺、江州司馬、杭州刺史，看起來什麼都齊全了。可是湘靈這個名字，他心裡一直沒放下——直到四十幾歲，還寫詩偷偷提起她，說自己這輩子最對不起的人是她，甚至在一次路過符離舊居附近時，還特意繞道去看了一眼，卻什麼人都沒等到。冬至那晚的被窩有多冷，後來的每一個冬至，他大概都會想起一次。有些心事，不是忘記了才不說，是說了也沒有用，只能留著，一年一年地，自己一個人扛。`
  },

  // id=282 中唐 韋應物 〈秋夜寄邱員外〉rating=2
  // 詩眼：隔著幾百里，靠同一刻的失眠彼此惦記
  // 隱藏連接：昔日放蕩的侍衛，晚年與辭官修道的邱丹惺惺相惜
  282: {
    title: "秋夜寄邱員外",
    author: "韋應物",
    summary: "他在院子裡散步的這一刻，篤定遠方那個朋友，此刻也還醒著。",
    story: `跟你說我朋友韋公在一個秋夜裡想起的一個人。他一個人在院子裡散步，嘴裡低低唸著幾句應景的詩，天氣涼得剛好。

韋應物這輩子，前半段跟後半段簡直像兩個人。年輕時他在長安當過玄宗身邊的侍衛，十五歲就出入宮禁，仗著皇帝寵信，橫行鄉里，喝酒、鬥毆、窩藏犯人，鄉里人見了他都要繞道走，誰都不敢惹。安史之亂一起，玄宗倉皇出逃，靠山一夕之間沒了，他流落失所，這才痛下決心收心讀書，從頭來過，一步步做到滁州、江州、蘇州刺史，晚年又喪了妻，性子也跟著沉靜下來，詩裡再看不到年輕時的驕氣，只剩山水和獨處的清淡，後人讀他的詩，很難想像他年輕時是那樣一個橫衝直撞的人。

他有個朋友邱丹，原本也是做官的，做到員外郎，後來看透了官場的起起落落，乾脆辭官不做，跑到臨平山裡當起了道士，一個人清清靜靜地過日子，種菜、煉丹、讀經，不再過問朝廷裡的事。韋應物很惦記這個朋友，常常想著他一個人在山裡，不知道過得怎麼樣，有沒有按時吃飯，會不會太過清苦。

這天晚上，韋應物在自己的院子裡走著走著，忽然就想起了邱丹。秋夜的空氣涼涼的，他一邊走一邊隨口念了幾句詩，配著這樣的天氣，心裡竟有點踏實的愜意。他忽然想，邱丹住的那座空山裡，此刻應該也是這樣安靜——山裡沒有旁的聲響，大概只聽得見松果一顆一顆從樹上掉下來，落在地上的聲音。

他猜，邱丹這個時候，大概也還沒睡。兩個人隔著好幾百里路，誰也看不見誰，可是韋應物就是篤定，那個選擇離開官場、躲進山裡修道的朋友，此刻的心境跟自己現在站在院子裡的心境，應該是同一種——都醒著，都在秋夜裡想著點什麼。

懷君屬秋夜，散步詠涼天。空山松子落，幽人應未眠。

信寫完，韋應物把它交給信差，往臨平山的方向送去，也不知道要走多少天才能送到。他知道邱丹收到信，大概不會太意外——這種心照不宣的默契，他們兩個人之間早就有了，不需要多說什麼客套話，一句想你，配上這樣的秋夜，就已經足夠。人不一定要坐在一起才算陪伴，有時候只是知道遠方那個人這一刻也醒著，跟自己想著同樣的心事，那份牽掛，就已經算是抵達了。韋應物晚年寫過不少這樣的詩，寄給散落在各地的老朋友，這首給邱丹的，是其中最安靜、也最教人記得住的一封。`
  },

  // id=285 中唐 權德輿 〈玉臺體〉rating=2
  // 詩眼：一整天的心思，繫在兩個迷信的小徵兆上
  // 隱藏連接：無（民間閨怨題材的擬作，非權德輿自身經歷）
  285: {
    title: "玉臺體",
    author: "權德輿",
    summary: "裙帶鬆了，蟢子飛了——她把懶得擦的脂粉，又重新拿了出來。",
    story: `跟你說我朋友載之寫過一個等信等到都學會看預兆的女人。

這首詩不是寫他自己的事，是他仿照南朝玉臺新詠那種閨怨小詩的筆法，寫一個等丈夫等了很久很久的婦人。載之這個人官做得不小，一路做到宰相，議事論政一板一眼，可是他年輕時特別喜歡寫這種民間小情小調的詩，把老百姓生活裡那些迷信的小講究，寫得又細膩又有人情味，跟他後來端坐廟堂的正經形象完全不同，倒像是另一個人。

詩裡這個女人，丈夫長年在外，家裡就她一個人守著。這天早上她起床，發現昨晚睡覺時裙帶自己鬆開了——民間傳說，裙帶無故鬆脫，是丈夫要回來的兆頭。她心裡咦了一聲，還沒來得及細想，轉頭又看見一隻蟢子飛過——蟢子是一種小蜘蛛，蟢跟喜同音，老一輩人都說，家裡飛進蟢子，是喜事要到的意思。一天之內，兩個吉兆都讓她碰上了。

她這些年臉上的脂粉都懶得認真上了，梳妝匣放在角落積了灰，反正丈夫不在，擦給誰看，早出晚歸只圖個方便。可是今天不一樣，她對著鏡子想了想，還是把胭脂水粉拿出來，細細地補上一層，連眉毛都仔細描了兩遍——脂粉不能就這麼放棄不用，萬一，萬一今天他真的要回來了呢。

昨夜裙帶解，今朝蟢子飛。鉛華不可棄，莫是藁砧歸。

藁砧這兩個字，是當時人拐了好幾個彎的隱語——藁砧是墊稻草用來剁東西的砧板，砧板配的是鈇，鈇跟夫同音，所以藁砧在詩裡拐著彎指的就是丈夫。載之寫這種民間常用的暗語，寫得很自然，一點都不生硬。這個女人到底等不等得到丈夫回來，詩裡沒說，載之也沒打算說。他要寫的就是那個瞬間——一整天的心思，全繫在兩個小小的迷信徵兆上，那種細小又執拗的盼望，比直接寫我好想你動人多了。她把脂粉盒收好，坐在窗邊，一邊縫著東西，一邊時不時往門口望一眼，聽見外頭有一點腳步聲，心就跟著跳一下，等著看今天究竟會不會有什麼不一樣的事情發生。這樣的日子她其實已經過了不知道多少回，裙帶鬆過很多次，蟢子也不是第一次飛進屋裡，可是每一次她都還是願意認真相信一次。載之把這一整天的心思，就這樣輕輕巧巧地放進二十個字裡，沒有一句喊苦，也沒有一句怨恨丈夫久久不歸，卻讓人看得出，那種盼望有多沉、又有多容易一次次落空。`
  },

  // id=287 中唐 張仲素 〈春閨思〉rating=2
  // 詩眼：手停在半空，思念比意志更快接管身體
  // 隱藏連接：無
  287: {
    title: "春閨思",
    author: "張仲素",
    summary: "她提著籠子站在桑樹下，忘了採葉——因為昨夜夢到了漁陽。",
    story: `跟你說我朋友仲素寫過一個採桑採到一半就忘了自己在做什麼的女人。

仲素這個人，詩寫得工整，特別擅長寫閨怨這一類的小詩——就是想像一個女人，丈夫遠戍邊關，她一個人守著家，把那種說不清楚的牽掛，寫進日常最普通的動作裡。他自己官做到中書舍人，起草詔令是他的本行，寫的都是朝廷大事，可是私底下最拿手、也最教人記住的，反倒是這種替尋常婦人設身處地寫下的幾句小詩。

這首詩裡的女人，住在城邊。城牆邊種著一整排柳樹，春天一到，柳條就這麼裊裊地垂下來，隨風輕輕晃著，晃得人心裡也跟著一陣一陣發軟。田埂小路兩邊，桑樹也綠得正好——這個時節正是採桑養蠶的忙季，家家戶戶的婦人天不亮就都提著籠子出門，趁著露水還沒乾、葉子最嫩的時候趕緊採，晚一點葉子老了，蠶吃了容易生病，養蠶這件事，耽誤不得。

她也提著籠子出了門，走到桑樹下，伸手要摘葉子。可是摘到一半，她整個人忽然停住了，手懸在半空中，籠子晾在一邊，葉子也忘了摘。她想起昨晚做的一個夢——夢裡她到了漁陽。

漁陽是北方邊塞一帶的地名，離她住的地方幾千里遠，是她丈夫戍守的地方。那個夢太清楚了，清楚到她現在站在桑樹底下，滿腦子都還是夢裡的畫面，手上的活全都忘了。旁邊一起採桑的鄰居喊了她一聲，她才回過神，低頭看看籠子，裡頭稀稀落落沒摘幾片葉子，太陽已經爬得老高了。

裊裊城邊柳，青青陌上桑。提籠忘采葉，昨夜夢漁陽。

仲素沒有寫她夢裡見到了什麼，丈夫過得好不好，信裡有沒有捎來消息——什麼都沒交代。他就寫到忘采葉這裡停住了，讓那籠子裡沒摘滿的葉子，替所有沒說出口的思念作證。日子還是要過，桑葉還是要採，蠶還是要養活，家裡等著吃飯的人也還等著，可是心思有時候不聽使喚，一個夢就能讓手停在半空——這種被思念打斷日常的瞬間，比任何一句我好想你都更真實。太陽漸漸曬熱了她的後背，她才慢慢回過神，重新彎腰摘葉，把那個夢先擱在心裡，等晚上一個人的時候再慢慢想。這首詩後來被收進許多閨怨詩的選本裡，讀的人未必記得住仲素這個名字，卻大多記得那個提著空籠子、忘了採葉的身影，還有那句沒頭沒尾、卻誰都懂的昨夜夢漁陽。`
  },

  // id=299 晚唐 西鄙人 〈哥舒歌〉rating=2
  // 詩眼：一首讓敵人不敢渡河的頌歌，主角後來卻輸給了自己人的逼迫
  // 隱藏連接：哥舒翰潼關兵敗被部下綁縛投降、最終被殺——正史記載，非虛構
  299: {
    title: "哥舒歌",
    author: "西鄙人",
    summary: "這首歌永遠停在他最風光的那個夜晚，沒人願意唱後面發生的事。",
    story: `跟你說我在隴右戍邊那群朋友，人人都會唱的一首歌。

這首哥舒歌不知道是誰先起的頭，傳唱的人自己也說不清楚，只曉得它從老百姓嘴裡一路傳到軍營裡，唱的都是同一個人——河西節度使哥舒翰。

哥舒翰不是漢人，祖上是突厥突騎施的貴族，長得魁梧，善使一把長槍，年輕時性子浪蕩，四十歲才發憤帶兵，沒想到一路打出了名堂。天寶年間，吐蕃常年在隴右一帶騷擾，搶糧搶馬，朝廷幾任將領都拿石堡城沒辦法——那是吐蕃卡在咽喉要道上的一座天險城池。哥舒翰硬是率軍強攻拿下了石堡城，吐蕃從此元氣大傷，再也不敢像以前那樣明目張膽地越境放牧、伺機偷襲。邊境的老百姓、駐軍，提起他都帶著敬畏，私底下傳唱起這首歌，說星斗滿天的夜裡，哥舒翰總是刀不離身，提防著敵人；吐蕃人到現在，還只敢遠遠地窺探邊境的牧馬，不敢再越過臨洮一步。

北斗七星高，哥舒夜帶刀。至今窺牧馬，不敢過臨洮。

這首歌唱的是他最風光的那幾年。可是後來的事，唱這首歌的人大概不敢想。安祿山起兵造反那年，哥舒翰已經中風癱在家裡好幾年了，朝廷實在無人可用，硬是把他從病榻上拖出來，派去守潼關——那是長安最後一道防線。哥舒翰本來主張堅守，可是宰相楊國忠不斷逼他出關迎戰，他拗不過朝廷的壓力，含淚領兵出關，結果在靈寶被叛軍打得全軍覆沒，自己也被部下綁了投降，後來被押到洛陽，第二年安祿山的兒子安慶緒棄城撤退時，把他殺了。

一輩子讓吐蕃人不敢過臨洮一步的猛將，最後沒有死在他最擅長的隴右戰場，是被自己人的猜忌和催逼，逼上了一場他不想打的仗。潼關那一敗，牽連的不只是他自己——長安門戶洞開，玄宗倉皇出逃，往後八年的動亂由此展開，多少人的命運都被這一場戰役改寫。這首歌至今還在傳唱，唱的永遠是他刀鋒最亮的那個夜晚——沒人願意把後面那段唱進去，可是知道結局的人，再聽這首歌，總覺得那把夜裡不離身的刀，聽著聽著，忽然有點心酸。守邊的老兵們唱起這首歌時，多半只唱前面兩句就笑著喝酒去了，後面的事，留給知道的人，自己在心裡默默接下去，誰也不忍心把話說破。`
  },

  // id=331 盛唐 張旭 〈桃花谿〉rating=2
  // 詩眼：明知道問了也不會有答案，還是問了
  // 隱藏連接：化用陶淵明桃花源記，狂草書法家寫下全唐詩僅存六首詩中最溫柔的一首
  331: {
    title: "桃花谿",
    author: "張旭",
    summary: "寫字瘋到嚇壞旁人的張旭，問了一個他自己都知道沒有答案的問題。",
    story: `跟你說我朋友張旭寫詩的時候有多反常。

張旭這個人，大家記得他都是因為他寫字。喝了酒，他就瘋，拿起筆龍飛鳳舞，寫出來的狂草沒人學得來，人稱他張顛，還有人說他喝醉了甚至用頭髮沾墨寫字，寫完醒來自己看了都嚇一跳，怎麼也重現不出同樣的筆法。後世把他跟懷素並稱，說他是把草書推到極致的第一人，連大詩人杜甫都專門寫詩讚嘆過他醉後揮毫的樣子。他的字狂放到極點，可是他留下來的詩，全唐詩裡總共只有六首，少得可憐，而且首首都跟他寫字的瘋勁完全相反——安安靜靜的，一點都不張狂，讀起來很難相信是出自同一個人的手筆。

這首桃花谿，寫的是他站在一座溪谷邊，望著遠處一座橋隱隱約約掛在山野的煙嵐裡，看不真切。他走到溪邊一塊突出的石磯旁，看見一艘漁船，就開口問船上的人——他想找的，是陶淵明筆下那個武陵漁人誤打誤撞進去的桃花源。傳說裡那個漁人沿著落滿桃花的溪流一路往上划，划到桃林盡頭，發現一個山洞，鑽進去以後別有洞天，裡頭的人過著與世隔絕、渾然不知道外頭改朝換代的日子。漁人出來以後，原本沿路做了記號，想著以後還能再找到，結果太守派人跟著記號去找，怎麼找都找不到，那個地方彷彿從沒存在過。

張旭望著眼前桃花整天整天地隨著水流漂過去，問船上的人，清澈的溪水裡，那個山洞到底藏在哪一邊？

隱隱飛橋隔野煙，石磯西畔問漁船。桃花盡日隨流水，洞在清谿何處邊。

他心裡其實清楚，這個問題自古以來就沒有人真正答得出來——連那個做了記號的漁人自己回頭去找，都找不到了。可是他還是問了。這就是張旭反差最大的地方：一個寫起字來瘋到能嚇壞旁人的人，寫起詩來，卻是這樣一個溫柔又帶點傻氣的提問，像個孩子一樣，明知道找不到，還是想問一句看看。狂草是他留給世人看的樣子，這一句輕輕的發問，才是他自己一個人面對山水時，真正的樣子。漁船上的人多半也答不上來，只能搖搖頭，繼續搖著槳往下游去。張旭站在石磯上，看著桃花一瓣一瓣漂遠，沒有再追問下去——有些答案，問出口那一刻，其實已經足夠了。`
  },

  // id=334 中唐 白居易 〈後宮詞〉rating=2
  // 詩眼：容顏還沒老，恩寵卻已經斷了
  // 隱藏連接：無（後宮制度縮影的代言體詩，非特定人物）
  334: {
    title: "後宮詞",
    author: "白居易",
    summary: "她的臉還沒老，可是皇帝的恩寵，早就已經斷了。",
    story: `跟你說我朋友樂天寫過一個宮裡的女人，一輩子都在等一場永遠不會來的寵幸。

樂天在朝廷裡做官，見多了宮裡的規矩——皇帝後宮動輒幾千個女人，可是能真正見到皇帝一面的，一輩子也就那麼幾個。剩下的人，進宮的時候都是十幾歲的年紀，滿懷著能被皇帝看一眼的念想，可是大半輩子就困在深宮的高牆裡，連皇帝長什麼樣子，可能都沒機會看清楚。樂天寫過不少這樣的詩，替這些沒有名字、沒有故事被記下來的女人說話，後宮詞就是其中一首。

詩裡這個女人，夜裡哭得整條絲帕都濕透了，連做夢都做不成——剛闔眼，又被自己的哭聲或者外頭的動靜驚醒。夜深了，前殿那邊隱隱約約傳來歌舞排演的聲音，她聽得出來，那是有新人正得寵，皇帝今晚多半是在那頭。她自己的臉，分明還沒老，皮膚還緊緻，眉眼還清秀，可是皇帝的恩寵，早在她還年輕的時候就已經斷了——不是等她人老珠黃才被冷落，是還沒等到真正被寵幸過，就已經被放在一邊了。

她沒有力氣再去猜今晚是誰得寵、又是哪個新人，這樣的夜晚她已經數不清經歷過多少回了，一開始還會傷心得整夜整夜掉眼淚，後來連哭都懶得哭出聲。她就只是斜靠在薰籠邊上——那是宮裡冬天用來薰香、順便取暖的一種竹製籠架，她靠著它，一直坐到天亮，衣角被薰籠的餘溫烘得暖暖的，可是心裡那塊地方，始終是涼的。

淚濕羅巾夢不成，夜深前殿按歌聲。紅顏未老恩先斷，斜倚薰籠坐到明。

樂天寫的不是某一個有名有姓的妃子，他寫的是後宮裡千千萬萬個這樣的女人的縮影。年輕貌美從來不是保障，在深宮這個地方，被冷落往往比容貌老去來得更早、更快，有的人進宮幾十年，連皇帝的面都沒見過幾次，卻已經在深宮裡從少女等成了老婦人。他把這首詩收進自己的新樂府一類的詩裡，想讓看到的人知道——宮牆裡頭，不是每個女人的故事都有機會被記住，可是至少這一首詩，替她們留了一盞天亮前沒滅的燈。這樣的女人，宮裡不知道還有多少個，樂天沒辦法把她們一個一個都寫進詩裡，也沒有辦法真的替她們改變什麼，只能寫下這一個，讓後來的人讀到的時候，多少想起她們曾經真實地存在過，在那一整座望不到頭的宮牆裡，安安靜靜地耗掉了一輩子。`
  },

  // id=346 中唐 劉方平 〈春怨〉rating=2
  // 詩眼：曾被許諾獨寵的金屋，最後成了沒人問的空院
  // 隱藏連接：劉方平終身未仕、隱居穎水，與詩中被冷落深宮的女子，同樣曾被安放在一個聽起來很好的位置上，卻沒人真的走進來看一眼
  346: {
    title: "春怨",
    author: "劉方平",
    summary: "金屋兩個字，曾是天底下最甜的承諾——後來變成了關住她一輩子的籠子。",
    story: `跟你說我朋友方平的一個習慣。他這輩子沒做過官，一年裡有大半時間住在洛陽近郊的穎水邊，沒事就往城裡走走，聽人閒聊。他聽故事的功夫，比很多當官的人還細——他總能從別人隨口一句話裡，聽出一整個人的委屈。

那年他在洛陽城裡，聽鄰居說起城東一戶大宅，裡頭鎖著一個女子，已經好幾年沒人提起她的名字。宅子蓋得很講究，金漆的窗框、雕花的樑柱，看起來富貴極了。可是白天很少開門，晚上也很少點燈。有人閒閒地說了一句，那屋子叫金屋——跟漢武帝小時候說要蓋金屋給阿嬌住的那個典故一樣的名字。

方平聽了心裡咯噔一下。當年那句金屋藏嬌，是天底下最甜的承諾，一整座屋子只為了一個人蓋。可是承諾這種東西，說出來的那天最值錢，之後只會一天天貶值。他猜這戶金屋，大概也是這樣開始的：曾經有人指著這棟屋子，說這裡以後只有你。後來人走了，屋子留下來，成了關她一輩子的籠子。

他這輩子沒有正經做過官，靠著幾個親戚朋友的接濟過日子，也因此常常在市井裡走動，聽的不是官場消息，是尋常百姓家的悲喜，這讓他寫起這種被冷落的宮怨，格外多了一分真實的體貼，不像有些文人只是憑空想像宮廷的華麗排場。

他站在巷口，看那扇緊閉的窗。紗窗糊得很細，夕陽一點一點從窗紙外頭滲進去，天色跟著暗下來，變成黃昏。方平猜屋裡那個人，此刻正一個人坐著，臉上有淚痕，卻沒有人看見，連鏡子都未必照得清楚，因為她可能連梳妝的心情都沒有了。

庭院裡沒有聲音。春天已經快過完了，寂寞把整個院子都佔滿。方平抬頭看院角那棵梨樹，花開得正好，可是沒有一個人踩進來看一眼，滿地梨花，安安靜靜地被落下、被踩爛、被遺忘，跟屋裡那個人一樣，沒人開那扇門。

方平把這一幕記在心裡，回去寫了四句話：

紗窗日落漸黃昏，金屋無人見淚痕。寂寞空庭春欲晚，梨花滿地不開門。

他自己一輩子沒有考過官，朝廷從沒點過他的名字，這件事外人看起來是可惜，他自己倒不太在意。但寫完這四句，他忽然覺得，這女子和他，某個地方竟然很像，都曾經被安放在一個聽起來很好的位置上，卻沒有人真的走進來看一眼。

那扇門，後來有沒有打開，方平不知道。他只知道，那年春天，滿院子的梨花開了又落，一直沒有人去撿。`
  },

  // id=347 中唐 李益 〈夜上受降城聞笛〉rating=2
  // 詩眼：望鄉不需要看見什麼，只需要聽見一個熟悉的調子
  // 隱藏連接：李益自己也是長年戍守邊塞、離家未歸的人，那一夜他跟士兵一樣，聽著蘆管說不出話
  347: {
    title: "夜上受降城聞笛",
    author: "李益",
    summary: "一整座城牆上的人同時想家——不是因為看見了什麼，是因為聽見了一支不知從哪傳來的笛聲。",
    story: `跟你說我朋友李益在西北邊塞待的那幾年。他不是隨便被派去的，是自己選的，年輕時考中進士，卻嫌內地官職升遷太慢，索性投身軍旅，跑到朔方節度使的幕府裡當差。那裡是黃河北岸，風沙比人多，冬天冷得能把人的骨頭凍裂。

受降城是唐朝為了防禦突厥築的三座城，由張仁願主持修建，分佈在黃河北岸一線。城牆很新，卻已經駐了好幾代戍卒。有一夜，李益跟一群士兵值夜，登上城樓透氣。眼前的沙地在月光下泛著白，遠遠望去像鋪了一層雪，其實一點都不冷得刺骨，是月色太亮，把黃沙照成了霜的顏色。

他知道，這裡的士兵大多不是自願來的，很多人一走十幾年，家書要輾轉好幾個月才能送到手上。他們白天訓練、修城、巡邊，看起來跟正常的軍人沒什麼不同。可是每到晚上，尤其是這種特別亮的月夜，所有人的臉色都會不一樣。

忽然，城牆某處傳來一聲蘆管的聲音。不知道是誰吹的，可能是伙夫，可能是哨兵，聲音斷斷續續，帶著點走調，卻剛好是每個戍卒小時候在自己家鄉都聽過的調子。李益站在城頭，看著身邊那些原本還在說笑的士兵，一個接一個慢慢不說話了。有人低下頭，有人望著遠方看不見的地方。

沒有人知道笛聲從哪個方向傳來，也沒有人問。因為答案不重要，重要的是那個聲音一響，一整座城牆上所有征人的心思，全部飄回了幾千里外的老家。

李益自己何嘗不是。他離開家鄉隴西已經好幾年，長年在各地軍府輾轉任職，家人的臉他有時候要想很久才想得清楚。那一夜他跟身邊的士兵一樣，聽著那支蘆管，說不出話。

他後來把這一夜寫成四句話：

回樂峰前沙似雪，受降城外月如霜。不知何處吹蘆管，一夜征人盡望鄉。

這首詩很快就傳唱開，甚至被譜成曲子，在軍營裡到處都有人唱。有意思的是，李益寫的不是自己想家，他寫的是一夜征人，是那一整座城牆上，所有跟他一樣的人，一起望向同一個方向。多年後，人們讀到這四句，依然能聽見那支不知從何處傳來的蘆管，依然會想起，思念這件事，從來不需要看見什麼，只需要聽見一個熟悉的調子。`
  },

  // id=355 晚唐 劉禹錫 〈再遊玄都觀〉rating=2
  // 詩眼：十四年後只剩自己一人站在原地，卻用四個字說我還在
  // 隱藏連接：與江雪柳宗元的生死之交，柳宗元病逝柳州後，劉禹錫接手整理他的遺稿、照顧他的遺孤
  355: {
    title: "再遊玄都觀",
    author: "劉禹錫",
    summary: "十四年前一首詩讓他被貶到天涯，十四年後他笑著回來，只說了四個字：我，又回來了。",
    story: `跟你說我朋友夢得中年以後最喜歡去的一個地方，是長安城南的玄都觀。準確地說，是他很想去，卻有十四年沒能踏進去。

他第一次寫玄都觀，是剛從朗州貶所召回長安沒多久。那時觀裡種了滿院子桃花，據說是他離開長安之後，一個道士新栽的。夢得看著滿樹桃花，順手寫了一首詩，末兩句挖苦得毫不客氣，說這些桃花全是他走了以後才栽的，暗指那些他離開長安後才靠著關係爬上來的新貴。這首詩傳到那些新貴耳裡，沒幾天他又被貶出京城，這次一走就是十四年，輾轉連州、夔州、和州，越貶越遠。

這十四年裡，他最放不下的一個人是柳宗元。兩人同一年被貶，一個去永州，一個去朗州，隔著幾百里通信，彼此的日子都不好過。柳宗元在永州寫下他那年冬天獨釣寒江雪的一個下午，寄給的正是夢得。後來柳宗元病死在柳州任上，四十七歲，沒能等到召回長安的那一天。夢得接手整理他留下的文稿，替他照看沒了父親的孩子，這是他這輩子最沉的一件事，比任何一次被貶都重。

他重遊玄都觀那天，特意選了個晴朗的午後，想著若真的什麼都沒了，至少陽光還在。走到觀門口，他甚至猶豫了一下要不要進去，畢竟上一次踏進這裡，換來的是十四年的流放，這一次他深吸一口氣，還是推開了門。

十四年後，夢得終於再回長安，第一件事就是重遊玄都觀。他心裡有數，這一次觀裡的桃花大概早就不在了，畢竟時間過去太久。他到了才發現，比想像中更荒涼：滿院子只剩一半是青苔，原本種桃花的地方全開了菜花，種桃的那個道士也不知道去了哪裡。當年得意的新貴，換了一輪又一輪，早就沒人記得那些桃花是誰栽的。

他站在滿地青苔的院子裡，柳宗元不在了，那批得罪過他的人也大半散了，只有他，又站在了原地。他忽然覺得，這種活著回來、站在原地的滋味，跟江雪裡那個獨自釣魚的柳宗元說的其實是同一件事，只要你還在，你就沒輸。

他提筆寫下：

百畝庭中半是苔，桃花淨盡菜花開。種桃道士歸何處，前度劉郎今又來。

寫完他笑了一下，這一笑裡有點得意，有點蒼涼。他知道這首詩傳出去，可能又要惹麻煩，但他已經不在乎了。十四年前那個因為一首詩被貶到天涯的年輕人，如今又站在同一個地方，笑著說了一句：我，又回來了。`
  },

  // id=382 晚唐 張祜 〈贈內人〉rating=2
  // 詩眼：自己被困住的人，卻拚命去救另一個要撲火的生命
  // 隱藏連接：張祜終身仕途不順，寫困守深宮的女子時，未嘗不是在寫自己被體制拋下、動彈不得的處境
  382: {
    title: "贈內人",
    author: "張祜",
    summary: "她自己被鎖在深宮裡連命運都動不了，卻在某個深夜，拚了命去救一隻要撲火的蛾。",
    story: `跟你說我朋友張祜寫過一整組宮詞，寫的都是他從沒見過面、卻聽人轉述過的深宮女子。他自己這輩子最想要的東西是一個官職，偏偏怎麼求都求不到，考了幾次都落第，靠著令狐楚的推薦進京，最後還是沒能留下來。他在長安晃了幾年，聽了不少宮裡流出來的閒話，其中一個女子的故事，他一直記在心裡。

那個女子被稱作內人，是宮裡負責歌舞、供皇室取樂的女子。這種身份說起來體面，住在宮牆裡，吃穿不缺，可是一輩子見不到宮牆外的世界，連自己家人想見一面都要層層通報。她的日子過得像被鎖在一個華麗的盒子裡，日復一日，沒有人問她想不想要別的人生。

張祜聽人說，這個女子有天晚上一個人待在殿外，月光照過禁門旁的樹梢，慢慢移過去。她能看的東西不多，眼前只有屋簷下窩著睡覺的鷺鳥。她就那樣看著，看了很久，沒有人陪她說話，甚至沒有人知道她在看什麼。

宮詞這種題材，張祜寫過不止一首，大多寫得很短，二十八個字，卻常常藏著一整段沒人知道的心事。他自己形容，這些深宮女子的故事，他多半是從教坊樂工、退休太監的閒談裡零零星星拼湊出來的，未必字字有據，卻件件都合情理。

後來燈影邊上飛來一隻蛾，一頭衝著燈火撲去。那火苗晃了一下，蛾翅膀燒到了。她原本什麼都沒做的手，忽然動了，她抽下頭上的玉釵，伸進燈裡，把那簇快要吞掉飛蛾的火苗撥開，硬是把那隻蛾從火裡救了出來。

張祜聽到這一段，愣了好一會兒。這個女子自己被關在宮牆裡，連自己的命運都動不了一根手指，卻在那一瞬間，拚盡全力去救一隻要撲火的蛾。沒有人救她，她卻去救別人。

他把這件事寫成四句話：

禁門宮樹月痕過，媚眼惟看宿鷺窠。斜拔玉釵燈影畔，剔開紅焰救飛蛾。

寫完之後張祜想，這個女子跟他自己竟然有點像。他這輩子想進的那個朝廷大門，對他來說也像一座禁門，怎麼求都求不進去；他手裡沒有玉釵，能做的頂多是把這些沒人看見的角落寫成詩，讓後來的人知道，宮牆裡曾經有這樣一個人，在誰都不知道的深夜，救過一隻蛾。

那隻蛾後來飛哪去了，沒人知道。那個女子後來怎麼樣了，張祜也沒能再聽到消息。只有這二十八個字，把那個瞬間留了下來。`
  },

  // id=385 晚唐 張祜 〈題金陵渡〉rating=2
  // 詩眼：隔著一條江，看著一點自己一輩子到不了的光
  // 隱藏連接：張祜一生求官不成、四處漂泊，這一夜的江邊燈火正是他人生處境的縮影
  385: {
    title: "題金陵渡",
    author: "張祜",
    summary: "對岸那兩三點燈火不是風景，是他這輩子求而不得、看得到卻摸不到的東西。",
    story: `跟你說我朋友張祜，晚年幾乎沒有一個固定的家。他年輕時求官不成，乾脆放棄了，四處遊歷，靠寫詩、靠朋友接濟過日子。這一年他走到金陵，天黑了還沒找到住的地方，最後在渡口邊一座不起眼的小山樓裡，租了一晚的房間。

金陵渡口是長江邊很熱鬧的一個渡頭，白天船來船往，商人、旅人、送信的差役都會在這裡上下船。可是一到晚上，喧鬧全部散去，只剩江水拍岸的聲音。張祜一個人待在小樓裡，身邊沒有一個認識的人，連店家跟他說話都帶著客套的疏離感。他躺下卻睡不著，索性起身，推開窗看江。

江水正在退潮，月亮斜斜掛著，照在江面上，把江水染成一種介於銀白跟暗青之間的顏色。他望向對岸，那裡是瓜州渡口，江對面同樣是個渡頭，同樣有人上岸、下船，可是隔著這條江，那邊的一切跟他完全無關。他只能看見兩三個小小的光點，那是瓜州岸上零星的燈火，在夜色裡忽明忽暗。

他年輕時也曾雄心勃勃，想著有一天能站上朝堂，替天下做點事。可是幾次應試都沒能如願，漸漸地，他也就不再執著於那條路，改成到處雲遊，靠著替人寫詩、寫墓誌銘賺點盤纏，換一個地方，就住一陣子。

張祜看著那兩三顆火光，忽然覺得胸口悶悶的。他這輩子求官不成，家也安不下來，走到哪裡都是這種借宿一晚、明天又要換地方的日子。眼前這條江，一邊是他暫時落腳的小樓，一邊是他完全不認識、也永遠踏不上的瓜州，中間隔著這一整條看不見底的江水，跟他這輩子求而不得的那些東西一樣，看得到，摸不到。

他知道自己這一夜大概是睡不好了，乾脆坐在窗邊，把眼前這幅畫面記下來，寫成四句：

金陵津渡小山樓，一宿行人自可愁。潮落夜江斜月裡，兩三星火是瓜州。

寫完他把筆放下，繼續看著那幾點火光，直到它們一顆一顆被夜色吞掉。天亮以後，他還是要繼續往下一個地方走，不會有人記得他在這座小山樓待過一夜。可是這四句詩留了下來，後來的人讀到兩三星火是瓜州，都會忽然明白，人生裡最深的孤獨，往往不是驚天動地的大事，只是隔著一條江，看著一點自己到不了的光。`
  },

  // id=427 晚唐 韋莊 〈荷葉杯〉rating=2
  // 詩眼：兩人都還活著，卻比死別更難相見
  // 隱藏連接：相傳韋莊念念不忘的謝娘，後來被蜀主王建強行收入身邊，兩人終生無法再見
  427: {
    title: "荷葉杯",
    author: "韋莊",
    summary: "相傳他愛的那個女子後來被自己投靠的蜀主奪走，他寫下的不是天涯永別，是比死更難見的距離。",
    story: `跟你說我朋友端己年輕時在長安，愛上一個姓謝的女子的故事。多年後這段回憶，變成他寫過最痛的幾首詞。

端己是韋莊，年輕時候在長安城裡混跡，結識了一個女子，人稱謝娘。相傳兩人是某個花下的深夜認識的，那晚水堂西面的畫簾垂著，兩人躲在簾子後面說話，一見面就聊得投機，臨走前還偷偷約定，以後要再見。那時候的端己還沒經歷過黃巢之亂，還沒流落到蜀地，人生正是最輕鬆、最敢許諾的年紀。

後來的日子他們確實見過幾次面，可是每一次都很短。有一次天快亮時分離，鶯在殘月下叫，兩人在城門邊道別，誰都沒說出這可能是最後一次這句話，但心裡都有點預感。分開以後，音訊漸漸斷了，不是誰不想寄信，是那年頭兵荒馬亂，長安幾度陷落，人一旦散了，想找也找不到。

端己晚年在蜀地寫過不少懷念長安舊事的詞，語氣總是淡淡的，不太肯把話說滿，可是懂他的人都看得出來，那些反覆出現的畫簾、水堂、殘月，說的其實都是同一件事、同一個人。

端己後來的人生，一路往南、往西漂，最後到了蜀地，投靠了王建。王建對他不薄，讓他當上宰相，寫下不少政令文書，算是亂世裡難得的安穩結局。可是相傳，端己晚年最惦記的那個謝娘，後來也流落到了蜀地附近，甚至有一說，她被王建看上、強行收進了自己身邊，端己想見都見不到，只能眼睜睜看著曾經跟自己有過約定的人，變成別人的所有物。

這件事真假難以考證，端己自己在詞裡沒有點名說是誰，只是反覆寫著同一種心事，兩個曾經在畫簾後面說好要再見的人，如今各自流落異鄉，一個困在權力身邊，一個困在朝廷公務裡，連寄一封信都要冒風險。

他把這段記憶寫進一首小詞：

記得那年花下，深夜，初識謝娘時。水堂西面畫簾垂，攜手暗相期。惆悵曉鶯殘月，相別，從此隔音塵。如今俱是異鄉人，相見更無因。

寫完之後，他把這首詞跟其他幾首放在一起，收進自己的詞集裡，沒有多做解釋。後人讀到如今俱是異鄉人，相見更無因這八個字，總覺得比任何哭喊都更冷，兩個人都還活著，卻比死別更難相見。`
  },

  // id=28 盛唐 王維 〈送綦毋潛落第還鄉〉rating=1
  // 詩眼：不說安慰的假話，用自己也曾被貶謫的經歷告訴朋友，這次沒被用上不代表沒有知音
  // 隱藏連接：王維早年因舞黃獅子事件被貶濟州，跟落第的綦毋潛同病相憐
  28: {
    title: "送綦毋潛落第還鄉",
    author: "王維",
    summary: "朋友落第心灰意冷，他沒說加油，只說了一句更重的話：這次沒被用上，不要以為懂你的人很少。",
    story: `跟你說我朋友摩詰送一個落第朋友回家的那個下午。這個朋友叫綦毋潛，兩人是長安城裡認識的，綦毋潛這次進京考試，又沒中。

摩詰自己也不是一路順風。他年輕時很早就中了進士，風頭正盛，結果沒幾年就因為一場舞黃獅子的表演犯了禁忌，被貶到濟州去當一個管糧倉的小官，遠離長安好幾年。那段日子他心裡清楚，不是自己沒本事，是運氣跟時機沒站在他這邊。所以當綦毋潛落第，一臉沮喪地要回鄉下老家，摩詰完全懂那種心情。

他沒有講什麼客套話安慰，直接說了一句挺重的話，聖明的時代不會留隱士，所有有才華的人最後都會被朝廷找回去。這句話聽起來像場面話，其實是摩詰自己走過的路。他懂得那種懷才不遇的委屈感覺很真實，但他也懂得，時機這種東西，早一點、晚一點，結果差很多。

綦毋潛這個人，史書留下的記載不多，只知道他後來還是考中了進士，只是比別人晚了幾年，這中間繞的彎路，多半就是摩詰這次送別詩裡沒有明說、卻句句都懂的那種滋味。

他跟綦毋潛聊起這幾年的事。綦毋潛這趟進京，在江淮一帶過了寒食節，又在京城裡趕著縫了一身春天穿的衣服，滿心以為這次能留下來，結果還是落榜。摩詰請他喝酒，在長安的路邊擺了一桌，兩人喝到有點微醺，聊起彼此這些年走過的彎路。

摩詰看著綦毋潛，想起自己當年在濟州碼頭邊，看著江船來來去去，心裡也是這種說不出的悶。他知道綦毋潛接下來要坐船南下，然後再從陸路走回家，這一路少不了要經過幾片荒涼的地方，天黑前遠遠的城牆會被落日照得只剩一個輪廓。

臨別時，摩詰把心裡想的話一次說完：

聖代無隱者，英靈盡來歸。遂令東山客，不得顧採薇。既至金門遠，孰云吾道非。江淮度寒食，京洛縫春衣。置酒長安道，同心與我違。行當浮桂棹，未幾拂荊扉。遠樹帶行客，孤城當落暉。吾謀適不用，勿謂知音稀。

最後這兩句他說得特別慢，這次的計謀沒被用上，不代表懂你的人很少。他自己就是懂的人之一，因為他也曾經站在被誤解、被貶謫的那一邊。

酒喝完，船也要開了。摩詰站在岸邊，看著綦毋潛的船慢慢離開長安。他知道，這次落第不是終點，就像自己那幾年被貶濟州也不是終點一樣。`
  },

  // id=30 盛唐 王維 〈渭川田家〉rating=1
  // 詩眼：羨慕的不是田園風景，是有個地方可以回去這件事本身
  // 隱藏連接：多年後王維真的在輞川買地隱居，渭水邊看到的柴門與麥田成了預告
  30: {
    title: "渭川田家",
    author: "王維",
    summary: "他看著別人黃昏歸家的畫面看到心裡發堵，多年後他真的替自己蓋了一扇可以回去的柴門。",
    story: `跟你說我朋友摩詰有一年黃昏，走過渭水邊一個小村子，看到的畫面讓他站住了很久。

那是傍晚時分，太陽已經斜斜掛在天邊，光線灑在一個個荒僻的村落上。牛羊正從外頭放牧的地方往回走，踏著窮巷裡的泥土路，揚起一點點塵土。村裡有個老人拄著拐杖，站在自家柴門邊，眼睛望著遠方，他在等自己放牛的孫子或晚輩回來。

摩詰站得稍遠，看見麥田裡野雞叫個不停，這時候麥苗正抽穗，長得茂盛；另一邊桑樹的葉子已經被蠶吃得稀稀落落，春蠶眠伏著，快要吐絲結繭了。這些都是最普通的鄉村景象，家家戶戶都在忙著同樣的事情。

摩詰寫這首詩的時候，還只是隔著官場的窗子，遠遠羨慕這種田園日子，他自己也說不清楚，這份羨慕，到底是一時興起的感慨，還是心裡早就埋下的種子。

田裡幹活的農夫扛著鋤頭，站在田埂上跟鄰居打招呼，說著些家常話，兩人聊得依依不捨，捨不得結束這段話。摩詰看著這一幕，忽然覺得心裡有點堵。這些人擁有的東西很簡單，一畦田、一群牲畜、幾句閒話，可是他們臉上那種安穩，是摩詰在朝廷裡從沒見過的。

摩詰這幾年在官場裡，見過太多爾虞我詐，升遷貶謫都由不得自己，今天站對邊明天就可能萬劫不復。他看著眼前這些農人，忙著養牛養蠶，卻沒有一個人露出他在長安官場常見的那種緊繃神色。他們的生活很累，可是累完了，天黑就回家，家裡有人等，有柴門可以推開。

他想起詩經裡那句式微式微，胡不歸，天快黑了，天快黑了，為什麼還不回家。那本來是勸人歸隱的老話，摩詰站在渭水邊，忽然覺得這句話問得很準，他自己何嘗不是，官場裡起起落落這麼多年，心裡一直有個模糊的念頭想歸去，卻一直沒有真正邁出那一步。

他把眼前的畫面寫成十句：

斜光照墟落，窮巷牛羊歸。野老念牧童，倚杖候荊扉。雉雊麥苗秀，蠶眠桑葉稀。田夫荷鋤立，相見語依依。即此羨閒逸，悵然吟式微。

寫完之後好多年，摩詰真的在輞川買了一片山水，蓋起別業，過起半官半隱的日子。那個黃昏他站在渭水邊看到的柴門、牛羊、老人和麥田，不是隨口寫寫，是一顆種子，多年後，他終於也推開了一扇屬於自己的柴門。`
  },

  // id=32 盛唐 孟浩然 〈秋登蘭山寄張五〉rating=1
  // 詩眼：登高望遠望的不是風景，是朋友所在的方向
  // 隱藏連接：張子容中第出仕、孟浩然終身未仕，兩人從同隱鹿門到天各一方
  32: {
    title: "秋登蘭山寄張五",
    author: "孟浩然",
    summary: "他登上一整座山，不是為了看風景，是為了看一眼老朋友所在的方向。",
    story: `跟你說我朋友浩然登蘭山那個秋天下午，其實不是去看風景，是去看一個人的方向。

浩然跟張五本名張子容是襄陽的同鄉，兩人年輕時一起在鹿門山隱居讀書，白天一起爬山，晚上一起喝酒論詩，好得跟親兄弟一樣。後來張子容去考了進士，中第了，被派去做官，兩人的日子從此分開，一個留在山裡繼續讀書、繼續等待機會，一個進了官場，天南地北地調動。

浩然這輩子最特別的一點是，他其實沒怎麼真的去考科舉，或者說考了沒中，索性徹底斷了念頭，一輩子沒有做官。旁人看著替他著急，他自己倒是活得挺自在，只是偶爾，比如這種秋天的午後，還是會想起那個曾經一起隱居的老朋友。

浩然這輩子交過不少朋友，太白、王維都跟他有過深厚的情誼，可是張五這種從少年時代就一起隱居的交情，是後來認識的朋友怎麼樣都比不上的，那是連彼此的沉默都能懂的那種默契。

那天他一個人登上蘭山，也叫萬山，山不算高，他站上去往北邊望。白雲裹著山頭，山裡那些真正的隱士圖的就是這份自在。浩然站在山頂，心思卻不在眼前的白雲上，他望著北邊，眼睛跟著一群往北飛的雁，一直看到雁群消失在天邊，那個方向，大概就是張五所在的地方。

暮色開始四合，一種說不清的愁緒跟著升起來，他告訴自己，這不完全是傷感，也是秋天這個季節本身勾出來的興致。山下有人正牽著牲畜往村子裡走，走到渡口邊停下來歇腳。遠處的樹小得像薺菜，江邊的沙洲看起來像一片月亮的形狀。

浩然站在那裡看了很久，愈看愈想，乾脆想好了一件事，等到重陽節，他要帶著酒去找張五，兩人像從前在鹿門山那樣，好好醉一場。

他把這份念頭寫成一首詩，寄給張五：

北山白雲裡，隱者自怡悅。相望始登高，心隨雁飛滅。愁因薄暮起，興是清秋發。時見歸村人，沙行渡頭歇。天邊樹若薺，江畔洲如月。何當載酒來，共醉重陽節。

這首詩寄過去以後，兩人有沒有真的在重陽節喝上那一場酒，史書沒有記載。但浩然這輩子沒有做官、沒有大富大貴，留下來的，恰恰是這種望著雁群消失的方向，還惦記著要跟老朋友喝一場酒的心思。`
  },

  // id=35 盛唐 王昌齡 〈同從弟南齋翫月憶山陰崔少府〉rating=1
  // 詩眼：同一片月光此刻正照著兩個相隔千里卻同樣想念彼此的人
  // 隱藏連接：無
  35: {
    title: "同從弟南齋翫月憶山陰崔少府",
    author: "王昌齡",
    summary: "他望著同一片月光，猜想千里外的朋友此刻大概也抬頭看著同一輪月亮。",
    story: `跟你說我朋友少伯跟堂弟一起賞月的那個夜晚，其實心思飄到了很遠的地方。

少伯是王昌齡，這輩子官運不算好，年輕時考中進士，後來輾轉做過幾個小官，仕途起起落落，始終沒能真正得志。他交朋友倒是很寬，各地都有幾個談得來的舊友，其中一個是崔少府，一個在山陰今浙江紹興一帶當縣尉的朋友。

那天晚上，少伯跟堂弟兩人在南齋裡閒坐，沒什麼特別的事，就是躺著聊天。他們把帷帳撩開，讓月光直接照進屋裡。月剛升起來，清冷的光灑在窗外的水面跟樹梢上，晃晃悠悠地映進屋子，灑在牆上、灑在兩人身上，那種光影晃動的感覺很輕，很安靜。

堂弟隨口說起，這月亮虧了又盈、盈了又虧，已經數不清多少回了，可是每次抬頭看，好像都不太一樣。少伯聽了點點頭，心裡想的是另一件事，這輪月亮清澄透亮，照過古人，也照著今人，亙古不變，可是月光下的人，一個一個都換了。

他想起崔少府這個朋友，人在山陰做官，此刻大概也在某個窗邊，望著同一片月光。少伯記得崔少府曾提過，他常常在清江邊上，對著這樣的月色，忍不住吟起越地那種帶著哀愁調子的曲子，山陰靠近古代越國，那裡的歌謠向來帶著一種淡淡的憂傷。

少伯坐在南齋裡，越想越覺得，眼前這片月光跟崔少府那邊的月光其實是同一片，只是隔了千里路。他跟堂弟說，不知道崔少府那邊怎麼樣了，這種掛念，說出來也沒什麼具體內容，就是很單純地，想起一個人。

他把這一夜寫成十句：

高臥南齋時，開帷月初吐。清輝淡水木，演漾在窗戶。苒苒幾盈虛，澄澄變今古。美人清江畔，是夜越吟苦。千里其如何，微風吹蘭杜。

寫完之後，一陣微風從窗外吹進來，帶著蘭草跟杜若的氣味。少伯跟堂弟兩人沒有再多說什麼，只是繼續躺著看月亮，各自想著自己惦記的那個人。這首詩沒有寄出去的記載，但少伯把這份想念寫下來的那一刻，崔少府或許真的也在千里之外，抬頭看著同一片月光。這種掛念沒有轟轟烈烈的表白，只是安靜地確認一件事：千里之外，總有一個人，此刻大概也正抬頭望著同一輪月亮，想著他。`
  },

  // id=42 中唐 元結 〈賊退示官吏并序〉rating=1
  // 詩眼：奉皇命辦事的官吏，比放過窮城的盜賊更狠
  // 隱藏連接：杜甫讀後深受感動，寫詩讚頌並抄錄教育子孫
  42: {
    title: "賊退示官吏并序",
    author: "元結",
    summary: "山賊沒搶的窮城，最後被自己朝廷的催稅使者逼到絕路——元結寫詩質問：奉皇命辦事的官員，難道不如盜賊？",
    story: `跟你說我朋友元次山的一段往事，發生在道州刺史任上的一個秋天。那一年道州城外全是逃難的人，家家戶戶把糧食埋進地窖，因為聽說西原蠻已經打下了附近好幾座城。可是道州城裡卻異常安靜，沒有人來搶。你猜為什麼。

因為窮。城太小，人太窮，連強盜都懶得進來。附近好幾座州縣都被打得城破人亡，唯獨道州，山賊繞城而過，看都懶得多看一眼。連年戰亂讓道州凋敝到這種地步，反倒成了它逃過一劫的原因。次山剛上任沒多久，看著滿城劫後餘生的百姓，心裡是慶幸的。他甚至想起自己年輕時候，曾在山林裡隱居整整二十年，門前就是山泉，屋後就是溶洞，日子過得緩慢，天黑了才睡，天亮很久了還能安睡，稅賦也是按老規矩交，從不催逼。那種太平年月，他以為早就過去了。

沒想到安史之亂一起，他被徵召從軍好幾年，輾轉多地，眼看著大半個天下都在打仗，最後才被派來當這個小郡的父母官。剛接手就遇上山賊圍城，僥倖躲過，鬆一口氣還沒幾天，朝廷催繳賦稅的使者就到了。

使者拿著公文，站在衙門口，逼得比賊還兇。他一句一句照著朝廷的規矩念，該收多少糧、該徵多少丁，一分都不能少，遲了就要治罪。道州人剛被搶過一次命，家裡的存糧本來就見底，現在又要被逼著交出最後一點口糧。次山看在眼裡，氣得提筆質問，這些奉皇命辦事的使者，難道不比強盜更狠嗎？強盜好歹留了道州一條生路，官府卻連這點餘地都不肯留。他想不通，同樣是拿人東西，為什麼披著官服的人，反而下手比山裡的賊寇還重。

他寫下這幾句：使臣將王命，豈不如賊焉。令彼徵歛者，迫之如火煎。誰能絕人命，以作時世賢。

寫完這首詩連同一篇序文，他直接抄送給轄下的官吏們看，等於當面斥責。他甚至動了辭官的念頭，想乾脆解下印綬，撐一根竹竿自己划船，帶著家人去有魚有麥的地方種田捕魚，歸老江湖，不再趟這渾水。

這首詩後來輾轉傳到了杜甫手裡。杜甫讀完深受震動，寫詩回應，把它與另一首舂陵行相提並論，稱讚兩篇像秋月一樣清亮，像星辰一樣難得，還說要抄錄下來教導子孫。一個小郡刺史的憤怒，就這樣透過另一位詩人的筆，留到了千年後。次山最終沒有真的划船歸隱，他繼續當著這個位低權輕的小官，一年一年，替道州人擋著催稅的使者。`
  },

  // id=43 中唐 韋應物 〈郡齋雨中與諸文士燕集〉rating=1
  // 詩眼：曾經橫行長安的紈絝侍衛，如今在自己最風光的酒席上，第一個念頭是替百姓感到不安
  // 隱藏連接：韋應物少年時是唐玄宗身邊放縱不學的侍衛，安史之亂後失勢才發憤讀書從政
  43: {
    title: "郡齋雨中與諸文士燕集",
    author: "韋應物",
    summary: "一場賓主盡歡的雨中宴會，座上這位刺史卻忽然說了一句讓滿堂安靜下來的話，他覺得自己住得太好，愧對治下百姓。",
    story: `跟你說我朋友韋應物的另一面。你如果只讀過他那些恬淡的山水詩，大概想不到他年輕時是什麼樣子。

十五歲那年，他就進宮當了唐玄宗身邊的三衛郎，說白了就是皇帝的貼身侍衛。仗著這層關係，他在長安街上橫著走，賭博、鬥雞、包庇亡命之徒，鄰里見了他都要繞道，連地方官都不敢輕易招惹他。他自己後來回憶這段日子，只用了八個字形容，少事武皇帝，無賴恃恩私。他那時候大字認不了幾個，成天想的只是今天要去哪裡鬥雞、跟誰賭錢。

安史之亂一爆發，玄宗倉皇出逃，靠山垮了，侍衛的差事也丟了。韋應物一夜之間從天子近臣變成無業遊民，昔日那些巴結他的人全都不見蹤影。他這才閉門讀書，一讀就是好幾年，把年少荒廢的功課一點一點補回來，從認字開始重新學起，一筆一劃跟著抄書，後來考中出身，一路做到郡守這個位置。這樣的轉折，放在誰身上都算得上脫胎換骨。

這天他在官署裡下著雨，擺了一桌酒席，請來城裡的文士聚會。兵衛在門外排開儀仗，戟上的漆光森然發亮；內室裡點著薰香，安靜清雅。海上刮來一陣風雨，池閣裡卻涼爽宜人。他這幾天身上的舊病剛好轉一些，滿座賓客正好都到齊，鮮魚肥肉這時節按規矩不能上桌，就用蔬果招待，大家也吃得盡興。他端起一杯酒，聽著席間有人吟誦文章，只覺得渾身輕鬆，像要乘風飛起來。

可是喝到一半，他忽然停下來，想起自己現在住的官邸有多高、多氣派，門外的儀仗有多森嚴，隨即說了一句讓滿座都靜下來的話，自慚居處崇，未睹斯民康。他覺得慚愧，自己住得這麼高，治下的百姓卻還沒過上安穩日子。那個曾經在長安橫行霸道、誰的死活都不放在心上的紈絝少年，如今坐在自己的酒席上，第一個想到的竟是別人過得好不好，這連他自己都覺得不可思議。

他後來又補了一句給在座的文士，說吳地文脈興盛，人才濟濟，可見這地方的底蘊不在錢財厚薄。席間有人勸他別想太多，難得聚一次，喝好酒、聽好詩才是正經事，他也只是笑笑，沒有反駁，但那句話已經說出口了，收不回去。宴席散去很久之後，人們記得的不是那頓酒席多豐盛，而是那句未睹斯民康，一個浪子回頭的官員，在自己最得意的時刻，替百姓感到不安。`
  },

  // id=46 中唐 韋應物 〈長安遇馮著〉rating=1
  // 詩眼：老友重逢，一句買斧頭的閒話裡藏著仕途死心後的心照不宣
  // 隱藏連接：無
  46: {
    title: "長安遇馮著",
    author: "韋應物",
    summary: "老朋友風塵僕僕從灞陵而來，韋應物問他進城做什麼，答案只是斧頭鈍了，要買一把新的。",
    story: `跟你說我朋友韋應物在長安城裡的一次重逢。那天他正在家裡，忽然聽見敲門聲，開門一看是馮著，好幾年沒見的老朋友，身上還沾著灞陵那邊的雨水。

灞陵是長安東邊出城必經的一個地方，橋頭種滿柳樹，是京城人送客的老地方，親友離別時習慣折一根柳枝相贈，取留的諧音。多少人在那座橋頭哭著道別，也有多少人從那座橋頭失魂落魄地走回城裡。馮著這身雨水，大概就是從灞陵那一路走過來沾上的，衣角還沒乾透。應物看著老友風塵僕僕的樣子，心裡先是一驚，馮著怎麼會突然出現在長安。

馮著這些年過得並不順。他早年也曾想在仕途上做出一番事業，跟應物一樣熬過幾年寒窗，可是幾次投謁、幾次落第，眼看著同輩一個個中舉、一個個外放做官，自己卻始終沒能踏進那道門檻，慢慢對官場死了心。這幾年他一直在終南山一帶過著半隱居的日子，靠採藥砍柴糊口，難得進一次城，平常連封信都懶得寫。應物明知道問了也是白問，還是隨口問了一句，你這趟進城，是為了什麼事。

馮著答得很輕鬆，說是山上砍柴的斧頭鈍了，特地進城來買一把新的。

這句話應物聽在耳裡，卻沒有半點輕鬆。一個曾經也想過在朝堂上有一番作為的人，如今進城最大的理由，只是買一把斧頭。他沒有多問馮著這幾年到底過得怎麼樣，兩人只是並肩站在院子裡，看著外頭花開得影影綽綽，新孵的燕子在簷下飛進飛出，忙著哺育雛鳥。

應物忽然算了算時間，才發現距離上次見面竟然已經隔了一整年，上一次分別還是去年，一轉眼又是春天。他側頭看馮著鬢角，幾縷白髮混在黑髮裡，藏都藏不住。他把這份感觸寫成了四句：客從東方來，衣上灞陵雨。問客何為來，采山因買斧。冥冥花正開，颺颺燕新乳。昨別今已春，鬢絲生幾縷。

兩人沒有多說什麼傷感的話。馮著買完斧頭，隔天就要回終南山去了，臨走前還開玩笑說，這把斧頭夠他再砍好幾年的柴。應物送他到城門口，看他背影消失在灞陵那一頭，就是他來時沾了滿身雨水的地方。老朋友的日子各自不同，一個在朝廷做官，一個在山裡砍柴，可是每次見面聊上幾句，好像什麼都沒變過，那份交情從沒因為境遇不同而淡了半分。`
  },

  // id=51 中唐 柳宗元 〈溪居〉rating=1
  // 詩眼：把被貶謫的災難說成幸運，是一個被整個朝廷放棄的人替自己找的活路
  // 隱藏連接：永州本地人因他是獲罪貶官而不敢往來，他常常一整天遇不到一個人
  51: {
    title: "溪居",
    author: "柳宗元",
    summary: "被貶到南方蠻荒之地，柳宗元卻說這是幸運，這句反話裡，藏著他撐過永州最孤獨歲月的方式。",
    story: `跟你說我朋友宗元搬進溪邊那間小屋的第一個早晨。永州城外，一條無名的小溪旁，他終於有了一個不用寄居寺廟的地方，雖然只是一間茅屋，但總算是自己的家。

在這之前，他借住在龍興寺好幾年，寄人籬下，連個像樣的書房都沒有，寫東西只能借僧人的桌案。這間溪邊小屋是他自己一點一點整理出來的，離永州城有點距離，清靜得幾乎沒有人會經過。他搬進來那天，心裡想的第一句話是，這輩子被官場的帽子和印綬綁得太久了，如今被貶到這南方蠻荒之地，竟然覺得是幸運。

這話聽起來像反話，其實是真心的。他這些年被朝廷冷落慣了，永貞革新失敗後，昔日同僚死的死、貶的貶，昔日一同議政的夥伴，如今天各一方，音訊斷絕，連一封信都要輾轉好幾個月才能收到。母親盧氏又在南下途中病故，他自己也大病一場，牙齒掉了、頭髮白了，走幾步路都要喘。長安城的那些人情往來、案牘公文，如今想起來只覺得疲憊，連夢裡都不想再回去。搬到溪邊之後，他學著像個農人那樣過日子，清晨起來，踩著露水翻整田裡的雜草，褲腳沾得全是泥；晚上划著小船回家，船底摩擦溪石發出聲響，成了他每天唯一固定會聽見的聲音。

沒有人來找他。永州本地人多半知道他是從長安貶下來的罪臣，怕受牽連，遠遠看見就繞道走，連平常打招呼都省了，市集上做買賣的人見了他也只是低頭裝作沒看見。他一個人耕田，一個人划船，一個人在溪邊坐到天黑，連個說話的對象都沒有。可是他沒有讓自己陷進那種孤單裡爛掉。他抬頭看看頭頂那片楚地的天空，湛藍湛藍的，忍不住扯開嗓子唱起歌來，聲音在空曠的溪谷裡傳得老遠，沒有人聽，他也不在乎。

他把這段日子寫成了八句：久為簪組累，幸此南夷謫。閑依農圃鄰，偶似山林客。曉耕翻露草，夜榜響溪石。來往不逢人，長歌楚天碧。

這首詩後來的人讀了，常常被那句幸此南夷謫打動，一個被整個朝廷放棄的人，把災難說成幸運，把孤獨唱成自由。宗元晚年沒有等到平反的那一天，可是溪邊那間小屋、那條沒有人經過的路，還有他一個人的歌聲，替他撐過了永州最難熬的那幾年。`
  },

  // id=65 盛唐 李白 〈長相思二首之二〉rating=1
  // 詩眼：一整晚換著樂器卻彈不完一首曲子的女子，心事無人可託
  // 隱藏連接：有學者認為此詩借思婦之口暗喻李白自己求仕無門的心境，並無確切史料佐證，誠實存疑
  65: {
    title: "長相思二首之二",
    author: "李白",
    summary: "她一整晚換了兩把琴，一首曲子都沒彈完，不是技藝生疏，是心裡的話沒有人能替她送到千里外。",
    story: `跟你說我朋友太白寫的一首詞，主角不是他自己，是一個他想像出來的女子。天色將盡，花朵籠在煙霧裡，月光皎潔得像雪，她卻一夜沒睡。

她原本坐在窗邊彈趙地的瑟，彈到一半忽然停手，鳳凰形狀的弦柱靜靜立在那裡，手指懸在半空，一動也不動。她又換了蜀地的琴，才想撥動刻著鴛鴦圖案的弦，又停下來，琴身還抱在懷裡，人卻已經失了神。她整晚就這樣換來換去，一首曲子都沒彈完，不是技藝生疏，是心思亂了，任何曲子彈到一半都會想起那個人，彈不下去，連指法都亂了套。屋子裡靜得能聽見燭火燃燒的聲音，窗外的月色一寸一寸挪過她的裙擺。

她想彈的這支曲子，其實是有心事的，可是身邊沒有人能懂，也沒有人能替她送到千里外，連個能說說話的丫鬟都不在跟前。她把琴瑟一件一件放下，走到窗邊，看著外頭的月色發呆。她想過，乾脆把這份心意託付給春風，讓風一路吹到燕然那邊去，那是漢朝大將竇憲當年打敗匈奴、刻石記功的地方，如今是她丈夫戍守的邊塞。隔著千里的天空，她只能對著月亮猜想，他現在過得怎麼樣，是不是也一樣睡不著，是不是也正抬頭看著同一輪月亮。

她想起從前，自己一雙眼睛顧盼生輝，人人稱讚她眼波流轉像水波橫生；可是這些年獨守空房，那雙眼睛早就不是從前的樣子了，天天流淚，活生生變成了一道泉水。她甚至賭氣地想，如果你不相信我心裡難受成這樣，那就回來，自己站在鏡子前看看我現在的臉。

太白把這些心事寫成了一首詞：日色已盡花含煙，月明欲素愁不眠。趙瑟初停鳳凰柱，蜀琴欲奏鴛鴦絃。此曲有意無人傳，願隨春風寄燕然。憶君迢迢隔青天。昔日橫波目，今成流淚泉。不信妾腸斷，歸來看取明鏡前。

相傳太白寫這首詩的那幾年，正是他在長安求仕無門、屢屢碰壁的時候，一次又一次遞出去的文章都石沉大海。有人說，這個對著鏡子以淚洗面的女子，其實也是他自己的影子，他也在等一個遲遲不肯回頭看他的君王，也不知道該把滿腹的曲子彈給誰聽。這說法查無實證，但太白這輩子寫過太多借女子之口說自己心事的詩，這首放在那幾年裡讀，確實特別像一面鏡子，照見的不只是一個等待的女子，還有一個等待被賞識的自己。`
  },

  // id=76 盛唐 杜甫 〈麗人行〉rating=1
  // 詩眼：眼前烈火烹油的盛宴，其實是帝國崩塌前最後一次奢華
  // 隱藏連接：兩年多後安史之亂爆發，詩中人物多死於馬嵬坡兵變
  76: {
    title: "麗人行",
    author: "杜甫",
    summary: "杜甫在曲江邊看了一整個下午的貴族春遊盛宴，寫下的最後一句，卻是誰也不敢議論的警告。",
    story: `跟你說我朋友杜甫在長安城外看到的一場春遊，日後想起來，像是一整個王朝崩塌前最後一次盛宴。

那年三月初三，上巳節，長安城的人照例到曲江邊踏青祓禊。子美那幾年正困居長安，求官無門，投獻的文章一篇又一篇送出去，回音卻少得可憐，日子過得緊巴巴的，經常要靠賣藥、靠朋友接濟過活，有時候一頓飯都要算計著吃。這天他也擠在曲江邊看熱鬧，人群裡擠得水泄不通，只不過看著看著，臉色沉了下來。

水邊那群女子，一個個姿態雍容，神情又濃豔又疏遠，皮膚細膩、身形勻稱，穿著繡花的羅衣，金線繡著孔雀，銀線繡著麒麟，在暮春的陽光下閃閃發亮。子美認出來了，為首的兩位正是虢國夫人、秦國夫人，當今貴妃的親姐姐，尋常百姓一輩子也見不到這樣的排場。她們頭上戴著翠玉葉片做的頭飾，一路垂到鬢邊；背後腰間的珠飾壓得裙擺服服貼貼，連走路的姿態都拿捏得恰到好處，每一步都像是排練過的。

她們的帳幕是雲錦搭的，因為是皇親國戚才有這個資格，尋常官宦人家連想都不敢想。侍從端上來的是駱駝峰做的湯，盛在翠綠的鍋裡；水晶盤子裡擺著白色的魚片。她們拿著犀角做的筷子，吃得心不在焉，廚子拿鸞刀細細切著肉，忙了半天沒人動幾口，滿桌珍饈剩下大半。宮裡派人騎馬送御膳過來，馬蹄快得不揚一點灰塵，一道接一道八珍佳餚流水般送到。簫鼓聲響得驚天動地，連鬼神聽了都要動容，子美擠在遠處的人群裡，聞著飄過來的香氣，肚子卻餓得發慌。

子美正看得出神，忽然人群一陣騷動，有人姍姍來遲，一路策馬到帳幕前才下馬，直接踏進錦繡地毯裡。楊花像雪一樣落在白色浮萍上，一隻青鳥叼著紅巾飛走了，像是在替誰傳話。子美這才看清楚來的人是誰。

他把這一幕寫進詩裡，最後幾句不再細寫排場，只留下一句冷冷的警告：炙手可熱勢絕倫，慎莫近前丞相嗔。滿座賓客沒有人敢多說一句話，連提都不敢提那個人和虢國夫人之間人盡皆知卻無人敢議論的曖昧傳聞。

子美寫完這首詩，把它收在袖子裡，誰也沒有大聲念出來過。兩年多以後，安史之亂爆發，這群人裡不少人死在馬嵬坡的兵變中。子美這天在曲江邊看到的，原來是那個王朝最後一次烈火烹油的盛宴。`
  },

  // id=80 盛唐 王維 〈老將行〉rating=1
  // 詩眼：曾經一劍擋百萬大軍的猛將，如今在門前賣瓜種柳，仍等著被重新召回的一天
  // 隱藏連接：詩中老將是綜合漢代名將與當代邊將遭遇塑造出的典型人物，並非實有其人，誠實標注
  80: {
    title: "老將行",
    author: "王維",
    summary: "門前賣瓜的老頭子，年輕時曾徒手搶下敵人的戰馬，王維寫的，是一個等著被重新想起的老兵。",
    story: `跟你說我朋友摩詰筆下的一個老頭子，門前擺著幾顆瓜，吆喝著要賣，沒有人知道他年輕時曾經一個人擋過百萬大軍。

摩詰這首詩裡的老將，不是哪一個真有名有姓的人物，是他把好幾個邊塞老兵的故事揉在一起寫出來的一個典型，但這樣的人，當時的長安城外到處都是。他十五歲不到就徒手搶了一匹胡人的戰馬騎走，山裡遇到吊睛白額的老虎，一箭射殺，那份膽氣，不比史書上鄴下那些少年英雄差。後來他上了戰場，一個人轉戰三千里，一柄劍曾經抵擋過百萬敵軍。漢軍衝鋒的時候像雷霆一樣猛，敵人的騎兵一看見他們插滿蒺藜的陣勢，遠遠就嚇得潰散。

摩詰寫到這裡，忽然筆鋒一轉，提起兩個漢朝的名字，衛青，一輩子打勝仗，可是史書上都說他多半靠運氣好；李廣，一輩子拚命卻始終沒有封侯，只能怪自己命數不濟。這兩句話看似是講古人，其實是在替眼前這位老將抱不平，功勞賞罰，從來就沒有真正公平過。

老將自從被朝廷擱置不用之後，人一下子就垮了，世事蹉跎，鬢角全白。當年箭法百發百中，箭箭正中要害，如今左手肘上都長出了贅瘤，連拉弓都吃力。他只能在路邊賣賣瓜，摩詰特地提了一句，這種賣瓜的營生，還是當年秦朝一位被貶的侯爺開的先例；他又學前人在門前種柳，打發日子。荒涼的古樹連著冷清的巷子，他一個人對著空蕩蕩的窗子，守著這片寥落的晚年。

可是他心裡那團火沒有熄。他發誓要像東漢名將耿恭那樣，在疏勒城缺水的絕境裡拜井求泉，也不要像西漢灌夫那樣，潦倒到只能借酒撒氣。就在他快要被世人遺忘的時候，賀蘭山下忽然戰雲密布，征調文書一天到晚傳來傳去，朝廷派使者到三河一帶招募壯丁，五路詔書同時發出去找將軍。

老將聽到消息，顫巍巍地把塵封已久的鐵甲拂拭乾淨，擦得像雪一樣亮，又把寶劍握在手裡，劍身上的星紋在光線下轉動。他把那把瓜刀放下，把種柳的鋤頭也放下，站在門前，望著賀蘭山的方向出神了好一會兒。他只求能拉開燕地的強弓，親手射下敵軍的大將，絕不讓外族的軍隊在自己的君王面前耀武揚威。他想對所有人說，別嫌我這個雲中太守是昨天的黃曆了，我還能再打一仗，立一次功。`
  },

  // id=83 盛唐 李頎 〈送陳章甫〉rating=1
  // 詩眼：昨天才被罷官，今天照樣買酒替朋友送行，把萬事看得比鴻毛還輕的灑脫
  // 隱藏連接：無
  83: {
    title: "送陳章甫",
    author: "李頎",
    summary: "剛被罷官的陳章甫，隔天照樣在東門買酒請客，李頎替他送行，寫下一句誰也答不上來的疑問。",
    story: `跟你說我朋友李頎在東門替一個朋友餞行的一個下午。那朋友叫陳章甫，前一天才剛剛丟了官，今天卻還是一副天塌下來也不當一回事的樣子。

四月的南風把大麥吹黃了，棗花還沒落盡，梧桐葉子已經抽得老長。陳章甫要沿著青山回鄉去，這一帶的山早上才剛道別，傍晚又能望見，他騎馬出門，聽著馬嘶，忽然想起了故鄉。這一帶山水他其實走過無數回，可是這一次，心境跟從前完全不同。

李頎認識陳章甫很多年了，兩人早年一起客居嵩山、洛陽一帶，論文論詩，情誼深厚。他最佩服的就是陳章甫這個人立身處世的坦蕩。他生得虯結的鬍鬚、老虎一樣的濃眉，額頭寬闊，一看就是個不好惹的人物；肚子裡卻藏著讀不完的萬卷書，從來不肯低頭去巴結那些草莽出身、只靠鑽營往上爬的人。這種脾氣，在官場裡是要吃虧的，陳章甫這些年幾次三番，官做得不順，眼看著資歷比他淺的人一個個升了上去，自己反倒昨天又被罷了官，可是他今天照樣在東門買酒請李頎喝，把萬事都看得比鴻毛還輕，臉上一點失意的樣子都看不出來。

兩人喝到日頭偏西還沒散席，陳章甫醉倒在座位上，渾然不覺天色已晚；醒了又望著天邊一朵孤雲發呆，不知道在想什麼。李頎看著他這個樣子，心裡替他難過，嘴上卻不敢說，怕一開口就戳破了陳章甫故意裝出來的輕鬆。長河的浪頭湧得又黑又急，渡口的船一時半刻過不去，兩人只能繼續在岸邊耗著，酒又添了一輪。

李頎想起自己也是鄭州一帶的人，如今客居洛陽，還沒能回家，聽著陳章甫要走了，忍不住替自己也嘆了口氣。他問陳章甫，聽說你老家那邊還有不少熟識的朋友，如今你罷官回去，不知道大家會怎麼看你這一場。

陳章甫沒有正面回答，只是又倒了一杯酒，笑著說天大地大，總有地方容得下他。李頎把這場送別寫成了一首詩，從南風吹黃麥子寫起，寫到虯鬚虎眉，寫到東門買酒，寫到長河浪頭連天，最後停在那句誰也答不上來的疑問裡，罷官昨日今如何。這首詩沒有寫陳章甫最後怎麼回答，因為連李頎自己也不知道答案，他只知道，不管明天過得怎麼樣，今天這杯酒，陳章甫喝得比誰都痛快。`
  },

  // id=86 盛唐 李頎 〈聽安萬善吹觱篥歌〉rating=1
  // 詩眼：一支從萬里之外的龜茲傳來的曲子，把滿堂客人的鄉愁都吹了出來
  // 隱藏連接：觱篥經絲路自龜茲、涼州輾轉傳入中原，安萬善的姓氏透露他可能是西域安國移民後裔
  86: {
    title: "聽安萬善吹觱篥歌",
    author: "李頎",
    summary: "一支用南方竹子做的樂器，吹出來的卻是萬里之外龜茲的調子，滿座賓客，沒有一個能忍住不落淚。",
    story: `跟你說我朋友李頎在一場夜宴上聽到的一支曲子，吹到後來，滿座客人沒有一個能忍住不掉眼淚。

吹奏的人叫安萬善，一聽這個姓，李頎就猜到他家世代大概是從西域安國一帶遷來的胡人，落籍中原也不知道幾代了，平常說話還帶著一點口音。他手裡那支樂器叫觱篥，是用南邊山裡砍來的竹子做的管子，可這門樂器根本不是中原的東西，最早是從龜茲，也就是今天的新疆庫車一帶，傳過來的，沿著絲路一路流轉，先到了涼州，又由涼州的胡人樂師帶進了中原，一路輾轉，經過幾代人的手，今晚才吹給李頎聽。

曲子一開始還算尋常，旁邊聽的人只是低聲讚嘆，端著酒杯有一搭沒一搭地聊著；可是吹著吹著，調子轉得越來越奇，滿座說話的聲音漸漸靜了下來，在座那些遠離家鄉客居異地的人，竟一個接一個紅了眼眶，連話都說不出來，有人乾脆別過臉去，假裝在看窗外。李頎心裡明白，這門樂器懂的人多，真正能聽出門道的人卻少，因為它的聲音本來就像長風一樣，在天地間自來自往，不是人人都跟得上它的心思。

一段旋律吹得像枯桑老柏在寒風裡颼颼作響，轉眼又變成九隻雛鳳亂糟糟地啼叫，接著龍吟虎嘯一齊迸發出來，像是萬千泉水匯聚成一整片秋天的聲音，聽得人渾身汗毛都豎了起來。李頎正聽得入神，曲調忽然一變，吹成了漁陽那一帶的軍樂，黃雲低垂，白日都顯得陰暗了下來。他心裡一凜，這是邊塞的殺伐之氣，彷彿下一刻就要聽見鼓角齊鳴。可是下一刻，調子又轉了，變成楊柳依依的春景，滿園繁花在眼前開得鮮亮如新，好像剛才那股肅殺全是幻覺，滿座的人這才鬆了一口氣。

那天晚上，堂上點著蠟燭直到深夜，燭淚積了老高，滿座的人守著一杯美酒，聽安萬善一曲接著一曲吹下去，誰都捨不得先開口說要散席。李頎後來把這一晚寫成了詩，從竹子產地寫到龜茲、涼州，寫到枯桑老柏、九雛鳴鳳，寫到漁陽的黃雲，寫到上林苑的繁花，最後停在那杯喝了一整夜也沒喝完的美酒上。他沒有寫安萬善這個人後來去了哪裡，只記得那支從萬里之外傳來的曲子，把滿堂客人的鄉愁都吹了出來。`
  },

  // id=92 盛唐 李頎 〈古從軍行〉rating=1
  // 詩眼：年年戰死的士兵，換回來的只是宮廷裡一顆好看的葡萄
  // 隱藏連接：借漢武帝求大宛汗血馬、葡萄種的典故，暗諷當朝對吐蕃、西域的用兵
  92: {
    title: "古從軍行",
    author: "李頎",
    summary: "士兵年年戰死在邊塞，李頎寫下的結尾卻只有一句冷冷的話，朝廷換回來的，不過是一顆葡萄。",
    story: `跟你說我朋友李頎寫的一首詩，表面上寫的是漢朝的事，其實他心裡想的是眼前這個朝代。

詩裡那個士兵，白天爬上山頭盯著烽火台，看有沒有敵情，黃昏又牽著馬到交河邊飲水，一天下來腳底磨出了新的水泡。他手裡提著刁斗，夜裡巡邏、白天煮飯都靠它，風沙打得天色昏暗，遠遠聽見有人在彈琵琶，那是當年遠嫁和親的公主留下的曲子，聽起來說不出的幽怨。四周是萬里荒野，連一座城郭的影子都看不見，雨雪連天，一路接到大漠深處，連個能躲雨的地方都找不到。天上南飛的胡雁夜夜哀鳴，連當地的胡人士兵聽了都忍不住掉淚，更何況這些千里迢迢從中原徵調來的漢家子弟，家鄉的模樣早就記不清了。

聽說玉門關那邊還在被人攔著不放回鄉的士兵通行，這個士兵知道自己這輩子大概是別想活著回去了，只能把命交給眼前這輛輕便的戰車，跟著它往前衝，連怕都來不及怕。年復一年，戰死沙場的士兵屍骨，就這樣一具接一具埋在荒外，沒人收，也沒人記得名字，只有秋天的風年年吹過那片荒地。

李頎寫到最後，筆鋒忽然轉了個方向，他沒有寫哪一場仗打贏了，也沒有寫哪一位將軍立了什麼功勳，只留下一句冷冷的結尾，這麼多年輕人死在邊塞，朝廷換來的是什麼，只不過是幾串葡萄種子，被人千里迢迢帶進了長安的宮廷裡，種在誰也不會多看一眼的園子角落。

這句話表面上講的是漢武帝當年為了求大宛的汗血寶馬和葡萄，派李廣利勞師遠征，死傷慘重才換回幾株葡萄苗種進了皇家園林。可是李頎活著的時代早就不是漢朝了，他寫的這些邊塞景象，交河、玉門關、大漠，其實正是當朝屢屢對吐蕃、對西域用兵的地方，戰報一份接一份送進長安，卻沒有人真正數過死了多少人。他借著漢朝的名字，把自己這個時代的話說了出來，因為有些話，直說是要惹禍的。

這首詩後來的人讀起來，很少有人真的把它當成單純懷古之作。年年戰死的士兵換不回一寸太平江山，換回來的只是宮廷裡一顆好看的葡萄，這句話擺在任何一個窮兵黷武的年代，都像是專門寫給那個時代聽的，而寫詩的人自己，卻只能把這句話藏在漢朝的外衣底下。`
  },

  // id=117 盛唐 杜甫 〈春宿左省花隱掖垣暮〉rating=1
  // 詩眼：九死一生才換來的職位，他捨不得閉眼，怕誤了明早進諫的時辰
  // 隱藏連接：他是穿著破麻鞋、衣袖露出兩肘，從叛軍占領的長安逃到鳳翔見皇帝的（《新唐書》有載）
  117: {
    title: "春宿左省花隱掖垣暮",
    author: "杜甫",
    summary: "所有人以為值夜班很無聊——他捨不得睡，是因為這個能講話的位置，他等了大半輩子才換到。",
    story: `跟你說我朋友子美的一個晚上。門下省的院子裡，暮色把牆邊那叢花蓋成一團模糊的影子，只剩幾隻歸巢的鳥啾啾叫著飛過去，別的，什麼聲音都沒有。他一個人坐在值房裡，一整夜沒睡。

你可能覺得奇怪，值夜班有什麼好緊張的。但你得知道，這個位置他是怎麼換來的。至德二年，長安還在叛軍手裡，子美本來已經逃出城，半路又被抓回去，困了快一年。後來他抓準機會，從一個城門的縫隙鑽出去，一路往北走，找當時逃到鳳翔的肅宗皇帝。史書上寫他到的時候，麻鞋見天子，衣袖露兩肘——草鞋磨穿了，袖子破了兩個洞，露出手肘，狼狽得不成樣子。皇帝看他這副模樣，倒是動了心，給了他一個左拾遺的官職。

左拾遺，品級不高，卻是皇帝身邊能講話的位置。子美四十六歲了，前半輩子考試落第、投詩求官都沒結果，這是他第一次真正站到了能講話的地方。他怎麼捨得隨便睡過去。

那晚他值宿在左省，院牆邊那叢花早就隱沒在暮色裡，剛才幾隻啾啾叫的歸鳥也飛得看不見了。他抬頭看星星，好像因為千家萬戶的燈火而跟著晃動；月亮貼著宮牆那頭的天空，看起來比別處都要大、都要亮，那是離皇帝最近的方向。他坐著，聽風吹過院子，恍惚間好像聽見有人騎馬過來，玉珂叮噹作響——那是官員上朝的馬飾聲。可是巡夜的更聲很安靜，什麼都沒有，只是他自己太緊張，一點動靜都要疑心一下。

他其實是在等一個聲音，宮門開鎖的金鑰聲。那個聲音一響，天就快亮了，早朝要開始，他明天有一份密封的奏事要遞上去。封事這種東西，得皇帝親自拆開看，措辭得反覆斟酌，遞晚了、遞錯了都不行。他一趟一趟問值夜的小吏，現在幾更了，夜還有多長，天什麼時候才會亮。

花隱掖垣暮，啾啾棲鳥過。星臨萬戶動，月傍九霄多。不寢聽金鑰，因風想玉珂。明朝有封事，數問夜如何。他把這些寫下來，不是在炫耀值夜有多辛苦，是在記一種他自己都覺得不可思議的心情——這輩子頭一次，有一件事重要到讓他捨不得閉眼睛。

那叢花、那幾隻歸鳥，早就融進暮色裡看不清楚了。江山風雨他還沒真正遇上，那是幾個月後的事——他因為替房琯說話觸怒皇帝，被貶到華州，從此再沒回過這麼靠近皇帝的位置。但那一夜他不知道往後會這樣。他只是坐著，一遍一遍問夜色還剩多長，像一個終於被准許上場的人，捨不得眨一下眼睛。`
  },

  // id=128 盛唐 王維 〈歸嵩山作〉rating=1
  // 詩眼：政治靠山倒了，他不是被貶，是自己先一步關上那扇門
  // 隱藏連接：張九齡罷相，王維失去朝中唯一真正提拔過他的人
  128: {
    title: "歸嵩山作",
    author: "王維",
    summary: "沒人趕他走，他是自己先收拾行李——因為朝裡唯一懂他的那個人，先垮了。",
    story: `跟你說我朋友摩詰的一次搬家。開元二十幾年那個秋天，他把長安的官服收進箱子裡，雇了輛牛車，往嵩山去。車馬走得很慢，慢到像是在跟這座城市告別。

摩詰入朝做官，靠的是張九齡。張九齡是當朝少見肯認真看詩、看人的宰相，把他從一個閒散的小官提拔成右拾遺，是那幾年裡唯一真心提攜過他的人。摩詰記得剛得到這個任命的時候，自己還特地寫了一首詩去謝張九齡，話說得誠懇，一點都不是官場上的客套。可是好景不長，張九齡跟另一派的李林甫鬥，輸了，被貶到荊州。消息傳來那天，摩詰寫信給他，說的是敬佩，不是求助——他心裡清楚，自己在朝裡的靠山沒了，往後的路，李林甫那批人不會待他客氣。他甚至想過，要不要主動去攀附新得勢的那一派，可是想了想，還是放不下這口氣。

他沒有等著被排擠出局。他選擇自己先走一步。收拾行李那天，他心裡很平靜，甚至有點輕鬆——這輩子第一次不是被誰安排去哪裡，是自己決定要去哪裡。

車出了城，沿著一條清澈的溪流走，溪岸兩邊長滿了高高的草，把水面遮出一條蜿蜒的暗綠色帶子。車馬走得不急，他也不催。看著溪水一路往前流，忽然覺得那水好像也懂他的心思，不是無情地流走，是陪著他一起往前走。傍晚時分，幾隻鳥從林子裡飛出來，跟他的方向一樣，也往嵩山那頭去，好像陪他一起回家。

路過一座荒城，城牆邊挨著一個古老的渡口，已經很久沒什麼人用了，渡口的木樁都朽得發黑。夕陽把整片秋天的山染成一種很滿很滿的橘紅色，不是蕭索，是一種鋪滿到看不見盡頭的溫暖。他站在渡口邊看了很久，沒有催車夫上路，心裡想的是，長安那些朝堂上的爭鬥，此刻竟然一點都撼動不了眼前這片山。

嵩山越來越近，他知道再往前走，人事、朝堂、張九齡的官司，都會被留在身後。到了山腳下，他叫車夫停下，自己走完最後一段路，鞋底踩過落葉，發出很輕的聲響。到家那天，他把門關上——不是逃避，是終於不用再應付誰的臉色，也不用再去猜哪句話該說、哪句話不該說。

清川帶長薄，車馬去閑閑。流水如有意，暮禽相與還。荒城臨古渡，落日滿秋山。迢遞嵩高下，歸來且閉關。這八句話，語氣很輕，沒有一句抱怨張九齡的失勢，也沒有一句咒罵李林甫。摩詰後來還是回了長安，還是做官，還是寫了輞川那些詩。可是嵩山這一次的閉關，他心裡明白，是他第一次替自己做的決定——不是誰貶了他，是他自己先關上了這扇門。`
  },

  // id=142 盛唐 孟浩然 〈宿桐廬江寄廣陵舊遊〉rating=1
  // 詩眼：一個四十歲還沒有官職的人，夜宿孤舟，想念的不是功名，是當年一起喝酒的朋友
  // 隱藏連接：相傳孟浩然曾被王維偷偷帶進宮裡，因一句詩觸怒唐玄宗，從此斷了求官的念頭
  142: {
    title: "宿桐廬江寄廣陵舊遊",
    author: "孟浩然",
    summary: "他這輩子沒當成官——可那年桐廬江上的一場猿啼夜雨，寫下的思念，比很多官員的功名留得都久。",
    story: `跟你說我朋友浩然的一個晚上。桐廬江上，船停在岸邊過夜，山裡傳來猿猴的哀鳴，一聲一聲，聽得人心裡發慌。滄江在夜裡流得特別急，水聲不停。這樣的夜，他一個人躺在船艙裡，睡不著。

浩然這輩子沒當過官。年輕時候他在鹿門山隱居讀書，交遊的都是些不問功名的朋友，日子過得清閒。四十歲那年他才第一次進長安，想試著求一個出身。他詩寫得好，張九齡、王維都跟他交好，王維甚至曾經冒著風險把他偷偷帶進宮裡——相傳那天唐玄宗突然駕到，浩然來不及走，只好躲到床底下，被王維老實招認之後，皇帝倒也沒生氣，叫他出來念首詩聽聽。浩然念的正是那句不才明主棄、多病故人疏，意思是自己沒才能才被明君捨棄。玄宗聽了臉色一沉，說你自己從沒求過官，朕幾時棄過你，這話別賴到朕頭上——就這樣把他放回去了。這件事之後，浩然徹底斷了在長安當官的念頭，轉頭往江湖裡去，一漂就是後半輩子，襄陽的家，他也是走走停停，很久才回去一趟。

這一晚他人在桐廬江，離揚州還遠。風吹得兩岸樹葉沙沙響，一輪月照著江上他這艘孤零零的船，船身隨著水流輕輕晃著，艙裡的燈也跟著搖。建德這地方風景是好，山也秀氣，水也清澈，可終究不是他的家鄉。他想起年輕時候在廣陵——也就是揚州，又叫維揚——跟一群朋友喝酒論詩的日子。那時候誰都還沒有官職的煩惱，喝到興頭上就拍桌子大笑，划拳、賦詩、互相取笑誰的句子寫得爛，誰都不覺得往後的路會走成這樣孤單。

他坐起來，就著船艙裡的一點光，把這些心事寫成一封詩，打算寄給揚州那些老朋友。他寫山裡的猿啼，寫江水的急流，寫兩岸的風聲，寫月光下這艘孤舟——這些都是眼前的景，寫著寫著，才寫到心裡真正想說的話。夜深了，江面上的霧氣越來越重，他把筆放下，又拿起來，反覆改了幾個字，才覺得對得起這一夜的思念。

山暝聽猿愁，滄江急夜流。風鳴兩岸葉，月照一孤舟。建德非吾土，維揚憶舊遊。還將兩行淚，遙寄海西頭。他把眼淚也寫進去了，兩行，是真哭了，還是只是形容，已經分不清。

詩寫完，他把紙折好，想著等船靠岸就找人捎去廣陵。江上猿聲還在，水還在急流，浩然這一輩子沒當成官，可這些年裡，他這樣的夜晚寫下的詩，後來比很多當官的人留得都久。`
  },

  // id=153 中唐 劉長卿 〈送李中丞歸漢陽別業〉rating=1
  // 詩眼：曾經統帥十萬大軍的名將，被罷官後，連回家的方向都不確定
  // 隱藏連接：劉長卿自己也曾兩次被誣陷貶謫，送別這位老將時，寫的其實也是自己
  153: {
    title: "送李中丞歸漢陽別業",
    author: "劉長卿",
    summary: "他送一位罷官的老將軍上船——那個曾經一個人鎮住三邊的人，如今連該往哪裡去都不知道。",
    story: `跟你說我朋友文房送別一位老將軍的事。那天江邊風大，一個滿頭白髮的老人站在渡口，身邊沒有隨從，也沒有儀仗，只有一把舊劍別在腰間。文房看著他，一時不知道該說什麼。

這位李中丞，當年可是威風過的人物。他帶兵征討南方，手下十萬大軍，一聲令下，三邊——邊境三處要地——都能安穩下來，是靠他一個人的本事鎮住的。文房年輕時候聽過他的名號，那時候誰不知道李將軍，連街頭巷尾的孩子都拿他的名字編過歌謠唱。

可是眼前這個人，罷官了，被朝廷一紙文書打發回鄉，連個像樣的家業都沒留下。漢陽的舊宅，他離開太久，早就荒了，屋頂大概也漏了，院子裡的草也該高過人了。年紀這麼大，還這麼眷戀那個曾經清明的時代——不是捨不得權位，是捨不得自己還能做點事的那份用處。文房心裡明白，這種話不能直說，說了反而扎心，只能陪他喝幾杯酒，多說些不相干的閒話。

他想起這老將軍當年的樣子。獨立三邊靜，那是真本事，一個人撐住，邊境就沒有戰事。輕生一劍知，什麼時候豁出命去拼，只有他腰上這把劍知道，旁人看不見那些生死交關的瞬間。可是現在，大軍沒了，官印交出去了，只剩下這把劍還跟著他。

文房送他到江邊，看著他準備登船。茫茫的江漢水面在暮色裡看不到盡頭，老將軍站在那裡，像是也不知道自己該往哪個方向去——這困惑與其說是文房替他問的，不如說是文房自己心裡也有的困惑。

因為文房自己也不是沒吃過這種虧。他這輩子兩次被人誣陷貶官，一次貶到嶺南潘州，罪名含糊，說不清楚是誰在背後動的手。他太懂這種滋味了——不是打了敗仗被罷，是明明沒做錯事，一紙公文下來，半輩子的功勞說沒就沒。

船要開了，文房站在岸邊，看著老將軍的背影一點一點變小。流落征南將，曾驅十萬師。罷歸無舊業，老去戀明時。獨立三邊靜，輕生一劍知。茫茫江漢上，日暮復何之。他把這幾句寫下來，替老將軍問，也替自己問——一個人把命都交給了朝廷，到頭來，朝廷卻連他該往哪裡去都沒交代清楚。

江水一直往東流，老將軍的船漸漸看不見了。文房站了很久才轉身回去，那把舊劍的影子，他很久都沒能忘掉。`
  },

  // id=173 晚唐 許渾 〈秋日赴闕題潼關驛樓〉rating=1
  // 詩眼：明明是要去長安謀官的路上，他心裡想的卻已經是歸隱的漁樵生活
  // 隱藏連接：無
  173: {
    title: "秋日赴闕題潼關驛樓",
    author: "許渾",
    summary: "離京城只剩一天路程，他坐在潼關驛樓上喝酒，想的卻已經是打漁砍柴的日子。",
    story: `跟你說我朋友用晦的一個傍晚。潼關驛站的樓上，他一個人坐著，面前一壺酒，窗外滿山紅葉被晚風吹得沙沙響。這頓酒，喝得他心裡很不是滋味。

用晦這趟是要進京城的。潼關是進出長安最要緊的關口，東邊來的人，過了這道關，再往前走幾天就到帝都了。這條路他不是第一次走，可每次過潼關，心情都不太一樣。照理說，快要抵達京城謀官，應該是興奮的，可他坐在這驛樓上，喝一口酒，望著窗外，心思卻飄得很遠。

殘雲慢慢往太華山那邊聚攏，一陣疏疏落落的雨掠過中條山。這一帶的山水他很熟——用晦這人寫詩，寫著寫著十首裡有九首都帶著點潮氣，不是雨就是露水，不是江就是湖，後來的人開玩笑說他大概是水裡撈出來的，寫詩沒有不濕的。今晚這場雨，倒不是刻意找的景，是真的下在他眼前。

他看著樹色一路跟著山勢延伸出去，看不到頭；河水的聲音一路往海的方向去，聽起來也是遠得沒有盡頭。這一關過去，人就要往仕途裡去了，考功名，謀官職，見宰相，見同僚，見那些他早就摸熟的官場規矩。他不是沒有把握，只是心裡清楚，那條路走進去，大概就沒那麼容易回頭了。

他自己也覺得好笑，這頭一天還沒到長安，人還沒開始做官，已經開始想退路了。明天，或者後天，他就要到帝京了，見過該見的人，遞過該遞的名帖，說著那些場面話。可是今晚在潼關驛樓上，他喝著這壺酒，想的卻是山裡打漁砍柴的日子，那種不用見誰的臉色、不用揣摩誰的心思的日子。他甚至想，等哪天真做了官，做得順不順都好，總要留一塊地方給自己，像今晚這樣喝一壺酒。

紅葉晚蕭蕭，長亭酒一瓢。殘雲歸太華，疏雨過中條。樹色隨山迥，河聲入海遙。帝鄉明日到，猶自夢漁樵。他把這幾句寫在驛樓的牆上，或是隨手記在紙上，誰知道呢。

這人後來確實一路做了不算小的官，潤州、睦州都做過刺史，官服穿了好些年，公文批了好些年，可是終其一生，他寫得最多的，還是水，還是山，還是這種心裡放不下的漁樵夢。潼關這一夜的酒，他大概也沒想到，自己這輩子在仕途和山水之間，一直都在來回搖擺，沒有真正選定過哪一邊，也沒有誰逼他選。`
  },

  // id=183 晚唐 張喬 〈書邊事〉rating=1
  // 詩眼：邊塞詩少見的畫面——不是打仗，是難得的太平，用王昭君的墳墓見證這份得來不易的安靜
  // 隱藏連接：詩中青塚是王昭君之墓，她當年和親換來的和平，數百年後終於在詩人眼前的邊塞真正兌現
  183: {
    title: "書邊事",
    author: "張喬",
    summary: "別人的邊塞詩寫烽火白骨，他站在王昭君墓前看到的，卻是幾百年後終於兌現的太平。",
    story: `跟你說我朋友張喬的一次邊塞見聞。號角聲劃破清秋的空氣，一個戍守邊疆的士兵靠在城樓上，眼神很放鬆。這幅畫面，擱在別的邊塞詩裡，大概接下來就要寫廝殺、寫流血了。可是張喬這次寫的，偏偏不是那些。

張喬是晚唐人，考中進士之後遇上黃巢之亂，索性隱居九華山，一輩子沒真正做過什麼大官。這首詩應該是他早年遊歷邊塞時寫下的所見所感，那時候他還年輕，還沒經歷後來的亂世，看邊塞的眼光還帶著幾分新鮮。他站在那座戍樓附近，看著春風吹過一座青色的墳塚——那是王昭君的墓。相傳那座墓終年常青，連塞外的秋冬都不落草色，所以叫青塚。王昭君當年是漢元帝時候的宮女，容貌出眾卻始終沒被皇帝看見，後來自願請命遠嫁匈奴單于，一個人遠嫁到這片荒涼的土地，用自己一輩子的孤獨，換了漢朝和匈奴幾十年不打仗。

幾百年過去了，張喬站在她的墓前，看見的邊塞，竟然真的是她當年用命換來的樣子——白日落梁州，天色一點一點暗下來，大漠上沒有一兵一卒阻擋，連他這樣的外地遊客都能安安穩穩地在邊疆行走。這在邊塞詩裡，是很少見的畫面。別人寫邊塞，寫的是烽火、寫的是白骨，張喬眼前這一片，竟然是太平。

他站在青塚旁邊想，昭君要是知道，幾百年後有人能在她墓前這樣悠閒地看夕陽，會不會覺得，自己當年那趟遠嫁，值了。這念頭一起，他忽然覺得自己這趟邊塞之行，不只是看看風景那麼簡單。

他往遠處看，一條河靜靜流著，水色映著天光。蕃人對大唐的心意，他覺得就像這條河一樣，一直往南流去——南邊是中原，是大唐的方向。這不是他一廂情願的想像，是他親眼見到的，邊疆各族的人，現在願意跟大唐好好相處，不是被打服的，是真心願意，路上遇見的牧人見了他，也只是好奇地打量，沒有半點戒備。

調角斷清秋，征人倚戍樓。春風對青塚，白日落梁州。大漠無兵阻，窮邊有客遊。蕃情似此水，長願向南流。他把這些寫下來，不是要歌頌誰的武功，是想記住這份得來不易的安靜——一份從昭君那年開始，幾百年後終於算是兌現的承諾。

風還在吹，號角聲漸漸遠了。張喬站在青塚旁邊，久久沒有離開。`
  },

  // id=188 晚唐 僧皎然 〈尋陸鴻漸不遇〉rating=1
  // 詩眼：去找一個一輩子閒不下來、連自己種的花都等不及看它開的朋友
  // 隱藏連接：陸鴻漸就是陸羽，寫《茶經》的那位茶聖，皎然是他一生的至交
  188: {
    title: "尋陸鴻漸不遇",
    author: "僧皎然",
    summary: "他去找老朋友喝茶，又撲了個空——但這種撲空，他早就摸透了對方的脾氣，一點也不生氣。",
    story: `跟你說我朋友皎然去找陸鴻漸的一次撲空。他沿著一條野徑走，兩邊種滿桑樹和麻，路是新開的，因為鴻漸剛搬了家——雖然離城郭不算遠，住的地方倒是偏得像鄉下。

陸鴻漸，大概沒人記得這個名字了，可是提到他另一個稱呼，陸羽，你大概就懂了。這人小時候是個棄嬰，相傳被一個叫智積的和尚在湖邊撿到，養在寺廟裡長大，師父原本想把他訓練成一個誦經的小和尚。他不愛念經，愛的是茶，寧可挨罰也要偷偷跑去煮水試茶。後來他走遍各地山水，嘗遍各種泉水，研究怎麼種茶、怎麼煮茶，甚至能光靠喝一口就分辨出是哪條溪的水，寫出了後來被人叫做《茶經》的那本書，世人稱他茶聖。

皎然是個和尚，住在附近的寺院裡，跟陸鴻漸是幾十年的至交，兩人詩來詩往，唱和的作品加起來也有不少。兩人常常一起喝茶、一起聊天，可鴻漸這人有個毛病，閒不下來，常常一聲不吭就往山裡跑，去找新的水源，去看沒喝過的茶樹，一去好幾天，回來的時候身上還帶著山裡的泥土氣。皎然找他，十次有五次撲空，已經習慣了。

今天皎然走到他新家門口，籬笆邊上種著幾叢菊花，是鴻漸最近才種下的。秋天都到了，那些菊花卻連一朵都還沒開。皎然站在那裡看了一下，覺得這花跟鴻漸這人還真像，都是種下去了，卻等不及看它自己開花，人就已經跑遠了。

他上前敲門，敲了半天，連狗叫聲都沒有，家裡大概真的一個人都沒有。皎然也不氣惱，轉身去問西邊的鄰居。鄰居告訴他，陸先生往山裡去了，平常都要等到太陽偏西才回來。

皎然聽完笑了笑，沒有再等下去的意思。這種撲空，他經歷太多次了，早就不當一回事。他慢慢往回走，把這趟拜訪寫成了詩。

移家雖帶郭，野徑入桑麻。近種籬邊菊，秋來未著花。扣門無犬吠，欲去問西家。報到山中去，歸來每日斜。他寫的不是失望，是一種很熟悉的了解——鴻漸這個人，一輩子都是這樣，心思全放在山水泉茶上，連自己種的花開不開，都不是他惦記的事。

皎然知道，再過幾天，或者再過幾年，這些菊花總會開，鴻漸也總會回來，兩人總能再坐下來喝一壺茶。這樣的友情，不需要每次都撲個正著，懂他往哪裡跑，比堵在他家門口等，更像真正的老朋友。`
  },

  // id=194 盛唐 杜甫 〈野望〉rating=1
  // 詩眼：一個老病的人，騎馬出城眺望，卻連為國家出一點力的機會都沒有
  // 隱藏連接：他弟弟們正因戰亂分散各地、音訊全無，他寫這首詩時人在成都嚴武幕下勉強度日
  194: {
    title: "野望",
    author: "杜甫",
    summary: "他騎馬出城透氣，望向西山的戍樓、望向失散的弟弟，卻只看見自己老病無用的身影。",
    story: `跟你說我朋友子美在成都的一次騎馬出遊。那天他從草堂出來，騎著一匹瘦馬，往城郊走，想透透氣，也想眺望一下遠方。他年紀大了，身體也差，平常很少這樣出門，可那天心裡悶，坐不住。

那年是廣德二年，子美五十出頭，在成都嚴武的幕府裡掛了個閒職，總算有點微薄的俸祿可以糊口，日子雖然清苦，好歹不用再逃難。可他心裡並不踏實。往西邊看，松州、維州、保州三座城池還在駐軍防著吐蕃，戰事還沒真正停過；往南邊望，萬里橋橫在錦江上，橋是修得漂亮，橋下船來船往，看起來一片熱鬧，可他知道，這太平的表象底下，四處都不安穩。

他這幾年顛沛得厲害。前一年成都還發生過徐知道叛亂，他帶著家人連夜逃到梓州、閬州避難，好不容易才又回到草堂，屋頂還漏著雨，也顧不上修。這些年天下亂成這樣，他幾個弟弟——穎、觀、豐、占，早就被戰亂沖散，各自流落一方，音訊斷絕，他連他們現在人在哪裡、是死是活都不知道，寫過幾封信出去，也不知道能不能送到。想到這裡，他一個人站在天涯這頭，忍不住掉眼淚。

他也想過，自己這輩子還能做點什麼。年輕時候，他也曾經想著要輔佐明君，幹一番事業，致君堯舜上是他掛在嘴邊的話。可如今五十幾歲了，一身是病，眼睛花、耳朵背、牙齒掉了好幾顆，腿腳也不利索，能拿出來回報朝廷的，連一點涓滴般的微小貢獻都算不上。這種無力感，比窮困本身更難受。

他騎著馬，一路走到郊外開闊的地方，勒住馬韁，極目遠望。西山的白雪、南浦的清江、萬里橋、三城的戍樓，都在眼前鋪展開。可他看得越遠，心裡越是堵得慌，人世間的這些事，一天比一天蕭條下去，他一個人騎在馬上，連個能說話的人都沒有。

西山白雪三城戍，南浦清江萬里橋。海內風塵諸弟隔，天涯涕淚一身遙。唯將遲暮供多病，未有涓埃答聖朝。跨馬出郊時極目，不堪人事日蕭條。他把這些寫下來的時候，天色已經不早了。

子美後來還會離開成都，沿著長江一路漂泊到夔州、到湖南，再也沒能真正安穩下來，那幾個失散的弟弟，他這輩子大多沒能再見到。`
  },

  // id=199 盛唐 杜甫 〈閣夜〉rating=1
  // 詩眼：五更鼓角聲裡，他發現連臥龍、躍馬這樣的英雄，最後也不過一抔黃土，何況他這樣一個聽不到老友消息的病老頭
  // 隱藏連接：他的至交好友李白、鄭虔、蘇源明此時大多已經去世，音書斷絕，正是人事音書漫寂寥的來由
  199: {
    title: "閣夜",
    author: "杜甫",
    summary: "五更的鼓角聲裡，他想到連諸葛亮、公孫述都不過一抔黃土，自己這個病老頭，又何必計較這麼多。",
    story: `跟你說我朋友子美在夔州過的一個冬夜。他住在江邊一座借來的閣樓裡，天快黑透了，年關將近，白天短得讓人措手不及，好像時間存心要催著人快點老。霜雪剛停，天邊的雲散開一點，露出一片格外冷的夜空。

這是大曆元年，子美五十五歲，住在夔州，就是現在的四川奉節，三峽的入口。他這幾年身體垮得厲害，肺病、風濕都找上他，牙齒掉了大半，一隻耳朵幾乎聽不見，右臂也開始不聽使喚。這麼一個病弱的老頭，窩在江邊借來的房子裡過冬，身邊沒剩下幾個熟人。

天快亮的五更時分，遠處傳來鼓聲和號角聲，悲壯得很，那是軍營裡報時兼示警的聲音，這一帶常年駐軍，提醒著這片土地離戰事其實沒有多遠。他抬頭看，三峽上空的星河，倒映在江水裡，隨著水波一直晃動，好像連天上的星星都跟著這個亂世不安穩。

他想起這一帶埋著的那些人。附近有諸葛亮的祠堂，人稱臥龍；還有公孫述，當年自立為蜀地皇帝，相傳因乘馬奔逃而得名躍馬——一個是千古忠臣的典範，一個是稱帝一方的梟雄，兩種截然不同的活法，到頭來都成了黃土一坏，誰也沒能例外。子美想，連他們這樣轟轟烈烈的人物都逃不過這個結局，自己一個又老又病、什麼都做不成的人，又何必計較這麼多。

他這些年真正在意的，其實是朋友。李白早幾年就死在當塗了，消息傳來的時候他傷心了很久；鄭虔死在台州，蘇源明死在長安，一個一個，他認識的、投契的人，漸漸都不在了。剩下的那幾個，山高水遠，書信也常常斷了聯繫，有時候半年、一年都等不到一封回信。這種寂寞，比窮困、比生病都難捱，不是沒人陪他說話，是那些真正懂他的人，一個個都走了，或者聯絡不上了。

歲暮陰陽催短景，天涯霜雪霽寒霄。五更鼓角聲悲壯，三峽星河影動搖。野哭千家聞戰伐，夷歌數處起漁樵。臥龍躍馬終黃土，人事音書漫寂寥。他把這些寫在紙上，窗外的鼓角聲還沒停，江水還在往下游流。

子美自己大概也沒想到，兩年後他會死在湘江的一條小船上，而這一夜寫下的八句話，後來被許多人認為是他晚年最見功力的一首詩。`
  },

  // id=200 盛唐 杜甫 〈詠懷古跡五首之一〉rating=1
  // 詩眼：他在憑弔兩百年前的一個人，卻越寫越覺得寫的是自己
  // 隱藏連接：庾信被扣留在北方一輩子回不了故國江南，晚年寫下最悲愴的作品《哀江南賦》，杜甫此刻的處境幾乎是他的翻版
  200: {
    title: "詠懷古跡五首之一",
    author: "杜甫",
    summary: "他寫的是兩百年前一個回不了家的南朝文人，寫著寫著才發現，那根本是他自己的日記。",
    story: `跟你說我朋友子美在夔州憑弔一個死了快兩百年的人。他這幾年常常想起庾信，不是因為讀他的賦讀得多熟，是因為越讀越覺得，那個人寫的簡直像是自己的日記。

庾信是南朝梁的人，年輕時候在宮廷裡寫些華麗精巧的詩賦，算是那個時代最頂尖的文人之一。後來梁朝派他出使西魏，人還沒回來，建康那邊就出事了，侯景之亂，接著江陵又被西魏攻破，梁朝實際上已經亡了。庾信這下子回不去了，西魏，後來的北周，把他留下來做官，表面上待他不薄，官位給得不低，可他心裡清楚，自己是個亡國之人，困在異鄉，再也見不到江南的山水，見不到故國的模樣。他這樣一困，就是後半輩子，直到老死都沒能回去。晚年他寫了一篇哀江南賦，把亡國之痛、思鄉之情，寫得極盡蒼涼，是他一輩子文章裡最重的一筆。

子美讀到這些，坐在夔州的屋子裡，忍不住覺得自己這條路，跟庾信走得太像了。安史之亂從東北的范陽燒起來，他跟著整個天下一起被打散，支離東北風塵際，說的就是這個。這幾年他一路往西南漂，從長安到秦州，到成都，再到夔州，漂泊西南天地間，沒有一個地方是能真正落腳的家。夔州這一帶，三峽的樓閣高聳，日月好像都被關在峽谷裡流動得特別慢；這裡住的還有五溪一帶的少數民族，他們的衣服樣式跟中原不同，子美如今就住在這些異族鄰居中間，活得像個異鄉人。

他也想到安祿山，那個本該效忠大唐、卻反過來把整個帝國攪得天翻地覆的胡人將領，羯胡事主終無賴，這口氣，子美嚥不下去。他這樣一個寫詩的人，遇上這樣的亂世，哀傷著，卻連回長安、回洛陽的機會都沒有，詞客哀時且未還，這句寫的是自己，也是庾信，兩個人隔著兩百年，活成同一種處境。

支離東北風塵際，漂泊西南天地間。三峽樓臺淹日月，五溪衣服共雲山。羯胡事主終無賴，詞客哀時且未還。庾信平生最蕭瑟，暮年詩賦動江關。他寫到庾信晚年最蕭條落魄的那幾年，反而寫出了最動人心魄的辭賦，一直震動著長江邊這一整片土地。

子美擱下筆，忽然覺得，自己這幾年在夔州寫的這些詩，說不定，也會是這樣。`
  },

  // id=201 盛唐 杜甫 〈詠懷古跡五首之二〉rating=1
  // 詩眼：千年後認出同一種懷才不遇，在宋玉舊宅前為自己掉淚
  // 隱藏連接：杜甫寫詩時正逢嚴武病逝、自己漂泊失所，跟宋玉當年懷才不遇的處境隔代呼應
  201: {
    title: "詠懷古跡五首之二",
    author: "杜甫",
    summary: "一個五十五歲、剛失去唯一靠山的老人，站在戰國辭賦家的塌牆舊宅前，忽然為一個素未謀面、死了快一千年的人掉下眼淚，因為他終於看懂了，那個人的悲傷，原來就是自己的悲傷。",
    story: `跟你說我朋友子美，五十五歲那年站在一間快要塌掉的老房子前面，站了很久很久。那是夔州城外，傳說是戰國時代宋玉住過的舊宅，牆塌了大半，滿地都是風吹落的枯葉。他不是路過，是特地繞過來的。

那幾年他過得很慘。靠山嚴武病死在成都，他在草堂待不下去了，只好帶著一家老小順江東下，一路漂泊，暫時落腳夔州，租了間破屋子住。這年秋天，滿山滿谷都在落葉，他走出城，聽人說附近有座宋玉的舊宅，就繞路過去看。

宋玉是誰？戰國末年楚國人，據說是屈原晚一輩的門生，辭賦寫得極好。他那篇〈九辯〉開頭一句「悲哉秋之為氣也，蕭瑟兮草木搖落而變衰」，把整個秋天寫成一種說不清楚原因的悲傷，草木凋零，萬物一下子都衰颯下來，那種心情，杜甫小時候背書時就背過，可是一直到這一刻，站在滿地落葉裡，他才真正懂了那句話在講什麼。

宋玉還寫過〈高唐賦〉，說楚王在雲夢澤一座高臺上做了個夢，夢見巫山神女，神女說自己「旦為朝雲，暮為行雨」，後來「雲雨」這個詞就是這樣來的，一路流傳到今天。可是杜甫沿路打聽，那座傳說中的高臺早就荒廢了，連確切位置都沒人說得準。

杜甫想的不是雲雨的故事，是宋玉這個人，一肚子才學，一輩子卻沒真正被重用，連舊居在哪裡，後人都吵不清楚。他自己呢？年輕時也以為能做出一番事業，一心想輔佐皇帝做出堯舜那樣的太平盛世。可是安史之亂一起，半生顛沛，官只做到左拾遺又被貶，晚年連一間穩定的房子都沒有，靠朋友接濟過活，如今還要繼續往下游漂。宋玉在戰國末年懷才不遇，他在安史之亂後懷才不遇，中間隔了快一千年，可是那種明明有本事、卻沒人真正用你的滋味，一模一樣。

他站在宋玉舊宅前，想著自己這一路，眼眶忽然就熱了，提筆寫下：

搖落深知宋玉悲，風流儒雅亦吾師。悵望千秋一灑淚，蕭條異代不同時。

寫完他又接著寫，宋玉的舊居和留下的文章倒還看得出形跡，但當年雲雨高臺的故事，恐怕也只是一場誰也說不準的夢；到頭來，整個楚國的宮殿都已經灰飛煙滅，只剩下江邊擺渡的船夫，偶爾指著一處土堆，說那大概就是舊址所在，說完自己也不太確定。

杜甫把筆放下，回頭又看了一眼那間塌了大半的老宅，滿地落葉還在風裡打著轉。四年後，他死在湘江的一條船上，沒能回到家鄉。可是他這天在江邊落下的眼淚，讓宋玉這個名字多了一位一千年後的知音，那份隔了一千年才被認出的悲傷，後來變成每一個懷才不遇的人看見滿地落葉時，都會想起的一句話。`
  },

  // id=213 盛唐 李頎 〈送魏萬之京〉rating=1
  // 詩眼：把自己踩過的長安陷阱，原封不動指給即將出發的年輕人看
  // 隱藏連接：魏萬後來追著李白走了三千里路，成為替李白整理詩稿、編成《李翰林集》的人
  213: {
    title: "送魏萬之京",
    author: "李頎",
    summary: "送一個還沒出名的年輕人去長安那天，李頎把自己走過的彎路全說成了臨別叮嚀，他沒想到，這個年輕人後來會追著李白走三千里路，替中國最偉大的詩人守住了一整批詩稿。",
    story: `跟你說我朋友李頎，送一個年輕人上路那天的事。那年輕人叫魏萬，還沒出名，剛決定要去長安闖一闖。李頎比他年長不少，也算半個過來人，考中進士之後，仕途一直不算得意，做過新鄉縣尉，官不大，早年也曾經在長安待過，長安那套先驚豔、後消磨的把戲，他看得很清楚。

送行那天是秋天，清早天還沒全亮，魏萬就要動身。頭天夜裡下過一層薄霜，黃河邊的渡口冷得刺骨。李頎聽見魏萬唱起送別的驪歌，聲音在河面上飄得很遠。他站在岸邊，看著這個比自己小了一大截的年輕人，忽然想起自己當年也是這樣，滿懷抱負，覺得長安遍地是機會，什麼都攔不住自己。

魏萬要走的這條路，李頎太熟了。北方大雁往南飛，叫聲淒厲，趕路的人聽了最容易心裡發慌；雲霧籠罩著遠山，一個人在外地做客，看著更覺得孤單。過了潼關，快到長安的城郊，樹葉的顏色一天比一天深，催著寒意逼近；宮苑附近入夜以後，搗衣的砧聲此起彼落，一聲聲提醒人，冬天要來了，家人在為出門在外的人添製寒衣。這些都是李頎自己走過的路，此刻原封不動搬到魏萬眼前。

李頎沒有多說什麼豪言壯語，他知道年輕人最缺的不是鼓勵，是提醒。長安太漂亮了，尤其對第一次進城的人，宮闕巍峨、酒肆熱鬧、才子雲集，一個不小心，幾年就能在那種熱鬧裡晃過去，回頭才發現自己什麼都沒做成。他自己年輕時也曾經被那種繁華晃花了眼，蹉跎過幾年才想明白。

送行的話說到最後，他提筆寫下：

莫見長安行樂處，空令歲月易蹉跎。

意思很直白：別把長安只當成一個享樂的地方，不然一晃眼，好幾年就這樣白白蹉跎過去了。這不是老生常談的客套話，是李頎把自己踩過的坑，原封不動指給魏萬看。

魏萬後來到了長安，果然沒有虛度。他一路往南，聽說當時最紅的詩人李白就在江南一帶，竟然追著找了他三千里路，終於在廣陵見到本人。李白對這個誠懇又執著的年輕人印象極深，後來甚至把自己的詩稿託付給他整理，魏萬也真的做到了，後來編成《李翰林集》，讓李白一大批詩作流傳到今天。李頎當年在河邊送別的，是一個還沒沒無聞的青年；他大概沒想過，這個青年後來會成為替中國最偉大的詩人守住作品的人。渡口的霜早就化了，那份臨別的叮嚀，卻替一整個時代留住了什麼。`
  },

  // id=219 中唐 劉長卿 〈長沙過賈誼宅〉rating=1
  // 詩眼：隔著九百年，一個被貶的人問另一個被貶的人「你為什麼到這裡來」，其實問的是自己
  // 隱藏連接：劉長卿被誣陷後第二次南下貶謫，途中特地繞去尋訪賈誼舊宅
  219: {
    title: "長沙過賈誼宅",
    author: "劉長卿",
    summary: "被貶官南下的路上，劉長卿特地繞去看一間快要沒了的舊宅，那是九百年前另一個被貶的天才住過的地方，他站在秋草裡問「你為什麼會落到這步田地」，問出口才發現，其實是在問自己。",
    story: `跟你說我朋友劉長卿，被貶官南下的路上，特地繞去長沙一間老房子看了看。那是漢代賈誼住過的舊宅，離他要去赴任的地方不遠，他聽說了，就繞過去。

賈誼是什麼樣的人，劉長卿太清楚了。漢文帝時代，賈誼二十出頭就被破格提拔，議論政事一針見血，連皇帝都佩服，可是滿朝老臣看這個毛頭小子平步青雲，心裡不服，聯手排擠，皇帝拗不過眾議，把他外放去當長沙王太傅，說好聽是太傅，其實就是變相流放。賈誼在長沙待了三年，鬱鬱寡歡，後來雖然被召回，又被派去教年幼的梁懷王讀書，結果梁懷王騎馬摔死，賈誼自責不已，隔年也跟著抑鬱而終，死時才三十三歲。

劉長卿自己的處境，跟賈誼隔著九百年，卻像照鏡子。他年輕時也是意氣風發考中進士，滿心以為能做出一番事業，沒想到仕途一路顛簸，先被誣陷貪贓，貶到嶺南，好不容易熬回來，又再被誣陷一次，這回南下的路，正是要去接受第二次貶謫。他走到長沙，天已經入秋，找到賈誼舊宅的位置，那裡如今只剩下一片荒草，宅子早就沒了人煙。

他一個人在草叢裡找了很久，才找到殘存的地基。夕陽斜照，一片寒林，靜得只剩風聲。他站在那裡，忽然覺得很不服氣，漢文帝在歷史上是出了名的仁厚明君，是史書公認的盛世之主，可就連他，對賈誼這樣的人才，恩澤都還是太薄了，何況是自己遇到的這種昏聵當道的世道。湘江的水從眼前流過，不聲不響，根本不會知道，此刻有一個人正站在江邊，替九百年前那個人難過。

他站了很久，提筆寫下：

寂寂江山搖落處，憐君何事到天涯。

問的是賈誼，為什麼你這麼有才華的人，會落到跑來這種天涯海角的地步。可是這句話問出口，劉長卿自己心裡清楚，其實也是在問自己。

寫完，他把紙收好，繼續往赴任的地方走。賈誼舊宅後來歷代都有人重修，一直保留到今天，長沙人管它叫賈太傅祠，就在湘江邊上。劉長卿那天在秋草裡站了很久很久，後人誰也不知道他到底想通了什麼，只知道從那之後，每一個被貶到偏遠地方的讀書人，路過長沙，都會想去看一眼那間老房子，因為賈誼待過那裡，因為劉長卿也曾經替他掉過眼淚。`
  },

  // id=220 中唐 劉長卿 〈自夏口至鸚洲夕望岳陽寄源中丞〉rating=1
  // 詩眼：途經一整條懷才不遇的地圖，把貶謫路上看到的每個典故都走成了自己的預告
  // 隱藏連接：這首詩寫於劉長卿南下貶謫途中，提到的賈誼長沙舊宅，正是他這趟旅程接下來會抵達、並寫下〈長沙過賈誼宅〉的地方
  220: {
    title: "自夏口至鸚洲夕望岳陽寄源中丞",
    author: "劉長卿",
    summary: "船停靠在殺死過一位年輕才子的荒洲邊，劉長卿望著暮色裡的洞庭湖，寫信給遠方的朋友，信裡提到的那位被貶長沙的漢代才子，幾天後，他自己就會站在那個人的舊宅門前。",
    story: `跟你說我朋友劉長卿，在被貶官南下的路上，途經一座島。那座島叫鸚鵡洲，在夏口（今天的武漢）附近的江面上，他的船暫時停靠在那，黃昏時分，他望著遠方的岳陽方向，提筆給一位姓源的朋友寫信。

鸚鵡洲這個地方，劉長卿不是第一次聽說。東漢末年，有個叫禰衡的年輕人，才氣極高，脾氣也極硬，得罪了當時的權貴黃祖，被殺死在這座洲上，年僅二十六歲。禰衡死前寫過一篇〈鸚鵡賦〉，這座洲後來就以此得名。劉長卿站在船頭，看著這片江水，心裡想的是，才氣這種東西，好像從來就沒真正被亂世善待過。

那天江面出奇地安靜，沒有一絲風浪，也沒有霧氣，能見度很好，反而讓人心裡更空。劉長卿望向遠方，心裡想的全是這一路要去的地方，長沙，還有更遠更遠的嶺南。他自己被誣陷貶官，這是第二回了，越往南走，離長安越遠，越覺得自己像個外人。

天色漸漸暗下來，夕陽斜照，江面上有幾隻鳥低低飛過，往漢口的方向去了。再往遠處看，洞庭湖的秋水浩浩蕩蕩，一直延伸到天邊，跟天色連成一片，分不清哪裡是水、哪裡是天。江邊有一座孤零零的城，背靠著山嶺，寒風裡傳來號角的聲音；江上還有一座孤零零的戍樓，他的船就孤零零地停靠在那，準備過夜。

他想起路上還會經過長沙，那裡有座賈誼的舊宅，漢代那位年輕的政治家，也是因為太有才華、太敢說話，被貶到了長沙，鬱鬱而終。劉長卿還沒到那裡，心裡已經先想好了要去看一眼。他提筆給遠方的源中丞寫信，把這一路的心情都寫進去：

賈誼上書憂漢室，長沙謫去古今憐。

意思是，賈誼當年上書替漢朝的江山操心，最後卻被貶到長沙，這種事，從古到今，人人都替他心疼。寫的是賈誼，其實也是寫給自己這一路的心情，順便，也是先跟遠方的朋友打個招呼，我快到那個地方了。

寫完信，天已經全黑，江上什麼都看不見了，只剩下水聲。劉長卿把信收好，準備託人帶去給源中丞。幾天後，他真的到了長沙，站在賈誼舊宅前，把這趟旅程走到了它命中注定的下一站。鸚鵡洲的江水，後來還是那樣流著，禰衡的名字，跟賈誼的名字，一起，成了往後每一個被貶官的人，路過都會想起的兩個典故。`
  },

  // id=222 中唐 元稹 〈遣悲懷三首之一〉rating=1
  // 詩眼：錢終於夠用的那天，人已經不在了
  // 隱藏連接：無
  222: {
    title: "遣悲懷三首之一",
    author: "元稹",
    summary: "元稹終於熬到俸祿過十萬錢的那一年，妻子韋叢卻已經不在了，那些年她翻箱倒櫃找舊布、拔金釵換酒錢的日子，如今全變成他再也沒辦法報答的遺憾。",
    story: `跟你說我朋友元稹，人到中年、終於熬出頭那一年，發生了一件讓他這輩子都沒辦法原諒自己的事，妻子韋叢死了，才二十七歲，而他手上剛好開始有點錢。

他們是多年前結的婚。元稹那時候二十五歲，還只是個沒什麼官職、口袋空空的窮小子；韋叢卻是名門之後，父親韋夏卿官居太子少保，按理說，嫁給元稹是下嫁。可是韋叢一點都沒嫌棄。家裡沒有好衣服穿，她就翻箱倒櫃找舊布料自己縫；元稹想喝點酒解悶，家裡沒錢，她二話不說，把自己頭上的金釵拔下來，拿去當了換酒錢。平常吃飯，就著野菜配豆葉，將就著吃，也吃得很甘心；家裡沒柴燒，就撿院子裡老槐樹落下的枯葉當柴火添進灶裡。這些事，她從沒抱怨過一句。

元稹後來慢慢熬出頭，官越做越大，日子也越來越寬裕。可是就在他終於能讓妻子過上好日子的節骨眼上，韋叢病倒了，很快就走了。元稹翻開家裡的帳本，看著如今每個月的俸祿已經超過十萬錢，這是他們剛結婚那幾年想都不敢想的數字，可是身邊已經沒有人可以陪他花這些錢了。他能做的，只剩下替她準備祭品，一次又一次地辦法事超度。

他想起韋叢還在世時，最愛開玩笑地說自己是家裡最受寵的小女兒，把自己父親比作東晉那個特別偏心小女兒的謝家，明明含著金湯匙出生，卻自從嫁給他之後，什麼事都不順遂。元稹當時聽了，只當是妻子撒嬌的玩笑話，此刻回想起來，才知道那句玩笑背後，藏著多少她從沒說出口的委屈。

他坐在書桌前，把這些年一件一件想起來，眼淚止不住地掉，最後寫下：

顧我無衣搜藎篋，泥他沽酒拔金釵。野蔬充膳甘長藿，落葉添薪仰古槐。今日俸錢過十萬，與君營奠復營齋。

這幾句話裡沒有一個字華麗，寫的全是最瑣碎的生活細節，找衣服、賣金釵、吃野菜、撿枯葉，可是每一件事，都是當年韋叢默默替他撐過來的證據。

元稹跟韋叢一共只有幾年的婚姻，他寫完這首，後面還接著又寫了兩首，合稱〈遣悲懷三首〉，加上另一組〈離思〉，成了後世公認最沉痛的悼亡詩之一。他這輩子後來又做過更大的官，甚至一度當上宰相，可是每次翻開帳本看見俸祿越來越高的時候，大概都會想起，那個曾經替他拔下金釵去換酒錢的人，再也看不到了。`
  },

  // id=227 中唐 岑參 〈奉和中書舍人賈至早朝大明宮〉rating=1
  // 詩眼：帝國差點亡掉之後，重新排好班、敲響晨鐘的那個清晨，底下全是劫後餘生的慶幸
  // 隱藏連接：賈至原詩之外，王維、杜甫、岑參同時各自寫了唱和詩，四位大唐第一流詩人同框見證了長安光復後的第一場早朝
  227: {
    title: "奉和中書舍人賈至早朝大明宮",
    author: "岑參",
    summary: "安史之亂讓長安兩度淪陷之後，岑參終於又聽見宮門口準時敲響的晨鐘，這場看似普通的早朝應酬詩，背後站著的，其實是四位劫後餘生的大唐頂尖詩人。",
    story: `跟你說我朋友岑參，經歷過長安差點就沒了的那幾年，這天終於又聽見宮門口那口晨鐘準時敲響。

安史之亂爆發那幾年，長安兩度落入叛軍手裡，玄宗倉皇逃往四川，肅宗在靈武倉促即位，整個帝國一度像是隨時要垮掉。岑參那時候人在西北邊塞，聽著長安的消息，提心吊膽了好一陣子。後來局勢慢慢穩住，肅宗收復兩京，把朝廷遷回長安，大明宮重新開始按照舊制舉行早朝，這件事說起來簡單，對經歷過那幾年動盪的人來說，卻是天大的事：帝國真的挺過來了。

這天清晨，天還沒亮透，岑參跟著滿朝文武一起入宮。紫色的宮道上，雄雞剛剛啼叫，曙光帶著寒意；宮牆外傳來黃鶯的叫聲，春天已經快要過去了。金光閃閃的宮門，隨著清晨的鐘聲一扇一扇打開，通向皇城裡的千家萬戶；玉石鋪成的臺階上，儀仗隊排得整整齊齊，像仙人一樣威嚴，身後跟著上千位官員魚貫而入。花叢間，佩劍和玉飾的官員們迎著剛剛落下的星光走過；柳條輕輕拂過旗幟，露水都還沒乾。

這一切，岑參太熟悉了，可是每一次看，還是覺得心裡發熱。這不是普通的排場，這是亂世之後好不容易重新排好的秩序。他身邊站著的，還有另外幾位當代最頂尖的詩人，中書舍人賈至率先寫了一首〈早朝大明宮〉記錄這個場面，王維、杜甫也都跟著寫了奉和的詩，一群曾經各自在戰亂裡顛沛流離的人，這天全都站在同一座宮殿裡，看著同一輪晨光。

岑參讀了賈至的原詩，覺得寫得極好，好到自己都覺得難以匹配。他把這份心情寫進自己的和詩最後兩句：

獨有鳳凰池上客，陽春一曲和皆難。

鳳凰池，是中書省的別稱，這裡指賈至的官職所在；陽春，是一首古代極難唱和的高雅曲子。岑參的意思是，賈至這首詩寫得太好了，像那首曲高和寡的〈陽春〉，誰都很難真正跟得上。

這首詩表面上是官場應酬的客套話，底下藏著的，其實是劫後餘生的慶幸。那年岑參已經四十歲出頭，經歷過安史之亂前後的大起大落，他知道能站在這座重新敲響晨鐘的宮殿裡，是件多不容易的事。多年以後，人們讀這幾首同題唱和的詩，會發現那個清晨，長安城裡最頂尖的幾位詩人，真的同時站在同一片晨光下，誰也不知道彼此正在心裡想著同一句話：這個朝廷，終於又活過來了。`
  },

  // id=229 中唐 韓翃 〈同題仙游觀〉rating=1
  // 詩眼：不必去別處尋仙，眼前這座清幽的道觀，已經是人間的丹丘
  // 隱藏連接：多年後韓翃因一首寒食詩被皇帝親自點名提拔，徹底翻轉了這段寫詩時還默默無聞的日子
  229: {
    title: "同題仙游觀",
    author: "韓翃",
    summary: "那些年韓翃還默默無聞，常常一個人跑去城外的道觀靜一靜，他不知道，自己後來會因為另一首詩，被皇帝親筆點名，一夕之間從谷底翻身。",
    story: `跟你說我朋友韓翃，那些年還沒紅的時候，最常去的地方是長安城外一座叫仙遊觀的道觀。

韓翃後來會出名，出名的方式還挺戲劇性，多年後他寫了一首寒食節的詩，「春城無處不飛花，寒食東風御柳斜」，寫得太好，皇帝親自過目，一眼就記住了，後來朝廷要選人補一個官缺，剛好又有另一個人也叫韓翃，官員拿不定主意去請示，皇帝親筆批了一句，就寫「春城無處不飛花」那個韓翃，直接把他從默默無聞的位置提拔上去。可是這首詩寫的那個下午，還是他人生裡平平淡淡的一段，他只是個常常一個人往城外跑、喜歡找地方靜一靜的讀書人。

仙遊觀是唐高宗時候為一位得道的潘姓道士興建的，規模不算頂大，但因為蓋在終南山一帶，環境清幽，一直是文人道士喜歡去的地方。韓翃那天去，剛好前一夜下過雨，天剛放晴。他遠遠先看到道觀的樓閣，五重疊起的樣子，像傳說裡神仙住的城池。四周景物帶著雨後特有的清冷，空氣裡還留著濕氣。

他順著山路往上走，回頭望向遠方，山色連綿一路延伸到暮色裡的長安城外，那些他熟悉的樹影，慢慢被夜色吞掉；附近村落裡，搗衣的砧聲一聲聲傳來，提醒他秋天已經到了長安城。走進道觀，院子裡的老松樹枝影稀疏，投在空蕩蕩的祭壇上，安靜得出奇；牆角的細草散發著淡淡香氣，一個小小的洞穴幽靜得像是與世隔絕。

韓翃那些年，日子過得不算得意，考中進士以後很久沒能謀到一官半職，眼看著同輩一個個都有了出路，自己還在到處遊蕩。可是站在這座清幽的道觀裡，他忽然覺得，人不一定非要去哪裡尋仙問道才叫解脫。這裡，此刻，就已經夠了。

他想著想著，寫下：

何用別尋方外去，人間亦自有丹丘。

丹丘，是傳說中神仙居住的地方。韓翃的意思是，何必捨近求遠，跑去別處尋找什麼神仙境界，眼前這座道觀，不就已經是人間的丹丘了嗎。

寫這首詩的時候，韓翃還不知道自己後來會因為另一首詩，被皇帝親自點名提拔，一夕之間從默默無聞變成人人稱羨的對象。那些年他一個人往城外跑、在道觀裡找安靜的日子，沒人記得，可是他心裡早就明白一件事，不管後來有沒有飛黃騰達，眼前能讓自己靜下來的地方，就已經是最好的地方。`
  },

  // id=248 晚唐 薛逢 〈宮詞〉rating=1
  // 詩眼：精心梳妝了一整個早上，最後只等到一個打掃床鋪的宮女走過
  // 隱藏連接：薛逢自己仕途屢遭排擠、始終等不到重用，宮女等待臨幸落空的畫面，是他自身處境的寫照
  248: {
    title: "宮詞",
    author: "薛逢",
    summary: "一位宮女梳妝了一整個早上，站上高樓遠遠張望，她等到的，不是皇帝的身影，只是一個打掃床鋪的宮女走過，薛逢把自己等不到的賞識，寫進了這個沒有名字的女人身上。",
    story: `跟你說我朋友薛逢，寫過一首宮女梳妝的詩，梳妝的細節寫得極細，細到讓人幾乎忘記，這首詩其實在講一件很殘忍的事。

薛逢自己的仕途，一路走得並不順。他年輕時考中進士，騎馬遊街那天何等風光，可是後來因為性子太直、嘴巴太硬，得罪了好幾位當朝的宰相，官越做越小，一路被排擠、被外放，眼看著同輩一個個高升，自己卻始終被晾在一邊，等不到真正被重用的那一天。他寫這首〈宮詞〉的時候，心裡想的，未必只是深宮裡的女人。

詩裡那位宮女，住在後宮眾多樓閣裡的一座，每天一大早就開始梳妝，梳完了，還要站到望仙樓上，遠遠望著，盼皇帝哪天會經過、會想起她。門上鎖著金屬獸頭形狀的鎖環，環環相扣，摸起來冰冷；銅鑄的水漏滴滴答答，計算著時辰，一整個白天，漏刻的聲音都顯得格外漫長。

她梳好雲髻一樣的髮型，還是忍不住又對著鏡子照了又照，總覺得哪裡可以再打理得更好一點；身上的絲綢衣裳換了又換，還要再添點香氣，她已經做到自己能做的一切，唯一做不到的，是讓皇帝真的看她一眼。

薛逢寫到這裡，筆鋒忽然一轉，鏡頭從這位宮女的房間，拉遠到正殿。他寫下：

遙窺正殿簾開處，袍褲宮人掃御床。

簾子被風掀開一角，她遠遠地往那邊望過去，想看看是不是皇帝駕到了。結果看到的，只是一個穿著粗布衣褲的宮女，正在打掃皇帝的床鋪。沒有皇帝的身影，只有日復一日的灑掃，連個排場都算不上。

這首詩最狠的地方，就是它什麼都沒明說。薛逢沒有寫她失望，沒有寫她流淚，只是讓讀的人自己看懂，她準備了一整個早上的希望，最後換來的，不過是別人打掃床鋪的背影。

薛逢自己何嘗不是這樣。他也曾經像那位宮女一樣，把自己收拾得漂漂亮亮，準備好一身的才學，等著朝廷哪天想起自己、重用自己，結果換來的，常常也只是別人平步青雲、自己繼續留在原地的落空。宮怨詩寫的是宮女，士人寫宮怨詩，寫的常常是自己等不到的那份賞識。薛逢晚年還是沒能得到真正的重用，鬱鬱而終，可是這首詩留下來了，每一個等待過、落空過的人讀到最後兩句，都會懂那種，精心準備了一切，卻只等到一個打掃床鋪的宮女走過的心情。`
  },

  // id=268 盛唐 祖詠 〈終南望餘雪〉rating=1
  // 詩眼：寫完自己想寫的就放下筆，哪怕會因此被扣分
  // 隱藏連接：祖詠與王維是至交好友，兩人詩作多有往來唱和
  268: {
    title: "終南望餘雪",
    author: "祖詠",
    summary: "考試題目要求寫滿十二句，祖詠只寫了二十個字就交卷，監考官問他怎麼回事，他說「意思已經寫完了」，這句話後來變成唐代科舉史上最著名的一次不從眾。",
    story: `跟你說我朋友祖詠，考試那天做了一件很多人想都不敢想的事，寫到覺得夠了，就把筆放下，不管卷子上還空著一大半。

那年是唐朝的科舉考試，祖詠參加的是省試，題目是〈終南望餘雪〉，要求寫一首五言六韻，也就是十二句的排律，這是官方訂下的格式，考生照規矩寫滿十二句，是最基本的要求。祖詠坐在考場裡，看著窗外終南山的方向，提筆寫了四句、二十個字，就停下來了。

監考的官員巡場時注意到他，走過去看，發現他這麼快就放下了筆，以為他寫不下去，便問他怎麼回事。祖詠說，自己想表達的意思已經寫完了，不需要再湊。這句話說出來，等於直接跟考試制度唱反調，按規矩，寫不滿十二句，是要扣分的，甚至可能直接影響能不能考中。可是祖詠不肯為了湊字數，硬塞幾句廢話進去毀掉一首已經寫完的詩。

他提筆寫下：

終南陰嶺秀，積雪浮雲端。林表明霽色，城中增暮寒。

短短二十個字，終南山背陰那面山嶺的秀麗、山頂積雪浮在雲端的樣子、樹林邊緣雨雪初晴的光亮，連長安城裡人此刻感受到的那股寒意，全都寫進去了，確實不需要再多說什麼。

祖詠這個人，朋友都知道他是這樣的性子，不喜歡把事情做過頭，寧可少寫兩句，也不願意寫得拖泥帶水，這股脾氣，考場裡碰到了，也照樣不打算收斂。他跟王維是好朋友，兩人常有詩作往來，王維寫過詩送給他，稱讚他的才學和性情，兩人平時談詩論文，最看重的就是一個「真」字，寧可話說得少，也不說一句多餘的場面話。這樣的朋友，大概也最能理解祖詠在考場裡放下筆的那一刻，心裡在想什麼，不是狂妄，是他清楚知道，一首詩什麼時候該停，硬要湊字，只會毀掉一首本來已經完整的作品。

那年祖詠真的考中了進士。可是他後來的仕途並不順遂，始終沒有做到什麼大官，晚年乾脆辭官，回到汝墳一帶，種田釣魚，過起隱居的日子，再也沒有回到那個講究規矩、講究排場的官場世界。他這輩子好像一直在做同一件事，覺得夠了，就停下來，不管外面的規矩要求你再湊幾句、再多做幾年。終南山上的殘雪，後來一年年照樣融了又下、下了又融，可是那個在考場上只寫二十個字就放下筆的年輕人，倒是把自己活成了那首詩最好的注解。`
  },

  // id=390 晚唐 韓偓 〈已涼〉rating=1
  // 詩眼：整個房間都準備好了，就是沒有人，寫的不是床，是等待本身
  // 隱藏連接：韓偓晚年成為唐朝末代忠臣，拒絕依附篡位的朱溫，被貶謫流放至福建，終生未能北返
  390: {
    title: "已涼",
    author: "韓偓",
    summary: "這首詩不寫一個人，只寫一間收拾得妥妥貼貼的閨房，多年後，寫下這份精緻閒適的韓偓，會親眼看著自己效忠一輩子的王朝，像這間房間的秋涼一樣，一天天冷到徹底崩塌。",
    story: `跟你說我朋友韓偓，年輕時寫過一首詩，整首詩裡連一個人影都沒有出現，卻讓人讀完覺得，好像有誰，正要走進畫面裡。

那是他年輕時候的作品，收在他後來自己編的詩集《香奩集》裡，寫的是一間精緻的閨房。他不寫美人，只寫房間裡的擺設，碧綠色的欄杆外面，垂著一層繡花的簾子；屏風是鮮豔的猩紅色，上面畫著折枝花卉的圖案。地上鋪著八尺長的龍鬚草蓆，上面又疊著一方錦緞坐墊，一切都收拾得妥妥貼貼。他提筆寫下：

碧闌干外繡簾垂，猩色屏風畫折枝。八尺龍鬚方錦褥，已涼天氣未寒時。

時節剛好落在秋天的邊緣，天氣已經轉涼，但還沒真正冷下來。

韓偓寫這首詩的時候還很年輕，那些年他常常出入這樣講究精緻的場合，見多了這類閨房陳設，才寫得出這種只描摹物件、不寫一個人卻處處讓人感覺到人的存在的筆法。後來的人讀這首詩，常常好奇，房間主人是誰？在等誰？為什麼把一切都準備得這麼周到？韓偓什麼都沒交代，他就是要讓讀的人自己去想像那個還沒出現的人。

如果只知道這首詩，大概會覺得韓偓是那種一輩子寫風花雪月的才子。可是這個人後來的人生，走向完全是另一個方向。韓偓後來成了唐朝最後一任皇帝唐昭宗身邊的重臣，深得信任。那時候大唐已經是風雨飄搖，權臣朱溫一步步把持朝政，最後要篡位自立。朱溫幾次想拉攏韓偓，許以高官厚祿，韓偓都不肯依附，堅持效忠已經名存實亡的唐朝。朱溫惱羞成怒，把他一貶再貶，最後韓偓乾脆帶著家人一路南逃，輾轉流落到福建，再也沒能回到北方。唐朝滅亡那年，他人已經在異鄉，眼睜睜看著自己效忠一輩子的王朝走到終點，自己卻連為它送終的資格都沒有。

那個秋涼未寒的節點，寫的本來只是天氣，可是放在他後來的人生裡回頭看，竟然像一句提前寫好的預言，那個曾經精緻講究、什麼都準備妥當的世界，終究還是一天一天冷下去，直到徹底崩塌。

韓偓最後死在福建南安，終年沒能回到故鄉。他年輕時寫下的那間閨房，簾子還垂著，屏風還豔麗著，那個他準備好卻始終沒讓讀者看見的人，或許從一開始，就是那個他自己也不知道命運會怎麼收場的、年輕的韓偓。`
  },

  // id=445 北宋 秦觀 〈江城子-西城楊柳弄春柔〉rating=1
  // 詩眼：就算整條春江都變成眼淚，也裝不下他心裡的遺憾
  // 隱藏連接：秦觀後來因新舊黨爭被貶至極南雷州，北歸途中病逝於藤州，終生未能回鄉，年輕時的這份遺憾後來被更大的不幸遠遠超過
  445: {
    title: "江城子-西城楊柳弄春柔",
    author: "秦觀",
    summary: "站在城樓上看柳絮紛飛，秦觀想起自己曾經把歸家的船拴在橋邊柳樹上的那個春天，他當時以為，那是人生最大的遺憾了，後來才知道，連好好回一次家，都會成為他終究沒能完成的心願。",
    story: `跟你說我朋友秦觀，有一年春天，站在城樓上，看著城牆邊的柳樹被風吹得輕輕擺動，忽然想起很久以前，自己曾經在這座橋邊，把要回家的船拴在一株柳樹上。

那是他年輕時候的事。相傳當年秦觀在家鄉高郵一帶，曾經有過一段刻骨銘心的感情，對象是誰，後人已經考據不清，只留下這闋詞裡幾句線索，一座朱紅色的橋，一片碧綠的原野，還有那年春天他跟她一起度過的、後來再也回不去的時光。

那時候的秦觀還很年輕，前途看起來一片光明，心裡也還相信，好日子會一直這樣過下去。他記得那年河邊柳絲正嫩，兩人一起在橋邊待了很久，他甚至還記得自己曾經把要遠行的船，用柳條繫在橋墩上，不急著走。可是後來，不知道為了什麼緣故，兩人終究還是分開了。橋還在，河水還在流，那個人卻不知道去了哪裡。

秦觀後來又經歷了好幾次科舉落第，直到三十六歲才終於考中進士，認識了蘇軾，成為蘇門四學士之一，仕途看起來總算要上軌道。可是每次春天柳絮紛飛的季節，他總會不由自主地想起年輕時候那段感情。這一年，他又一次登上城樓，看見漫天飛絮和滿地落花，眼前的景色跟記憶裡那年春天，幾乎一模一樣。

他站在樓上想，美好的年華從來不會因為誰還年輕、還捨不得，就特意停下來等一等。那些他以為理所當然、以為可以慢慢享受的時光，早就一去不回了。這份遺憾，悠悠盪盪，不知道什麼時候才能真正放下。

他提筆寫下這闋詞，寫到最後，情緒再也壓不住，寫下：

便做春江都是淚，流不盡，許多愁。

意思是，就算把整條春天的江水都變成眼淚，也裝不下他心裡這麼多的愁緒。這句話後來成了秦觀詞裡最被人記住的一句，寫盡了那種遺憾大到連江水都容不下的感覺。

秦觀當時大概沒想過，這份因為一段感情而生的遺憾，後來會被他自己更大的不幸遠遠超過。多年後，政局翻覆，他因為跟蘇軾同一陣營，被一路貶到郴州、橫州，最後貶到極南邊的雷州，離家鄉幾千里。等到朝廷終於下令赦免，他啟程北返，卻死在半路上的藤州，再也沒能真正回家。年輕時在橋邊拴船的那個下午，他以為春江裝不下的愁，已經是人生最大的遺憾了，他不知道，後來連回家這件小事，都成了他終究沒能完成的心願。`
  },

};

